#include <stdlib.h>
#include <pthread.h>

#define MAX_MAC_PDUS 1024

typedef struct {
    // Define L2Header structure here
} L2Header;

typedef struct {
    L2Header header;
    char *payload;
    size_t payload_size;
} MAC_PDU;

typedef struct {
    MAC_PDU *pdus[MAX_MAC_PDUS];
    int count;
    pthread_mutex_t lock;
} MAC_PDU_Array;

void initialize_mac_pdu_array(MAC_PDU_Array *array) {
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
}

int add_mac_pdu(MAC_PDU_Array *array, L2Header header, const char *payload, size_t payload_size) {
    pthread_mutex_lock(&array->lock);
    if (array->count >= MAX_MAC_PDUS) {
        pthread_mutex_unlock(&array->lock);
        return -1; // Array is full
    }
    MAC_PDU *new_pdu = malloc(sizeof(MAC_PDU));
    if (!new_pdu) {
        pthread_mutex_unlock(&array->lock);
        return -2; // Memory allocation failed
    }
    new_pdu->header = header;
    new_pdu->payload = malloc(payload_size);
    if (!new_pdu->payload) {
        free(new_pdu);
        pthread_mutex_unlock(&array->lock);
        return -3; // Payload memory allocation failed
    }
    memcpy(new_pdu->payload, payload, payload_size);
    new_pdu->payload_size = payload_size;
    array->pdus[array->count++] = new_pdu;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

void free_mac_pdu_array(MAC_PDU_Array *array) {
    pthread_mutex_lock(&array->lock);
    for (int i = 0; i < array->count; i++) {
        free(array->pdus[i]->payload);
        free(array->pdus[i]);
    }
    array->count = 0;
    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
}
