#define MAX_RECORDS 1000

typedef struct {
    int value;
    int* key_ptr;
} Record;

Record** records = NULL;
int record_count = 0;
int max_records = 0;

void init_record_collection(int N) {
    if (N > MAX_RECORDS) {
        fprintf(stderr, "Error: Maximum number of records exceeded.\n");
        return;
    }
    records = (Record**)malloc(N * sizeof(Record*));
    if (!records) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    max_records = N;
}

void add_record(int key_index) {
    if (record_count >= max_records) {
        int new_capacity = max_records + (max_records / 10);
        Record** new_records = (Record**)realloc(records, new_capacity * sizeof(Record*));
        if (!new_records) {
            fprintf(stderr, "Memory reallocation failed.\n");
            exit(EXIT_FAILURE);
        }
        records = new_records;
        max_records = new_capacity;
    }
    records[record_count] = (Record*)malloc(sizeof(Record));
    if (!records[record_count]) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    records[record_count]->value = rand() % 100; // Random value between 0 and 99
    records[record_count]->key_ptr = &keys[key_index];
    record_count++;
}

void cleanup_record_collection() {
    for (int i = 0; i < record_count; i++) {
        free(records[i]);
    }
    free(records);
    records = NULL;
    record_count = 0;
    max_records = 0;
}
