#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <resolv.h>

#define MAX_HOSTNAME_LEN 256
#define MAX_IP_LEN INET_ADDRSTRLEN
#define MAX_FIELDS 10

void resolve_dns(const char *hostname, char *ip) {
    struct hostent *host;
    if ((host = gethostbyname(hostname)) != NULL) {
        strcpy(ip, inet_ntoa(*(struct in_addr *)host->h_addr_list[0]));
    } else {
        perror("gethostbyname");
    }
}

double calculate_average(int fields[], int count) {
    double sum = 0;
    for (int i = count - 2; i < count; i++) {
        sum += fields[i];
    }
    return sum / 2;
}

void process_csv(const char *filename, const char *output_filename) {
    FILE *input_file = fopen(filename, "r");
    if (!input_file) {
        perror("fopen");
        return;
    }

    FILE *output_file = fopen(output_filename, "w");
    if (!output_file) {
        perror("fopen");
        fclose(input_file);
        return;
    }

    char line[1024];
    while (fgets(line, sizeof(line), input_file)) {
        char *token = strtok(line, ",");
        int fields[MAX_FIELDS] = {0};
        int field_count = 0;

        while (token != NULL && field_count < MAX_FIELDS) {
            if (isdigit(token[0])) {
                fields[field_count++] = atoi(token);
            }
            token = strtok(NULL, ",");
        }

        char ip[MAX_IP_LEN];
        resolve_dns(line, ip);

        double average = calculate_average(fields, field_count);
        fprintf(output_file, "%s,%f\n", line, average);
    }

    fclose(input_file);
    fclose(output_file);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <input.csv> <output.csv>\n", argv[0]);
        return 1;
    }

    process_csv(argv[1], argv[2]);

    return 0;
}
