#define MAX_INTS 1000

typedef struct {
    int *data;
    size_t count;
    size_t capacity;
} IntBuffer;

void init_buffer(IntBuffer *buf) {
    buf->data = (int *)malloc(MAX_INTS * sizeof(int));
    if (!buf->data) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    buf->count = 0;
    buf->capacity = MAX_INTS;
}

void free_buffer(IntBuffer *buf) {
    free(buf->data);
    buf->data = NULL;
    buf->count = 0;
    buf->capacity = 0;
}

bool add_to_buffer(IntBuffer *buf, int value) {
    if (buf->count >= buf->capacity) {
        fprintf(stderr, "Buffer overflow\n");
        return false;
    }
    buf->data[buf->count++] = value;
    return true;
}

int find_max(const IntBuffer *buf) {
    if (buf->count == 0) {
        fprintf(stderr, "Empty buffer\n");
        exit(EXIT_FAILURE);
    }
    int max = buf->data[0];
    for (size_t i = 1; i < buf->count; ++i) {
        if (buf->data[i] > max) {
            max = buf->data[i];
        }
    }
    return max;
}

int find_min(const IntBuffer *buf) {
    if (buf->count == 0) {
        fprintf(stderr, "Empty buffer\n");
        exit(EXIT_FAILURE);
    }
    int min = buf->data[0];
    for (size_t i = 1; i < buf->count; ++i) {
        if (buf->data[i] < min) {
            min = buf->data[i];
        }
    }
    return min;
}

double calculate_average(const IntBuffer *buf) {
    if (buf->count == 0) {
        fprintf(stderr, "Empty buffer\n");
        exit(EXIT_FAILURE);
    }
    double sum = 0;
    for (size_t i = 0; i < buf->count; ++i) {
        sum += buf->data[i];
    }
    return sum / buf->count;
}

int main() {
    IntBuffer buffer;
    init_buffer(&buffer);

    // Simulate receiving integers from a network stream
    for (int i = 1; i <= 10; ++i) {
        if (!add_to_buffer(&buffer, i)) {
            break;
        }
    }

    printf("Max: %d\n", find_max(&buffer));
    printf("Min: %d\n", find_min(&buffer));
    printf("Average: %.2f\n", calculate_average(&buffer));

    free_buffer(&buffer);
    return 0;
}
