#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef enum {
    DEBUG,
    INFO,
    WARNING,
    ERROR,
    CRITICAL
} LogLevel;

typedef struct LoggerConfig {
    LogLevel level;
    char *log_format;
    FILE *output_file;
    int rotate_size;
    int compress_logs;
    pthread_mutex_t lock;
} LoggerConfig;

LoggerConfig* create_logger(LogLevel level, const char *log_format, const char *filename, int rotate_size, int compress_logs) {
    LoggerConfig *config = (LoggerConfig*)malloc(sizeof(LoggerConfig));
    config->level = level;
    config->log_format = strdup(log_format);
    config->output_file = fopen(filename, "a");
    config->rotate_size = rotate_size;
    config->compress_logs = compress_logs;
    pthread_mutex_init(&config->lock, NULL);
    return config;
}

void log_message(LoggerConfig *config, LogLevel level, const char *message) {
    if (level >= config->level) {
        pthread_mutex_lock(&config->lock);
        fprintf(config->output_file, "%s\n", message);
        fflush(config->output_file);
        pthread_mutex_unlock(&config->lock);
    }
}

void destroy_logger(LoggerConfig *config) {
    free(config->log_format);
    fclose(config->output_file);
    pthread_mutex_destroy(&config->lock);
    free(config);
}
