typedef struct {
    EVP_CIPHER_CTX *ctx;
    const EVP_CIPHER *cipher;
} CipherObject;

CipherObject* initialize_cipher(const char *config_file, const char *algorithm) {
    CipherObject *cipher_obj = (CipherObject*)malloc(sizeof(CipherObject));
    if (!cipher_obj) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    json_object *config_json = json_read_file(config_file);
    if (!config_json) {
        fprintf(stderr, "Failed to read JSON configuration file\n");
        free(cipher_obj);
        return NULL;
    }

    const char *cipher_name = json_object_get_string(json_object_object_get_ex(config_json, "cipher", NULL));
    if (strcmp(cipher_name, algorithm)) {
        fprintf(stderr, "Cipher mismatch in configuration\n");
        json_object_put(config_json);
        free(cipher_obj);
        return NULL;
    }

    cipher_obj->cipher = EVP_CIPHER_fetch(NULL, cipher_name, NULL);
    if (!cipher_obj->cipher) {
        fprintf(stderr, "Failed to fetch cipher algorithm\n");
        json_object_put(config_json);
        free(cipher_obj);
        return NULL;
    }

    cipher_obj->ctx = EVP_CIPHER_CTX_new();
    if (!cipher_obj->ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        EVP_CIPHER_free(cipher_obj->cipher);
        json_object_put(config_json);
        free(cipher_obj);
        return NULL;
    }

    // Initialize the cipher context with default parameters
    if (EVP_EncryptInit_ex(cipher_obj->ctx, cipher_obj->cipher, NULL, NULL, NULL) != 1) {
        fprintf(stderr, "Failed to initialize cipher\n");
        EVP_CIPHER_CTX_free(cipher_obj->ctx);
        EVP_CIPHER_free(cipher_obj->cipher);
        json_object_put(config_json);
        free(cipher_obj);
        return NULL;
    }

    // Log initialization success
    printf("Cipher initialized successfully with algorithm: %s\n", cipher_name);

    json_object_put(config_json);
    return cipher_obj;
}

void cleanup_cipher(CipherObject *cipher_obj) {
    if (cipher_obj->ctx) {
        EVP_CIPHER_CTX_free(cipher_obj->ctx);
    }
    if (cipher_obj->cipher) {
        EVP_CIPHER_free(cipher_obj->cipher);
    }
    free(cipher_obj);
}
