#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    sem_t *sems;
    int num_sems;
    pthread_mutex_t lock;
} SemaphoreManager;

SemaphoreManager* create_semaphore_manager(int num_sems) {
    SemaphoreManager *manager = (SemaphoreManager*)malloc(sizeof(SemaphoreManager));
    if (!manager) return NULL;

    manager->num_sems = num_sems;
    manager->sems = (sem_t*)calloc(num_sems, sizeof(sem_t));
    if (!manager->sems) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);

    for (int i = 0; i < num_sems; i++) {
        sem_init(&manager->sems[i], 0, 1); // Binary semaphore
    }

    return manager;
}

void destroy_semaphore_manager(SemaphoreManager *manager) {
    if (!manager) return;

    for (int i = 0; i < manager->num_sems; i++) {
        sem_destroy(&manager->sems[i]);
    }

    free(manager->sems);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int join_semaphore(SemaphoreManager *manager, int sem_id) {
    if (!manager || sem_id < 0 || sem_id >= manager->num_sems) return -1;

    pthread_mutex_lock(&manager->lock);
    int ret = sem_wait(&manager->sems[sem_id]);
    pthread_mutex_unlock(&manager->lock);

    return ret;
}

int leave_semaphore(SemaphoreManager *manager, int sem_id) {
    if (!manager || sem_id < 0 || sem_id >= manager->num_sems) return -1;

    pthread_mutex_lock(&manager->lock);
    int ret = sem_post(&manager->sems[sem_id]);
    pthread_mutex_unlock(&manager->lock);

    return ret;
}

int get_semaphore_state(SemaphoreManager *manager, int sem_id) {
    if (!manager || sem_id < 0 || sem_id >= manager->num_sems) return -1;

    int val;
    pthread_mutex_lock(&manager->lock);
    sem_getvalue(&manager->sems[sem_id], &val);
    pthread_mutex_unlock(&manager->lock);

    return val;
}

int main() {
    SemaphoreManager *manager = create_semaphore_manager(5);
    if (!manager) {
        fprintf(stderr, "Failed to create semaphore manager\n");
        return 1;
    }

    // Example usage
