    fn new(config: Config) -> Self {
        ServiceClient {
            client: Client::new(),
            config,
            cache: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    async fn fetch_and_optimize(&self, request: &str) -> Result<OptimizedCode, reqwest::Error> {
        if let Some(code) = self.cache.lock().unwrap().get(request) {
            return Ok(code.clone());
        }

        let response = self.client.get(&self.config.endpoint).send().await?;
        let optimized_code = self.optimize_response(response.text().await?);

        self.cache.lock().unwrap().insert(request.to_string(), optimized_code.clone());

        Ok(optimized_code)
    }

    fn optimize_response(&self, response: String) -> OptimizedCode {
        // Implement the logic to optimize the response
        OptimizedCode {}
    }
