#include <vector>
#include <memory>
#include <string>

void insertUniqueString(std::vector<std::shared_ptr<std::string>>& vec, const std::string& searchStr, const std::string& insertStr) {
    for (auto it = vec.begin(); it != vec.end(); ++it) {
        if (*(*it) == searchStr) {
            // Check if the next element is not already the insert string
            if (std::next(it) == vec.end() || *(*std::next(it)) != insertStr) {
                vec.insert(std::next(it), std::make_shared<std::string>(insertStr));
                return;
            }
        }
    }
    // If search string not found, append the insert string
    vec.push_back(std::make_shared<std::string>(insertStr));
}
