using System;
using System.Collections.Generic;
using System.Data.SqlClient;
using System.Threading.Tasks;

public class ConnectionPoolManager
{
    private readonly string _connectionString;
    private readonly int _maxConcurrentConnections;
    private readonly TimeSpan _timeout;

    public ConnectionPoolManager(string connectionString, int maxConcurrentConnections, TimeSpan timeout)
    {
        _connectionString = connectionString;
        _maxConcurrentConnections = maxConcurrentConnections;
        _timeout = timeout;
    }

    public async Task<List<Task<SqlDataReader>>> ExecuteOperationsAsync(List<(string CommandText, List<SqlParameter> Parameters)> operations)
    {
        var tasks = new List<Task<SqlDataReader>>();
        using (var connectionPool = new ConnectionPool(_connectionString, _maxConcurrentConnections))
        {
            foreach (var operation in operations)
            {
                tasks.Add(connectionPool.ExecuteAsync(operation.CommandText, operation.Parameters));
            }
        }

        return tasks;
    }
}

public class ConnectionPool : IDisposable
{
    private readonly string _connectionString;
    private readonly int _maxConcurrentConnections;
    private readonly Queue<SqlConnection> _availableConnections = new Queue<SqlConnection>();
    private readonly SemaphoreSlim _semaphore;

    public ConnectionPool(string connectionString, int maxConcurrentConnections)
    {
        _connectionString = connectionString;
        _maxConcurrentConnections = maxConcurrentConnections;
        _semaphore = new SemaphoreSlim(maxConcurrentConnections);
    }

    public async Task<SqlDataReader> ExecuteAsync(string commandText, List<SqlParameter> parameters)
    {
        await _semaphore.WaitAsync();
        var connection = await GetConnectionAsync();

        try
        {
            using (var command = new SqlCommand(commandText, connection))
            {
                command.CommandTimeout = (int)_timeout.TotalSeconds;
                foreach (var parameter in parameters)
                {
                    command.Parameters.Add(parameter);
                }

                return await command.ExecuteReaderAsync();
            }
        }
        finally
        {
            _availableConnections.Enqueue(connection);
            _semaphore.Release();
        }
    }

    private async Task<SqlConnection> GetConnectionAsync()
    {
        if (_availableConnections.Count > 0)
        {
            return _availableConnections.Dequeue();
        }

        var connection = new SqlConnection(_connectionString);
        await connection.OpenAsync();
        return connection;
    }

    public void Dispose()
    {
        foreach (var connection in _availableConnections)
        {
            connection.Dispose();
        }
        _semaphore.Dispose();
    }
}
