    private readonly string _jsonPath;
    private readonly string _yamlPath;
    private readonly string _xmlPath;

    public GameConfigLoader(string jsonPath, string yamlPath = null, string xmlPath = null)
    {
        _jsonPath = jsonPath;
        _yamlPath = yamlPath;
        _xmlPath = xmlPath;
    }

    public GameConfig LoadConfig()
    {
        var config = new GameConfig();

        try
        {
            if (File.Exists(_jsonPath))
            {
                var jsonContent = File.ReadAllText(_jsonPath);
                var jsonObject = JObject.Parse(jsonContent);
                ApplyJsonSettings(jsonObject, config);
            }
        }
        catch (Exception ex)
        {
            LogError($"Failed to load JSON configuration: {ex.Message}");
        }

        if (!string.IsNullOrEmpty(_yamlPath) && File.Exists(_yamlPath))
        {
            var yamlContent = File.ReadAllText(_yamlPath);
            var deserializer = new Deserializer();
            var yamlObject = deserializer.Deserialize<YamlConfig>(yamlContent);
            ApplyYamlSettings(yamlObject, config);
        }

        if (!string.IsNullOrEmpty(_xmlPath) && File.Exists(_xmlPath))
        {
            var xmlDocument = new XmlDocument();
            xmlDocument.Load(_xmlPath);
            var xmlConfig = DeserializeXml(xmlDocument);
            ApplyXmlSettings(xmlConfig, config);
        }

        return config;
    }

    private void ApplyJsonSettings(JObject jsonObject, GameConfig config)
    {
        if (jsonObject.ContainsKey("Resolution"))
        {
            config.Resolution = jsonObject["Resolution"].ToObject<string>();
        }
        // Add other JSON settings here
    }

    private void ApplyYamlSettings(YamlConfig yamlObject, GameConfig config)
    {
        if (!string.IsNullOrEmpty(yamlObject.Resolution))
        {
            config.Resolution = yamlObject.Resolution;
        }
        // Add other YAML settings here
    }

    private void ApplyXmlSettings(XmlConfig xmlConfig, GameConfig config)
    {
        if (!string.IsNullOrEmpty(xmlConfig.Resolution))
        {
            config.Resolution = xmlConfig.Resolution;
        }
        // Add other XML settings here
    }

    private XmlConfig DeserializeXml(XmlDocument xmlDoc)
    {
        var serializer = new XmlSerializer(typeof(XmlConfig));
        using (var reader = new StringReader(xmlDoc.OuterXml))
        {
            return (XmlConfig)serializer.Deserialize(reader);
        }
    }

    private void LogError(string message)
    {
        Console.WriteLine($"ERROR: {message}");
    }
