from flask import Flask, request, jsonify
import requests

app = Flask(__name__)

# Mock database for demonstration purposes
database = {
    '1': {'name': 'Resource 1', 'data': 'Initial Data'},
    '2': {'name': 'Resource 2', 'data': 'Initial Data'}
}

def update_resource(resource_id, updated_data):
    if resource_id in database:
        # Simulate third-party service call for data validation and transformation
        try:
            response = requests.post('https://thirdpartyapi.com/validate', json=updated_data)
            response.raise_for_status()
            transformed_data = response.json()
        except requests.RequestException as e:
            return jsonify({'error': 'Failed to validate data'}), 502

        # Update resource in database
        database[resource_id].update(transformed_data)
        return jsonify(database[resource_id]), 200
    else:
        return jsonify({'error': 'Resource not found'}), 404

def delete_resource(resource_id):
    if resource_id in database:
        # Simulate third-party service call for data transformation
        try:
            response = requests.post('https://thirdpartyapi.com/transform', json={'resource_id': resource_id})
            response.raise_for_status()
            transformed_data = response.json()
        except requests.RequestException as e:
            return jsonify({'error': 'Failed to transform data'}), 502

        # Create new resource with default values
        new_resource = {'name': f'New Resource {resource_id}', **transformed_data}
        database[resource_id] = new_resource
        return jsonify(new_resource), 201
    else:
        return jsonify({'error': 'Resource not found'}), 404

@app.route('/update/<string:resource_id>', methods=['PUT'])
def handle_update(resource_id):
    updated_data = request.get_json()
    return update_resource(resource_id, updated_data)

@app.route('/delete/<string:resource_id>', methods=['DELETE'])
def handle_delete(resource_id):
    return delete_resource(resource_id)

if __name__ == '__main__':
    app.run(debug=True)
