public class XmlParser
{
    public static XPathNavigator FindXmlElementByName(string xmlContent, string elementName)
    {
        if (string.IsNullOrEmpty(xmlContent) || string.IsNullOrEmpty(elementName))
        {
            throw new ArgumentException("XML content and element name cannot be null or empty.");
        }

        try
        {
            XPathDocument document = new XPathDocument(new System.IO.StringReader(xmlContent));
            XPathNavigator navigator = document.CreateNavigator();
            return navigator.SelectSingleNode($"//{elementName}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error parsing XML: {ex.Message}");
            throw;
        }
    }
}
