use std::env;
use std::fs;

pub fn create_directory_and_set_env_var(env_var_name: &str, new_dir_path: &str) -> Result<(), Box<dyn std::error::Error>> {
    if env_var_name.is_empty() || new_dir_path.is_empty() {
        return Err("Environment variable name and directory path cannot be empty.".into());
    }

    let current_dir_path = env::var(env_var_name).unwrap_or_else(|_| String::new());

    if current_dir_path != new_dir_path {
        fs::create_dir_all(&new_dir_path)?;
        env::set_var(env_var_name, &new_dir_path);
    }

    Ok(())
}
