import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class MD5HashService {

    private static final int BATCH_SIZE = 1000;
    private static final long LATENCY_TARGET = 100; // in milliseconds
    private ExecutorService executorService;

    public MD5HashService() {
        this.executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
    }

    public void processBatch(String[] batch, MetadataSource metadataSource) throws InterruptedException {
        for (int i = 0; i < batch.length; i += BATCH_SIZE) {
            int end = Math.min(i + BATCH_SIZE, batch.length);
            String[] subBatch = new String[end - i];
            System.arraycopy(batch, i, subBatch, 0, subBatch.length);

            executorService.submit(() -> {
                for (String str : subBatch) {
                    try {
                        String metadata = metadataSource.getMetadata(str);
                        String hash = computeMD5Hash(str + metadata);
                        // Process the hash as needed
                    } catch (NoSuchAlgorithmException e) {
                        Thread.currentThread().interrupt();
                        throw new RuntimeException("Failed to compute MD5 hash", e);
                    }
                }
            });
        }

        executorService.shutdown();
        if (!executorService.awaitTermination(LATENCY_TARGET, TimeUnit.MILLISECONDS)) {
            executorService.shutdownNow();
        }
    }

    private String computeMD5Hash(String input) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] messageDigest = md.digest(input.getBytes());
        StringBuilder hexString = new StringBuilder();
        for (byte b : messageDigest) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

    public interface MetadataSource {
        String getMetadata(String str) throws InterruptedException;
    }
}
