response:
["```javascript
const containerElement = document.getElementById('footer-scripts');
if (!containerElement) {
    console.warn('Container element not found.');
}

function renderFooterScripts(scripts) {
    if (!Array.isArray(scripts) || scripts.length === 0) return;

    const existingScripts = new Set(Array.from(containerElement.getElementsByTagName('script')).map(script => script.src));

    scripts.forEach(script => {
        if (typeof script.key !== 'string' || typeof script.code !== 'string') return;
        if (existingScripts.has(script.key)) return;

        const scriptTag = document.createElement('script');
        scriptTag.src = script.key;
        scriptTag.onload = () => {
            try {
                eval(script.code);
            } catch (error) {
                console.error(`Error executing script ${script.key}:`, error);
            }
        };
        scriptTag.onerror = () => {
            console.error(`Failed to load script ${script.key}`);
        };

        containerElement.appendChild(scriptTag);
        existingScripts.add(script.key);
    });
}
```"]

