class DataPipeline {
  constructor(maxStreams, checkInterval, timeout) {
    this.maxStreams = maxStreams;
    this.checkInterval = checkInterval;
    this.timeout = timeout;
    this.streams = [];
    this.paused = false;
    this.monitoringSystem = null;
    this.logger = console.log;
    this.errorHandler = console.error;
  }

  setMonitoringSystem(system) {
    this.monitoringSystem = system;
  }

  setLogger(logger) {
    this.logger = logger;
  }

  setErrorHandler(handler) {
    this.errorHandler = handler;
  }

  async start() {
    setInterval(async () => {
      if (!this.paused && this.streams.length < this.maxStreams) {
        try {
          const streamData = await this.collectData();
          this.aggregateData(streamData);
        } catch (error) {
          this.errorHandler(error);
        }
      }
    }, this.checkInterval);
  }

  async collectData() {
    // Simulate data collection from a stream
    return new Promise((resolve, reject) => {
      setTimeout(() => {
        resolve({ data: 'Sample Data' });
      }, this.timeout);
    });
  }

  aggregateData(data) {
    // Aggregate data into the centralized store
    this.logger('Aggregating data:', data);
  }

  pause() {
    this.paused = true;
    if (this.monitoringSystem) {
      this.monitoringSystem.updateStatus('Paused');
    }
  }

  resume() {
    this.paused = false;
  }
}

