const EventEmitter = require('events');
const axios = require('axios');

class DataAggregator extends EventEmitter {
  constructor(maxBufferSize) {
    super();
    this.maxBufferSize = maxBufferSize;
    this.buffer = [];
    this.activeStreams = new Set();
    this.retryAttempts = {};
  }

  async addStream(streamId, apiUrl) {
    if (this.activeStreams.has(streamId)) return;

    this.activeStreams.add(streamId);
    this.retryAttempts[streamId] = 0;

    const fetchData = async () => {
      try {
        const response = await axios.get(apiUrl);
        this.buffer.push(response.data);
        this.emit('data', response.data);

        if (this.buffer.length >= this.maxBufferSize) {
          this.emit('bufferFull');
        }

        fetchData();
      } catch (error) {
        if (this.retryAttempts[streamId] < 3) {
          this.retryAttempts[streamId]++;
          setTimeout(fetchData, 1000); // Retry after 1 second
        } else {
          console.error(`Failed to fetch data from ${apiUrl} after multiple attempts`);
          this.activeStreams.delete(streamId);
        }
      }
    };

    fetchData();
  }

  clearBuffer() {
    this.buffer = [];
    this.emit('bufferCleared');
  }

  getBufferSize() {
    return this.buffer.length;
  }
}

// Usage example
const aggregator = new DataAggregator(100);

aggregator.on('data', (data) => {
  console.log('New data received:', data);
});

aggregator.on('bufferFull', () => {
  console.log('Buffer is full. Processing...');
  // Perform buffer processing here
});

aggregator.on('bufferCleared', () => {
  console.log('Buffer has been cleared.');
});

// Add streams with different APIs
aggregator.addStream('stream1', 'https://api.example.com/data1');
aggregator.addStream('stream2', 'https://api.example.com/data2');

// Clear buffer after some time
setTimeout(() => aggregator.clearBuffer(), 5000);
```"]

["```javascript
function traverseDOM(selectors, callback) {
    const elements = [];

    function traverse(node) {
        if (node.nodeType === Node.ELEMENT_NODE) {
            let matches = true;
            selectors.forEach(selector => {
                if (!matchesSelector(node, selector)) {
                    matches = false;
                }
            });

            if (matches && !isHidden(node)) {
                elements.push(node);
                callback(node);
            }
        }

        for (let child of node.childNodes) {
            traverse(child);
        }
    }

    function isHidden(element) {
        return window.getComputedStyle(element).display === 'none';
    }

    function matchesSelector(element, selector) {
        if (selector.startsWith('#')) {
            return element.id === selector.slice(1);
        } else if (selector.startsWith('.')) {
            return element.classList.contains(selector.slice(1));
        }
        // Add more selector types as needed
        return false;
    }

    traverse(document.body);
    return elements;
}

// Example usage:
traverseDOM(['#myId', '.myClass'], node => {
    console.log(node);
});
```

This code snippet provides a basic implementation of the described functionality. It uses an iterative approach to traverse the DOM tree, avoiding potential stack overflow errors due to deep recursion. The `matchesSelector` function checks if an element matches a given selector based on class and ID attributes. The `isHidden` function determines if an element is conditionally hidden. The `traverseDOM` function takes an array of selectors and a callback function as arguments, traverses the DOM tree, and applies the specified criteria to each element."]

