import android.content.Context;
import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.os.Environment;
import androidx.annotation.NonNull;
import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.util.LinkedHashMap;
import java.util.Map;

public class ThemeCacheManager {
    private static final String DEFAULT_THEME_DIR = "default_theme_dir";
    private static final int MAX_CACHE_SIZE = 1024 * 1024 * 5; // 5MB
    private static final float COMPRESSION_QUALITY = 0.8f;
    private Context context;
    private File themeDir;
    private Map<String, Bitmap> cache;

    public ThemeCacheManager(@NonNull Context context) {
        this.context = context;
        initializeThemeDirectory();
        this.cache = new LinkedHashMap<>(16, 0.75f, true) {
            protected boolean removeEldestEntry(Map.Entry eldest) {
                return size() > MAX_CACHE_SIZE;
            }
        };
    }

    private void initializeThemeDirectory() {
        themeDir = context.getDir(DEFAULT_THEME_DIR, Context.MODE_PRIVATE);
        if (!themeDir.exists()) {
            themeDir.mkdirs();
        }
    }

    public Bitmap getThemeBitmap(String themeName) {
        Bitmap bitmap = cache.get(themeName);
        if (bitmap == null) {
            File file = new File(themeDir, themeName + ".png");
            if (file.exists()) {
                bitmap = BitmapFactory.decodeFile(file.getAbsolutePath());
                cache.put(themeName, bitmap);
            }
        } else {
            // Recycle unused bitmaps
            recycleUnusedBitmaps();
        }
        return bitmap;
    }

    private void recycleUnusedBitmaps() {
        for (Bitmap bitmap : cache.values()) {
            if (!bitmap.isRecycled()) {
                bitmap.recycle();
                break; // Only one at a time to avoid excessive GC pressure
            }
        }
    }

    public void saveThemeBitmap(String themeName, Bitmap bitmap) throws IOException {
        File file = new File(themeDir, themeName + ".png");
        FileOutputStream out = new FileOutputStream(file);
        bitmap.compress(Bitmap.CompressFormat.PNG, (int) (COMPRESSION_QUALITY * 100), out);
        out.flush();
        out.close();
        cache.put(themeName, bitmap);
    }

    public void clearCache() {
        for (Bitmap bitmap : cache.values()) {
            if (!bitmap.isRecycled()) {
                bitmap.recycle();
            }
        }
        cache.clear();
    }

    // Additional methods for external storage integration, dynamic theme switching,
    // performance metrics logging, and configuration management can be added here.
}
