public class DistributedServiceManager {
    private static final Logger logger = Logger.getLogger(DistributedServiceManager.class.getName());
    private final int maxInstances;
    private final long delayRangeMin;
    private final long delayRangeMax;
    private final String healthCheckUrl;
    private final long healthCheckInterval;
    private final BlockingQueue<Runnable> taskQueue;
    private final ExecutorService executorService;

    public DistributedServiceManager(String configFilePath) throws IOException {
        Properties properties = new Properties();
        try (FileInputStream fis = new FileInputStream(configFilePath)) {
            properties.load(fis);
        }

        this.maxInstances = Integer.parseInt(properties.getProperty("max.instances"));
        this.delayRangeMin = Long.parseLong(properties.getProperty("delay.range.min"));
        this.delayRangeMax = Long.parseLong(properties.getProperty("delay.range.max"));
        this.healthCheckUrl = properties.getProperty("health.check.url");
        this.healthCheckInterval = Long.parseLong(properties.getProperty("health.check.interval"));

        this.taskQueue = new LinkedBlockingQueue<>();
        this.executorService = Executors.newFixedThreadPool(maxInstances);
    }

    public void start() {
        while (true) {
            try {
                if (isHealthy()) {
                    submitTask();
                }
                Thread.sleep(getRandomDelay());
            } catch (InterruptedException e) {
                logger.log(Level.SEVERE, "Thread interrupted", e);
                Thread.currentThread().interrupt();
            }
        }
    }

    private boolean isHealthy() {
        // Simulate health check
        try {
            // Replace with actual health check logic
            return true;
        } catch (Exception e) {
            logger.log(Level.WARNING, "Health check failed", e);
            return false;
        }
    }

    private void submitTask() {
        if (executorService.getActiveCount() < maxInstances) {
            executorService.submit(() -> {
                try {
                    // Simulate service work
                    Thread.sleep(1000);
                } catch (InterruptedException e) {
                    logger.log(Level.SEVERE, "Thread interrupted", e);
                    Thread.currentThread().interrupt();
                }
                stop();
            });
        } else {
            taskQueue.offer(() -> submitTask());
        }
    }

    private void stop() {
        // Simulate service stop
        try {
            // Replace with actual stop logic
            Thread.sleep(1000);
        } catch (InterruptedException e) {
            logger.log(Level.SEVERE, "Thread interrupted", e);
            Thread.currentThread().interrupt();
        }
        logger.info("Service stopped");
    }

    private long getRandomDelay() {
        return delayRangeMin + (long) (Math.random() * (delayRangeMax - delayRangeMin));
    }

    public void reloadConfig(String configFilePath) throws IOException {
        Properties properties = new Properties();
        try (FileInputStream fis = new FileInputStream(configFilePath)) {
            properties.load(fis);
        }

        this.maxInstances = Integer.parseInt(properties.getProperty("max.instances"));
        this.delayRangeMin = Long.parseLong(properties.getProperty("delay.range.min"));
        this.delayRangeMax = Long.parseLong(properties.getProperty("delay.range.max"));
        this.healthCheckUrl = properties.getProperty("health.check.url");
        this.healthCheckInterval = Long.parseLong(properties.getProperty("health.check.interval"));

        executorService.shutdownNow();
        executorService = Executors.newFixedThreadPool(maxInstances);
    }

    public static void main(String[] args) {
        try {
            DistributedServiceManager manager = new DistributedServiceManager("config.yaml");
            manager.start();
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Failed to load configuration", e);
        }
    }
}
