use hyper::{Client, Uri};
use hyper_tls::HttpsConnector;
use std::time::Duration;

#[derive(Clone)]
struct HttpClientConfig {
    base_url: String,
    validate_cert: bool,
    custom_headers: Vec<(String, String)>,
    upload_params: Option<UploadParams>,
    retry_policy: RetryPolicy,
}

#[derive(Clone)]
struct UploadParams {
    file_path: String,
    content_type: String,
}

#[derive(Clone)]
struct RetryPolicy {
    max_retries: u32,
    initial_delay: Duration,
    backoff_factor: f64,
}

pub struct HttpClient {
    client: Client<HttpsConnector>,
    config: HttpClientConfig,
}

impl HttpClient {
    pub fn new(config: HttpClientConfig) -> Self {
        let https = HttpsConnector::new();
        let client = Client::builder()
            .build(https)
            .expect("Failed to create HTTP client");
        HttpClient { client, config }
    }

    pub async fn request(
        &self,
        method: hyper::Method,
        path: String,
        body: Option<hyper::Body>,
    ) -> Result<hyper::Response<hyper::Body>, hyper::Error> {
        let uri = format!("{}{}", self.config.base_url, path).parse::<Uri>()?;
        let mut request = hyper::Request::builder()
            .method(method)
            .uri(uri)
            .body(body.unwrap_or_default())
            .expect("Failed to build HTTP request");

        for (key, value) in &self.config.custom_headers {
            request.headers_mut().insert(key.parse()?, value.parse()?);
        }

        self.client.request(request).await
    }
}

fn main() {
    let config = HttpClientConfig {
        base_url: "https://api.example.com".to_string(),
        validate_cert: true,
        custom_headers: vec![
            ("User-Agent".to_string(), "MyClient/1.0".to_string()),
        ],
        upload_params: Some(UploadParams {
            file_path: "/path/to/file.txt".to_string(),
            content_type: "application/octet-stream".to_string(),
        }),
        retry_policy: RetryPolicy {
            max_retries: 3,
            initial_delay: Duration::from_secs(1),
            backoff_factor: 2.0,
        },
    };

    let client = HttpClient::new(config);

    // Example usage
    tokio::runtime::Runtime::new().unwrap().block_on(async move {
        match client.request(hyper::Method::GET, "/endpoint".to_string(), None).await {
            Ok(response) => println!("Response: {:?}", response),
            Err(e) => eprintln!("Error: {}", e),
        }
    });
}
