use std::env;
use std::process::{Command, ExitCode};
use std::time::{Instant, Duration};
use rustc_driver::{self, catch_with_exit_code};
use get_resident_set_size::get_resident_set_size;
use sync_lazy::SyncLazy;

fn main() -> ExitCode {
    let args: Vec<String> = env::args().collect();
    if args.len() < 3 {
        eprintln!("Usage: {} <project_dir1> <project_dir2> ... <log_level>", args[0]);
        return ExitCode::FAILURE;
    }

    let log_level = &args[args.len() - 1];
    let project_dirs = &args[1..args.len() - 1];

    for dir in project_dirs {
        match compile_project(dir, log_level) {
            Ok(exit_code) => println!("Project {} compiled with exit code {}", dir, exit_code),
            Err(e) => eprintln!("Error compiling project {}: {}", dir, e),
        }
    }

    ExitCode::SUCCESS
}

fn compile_project(project_dir: &str, log_level: &str) -> Result<ExitCode, String> {
    let start_time = Instant::now();
    let before_rss = get_resident_set_size().unwrap_or(0);

    let exit_code = catch_with_exit_code(|| {
        // Simulate compilation process
        Command::new("rustc")
            .arg("--crate-type=bin")
            .arg("-C")
            .arg(format!("debuginfo={}", log_level))
            .current_dir(project_dir)
            .status()
            .map_err(|e| format!("Failed to run rustc: {}", e))?
            .code()
    })?;

    let after_rss = get_resident_set_size().unwrap_or(0);
    let duration = start_time.elapsed();

    println!("Compilation took {}ms, RSS before: {}, after: {}", 
              duration.as_millis(), before_rss, after_rss);

    Ok(exit_code)
}
```

This code snippet provides a basic structure for the Rust function that integrates into a larger build system. It accepts command-line arguments specifying project directories and a custom logging level. The function measures the time taken for each compilation using `std::time::Instant` and captures the resident set size before and after the compilation using `get_resident_set_size`. It uses `rustc_driver::catch_with_exit_code` to handle potential errors during compilation, gracefully reporting them while minimizing impact on other ongoing compilations. The function simulates a compilation process using `Command::new("rustc")`, but in a real-world scenario, you would replace this with the actual compilation command for your projects.']

