from functools import lru_cache
import requests

# Simulated database operations
def update_database(patient_id, new_status, ip_address):
    # Simulate a database update operation
    print(f"Updating patient {patient_id} with status {new_status} from IP {ip_address}")
    return True

def check_patient_exists(patient_id):
    # Simulate checking if a patient exists in the database
    return random.choice([True, False])

# Caching mechanism to store patient existence checks
@lru_cache(maxsize=1024)
def cached_check_patient_exists(patient_id):
    return check_patient_exists(patient_id)

# Function to update patient status with retry logic and caching
def update_patient_status(patient_id, new_status, ip_address):
    max_retries = 5
    backoff_factor = 2

    for attempt in range(max_retries + 1):
        try:
            if cached_check_patient_exists(patient_id):
                success = update_database(patient_id, new_status, ip_address)
                if success:
                    return "Update successful"
                else:
                    raise Exception("Database update failed")
            else:
                return "Patient ID not found"
        except requests.exceptions.RequestException as e:
            print(f"Request error: {e}. Retrying...")
            time.sleep(backoff_factor ** attempt * random.uniform(0.5, 1.5))
        except Exception as e:
            print(f"Error during update: {e}")
            return "Update failed"

    return "Update failed after retries"

# Example usage
print(update_patient_status("P12345", "Active", "192.168.1.1"))
