<?php

function generateRandomString($length = 10, $characters = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ') {
    return substr(str_shuffle(str_repeat($characters, ceil($length / strlen($characters)))), 1, $length);
}

function hashPassword($password) {
    return password_hash($password, PASSWORD_DEFAULT);
}

async function readFileAsync($filePath) {
    try {
        $file = fopen($filePath, 'r');
        if ($file === false) {
            throw new Exception("Failed to open file: $filePath");
        }

        $content = await \React\Promise\resolve(fread($file, filesize($filePath)));
        fclose($file);
        return $content;
    } catch (\Exception $e) {
        error_log("Error reading file $filePath: " . $e->getMessage());
        return null;
    }
}

async function readFilesAsync($filePaths) {
    $promises = [];
    foreach ($filePaths as $filePath) {
        $promises[] = readFileAsync($filePath);
    }

    $contents = await \React\Promise\all($promises);
    return array_map(function($content, $path) {
        if ($content === null) {
            return null;
        }
        return ['path' => $path, 'content' => $content];
    }, $contents, $filePaths);
}

// Example usage:
$characters = 'abcdefghijklmnopqrstuvwxyz';
$password = 'mySecurePassword123';
$filePaths = ['/path/to/file1.txt', '/path/to/file2.txt'];

$randomString = generateRandomString(8, $characters);
$hashedPassword = hashPassword($password);

$loop = \React\EventLoop\Factory::create();
$filesContents = await readFilesAsync($filePaths)->then(function($contents) {
    return array_filter($contents, function($content) {
        return $content !== null;
    });
})->done();

print_r($randomString);
echo "\n";
print_r($hashedPassword);
echo "\n";
print_r($filesContents);

$loop->run();
?>
```

