void insertState(State** head, int id, int position) {
    State* newState = (State*)malloc(sizeof(State));
    if (newState == NULL) {
        // Handle memory allocation failure
        return;
    }
    newState->id = id;
    newState->next = NULL;

    if (*head == NULL || position == 0) {
        newState->next = *head;
        *head = newState;
    } else {
        State* current = *head;
        for (int i = 1; current != NULL && i < position; i++) {
            current = current->next;
        }
        if (current != NULL) {
            newState->next = current->next;
            current->next = newState;
        } else {
            // Handle invalid position
            free(newState);
        }
    }
}

// Function to dynamically manage the linked list of states from an FSA
void manageStateList(int* stateArray, int numStates, FSA* fsa, int lastState) {
    State* head = NULL;

    // Populate the initial state list based on the FSA
    for (int i = 0; i < numStates; i++) {
        insertState(&head, stateArray[i], i);
    }

    // Sort the state list using the custom comparator and secondary criterion
    qsort(head, numStates, sizeof(State), compareStates);
    if (numStates > 1) {
        for (int i = 0; i < numStates - 1; i++) {
            if (compareStates(&head[i], &head[i + 1]) == 0) {
                qsort(&head[i], 2, sizeof(State), secondarySortCriterion);
            }
        }
    }

    // Insert new states at specific positions in the list
    insertState(&head, lastState, numStates);

    // Free the memory allocated for the state list
    State* current = head;
    while (current != NULL) {
        State* next = current->next;
        free(current);
        current = next;
    }
}
