#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_REQUESTS 10000
#define LOG_INTERVAL 60

typedef struct {
    int id;
    time_t timestamp;
    size_t size;
} Request;

typedef struct {
    Request requests[MAX_REQUESTS];
    int count;
    size_t total_size;
    time_t last_log_time;
} Metrics;

void process_request(Metrics *metrics, int request_id, size_t request_size) {
    if (metrics->count >= MAX_REQUESTS) {
        printf("Error: Maximum number of concurrent requests reached.\n");
        return;
    }

    metrics->requests[metrics->count].id = request_id;
    metrics->requests[metrics->count].timestamp = time(NULL);
    metrics->requests[metrics->count].size = request_size;
    metrics->total_size += request_size;
    metrics->count++;

    if (time(NULL) - metrics->last_log_time >= LOG_INTERVAL) {
        printf("Metrics: %d requests, total size: %zu bytes\n", metrics->count, metrics->total_size);
        metrics->last_log_time = time(NULL);
    }
}

int main() {
    Metrics metrics = {0};
    srand(time(NULL));

    for (int i = 0; i < 15000; i++) {
        int request_id = rand() % MAX_REQUESTS;
        size_t request_size = rand() % 1024 + 1;
        process_request(&metrics, request_id, request_size);
        usleep(100); // Simulate processing time
    }

    return 0;
}
