// Define a structure to hold attack details
struct Attack {
    int id;
    int cooldown;
    int frequencyLimit;
    int usageCount;
};

class GameCharacter {
private:
    std::vector<Attack> attacks;
    std::mt19937 rng;
    std::uniform_int_distribution<> dist;

public:
    GameCharacter() : rng(std::random_device{}()), dist(0, 2) {
        // Initialize attacks with unique IDs, cooldowns, and frequency limits
        attacks.push_back({1, 500, 5, 0});
        attacks.push_back({2, 750, 5, 0});
        attacks.push_back({3, 1000, 5, 0});
    }

    void useAttack() {
        // Select an attack based on probability and cooldown
        int selected = dist(rng);
        while (attacks[selected].usageCount >= attacks[selected].frequencyLimit || std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now() - std::chrono::system_clock::from_time_t(attacks[selected].lastUsed)).count() < attacks[selected].cooldown) {
            selected = dist(rng);
        }

        // Update attack usage and last used time
        attacks[selected].usageCount++;
        attacks[selected].lastUsed = std::chrono::system_clock::to_time_t(std::chrono::system_clock::now());

        // Log the attack usage (simulated)
        logAttackUsage(attacks[selected]);
    }

private:
    void logAttackUsage(const Attack& attack) {
        // Simulate logging to an external system
        std::cout << "Attack " << attack.id << " used at " << std::chrono::system_clock::to_time_t(std::chrono::system_clock::now()) << std::endl;
    }
};

int main() {
    GameCharacter character;
    for (int i = 0; i < 10; ++i) {
        character.useAttack();
        std::this_thread::sleep_for(std::chrono::milliseconds(200)); // Simulate game loop
    }
    return 0;
}
