using System;
using System.Collections.Concurrent;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;

[Serializable]
public class CustomRandomGeneratorContext
{
    public string Id { get; set; }
    public Type NumberType { get; set; }
    public double MinValue { get; set; }
    public double MaxValue { get; set; }
    public bool IsInclusive { get; set; }

    public object GenerateRandom()
    {
        Random random = new Random();
        if (NumberType == typeof(int))
        {
            int min = (int)Math.Round(IsInclusive ? MinValue : MinValue + 1);
            int max = (int)Math.Round(IsInclusive ? MaxValue : MaxValue - 1);
            return random.Next(min, max + 1);
        }
        else if (NumberType == typeof(double))
        {
            double min = IsInclusive ? MinValue : MinValue + 0.0001;
            double max = IsInclusive ? MaxValue : MaxValue - 0.0001;
            return random.NextDouble() * (max - min) + min;
        }
        throw new InvalidOperationException("Unsupported number type.");
    }

    public byte[] Serialize()
    {
        BinaryFormatter formatter = new BinaryFormatter();
        using (MemoryStream stream = new MemoryStream())
        {
            formatter.Serialize(stream, this);
            return stream.ToArray();
        }
    }

    public static CustomRandomGeneratorContext Deserialize(byte[] data)
    {
        BinaryFormatter formatter = new BinaryFormatter();
        using (MemoryStream stream = new MemoryStream(data))
        {
            return (CustomRandomGeneratorContext)formatter.Deserialize(stream);
        }
    }
}

public class CustomRandomGenerator
{
    private ConcurrentDictionary<string, CustomRandomGeneratorContext> contexts;

    public CustomRandomGenerator()
    {
        contexts = new ConcurrentDictionary<string, CustomRandomGeneratorContext>();
    }

    public void AddOrUpdateContext(string id, Type numberType, double minValue, double maxValue, bool isInclusive)
    {
        contexts[id] = new CustomRandomGeneratorContext
        {
            Id = id,
            NumberType = numberType,
            MinValue = minValue,
            MaxValue = maxValue,
            IsInclusive = isInclusive
        };
    }

    public object GenerateRandom(string id)
    {
        if (contexts.TryGetValue(id, out CustomRandomGeneratorContext context))
        {
            return context.GenerateRandom();
        }
        throw new ArgumentException("Context not found.");
    }

    public byte[] SerializeContext(string id)
    {
        if (contexts.TryGetValue(id, out CustomRandomGeneratorContext context))
        {
            return context.Serialize();
        }
        throw new ArgumentException("Context not found.");
    }

    public void DeserializeContext(string id, byte[] data)
    {
        CustomRandomGeneratorContext context = CustomRandomGeneratorContext.Deserialize(data);
        contexts[id] = context;
    }

    public override string ToString()
    {
        if (contexts.Count > 0)
        {
            return $"Active Context: {contexts.First().Value.Id}, Range: [{contexts.First().Value.MinValue}, {contexts.First().Value.MaxValue}]";
        }
        return "No active context.";
    }
}
