function getElementList(rootNode, selector, testElement, deepSearch) {
    if (rootNode === null || typeof selector !== 'string' || typeof testElement !== 'function') {
        return [];
    }
    let result = [];
    function traverse(node) {
        if (node.matches(selector) && testElement(node)) {
            result.push(node);
        }
        if (deepSearch) {
            for (let child of node.children) {
                traverse(child);
            }
        }
    }
    traverse(rootNode);
    return result;
}
