#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PATH_LENGTH 260

char* generate_unique_filename(const char* directory_path, const char* original_filename) {
    if (directory_path == NULL || original_filename == NULL) {
        return NULL;
    }

    // Truncate the filename if it exceeds the maximum path length
    size_t truncated_length = strlen(directory_path) + strlen(original_filename);
    if (truncated_length > MAX_PATH_LENGTH - 1) {
        original_filename += truncated_length - MAX_PATH_LENGTH + 1;
    }

    // Extract the base name and extension from the original filename
    char* base_name = strtok((char*)original_filename, ".");
    char* extension = strtok(NULL, ".");

    if (base_name == NULL || extension == NULL) {
        return NULL;
    }

    // Generate a hash based on the original filename's characters
    unsigned int hash = 0;
    for (size_t i = 0; i < strlen(original_filename); ++i) {
        hash += original_filename[i];
    }

    // Append a sequence of digits and file type extension to ensure uniqueness
    char* new_filename = malloc(MAX_PATH_LENGTH);
    if (new_filename == NULL) {
        return NULL;
    }

    snprintf(new_filename, MAX_PATH_LENGTH, "%s_%u.%s", base_name, hash, extension);

    return new_filename;
}

int main() {
    const char* directory_path = "C:\\Users\\Username\\Documents";
    const char* original_filename = "example file.txt";

    char* unique_filename = generate_unique_filename(directory_path, original_filename);
    if (unique_filename != NULL) {
        printf("Unique filename: %s\n", unique_filename);
        free(unique_filename);
    } else {
        printf("Failed to generate unique filename.\n");
    }

    return 0;
}
