    if (!ctx) return NULL;

    // Derive key using a secure KDF
    unsigned char key[32];
    unsigned char salt[16];
    if (RAND_bytes(salt, sizeof(salt)) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    int derived_key_len = PKCS5_PBKDF2_HMAC(password, strlen(password), salt, sizeof(salt), 10000, EVP_sha256(), key, sizeof(key));
    if (derived_key_len != sizeof(key)) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Set IV length and key length
    unsigned char iv[EVP_CIPHER_iv_length(EVP_aes_256_cbc())];
    if (RAND_bytes(iv, sizeof(iv)) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Initialize cipher context
    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

void cleanup_cipher(EVP_CIPHER_CTX *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx);
    }
}
