    if (system(command) != 0) {
        perror("Conversion failed");
        close(lock_fd);
        unlink(lock_file);
        return NULL;
    }

    close(lock_fd);
    unlink(lock_file);
    return NULL;
}

int process_files(FileData files[], int num_files) {
    pthread_t threads[MAX_FILES];
    int success_count = 0;

    for (int i = 0; i < num_files; i++) {
        if (pthread_create(&threads[i], NULL, convert_to_pdf, &files[i]) != 0) {
            perror("Failed to create thread");
            return -1;
        }
    }

    for (int i = 0; i < num_files; i++) {
        pthread_join(threads[i], NULL);
        success_count++;
    }

    printf("Conversion success rate: %.2f%%\n", ((float)success_count / num_files) * 100);
    return 0;
}

