#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <signal.h>

#define MAX_CONCURRENT_TASKS 10

typedef struct {
    int task_id;
    // Add other task parameters here
} Task;

typedef struct {
    Task tasks[MAX_CONCURRENT_TASKS];
    int front, rear;
    sem_t semaphore;
    pthread_mutex_t mutex;
} TaskQueue;

TaskQueue task_queue;

void initialize_task_queue() {
    task_queue.front = 0;
    task_queue.rear = -1;
    sem_init(&task_queue.semaphore, 0, MAX_CONCURRENT_TASKS);
    pthread_mutex_init(&task_queue.mutex, NULL);
}

int is_task_queue_full() {
    return (task_queue.rear + 1) % MAX_CONCURRENT_TASKS == task_queue.front;
}

int is_task_queue_empty() {
    return task_queue.front == -1;
}

void enqueue_task(Task task) {
    sem_wait(&task_queue.semaphore);
    pthread_mutex_lock(&task_queue.mutex);

    if (is_task_queue_empty()) {
        task_queue.front = 0;
    }

    task_queue.rear = (task_queue.rear + 1) % MAX_CONCURRENT_TASKS;
    task_queue.tasks[task_queue.rear] = task;

    pthread_mutex_unlock(&task_queue.mutex);
}

Task dequeue_task() {
    Task task;
    sem_wait(&task_queue.semaphore);
    pthread_mutex_lock(&task_queue.mutex);

    if (is_task_queue_empty()) {
        // Handle error: no tasks to dequeue
        task.task_id = -1; // Invalid task ID
    } else {
        task = task_queue.tasks[task_queue.front];

        if (task_queue.front == task_queue.rear) {
            task_queue.front = -1;
            task_queue.rear = -1;
        } else {
            task_queue.front = (task_queue.front + 1) % MAX_CONCURRENT_TASKS;
        }
    }

    pthread_mutex_unlock(&task_queue.mutex);
    return task;
}

void* background_task_runner(void* arg) {
    while (1) {
        Task task = dequeue_task();
        if (task.task_id == -1) {
            break; // Exit thread on invalid task ID
        }
        // Execute the task here
        printf("Executing task %d\n", task.task_id);
    }
    return NULL;
}

void handle_shutdown_signal(int signum) {
    // Signal handler for system shutdown
    printf("System shutting down...\n");
    // Gracefully terminate all background tasks
    exit(0);
}

int main() {
    initialize_task_queue();

    pthread_t threads[MAX_CONCURRENT_TASKS];
    for (int i = 0; i < MAX_CONCURRENT_TASKS; i++) {
        pthread_create(&threads[i], NULL, background_task_runner, NULL);
    }

    // Simulate task submissions
    for (int i = 1; i <= 20; i++) {
        Task task;
        task.task_id = i;
        enqueue_task(task);
    }

    // Register signal handler for system shutdown
    signal(SIGINT, handle_shutdown_signal);

    // Wait for all background threads to finish
    for (int i = 0; i < MAX_CONCURRENT_TASKS; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
