using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Threading.Tasks;

public class WebAppManager
{
    private const int MaxConcurrentProcesses = 100;
    private readonly Dictionary<string, Process> _processes = new Dictionary<string, Process>();

    public async Task DeployApplicationsAsync(string directoryPath)
    {
        var directories = Directory.GetDirectories(directoryPath);
        var tasks = new List<Task>();

        foreach (var dir in directories)
        {
            if (_processes.Count >= MaxConcurrentProcesses)
            {
                await Task.Delay(100); // Throttle to avoid overwhelming the system
            }

            tasks.Add(DeployApplicationAsync(dir));
        }

        await Task.WhenAll(tasks);
    }

    private async Task DeployApplicationAsync(string directoryPath)
    {
        var configFilePath = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(configFilePath))
        {
            LogError($"Missing web.config file in {directoryPath}");
            return;
        }

        try
        {
            var processInfo = new ProcessStartInfo
            {
                FileName = "dotnet",
                Arguments = $"run --project {directoryPath}",
                RedirectStandardOutput = true,
                RedirectStandardError = true,
                UseShellExecute = false,
                CreateNoWindow = true
            };

            using (var process = new Process { StartInfo = processInfo })
            {
                _processes[process.Id] = process;
                process.OutputDataReceived += (sender, e) => LogOutput(e.Data);
                process.ErrorDataReceived += (sender, e) => LogError(e.Data);

                await Task.Run(() =>
                {
                    process.Start();
                    process.BeginOutputReadLine();
                    process.BeginErrorReadLine();

                    process.WaitForExit();
                });

                _processes.Remove(process.Id);
            }
        }
        catch (Exception ex)
        {
            LogError($"Failed to deploy application in {directoryPath}: {ex.Message}");
        }
    }

    private void LogOutput(string output)
    {
        Console.WriteLine(output);
    }

    private void LogError(string error)
    {
        Console.Error.WriteLine(error);
    }
}
