public class DataProcessor
{
    public async Task<(DataTableReader reader, string executionLog)> ProcessDataAsync(byte[] data, string phpScript)
    {
        // Validate data with third-party REST API
        var apiResponse = await ValidateDataWithApi(data);

        if (apiResponse.IsSuccessStatusCode)
        {
            // Store validated data in relational database
            var dataTable = await StoreDataInDatabase(apiResponse.Content);

            // Execute PHP script asynchronously
            var executionLog = await ExecutePhpScriptAsync(phpScript, dataTable);

            return (dataTable.CreateDataReader(), executionLog);
        }
        else
        {
            throw new Exception($"API validation failed with status code: {apiResponse.StatusCode}");
        }
    }

    private async Task<HttpResponseMessage> ValidateDataWithApi(byte[] data)
    {
        using (var client = new HttpClient())
        {
            var content = new ByteArrayContent(data);
            return await client.PostAsync("https://thirdpartyapi.com/validate", content);
        }
    }

    private async Task<DataTable> StoreDataInDatabase(string apiResponseContent)
    {
        // Simulate database operation
        var dataTable = new DataTable();
        dataTable.Columns.Add("Id", typeof(int));
        dataTable.Columns.Add("Data", typeof(byte[]));

        var row = dataTable.NewRow();
        row["Id"] = 1;
        row["Data"] = Convert.FromBase64String(apiResponseContent);
        dataTable.Rows.Add(row);

        return dataTable;
    }

    private async Task<string> ExecutePhpScriptAsync(string phpScript, DataTable dataTable)
    {
        using (var process = new System.Diagnostics.Process())
        {
            process.StartInfo.FileName = "php";
            process.StartInfo.Arguments = $"-r \"{phpScript}\"";
            process.StartInfo.RedirectStandardOutput = true;
            process.StartInfo.RedirectStandardError = true;
            process.StartInfo.UseShellExecute = false;
            process.StartInfo.CreateNoWindow = true;

            await process.StartAsync();

            var output = await process.StandardOutput.ReadToEndAsync();
            var error = await process.StandardError.ReadToEndAsync();

            if (!string.IsNullOrEmpty(error))
            {
                throw new Exception($"PHP script execution failed with errors: {error}");
            }

            return output;
        }
    }
}
