public class MessageDecryptor
{
    private readonly ConcurrentDictionary<string, (byte[], byte[])> _keyCache = new ConcurrentDictionary<string, (byte[], byte[])>();
    private readonly IMessagingService _messagingService;

    public MessageDecryptor(IMessagingService messagingService)
    {
        _messagingService = messagingService;
    }

    public async Task<string> DecryptMessageAsync(string messageId, string base64EncryptedMessage)
    {
        if (!_keyCache.TryGetValue(messageId, out var keyAndIv))
        {
            keyAndIv = await RetrieveKeyAndIVAsync(messageId);
            _keyCache.TryAdd(messageId, keyAndIv);
        }

        byte[] encryptedBytes = Convert.FromBase64String(base64EncryptedMessage);
        using (TripleDES tripleDes = TripleDES.Create())
        {
            tripleDes.Key = keyAndIv.Item1;
            tripleDes.IV = keyAndIv.Item2;
            tripleDes.Mode = CipherMode.CBC;
            tripleDes.Padding = PaddingMode.PKCS7;

            using (MemoryStream msDecrypt = new MemoryStream(encryptedBytes))
            using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, tripleDes.CreateDecryptor(), CryptoStreamMode.Read))
            {
                using (StreamReader srDecrypt = new StreamReader(csDecrypt))
                {
                    string decryptedMessage = await srDecrypt.ReadToEndAsync();
                    _messagingService.NotifyDelivery(messageId);
                    return decryptedMessage;
                }
            }
        }
    }

    private async Task<(byte[], byte[])> RetrieveKeyAndIVAsync(string messageId)
