    public static string HashString(string input, HashAlgorithm algorithm)
    {
        byte[] inputBytes = Encoding.UTF8.GetBytes(input);
        byte[] hashBytes = algorithm.ComputeHash(inputBytes);
        return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
    }

    public static string MD5Hash(string input)
    {
        using (MD5 md5 = MD5.Create())
        {
            return HashString(input, md5);
        }
    }

    public static string SHA256Hash(string input)
    {
        using (SHA256 sha256 = SHA256.Create())
        {
            return HashString(input, sha256);
        }
    }

    public static async Task<string> FetchMetadataAsync(string hash)
    {
        using (HttpClient client = new HttpClient())
        {
            try
            {
                HttpResponseMessage response = await client.GetAsync($"https://api.example.com/metadata/{hash}");
                response.EnsureSuccessStatusCode();
                string responseBody = await response.Content.ReadAsStringAsync();
                return responseBody;
            }
            catch (HttpRequestException e)
            {
                Console.WriteLine($"Request error: {e.Message}");
                return null;
            }
        }
    }

    public static async Task<string> HashAndFetchMetadataAsync(string input, HashAlgorithm algorithm)
    {
        string hash = HashString(input, algorithm);
        string metadata = await FetchMetadataAsync(hash);
        return $"{hash}:{metadata}";
    }
