using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class EncryptionService
{
    private readonly byte[] _key;
    private readonly byte[] _iv;

    public EncryptionService(byte[] key, byte[] iv)
    {
        _key = key;
        _iv = iv;
    }

    public byte[] Decrypt(byte[] ciphertext, byte[] hmacKey)
    {
        using (Aes aesAlg = Aes.Create())
        {
            aesAlg.Key = _key;
            aesAlg.IV = _iv;
            aesAlg.Mode = CipherMode.CBC;
            aesAlg.Padding = PaddingMode.PKCS7;

            ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);

            using (MemoryStream msDecrypt = new MemoryStream(ciphertext))
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                {
                    byte[] decryptedBytes = new byte[ciphertext.Length];
                    int bytesRead = csDecrypt.Read(decryptedBytes, 0, decryptedBytes.Length);

                    // Validate HMAC
                    byte[] hmacData = new byte[bytesRead - 32]; // Assuming the last 32 bytes are HMAC
                    Buffer.BlockCopy(decryptedBytes, 0, hmacData, 0, hmacData.Length);
                    byte[] receivedHmac = new byte[32];
                    Buffer.BlockCopy(decryptedBytes, hmacData.Length, receivedHmac, 0, receivedHmac.Length);

                    using (HMACSHA256 hmac = HMACSHA256.Create())
                    {
                        hmac.Key = hmacKey;
                        byte[] computedHmac = hmac.ComputeHash(hmacData);

                        if (!computedHmac.SequenceEqual(receivedHmac))
                        {
                            LogError("HMAC validation failed", decryptedBytes, hmacKey);
                            throw new InvalidOperationException("HMAC validation failed");
                        }
                    }

                    return hmacData; // Return the actual decrypted data without HMAC
                }
            }
        }
    }

    private void LogError(string message, byte[] data, byte[] key)
    {
        string timestamp = DateTime.UtcNow.ToString("o");
        string logMessage = $"[{timestamp}] Error: {message} - Data: {Convert.ToBase64String(data)} - Key: {Convert.ToBase64String(key)}";
        Console.WriteLine(logMessage); // Replace with actual logging framework
    }
}
```

