public class ConfigManager
{
    private readonly Dictionary<string, string> _configCache = new Dictionary<string, string>();
    private readonly HttpClient _httpClient;

    public ConfigManager()
    {
        _httpClient = new HttpClient();
    }

    public async Task<string> GetConfigAsync(string key)
    {
        if (_configCache.ContainsKey(key))
        {
            return _configCache[key];
        }

        try
        {
            var localValue = await LoadLocalConfigAsync(key);
            if (!string.IsNullOrEmpty(localValue))
            {
                _configCache[key] = localValue;
                return localValue;
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error loading local config: {ex.Message}");
        }

