const { exec } = require('child_process');
const axios = require('axios');
const rateLimit = require('express-rate-limit');
const express = require('express');
const app = express();
const port = 3000;

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 20, // limit each IP to 20 requests per windowMs
});

app.use(limiter);

// Function to execute shell commands and fetch data from external services
async function fetchData() {
  try {
    const [stdout, stderr] = await new Promise((resolve, reject) => {
      exec('your_shell_command_here', (error, stdout, stderr) => {
        if (error) {
          reject(error);
        } else {
          resolve([stdout, stderr]);
        }
      });
    });

    const response = await axios.get('https://api.example.com/data');
    return { stdout, data: response.data };
  } catch (error) {
    console.error('Error fetching data:', error);
    throw error;
  }
}

// Route to display metrics
app.get('/metrics', async (req, res) => {
  try {
    const { stdout, data } = await fetchData();
    // Process and render the results in a user-friendly format
    res.send(`
      <h1>Metrics</h1>
      <pre>${stdout}</pre>
      <table>
        ${data.map(item => `<tr><td>${item.name}</td><td>${item.value}</td></tr>`).join('')}
      </table>
    `);
  } catch (error) {
    res.status(500).send('Error fetching metrics');
  }
});

app.listen(port, () => {
  console.log(`Server running at http://localhost:${port}/`);
});
