use std::fs;
use std::env;
use std::path::Path;
use std::sync::{Mutex, Arc};
use log::{info, error};

static DIRECTORY_LOCK: Mutex<()> = Mutex::new(());

fn create_directory_and_set_env_var(directory_name: &str) -> Result<(), String> {
    let directory_path = Path::new(directory_name);

    // Acquire lock to handle race conditions
    let _guard = DIRECTORY_LOCK.lock().map_err(|_| "Failed to acquire lock")?;

    if directory_path.exists() {
        info!("Directory {} already exists, skipping creation.", directory_name);
    } else {
        fs::create_dir_all(directory_path).map_err(|e| format!("Failed to create directory: {}", e))?;
        info!("Created directory: {}", directory_name);
    }

    // Set environment variable atomically
    env::set_var("MY_DIRECTORY", directory_path.to_str().unwrap_or(""));
    info!("Set environment variable MY_DIRECTORY to: {}", directory_path.display());

    Ok(())
}

fn main() {
    if let Err(e) = create_directory_and_set_env_var("my_directory") {
        error!("{}", e);
    }
}
```

