import json
from abc import ABC, abstractmethod

class Config(ABC):
    @abstractmethod
    def to_json(self) -> str:
        pass

    @classmethod
    @abstractmethod
    def from_json(cls, json_str: str) -> 'Config':
        pass

class EnvironmentConfig(Config):
    def __init__(self, environment_id: str, settings: dict):
        self.environment_id = environment_id
        self.settings = settings

    def to_json(self) -> str:
        return json.dumps({'environment_id': self.environment_id, 'settings': self.settings})

    @classmethod
    def from_json(cls, json_str: str) -> 'EnvironmentConfig':
        data = json.loads(json_str)
        return cls(data['environment_id'], data['settings'])

class ConfigFactoryRegistry:
    _registry = {}

    @staticmethod
    def register_factory(environment_id: str, factory_func):
        if environment_id in ConfigFactoryRegistry._registry:
            raise ValueError(f"Factory for environment ID '{environment_id}' already exists.")
        ConfigFactoryRegistry._registry[environment_id] = factory_func

    @staticmethod
    def create_config(environment_id: str) -> Config:
        if environment_id not in ConfigFactoryRegistry._registry:
            raise KeyError(f"No factory registered for environment ID '{environment_id}'.")
        return ConfigFactoryRegistry._registry[environment_id]()

class DefaultConfig(EnvironmentConfig):
    DEFAULT_SETTINGS = {'debug': False, 'timeout': 30}

    def __init__(self, environment_id: str):
        super().__init__(environment_id, self.DEFAULT_SETTINGS)

# Example usage
def production_config_factory():
    return EnvironmentConfig('production', {'debug': False, 'timeout': 60})

ConfigFactoryRegistry.register_factory('production', production_config_factory)

config = ConfigFactoryRegistry.create_config('production')
print(config.to_json())
