#define MAX_RECORDS 1000
#define RESIZE_FACTOR 1.1

typedef struct {
    int value;
    char* key;
} Record;

typedef struct {
    Record* records;
    size_t count;
    size_t capacity;
} DynamicList;

DynamicList* create_dynamic_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;
    list->records = (Record*)calloc(MAX_RECORDS, sizeof(Record));
    if (!list->records) {
        free(list);
        return NULL;
    }
    list->count = 0;
    list->capacity = MAX_RECORDS;
    return list;
}

void destroy_dynamic_list(DynamicList* list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->records[i].key);
    }
    free(list->records);
    free(list);
}

int add_record(DynamicList* list, int value, const char* key) {
    if (list->count >= list->capacity) {
        size_t new_capacity = (size_t)(list->capacity * RESIZE_FACTOR);
        Record* new_records = (Record*)realloc(list->records, new_capacity * sizeof(Record));
        if (!new_records) return -1;
        list->records = new_records;
        list->capacity = new_capacity;
    }
    for (size_t i = 0; i < list->count; ++i) {
        if (strcmp(list->records[i].key, key) == 0) {
            printf("Duplicate key: %s\n", key);
            return -1;
        }
    }
    list->records[list->count].value = value;
    list->records[list->count].key = strdup(key);
    if (!list->records[list->count].key) return -1;
    ++list->count;
    return 0;
}

void print_largest_value(DynamicList* list) {
    int max_value = INT_MIN;
    for (size_t i = 0; i < list->count; ++i) {
        if (list->records[i].value > max_value) {
            max_value = list->records[i].value;
        }
    }
    printf("Largest value: %d\n", max_value);
}

int main() {
    DynamicList* list = create_dynamic_list();
    if (!list) return 1;

    // Simulate adding records
    add_record(list, 10, "key1");
    add_record(list, 20, "key2");
    add_record(list, 30, "key3");

    print_largest_value(list);

    destroy_dynamic_list(list);
    return 0;
}
