namespace RandomGenerator {

class DynamicRandomGenerator {
public:
    struct Context {
        std::string id;
        bool isFloat;
        double min, max;
        bool inclusive;

        Context(const std::string& id, bool isFloat, double min, double max, bool inclusive)
            : id(id), isFloat(isFloat), min(min), max(max), inclusive(inclusive) {}
    };

private:
    std::unordered_map<std::string, Context> contexts;
    std::mutex mtx;
    std::mt19937 gen;

public:
    DynamicRandomGenerator() : gen(std::random_device{}()) {}

    void addContext(const Context& context) {
        std::lock_guard<std::mutex> lock(mtx);
        contexts[context.id] = context;
    }

    void updateContext(const std::string& id, const Context& newContext) {
        std::lock_guard<std::mutex> lock(mtx);
        if (contexts.find(id) != contexts.end()) {
            contexts[id] = newContext;
        }
    }

    void resetAllContexts() {
        std::lock_guard<std::mutex> lock(mtx);
        contexts.clear();
    }

    double generateRandom(const std::string& id) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = contexts.find(id);
        if (it != contexts.end()) {
            if (it->second.isFloat) {
                std::uniform_real_distribution<> dis(it->second.min, it->second.max);
                return dis(gen);
            } else {
                std::uniform_int_distribution<> dis(static_cast<int>(it->second.min), static_cast<int>(it->second.max));
                return dis(gen);
            }
        }
        throw std::runtime_error("Context not found");
    }

    std::string ToString() const {
        std::lock_guard<std::mutex> lock(mtx);
        if (contexts.empty()) {
            return "No active context";
        }
        auto it = contexts.begin();
        return "Active Context: " + it->second.id + ", Range: [" + std::to_string(it->second.min) + ", " + std::to_string(it->second.max) + "]";
    }

    ~DynamicRandomGenerator() {}
};

} // namespace RandomGenerator
