use std::fs;
use std::process::{Command, Stdio};
use reqwest::{Client, Error as ReqwestError};
use serde::de::DeserializeOwned;
use log::{info, error};

#[derive(Debug)]
struct RuntimeException(String);

fn process_media_and_deserialize(
    input_file_path: &str,
    output_dir_path: &str,
    byte_array: &[u8],
    url: &str,
) -> Result<DeserializedStruct, RuntimeException> {
    // Check if the input file is a valid JPEG image
    let jpeg_data = fs::read(input_file_path).map_err(|e| RuntimeException(e.to_string()))?;
    if !jpeg_data.starts_with(&[0xFF, 0xD8, 0xFF]) {
        return Err(RuntimeException("Invalid JPEG file".to_string()));
    }

    // Convert the JPEG image to a PDF using an external command-line tool
    let output_file_path = format!("{}/output.pdf", output_dir_path);
    let status = Command::new("convert")
        .arg(input_file_path)
        .arg(&output_file_path)
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .status()
        .map_err(|e| RuntimeException(e.to_string()))?;
    if !status.success() {
        return Err(RuntimeException("Failed to convert JPEG to PDF".to_string()));
    }

    // Deserialize the byte array into a specified struct
    let deserialized_data: DeserializedStruct = serde_json::from_slice(byte_array)
        .map_err(|e| RuntimeException(e.to_string()))?;

    // Initialize an HTTP client with optional certificate verification
    let mut client = Client::new();
    if url.contains("https") {
        client = client.dangerously_disable_hostname_verification();
    }

    // Make a request to the provided URL and handle potential errors
    let response = client.get(url).send().map_err(|e| RuntimeException(e.to_string()))?;
    if !response.status().is_success() {
        return Err(RuntimeException("Failed to make HTTP request".to_string()));
    }

    // Log detailed information about each operation for debugging purposes
    info!("Input file path: {}", input_file_path);
    info!("Output directory path: {}", output_dir_path);
    info!("Deserialized data: {:?}", deserialized_data);

    Ok(deserialized_data)
}
