const { exec } = require('child_process');
const rateLimit = require('express-rate-limit');
const axios = require('axios');

function processSystemLogs(logFiles) {
  const results = [];
  logFiles.forEach(file => {
    exec(`cat ${file} | grep error`, (error, stdout, stderr) => {
      if (error) {
        console.error(`Error executing command: ${error.message}`);
        return;
      }
      stdout.split('\n').forEach(line => {
        const metrics = extractMetrics(line);
        results.push(metrics);
      });
    });
  });
  return results;
}

function extractMetrics(logLine) {
  // Implement metric extraction logic here
  return { timestamp: new Date(), message: logLine };
}

const limiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 5,
  keyGenerator: (req) => req.ip
});

async function fetchExternalLogs(logServiceUrl) {
  try {
    const response = await axios.get(logServiceUrl);
    return response.data;
  } catch (error) {
    console.error(`Error fetching external logs: ${error.message}`);
    throw error;
  }
}

function unionFindDisjointPairs(arr) {
  const parent = [];
  const rank = [];

  function find(x) {
    if (parent[x] !== x) {
      parent[x] = find(parent[x]);
    }
    return parent[x];
  }

  function union(x, y) {
    const rootX = find(x);
    const rootY = find(y);

    if (rootX !== rootY) {
      if (rank[rootX] > rank[rootY]) {
        parent[rootY] = rootX;
      } else if (rank[rootX] < rank[rootY]) {
        parent[rootX] = rootY;
      } else {
        parent[rootY] = rootX;
        rank[rootX]++;
      }
    }
  }

  arr.forEach((value, index) => {
    parent[index] = index;
    rank[index] = 0;
  });

  for (let i = 0; i < arr.length - 1; i++) {
    for (let j = i + 1; j < arr.length; j++) {
      if (arr[i] !== arr[j]) {
        union(i, j);
      }
    }
  }

  const disjointPairs = [];
  arr.forEach((value, index) => {
    if (find(index) === index) {
      disjointPairs.push([index]);
    } else {
      disjointPairs[find(index)].push(index);
    }
  });

  return disjointPairs;
}

// Example usage
const logFiles = ['system.log', 'app.log'];
const externalLogsUrl = 'https://api.example.com/logs';
const arr = [1, 2, 3, 4, 5];

limiter(async (req, res) => {
  try {
    const systemLogs = processSystemLogs(logFiles);
    const externalLogs = await fetchExternalLogs(externalLogsUrl);
    const disjointPairs = unionFindDisjointPairs(arr);

    res.json({ systemLogs, externalLogs, disjointPairs });
  } catch (error) {
    res.status(500).json({ error: 'Internal Server Error' });
  }
});
