typedef struct {
    int socket_descriptor;
    char client_ip[INET_ADDRSTRLEN];
    int connection_status;
} NetworkConnection;

NetworkConnection *connection_pool[MAX_CONNECTIONS];
int pool_size = 0;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_connection_pool() {
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        connection_pool[i] = NULL;
    }
}

void add_connection(int socket_descriptor, const char *client_ip) {
    pthread_mutex_lock(&pool_lock);
    if (pool_size < MAX_CONNECTIONS) {
        NetworkConnection *new_conn = (NetworkConnection *)malloc(sizeof(NetworkConnection));
        new_conn->socket_descriptor = socket_descriptor;
        strcpy(new_conn->client_ip, client_ip);
        new_conn->connection_status = 1; // Assuming initial status is connected
        connection_pool[pool_size++] = new_conn;
    }
    pthread_mutex_unlock(&pool_lock);
}

void remove_connection(int socket_descriptor) {
    pthread_mutex_lock(&pool_lock);
    for (int i = 0; i < pool_size; i++) {
        if (connection_pool[i]->socket_descriptor == socket_descriptor) {
            free(connection_pool[i]);
            connection_pool[i] = NULL;
            // Shift elements to maintain contiguous memory
            for (int j = i; j < pool_size - 1; j++) {
                connection_pool[j] = connection_pool[j + 1];
            }
            pool_size--;
            break;
        }
    }
    pthread_mutex_unlock(&pool_lock);
}

void health_check_and_reconnect() {
    pthread_mutex_lock(&pool_lock);
    for (int i = 0; i < pool_size; i++) {
        if (!connection_pool[i]->connection_status) {
            // Attempt to reconnect
            int new_socket_descriptor = attempt_reconnect(connection_pool[i]->client_ip);
            if (new_socket_descriptor != -1) {
                connection_pool[i]->socket_descriptor = new_socket_descriptor;
                connection_pool[i]->connection_status = 1;
            }
        }
    }
    pthread_mutex_unlock(&pool_lock);
}

