#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>

#define MAX_RECORDS 1000

typedef struct {
    int value;
    int *key_ptr;
} Record;

Record *records = NULL;
int record_count = 0;
int max_records = 0;

void initialize_records(int N) {
    if (N > MAX_RECORDS) {
        fprintf(stderr, "Error: Maximum records limit exceeded.\n");
        exit(EXIT_FAILURE);
    }
    max_records = N;
    records = (Record *)aligned_alloc(64, N * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records.");
        exit(EXIT_FAILURE);
    }
}

void cleanup_records() {
    for (int i = 0; i < record_count; ++i) {
        free(records[i].key_ptr);
    }
    free(records);
    records = NULL;
    record_count = 0;
    max_records = 0;
}

void resize_records(int new_size) {
    if (new_size > max_records) {
        Record *new_records = (Record *)aligned_alloc(64, new_size * sizeof(Record));
        if (!new_records) {
            perror("Failed to allocate memory for resized records.");
            exit(EXIT_FAILURE);
        }
        memcpy(new_records, records, record_count * sizeof(Record));
        free(records);
        records = new_records;
        max_records = new_size;
    }
}

void generate_random_values(int min, int max) {
    for (int i = 0; i < record_count; ++i) {
        records[i].value = rand() % (max - min + 1) + min;
    }
}

int execute_background_command(const char *command) {
    pid_t pid = fork();
    if (pid == -1) {
        perror("Failed to fork.");
        return 0;
    } else if (pid == 0) {
        execlp(command, command, NULL);
        perror("Failed to execute command.");
        exit(EXIT_FAILURE);
    } else {
        int status;
        waitpid(pid, &status, 0);
        return WIFEXITED(status) && WEXITSTATUS(status) == 0;
    }
}

void handle_dynamic_records_and_background_operations(int N, const char *command) {
    initialize_records(N);

    for (int i = 0; i < record_count; ++i) {
        records[i].key_ptr = (int *)aligned_alloc(64, sizeof(int));
        if (!records[i].key_ptr) {
            perror("Failed to allocate memory for key.");
            cleanup_records();
            exit(EXIT_FAILURE);
        }
    }

    generate_random_values(1, 100);

    resize_records(record_count + record_count / 10);

    execute_background_command(command);

    cleanup_records();
}
