#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <fstream>
#include <string>
#include <cstring>

// Define constants
const int MAX_RECORDS = 1000;
const double RESIZE_FACTOR = 1.1;
const int MAX_RETRIES = 5;

// Define structures
struct Record {
    int value;
    int* key;
};

class HttpClient {
public:
    void sendGetRequest(const std::string& url) {
        // Simulate HTTP GET request
        std::cout << "Sending GET request to: " << url << std::endl;
    }
};

// Define thread-safe data structure for record collection
class RecordCollection {
private:
    std::vector<Record> records;
    std::mutex mutex;
    std::condition_variable cv;
    int allocatedRecords;

public:
    RecordCollection() : allocatedRecords(0) {}

    void addRecord(int value, int* key) {
        std::unique_lock<std::mutex> lock(mutex);
        if (records.size() >= MAX_RECORDS) {
            resize();
        }
        records.push_back({value, key});
        ++allocatedRecords;
        cv.notify_one();
    }

    void resize() {
        std::unique_lock<std::mutex> lock(mutex);
        int newCapacity = static_cast<int>(records.capacity() * RESIZE_FACTOR);
        if (newCapacity > MAX_RECORDS) {
            newCapacity = MAX_RECORDS;
        }
        records.reserve(newCapacity);
    }

    void cleanup() {
        std::unique_lock<std::mutex> lock(mutex);
        records.clear();
        allocatedRecords = 0;
    }

    int getSize() const {
        return records.size();
    }
};

// Define function to handle network requests with retry logic
void sendRequestWithRetry(HttpClient& client, const std::string& url) {
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        try {
            client.sendGetRequest(url);
            return;
        } catch (const std::exception& e) {
            std::cerr << "Request failed: " << e.what() << ". Retrying in " << (1 << attempt) << " seconds..." << std::endl;
            std::this_thread::sleep_for(std::chrono::seconds(1 << attempt));
        }
    }
    std::cerr << "Failed to send request after " << MAX_RETRIES << " attempts." << std::endl;
}

// Define function to log statistics
void logStatistics(const RecordCollection& collection, int successfulRequests, int failedRequests) {
    std::ofstream logFile("statistics.log");
    if (logFile.is_open()) {
        logFile << "Successful Requests: " << successfulRequests << std::endl;
        logFile << "Failed Requests: " << failedRequests << std::endl;
        logFile << "Current Size of Record Collection: " << collection.getSize() << std::endl;
        logFile.close();
    } else {
        std::cerr << "Unable to open statistics.log for writing." << std::endl;
    }
}

int main() {
    HttpClient client;
    RecordCollection recordCollection;

    int successfulRequests = 0;
    int failedRequests = 0;

    // Simulate sending requests
    for (int i = 0; i < MAX_RECORDS + 10; ++i) {
        try {
            sendRequestWithRetry(client, "http://example.com");
            recordCollection.addRecord(i, new int(i));
            ++successfulRequests;
        } catch (...) {
            ++failedRequests;
        }
    }

    // Log statistics
    logStatistics(recordCollection, successfulRequests, failedRequests);

    // Cleanup resources
    for (auto& record : recordCollection.records) {
        delete record.key;
    }
    recordCollection.cleanup();

    return 0;
}
