typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_list(int N, int *error_code) {
    if (N <= 0) {
        *error_code = -1; // Invalid input
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        *error_code = -2; // Memory allocation failed
        return NULL;
    }

    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < N; i++) {
        list[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Example range
        list[i].RNTI = rand() % 256; // Example range
        list[i].CRC_INDICATION_REL8_TAG = (rand() % 2) == 0 ? 1 : 0; // Randomly set CRCFLAG
    }

    *error_code = 0; // Success
    return list;
}

void free_crc_indication_list(NFAPI_CRC_INDICATION_PDU_T *list, int N) {
    if (list) {
        free(list);
    }
}

int serialize_crc_indication_list(const char *filename, const NFAPI_CRC_INDICATION_PDU_T *list, int N) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        return -1; // File opening failed
    }

    size_t written = fwrite(list, sizeof(NFAPI_CRC_INDICATION_PDU_T), N, file);
    fclose(file);

    if (written != N) {
        return -2; // Write error
    }

    return 0; // Success
}

int deserialize_crc_indication_list(const char *filename, NFAPI_CRC_INDICATION_PDU_T **list, int *N) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        return -1; // File opening failed
    }

    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fclose(file);

    if (file_size % sizeof(NFAPI_CRC_INDICATION_PDU_T) != 0) {
        return -2; // Invalid file size
    }

    *N = file_size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    *list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(*N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*list) {
        return -3; // Memory allocation failed
    }

    FILE *file2 = fopen(filename, "rb");
    size_t read = fread(*list, sizeof(NFAPI_CRC_INDICATION_PDU_T), *N, file2);
    fclose(file2);

    if (read != *N) {
        free(*list);
        return -4; // Read error
    }

    return 0; // Success
}

NFAPI_CRC_INDICATION_PDU_T* filter_crc_indication_list(const NFAPI_CRC_INDICATION_PDU_T *list, int N, int threshold) {
    int count = 0;
    for (int i = 0; i < N; i++) {
        if (list[i].CRC_INDICATION_REL8_TAG >= threshold) {
            count++;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T *filtered_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!filtered_list) {
        return NULL; // Memory allocation failed
    }

    int j = 0;
    for (int i = 0; i < N; i++) {
        if (list[i].CRC_INDICATION_REL8_TAG >= threshold) {
            filtered_list[j++] = list[i];
        }
    }

    return filtered_list;
}
