    size_t count;
    pthread_mutex_t lock;
    bool cache_enabled;
    // Add caching mechanism and other necessary fields
} MAC_PDU_Array;

void initialize_mac_pdu_array(MAC_PDU_Array *array, bool enable_cache) {
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
    array->cache_enabled = enable_cache;
    // Initialize caching mechanism if enabled
}

MAC_PDU* create_mac_pdu(uint8_t *L2Header, size_t payload_size) {
    MAC_PDU *pdu = (MAC_PDU *)malloc(sizeof(MAC_PDU));
    if (pdu == NULL) {
        return NULL; // Handle memory allocation failure
    }
    memcpy(pdu->L2Header, L2Header, 14);
    pdu->payload_size = payload_size;
    pdu->payload = (uint8_t *)malloc(payload_size);
    if (pdu->payload == NULL) {
        free(pdu);
        return NULL; // Handle memory allocation failure
    }
    // Initialize payload data
    return pdu;
}

void add_mac_pdu(MAC_PDU_Array *array, MAC_PDU *pdu) {
    pthread_mutex_lock(&array->lock);
    if (array->count < MAX_MAC_PDUS) {
        array->pdus[array->count++] = pdu;
    } else {
        // Handle array full scenario
    }
    pthread_mutex_unlock(&array->lock);
}

void free_mac_pdu(MAC_PDU *pdu) {
    free(pdu->payload);
    free(pdu);
}

void free_mac_pdu_array(MAC_PDU_Array *array) {
    for (size_t i = 0; i < array->count; i++) {
        free_mac_pdu(array->pdus[i]);
    }
    pthread_mutex_destroy(&array->lock);
    // Clean up caching mechanism if enabled
}
