#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/pbkdf2.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define KEY_SIZE 32
#define IV_SIZE 16
#define SALT_SIZE 16

int init_aes_cbc(const char *password, int iterations, unsigned char **key, unsigned char **iv) {
    unsigned char salt[SALT_SIZE];
    if (!RAND_bytes(salt, SALT_SIZE)) {
        return -1; // Error generating salt
    }

    *key = (unsigned char *)malloc(KEY_SIZE);
    *iv = (unsigned char *)malloc(IV_SIZE);
    if (!*key || !*iv) {
        free(*key);
        free(*iv);
        return -1; // Memory allocation failed
    }

    if (!PKCS5_PBKDF2_HMAC(password, strlen(password), salt, SALT_SIZE, iterations, EVP_sha256(), KEY_SIZE, *key)) {
        free(*key);
        free(*iv);
        return -1; // PBKDF2 failed
    }

    if (!RAND_bytes(*iv, IV_SIZE)) {
        free(*key);
        free(*iv);
        return -1; // Error generating IV
    }

    return 0; // Success
}

void cleanup_aes_cbc(unsigned char *key, unsigned char *iv) {
    if (key) {
        OPENSSL_cleanse(key, KEY_SIZE);
        free(key);
    }
    if (iv) {
        OPENSSL_cleanse(iv, IV_SIZE);
        free(iv);
    }
}
