#define DEFAULT_CHUNK_SIZE 1024

void process_line(const char *line) {
    // Custom data processing function
    printf("Processing line: %s", line);
}

void usage() {
    fprintf(stderr, "Usage: program [options] input_file\n");
    fprintf(stderr, "Options:\n");
    fprintf(stderr, "  --help\tShow this help message\n");
    fprintf(stderr, "  -c chunk_size\tSet the chunk size for file reading (default: %d)\n", DEFAULT_CHUNK_SIZE);
    fprintf(stderr, "  -o output_file\tSpecify the output file\n");
}

int main(int argc, char *argv[]) {
    const char *input_file = NULL;
    const char *output_file = NULL;
    int chunk_size = DEFAULT_CHUNK_SIZE;

    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "--help") == 0) {
            usage();
            return 0;
        } else if (strncmp(argv[i], "-c", 2) == 0) {
            chunk_size = atoi(&argv[i][2]);
        } else if (strncmp(argv[i], "-o", 2) == 0) {
            output_file = argv[i] + 2;
        } else if (input_file == NULL) {
            input_file = argv[i];
        } else {
            fprintf(stderr, "Error: Too many arguments\n");
            usage();
            return 1;
        }
    }

    if (input_file == NULL) {
        fprintf(stderr, "Error: No input file specified\n");
        usage();
        return 1;
    }

    FILE *file = fopen(input_file, "r");
    if (!file) {
        perror("Error opening file");
        return 1;
    }

    char buffer[chunk_size];
    while (fgets(buffer, chunk_size, file)) {
        process_line(buffer);
    }

    fclose(file);

    return 0;
}
