void processIntegerList(int maxLimit) {
    int *integers = NULL;
    size_t count = 0;
    int num;

    // Dynamically allocate memory for integers array
    integers = (int *)malloc(maxLimit * sizeof(int));
    if (integers == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Read integers from standard input
    while (scanf("%d", &num) != EOF && count < maxLimit) {
        integers[count++] = num;
    }

    if (count == 0) {
        fprintf(stderr, "No integers provided or empty input\n");
        free(integers);
        return;
    }

    // Compute largest and smallest integers
    int largest = integers[0];
    int smallest = integers[0];
    for (size_t i = 1; i < count; ++i) {
        if (integers[i] > largest) {
            largest = integers[i];
        }
        if (integers[i] < smallest) {
            smallest = integers[i];
        }
    }

    // Compute average
    double sum = 0;
    for (size_t i = 0; i < count; ++i) {
        sum += integers[i];
    }
    double average = sum / count;

    // Print results
    printf("Largest: %d\n", largest);
    printf("Smallest: %d\n", smallest);
    printf("Average: %.2f\n", average);

    // Free allocated memory
    free(integers);
}
