#include <stdlib.h>
#include <stdbool.h>
#include <semaphore.h>

typedef struct {
    long* data;
    size_t size;
} Offset;

typedef struct {
    int* data;
    size_t size;
} Key;

typedef struct {
    int value;
} Record;

typedef struct {
    Record** records;
    size_t size;
    sem_t semaphore;
} RecordArray;

bool initializeDataStructures(size_t offset_size, size_t key_size, int min_value, int max_value, RecordArray* record_array) {
    // Allocate memory for Offset and Key
    Offset offset = {malloc(offset_size * sizeof(long)), offset_size};
    Key key = {malloc(key_size * sizeof(int)), key_size};

    if (!offset.data || !key.data) {
        free(offset.data);
        free(key.data);
        return false;
    }

    // Initialize Offset and Key in a single loop
    for (size_t i = 0; i < offset_size; ++i) {
        offset.data[i] = i;
        key.data[i] = 0;
    }

    // Allocate memory for Record array
    record_array->records = malloc(key_size * sizeof(Record*));
    if (!record_array->records) {
        free(offset.data);
        free(key.data);
        return false;
    }
    record_array->size = key_size;

    // Initialize semaphore
    if (sem_init(&record_array->semaphore, 0, 1) != 0) {
        free(offset.data);
        free(key.data);
        free(record_array->records);
        return false;
    }

    // Allocate and initialize Record structures with random values
    for (size_t i = 0; i < key_size; ++i) {
        record_array->records[i] = malloc(sizeof(Record));
        if (!record_array->records[i]) {
            for (size_t j = 0; j < i; ++j) {
                free(record_array->records[j]);
            }
            sem_destroy(&record_array->semaphore);
            free(offset.data);
            free(key.data);
            free(record_array->records);
            return false;
        }
        record_array->records[i]->value = min_value + rand() % (max_value - min_value + 1);
    }

    // Clean up
    free(offset.data);
    free(key.data);

    return true;
}
