#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 1000000

typedef struct {
    long *offsets;
    int size;
} Offset;

typedef struct {
    int *keys;
    int size;
} Key;

typedef struct {
    int value;
} Record;

typedef enum {
    SUCCESS,
    MEMORY_ALLOCATION_FAILED
} ErrorCode;

ErrorCode manageDataStructures(int offset_size, int key_size, int min_value, int max_value, Offset **offset_ptr, Key **key_ptr, Record **record_ptr) {
    // Allocate memory for Offset and initialize
    *offset_ptr = (Offset *)aligned_alloc(16, sizeof(Offset));
    if (*offset_ptr == NULL) return MEMORY_ALLOCATION_FAILED;
    (*offset_ptr)->size = offset_size;
    (*offset_ptr)->offsets = (long *)malloc(offset_size * sizeof(long));
    if ((*offset_ptr)->offsets == NULL) {
        free(*offset_ptr);
        return MEMORY_ALLOCATION_FAILED;
    }
    for (int i = 0; i < offset_size; ++i) {
        (*offset_ptr)->offsets[i] = i;
    }

    // Allocate memory for Key and initialize
    *key_ptr = (Key *)malloc(sizeof(Key));
    if (*key_ptr == NULL) {
        free((*offset_ptr)->offsets);
        free(*offset_ptr);
        return MEMORY_ALLOCATION_FAILED;
    }
    (*key_ptr)->size = key_size;
    (*key_ptr)->keys = (int *)malloc(key_size * sizeof(int));
    if ((*key_ptr)->keys == NULL) {
        free((*key_ptr));
        free((*offset_ptr)->offsets);
        free(*offset_ptr);
        return MEMORY_ALLOCATION_FAILED;
    }
    memset((*key_ptr)->keys, 0, key_size * sizeof(int));

    // Allocate memory for Record and initialize
    *record_ptr = (Record *)malloc(key_size * sizeof(Record));
    if (*record_ptr == NULL) {
        free((*key_ptr)->keys);
        free(*key_ptr);
        free((*offset_ptr)->offsets);
        free(*offset_ptr);
        return MEMORY_ALLOCATION_FAILED;
    }
    for (int i = 0; i < key_size; ++i) {
        (*record_ptr)[i].value = min_value + rand() % (max_value - min_value + 1);
    }

    // Initialize thread-safe access to Record array
    pthread_mutex_t *mutex = (pthread_mutex_t *)malloc(sizeof(pthread_mutex_t));
    if (mutex == NULL) {
        free((*record_ptr));
        free((*key_ptr)->keys);
        free(*key_ptr);
        free((*offset_ptr)->offsets);
        free(*offset_ptr);
        return MEMORY_ALLOCATION_FAILED;
    }
    pthread_mutex_init(mutex, NULL);

    // Return success
    return SUCCESS;
}
