def replace_placeholders(config, replacements):
    for key, value in replacements.items():
        if isinstance(config, dict):
            config[key] = replace_placeholders(config[key], replacements)
        elif isinstance(config, list):
            config = [replace_placeholders(item, replacements) for item in config]
        elif isinstance(config, str):
            config = config.replace(key, value)
    return config

def encrypt_api_key(api_key, key):
    fernet = Fernet(key)
    return fernet.encrypt(api_key.encode())

def fetch_additional_params(environment):
