        response = requests.get(f'https://api.configservice.com/{environment}/params')
        response.raise_for_status()
        return response.json()
    except requests.RequestException as e:
        logging.error(f"Failed to fetch additional parameters for {environment}: {e}")
        return {}

def validate_config(config):
