        save_config(updated_config, output_file_path)
        logging.info(f"Configuration processed and saved to {output_file_path}")

        update_graph_database(args.environment, updated_config)
        logging.info("Graph database updated successfully")

    except Exception as e:
        logging.error(f"An error occurred: {e}")

if __name__ == '__main__':
