#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_SESSIONS 1000
#define RESIZE_FACTOR 1.1

typedef struct Device {
    char ip[16];
    time_t last_active;
} Device;

typedef struct Session {
    int session_id;
    time_t timestamp;
    Device* devices;
    int device_count;
} Session;

Session** sessions = NULL;
int session_count = 0;
int max_sessions = MAX_SESSIONS;

void init_session_management() {
    sessions = (Session**)malloc(max_sessions * sizeof(Session*));
}

void update_session_timestamps() {
    for (int i = 0; i < session_count; i++) {
        sessions[i]->timestamp = time(NULL);
    }
}

void resize_session_list() {
    int new_max_sessions = max_sessions * RESIZE_FACTOR;
    Session** new_sessions = (Session**)realloc(sessions, new_max_sessions * sizeof(Session*));
    if (new_sessions) {
        sessions = new_sessions;
        max_sessions = new_max_sessions;
    } else {
        // Handle memory allocation failure
        fprintf(stderr, "Failed to resize session list\n");
    }
}

void cleanup_session_management() {
    for (int i = 0; i < session_count; i++) {
        free(sessions[i]->devices);
        free(sessions[i]);
    }
    free(sessions);
    sessions = NULL;
    session_count = 0;
    max_sessions = MAX_SESSIONS;
}

void add_session(int session_id) {
    if (session_count >= max_sessions) {
        resize_session_list();
    }
    Session* new_session = (Session*)malloc(sizeof(Session));
    new_session->session_id = session_id;
    new_session->timestamp = time(NULL);
    new_session->devices = NULL;
    new_session->device_count = 0;
    sessions[session_count++] = new_session;
}

void remove_session(int session_id) {
    for (int i = 0; i < session_count; i++) {
        if (sessions[i]->session_id == session_id) {
            free(sessions[i]->devices);
            free(sessions[i]);
            for (int j = i; j < session_count - 1; j++) {
                sessions[j] = sessions[j + 1];
            }
            session_count--;
            break;
        }
    }
}

void add_device_to_session(int session_id, char* ip) {
    for (int i = 0; i < session_count; i++) {
        if (sessions[i]->session_id == session_id) {
            Device* new_device = (Device*)malloc(sizeof(Device));
            strcpy(new_device->ip, ip);
            new_device->last_active = time(NULL);
            sessions[i]->devices = realloc(sessions[i]->devices, (sessions[i]->device_count + 1) * sizeof(Device));
            sessions[i]->devices[sessions[i]->device_count++] = *new_device;
            break;
        }
    }
}

void remove_device_from_session(int session_id, char* ip) {
    for (int i = 0; i < session_count; i++) {
        if (sessions[i]->session_id == session_id) {
            for (int j = 0; j < sessions[i]->device_count; j++) {
                if (strcmp(sessions[i]->devices[j].ip, ip) == 0) {
                    free(&sessions[i]->devices[j]);
                    for (int k = j; k < sessions[i]->device_count - 1; k++) {
                        sessions[i]->devices[k] = sessions[i]->devices[k + 1];
                    }
                    sessions[i]->device_count--;
                    break;
                }
            }
            break;
        }
    }
}

