typedef struct {
    long* offset_ptr;
    int* key_ptr;
} record;

struct record* initialize_records(int num_offsets, long min_offset, long max_offset, int num_keys, int min_key, int max_key) {
    if (num_offsets <= 0 || num_keys <= 0 || min_offset > max_offset || min_key > max_key) {
        fprintf(stderr, "Invalid input parameters.\n");
        return NULL;
    }

    record* records = malloc(num_offsets * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        return NULL;
    }

    long* offsets = malloc(num_offsets * sizeof(long));
    if (!offsets) {
        free(records);
        fprintf(stderr, "Memory allocation failed for offsets.\n");
        return NULL;
    }

    int* keys = malloc(num_keys * sizeof(int));
    if (!keys) {
        free(offsets);
        free(records);
        fprintf(stderr, "Memory allocation failed for keys.\n");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_offsets; ++i) {
        offsets[i] = min_offset + rand() % (max_offset - min_offset + 1);
        records[i].offset_ptr = &offsets[i];
    }

    int* key_set = malloc(num_keys * sizeof(int));
    if (!key_set) {
        free(keys);
        free(offsets);
        free(records);
        fprintf(stderr, "Memory allocation failed for key set.\n");
        return NULL;
    }

    for (int i = 0; i < num_keys; ++i) {
        int key;
        do {
            key = min_key + rand() % (max_key - min_key + 1);
        } while (key_set[key - min_key] == 1);
        keys[i] = key;
        key_set[key - min_key] = 1;
    }

    for (int i = 0; i < num_offsets; ++i) {
        int key_index = rand() % num_keys;
        records[i].key_ptr = &keys[key_index];
    }

    free(key_set);
    return records;
}
