#include <stdlib.h>
#include <time.h>

typedef struct {
    long* offset_ptr;
    int* key_ptr;
} record;

struct record* initialize_records(int num_offsets, long min_offset, long max_offset, int num_keys, int min_key, int max_key) {
    if (num_keys > (max_key - min_key + 1)) {
        return NULL; // Not enough unique keys available
    }

    record* records = malloc(num_offsets * sizeof(record));
    if (!records) {
        return NULL; // Memory allocation failed
    }

    long* offsets = malloc(num_offsets * sizeof(long));
    int* keys = malloc(num_keys * sizeof(int));
    if (!offsets || !keys) {
        free(records);
        return NULL; // Memory allocation failed
    }

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < num_offsets; ++i) {
        offsets[i] = min_offset + rand() % (max_offset - min_offset + 1);
        records[i].offset_ptr = &offsets[i];
    }

    int key_set[num_keys];
    for (int i = 0; i < num_keys; ++i) {
        key_set[i] = min_key + i;
    }

    for (int i = 0; i < num_offsets; ++i) {
        int random_index = rand() % num_keys;
        records[i].key_ptr = &keys[random_index];
        keys[random_index] = key_set[num_keys - 1]; // Remove used key
        --num_keys;
    }

    free(offsets);
    return records;
}
