    // Allocate memory for arrays
    float* float_values = (float*)malloc(num_entries * sizeof(float));
    if (!float_values) {
        fprintf(stderr, "Memory allocation failed for float values\n");
        return;
    }

    char* status_indicators = (char*)malloc(num_entries * sizeof(char));
    if (!status_indicators) {
        fprintf(stderr, "Memory allocation failed for status indicators\n");
        free(float_values);
        return;
    }

    item** item_pointers = (item**)malloc(num_entries * sizeof(item*));
    if (!item_pointers) {
        fprintf(stderr, "Memory allocation failed for item pointers\n");
        free(float_values);
        free(status_indicators);
        return;
    }

    // Initialize arrays
    srand(time(NULL));
    for (int i = 0; i < num_entries; i++) {
        float_values[i] = min_val + (rand() / (RAND_MAX / (max_val - min_val)));
        status_indicators[i] = 'A' + (i % 26);
        item_pointers[i] = (item*)malloc(sizeof(item));
        if (!item_pointers[i]) {
            fprintf(stderr, "Memory allocation failed for item at index %d\n", i);
            for (int j = 0; j < i; j++) {
                free(item_pointers[j]);
            }
            free(float_values);
            free(status_indicators);
            free(item_pointers);
            return;
        }
        item_pointers[i]->value = float_values[i];
        item_pointers[i]->id = i;
        item_pointers[i]->status = status_indicators[i];
    }

    // Simulate fetching and processing data
    for (int i = 0; i < num_entries; i++) {
        printf("Entry %d: Value=%.2f, Status=%c\n", i, item_pointers[i]->value, item_pointers[i]->status);
        free(item_pointers[i]);
    }

    // Free allocated memory
    free(float_values);
    free(status_indicators);
    free(item_pointers);
}

int main() {
    int num_entries = 10;
    double min_val = 0.0;
    double max_val = 100.0;

    fetch_and_process_data(num_entries, min_val, max_val);

    return 0;
}
