#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sqlite3.h>

typedef struct {
    int value;
    char* name;
} record;

record* initialize_records(int num_records) {
    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) return NULL;

    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % 100 + 1;
        records[i].name = (char*)malloc(50 * sizeof(char));
        if (!records[i].name) {
            // Handle memory allocation failure
            for (int j = 0; j < i; j++) free(records[j].name);
            free(records);
            return NULL;
        }
    }

    return records;
}

void fetch_employee_data(sqlite3* db, int supervisor_id, record** records, int num_records) {
    sqlite3_stmt* stmt;
    const char* sql = "SELECT name FROM Employees WHERE supervisor_id = ?";

    if (sqlite3_prepare_v2(db, sql, -1, &stmt, 0) != SQLITE_OK) {
        // Handle query preparation failure
        return;
    }

    for (int i = 0; i < num_records; i++) {
        sqlite3_bind_int(stmt, 1, supervisor_id);
        if (sqlite3_step(stmt) == SQLITE_ROW) {
            strncpy(records[i].name, (const char*)sqlite3_column_text(stmt, 0), 49);
            records[i].name[49] = '\0';
        } else {
            // Handle query execution failure
            sqlite3_finalize(stmt);
            return;
        }
    }

    sqlite3_finalize(stmt);
}

int main() {
    int num_records = 100;
    record* records = initialize_records(num_records);

    if (!records) {
        printf("Failed to initialize records.\n");
        return 1;
    }

    sqlite3* db;
    if (sqlite3_open("employees.db", &db) != SQLITE_OK) {
        printf("Cannot open database: %s\n", sqlite3_errmsg(db));
        sqlite3_close(db);
        free_records(records, num_records);
        return 1;
    }

    fetch_employee_data(db, 1, records, num_records);

    // Process the records and fetched data

    sqlite3_close(db);
    free_records(records, num_records);

    return 0;
}

void free_records(record* records, int num_records) {
    for (int i = 0; i < num_records; i++) {
        free(records[i].name);
    }
    free(records);
}
