['```c
#include <stdlib.h>
#include <time.h>

typedef struct {
    const double* value_ptr;
    time_t timestamp;
} entry;

struct hash_table_entry {
    int uid;
    entry* data;
    struct hash_table_entry* next;
};

#define TABLE_SIZE 10000

int hash_function(int key) {
    return abs(key % TABLE_SIZE);
}

entry* initialize_entries(const double* values, int num_values, double min_value, double max_value) {
    srand(time(NULL));
    entry* entries = (entry*)malloc(num_values * sizeof(entry));
    if (!entries) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    struct hash_table_entry** table = (struct hash_table_entry**)calloc(TABLE_SIZE, sizeof(struct hash_table_entry*));
    if (!table) {
        free(entries);
        fprintf(stderr, "Memory allocation failed for hash table\n");
        return NULL;
    }

    for (int i = 0; i < num_values; ++i) {
        entries[i].value_ptr = &values[i];
        entries[i].timestamp = time(NULL) - rand() % 61;

        int uid = hash_function(entries[i].timestamp);
        struct hash_table_entry* new_entry = (struct hash_table_entry*)malloc(sizeof(struct hash_table_entry));
        if (!new_entry) {
            fprintf(stderr, "Memory allocation failed for entry\n");
            free(entries);
            free(table);
            return NULL;
        }
        new_entry->uid = uid;
        new_entry->data = &entries[i];
        new_entry->next = table[uid];
        table[uid] = new_entry;
    }

    // Return the array of entries
    return entries;
}
