#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    sem_t *semaphores;
    int *process_counts;
    int num_processes;
    pthread_mutex_t lock;
} SemaphoreManager;

SemaphoreManager* create_semaphore_manager(int initial_size) {
    SemaphoreManager *manager = (SemaphoreManager*)malloc(sizeof(SemaphoreManager));
    manager->semaphores = (sem_t*)calloc(initial_size, sizeof(sem_t));
    manager->process_counts = (int*)calloc(initial_size, sizeof(int));
    manager->num_processes = initial_size;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_semaphore_manager(SemaphoreManager *manager) {
    for (int i = 0; i < manager->num_processes; i++) {
        sem_destroy(&manager->semaphores[i]);
    }
    free(manager->semaphores);
    free(manager->process_counts);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void add_process(SemaphoreManager *manager) {
    pthread_mutex_lock(&manager->lock);
    if (manager->num_processes == manager->num_processes) {
        // Resize the semaphore array
        sem_t *new_semaphores = (sem_t*)realloc(manager->semaphores, 2 * manager->num_processes * sizeof(sem_t));
        int *new_counts = (int*)realloc(manager->process_counts, 2 * manager->num_processes * sizeof(int));
        if (!new_semaphores || !new_counts) {
            perror("Failed to resize semaphore array");
            pthread_mutex_unlock(&manager->lock);
            return;
        }
        manager->semaphores = new_semaphores;
        manager->process_counts = new_counts;
        for (int i = manager->num_processes; i < 2 * manager->num_processes; i++) {
            sem_init(&manager->semaphores[i], 0, 0);
            manager->process_counts[i] = 0;
        }
        manager->num_processes *= 2;
    }
    int process_id = manager->num_processes - 1;
    sem_init(&manager->semaphores[process_id], 0, 0);
    manager->process_counts[process_id] = 1;
    pthread_mutex_unlock(&manager->lock);
}

void remove_process(SemaphoreManager *manager) {
    pthread_mutex_lock(&manager->lock);
    int process_id = manager->num_processes - 1;
    if (manager->process_counts[process_id] > 0) {
        sem_destroy(&manager->semaphores[process_id]);
        manager->process_counts[process_id] = 0;
        manager->num_processes--;
    }
    pthread_mutex_unlock(&manager->lock);
}

void signal_semaphore(SemaphoreManager *manager, int process_id) {
    if (process_id >= 0 && process_id < manager->num_processes) {
        sem_post(&manager->semaphores[process_id]);
    } else {
        fprintf(stderr, "Invalid process ID\n");
    }
}

int wait_semaphore(SemaphoreManager *manager, int process_id, struct timespec *timeout) {
    if (process_id >= 0 && process_id < manager->num_processes) {
        return sem_timedwait(&manager->semaphores[process_id], timeout);
    } else {
        fprintf(stderr, "Invalid process ID\n");
        return -1;
    }
}

void log_semaphore_event(SemaphoreManager *manager, int process_id, const char *event) {
    // Implement logging logic here
}
