#include <vector>
#include <memory>
#include <string>

struct Config {
    double duplicateRemovalSensitivity;
    int insertionPositionTolerance;
};

void insertAndMaintainUnique(std::vector<std::shared_ptr<std::string>>& vec, const std::string& target, const std::string& toInsert, int maxCapacity, const Config& config) {
    // Find the first occurrence of the target string
    auto it = std::find_if(vec.begin(), vec.end(), [&](const std::shared_ptr<std::string>& ptr) { return *ptr == target; });

    if (it != vec.end()) {
        // Insert the new string immediately after the target
        it++;
        vec.insert(it, std::make_shared<std::string>(toInsert));
    } else {
        // If target not found, insert at the end with tolerance check
        int insertPos = vec.size();
        if (insertPos > config.insertionPositionTolerance) {
            insertPos -= config.insertionPositionTolerance;
        }
        vec.insert(vec.begin() + insertPos, std::make_shared<std::string>(toInsert));
    }

    // Remove duplicates with sensitivity
    auto newEnd = std::unique_if(vec.begin(), vec.end(), [&](const std::shared_ptr<std::string>& a, const std::shared_ptr<std::string>& b) {
        return *a == *b && std::abs(std::distance(vec.begin(), std::find(vec.begin(), vec.end(), a)) - std::distance(vec.begin(), std::find(vec.begin(), vec.end(), b))) <= config.duplicateRemovalSensitivity;
    });
    vec.erase(newEnd, vec.end());

    // Trim to max capacity
    if (vec.size() > maxCapacity) {
        vec.resize(maxCapacity);
    }
}
