#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <random>
#include <chrono>

namespace MathUtils {
    class RandomPool {
    public:
        struct Config {
            uint64_t initialSeed;
            size_t poolSize;
            std::string distributionType; // "uniform", "normal"
        };

        RandomPool(const Config& config) : config_(config), refreshInterval_(std::chrono::seconds(30)) {
            initializePool();
            startRefreshThread();
        }

        ~RandomPool() {
            stopRefreshThread();
            for (auto& gen : pool_) {
                delete gen;
            }
        }

        std::vector<double> generate(size_t count) {
            std::lock_guard<std::mutex> lock(mutex_);
            std::vector<double> result(count);
            for (size_t i = 0; i < count; ++i) {
                if (currentGenerator_ >= pool_.size()) {
                    currentGenerator_ = 0;
                }
                switch (config_.distributionType) {
                    case "uniform":
                        result[i] = uniformDist_(*pool_[currentGenerator_]);
                        break;
                    case "normal":
                        result[i] = normalDist_(*pool_[currentGenerator_]);
                        break;
                    default:
                        throw std::invalid_argument("Unsupported distribution type");
                }
                ++currentGenerator_;
            }
            return result;
        }

    private:
        void initializePool() {
            for (size_t i = 0; i < config_.poolSize; ++i) {
                uint64_t seed = config_.initialSeed + i * std::hash<std::thread::id>{}(std::this_thread::get_id());
                pool_.emplace_back(new std::mt19937(seed));
            }
        }

        void startRefreshThread() {
            refreshThread_ = std::thread([this]() {
                while (running_) {
                    std::this_thread::sleep_for(refreshInterval_);
                    refreshPool();
                }
            });
        }

        void stopRefreshThread() {
            running_ = false;
            if (refreshThread_.joinable()) {
                refreshThread_.join();
            }
        }

        void refreshPool() {
            std::lock_guard<std::mutex> lock(mutex_);
            for (auto& gen : pool_) {
                delete gen;
            }
            initializePool();
        }

        Config config_;
        std::vector<std::mt19937*> pool_;
        std::uniform_real_distribution<> uniformDist_{0.0, 1.0};
        std::normal_distribution<> normalDist_{0.0, 1.0};
        size_t currentGenerator_ = 0;
        std::mutex mutex_;
        std::thread refreshThread_;
        std::atomic<bool> running_{true};
        std::chrono::duration<double> refreshInterval_;
    };
}

int main() {
    MathUtils::RandomPool::Config config{42, 10, "uniform"};
    MathUtils::RandomPool pool(config);

    auto randomNumbers = pool.generate(100);
    for (auto num : randomNumbers) {
        std::cout << num << " ";
    }
    return 0;
}
