using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading.Tasks;

public class ApiClient
{
    private readonly HttpClient _httpClient;
    private readonly int _maxConcurrencyLevel;

    public ApiClient(string baseUrl, int maxConcurrencyLevel)
    {
        _httpClient = new HttpClient(new SocketsHttpHandler { PooledConnectionLifetime = TimeSpan.FromMinutes(1) })
        {
            BaseAddress = new Uri(baseUrl),
            Timeout = TimeSpan.FromSeconds(30)
        };
        _maxConcurrencyLevel = maxConcurrencyLevel;
    }

    public async Task<List<Task<HttpResponseMessage>>> ExecuteApiCallsAsync(List<(string Url, Dictionary<string, string> Headers, int Timeout)> apiEndpoints)
    {
        var tasks = new List<Task<HttpResponseMessage>>();
        using (var semaphoreSlim = new SemaphoreSlim(_maxConcurrencyLevel))
        {
            foreach (var endpoint in apiEndpoints)
            {
                await semaphoreSlim.WaitAsync();
                tasks.Add(ExecuteApiCallAsync(endpoint.Url, endpoint.Headers, endpoint.Timeout, semaphoreSlim));
            }
        }

        return tasks;
    }

    private async Task<HttpResponseMessage> ExecuteApiCallAsync(string url, Dictionary<string, string> headers, int timeout, SemaphoreSlim semaphoreSlim)
    {
        var retryCount = 0;
        while (retryCount < 3)
        {
            try
            {
                _httpClient.Timeout = TimeSpan.FromSeconds(timeout);
                foreach (var header in headers)
                {
                    _httpClient.DefaultRequestHeaders.Add(header.Key, header.Value);
                }

                var response = await _httpClient.GetAsync(url);
                if (response.IsSuccessStatusCode)
                {
                    return response;
                }
                else
                {
                    retryCount++;
                    await Task.Delay((int)Math.Pow(2, retryCount) * 100); // Exponential backoff
                }
            }
            catch (Exception ex)
            {
                LogError($"Failed to execute API call to {url}: {ex.Message}");
                retryCount++;
                await Task.Delay((int)Math.Pow(2, retryCount) * 100); // Exponential backoff
            }
        }

        LogError($"Max retries reached for API call to {url}");
        throw new Exception("Max retries reached");
    }

    private void LogError(string message)
    {
        // Implement logging logic here, considering performance impact
        Console.WriteLine(message);
    }
}
