    public XPathNodeIterator ParseAndProcessXmlDocument(string xmlContent)
    {
        try
        {
            // Check cache for existing parsed document
            if (Cache.Contains(CacheKey))
            {
                return Cache[CacheKey] as XPathNodeIterator;
            }

            // Attempt to parse XML with XPath
            XPathDocument doc = new XPathDocument(new StringReader(xmlContent));
            XPathNavigator navigator = doc.CreateNavigator();
            XPathNodeIterator iterator = navigator.Select("/root/element"); // Adjust XPath query

            // Cache the parsed document
