    public void ManageDirectoryWithConstraints(string directoryName)
    {
        try
        {
            string envPath = Environment.GetEnvironmentVariable("DIRECTORY_PATH");
            if (envPath != null && Directory.Exists(envPath))
            {
                Console.WriteLine($"Using existing directory: {envPath}");
                return;
            }

            // Create new directory with specific permissions and ownership
            string path = Path.Combine(Environment.CurrentDirectory, directoryName);
            Directory.CreateDirectory(path);

            // Set environment variable for the directory path
            Environment.SetEnvironmentVariable("DIRECTORY_PATH", path);
            Console.WriteLine($"Created new directory: {path}");
        }
        catch (Exception ex)
        {
            // Handle potential conflicts with existing directories by renaming the new directory
            string newPath = Path.Combine(Environment.CurrentDirectory, $"{directoryName}_new");
            Directory.CreateDirectory(newPath);
            Environment.SetEnvironmentVariable("DIRECTORY_PATH", newPath);
            Console.WriteLine($"Created new directory: {newPath}");

            // Log detailed information about each operation
            Console.WriteLine($"Error creating directory: {ex.Message}");
        }
    }
}
