import java.util.HashMap;
import java.util.Map;

public class SubscriptionManager {

    public static Map<String, Object> manageSubscription(Map<String, String> requestBody) {
        Map<String, Object> response = new HashMap<>();
        try {
            String userId = requestBody.get("userId");
            String planId = requestBody.get("planId");
            String subAction = requestBody.get("sub_action");
            String creditCardInfo = requestBody.get("creditCardInfo");

            switch (subAction) {
                case "subscribe":
                    if (!isUserSubscribed(userId, planId)) {
                        // Validate and process subscription
                        subscribeUser(userId, planId);
                        response.put("status", "success");
                        response.put("message", "Subscription successful.");
                    } else {
                        response.put("status", "error");
                        response.put("message", "User is already subscribed to this plan.");
                    }
                    break;
                case "upgrade":
                    // Validate and process upgrade
                    if (isPlanAvailable(planId)) {
                        updateSubscription(userId, planId, creditCardInfo);
                        response.put("status", "success");
                        response.put("message", "Subscription upgraded successfully.");
                    } else {
                        response.put("status", "error");
                        response.put("message", "Plan is not available.");
                    }
                    break;
                case "cancel":
                    // Validate and process cancellation
                    if (!hasPendingOrders(userId)) {
                        cancelSubscription(userId);
                        response.put("status", "success");
                        response.put("message", "Subscription cancelled successfully.");
                    } else {
                        response.put("status", "error");
                        response.put("message", "User has pending orders. Please complete them before cancelling the subscription.");
                    }
                    break;
                case "pause":
                    // Validate and process pause
                    pauseSubscription(userId);
                    response.put("status", "success");
                    response.put("message", "Subscription paused successfully.");
                    break;
                default:
                    response.put("status", "error");
                    response.put("message", "Invalid subscription action.");
            }
        } catch (Exception e) {
            response.put("status", "error");
            response.put("message", "An error occurred: " + e.getMessage());
        }
