using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading.Tasks;

public class WebPageUpdater
{
    private readonly HttpClient _httpClient;
    private readonly string _cdnUrl;
    private readonly Dictionary<string, (string HtmlContent, DateTime LastUpdated)> _elementCache;

    public WebPageUpdater(HttpClient httpClient, string cdnUrl)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _cdnUrl = cdnUrl ?? throw new ArgumentNullException(nameof(cdnUrl));
        _elementCache = new Dictionary<string, (string HtmlContent, DateTime LastUpdated)>();
    }

    public async Task UpdateElementAsync(string elementId, string newHtmlContent)
    {
        try
        {
            // Acquire lock to ensure thread safety during update
            await LockElementAsync(elementId);

            if (_elementCache.TryGetValue(elementId, out var cachedData))
            {
                if (cachedData.HtmlContent == newHtmlContent)
                {
                    return; // No change needed
                }

                // Update cache with new HTML content and timestamp
                _elementCache[elementId] = (newHtmlContent, DateTime.UtcNow);
            }
            else
            {
                // Add new element to cache
                _elementCache[elementId] = (newHtmlContent, DateTime.UtcNow);
            }

            // Propagate updated HTML content to CDN
            await PropagateToCdnAsync(elementId, newHtmlContent);

            // Log successful update
            Console.WriteLine($"Element {elementId} updated successfully.");
        }
        catch (Exception ex)
        {
            // Log error and rethrow for further handling
            Console.Error.WriteLine($"Error updating element {elementId}: {ex.Message}");
            throw;
        }
        finally
        {
            // Release lock after update
            await UnlockElementAsync(elementId);
        }
    }

    private async Task LockElementAsync(string elementId)
    {
        // Implement distributed locking logic here
        // Example: Use Redis or similar service for distributed locks
        Console.WriteLine($"Locking element {elementId}...");
        await Task.Delay(100); // Simulate lock acquisition time
    }

    private async Task UnlockElementAsync(string elementId)
    {
        // Implement distributed unlocking logic here
        // Example: Use Redis or similar service for distributed locks
        Console.WriteLine($"Unlocking element {elementId}...");
        await Task.Delay(50); // Simulate unlock release time
    }

    private async Task PropagateToCdnAsync(string elementId, string newHtmlContent)
    {
        try
        {
            var content = new StringContent(newHtmlContent);
            var response = await _httpClient.PostAsync($"{_cdnUrl}/{elementId}", content);

            if (!response.IsSuccessStatusCode)
            {
                throw new Exception($"Failed to propagate update for element {elementId} to CDN.");
            }

            Console.WriteLine($"Updated HTML content for element {elementId} propagated to CDN successfully.");
        }
        catch (Exception ex)
        {
            // Log error and rethrow for further handling
            Console.Error.WriteLine($"Error propagating update for element {elementId} to CDN: {ex.Message}");
            throw;
        }
    }
}
