import java.net.http.HttpResponse;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.concurrent.ConcurrentHashMap;
import com.fasterxml.jackson.databind.ObjectMapper;

public class ConfigManager {
    private static final String DEFAULT_CONFIG_DIR = "/default/config";
    private static final long CACHE_EXPIRY_TIME = 3600; // Cache expiry time in seconds
    private static final HttpClient httpClient = HttpClient.newHttpClient();
    private static final ConcurrentHashMap<String, Config> configCache = new ConcurrentHashMap<>();

    public static void initConfigFromCloud(String cloudUri) {
        try {
            Path cacheRoot = Paths.get(getConfigDir());
            if (!Files.exists(cacheRoot)) {
                Files.createDirectories(cacheRoot);
            }

            String jsonContent = fetchJsonFromCloud(cloudUri);
            Config config = parseJsonToConfig(jsonContent);

            configCache.put("config", config);
        } catch (IOException | InterruptedException e) {
            System.err.println("Failed to initialize configuration: " + e.getMessage());
        }
    }

    private static String getConfigDir() {
        // Implement logic to retrieve the configured directory or use the default
        return System.getProperty("config.dir", DEFAULT_CONFIG_DIR);
    }

    private static String fetchJsonFromCloud(String cloudUri) throws IOException, InterruptedException {
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(cloudUri))
                .GET()
                .build();

        HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
        return response.body();
    }

    private static Config parseJsonToConfig(String jsonContent) throws IOException {
        ObjectMapper objectMapper = new ObjectMapper();
        return objectMapper.readValue(jsonContent, Config.class);
    }

    public static Config getConfig() {
        Config cachedConfig = configCache.get("config");
        if (cachedConfig == null || isCacheStale(cachedConfig)) {
            initConfigFromCloud("https://example.com/config.json");
            return configCache.get("config");
        }
        return cachedConfig;
    }

    private static boolean isCacheStale(Config config) {
        // Implement logic to check if the cache is stale based on last update time
        return System.currentTimeMillis() - config.getLastUpdateTime() > CACHE_EXPIRY_TIME * 1000;
    }

    public static void main(String[] args) {
        Config config = getConfig();
        System.out.println("Configuration: " + config);
    }
}

