function runTestSuite(testModules, testLabel, runTest, maxMemoryUsage, dependencyCache) {
    const blueslip = require('blueslip');
    let memoryUsage = 0;
    let passedTests = [];
    let failedTests = [];

    function log(message) {
        console.log(`${testLabel}: ${message}`);
    }

    function resetBlueslip() {
        blueslip.clear();
    }

    function checkMemoryUsage() {
        if (memoryUsage > maxMemoryUsage) {
            throw new Error('Memory usage limit exceeded');
        }
    }

    async function executeTest(modulePath) {
        try {
            log(`Starting test for module: ${modulePath}`);
            await runTest(modulePath, () => {
                passedTests.push(modulePath);
                log(`Test passed for module: ${modulePath}`);
            });
            resetBlueslip();
        } catch (error) {
            failedTests.push(modulePath);
            log(`Test failed for module: ${modulePath}. Error: ${error.message}`);
        }
    }

    async function runAllTests() {
        for (const modulePath of testModules) {
            await executeTest(modulePath);
            checkMemoryUsage();
        }
    }

    try {
        await runAllTests();
    } catch (error) {
        log(`Error during test execution: ${error.message}`);
    }

    const summary = {
        passed: passedTests,
        failed: failedTests,
        memoryUsage
    };

    return summary;
}
