// Define AngularJS module and controller
var app = angular.module('dialogApp', []);
app.controller('DialogController', ['$scope', '$http', function($scope, $http) {
    // Cache to store successfully refreshed fields
    var refreshCache = {};

    // Function to refresh dialog fields
    $scope.refreshFields = function(fieldNames, allFieldNames, resourceId, url) {
        fieldNames.forEach(function(fieldName) {
            if (allFieldNames.includes(fieldName)) {
                if (!refreshCache[fieldName]) {
                    $http.get(url + '?resourceId=' + resourceId + '&fieldName=' + fieldName)
                        .then(function(response) {
                            // Handle successful response
                            refreshCache[fieldName] = true;
                            $scope.$emit('fieldRefreshed', { fieldName: fieldName, data: response.data });
                        })
                        .catch(function(error) {
                            // Handle error and retry logic
                            console.error('Error refreshing field:', fieldName);
                            setTimeout(function() {
                                $scope.refreshFields([fieldName], allFieldNames, resourceId, url);
                            }, 2000); // Retry after 2 seconds
                        });
                }
            }
        });
    };

    // Helper function to modify forward list of strings
    $scope.insertAfter = function(forwardList, searchString, insertString) {
        var index = forwardList.indexOf(searchString);
        if (index !== -1) {
            forwardList.splice(index + 1, 0, insertString);
        } else {
            forwardList.push(insertString);
        }
    };
}]);

// Example usage in HTML
<div ng-app="dialogApp" ng-controller="DialogController">
    <button ng-click="refreshFields(['field1', 'field2'], ['field1', 'field2', 'field3'], '123', '/api/refresh')">Refresh Fields</button>
</div>
