import json

def validate_config(config_tree, profile):
    def traverse(node, path):
        if not isinstance(node, dict):
            raise ValueError(f"Invalid configuration at {path}: Expected a dictionary")

        for key, value in node.items():
            new_path = f"{path}.{key}" if path else key
            if key not in profile:
                raise ValueError(f"Unexpected setting '{key}' at {new_path}")

            expected_type = profile[key].get('type')
            if expected_type and not isinstance(value, expected_type):
                raise ValueError(f"Incorrect type for '{key}' at {new_path}. Expected {expected_type.__name__}, got {type(value).__name__}")

            required = profile[key].get('required', False)
            if required and value is None:
                raise ValueError(f"Missing required setting '{key}' at {new_path}")

            optional = profile[key].get('optional', False)
            if not required and not optional and value is None:
                continue

            sub_profile = profile[key].get('profile')
            if sub_profile:
                traverse(value, new_path)

    traverse(config_tree, "")
    return True

# Example usage
config_tree = {
    "database": {
        "host": "localhost",
        "port": 5432,
        "user": "admin"
    },
    "logging": {
        "level": "INFO"
    }
}

profile = {
    "database": {
        "type": dict,
        "required": True,
        "profile": {
            "host": {"type": str, "required": True},
            "port": {"type": int, "required": True},
            "user": {"type": str, "required": True}
        }
    },
    "logging": {
        "type": dict,
        "optional": True,
        "profile": {
            "level": {"type": str, "optional": True}
        }
    }
}

try:
    validate_config(config_tree, profile)
    print("Configuration is valid.")
except ValueError as e:
    print(f"Validation error: {e}")
