import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.*;
import java.util.concurrent.*;
import java.util.stream.Collectors;

public class FileProcessor {

    private static final int MAX_RETRIES = 3;
    private static final long RETRY_DELAY = 1000; // milliseconds
    private static final Cache<Path, Boolean> fileCache = Caffeine.newBuilder()
            .maximumSize(1000)
            .expireAfterWrite(5, TimeUnit.MINUTES)
            .build();

    public static void processFiles(List<String> filePaths) {
        long startTime = System.currentTimeMillis();
        ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        CompletionService<Long> completionService = new ExecutorCompletionService<>(executor);

        for (String path : filePaths) {
            Path resolvedPath = Paths.get(path).toAbsolutePath().normalize();
            completionService.submit(() -> processFile(resolvedPath));
        }

        long totalSize = 0;
        int completedTasks = 0;

        while (completedTasks < filePaths.size()) {
            try {
                Future<Long> future = completionService.take();
                Long fileSize = future.get();
                if (fileSize != null) {
                    totalSize += fileSize;
                }
                completedTasks++;
            } catch (InterruptedException | ExecutionException e) {
                e.printStackTrace();
            }
        }

        executor.shutdown();
        long endTime = System.currentTimeMillis();
        System.out.println("Total processing time: " + (endTime - startTime) + " ms");
    }

    private static Long processFile(Path path) {
        if (!fileCache.getIfPresent(path)) {
            try {
                Path resolvedPath = Files.readSymbolicLink(path);
                fileCache.put(resolvedPath, true);
            } catch (IOException e) {
                System.out.println("Failed to resolve symbolic link: " + path);
                return null;
            }
        }

        for (int retry = 0; retry < MAX_RETRIES; retry++) {
            try {
                if (Files.isReadable(path)) {
                    long fileSize = Files.size(path);
                    System.out.println("File accessible and readable: " + path + ", size: " + fileSize);
                    return fileSize;
                } else {
                    Thread.sleep(RETRY_DELAY);
                }
            } catch (IOException | InterruptedException e) {
                System.out.println("Failed to check file accessibility: " + path);
                return null;
            }
        }

        System.out.println("File inaccessible after retries: " + path);
        return null;
    }

    public static void main(String[] args) {
        List<String> filePaths = Arrays.asList(
                "/path/to/file1",
                "/path/to/file2",
                "/path/to/symlink"
        );
        processFiles(filePaths);
    }
}
