public class ThemeCacheManager {
    private static final String DEFAULT_THEME_DIR = "default_theme_dir";
    private static final int INITIAL_CACHE_SIZE = 1024;
    private static final double LOAD_FACTOR = 0.75;
    private static final long MAX_LATENCY = 100; // milliseconds
    private static final int MIN_CACHE_SIZE = 128;

    private ConcurrentHashMap<String, byte[]> cache;
    private File themeDir;
    private ExternalStorageService storageService;

    public ThemeCacheManager() {
        this.cache = new ConcurrentHashMap<>(INITIAL_CACHE_SIZE, LOAD_FACTOR);
        configureThemeDirectory();
        initializeExternalStorage();
    }

    private void configureThemeDirectory() {
        // Validate and configure the default theme directory
        File dir = new File(DEFAULT_THEME_DIR);
        if (!dir.exists()) {
            dir.mkdirs();
        }
        this.themeDir = dir;
    }

    private void initializeExternalStorage() {
        // Initialize external storage service with fallback mechanisms
        try {
            this.storageService = new ExternalStorageService();
        } catch (Exception e) {
            System.err.println("Failed to initialize external storage. Using local cache.");
            this.storageService = null;
        }
    }

    public byte[] loadThemeBitmap(String themeName) throws IOException {
        // Load and parse a PNG file from the cache root directory
        File file = new File(themeDir, themeName + ".png");
        if (file.exists()) {
            return readBytesFromFile(file);
        } else {
            byte[] bitmap = storageService.fetchThemeBitmap(themeName);
            if (bitmap != null) {
                writeBytesToFile(file, bitmap);
                return bitmap;
            }
        }
        throw new FileNotFoundException("Theme bitmap not found: " + themeName);
    }

    private byte[] readBytesFromFile(File file) throws IOException {
        try (FileInputStream fis = new FileInputStream(file)) {
            return fis.readAllBytes();
        }
    }

    private void writeBytesToFile(File file, byte[] bytes) throws IOException {
        try (FileOutputStream fos = new FileOutputStream(file)) {
            fos.write(bytes);
        }
    }

    public void evictLeastRecentlyUsed() {
        // Implement a scalable eviction policy
        if (cache.size() > MAX_LATENCY * cache.size()) {
            cache.entrySet().removeIf(entry -> entry.getValue().length > 1024); // Example condition
        }
    }

    public String computeMD5(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] hashBytes = md.digest(input.getBytes());
            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            System.err.println("MD5 algorithm not available.");
            return null;
        }
    }

    public void logCacheMetrics() {
        // Monitor cache performance metrics
        System.out.println("Cache hit rate: " + calculateHitRate());
        System.out.println("Average latency: " + calculateLatency() + " ms");
    }

    private double calculateHitRate() {
        // Calculate cache hit rate
        return 0.95; // Example value
    }

    private long calculateLatency() {
        // Calculate average latency
        return 20; // Example value in milliseconds
    }
}

interface ExternalStorageService {
    byte[] fetchThemeBitmap(String themeName) throws IOException;
}
