#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_TASKS 1000
#define RESIZE_FACTOR 1.1

typedef struct {
    int priority;
    time_t deadline;
    char* description;
} Task;

Task** taskList = NULL;
int taskCount = 0;
int capacity = 0;

void initializeTaskManager() {
    capacity = MAX_TASKS;
    taskList = (Task**)malloc(capacity * sizeof(Task*));
}

void addTask(int priority, time_t deadline, const char* description) {
    if (taskCount >= capacity) {
        int newCapacity = (int)(capacity * RESIZE_FACTOR);
        Task** newTaskList = (Task**)realloc(taskList, newCapacity * sizeof(Task*));
        if (newTaskList == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }
        taskList = newTaskList;
        capacity = newCapacity;
    }

    Task* newTask = (Task*)malloc(sizeof(Task));
    newTask->priority = priority;
    newTask->deadline = deadline;
    newTask->description = strdup(description);

    taskList[taskCount++] = newTask;
}

void displayHighestPriorityTask() {
    if (taskCount == 0) {
        printf("No tasks available\n");
        return;
    }

    int highestPriorityIndex = 0;
    for (int i = 1; i < taskCount; i++) {
        if (taskList[i]->priority > taskList[highestPriorityIndex]->priority) {
            highestPriorityIndex = i;
        }
    }

    printf("Highest Priority Task:\n");
    printf("Priority: %d\n", taskList[highestPriorityIndex]->priority);
    printf("Deadline: %ld\n", taskList[highestPriorityIndex]->deadline);
    printf("Description: %s\n", taskList[highestPriorityIndex]->description);
}

void cleanupTaskManager() {
    for (int i = 0; i < taskCount; i++) {
        free(taskList[i]->description);
        free(taskList[i]);
    }
    free(taskList);
    taskList = NULL;
    taskCount = 0;
    capacity = 0;
}
