#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_RECORDS 10000
#define INITIAL_CAPACITY 10

typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t count;
    size_t alignment;
} KeyValueStore;

KeyValueStore* createKeyValueStore(size_t alignment) {
    KeyValueStore* store = (KeyValueStore*)malloc(sizeof(KeyValueStore));
    if (!store) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    store->records = (Record*)aligned_alloc(alignment, sizeof(Record) * INITIAL_CAPACITY);
    if (!store->records) {
        free(store);
        fprintf(stderr, "Memory allocation failed for records\n");
        return NULL;
    }
    store->capacity = INITIAL_CAPACITY;
    store->count = 0;
    store->alignment = alignment;
    return store;
}

void addRecord(KeyValueStore* store, int key, long offset) {
    if (store->count >= MAX_RECORDS) {
        fprintf(stderr, "Maximum number of records reached\n");
        return;
    }
    if (store->count == store->capacity) {
        size_t new_capacity = store->capacity * 1.1;
        Record* new_records = (Record*)aligned_alloc(store->alignment, sizeof(Record) * new_capacity);
        if (!new_records) {
            fprintf(stderr, "Memory allocation failed for records\n");
            return;
        }
        memcpy(new_records, store->records, store->count * sizeof(Record));
        free(store->records);
        store->records = new_records;
        store->capacity = new_capacity;
    }
    store->records[store->count].key = key;
    store->records[store->count].offset = offset;
    store->count++;
}

void printLargestKey(KeyValueStore* store) {
    if (store->count == 0) {
        printf("No records to display\n");
        return;
    }
    int largest_key = store->records[0].key;
    for (size_t i = 1; i < store->count; i++) {
        if (store->records[i].key > largest_key) {
            largest_key = store->records[i].key;
        }
    }
    printf("Largest key: %d\n", largest_key);
}

void cleanupKeyValueStore(KeyValueStore* store) {
    free(store->records);
    store->records = NULL;
    store->capacity = 0;
    store->count = 0;
    store->alignment = 0;
    free(store);
}
