#include <iostream>
#include <vector>
#include <string>
#include <thread>
#include <chrono>
#include <random>
#include <curl/curl.h>

struct Record {
    int value;
    int* key;
};

class HTTPClient {
public:
    HTTPClient(const std::string& serverUrl) : serverUrl(serverUrl), recordCapacity(10), records(recordCapacity), totalRecords(0) {}

    ~HTTPClient() {
        for (auto& record : records) {
            delete record.key;
        }
    }

    void addRecord(int value, int key) {
        if (totalRecords >= recordCapacity) {
            resizeRecords();
        }
        Record newRecord = {value, new int(key)};
        records[totalRecords++] = newRecord;
    }

    void sendRequests() {
        for (int i = 0; i < totalRecords; ++i) {
            std::thread([this, i]() {
                performRequest(records[i]);
            }).detach();
        }
    }

private:
    std::string serverUrl;
    int recordCapacity;
    std::vector<Record> records;
    int totalRecords;

    void resizeRecords() {
        recordCapacity = static_cast<int>(recordCapacity * 1.1);
        records.resize(recordCapacity);
    }

    size_t writeCallback(void* contents, size_t size, size_t nmemb, void* userp) {
        // Handle response data
        return size * nmemb;
    }

    void performRequest(const Record& record) {
        CURL* curl = curl_easy_init();
        if (curl) {
            std::string url = serverUrl + "?key=" + std::to_string(*record.key);
            curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
            curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writeCallback);

            auto start = std::chrono::high_resolution_clock::now();
            CURLcode res = curl_easy_perform(curl);
            auto end = std::chrono::high_resolution_clock::now();

            if (res != CURLE_OK) {
                // Handle error
            } else {
                // Log metrics
                std::chrono::duration<double> duration = end - start;
                std::cout << "Request took: " << duration.count() << " seconds" << std::endl;
            }

            curl_easy_cleanup(curl);
        }
    }
};

int main() {
    HTTPClient client("http://example.com/api");
    client.addRecord(1, 100);
    client.addRecord(2, 200);

    client.sendRequests();

    return 0;
}
