<?php

class UserService {
    private $db;
    private $themeService;

    public function __construct($db, $themeService) {
        $this->db = $db;
        $this->themeService = $themeService;
    }

    public function updatePassword($userId, $newPassword) {
        // Validate password strength
        if (!$this->validatePasswordStrength($newPassword)) {
            throw new Exception("Invalid password strength");
        }

        // Retry mechanism with exponential backoff
        for ($retryCount = 0; $retryCount < MAX_RETRIES; $retryCount++) {
            try {
                // Update user password in database atomically
                $this->db->beginTransaction();
                $this->updateUserPasswordInDatabase($userId, $newPassword);
                $this->db->commit();
                break;
            } catch (Exception $e) {
                if ($retryCount == MAX_RETRIES - 1) {
                    throw $e;
                }
                sleep(pow(2, $retryCount));
            }
        }

        // Update theme cache
        $this->themeService->updateThemeCache($userId);
    }

    private function validatePasswordStrength($password) {
        // External service call to validate password strength
        return $this->externalServiceCall('validate_password', ['password' => $password]);
    }

    private function updateUserPasswordInDatabase($userId, $newPassword) {
        // Update user password in database atomically
        $encryptedPassword = $this->encryptPassword($newPassword);
        $sql = "UPDATE users SET password = :password WHERE id = :id";
        $stmt = $this->db->prepare($sql);
        $stmt->execute([':password' => $encryptedPassword, ':id' => $userId]);
    }

    private function encryptPassword($password) {
        // Derive key using secure KDF
        $key = hash_pbkdf2('sha256', $password, SALT, 100000, 32);

        // Generate IV and encrypt password with AES-256-CBC
        $iv = openssl_random_pseudo_bytes(openssl_cipher_iv_length('aes-256-cbc'));
        return base64_encode($iv . openssl_encrypt($password, 'aes-256-cbc', $key, OPENSSL_RAW_DATA, $iv));
    }

    private function externalServiceCall($endpoint, $data) {
        // External service call with error handling
        try {
            $response = file_get_contents("http://external-service/$endpoint?" . http_build_query($data));
            return json_decode($response, true);
        } catch (Exception $e) {
            throw new Exception("External service failure");
        }
    }
}

class ThemeService {
    public function updateThemeCache($userId) {
        // Update theme cache
        $themeBitmap = $this->getThemeBitmapFromCache();
        if ($themeBitmap) {
            $this->recycleThemeBitmap($themeBitmap);
        }

        $defaultThemePath = $this->getDefaultThemePath();
        $pngFile = $this->parsePngFile($defaultThemePath);

        // Store PNG file in theme cache
        $this->storePngFileInCache($pngFile);
    }

    private function getThemeBitmapFromCache() {
        // Retrieve theme bitmap from cache
        return $this->cacheService->get('theme_bitmap');
    }

    private function recycleThemeBitmap($themeBitmap) {
        // Recycle theme bitmap
        $this->cacheService->delete('theme_bitmap');
    }

    private function getDefaultThemePath() {
        // Establish default theme directory
        return '/path/to/default/theme';
    }

    private function parsePngFile($filePath) {
        // Parse PNG file from cache root directory
        if (!file_exists($filePath)) {
            throw new Exception("Invalid input parameters or missing files");
        }
        return file_get_contents($filePath);
    }

    private function storePngFileInCache($pngFile) {
        // Store PNG file in theme cache
        $this->cacheService->set('theme_png', $pngFile);
    }
}

// Usage example
$db = new PDO('mysql:host=localhost;dbname=users', 'username', 'password');
$themeService = new ThemeService(new CacheService());
$userService = new UserService($db, $themeService);

try {
    $userService->updatePassword(123, 'new_secure_password');
} catch (Exception $e) {
    echo "Error: " . $e->getMessage();
}
?>
