from queue import Queue
from concurrent.futures import ThreadPoolExecutor

class ExternalAPIClient:
    def validate_sequence_number(self, sequence_number):
        # Placeholder for actual API validation logic
        pass

def distributed_lock(lock_name):
    lock = Lock()

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            with lock:
                return func(*args, **kwargs)
        return wrapper
    return decorator

@distributed_lock('file_processing_lock')
def process_file(file_path, sort_key, api_client):
    start_time = time.time()

    try:
        with open(file_path, 'r') as file:
            data = []
            for line in file:
                obj = json.loads(line)
                data.append(obj)

        sorted_data = sorted(data, key=lambda x: x[sort_key])
        last_sequence_number = sorted_data[-1]['sequence_number']

        api_client.validate_sequence_number(last_sequence_number)

    except FileNotFoundError:
        print("File not found.")
    except json.JSONDecodeError:
        print("Invalid JSON format in file.")
    except Exception as e:
        print(f"An error occurred: {e}")

    end_time = time.time()
    processing_time = end_time - start_time
    print(f"Processing time: {processing_time} seconds")

def monitor_and_log(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        start_time = time.time()
        result = func(*args, **kwargs)
        end_time = time.time()
        processing_time = end_time - start_time
        print(f"Function {func.__name__} took {processing_time} seconds to execute")
        return result
    return wrapper

@monitor_and_log
def process_files_concurrently(file_paths, sort_key, api_client):
    with ThreadPoolExecutor(max_workers=5) as executor:
        futures = [executor.submit(process_file, file_path, sort_key, api_client) for file_path in file_paths]
        for future in futures:
            future.result()

# Example usage
api_client = ExternalAPIClient()
file_paths = ['path/to/file1.json', 'path/to/file2.json']
sort_key = 'timestamp'
process_files_concurrently(file_paths, sort_key, api_client)
