    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} RecordList;

RecordList* create_record_list() {
    RecordList* list = (RecordList*)malloc(sizeof(RecordList));
    if (!list) return NULL;

    list->records = (Record**)calloc(INITIAL_CAPACITY, sizeof(Record*));
    if (!list->records) {
        free(list);
        return NULL;
    }

    list->capacity = INITIAL_CAPACITY;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void destroy_record_list(RecordList* list) {
    for (size_t i = 0; i < list->size; ++i) {
        free(list->records[i]->key);
        free(list->records[i]);
    }
    free(list->records);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

void grow_record_list(RecordList* list) {
    size_t new_capacity = (size_t)(list->capacity * GROWTH_FACTOR);
    Record** new_records = (Record**)realloc(list->records, new_capacity * sizeof(Record*));

    if (!new_records) return;

    list->records = new_records;
    list->capacity = new_capacity;
}

void add_record(RecordList* list, int value, const char* key, float average) {
    pthread_mutex_lock(&list->mutex);

    if (list->size == list->capacity) grow_record_list(list);

    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) {
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    record->value = value;
    record->key = strdup(key);
    record->average = average;

    list->records[list->size++] = record;

    pthread_mutex_unlock(&list->mutex);
}

void* read_input_thread(void* arg) {
    RecordList* list = (RecordList*)arg;
    int value;
    char key[256];
    float average;

    while (scanf("%d %s %f", &value, key, &average) == 3) {
        add_record(list, value, key, average);
    }

    return NULL;
}

int main() {
    RecordList* list = create_record_list();
    if (!list) {
        fprintf(stderr, "Failed to create record list\n");
        return EXIT_FAILURE;
    }

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, read_input_thread, list) != 0) {
        fprintf(stderr, "Failed to create input thread\n");
        destroy_record_list(list);
        return EXIT_FAILURE;
    }

    pthread_join(thread_id, NULL);

    // Perform statistical calculations using external library

    destroy_record_list(list);
    return EXIT_SUCCESS;
}
