#include <time.h>

typedef struct {
    double budget;
    char *status;
    time_t completion_deadline;
} Project;

Project* init_project_list(int num_projects, double max_budget) {
    Project *projects = (Project*)malloc(num_projects * sizeof(Project));
    if (!projects) return NULL;

    for (int i = 0; i < num_projects; i++) {
        projects[i].budget = fmin(10000.0 + i * 10000.0, max_budget);
        projects[i].status = strdup("Active");
        if (!projects[i].status) {
            free(projects);
            return NULL;
        }
        time_t now = time(NULL);
        projects[i].completion_deadline = now + (i + 1) * 86400; // 24 hours later
    }

    return projects;
}

void update_project_status(Project *project, const char *new_status) {
    if (strcmp(project->status, "Active") == 0 && strcmp(new_status, "Completed") == 0) {
        time_t now = time(NULL);
        project->completion_deadline = now + 86400; // Recalculate deadline to 24 hours from now
    }
    free(project->status);
    project->status = strdup(new_status);
}

void export_to_csv(Project *projects, int num_projects, const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) return;

    fprintf(file, "Budget,Status,Completion Deadline\n");
    for (int i = 0; i < num_projects; i++) {
        fprintf(file, "%.2f,%s,%ld\n", projects[i].budget, projects[i].status, projects[i].completion_deadline);
    }

    fclose(file);
}

void free_project_list(Project *projects, int num_projects) {
    for (int i = 0; i < num_projects; i++) {
        free(projects[i].status);
    }
    free(projects);
}
