#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/time.h>

#define INITIAL_CAPACITY 10
#define GROWTH_FACTOR 1.1
#define MAX_RECORDS 1000

typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t count;
    size_t alignment;
} RecordManager;

RecordManager* create_record_manager(size_t initial_capacity, size_t alignment) {
    RecordManager* manager = (RecordManager*)aligned_alloc(alignment, sizeof(RecordManager));
    if (!manager) {
        perror("Failed to allocate memory for RecordManager");
        return NULL;
    }
    manager->records = (Record*)aligned_alloc(alignment, initial_capacity * sizeof(Record));
    if (!manager->records) {
        perror("Failed to allocate memory for records");
        free(manager);
        return NULL;
    }
    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->alignment = alignment;
    return manager;
}

void destroy_record_manager(RecordManager* manager) {
    if (manager->records) {
        free(manager->records);
    }
    free(manager);
}

int add_record(RecordManager* manager, int key, long offset) {
    if (manager->count >= MAX_RECORDS) {
        fprintf(stderr, "Maximum number of records reached\n");
        return -1;
    }
    if (manager->count == manager->capacity) {
        size_t new_capacity = (size_t)(manager->capacity * GROWTH_FACTOR);
        Record* new_records = (Record*)aligned_alloc(manager->alignment, new_capacity * sizeof(Record));
        if (!new_records) {
            perror("Failed to allocate memory for new records");
            return -1;
        }
        memcpy(new_records, manager->records, manager->count * sizeof(Record));
        free(manager->records);
        manager->records = new_records;
        manager->capacity = new_capacity;
    }
    manager->records[manager->count].key = key;
    manager->records[manager->count].offset = offset;
    manager->count++;
    return 0;
}

void find_and_print_largest_key(RecordManager* manager) {
    if (manager->count == 0) {
        printf("No records to process\n");
        return;
    }
    int largest_key = manager->records[0].key;
    for (size_t i = 1; i < manager->count; i++) {
        if (manager->records[i].key > largest_key) {
            largest_key = manager->records[i].key;
        }
    }
    printf("Largest key: %d\n", largest_key);
}

int main() {
    RecordManager* manager = create_record_manager(INITIAL_CAPACITY, 64);
    if (!manager) {
        return EXIT_FAILURE;
    }

    add_record(manager, 10, 12345);
    add_record(manager, 20, 67890);

    find_and_print_largest_key(manager);

    destroy_record_manager(manager);
    return EXIT_SUCCESS;
}
