#include <iostream>
#include <queue>
#include <vector>
#include <random>
#include <mutex>
#include <condition_variable>

class GameCharacterAttackSystem {
public:
    struct Attack {
        int id;
        double probability;
        int cooldown;
        int usageCount;
        std::chrono::time_point<std::chrono::system_clock> lastUsed;

        Attack(int id, double probability, int cooldown)
            : id(id), probability(probability), cooldown(cooldown), usageCount(0) {}
    };

private:
    std::vector<Attack> attacks;
    std::queue<int> attackQueue;
    std::mutex mtx;
    std::condition_variable cv;
    bool sessionActive;

public:
    GameCharacterAttackSystem() : sessionActive(false) {
        attacks.emplace_back(1, 0.4, 9);
        attacks.emplace_back(2, 0.35, 12);
        attacks.emplace_back(3, 0.25, 15);
    }

    void startSession() {
        std::lock_guard<std::mutex> lock(mtx);
        sessionActive = true;
        refillAttackQueue();
    }

    void endSession() {
        std::lock_guard<std::mutex> lock(mtx);
        sessionActive = false;
        attackQueue = {};
    }

    int getNextAttack() {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this] { return !attackQueue.empty(); });
        int nextAttack = attackQueue.front();
        attackQueue.pop();
        updateAttackUsage(nextAttack);
        return nextAttack;
    }

private:
    void refillAttackQueue() {
        std::random_device rd;
        std::mt19937 gen(rd());
        while (sessionActive && attackQueue.size() < 3) {
            int nextAttack = selectNextAttack(gen);
            if (nextAttack != -1) {
                attackQueue.push(nextAttack);
            }
        }
    }

    int selectNextAttack(std::mt19937& gen) {
        std::discrete_distribution<> dist({attacks[0].probability, attacks[1].probability, attacks[2].probability});
        int selected = dist(gen);
        if (attacks[selected].usageCount < 5 && canUseAttack(selected)) {
            return selected;
        }
        return -1;
    }

    bool canUseAttack(int id) {
        std::chrono::time_point<std::chrono::system_clock> now = std::chrono::system_clock::now();
        for (auto& attack : attacks) {
            if (attack.id == id && now < attack.lastUsed + std::chrono::seconds(attack.cooldown)) {
                return false;
            }
        }
        return true;
    }

    void updateAttackUsage(int id) {
        for (auto& attack : attacks) {
            if (attack.id == id) {
                attack.usageCount++;
                attack.lastUsed = std::chrono::system_clock::now();
                break;
            }
        }
    }
};
