#include <atomic>
#include <thread>
#include <mutex>

struct Record {
    long timestamp;
    int key;
    double value;
};

class MemoryManager {
public:
    MemoryManager(size_t initialSize, size_t maxRecords)
        : records_(new Record[maxRecords]), capacity_(maxRecords), size_(0) {}

    ~MemoryManager() {
        delete[] records_;
    }

    Record* allocateRecord(long timestampRangeStart, long timestampRangeEnd, double valuePrecision) {
        if (size_ >= capacity_) {
            expandCapacity();
        }
        Record& record = records_[size_++];
        record.timestamp = generateRandomTimestamp(timestampRangeStart, timestampRangeEnd);
        record.key = generateRandomKey();
        record.value = generateRandomValue(valuePrecision);
        return &record;
    }

private:
    Record* records_;
    size_t capacity_;
    size_t size_;

    void expandCapacity() {
        size_t newCapacity = capacity_ * 2;
        Record* newRecords = new Record[newCapacity];
        for (size_t i = 0; i < size_; ++i) {
            newRecords[i] = records_[i];
        }
        delete[] records_;
        records_ = newRecords;
        capacity_ = newCapacity;
    }

    long generateRandomTimestamp(long start, long end) {
        return start + rand() % (end - start + 1);
    }

    int generateRandomKey() {
        return rand();
    }

    double generateRandomValue(double precision) {
        return ((double)rand() / RAND_MAX) * precision;
    }
};

int main() {
    srand(time(0));
    MemoryManager manager(10, 100);

    for (size_t i = 0; i < 50; ++i) {
        Record* record = manager.allocateRecord(1633072800L, 1633159200L, 100.0);
        // Use the record
    }

    return 0;
}
