typedef int (*FilterCallback)(int);

int optimizeMemoryUsage(int* dataArray, int arraySize, FilterCallback filterElement) {
    if (dataArray == NULL || arraySize < 0) {
        return 0;
    }

    int writeIndex = 0;
    for (int i = 0; i < arraySize; i++) {
        if (!filterElement(dataArray[i])) {
            dataArray[writeIndex++] = dataArray[i];
        }
    }

    // Resize the array to remove unused elements
    int* newArray = realloc(dataArray, writeIndex * sizeof(int));
    if (newArray != NULL) {
        dataArray = newArray;
    } else {
        return 0; // Memory allocation failed
    }

    return writeIndex;
}

int isNotDivisibleByThree(int element) {
    return element % 3 != 0;
