struct LogEntry {
    std::string timestamp;
    std::string description;
};

class LogProcessor {
public:
    LogProcessor(size_t max_entries, size_t max_description_length)
        : max_entries_(max_entries), max_description_length_(max_description_length) {}

    void addLog(const std::string& timestamp, const std::string& description) {
        std::unique_lock<std::mutex> lock(mutex_);
        cv_.wait(lock, [this] { return entries_.size() < max_entries_; });
        if (entries_.size() >= max_entries_) {
            throw std::runtime_error("Log buffer is full");
        }
        if (!isValidTimestamp(timestamp) || description.length() > max_description_length_) {
            throw std::invalid_argument("Invalid log entry");
        }
        entries_.push_back({timestamp, description});
        cv_.notify_one();
    }

    void processLogs() {
        while (true) {
            LogEntry entry;
            {
                std::unique_lock<std::mutex> lock(mutex_);
                cv_.wait(lock, [this] { return !entries_.empty(); });
                if (entries_.empty()) {
                    break;
                }
                entry = entries_.back();
                entries_.pop_back();
            }
            processLogEntry(entry);
        }
    }

private:
    bool isValidTimestamp(const std::string& timestamp) {
        // Implement timestamp validation logic
        return true;
    }

    void processLogEntry(const LogEntry& entry) {
        // Implement log processing logic
        std::cout << "Processing log: " << entry.timestamp << " - " << entry.description << std::endl;
    }

    size_t max_entries_;
    size_t max_description_length_;
    std::vector<LogEntry> entries_;
    std::mutex mutex_;
    std::condition_variable cv_;
};

