};

// Function to process and initialize an octree
std::pair<std::string, Octree*> processAndInitializeOctree(const std::string& filename, int featureSize, int leafNodes, int maxFilenameLength) {
    // Check for invalid input or exceeding maximum filename length
    if (filename.empty() || featureSize <= 0 || leafNodes <= 0 || maxFilenameLength <= 0) {
        return {filename, nullptr};
    }

    std::string modifiedFilename = filename;
    // Remove spaces and special characters, convert to lowercase
    for (auto& ch : modifiedFilename) {
        if (!isalnum(ch)) {
            ch = '_';
        } else {
            ch = tolower(ch);
        }
    }

    // Ensure the filename does not exceed the maximum length
    if (modifiedFilename.length() > maxFilenameLength) {
        modifiedFilename.resize(maxFilenameLength);
    }

    // Append the octree feature size and leaf nodes as an extension
    modifiedFilename += "_fs" + std::to_string(featureSize) + "_ln" + std::to_string(leafNodes);

    // Initialize the octree
    Octree* octree = new Octree();
    octree->featureSize = featureSize;
    octree->leafNodes = leafNodes;

    return {modifiedFilename, octree};
}

// Example usage
int main() {
    auto [newFilename, octree] = processAndInitializeOctree("example file.txt", 8, 16, 20);
    if (octree) {
        std::cout << "New Filename: " << newFilename << std::endl;
        // Use the octree object
        delete octree; // Don't forget to clean up
    } else {
        std::cout << "Failed to initialize octree." << std::endl;
    }
    return 0;
}
