#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_CONCURRENT_PROCESSES 10
#define LOG_FILE "execution_log.txt"

typedef struct {
    char *sql_command;
    void *db_connection_details;
    int *status_code;
} CommandRequest;

CommandRequest request_queue[MAX_CONCURRENT_PROCESSES];
int queue_head = 0, queue_tail = 0, queue_size = 0;
sem_t queue_mutex, queue_full, queue_empty;

void log_error(const char *error_message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", __TIMESTAMP__, error_message);
        fclose(log_file);
    }
}

int executeCommandAsync(char *sql_command, void *db_connection_details, int *status_code) {
    sem_wait(&queue_full);
    sem_wait(&queue_mutex);

    if (queue_size == MAX_CONCURRENT_PROCESSES) {
        sem_post(&queue_mutex);
        sem_post(&queue_full);
        return 0; // Queue is full
    }

    request_queue[queue_tail].sql_command = sql_command;
    request_queue[queue_tail].db_connection_details = db_connection_details;
    request_queue[queue_tail].status_code = status_code;

    queue_tail = (queue_tail + 1) % MAX_CONCURRENT_PROCESSES;
    queue_size++;

    sem_post(&queue_mutex);
    sem_post(&queue_empty);

    return 1; // Command added to queue
}

void *process_commands(void *arg) {
    while (1) {
        sem_wait(&queue_empty);
        sem_wait(&queue_mutex);

        if (queue_size == 0) {
            sem_post(&queue_mutex);
            sem_post(&queue_empty);
            continue;
        }

        CommandRequest request = request_queue[queue_head];
        queue_head = (queue_head + 1) % MAX_CONCURRENT_PROCESSES;
        queue_size--;

        sem_post(&queue_mutex);
        sem_post(&queue_full);

        // Execute the command here
        // Example: int result = execute_sql_command(request.sql_command, request.db_connection_details);
        // *request.status_code = result;

        // Log the status code or any other relevant information
    }

    return NULL;
}

int main() {
    sem_init(&queue_mutex, 0, 1);
    sem_init(&queue_full, 0, MAX_CONCURRENT_PROCESSES);
    sem_init(&queue_empty, 0, 0);

    pthread_t threads[MAX_CONCURRENT_PROCESSES];
    for (int i = 0; i < MAX_CONCURRENT_PROCESSES; i++) {
        pthread_create(&threads[i], NULL, process_commands, NULL);
    }

    // Example usage
    int status_code;
    if (!executeCommandAsync("SELECT * FROM users", db_connection, &status_code)) {
        log_error("Failed to add command to queue");
    }

    for (int i = 0; i < MAX_CONCURRENT_PROCESSES; i++) {
        pthread_join(threads[i], NULL);
    }

    sem_destroy(&queue_mutex);
    sem_destroy(&queue_full);
    sem_destroy(&queue_empty);

    return 0;
}
