    char *decryptionKey;
    char *iv;
    // Add other necessary fields for decryption
} DecryptionConfig;

// Define the connection structure
typedef struct {
    char *title;
    char *hostname;
    int active;
    // Add other necessary fields for connection
} Connection;

// Define the timer handle structure
typedef struct {
    time_t startTime;
    time_t timeout;
    // Add other necessary fields for timer
} TimerHandle;

// Function to convert Base64 to binary
void base64ToBinary(const char *base64, unsigned char **binary, size_t *length);

// Function to decrypt message using Triple DES
int decryptMessage(unsigned char *binary, size_t length, const char *key, const char *iv, unsigned char **decrypted);

// Function to validate the configuration
int validateConfig(void *config);

// Function to log events
void logEvent(const char *message);

// Main function
int processEncryptedMessage(EncryptionContext *context, const char *base64Message, void (*callback)(void), int timeout, void (*logFunc)(const char *)) {
    // Validate password
    if (context->password == NULL || strlen(context->password) == 0) {
        return ERR_INVALID_PASSWORD;
    }

    // Validate connection
    Connection *conn = (Connection *)context->connection;
    if (conn == NULL || conn->title == NULL || strlen(conn->hostname) == 0 || !conn->active) {
        return ERR_INVALID_CONNECTION;
    }

    // Validate callback function
    if (callback == NULL) {
        return ERR_NULL_CALLBACK;
    }

    // Validate timer handle
    TimerHandle *timer = (TimerHandle *)context->timerHandle;
    if (timer == NULL || time(NULL) > timer->startTime + timer->timeout) {
        return ERR_TIMER_EXPIRED;
    }

    // Validate configuration
    if (!validateConfig(context->config)) {
        return ERR_INVALID_CONFIG;
    }

    // Convert Base64 to binary
    unsigned char *binary = NULL;
    size_t length = 0;
    base64ToBinary(base64Message, &binary, &length);

    // Decrypt message
    unsigned char *decrypted = NULL;
    int result = decryptMessage(binary, length, ((DecryptionConfig *)context->config)->decryptionKey, ((DecryptionConfig *)context->config)->iv, &decrypted);
    free(binary);

    if (result != 0) {
        logEvent("Decryption failed");
        return ERR_DECRYPTION_FAILED;
    }

    // Validate decrypted message
    // Add validation logic here

    // Log decryption completion
    logEvent("Message decrypted successfully");

    // Call callback function
    callback();

    // Return decrypted message
    char *decryptedStr = (char *)malloc(length + 1);
    memcpy(decryptedStr, decrypted, length);
    decryptedStr[length] = '\0';
    free(decrypted);

    return (int)strlen(decryptedStr); // Return the length of the decrypted message
}

// Example usage
void exampleCallback() {
    printf("Decryption completed successfully.\n");
}

void logEvent(const char *message) {
    printf("Log: %s\n", message);
}

int main() {
    EncryptionContext context = {
        .password = "securePassword123",
        .config = (void *)malloc(sizeof(DecryptionConfig)),
        .connection = (void *)malloc(sizeof(Connection)),
        .callback = exampleCallback,
        .timerHandle = (void *)malloc(sizeof(TimerHandle))
    };

    // Initialize context members
    ((DecryptionConfig *)context.config)->decryptionKey = "key1234567890";
    ((DecryptionConfig *)context.config)->iv = "iv1234567890";
    ((Connection *)context.connection)->title = "Example Connection";
    ((Connection *)context.connection)->hostname = "example.com";
    ((Connection *)context.connection)->active = 1;
    ((TimerHandle *)context.timerHandle)->startTime = time(NULL);
    ((TimerHandle *)context.timerHandle)->timeout = 5;

    int result = processEncryptedMessage(&context, "SGVsbG8gV29ybGQh", exampleCallback, 5000, logEvent);

    if (result < 0) {
