using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class MessageHandler
{
    private ConcurrentDictionary<string, (byte[], byte[])> messageStore = new ConcurrentDictionary<string, (byte[], byte[])>();
    private readonly ICryptoTransform decryptor;

    public MessageHandler(byte[] key, byte[] iv)
    {
        using (TripleDES des = TripleDES.Create())
        {
            des.Key = key;
            des.IV = iv;
            decryptor = des.CreateDecryptor();
        }
    }

    public void AddMessage(string id, string base64EncodedMessage)
    {
        if (!messageStore.TryAdd(id, DecodeBase64(base64EncodedMessage)))
        {
            throw new InvalidOperationException("Message ID already exists.");
        }
    }

    public byte[] RetrieveAndDecryptMessage(string id)
    {
        if (messageStore.TryGetValue(id, out var message))
        {
            return DecryptMessage(message.Item1, message.Item2);
        }
        throw new KeyNotFoundException("Message not found.");
    }

    private (byte[], byte[]) DecodeBase64(string base64EncodedMessage)
    {
        byte[] decodedBytes = Convert.FromBase64String(base64EncodedMessage);
        int ivLength = 8; // Triple DES IV length
        return (decodedBytes.Skip(ivLength).ToArray(), decodedBytes.Take(ivLength).ToArray());
    }

    private byte[] DecryptMessage(byte[] encryptedData, byte[] iv)
    {
        using (MemoryStream msDecrypt = new MemoryStream(encryptedData))
        using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
        {
            using (var memoryStream = new MemoryStream())
            {
                csDecrypt.CopyTo(memoryStream);
                return memoryStream.ToArray();
            }
        }
    }

    public void SendDeliveryNotification(string id)
    {
        // Implement notification logic here
    }

    public static int ResolveDns(string hostname, out u_char[] ipAddress)
    {
        try
        {
            IPHostEntry hostEntry = Dns.GetHostEntry(hostname);
            IPAddress ip = hostEntry.AddressList[0];
            ipAddress = new u_char[ip.GetAddressBytes().Length];
            Buffer.BlockCopy(ip.GetAddressBytes(), 0, ipAddress, 0, ip.GetAddressBytes().Length);
            return 0; // Success
        }
        catch (Exception ex)
        {
            Console.WriteLine($"DNS resolution failed: {ex.Message}");
            ipAddress = null;
            return -1; // Error
        }
    }
}
```

