public class WebDirectoryManager
{
    private string _directoryPath;
    private static readonly log4net.ILog Log = log4net.LogManager.GetLogger(typeof(WebDirectoryManager));

    public WebDirectoryManager(string directoryPath)
    {
        _directoryPath = directoryPath;
        if (!Directory.Exists(_directoryPath))
        {
            Directory.CreateDirectory(_directoryPath);
        }
    }

    public string GenerateMD5Hash(string input)
    {
        using (MD5 md5 = MD5.Create())
        {
            byte[] inputBytes = Encoding.ASCII.GetBytes(input);
            byte[] hashBytes = md5.ComputeHash(inputBytes);
            StringBuilder sb = new StringBuilder();
            foreach (byte b in hashBytes)
            {
                sb.Append(b.ToString("x2"));
            }
            return sb.ToString();
        }
    }

    public string GenerateSHA256Hash(string input)
    {
        using (SHA256 sha256 = SHA256.Create())
        {
            byte[] inputBytes = Encoding.ASCII.GetBytes(input);
            byte[] hashBytes = sha256.ComputeHash(inputBytes);
            StringBuilder sb = new StringBuilder();
            foreach (byte b in hashBytes)
            {
                sb.Append(b.ToString("x2"));
            }
            return sb.ToString();
        }
    }

    public string GenerateCustomKDFHash(string input, int iterations)
    {
        using (Rfc2898DeriveBytes kdf = new Rfc2898DeriveBytes(input, Encoding.ASCII.GetBytes("salt"), iterations))
        {
            byte[] hashBytes = kdf.GetBytes(32);
            StringBuilder sb = new StringBuilder();
            foreach (byte b in hashBytes)
            {
                sb.Append(b.ToString("x2"));
            }
            return sb.ToString();
        }
    }

    public string AddWebsite(string websiteName, string configData)
    {
        try
        {
            string webConfigPath = Path.Combine(_directoryPath, $"{websiteName}.config");
            if (!File.Exists(webConfigPath))
            {
                Log.Warn($"Web.config file does not exist for {websiteName}");
                return null;
            }

            File.WriteAllText(webConfigPath, configData);
            Log.Info($"Website {websiteName} added successfully.");
            return webConfigPath;
        }
        catch (Exception ex)
        {
            Log.Error($"Error adding website {websiteName}: {ex.Message}", ex);
            throw;
        }
    }

    // Additional methods for hash storage management, incremental updates, external configuration integration,
    // performance monitoring, and horizontal scaling can be added here.
}
