using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json;

public class ConfigLoader
{
    private readonly HttpClient _httpClient;
    private readonly string _apiUrl;
    private readonly string _jsonFilePath;
    private readonly ILogger _logger;
    private Dictionary<string, object> _cachedConfig;
    private DateTime _lastCacheRefreshTime;

    public ConfigLoader(string apiUrl, string jsonFilePath, ILogger logger)
    {
        _apiUrl = apiUrl;
        _jsonFilePath = jsonFilePath;
        _logger = logger;
        _httpClient = new HttpClient();
        _cachedConfig = new Dictionary<string, object>();
        _lastCacheRefreshTime = DateTime.MinValue;
    }

    public async Task<Dictionary<string, object>> LoadConfigAsync()
    {
        try
        {
            var configFromApi = await FetchConfigFromApiAsync();
            if (configFromApi != null)
            {
                _cachedConfig = configFromApi;
                _lastCacheRefreshTime = DateTime.UtcNow;
                return configFromApi;
            }

            var configFromJson = LoadConfigFromJsonFile();
            if (configFromJson != null)
            {
                _cachedConfig = configFromJson;
                _lastCacheRefreshTime = DateTime.UtcNow;
                return configFromJson;
            }

            var configFromEnvVars = LoadConfigFromEnvironmentVariables();
            if (configFromEnvVars != null)
            {
                _cachedConfig = configFromEnvVars;
                _lastCacheRefreshTime = DateTime.UtcNow;
                return configFromEnvVars;
            }

            // Fallback to default values
            return new Dictionary<string, object>
            {
                { "Setting1", "Default1" },
                { "Setting2", "Default2" }
            };
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to load configuration");
            throw;
        }
    }

    private async Task<Dictionary<string, object>> FetchConfigFromApiAsync()
    {
        try
        {
            var response = await _httpClient.GetAsync(_apiUrl);
            if (response.IsSuccessStatusCode)
            {
                var jsonContent = await response.Content.ReadAsStringAsync();
                return JsonConvert.DeserializeObject<Dictionary<string, object>>(jsonContent);
            }
        }
        catch (Exception ex)
        {
            _logger.LogWarning(ex, "Failed to fetch config from API");
        }

        return null;
    }

    private Dictionary<string, object> LoadConfigFromJsonFile()
    {
        try
        {
            var jsonContent = System.IO.File.ReadAllText(_jsonFilePath);
            return JsonConvert.DeserializeObject<Dictionary<string, object>>(jsonContent);
        }
        catch (Exception ex)
        {
            _logger.LogWarning(ex, "Failed to load config from JSON file");
        }

        return null;
    }

    private Dictionary<string, object> LoadConfigFromEnvironmentVariables()
    {
        var envVars = Environment.GetEnvironmentVariables();
        return envVars.Cast<DictionaryEntry>().ToDictionary(e => e.Key.ToString(), e => e.Value);
    }
}

public interface ILogger
{
    void LogError(Exception ex, string message);
    void LogWarning(Exception ex, string message);
}
