const axios = require('axios');
const sharp = require('sharp');
const LRU = require('lru-cache');

// Initialize cache
const cache = new LRU({ max: 500, maxAge: 1000 * 60 * 60 }); // Cache up to 500 items for 1 hour

async function generateThumbnail(imageUrl) {
    try {
        // Check if thumbnail is already in cache
        const cachedThumbnail = cache.get(imageUrl);
        if (cachedThumbnail) {
            return { url: cachedThumbnail, statusCode: 200 };
        }

        // Fetch image from third-party API
        const response = await axios.get(imageUrl, { responseType: 'arraybuffer' });
        const buffer = Buffer.from(response.data, 'binary');

        // Resize and optimize the image using sharp
        const thumbnailBuffer = await sharp(buffer)
            .resize(200, 200) // Example size
            .png({ quality: 80 })
            .toBuffer();

        // Store thumbnail in cache
        cache.set(imageUrl, thumbnailBuffer);

        // Upload thumbnail to a storage service (e.g., AWS S3)
        const uploadResponse = await axios.post('https://your-storage-service.com/upload', thumbnailBuffer, {
            headers: { 'Content-Type': 'image/png' }
        });

        // Return the URL of the uploaded thumbnail
        return { url: uploadResponse.data.url, statusCode: 200 };
    } catch (error) {
        console.error('Error generating thumbnail:', error);
        return { url: null, statusCode: 500 };
    }
}

// Example usage
generateThumbnail('https://example.com/image.jpg')
    .then(result => console.log(result))
    .catch(error => console.error(error));
```

