use reqwest::Client;
use diesel::{prelude::*, Connection};
use tokio::sync::Mutex;
use std::collections::HashMap;
use std::time::{Duration, Instant};

// Define your database schema and models here

struct WeatherService {
    client: Client,
    db_connection: Mutex<Connection>,
    cache: Mutex<HashMap<String, String>>,
}

impl WeatherService {
    async fn new() -> Self {
        let client = Client::new();
        let db_connection = Connection::establish("your_database_url").unwrap();
        let cache = HashMap::new();

        WeatherService {
            client,
            db_connection: Mutex::new(db_connection),
            cache: Mutex::new(cache),
        }
    }

    async fn fetch_weather(&self, city: &str) -> Result<String, reqwest::Error> {
        if let Some(cached_data) = self.cache.lock().await.get(city) {
            return Ok(cached_data.clone());
        }

        let response = self.client.get(format!("https://api.weather.com/endpoint?city={}", city)).send().await?;
        let weather_data = response.text().await?;

        self.cache.lock().await.insert(city.to_string(), weather_data.clone());

        Ok(weather_data)
    }

    async fn update_database(&self, city: &str, weather_data: String) -> Result<(), diesel::result::Error> {
        use schema::weather_table::dsl::*;

        let connection = self.db_connection.lock().await;
        diesel::insert_into(weather_table)
            .values((city.eq(city), weather_data.eq(weather_data)))
            .on_conflict(city)
            .do_update()
            .set(weather_data.eq(weather_data))
            .execute(&*connection)?;

        Ok(())
    }

    async fn update_weather_for_city(&self, city: &str) -> Result<(), Box<dyn std::error::Error>> {
        let weather_data = self.fetch_weather(city).await?;
        self.update_database(city, weather_data).await?;

        Ok(())
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let service = WeatherService::new().await?;

    let cities = vec!["New York", "London", "Tokyo"];

    for city in cities {
        tokio::spawn(async move {
            if let Err(e) = service.update_weather_for_city(city).await {
                eprintln!("Failed to update weather for {}: {}", city, e);
            }
        });
    }

    Ok(())
}
```

