use std::fs;
use std::path::Path;

const QUOTA_LIMIT: u64 = 10 * 1024 * 1024 * 1024; // 10GB

fn create_directory_with_quota_check(dir_name: &str) -> Result<(), String> {
    let dir_path = Path::new(dir_name);

    if dir_path.exists() {
        return Err(format!("Directory {} already exists.", dir_name));
    }

    match fs::create_dir(&dir_path) {
        Ok(_) => {
            println!("Directory {} created successfully.", dir_name);
            Ok(())
        }
        Err(e) => Err(format!("Failed to create directory {}: {}", dir_name, e)),
    }
}

fn check_disk_usage_and_alert() -> Result<(), String> {
    // Simulate disk usage check
    let current_usage = 8 * 1024 * 1024 * 1024; // 8GB

    if current_usage + QUOTA_LIMIT / 10 < QUOTA_LIMIT {
        println!("Disk usage is within acceptable limits.");
        Ok(())
    } else {
        println!("Warning: Disk usage approaching quota limit. Current usage: {}GB, Quota limit: {}GB", current_usage / (1024 * 1024 * 1024), QUOTA_LIMIT / (1024 * 1024 * 1024));
        Ok(())
    }
}

fn main() {
    let dir_name = "new_directory";

    if check_disk_usage_and_alert().is_ok() {
        create_directory_with_quota_check(dir_name).unwrap();
    } else {
        println!("Disk usage is too high to create new directory.");
    }
}
