import json
import yaml
from abc import ABC, abstractmethod
from typing import Dict, Any, Callable, Optional

class Config(ABC):
    @abstractmethod
    def to_json(self) -> str:
        pass

    @abstractmethod
    def from_json(cls, data: str) -> 'Config':
        pass

    @abstractmethod
    def to_yaml(self) -> str:
        pass

    @abstractmethod
    def from_yaml(cls, data: str) -> 'Config':
        pass

class EnvironmentConfig(Config):
    def __init__(self, settings: Dict[str, Any]):
        self.settings = settings

    def to_json(self) -> str:
        return json.dumps(self.settings)

    @classmethod
    def from_json(cls, data: str) -> 'EnvironmentConfig':
        return cls(json.loads(data))

    def to_yaml(self) -> str:
        return yaml.dump(self.settings)

    @classmethod
    def from_yaml(cls, data: str) -> 'EnvironmentConfig':
        return cls(yaml.safe_load(data))

class ConfigFactoryRegistry:
    _registry: Dict[str, Callable[[], Config]] = {}

    @staticmethod
    def register_factory(env_id: str, factory_func: Callable[[], Config]):
        ConfigFactoryRegistry._registry[env_id] = factory_func

    @staticmethod
    def create_config(env_id: str) -> Optional[Config]:
        if env_id in ConfigFactoryRegistry._registry:
            return ConfigFactoryRegistry._registry[env_id]()
        else:
            # Fallback logic here
            return EnvironmentConfig({})

class ConfigManager:
    _default_settings: Dict[str, Any] = {}

    @staticmethod
    def set_default_settings(settings: Dict[str, Any]):
        ConfigManager._default_settings = settings

    @staticmethod
    def get_config(env_id: str) -> Config:
        config = ConfigFactoryRegistry.create_config(env_id)
        return EnvironmentConfig({**config.settings, **ConfigManager._default_settings})

# Example usage
class DevelopmentConfig(EnvironmentConfig):
    pass

class ProductionConfig(EnvironmentConfig):
    pass

ConfigFactoryRegistry.register_factory('development', DevelopmentConfig)
ConfigFactoryRegistry.register_factory('production', ProductionConfig)

ConfigManager.set_default_settings({'debug': True})

dev_config = ConfigManager.get_config('development')
prod_config = ConfigManager.get_config('production')

print(dev_config.settings)  # Output: {'debug': True}
print(prod_config.settings)  # Output: {'debug': True}
