typedef struct {
    int value;
    long *offset_ptr;
} record;

void manage_dynamic_memory(int initial_capacity) {
    if (initial_capacity <= 0) {
        fprintf(stderr, "Invalid capacity: %d\n", initial_capacity);
        return;
    }

    long *offsets = malloc(initial_capacity * sizeof(long));
    int *keys = malloc(initial_capacity * sizeof(int));
    record *records = malloc(initial_capacity * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    srand(time(NULL));

    for (int i = 0; i < initial_capacity; i++) {
        offsets[i] = rand() % 1000L;
        keys[i] = rand() % 100;
        records[i].value = rand() % 1000;
        records[i].offset_ptr = &offsets[i];
    }

    // Simulate dynamic resizing
    int new_capacity = initial_capacity * 2;
    long *new_offsets = realloc(offsets, new_capacity * sizeof(long));
    int *new_keys = realloc(keys, new_capacity * sizeof(int));
    record *new_records = realloc(records, new_capacity * sizeof(record));

    if (!new_offsets || !new_keys || !new_records) {
        fprintf(stderr, "Memory reallocation failed\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    offsets = new_offsets;
    keys = new_keys;
    records = new_records;

    // Update records with new pointers
    for (int i = initial_capacity; i < new_capacity; i++) {
        offsets[i] = rand() % 1000L;
        keys[i] = rand() % 100;
        records[i].value = rand() % 1000;
        records[i].offset_ptr = &offsets[i];
    }

    // Cleanup
    free(offsets);
    free(keys);
    free(records);
}
