typedef struct {
    // Define metadata structure here
} metadata;

typedef struct node {
    record *rec;
    metadata *meta;
    struct node *next;
} node;

typedef struct {
    node *head;
    node *tail;
    pthread_mutex_t lock;
    atomic_int size;
} thread_safe_queue;

void initialize_thread_safe_queue(thread_safe_queue *q) {
    q->head = q->tail = NULL;
    pthread_mutex_init(&q->lock, NULL);
    atomic_store(&q->size, 0);
}

void enqueue(thread_safe_queue *q, record *rec, metadata *meta) {
    node *new_node = (node *)malloc(sizeof(node));
    new_node->rec = rec;
    new_node->meta = meta;
    new_node->next = NULL;

    pthread_mutex_lock(&q->lock);
    if (q->tail == NULL) {
        q->head = q->tail = new_node;
    } else {
        q->tail->next = new_node;
        q->tail = new_node;
    }
    atomic_fetch_add(&q->size, 1);
    pthread_mutex_unlock(&q->lock);
}

record *dequeue(thread_safe_queue *q) {
    record *rec = NULL;

    pthread_mutex_lock(&q->lock);
    if (q->head != NULL) {
        node *temp = q->head;
        rec = temp->rec;
        q->head = temp->next;
        if (q->head == NULL) {
            q->tail = NULL;
        }
        free(temp);
        atomic_fetch_sub(&q->size, 1);
    }
    pthread_mutex_unlock(&q->lock);

    return rec;
}

