#include <pthread.h>
#include <stdatomic.h>

typedef struct {
    long timestamp;
    int key;
    double value;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t size;
    atomic_int ref_count;
    pthread_mutex_t lock;
} RecordPool;

RecordPool* create_record_pool(size_t initial_capacity) {
    RecordPool* pool = (RecordPool*)malloc(sizeof(RecordPool));
    if (!pool) return NULL;

    pool->records = (Record*)calloc(initial_capacity, sizeof(Record));
    if (!pool->records) {
        free(pool);
        return NULL;
    }

    pool->capacity = initial_capacity;
    pool->size = 0;
    atomic_init(&pool->ref_count, 1);
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void destroy_record_pool(RecordPool* pool) {
    if (atomic_fetch_sub(&pool->ref_count, 1) == 1) {
        free(pool->records);
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}

Record* allocate_record(RecordPool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->size >= pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        Record* new_records = (Record*)realloc(pool->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }
        pool->records = new_records;
        pool->capacity = new_capacity;
    }

    Record* record = &pool->records[pool->size++];
    pthread_mutex_unlock(&pool->lock);

