int isPrime(int num) {
    if (num <= 1) return 0;
    for (int i = 2; i * i <= num; ++i) {
        if (num % i == 0) return 0;
    }
    return 1;
}

int* allocateKeys(int numOffsets) {
    int* keys = (int*)malloc(numOffsets * sizeof(int));
    if (!keys) return NULL;
    int count = 0, candidate = 101;
    while (count < numOffsets) {
        if (isPrime(candidate)) {
            keys[count++] = candidate;
        }
        ++candidate;
    }
    return keys;
}

record* allocateRecords(int numRecords, int minValue, int maxValue) {
