typedef struct {
    long *offsets;
    int *keys;
    size_t capacity;
    size_t size;
} RecordCollection;

RecordCollection* create_record_collection(size_t initial_capacity) {
    RecordCollection *collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->capacity = initial_capacity;
    collection->size = 0;
    collection->offsets = (long*)calloc(initial_capacity, sizeof(long));
    collection->keys = (int*)calloc(initial_capacity, sizeof(int));

    if (!collection->offsets || !collection->keys) {
        free(collection);
        return NULL;
    }

    srand(time(NULL)); // Seed for random number generation
    return collection;
}

void destroy_record_collection(RecordCollection *collection) {
    if (collection) {
        free(collection->offsets);
        free(collection->keys);
        free(collection);
    }
}

int add_record(RecordCollection *collection, int key) {
    if (collection->size >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        long *new_offsets = (long*)realloc(collection->offsets, new_capacity * sizeof(long));
        int *new_keys = (int*)realloc(collection->keys, new_capacity * sizeof(int));

        if (!new_offsets || !new_keys) {
            return -1; // Memory allocation failed
        }

        collection->offsets = new_offsets;
        collection->keys = new_keys;
        collection->capacity = new_capacity;
    }

    collection->keys[collection->size] = key;
    collection->offsets[collection->size] = rand(); // Random offset for demonstration
    collection->size++;
    return 0; // Success
}

// Example usage:
int main() {
    RecordCollection *collection = create_record_collection(1000000);
    if (collection) {
        for (int i = 0; i < 5000000; i++) {
            add_record(collection, i);
        }
        destroy_record_collection(collection);
    }
    return 0;
}
