#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_FILES 10
#define MAX_THREADS 5
#define REPORT_FILE "output.txt"
#define COMMENT_CHAR '#'
#define MAX_LINE_LENGTH 1024

typedef struct {
    char *filename;
    FILE *file;
} FileData;

void* process_file(void* arg) {
    FileData *data = (FileData*)arg;
    FILE *report = fopen(REPORT_FILE, "a");
    if (!report) {
        perror("Failed to open report file");
        return NULL;
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), data->file)) {
        if (line[0] != COMMENT_CHAR) {
            // Process the line
            fprintf(report, "%s", line);
        }
    }

    fclose(data->file);
    fclose(report);
    free(data);
    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s [-o output_file] file1 [file2 ...]\n", argv[0]);
        return 1;
    }

    FILE *report = fopen(REPORT_FILE, "w");
    if (!report) {
        perror("Failed to open report file");
        return 1;
    }
    fclose(report);

    pthread_t threads[MAX_THREADS];
    int thread_count = 0;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-o") == 0) {
            // Skip the option and its value
            i++;
            continue;
        }

        if (thread_count >= MAX_THREADS) {
            printf("Maximum number of threads reached\n");
            break;
        }

        FileData *data = malloc(sizeof(FileData));
        data->filename = argv[i];
        data->file = fopen(data->filename, "r");
        if (!data->file) {
            perror("Failed to open file");
            free(data);
            continue;
        }

        pthread_create(&threads[thread_count], NULL, process_file, data);
        thread_count++;
    }

    for (int i = 0; i < thread_count; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
