#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef enum {
    DEBUG,
    INFO,
    WARNING,
    ERROR,
    CRITICAL
} LogLevel;

typedef struct LoggerConfig {
    LogLevel level;
    char format[20];
    FILE *logFile;
} LoggerConfig;

LoggerConfig* init_logger(LogLevel level, const char* format) {
    LoggerConfig* config = (LoggerConfig*)malloc(sizeof(LoggerConfig));
    config->level = level;
    strcpy(config->format, format);
    config->logFile = fopen("app.log", "a");
    return config;
}

void log_message(LoggerConfig* config, LogLevel level, const char* message) {
    if (level >= config->level) {
        fprintf(config->logFile, "[%s] %s\n", level == DEBUG ? "DEBUG" : 
            level == INFO ? "INFO" : level == WARNING ? "WARNING" : 
            level == ERROR ? "ERROR" : "CRITICAL", message);
    }
}

void close_logger(LoggerConfig* config) {
    fclose(config->logFile);
    free(config);
}
