```php
<?php
class UserManager {
    private $db;

    public function __construct($db) {
        $this->db = $db;
    }

    public function manageUser($_REQUEST) {
        $response = ['message' => 'error'];

        if (!isset($_REQUEST['name']) || !isset($_REQUEST['email']) || !isset($_REQUEST['password'])) {
            return json_encode($response);
        }

        $id = isset($_REQUEST['id']) ? intval($_REQUEST['id']) : null;
        $name = $_REQUEST['name'];
        $email = $_REQUEST['email'];
        $password = password_hash($_REQUEST['password'], PASSWORD_DEFAULT);

        if (isset($_REQUEST['sub_action']) && $_REQUEST['sub_action'] == 'delete') {
            if ($this->db->query("DELETE FROM users WHERE id = ?", [$id])) {
                $response['message'] = 'success';
            }
        } else {
            if ($id) {
                if ($this->db->query("UPDATE users SET name = ?, email = ?, password = ? WHERE id = ?", [$name, $email, $password, $id])) {
                    $response['message'] = 'success';
                }
            } else {
                if ($this->db->query("INSERT INTO users (name, email, password) VALUES (?, ?, ?)", [$name, $email, $password])) {
                    $response['message'] = 'success';
                }
            }
        }

        return json_encode($response);
    }
}

// Example usage:
$db = new PDO('mysql:host=localhost;dbname=yourdb', 'username', 'password');
$userManager = new UserManager($db);
echo $userManager->manageUser($_REQUEST);
?>
