        // Simulate parsing logic
        if (sscanf(buffer, "%ld,%d", &(*offsets)[count], &(*keys)[count]) == 2) {
            (*records)[count].value = rand() % 100; // Random value between 0 and 99
            count++;
        } else {
            fprintf(stderr, "Skipping corrupted record: %s", buffer);
        }

        if (count >= MAX_RECORDS) {
            break;
        }
