#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    int id;
    sem_t *sem;
} ProcessSemaphore;

typedef struct {
    pthread_mutex_t lock;
    int process_count;
    ProcessSemaphore *processes;
    int max_processes;
} SemaphoreManager;

SemaphoreManager *create_semaphore_manager(int initial_size) {
    SemaphoreManager *manager = (SemaphoreManager *)malloc(sizeof(SemaphoreManager));
    manager->lock = PTHREAD_MUTEX_INITIALIZER;
    manager->process_count = 0;
    manager->max_processes = initial_size;
    manager->processes = (ProcessSemaphore *)calloc(initial_size, sizeof(ProcessSemaphore));
    return manager;
}

int add_process_semaphore(SemaphoreManager *manager, int process_id, int initial_value) {
    pthread_mutex_lock(&manager->lock);
    if (manager->process_count >= manager->max_processes) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Error: Manager is full
    }
    for (int i = 0; i < manager->process_count; i++) {
        if (manager->processes[i].id == process_id) {
            pthread_mutex_unlock(&manager->lock);
            return -2; // Error: Process ID already exists
        }
    }
    int index = manager->process_count;
    manager->processes[index].id = process_id;
    manager->processes[index].sem = (sem_t *)malloc(sizeof(sem_t));
    sem_init(manager->processes[index].sem, 0, initial_value);
    manager->process_count++;
    pthread_mutex_unlock(&manager->lock);
    return index;
}

void remove_process_semaphore(SemaphoreManager *manager, int process_id) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->process_count; i++) {
        if (manager->processes[i].id == process_id) {
            sem_destroy(manager->processes[i].sem);
            free(manager->processes[i].sem);
            for (int j = i; j < manager->process_count - 1; j++) {
                manager->processes[j] = manager->processes[j + 1];
            }
            manager->process_count--;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void signal_semaphore(SemaphoreManager *manager, int process_id) {
    for (int i = 0; i < manager->process_count; i++) {
        if (manager->processes[i].id == process_id) {
            sem_post(manager->processes[i].sem);
            break;
        }
    }
}

void wait_semaphore(SemaphoreManager *manager, int process_id, struct timespec *timeout) {
    for (int i = 0; i < manager->process_count; i++) {
        if (manager->processes[i].id == process_id) {
            sem_timedwait(manager->processes[i].sem, timeout);
            break;
        }
    }
}

void destroy_semaphore_manager(SemaphoreManager *manager) {
    for (int i = 0; i < manager->process_count; i++) {
        sem_destroy(manager->processes[i].sem);
        free(manager->processes[i].sem);
    }
    free(manager->processes);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
