#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <random>
#include <chrono>
#include <functional>

namespace MathUtils {
    class RandomPool {
    public:
        struct Config {
            uint64_t initialSeed;
            size_t poolSize;
            std::string distributionType; // "uniform", "normal"
        };

        RandomPool(const Config& config) : config_(config), refreshInterval_(std::chrono::seconds(10)) {
            initializePool();
        }

        ~RandomPool() {
            for (auto& gen : generators_) {
                delete gen;
            }
        }

        std::vector<double> generate(size_t count) {
            std::lock_guard<std::mutex> lock(mutex_);
            refreshIfNeeded();

            std::vector<double> results(count);
            for (size_t i = 0; i < count; ++i) {
                auto& gen = generators_[threadId_];
                if (config_.distributionType == "uniform") {
                    results[i] = gen->generateUniform();
                } else if (config_.distributionType == "normal") {
                    results[i] = gen->generateNormal();
                }
            }

            return results;
        }

    private:
        struct Generator {
            std::mt19937 engine;
            std::uniform_real_distribution<double> uniformDist;
            std::normal_distribution<double> normalDist;

            Generator(uint64_t seed) : engine(seed), uniformDist(0.0, 1.0), normalDist(0.0, 1.0) {}

            double generateUniform() {
                return uniformDist(engine);
            }

            double generateNormal() {
                return normalDist(engine);
            }
        };

        void initializePool() {
            for (size_t i = 0; i < config_.poolSize; ++i) {
                uint64_t seed = calculateSeed(i);
                generators_.push_back(new Generator(seed));
            }
        }

        uint64_t calculateSeed(size_t index) {
            auto now = std::chrono::system_clock::now().time_since_epoch().count();
            return config_.initialSeed + index * 131 + now * 31;
        }

        void refreshIfNeeded() {
            auto now = std::chrono::steady_clock::now();
            if (now - lastRefresh_ > refreshInterval_) {
                refreshPool();
                lastRefresh_ = now;
            }
        }

        void refreshPool() {
            for (auto& gen : generators_) {
                delete gen;
            }
            generators_.clear();
            initializePool();
        }

        Config config_;
        std::vector<Generator*> generators_;
        std::mutex mutex_;
        std::chrono::steady_clock::time_point lastRefresh_ = std::chrono::steady_clock::now();
        size_t threadId_ = std::hash<std::thread::id>{}(std::this_thread::get_id());
    };
}

int main() {
    MathUtils::RandomPool::Config config = {12345, 10, "uniform"};
    MathUtils::RandomPool pool(config);

    auto results = pool.generate(10);
    for (auto num : results) {
        std::cout << num << " ";
    }
    std::cout << std::endl;

    return 0;
}
