using System;
using System.IO;
using Newtonsoft.Json;

public class VRConfig
{
    public int ResolutionWidth { get; set; } = 1920;
    public int ResolutionHeight { get; set; } = 1080;
    public int MaxUsers { get; set; } = 10;
    public Dictionary<string, int> UserEnergyLevels { get; set; } = new Dictionary<string, int>();
    public List<Vector3> SpawnPoints { get; set; } = new List<Vector3>();

    public VRConfig LoadFromJson(string filePath)
    {
        if (!File.Exists(filePath))
        {
            Log("Configuration file not found. Using default settings.");
            return this;
        }

        try
        {
            string jsonContent = File.ReadAllText(filePath);
            VRConfig config = JsonConvert.DeserializeObject<VRConfig>(jsonContent);

            // Validate and apply configuration
            if (config.ResolutionWidth <= 0) config.ResolutionWidth = ResolutionWidth;
            if (config.ResolutionHeight <= 0) config.ResolutionHeight = ResolutionHeight;
            if (config.MaxUsers <= 0) config.MaxUsers = MaxUsers;

            foreach (var user in UserEnergyLevels)
            {
                if (!config.UserEnergyLevels.ContainsKey(user.Key))
                    config.UserEnergyLevels[user.Key] = user.Value;
            }

            SpawnPoints.AddRange(config.SpawnPoints);

            Log("Configuration loaded successfully.");
            return config;
        }
        catch (Exception ex)
        {
            Log($"Error loading configuration: {ex.Message}");
            return this; // Return default settings
        }
    }

    private void Log(string message)
    {
        Console.WriteLine(message);
    }
}

public class Vector3
{
    public float X { get; set; }
    public float Y { get; set; }
    public float Z { get; set; }
}
