use std::env;
use std::fs;
use std::path::Path;

fn create_directory_and_set_env_var(dir_name: &str, env_var_name: &str) {
    let dir_path = Path::new(dir_name);

    if dir_path.exists() && dir_path.is_dir() {
        if let Ok(path_str) = env::var(env_var_name) {
            println!("Environment variable {} already set to {}", env_var_name, path_str);
            return;
        }
    }

    match fs::create_dir_all(dir_path) {
        Ok(_) => {
            println!("Directory created successfully: {:?}", dir_path);
            if let Err(e) = env::set_var(env_var_name, dir_path.display()) {
                eprintln!("Failed to set environment variable {}: {}", env_var_name, e);
            }
        },
        Err(e) => eprintln!("Failed to create directory {}: {}", dir_path.display(), e),
    }
}
