    {
        _httpClient = httpClient;
        _lockManager = lockManager;
    }

    public async Task<UpdateResponse> UpdateElementAsync(int pageSectionId, string elementId, string htmlContent, string revisionNote)
    {
        try
        {
            using (var lockHandle = await _lockManager.AcquireLockAsync(elementId))
            {
                if (lockHandle == null)
                {
                    return new UpdateResponse { RefreshPage = false, ErrorMessage = "Failed to acquire lock" };
                }

                // Simulate service call to update element content
                var updateResult = await UpdateElementContentAsync(pageSectionId, elementId, htmlContent);
                if (!updateResult.Success)
                {
                    return new UpdateResponse { RefreshPage = false, ErrorMessage = updateResult.ErrorMessage };
                }

                // Apply revision note and log change
                LogRevisionNote(elementId, revisionNote);

                return new UpdateResponse { RefreshPage = true };
            }
        }
        catch (Exception ex)
        {
            // Log exception details
            Console.WriteLine($"Error updating element: {ex.Message}");
            return new UpdateResponse { RefreshPage = false, ErrorMessage = "Internal server error" };
        }
    }

