using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

public class IdentityManagementService
{
    private Dictionary<string, UserAccount> _userAccounts = new Dictionary<string, UserAccount>();
    private ILogger _logger;
    private ICacheProvider _cacheProvider;

    public IdentityManagementService(ILogger logger, ICacheProvider cacheProvider)
    {
        _logger = logger;
        _cacheProvider = cacheProvider;
    }

    public async Task<bool> AuthenticateUserAsync(string username, string password)
    {
        if (!_userAccounts.ContainsKey(username))
        {
            _logger.Log("Authentication failed: User not found.");
            return false;
        }

        var userAccount = _userAccounts[username];
        if (userAccount.IsLockedOut)
        {
            _logger.Log("Authentication failed: Account is locked out.");
            return false;
        }

        if (!userAccount.VerifyPassword(password))
        {
            _logger.Log("Authentication failed: Incorrect password.");
            await IncrementFailedLoginAttemptsAsync(username);
            return false;
        }

        ResetFailedLoginAttemptsAsync(username);
        _cacheProvider.SetUserToken(username, userAccount.GenerateToken());
        _logger.Log("Authentication successful.");
        return true;
    }

    public async Task LockoutUserAsync(string username)
    {
        if (!_userAccounts.ContainsKey(username))
        {
            _logger.Log("Lockout failed: User not found.");
            return;
        }

        var userAccount = _userAccounts[username];
        userAccount.LockOut();
        await _cacheProvider.SetUserLockoutStatusAsync(username, true);
        _logger.Log($"Account locked out for {userAccount.LockoutPeriod} minutes.");
    }

    public async Task UnlockUserAsync(string username)
    {
        if (!_userAccounts.ContainsKey(username))
        {
            _logger.Log("Unlock failed: User not found.");
            return;
        }

        var userAccount = _userAccounts[username];
        userAccount.Unlock();
        await _cacheProvider.SetUserLockoutStatusAsync(username, false);
        _logger.Log("Account unlocked.");
    }

    public async Task AddMFAOptionAsync(string username, MFAOption mfaOption)
    {
        if (!_userAccounts.ContainsKey(username))
        {
            _logger.Log("Adding MFA option failed: User not found.");
            return;
        }

        var userAccount = _userAccounts[username];
        userAccount.AddMFAOption(mfaOption);
        await _cacheProvider.SetUserMFADetailsAsync(username, mfaOption);
        _logger.Log($"MFA option added for {username}: {mfaOption.Type}");
    }

    private async Task IncrementFailedLoginAttemptsAsync(string username)
    {
        var failedAttempts = await _cacheProvider.GetFailedLoginAttemptsAsync(username) ?? 0;
        failedAttempts++;
        await _cacheProvider.SetFailedLoginAttemptsAsync(username, failedAttempts);
    }

    private async Task ResetFailedLoginAttemptsAsync(string username)
    {
        await _cacheProvider.SetFailedLoginAttemptsAsync(username, 0);
    }
}

