import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class ConfigCacheManager {
    private final ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();
    private final Lock lock = new ReentrantLock();
    private final ConfigurationService configService;

    public ConfigCacheManager(ConfigurationService configService) {
        this.configService = configService;
    }

    public String getConfig(String key) {
        lock.lock();
        try {
            if (cache.containsKey(key)) {
                return cache.get(key);
            } else {
                String value = fetchConfigFromService(key);
                if (value != null) {
                    cache.put(key, value);
                }
                return value;
            }
        } finally {
            lock.unlock();
        }
    }

    private String fetchConfigFromService(String key) {
        try {
            return configService.getConfig(key);
        } catch (Exception e) {
            // Log the error and fall back to a default value or handle it gracefully
            return null;
        }
    }

    public void updateConfig(String key, String value) {
        lock.lock();
        try {
            cache.put(key, value);
            configService.updateConfig(key, value);
        } finally {
            lock.unlock();
        }
    }

    // Additional methods for monitoring, logging, and testing can be added here
}
