["```javascript
const https = require('https');
const fs = require('fs');
const crypto = require('crypto');
const zlib = require('zlib');

class OAuthCertificateManager {
  constructor(options) {
    this.options = options;
    this.cache = new Map();
    this.log = this.createLogger(options.logLevel);
  }

  async retrieveCertificates() {
    const url = this.options.certificateUrl;
    if (this.cache.has(url)) {
      return this.cache.get(url);
    }
    try {
      const response = await this.makeRequest(url, { method: 'GET' });
      const data = await this.validateAndCache(response.data, url);
      return data;
    } catch (error) {
      this.log.error('Failed to retrieve certificates:', error);
      throw error;
    }
  }

  async validateAndCache(data, url) {
    if (!this.options.trustedCAs.includes(data.issuer)) {
      throw new Error('Untrusted certificate issuer');
    }
    const cacheKey = `cert-${crypto.randomBytes(16).toString('hex')}`;
    this.cache.set(url, { data, cacheKey });
    return { ...data, cacheKey };
  }

  async makeRequest(url, options) {
    return new Promise((resolve, reject) => {
      https.request(url, options, (res) => {
        if (res.statusCode !== 200) {
          reject(new Error(`HTTP error! status: ${res.statusCode}`));
        }
        const chunks = [];
        res.on('data', (chunk) => chunks.push(chunk));
        res.on('end', () => resolve(Buffer.concat(chunks)));
      }).on('error', (err) => reject(err)).end();
    });
  }

  createLogger(level) {
    return {
      info: (message) => level === 'info' && console.log(message),
      error: (message) => level === 'error' && console.error(message)
    };
  }
}

module.exports = OAuthCertificateManager;
