#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int key;
    char buffer[256];
    double timestamp;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} RecordManager;

RecordManager* record_manager_init(size_t initial_capacity) {
    RecordManager *manager = (RecordManager*)malloc(sizeof(RecordManager));
    if (!manager) {
        // Log memory allocation failure
        return NULL;
    }
    manager->records = (Record*)calloc(initial_capacity, sizeof(Record));
    if (!manager->records) {
        // Log memory allocation failure
        free(manager);
        return NULL;
    }
    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void record_manager_add(RecordManager *manager, int key, const char *buffer) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->capacity) {
        // Trigger garbage collection
        // ...
    }
    Record *record = &manager->records[manager->count++];
    record->key = key;
    strncpy(record->buffer, buffer, sizeof(record->buffer));
    record->timestamp = time(NULL);
    pthread_mutex_unlock(&manager->lock);
}

Record* record_manager_get(RecordManager *manager, int key) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->records[i].key == key) {
            Record *record = &manager->records[i];
            pthread_mutex_unlock(&manager->lock);
            return record;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

void record_manager_free(RecordManager *manager) {
    pthread_mutex_lock(&manager->lock);
    free(manager->records);
    manager->records = NULL;
    manager->capacity = 0;
    manager->count = 0;
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

// Example usage
int main() {
    RecordManager *manager = record_manager_init(1024);
    if (!manager) {
        // Handle initialization failure
        return -1;
    }

    record_manager_add(manager, 1, "Record 1");
    record_manager_add(manager, 2, "Record 2");

    Record *record = record_manager_get(manager, 1);
    if (record) {
        printf("Key: %d, Buffer: %s, Timestamp: %f\n", record->key, record->buffer, record->timestamp);
    }

    record_manager_free(manager);
    return 0;
}
