async function manageTestSuite(label, modules, parallel, maxConcurrency, timeout) {
  console.log(`Starting test suite: ${label}`);

  for (const module of modules) {
    const moduleName = module.name;
    console.log(`Loading module: ${moduleName}`);

    try {
      const moduleInstance = require(moduleName);
      await runTests(moduleName, module.tests, parallel, maxConcurrency, timeout);
    } catch (error) {
      console.error(`Failed to load module ${moduleName}:`, error);
    }
  }

  console.log('Test suite completed.');
}

async function runTests(moduleName, tests, parallel, maxConcurrency, timeout) {
  const results = [];
  let concurrencyCount = 0;

  for (const test of tests) {
    if (parallel && concurrencyCount < maxConcurrency) {
      concurrencyCount++;
      await new Promise((resolve, reject) => {
        setTimeout(async () => {
          try {
            const result = await runTest(test);
            results.push(result);
            resolve();
          } catch (error) {
            results.push({ error });
            reject(error);
          }
        }, 0);
      }).catch(console.error);
    } else {
      const result = await runTest(test);
      results.push(result);
    }
  }

  if (parallel) {
    await Promise.allSettled(results.map((result, index) => {
      return new Promise(async (resolve) => {
        setTimeout(async () => {
          try {
            await blueslip.reset();
            console.log(`Module: ${moduleName}, Test: ${tests[index].name}, Duration: ${result.duration}ms`);
            resolve();
          } catch (error) {
            console.error(`Failed to reset module ${moduleName}:`, error);
            resolve();
          }
        }, 0);
      });
    }));
  }

  return results;
}

async function runTest(testFunction) {
  const startTime = Date.now();
  try {
    await testFunction();
    return { passed: true, duration: Date.now() - startTime };
  } catch (error) {
    return { error, duration: Date.now() - startTime };
  }
}
