#include <sys/time.h>

#define MAX_CONNECTIONS 100

typedef struct {
    int id;
    double latency;
    size_t size;
} Request;

typedef struct {
    int id;
    char address[256];
    pthread_t thread_id;
    int connected;
    time_t last_attempt;
} Connection;

Connection connections[MAX_CONNECTIONS];
int connection_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* monitor_connection(void* arg) {
    Connection* conn = (Connection*)arg;
    while (1) {
        pthread_mutex_lock(&lock);
        if (!conn->connected) {
            time_t now = time(NULL);
            if (now - conn->last_attempt > 5) { // Retry after 5 seconds
                // Attempt to reconnect
                printf("Reconnecting to %s\n", conn->address);
                conn->connected = 1; // Simulate successful connection
                conn->last_attempt = now;
            }
        }
        pthread_mutex_unlock(&lock);
        sleep(1); // Check every second
    }
}

int processAndTrackRequests(Request* requests, int count) {
    pthread_t threads[MAX_CONNECTIONS];
    for (int i = 0; i < count; i++) {
        Connection conn;
        conn.id = requests[i].id;
        strcpy(conn.address, "remote_address");
        conn.connected = 1; // Simulate initial connection
        conn.last_attempt = time(NULL);
        connections[connection_count++] = conn;

        pthread_create(&threads[i], NULL, monitor_connection, &connections[i]);
    }

    size_t max_size = 0;
    int max_id = -1;
    for (int i = 0; i < count; i++) {
        if (requests[i].size > max_size) {
            max_size = requests[i].size;
            max_id = requests[i].id;
        }
    }

    return max_id;
}

int main() {
    Request requests[] = {{1, 0.5, 1024}, {2, 0.3, 2048}, {3, 0.7, 512}};
    int count = sizeof(requests) / sizeof(requests[0]);
    int max_id = processAndTrackRequests(requests, count);
    printf("Max size request ID: %d\n", max_id);
    return 0;
}
