#include <iostream>
#include <vector>
#include <string>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <random>
#include <unordered_map>

struct Record {
    int value;
    int* key;
};

class HTTPClient {
public:
    HTTPClient(int initialCapacity = 10) : capacity(initialCapacity), size(0), records(capacity), keys(new int[capacity]) {}

    ~HTTPClient() {
        delete[] keys;
        for (auto& record : records) {
            delete record.key;
        }
    }

    void addRecord(int value, int key) {
        std::lock_guard<std::mutex> lock(mutex);
        if (size == capacity) {
            resize();
        }
        records[size].value = value;
        records[size].key = new int(key);
        keys[size] = key;
        ++size;
    }

    void get(const std::string& url) {
        // Simulate GET request
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
        std::cout << "GET request to " << url << std::endl;
    }

    void post(const std::string& url, const std::string& data) {
        // Simulate POST request
        std::this_thread::sleep_for(std::chrono::milliseconds(200));
        std::cout << "POST request to " << url << " with data: " << data << std::endl;
    }

private:
    void resize() {
        capacity = static_cast<int>(capacity * 1.1);
        Record* newRecords = new Record[capacity];
        int* newKeys = new int[capacity];

        for (int i = 0; i < size; ++i) {
            newRecords[i] = records[i];
            newKeys[i] = keys[i];
        }

        delete[] records;
        delete[] keys;

        records = newRecords;
        keys = newKeys;
    }

    int capacity;
    int size;
    Record* records;
    int* keys;
    std::mutex mutex;
};

int main() {
    HTTPClient client;
    client.addRecord(1, 10);
    client.addRecord(2, 20);

    std::thread t1(&HTTPClient::get, &client, "http://example.com");
    std::thread t2(&HTTPClient::post, &client, "http://example.com", "data");

    t1.join();
    t2.join();

    return 0;
}
