#include <iostream>
#include <string>
#include <unordered_map>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <random>
#include <fstream>

class DynamicRandomContextManager {
public:
    struct ContextConfig {
        std::string key;
        double minRange, maxRange;
        bool isInteger;
        int seed = 0;
    };

    struct AccessLogEntry {
        std::string contextKey;
        size_t accessCount;
    };

private:
    std::unordered_map<std::string, std::mt19937> generators;
    std::unordered_map<std::string, ContextConfig> configs;
    std::mutex logMutex;
    std::queue<AccessLogEntry> accessLog;
    const size_t logBufferSize = 100;

public:
    DynamicRandomContextManager() {}

    void addContext(const ContextConfig& config) {
        std::lock_guard<std::mutex> lock(logMutex);
        if (config.seed == 0) {
            config.seed = std::random_device{}();
        }
        generators[config.key] = std::mt19937(config.seed);
        configs[config.key] = config;
    }

    void logAccess(const std::string& contextKey) {
        std::lock_guard<std::mutex> lock(logMutex);
        accessLog.push({contextKey, 1});
        if (accessLog.size() > logBufferSize) {
            accessLog.pop();
        }
    }

    double getRandomNumber(const std::string& contextKey) {
        std::lock_guard<std::mutex> lock(logMutex);
        auto& config = configs[contextKey];
        if (config.isInteger) {
            return static_cast<double>(generators[contextKey]()) / (std::mt19937::max() - 1.0) * (config.maxRange - config.minRange + 1) + config.minRange;
        } else {
            return static_cast<double>(generators[contextKey]()) / std::mt19937::max() * (config.maxRange - config.minRange) + config.minRange;
        }
    }

    void dumpLogToFile(const std::string& filename) {
        std::ofstream file(filename);
        if (!file.is_open()) {
            std::cerr << "Failed to open log file: " << filename << std::endl;
            return;
        }
        std::lock_guard<std::mutex> lock(logMutex);
        while (!accessLog.empty()) {
            auto entry = accessLog.front();
            file << "Context: " << entry.contextKey << ", Accesses: " << entry.accessCount << std::endl;
            accessLog.pop();
        }
    }

    void monitorHealth() {
        // Implement health monitoring logic here
    }
};
