typedef struct {
    int id;
    time_t last_activity;
    char *packet_buffer;
    size_t buffer_size;
    char src_ip[16];
    char dst_ip[16];
} NetworkConnection;

typedef struct {
    NetworkConnection *connections;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} ConnectionManager;

ConnectionManager* create_connection_manager(size_t initial_capacity) {
    if (initial_capacity == 0) {
        return NULL; // Error handling for zero or negative initial capacity
    }
    ConnectionManager *manager = malloc(sizeof(ConnectionManager));
    if (!manager) {
        return NULL; // Handle memory allocation failure
    }
    manager->connections = malloc(initial_capacity * sizeof(NetworkConnection));
    if (!manager->connections) {
        free(manager);
        return NULL; // Handle memory allocation failure
    }
    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_connection_manager(ConnectionManager *manager) {
    if (!manager) {
        return;
    }
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->connections[i].packet_buffer);
    }
    free(manager->connections);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void resize_connection_manager(ConnectionManager *manager, size_t new_capacity) {
    if (!manager || new_capacity <= manager->capacity) {
        return;
    }
    NetworkConnection *new_connections = realloc(manager->connections, new_capacity * sizeof(NetworkConnection));
    if (!new_connections) {
        // Handle memory allocation failure
        return;
    }
    manager->connections = new_connections;
    manager->capacity = new_capacity;
}

void add_connection(ConnectionManager *manager, int id, char *src_ip, char *dst_ip, size_t packet_size) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->capacity) {
        resize_connection_manager(manager, manager->capacity * 2); // Double the capacity
    }
    NetworkConnection *new_conn = &manager->connections[manager->count++];
    new_conn->id = id;
    new_conn->last_activity = time(NULL);
    new_conn->packet_buffer = malloc(packet_size);
    if (!new_conn->packet_buffer) {
        // Handle memory allocation failure
        manager->count--; // Decrement count to maintain consistency
        pthread_mutex_unlock(&manager->lock);
        return;
    }
    new_conn->buffer_size = packet_size;
    strncpy(new_conn->src_ip, src_ip, sizeof(new_conn->src_ip));
    strncpy(new_conn->dst_ip, dst_ip, sizeof(new_conn->dst_ip));
    pthread_mutex_unlock(&manager->lock);
}

void update_connection(ConnectionManager *manager, int id, char *packet_data, size_t packet_size) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->connections[i].id == id) {
            if (packet_size > manager->connections[i].buffer_size) {
                char *new_buffer = realloc(manager->connections[i].packet_buffer, packet_size);
                if (!new_buffer) {
                    // Handle memory allocation failure
                    pthread_mutex_unlock(&manager->lock);
                    return;
                }
                manager->connections[i].packet_buffer = new_buffer;
                manager->connections[i].buffer_size = packet_size;
            }
            memcpy(manager->connections[i].packet_buffer, packet_data, packet_size);
            manager->connections[i].last_activity = time(NULL);
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

