#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int connection_id;
    time_t last_activity;
    char* packet_buffer;
} NetworkConnection;

typedef struct {
    long timestamp;
    int key;
    double value;
} Record;

typedef struct {
    NetworkConnection** connections;
    Record** records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} ConnectionManager;

ConnectionManager* create_connection_manager(size_t initial_capacity) {
    ConnectionManager* manager = (ConnectionManager*)malloc(sizeof(ConnectionManager));
    if (!manager) return NULL;

    manager->connections = (NetworkConnection**)calloc(initial_capacity, sizeof(NetworkConnection*));
    manager->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_connection_manager(ConnectionManager* manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->size; ++i) {
        free(manager->connections[i]->packet_buffer);
        free(manager->connections[i]);
        free(manager->records[i]);
    }

    free(manager->connections);
    free(manager->records);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void resize_connection_manager(ConnectionManager* manager, size_t new_capacity) {
    if (!manager || new_capacity <= manager->capacity) return;

    NetworkConnection** new_connections = (NetworkConnection**)realloc(manager->connections, new_capacity * sizeof(NetworkConnection*));
    Record** new_records = (Record**)realloc(manager->records, new_capacity * sizeof(Record*));

    if (!new_connections || !new_records) {
        // Handle memory allocation failure
        return;
    }

    manager->connections = new_connections;
    manager->records = new_records;
    manager->capacity = new_capacity;
}

void update_connection_activity(ConnectionManager* manager, int connection_id, time_t timestamp) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->connections[i]->connection_id == connection_id) {
            manager->connections[i]->last_activity = timestamp;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void add_record(ConnectionManager* manager, long timestamp, int key, double value) {
    pthread_mutex_lock(&manager->lock);
    if (manager->size == manager->capacity) {
        resize_connection_manager(manager, manager->capacity * 2);
    }

    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) {
        // Handle memory allocation failure
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    record->timestamp = timestamp;
    record->key = key;
    record->value = value;

    manager->records[manager->size++] = record;
    pthread_mutex_unlock(&manager->lock);
}

void generate_random_records(ConnectionManager* manager, size_t count) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < count; ++i) {
        if (manager->size == manager->capacity) {
            resize_connection_manager(manager, manager->capacity * 2);
        }

        Record* record = (Record*)malloc(sizeof(Record));
        if (!record) {
            // Handle memory allocation failure
            pthread_mutex_unlock(&manager->lock);
            return;
        }

        record->timestamp = time(NULL);
        record->key = rand() % 1000; // Example range for key
        record->value = (double)(rand() % 100) / 10.0; // Example range for value

        manager->records[manager->size++] = record;
    }
    pthread_mutex_unlock(&manager->lock);
}
