DynamicList* create_list(size_t initial_capacity, size_t max_entries) {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->data = (CustomData*)calloc(initial_capacity, sizeof(CustomData));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->count = 0;
    list->limit = max_entries;

    return list;
}

void destroy_list(DynamicList* list) {
