        free(list->data[i].address);
    }
    free(list->data);
    free(list);
}

int add_entry(DynamicList* list, const char* name, int age, void* address) {
    if (list->count >= list->limit) return -1;

    if (strlen(name) > MAX_NAME_LENGTH) return -2;

    for (size_t i = 0; i < list->count; ++i) {
        if (strcmp(list->data[i].name, name) == 0) return -3;
    }

    CustomData* new_entry = &list->data[list->count++];
    strcpy(new_entry->name, name);
    new_entry->age = age;
    new_entry->address = address;

    return 0;
}

void* get_address_by_name(DynamicList* list, const char* name) {
    for (size_t i = 0; i < list->count; ++i) {
        if (strcmp(list->data[i].name, name) == 0) {
            return list->data[i].address;
        }
    }
    return NULL;
}

int main() {
    DynamicList* list = create_list(INITIAL_CAPACITY, MAX_ENTRIES);
    if (!list) {
        fprintf(stderr, "Failed to create list\n");
        return 1;
    }

    // Example usage
    void* address1 = malloc(sizeof(int));
    void* address2 = malloc(sizeof(double));

    add_entry(list, "Alice", 30, address1);
    add_entry(list, "Bob", 25, address2);

    void* retrieved_address = get_address_by_name(list, "Alice");
    if (retrieved_address) {
        printf("Retrieved address for Alice: %p\n", retrieved_address);
    } else {
        printf("Address not found for Alice\n");
    }

    destroy_list(list);
    return 0;
}
