#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INITIAL_CAPACITY 10
#define MAX_NAME_LENGTH 256
#define MAX_EMAIL_LENGTH 256

typedef struct {
    char name[MAX_NAME_LENGTH];
    char email[MAX_EMAIL_LENGTH];
    void* address;
} Entry;

typedef struct {
    Entry* entries;
    size_t capacity;
    size_t count;
    size_t limit;
} List;

List* list_init(size_t initial_capacity, size_t limit) {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;

    list->entries = (Entry*)calloc(initial_capacity, sizeof(Entry));
    if (!list->entries) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->count = 0;
    list->limit = limit;

    return list;
}

void list_free(List* list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->entries[i].name);
        free(list->entries[i].email);
        free(list->entries[i].address);
    }
    free(list->entries);
    free(list);
}

int list_add(List* list, const char* name, const char* email, void* address) {
    if (list->count >= list->limit) return -1; // Limit reached

    size_t hash = 0;
    for (size_t i = 0; name[i]; ++i) {
        hash += name[i];
    }

    size_t index = hash % list->capacity;
    while (list->entries[index].name[0] != '\0' && strcmp(list->entries[index].name, name)) {
        index = (index + 1) % list->capacity;
    }

    if (list->entries[index].name[0] != '\0') return -2; // Duplicate entry

    strcpy(list->entries[index].name, name);
    strcpy(list->entries[index].email, email);
    list->entries[index].address = address;

    ++list->count;

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        Entry* new_entries = (Entry*)realloc(list->entries, new_capacity * sizeof(Entry));
        if (!new_entries) return -3; // Memory allocation failed

        list->entries = new_entries;
        list->capacity = new_capacity;
    }

    return 0;
}

void* list_get_address(List* list, const char* name, const char* email) {
    size_t hash = 0;
    for (size_t i = 0; name[i]; ++i) {
        hash += name[i];
    }

    size_t index = hash % list->capacity;
    while (list->entries[index].name[0] != '\0' && strcmp(list->entries[index].name, name)) {
        index = (index + 1) % list->capacity;
    }

    if (list->entries[index].name[0] == '\0') return NULL; // Entry not found

    if (strcmp(list->entries[index].email, email) != 0) return NULL; // Mismatched email

    return list->entries[index].address;
}
