#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_LOG_SIZE 1024

typedef struct {
    char *log_message;
    int log_level;
} LogEntry;

typedef struct {
    LogEntry buffer[MAX_LOG_SIZE];
    int head, tail, count;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} LoggerQueue;

LoggerQueue logger_queue;

void init_logger() {
    memset(&logger_queue, 0, sizeof(LoggerQueue));
    pthread_mutex_init(&logger_queue.mutex, NULL);
    pthread_cond_init(&logger_queue.cond, NULL);
}

void enqueue_log(LogEntry entry) {
    pthread_mutex_lock(&logger_queue.mutex);
    while (logger_queue.count == MAX_LOG_SIZE) {
        pthread_cond_wait(&logger_queue.cond, &logger_queue.mutex);
    }
    logger_queue.buffer[logger_queue.tail] = entry;
    logger_queue.tail = (logger_queue.tail + 1) % MAX_LOG_SIZE;
    logger_queue.count++;
    pthread_mutex_unlock(&logger_queue.mutex);
    pthread_cond_signal(&logger_queue.cond);
}

void *log_thread(void *arg) {
    while (1) {
        LogEntry entry;
        pthread_mutex_lock(&logger_queue.mutex);
        while (logger_queue.count == 0) {
            pthread_cond_wait(&logger_queue.cond, &logger_queue.mutex);
        }
        entry = logger_queue.buffer[logger_queue.head];
        logger_queue.head = (logger_queue.head + 1) % MAX_LOG_SIZE;
        logger_queue.count--;
        pthread_mutex_unlock(&logger_queue.mutex);

        // Log the message to a file or external service
        printf("Log Level: %d, Message: %s\n", entry.log_level, entry.log_message);
    }
}

int main() {
    init_logger();
    pthread_t log_tid;
    pthread_create(&log_tid, NULL, log_thread, NULL);

    // Example usage
    LogEntry entry1 = {"User logged in", 1};
    enqueue_log(entry1);

    LogEntry entry2 = {"Error occurred", 3};
    enqueue_log(entry2);

    pthread_join(log_tid, NULL);
    return 0;
}
