void init_record_manager(RecordManager* manager, size_t initial_capacity, size_t max_records) {
    manager->records = (Record*)aligned_alloc(64, initial_capacity * sizeof(Record));
    if (!manager->records) {
        fprintf(stderr, "Failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }
    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->max_records = max_records;
}

void add_record(RecordManager* manager) {
    if (manager->count >= manager->max_records) {
        fprintf(stderr, "Warning: Maximum number of records reached\n");
    }
    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 1.2;
        Record* new_records = (Record*)aligned_alloc(64, new_capacity * sizeof(Record));
        if (!new_records) {
            fprintf(stderr, "Failed to allocate memory\n");
            exit(EXIT_FAILURE);
        }
        for (size_t i = 0; i < manager->count; ++i) {
            new_records[i] = manager->records[i];
        }
        free(manager->records);
        manager->records = new_records;
        manager->capacity = new_capacity;
    }
    manager->records[manager->count].offset = rand();
    manager->records[manager->count].key = rand() % 1000;
    manager->records[manager->count].data = NULL; // Placeholder for actual data
    ++manager->count;
}

void cleanup_record_manager(RecordManager* manager) {
    free(manager->records);
    manager->records = NULL;
    manager->capacity = 0;
    manager->count = 0;
    manager->max_records = 0;
}

int main() {
    srand(time(NULL));
    RecordManager manager;
    init_record_manager(&manager, INITIAL_CAPACITY, MAX_RECORDS);

    for (size_t i = 0; i < 1500; ++i) {
        add_record(&manager);
    }

    cleanup_record_manager(&manager);
    return 0;
}
