    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->connections[i]->id == id) {
            manager->connections[i]->last_activity = new_time;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void destroy_connection_manager(ConnectionManager *manager) {
    for (size_t i = 0; i < manager->size; ++i) {
        free(manager->connections[i]->buffer);
        free(manager->connections[i]);
    }
    free(manager->connections);
    pthread_mutex_destroy(&manager->lock);
}
