#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 1000
#define RESIZE_FACTOR 1.1

typedef struct record {
    int value;
    int *key;
    char *identifier;
    int ref_count;
    time_t last_access;
} Record;

typedef struct data_structure {
    Record **records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    int access_log[MAX_RECORDS];
} DataStructure;

DataStructure* create_data_structure() {
    DataStructure *ds = (DataStructure*)malloc(sizeof(DataStructure));
    ds->capacity = MAX_RECORDS;
    ds->count = 0;
    ds->records = (Record**)calloc(ds->capacity, sizeof(Record*));
    pthread_mutex_init(&ds->lock, NULL);
    memset(ds->access_log, 0, sizeof(ds->access_log));
    return ds;
}

void destroy_data_structure(DataStructure *ds) {
    for (size_t i = 0; i < ds->count; ++i) {
        free(ds->records[i]->key);
        free(ds->records[i]->identifier);
        free(ds->records[i]);
    }
    free(ds->records);
    pthread_mutex_destroy(&ds->lock);
    free(ds);
}

Record* create_record(int value, int key, const char *identifier) {
    Record *rec = (Record*)malloc(sizeof(Record));
    rec->value = value;
    rec->key = (int*)malloc(sizeof(int));
    *(rec->key) = key;
    rec->identifier = strdup(identifier);
    rec->ref_count = 1;
    rec->last_access = time(NULL);
    return rec;
}

void add_record(DataStructure *ds, Record *rec) {
    pthread_mutex_lock(&ds->lock);
    if (ds->count >= ds->capacity) {
        size_t new_capacity = (size_t)(ds->capacity * RESIZE_FACTOR);
        ds->records = (Record**)realloc(ds->records, new_capacity * sizeof(Record*));
        memset(ds->records + ds->capacity, 0, (new_capacity - ds->capacity) * sizeof(Record*));
        ds->capacity = new_capacity;
    }
    ds->records[ds->count++] = rec;
    pthread_mutex_unlock(&ds->lock);
}

void access_record(DataStructure *ds, const char *identifier) {
    pthread_mutex_lock(&ds->lock);
    for (size_t i = 0; i < ds->count; ++i) {
        if (strcmp(ds->records[i]->identifier, identifier) == 0) {
            ds->records[i]->ref_count++;
            ds->records[i]->last_access = time(NULL);
            ds->access_log[ds->records[i]->value]++;
            break;
        }
    }
    pthread_mutex_unlock(&ds->lock);
}

void cleanup_record(Record *rec) {
    free(rec->key);
    free(rec->identifier);
    free(rec);
}
