#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_NAME_LENGTH 100
#define INITIAL_CAPACITY 10
#define MAX_ENTRIES 1000

typedef struct {
    char name[MAX_NAME_LENGTH];
    int age;
    void* address;
} Entry;

typedef struct {
    Entry* entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} List;

List* create_list(size_t initial_capacity) {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;

    list->entries = (Entry*)calloc(initial_capacity, sizeof(Entry));
    if (!list->entries) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_list(List* list) {
    if (list) {
        for (size_t i = 0; i < list->count; ++i) {
            free(list->entries[i].address);
        }
        free(list->entries);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

void resize_list(List* list, size_t new_capacity) {
    Entry* new_entries = (Entry*)realloc(list->entries, new_capacity * sizeof(Entry));
    if (!new_entries) return;

    list->entries = new_entries;
    list->capacity = new_capacity;
}

int add_entry(List* list, const char* name, int age, void* address) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_ENTRIES) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }

    size_t hash = 0;
    for (size_t i = 0; name[i]; ++i) {
        hash = hash * 31 + name[i];
    }
    hash %= list->capacity;

    while (list->entries[hash].name[0] != '\0' && strcmp(list->entries[hash].name, name) != 0) {
        hash = (hash + 1) % list->capacity;
    }

    if (list->entries[hash].name[0] != '\0') {
        pthread_mutex_unlock(&list->lock);
        return -2; // Duplicate entry
    }

    strncpy(list->entries[hash].name, name, MAX_NAME_LENGTH);
    list->entries[hash].age = age;
    list->entries[hash].address = address;
    ++list->count;

    if (list->count >= list->capacity) {
        resize_list(list, list->capacity * 2);
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void* get_address(List* list, const char* name) {
    pthread_mutex_lock(&list->lock);

    size_t hash = 0;
    for (size_t i = 0; name[i]; ++i) {
        hash = hash * 31 + name[i];
    }
    hash %= list->capacity;

    while (list->entries[hash].name[0] != '\0' && strcmp(list->entries[hash].name, name) != 0) {
        hash = (hash + 1) % list->capacity;
    }

    if (list->entries[hash].name[0] == '\0') {
        pthread_mutex_unlock(&list->lock);
        return NULL; // Name not found
    }

    void* address = list->entries[hash].address;
    pthread_mutex_unlock(&list->lock);
    return address;
}

void log_operation(const char* operation, size_t count) {
    printf("%s: %zu\n", operation, count);
}
