#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <stdint.h>

#define MAX_RECORDS 1000
#define GROWTH_FACTOR 0.15

typedef struct {
    int value;
    int *key;
    double *sqrt_value;
    uintptr_t alignment;
} Record;

Record* records = NULL;
int record_count = 0;
int capacity = 0;

void initialize_records(int start, int end) {
    if (end - start + 1 > MAX_RECORDS) {
        fprintf(stderr, "Error: Exceeds maximum number of records.\n");
        return;
    }
    if (records == NULL) {
        capacity = (int)(MAX_RECORDS * GROWTH_FACTOR);
        records = (Record*)aligned_alloc(64, capacity * sizeof(Record));
        if (records == NULL) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            return;
        }
    } else if (record_count + end - start + 1 > capacity) {
        int new_capacity = (int)(capacity * (1 + GROWTH_FACTOR));
        Record* new_records = (Record*)aligned_alloc(64, new_capacity * sizeof(Record));
        if (new_records == NULL) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            return;
        }
        for (int i = 0; i < record_count; i++) {
            new_records[i] = records[i];
        }
        free(records);
        records = new_records;
        capacity = new_capacity;
    }
    for (int i = start; i <= end; i++) {
        records[record_count].value = i;
        records[record_count].key = &records[record_count].value;
        records[record_count].sqrt_value = (double*)aligned_alloc(64, sizeof(double));
        if (records[record_count].sqrt_value == NULL) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            return;
        }
        *records[record_count].sqrt_value = sqrt(i);
        records[record_count].alignment = (uintptr_t)&records[record_count] % 64;
        record_count++;
    }
}

void find_and_print_largest() {
    if (record_count == 0) {
        printf("No records to process.\n");
        return;
    }
    int largest_value = records[0].value;
    double largest_sqrt = *records[0].sqrt_value;
    for (int i = 1; i < record_count; i++) {
        if (records[i].value > largest_value) {
            largest_value = records[i].value;
            largest_sqrt = *records[i].sqrt_value;
        }
    }
    printf("Largest value: %d, Square root: %.2f\n", largest_value, largest_sqrt);
}

void cleanup_records() {
    for (int i = 0; i < record_count; i++) {
        free(records[i].sqrt_value);
    }
    free(records);
    records = NULL;
    record_count = 0;
    capacity = 0;
}
