const express = require('express');
const axios = require('axios');
const { exec } = require('child_process');
const rateLimit = require('express-rate-limit');
const fs = require('fs');
const path = require('path');
const PDFImage = require('pdf-image').PDFImage;
const UnionFind = require('union-find');

const app = express();
app.use(express.json());
app.use(rateLimit({
  windowMs: 1000, // 1 second
  max: 5 // limit each IP to 5 requests per windowMs
}));

const pdfConverter = new PDFImage('/path/to/pdf-image-converter');
let conversionSuccessCount = 0;
let totalConversionAttempts = 0;

app.post('/metrics', async (req, res) => {
  const { data } = req.body;
  const unionFind = new UnionFind(data.length);

  for (let i = 0; i < data.length; i++) {
    for (let j = i + 1; j < data.length; j++) {
      if (data[i] === data[j]) {
        unionFind.union(i, j);
      }
    }
  }

  const disjointPairs = unionFind.getDisjointSets();
  res.json({ disjointPairs });
});

app.post('/process-file', async (req, res) => {
  const { filePath } = req.body;
  try {
    await pdfConverter.convert(filePath);
    conversionSuccessCount++;
  } catch (error) {
    console.error(`Failed to convert file: ${filePath}`, error);
  }
  totalConversionAttempts++;

  if (totalConversionAttempts % 10 === 0) {
    const successRate = conversionSuccessCount / totalConversionAttempts;
    res.json({ successRate });
  } else {
    res.status(204).send();
  }
});

app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).send('Something broke!');
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
