#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PROJECTS 1000
#define MAX_STATUS_LENGTH 50
#define BUDGET_INCREMENT 10000.0
#define MAX_BUDGET 500000.0

typedef struct {
    double budget;
    char *status;
    time_t completion_deadline;
} Project;

Project projects[MAX_PROJECTS];
int project_count = 0;

void initialize_projects(double max_budget) {
    for (int i = 0; i < MAX_PROJECTS && project_count < MAX_PROJECTS; i++) {
        projects[project_count].budget = BUDGET_INCREMENT * i;
        if (projects[project_count].budget > max_budget) {
            projects[project_count].budget = max_budget;
        }
        projects[project_count].status = malloc(MAX_STATUS_LENGTH);
        strcpy(projects[project_count].status, "Active");
        time_t now = time(NULL);
        projects[project_count].completion_deadline = now + (i * 86400); // 1 day increment
        project_count++;
    }
}

void update_project_status(int index, const char *new_status) {
    if (index >= 0 && index < project_count) {
        free(projects[index].status);
        projects[index].status = malloc(MAX_STATUS_LENGTH);
        strcpy(projects[index].status, new_status);
        if (strcmp(new_status, "Completed") == 0) {
            time_t now = time(NULL);
            projects[index].completion_deadline = now + 86400; // 1 day after completion
        } else if (strcmp(new_status, "Pending") == 0) {
            projects[index].budget *= 2.0; // Example adjustment for pending status
        }
    }
}

void export_projects_to_csv(const char *filename) {
    FILE *file = fopen(filename, "w");
    if (file != NULL) {
        fprintf(file, "Budget,Status,Completion Deadline\n");
        for (int i = 0; i < project_count; i++) {
            fprintf(file, "%.2f,%s,%ld\n", projects[i].budget, projects[i].status, projects[i].completion_deadline);
        }
        fclose(file);
    } else {
        printf("Failed to open file for writing.\n");
    }
}

int main() {
    initialize_projects(MAX_BUDGET);
    update_project_status(0, "Completed");
    export_projects_to_csv("projects.csv");
    return 0;
}
