#include <boost/asio.hpp>
#include <boost/beast/core.hpp>
#include <boost/beast/http.hpp>
#include <boost/beast/version.hpp>
#include <iostream>
#include <memory>
#include <string>
#include <vector>

namespace beast = boost::beast;         // from <boost/beast.hpp>
namespace http = beast::http;           // from <boost/beast/http.hpp>
namespace net = boost::asio;            // from <boost/asio.hpp>
using tcp = boost::asio::ip::tcp;       // from <boost/asio/ip/tcp.hpp>

class AsyncClient {
public:
    AsyncClient(net::io_context& ioc, std::string_view host, std::string_view port)
        : resolver_(ioc), stream_(ioc) {
        resolve(host, port);
    }

    void start() {
        do_request();
    }

private:
    void resolve(std::string_view host, std::string_view port) {
        resolver_.async_resolve(
            host,
            port,
            beast::bind_front_handler(&AsyncClient::on_resolve, this, beast::placeholders::_1, beast::placeholders::_2));
    }

    void on_resolve(beast::error_code ec, tcp::resolver::results_type results) {
        if (ec)
            return fail(ec);

        stream_.async_connect(results,
                              beast::bind_front_handler(&AsyncClient::on_connect, this, beast::placeholders::_1));
    }

    void on_connect(beast::error_code ec) {
        if (ec)
            return fail(ec);

        http::request<http::string_body> req{http::verb::get, "/", 11};
        req.set(http::field::host, resolver_.results().begin()->endpoint().address().to_string());
        req.set(http::field::user_agent, BOOST_BEAST_VERSION_STRING);

        http::async_write(stream_, req,
                          beast::bind_front_handler(&AsyncClient::on_write, this, beast::placeholders::_1));
    }

    void on_write(beast::error_code ec, std::size_t bytes_transferred) {
        if (ec)
            return fail(ec);

        http::async_read_until(stream_, buffer_, "\r\n\r\n",
                                beast::bind_front_handler(&AsyncClient::on_read_header, this, beast::placeholders::_1));
    }

    void on_read_header(beast::error_code ec, std::size_t bytes_transferred) {
        if (ec)
            return fail(ec);

        http::response<http::string_body> res;
        http::async_read(stream_, buffer_, res,
                          beast::bind_front_handler(&AsyncClient::on_read_body, this, beast::placeholders::_1));
    }

    void on_read_body(beast::error_code ec, std::size_t bytes_transferred) {
        if (ec)
            return fail(ec);

        // Process the response
        std::cout << res.body() << std::endl;

        do_request();
    }

    void fail(beast::error_code ec) {
        std::cerr << "Error: " << ec.message() << std::endl;
    }

    tcp::resolver resolver_;
    beast::tcp_stream stream_;
    beast::flat_buffer buffer_;
};

int main(int argc, char** argv) {
    try {
        if (argc != 4) {
            std::cerr << "Usage: async_client <host> <port> <path>\n";
            return EXIT_FAILURE;
        }

        net::io_context ioc{1};
        AsyncClient client{ioc, argv[1], argv[2]};
        client.start();

        ioc.run();
    } catch (std::exception const& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
