// Third-party HTTP client library (e.g., cURL)
extern "C" {
    #include <curl/curl.h>
}

struct Record {
    int value;
    int* keyPtr;
};

class HttpClient {
public:
    HttpClient(const std::string& url) : url_(url), retryCount_(0), maxRetries_(3), backoffFactor_(2.0) {}

    void sendGetRequest() {
        CURL* curl = curl_easy_init();
        if (curl) {
            curl_easy_setopt(curl, CURLOPT_URL, url_.c_str());
            CURLcode res = curl_easy_perform(curl);
            if (res != CURLE_OK) {
                std::cerr << "Failed to perform GET request: " << curl_easy_strerror(res) << std::endl;
                retryRequest();
            }
            curl_easy_cleanup(curl);
        } else {
            std::cerr << "Failed to initialize cURL" << std::endl;
            retryRequest();
        }
    }

private:
    void retryRequest() {
        if (retryCount_ < maxRetries_) {
            std::this_thread::sleep_for(std::chrono::milliseconds(static_cast<int>(backoffFactor_ * std::pow(2, retryCount_))));
            retryCount_++;
            sendGetRequest();
        } else {
            std::cerr << "Max retries reached" << std::endl;
        }
    }

    std::string url_;
    int retryCount_;
    int maxRetries_;
    double backoffFactor_;
};

class RecordManager {
public:
    RecordManager(size_t initialCapacity) : capacity_(initialCapacity), size_(0), records_(new Record[capacity_]) {}

    ~RecordManager() {
        cleanup();
    }

    void addRecord(int value, int* keyPtr) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (size_ == capacity_) {
            resize(capacity_ * 1.1);
        }
        records_[size_].value = value;
        records_[size_].keyPtr = keyPtr;
        size_++;
    }

    void removeRecord(int* keyPtr) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (size_t i = 0; i < size_; ++i) {
            if (records_[i].keyPtr == keyPtr) {
                records_[i] = records_[--size_];
                break;
            }
        }
    }

    void cleanup() {
        std::lock_guard<std::mutex> lock(mutex_);
        delete[] records_;
        records_ = nullptr;
        capacity_ = 0;
        size_ = 0;
    }

private:
    void resize(size_t newCapacity) {
        Record* newRecords = new Record[newCapacity];
        std::copy(records_, records_ + size_, newRecords);
        delete[] records_;
        records_ = newRecords;
        capacity_ = newCapacity;
    }

    size_t capacity_;
    size_t size_;
    Record* records_;
    std::mutex mutex_;
};

int main() {
    HttpClient client("http://example.com/api");
    RecordManager manager(10);

    // Example usage
    int key1 = 42;
    int key2 = 99;
    manager.addRecord(10, &key1);
    manager.addRecord(20, &key2);

    std::thread t([&client]() {
        client.sendGetRequest();
    });

    t.join();

    manager.removeRecord(&key1);

    return 0;
}
