#include <thread>
#include <atomic>

struct Connection {
    int socketDescriptor;
    std::string clientIP;
    bool isConnected;
    std::chrono::time_point<std::chrono::system_clock> lastHealthCheck;
};

class NetworkManager {
public:
    void addConnection(int socket, const std::string& ip) {
        std::lock_guard<std::mutex> lock(mutex_);
        connections_.emplace_back(Connection{socket, ip, true, std::chrono::system_clock::now()});
    }

    void removeConnection(int socket) {
        std::lock_guard<std::mutex> lock(mutex_);
        connections_.erase(std::remove_if(connections_.begin(), connections_.end(),
                                          [socket](const Connection& conn) { return conn.socketDescriptor == socket; }),
                          connections_.end());
    }

    void updateHealthCheck(int socket) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto& conn : connections_) {
            if (conn.socketDescriptor == socket) {
                conn.lastHealthCheck = std::chrono::system_clock::now();
                break;
            }
        }
    }

    void monitorConnections() {
        while (!shutdown_.load()) {
            std::this_thread::sleep_for(std::chrono::seconds(1));
            std::lock_guard<std::mutex> lock(mutex_);
            for (auto& conn : connections_) {
                if (!conn.isConnected) {
                    // Attempt to re-establish connection
                    conn.isConnected = true;
                }
            }
        }
    }

private:
    std::vector<Connection> connections_;
    std::mutex mutex_;
    std::condition_variable cv_;
    std::atomic<bool> shutdown_{false};
};

void insertAfterForwardList(std::forward_list<std::string>& list, const std::string& target, const std::string& toInsert) {
    auto it = list.before_begin();
    for (; it != list.end(); ++it) {
        if (*it == target) {
            break;
        }
    }
    if (it == list.end()) {
        list.push_back(toInsert);
    } else {
        list.insert_after(it, toInsert);
    }
}

int main() {
    NetworkManager manager;
    std::thread monitor(&NetworkManager::monitorConnections, &manager);

    // Example usage
    manager.addConnection(12345, "192.168.1.1");
    manager.updateHealthCheck(12345);
    manager.removeConnection(12345);

    insertAfterForwardList(std::forward_list<std::string>{"apple", "banana"}, "apple", "orange");

    monitor.join();
    return 0;
}
