    int connection_status;
    time_t last_active;
} Connection;

Connection connections[MAX_CONNECTIONS];
int connection_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* health_check_thread(void* arg) {
    while (1) {
        pthread_mutex_lock(&lock);
        for (int i = 0; i < connection_count; i++) {
            if (time(NULL) - connections[i].last_active > HEALTH_CHECK_INTERVAL) {
                // Re-establish failed connection
                printf("Re-establishing connection with %s\n", connections[i].client_ip);
                // Code to re-establish connection goes here
            }
        }
        pthread_mutex_unlock(&lock);
        sleep(HEALTH_CHECK_INTERVAL);
    }
    return NULL;
}

void add_connection(int socket_descriptor, const char* client_ip) {
    pthread_mutex_lock(&lock);
    if (connection_count < MAX_CONNECTIONS) {
        connections[connection_count].socket_descriptor = socket_descriptor;
        strcpy(connections[connection_count].client_ip, client_ip);
        connections[connection_count].connection_status = 1;
        connections[connection_count].last_active = time(NULL);
        connection_count++;
    } else {
        printf("Connection pool is full\n");
    }
    pthread_mutex_unlock(&lock);
}

void remove_connection(int socket_descriptor) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < connection_count; i++) {
        if (connections[i].socket_descriptor == socket_descriptor) {
            // Code to close the socket goes here
            memmove(&connections[i], &connections[i + 1], sizeof(Connection) * (connection_count - i - 1));
            connection_count--;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

void* monitor_thread(void* arg) {
