        double average_response_time = (double)total_response_time / active_connections;
        printf("Active Connections: %d, Average Response Time: %.2f\n", active_connections, average_response_time);
        pthread_mutex_unlock(&lock);
        sleep(10); // Monitor every 10 seconds
    }
    return NULL;
