#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define N 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* list[N];
int count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void generate_and_manage_list(int N) {
    for (int i = 0; i < N; i++) {
        pthread_mutex_lock(&lock);
        list[count] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (list[count] == NULL) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }
        list[count]->RX_UE_INFORMATION_TAG = rand() % 100;
        list[count]->RNTI = rand() % 1000;
        list[count]->CRC_INDICATION_REL8_TAG = (rand() % 2 == 0) ? 0 : 1;
        count++;
        pthread_mutex_unlock(&lock);
    }
}

void filter_list(int threshold) {
    int new_count = 0;
    for (int i = 0; i < count; i++) {
        if (list[i]->CRC_INDICATION_REL8_TAG == threshold) {
            list[new_count] = list[i];
            new_count++;
        } else {
            free(list[i]);
        }
    }
    count = new_count;
}

void serialize_list(const char* filename, int version) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        perror("File opening failed");
        exit(EXIT_FAILURE);
    }
    fwrite(&version, sizeof(int), 1, file);
    for (int i = 0; i < count; i++) {
        fwrite(list[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }
    fclose(file);
}

void deserialize_list(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        perror("File opening failed");
        exit(EXIT_FAILURE);
    }
    int version;
    fread(&version, sizeof(int), 1, file);
    while (!feof(file)) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pdu == NULL) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }
        fread(pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        list[count] = pdu;
        count++;
    }
    fclose(file);
}

int main() {
    generate_and_manage_list(N);
    filter_list(1);
    serialize_list("list.bin", 1);
    deserialize_list("list.bin");
    return 0;
}
