#include <iostream>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <chrono>
#include <queue>
#include <atomic>

struct Connection {
    int socketDescriptor;
    std::string clientIP;
    bool isConnected;
    std::time_t lastHealthCheck;
};

class NetworkManager {
public:
    void addConnection(int socket, const std::string& ip) {
        std::lock_guard<std::mutex> lock(mutex_);
        connections_.push_back({socket, ip, true, std::time(nullptr)});
        cv_.notify_one();
    }

    void removeConnection(int socket) {
        std::lock_guard<std::mutex> lock(mutex_);
        connections_.erase(std::remove_if(connections_.begin(), connections_.end(),
                                          [socket](const Connection& conn) { return conn.socketDescriptor == socket; }),
                          connections_.end());
    }

    void checkHealth() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            cv_.wait(lock, [this] { return !connections_.empty(); });
            for (auto& conn : connections_) {
                if (!conn.isConnected && std::time(nullptr) - conn.lastHealthCheck > 60) {
                    // Attempt to re-establish connection
                    conn.isConnected = true;
                    conn.lastHealthCheck = std::time(nullptr);
                    logEvent("Connection re-established: " + conn.clientIP);
                }
            }
        }
    }

private:
    void logEvent(const std::string& event) {
        // Log the event using an external logging service
        std::cout << "Log: " << event << std::endl;
    }

    std::mutex mutex_;
    std::condition_variable cv_;
    std::vector<Connection> connections_;
};

int main() {
    NetworkManager manager;
    std::thread healthThread(&NetworkManager::checkHealth, &manager);

    // Simulate adding and removing connections
    for (int i = 0; i < 10; ++i) {
        manager.addConnection(i, "192.168.1." + std::to_string(i));
        std::this_thread::sleep_for(std::chrono::seconds(1));
    }

    for (int i = 0; i < 5; ++i) {
        manager.removeConnection(i);
        std::this_thread::sleep_for(std::chrono::seconds(2));
    }

    healthThread.join();
    return 0;
}
