#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int tx_power_level;
    int channel_id;
    int format_version;
} PHY_TRANSPORT_CHANNEL_PDU_T;

typedef struct {
    PHY_TRANSPORT_CHANNEL_PDU_T *pdu_array;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} PDU_COLLECTION_T;

PDU_COLLECTION_T* create_pdu_collection(size_t initial_capacity) {
    PDU_COLLECTION_T *collection = (PDU_COLLECTION_T*)malloc(sizeof(PDU_COLLECTION_T));
    if (!collection) return NULL;

    collection->pdu_array = (PHY_TRANSPORT_CHANNEL_PDU_T*)calloc(initial_capacity, sizeof(PHY_TRANSPORT_CHANNEL_PDU_T));
    if (!collection->pdu_array) {
        free(collection);
        return NULL;
    }

    collection->count = 0;
    collection->capacity = initial_capacity;
    pthread_mutex_init(&collection->mutex, NULL);

    return collection;
}

void destroy_pdu_collection(PDU_COLLECTION_T *collection) {
    pthread_mutex_lock(&collection->mutex);
    free(collection->pdu_array);
    pthread_mutex_unlock(&collection->mutex);
    pthread_mutex_destroy(&collection->mutex);
    free(collection);
}

int add_pdu_to_collection(PDU_COLLECTION_T *collection, PHY_TRANSPORT_CHANNEL_PDU_T pdu) {
    pthread_mutex_lock(&collection->mutex);

    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity ? collection->capacity * 2 : 1;
        PHY_TRANSPORT_CHANNEL_PDU_T *new_array = (PHY_TRANSPORT_CHANNEL_PDU_T*)realloc(collection->pdu_array, new_capacity * sizeof(PHY_TRANSPORT_CHANNEL_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&collection->mutex);
            return -1; // Memory allocation failed
        }
        collection->pdu_array = new_array;
        collection->capacity = new_capacity;
    }

    collection->pdu_array[collection->count++] = pdu;

    pthread_mutex_unlock(&collection->mutex);
    return 0;
}

int filter_pdu_collection(PDU_COLLECTION_T *collection, int min_format_version) {
    pthread_mutex_lock(&collection->mutex);

    size_t i = 0, j = 0;
    while (i < collection->count) {
        if (collection->pdu_array[i].format_version >= min_format_version) {
            collection->pdu_array[j++] = collection->pdu_array[i];
        }
        i++;
    }

    collection->count = j;

    pthread_mutex_unlock(&collection->mutex);
    return 0;
}

int serialize_pdu_collection(PDU_COLLECTION_T *collection, FILE *file) {
    pthread_mutex_lock(&collection->mutex);

    if (fwrite(&collection->count, sizeof(size_t), 1, file) != 1) {
        pthread_mutex_unlock(&collection->mutex);
        return -1; // Write failed
    }

    for (size_t i = 0; i < collection->count; i++) {
        if (fwrite(&collection->pdu_array[i], sizeof(PHY_TRANSPORT_CHANNEL_PDU_T), 1, file) != 1) {
            pthread_mutex_unlock(&collection->mutex);
            return -1; // Write failed
        }
    }

    pthread_mutex_unlock(&collection->mutex);
    return 0;
}

int deserialize_pdu_collection(PDU_COLLECTION_T *collection, FILE *file) {
    pthread_mutex_lock(&collection->mutex);

    size_t new_count;
    if (fread(&new_count, sizeof(size_t), 1, file) != 1) {
        pthread_mutex_unlock(&collection->mutex);
        return -1; // Read failed
    }

    if (new_count > collection->capacity) {
        PHY_TRANSPORT_CHANNEL_PDU_T *new_array = (PHY_TRANSPORT_CHANNEL_PDU_T*)realloc(collection->pdu_array, new_count * sizeof(PHY_TRANSPORT_CHANNEL_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&collection->mutex);
            return -1; // Memory allocation failed
        }
        collection->pdu_array = new_array;
        collection->capacity = new_count;
    }

    for (size_t i = 0; i < new_count; i++) {
        if (fread(&collection->pdu_array[i], sizeof(PHY_TRANSPORT_CHANNEL_PDU_T), 1, file) != 1) {
            pthread_mutex_unlock(&collection->mutex);
            return -1; // Read failed
        }
    }

    collection->count = new_count;

    pthread_mutex_unlock(&collection->mutex);
    return 0;
}
