#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PROJECTS 1000

typedef struct {
    int priority;
    char *status;
    time_t deadline;
    time_t start_date;
} Project;

void initialize_projects(Project **projects, int count) {
    if (count > MAX_PROJECTS) {
        fprintf(stderr, "Error: Exceeds maximum project limit.\n");
        return;
    }

    *projects = malloc(count * sizeof(Project));
    if (*projects == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return;
    }

    for (int i = 0; i < count; i++) {
        (*projects)[i].priority = i + 1;
        (*projects)[i].status = malloc(20 * sizeof(char));
        if ((*projects)[i].status == NULL) {
            fprintf(stderr, "Error: Memory allocation failed for status.\n");
            return;
        }
        strcpy((*projects)[i].status, "Pending");

        time_t now = time(NULL);
        (*projects)[i].start_date = now;

        // Assuming deadline is 1 month from start date
        (*projects)[i].deadline = now + (30 * 24 * 60 * 60);
    }
}

void update_project_statuses(Project *projects, int count) {
    time_t now = time(NULL);

    for (int i = 0; i < count; i++) {
        double elapsed_time = difftime(now, projects[i].start_date);
        double total_duration = difftime(projects[i].deadline, projects[i].start_date);

        if (elapsed_time > total_duration) {
            strcpy(projects[i].status, "Late");
        } else if (elapsed_time > total_duration / 2) {
            strcpy(projects[i].status, "Completed");
        } else {
            strcpy(projects[i].status, "In Progress");
        }
    }
}

void free_projects(Project *projects, int count) {
    for (int i = 0; i < count; i++) {
        free(projects[i].status);
    }
    free(projects);
}
