#include <stdlib.h>
#include <pthread.h>

#define MAX_STRUCTURES 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array[MAX_STRUCTURES];
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

void initDynamicArray(DynamicArray *da) {
    da->count = 0;
    pthread_mutex_init(&da->lock, NULL);
}

int addStructure(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T *newStruct) {
    pthread_mutex_lock(&da->lock);
    if (da->count >= MAX_STRUCTURES) {
        pthread_mutex_unlock(&da->lock);
        return -1; // Array is full
    }
    da->array[da->count++] = newStruct;
    pthread_mutex_unlock(&da->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* getStructureByRNTI(DynamicArray *da, int RNTI) {
    pthread_mutex_lock(&da->lock);
    for (size_t i = 0; i < da->count; ++i) {
        if (da->array[i]->RNTI == RNTI) {
            pthread_mutex_unlock(&da->lock);
            return da->array[i];
        }
    }
    pthread_mutex_unlock(&da->lock);
    return NULL;
}

int deleteStructureByRNTI(DynamicArray *da, int RNTI) {
    pthread_mutex_lock(&da->lock);
    for (size_t i = 0; i < da->count; ++i) {
        if (da->array[i]->RNTI == RNTI) {
            free(da->array[i]);
            for (; i + 1 < da->count; ++i) {
                da->array[i] = da->array[i + 1];
            }
            da->count--;
            pthread_mutex_unlock(&da->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&da->lock);
    return -1; // Structure not found
}

int bulkDeleteByRNTIRange(DynamicArray *da, int startRNTI, int endRNTI) {
    pthread_mutex_lock(&da->lock);
    size_t i = 0;
    while (i < da->count) {
        if (da->array[i]->RNTI >= startRNTI && da->array[i]->RNTI <= endRNTI) {
            free(da->array[i]);
            for (; i + 1 < da->count; ++i) {
                da->array[i] = da->array[i + 1];
            }
            da->count--;
        } else {
            ++i;
        }
    }
    pthread_mutex_unlock(&da->lock);
    return 0;
}

void destroyDynamicArray(DynamicArray *da) {
    pthread_mutex_lock(&da->lock);
    for (size_t i = 0; i < da->count; ++i) {
        free(da->array[i]);
    }
    da->count = 0;
    pthread_mutex_unlock(&da->lock);
    pthread_mutex_destroy(&da->lock);
}
