#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_STRUCTS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array[MAX_STRUCTS];
    int count;
    pthread_mutex_t mutex;
} DynamicArray;

int add_structure(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T *new_struct) {
    pthread_mutex_lock(&da->mutex);
    if (da->count >= MAX_STRUCTS) {
        pthread_mutex_unlock(&da->mutex);
        return -1; // Array is full
    }
    for (int i = 0; i < da->count; i++) {
        if (da->array[i]->RNTI == new_struct->RNTI) {
            pthread_mutex_unlock(&da->mutex);
            return -2; // Duplicate RNTI
        }
    }
    da->array[da->count++] = new_struct;
    pthread_mutex_unlock(&da->mutex);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_structure(DynamicArray *da, int rnti) {
    pthread_mutex_lock(&da->mutex);
    for (int i = 0; i < da->count; i++) {
        if (da->array[i]->RNTI == rnti) {
            pthread_mutex_unlock(&da->mutex);
            return da->array[i];
        }
    }
    pthread_mutex_unlock(&da->mutex);
    return NULL;
}

int load_config_file(const char *path, int **bundle, int *num_items) {
    FILE *file = fopen(path, "r");
    if (!file) {
        perror("Failed to open file");
        return -1;
    }

    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    char *buffer = (char *)malloc(file_size + 1);
    if (!buffer) {
        perror("Failed to allocate memory for buffer");
        fclose(file);
        return -2;
    }

    fread(buffer, 1, file_size, file);
    buffer[file_size] = '\0';
    fclose(file);

    // Simulate parsing the bundle
    *num_items = 5; // Example number of items
    *bundle = (int *)malloc(*num_items * sizeof(int));
    if (!*bundle) {
        perror("Failed to allocate memory for bundle");
        free(buffer);
        return -3;
    }

    for (int i = 0; i < *num_items; i++) {
        (*bundle)[i] = i; // Example values
    }

    free(buffer);
    return 0;
}

int main() {
    DynamicArray da;
    pthread_mutex_init(&da.mutex, NULL);
    da.count = 0;

    NFAPI_CRC_INDICATION_PDU_T *new_struct = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_struct) {
        perror("Failed to allocate memory for new structure");
        return -1;
    }
    new_struct->RX_UE_INFORMATION_TAG = 123;
    new_struct->RNTI = 456;
    new_struct->CRC_INDICATION_REL8_TAG = rand() % 2;

    if (add_structure(&da, new_struct) != 0) {
        perror("Failed to add structure");
        free(new_struct);
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *retrieved_struct = get_structure(&da, 456);
    if (!retrieved_struct) {
        perror("Failed to retrieve structure");
        return -1;
    }

    int *bundle;
    int num_items;
    if (load_config_file("config.txt", &bundle, &num_items) != 0) {
        perror("Failed to load config file");
        return -1;
    }

    printf("Number of items in bundle: %d\n", num_items);

    free(new_struct);
    pthread_mutex_destroy(&da.mutex);
    for (int i = 0; i < num_items; i++) {
        free(bundle[i]);
    }
    free(bundle);

    return 0;
}
