#include <time.h>
#include <pthread.h>

#define MAX_SESSIONS 1000
#define SESSION_EXPIRY_TIME 3600 // 1 hour in seconds
#define DEVICE_VALIDATION_DB "trusted_devices.db"

typedef struct Device {
    char ip[16];
    time_t last_active;
    char hardware_id[256];
} Device;

typedef struct Session {
    int session_id;
    time_t timestamp;
    Device *devices;
    int device_count;
    int max_devices;
} Session;

Session *session_list[MAX_SESSIONS];
int session_count = 0;
pthread_mutex_t session_lock = PTHREAD_MUTEX_INITIALIZER;

void update_session_timestamps() {
    pthread_mutex_lock(&session_lock);
    for (int i = 0; i < session_count; i++) {
        session_list[i]->timestamp = time(NULL);
    }
    pthread_mutex_unlock(&session_lock);
}

void purge_old_sessions(time_t current_time) {
    pthread_mutex_lock(&session_lock);
    for (int i = 0; i < session_count; i++) {
        if (current_time - session_list[i]->timestamp > SESSION_EXPIRY_TIME) {
            free(session_list[i]->devices);
            free(session_list[i]);
            for (int j = i; j < session_count - 1; j++) {
                session_list[j] = session_list[j + 1];
            }
            session_count--;
            i--; // Adjust index after removal
        }
    }
    pthread_mutex_unlock(&session_lock);
}

void *validate_device(void *device_info) {
    Device *device = (Device *)device_info;
    // Simulate database query
    if (strcmp(device->hardware_id, "trusted_hardware_id") == 0) {
        return NULL; // Valid device
    } else {
        return device; // Invalid device
    }
}

void add_session(int session_id) {
    pthread_mutex_lock(&session_lock);
    if (session_count >= MAX_SESSIONS) {
        printf("Session limit reached\n");
        pthread_mutex_unlock(&session_lock);
        return;
    }
    Session *new_session = malloc(sizeof(Session));
    new_session->session_id = session_id;
    new_session->timestamp = time(NULL);
    new_session->devices = NULL;
    new_session->device_count = 0;
    new_session->max_devices = 10; // Initial capacity
    session_list[session_count++] = new_session;
    pthread_mutex_unlock(&session_lock);
}

void add_device_to_session(int session_id, Device *device) {
    pthread_mutex_lock(&session_lock);
    for (int i = 0; i < session_count; i++) {
        if (session_list[i]->session_id == session_id) {
            if (session_list[i]->device_count >= session_list[i]->max_devices) {
                // Resize the device list
                Device *new_devices = realloc(session_list[i]->devices, session_list[i]->max_devices * 2 * sizeof(Device));
                if (new_devices == NULL) {
                    printf("Memory allocation failed\n");
                    pthread_mutex_unlock(&session_lock);
                    return;
                }
                session_list[i]->devices = new_devices;
                session_list[i]->max_devices *= 2;
            }
            // Validate device asynchronously
            pthread_t thread_id;
            if (pthread_create(&thread_id, NULL, validate_device, device) != 0) {
                printf("Thread creation failed\n");
                pthread_mutex_unlock(&session_lock);
                return;
            }
            session_list[i]->devices[session_list[i]->device_count++] = *device;
            break;
        }
    }
    pthread_mutex_unlock(&session_lock);
}

void cleanup_sessions() {
    pthread_mutex_lock(&session_lock);
    for (int i = 0; i < session_count; i++) {
        free(session_list[i]->devices);
        free(session_list[i]);
    }
    session_count = 0;
    pthread_mutex_unlock(&session_lock);
}
