int addStructToDynamicArray(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T *newStruct) {
    pthread_mutex_lock(&da->lock);
    if (da->count >= MAX_STRUCTS) {
        fprintf(stderr, "Error: Dynamic array is full.\n");
        pthread_mutex_unlock(&da->lock);
        return -1;
    }
    da->array[da->count++] = newStruct;
    pthread_mutex_unlock(&da->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* getStructFromDynamicArray(DynamicArray *da, int RNTI) {
    pthread_mutex_lock(&da->lock);
    for (int i = 0; i < da->count; i++) {
        if (da->array[i]->RNTI == RNTI) {
            pthread_mutex_unlock(&da->lock);
            return da->array[i];
        }
    }
    pthread_mutex_unlock(&da->lock);
    return NULL;
}

int deleteStructFromDynamicArray(DynamicArray *da, int RNTI) {
    pthread_mutex_lock(&da->lock);
    for (int i = 0; i < da->count; i++) {
        if (da->array[i]->RNTI == RNTI) {
            free(da->array[i]);
            for (int j = i; j < da->count - 1; j++) {
                da->array[j] = da->array[j + 1];
