        }
    }
    pthread_mutex_unlock(&da->lock);
    fprintf(stderr, "Error: Struct with RNTI %d not found.\n", RNTI);
    return -1;
}

void validateDynamicArray(DynamicArray *da) {
    pthread_mutex_lock(&da->lock);
    for (int i = 0; i < da->count - 1; i++) {
        if (da->array[i]->RNTI >= da->array[i + 1]->RNTI) {
            fprintf(stderr, "Warning: Inconsistent RNTI order detected.\n");
        }
    }
    pthread_mutex_unlock(&da->lock);
}

void cleanupDynamicArray(DynamicArray *da) {
    pthread_mutex_lock(&da->lock);
    for (int i = 0; i < da->count; i++) {
        free(da->array[i]);
    }
    da->count = 0;
    pthread_mutex_unlock(&da->lock);
}
