public class FileTransferUtility {
    private ExecutorService executorService;
    private BlockingQueue<FileTransferTask> taskQueue;
    private int maxQueueSize;

    public FileTransferUtility(int initialCapacity, int maxCapacity) {
        this.taskQueue = new ArrayBlockingQueue<>(initialCapacity);
        this.maxQueueSize = maxCapacity;
        this.executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
    }

    public void addTask(File sourceFile, String destinationDir, boolean isSynchronous, int priority, int urgency) {
        FileTransferTask task = new FileTransferTask(sourceFile, destinationDir, isSynchronous, priority, urgency);
        try {
            if (taskQueue.size() >= maxQueueSize * 0.75) {
                resizeQueue(maxQueueSize + maxQueueSize / 4);
            }
            taskQueue.put(task);
            executorService.submit(task);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    private void resizeQueue(int newSize) {
        BlockingQueue<FileTransferTask> newQueue = new ArrayBlockingQueue<>(newSize);
        taskQueue.drainTo(newQueue);
        taskQueue = newQueue;
    }

