#include <string.h>
#include <pthread.h>

#define MAX_KEYS 1000
#define RECORD_THRESHOLD 10000
#define RANDOM_RANGE 100

typedef struct {
    int value;
    int *key;
} Record;

typedef struct {
    Record **records;
    int count;
    int capacity;
    pthread_mutex_t mutex;
} RecordCollection;

int load_keys(const char *path, int *keys, int max_keys) {
    FILE *file = fopen(path, "r");
    if (!file) return -1;

    int key_count = 0;
    while (key_count < max_keys && fscanf(file, "%d", &keys[key_count]) == 1) {
        key_count++;
    }

    fclose(file);
    return key_count;
}

int initialize_records(RecordCollection *collection, const char *path, int max_keys) {
    pthread_mutex_init(&collection->mutex, NULL);
    collection->records = (Record **)malloc(sizeof(Record *) * max_keys);
    if (!collection->records) return -1;

    int keys[MAX_KEYS];
    int key_count = load_keys(path, keys, max_keys);
    if (key_count < 0) {
        free(collection->records);
        pthread_mutex_destroy(&collection->mutex);
        return -1;
    }

    collection->capacity = max_keys;
    collection->count = 0;

    for (int i = 0; i < key_count; i++) {
        Record *record = (Record *)malloc(sizeof(Record));
        if (!record) {
            free_records(collection);
            pthread_mutex_destroy(&collection->mutex);
            return -1;
        }
        record->value = rand() % RANDOM_RANGE;
        record->key = &keys[i];
        collection->records[collection->count++] = record;
    }

    return 0;
}

void free_records(RecordCollection *collection) {
    pthread_mutex_lock(&collection->mutex);
    for (int i = 0; i < collection->count; i++) {
        free(collection->records[i]);
    }
    free(collection->records);
    pthread_mutex_unlock(&collection->mutex);
    pthread_mutex_destroy(&collection->mutex);
}

