#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INITIAL_CAPACITY 100
#define GROWTH_FACTOR 1.5

typedef struct PacketHeader {
    char source_ip[16];
    char destination_ip[16];
    int protocol_type;
    int payload_size;
} PacketHeader;

typedef struct Node {
    PacketHeader header;
    struct Node* next;
} Node;

typedef struct PacketList {
    Node* head;
    Node* tail;
    size_t count;
    size_t capacity;
} PacketList;

PacketList* create_packet_list() {
    PacketList* list = (PacketList*)malloc(sizeof(PacketList));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    list->count = 0;
    list->capacity = INITIAL_CAPACITY;
    return list;
}

void destroy_packet_list(PacketList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

int add_packet_header(PacketList* list, const PacketHeader* header) {
    if (list->count >= list->capacity) {
        size_t new_capacity = (size_t)(list->capacity * GROWTH_FACTOR);
        Node** new_nodes = realloc(list->head, new_capacity * sizeof(Node));
        if (!new_nodes) return -1;
        list->head = new_nodes;
        list->tail = &new_nodes[list->count];
        list->capacity = new_capacity;
    }
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1;
    memcpy(&new_node->header, header, sizeof(PacketHeader));
    new_node->next = NULL;
    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;
    list->count++;
    return 0;
}

int remove_packet_header(PacketList* list, size_t index) {
    if (index >= list->count) return -1;
    Node* current = list->head;
    for (size_t i = 0; i < index; i++) {
        current = current->next;
    }
    if (current == list->head) {
        list->head = current->next;
    } else {
        Node* prev = list->head;
        while (prev->next != current) {
            prev = prev->next;
        }
        prev->next = current->next;
    }
    if (current == list->tail) {
        list->tail = prev;
    }
    free(current);
    list->count--;
    return 0;
}

// Additional functions for asynchronous processing, error handling, and resource management can be added here.
