#include <stdlib.h>
#include <stdint.h>
#include <string.h>

typedef struct {
    int value;
    int *key_ptr;
} record;

void initialize_arrays(size_t initial_capacity, size_t max_capacity) {
    long *offsets = aligned_alloc(64, initial_capacity * sizeof(long));
    int *keys = aligned_alloc(64, initial_capacity * sizeof(int));
    record *records = aligned_alloc(64, initial_capacity * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    size_t allocated_records = 0;

    while (allocated_records < max_capacity) {
        size_t to_add = (size_t)(initial_capacity * 0.1);
        if (allocated_records + to_add > max_capacity) {
            to_add = max_capacity - allocated_records;
        }

        for (size_t i = 0; i < to_add; ++i) {
            offsets[allocated_records + i] = rand();
            keys[allocated_records + i] = rand() % 1000;
            records[allocated_records + i].value = rand() % 1000;
            records[allocated_records + i].key_ptr = &keys[allocated_records + i];
        }

        allocated_records += to_add;

        if (allocated_records >= max_capacity) {
            break;
        }
    }

    // Cleanup
    free(offsets);
    free(keys);
    free(records);
}
