    collection->records = malloc(sizeof(Record *) * RECORD_THRESHOLD);
    if (!collection->records) return -2;

    pthread_mutex_init(&collection->lock, NULL);

    for (int i = 0; i < key_count && i < RECORD_THRESHOLD; i++) {
