        record->value = rand() % RANDOM_RANGE;
        record->key = &keys[i];
        record->metadata = NULL;

        collection->records[i] = record;
    }

    collection->count = key_count;
    collection->capacity = RECORD_THRESHOLD;

    return 0;
}

void free_records(RecordCollection *collection) {
    pthread_mutex_lock(&collection->lock);
    for (int i = 0; i < collection->count; i++) {
        free(collection->records[i]);
