void filter_records(RecordCollection *collection, int (*predicate)(Record *)) {
    pthread_mutex_lock(&collection->lock);
    for (int i = collection->count - 1; i >= 0; i--) {
        if (!predicate(collection->records[i])) {
            free(collection->records[i]);
            memmove(&collection->records[i], &collection->records[i + 1], sizeof(Record *) * (collection->count - i - 1));
