NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_array(int initial_size, int max_size) {
    if (initial_size > max_size || initial_size <= 0) {
        return nullptr;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        return nullptr;
    }

    std::lock_guard<std::mutex> lock(allocation_mutex);
    if (total_elements + initial_size > MAX_ELEMENTS) {
        free(array);
        return nullptr;
    }
    total_elements += initial_size;

    srand(time(0));
    for (int i = 0; i < initial_size; ++i) {
