void resize_array(NFAPI_CRC_INDICATION_PDU_T** array, int current_size, int new_size) {
    if (new_size > MAX_ELEMENTS || new_size <= 0) {
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(*array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        // Handle reallocation failure
        printf("Failed to resize array\n");
        return;
    }

    std::lock_guard<std::mutex> lock(allocation_mutex);
    if (total_elements + (new_size - current_size) > MAX_ELEMENTS) {
        free(new_array);
        printf("Resize exceeds maximum elements limit\n");
        return;
    }
    total_elements += (new_size - current_size);

