#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define MAX_ALLOCATION_LIMIT 500

typedef struct record {
    int value;
    int key_index;
} Record;

typedef struct dynamic_collection {
    Record** records;
    long* offsets;
    int* keys;
    size_t capacity;
    size_t count;
    size_t allocation_limit;
} DynamicCollection;

DynamicCollection* create_dynamic_collection(size_t initial_capacity, size_t allocation_limit) {
    DynamicCollection* collection = (DynamicCollection*)malloc(sizeof(DynamicCollection));
    if (!collection) return NULL;

    collection->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    collection->offsets = (long*)calloc(initial_capacity, sizeof(long));
    collection->keys = (int*)calloc(initial_capacity, sizeof(int));
    collection->capacity = initial_capacity;
    collection->count = 0;
    collection->allocation_limit = allocation_limit;

    if (!collection->records || !collection->offsets || !collection->keys) {
        free(collection);
        return NULL;
    }

    srand(time(NULL)); // Seed for random number generation
    return collection;
}

void resize_collection(DynamicCollection* collection) {
    size_t new_capacity = collection->capacity * 1.5;
    if (new_capacity > MAX_ALLOCATION_LIMIT) return;

    Record** new_records = (Record**)realloc(collection->records, new_capacity * sizeof(Record*));
    long* new_offsets = (long*)realloc(collection->offsets, new_capacity * sizeof(long));
    int* new_keys = (int*)realloc(collection->keys, new_capacity * sizeof(int));

    if (!new_records || !new_offsets || !new_keys) return;

    collection->records = new_records;
    collection->offsets = new_offsets;
    collection->keys = new_keys;
    collection->capacity = new_capacity;
}

void insert_record(DynamicCollection* collection, long offset, int key) {
    if (collection->count >= collection->allocation_limit) return;

    if (collection->count == collection->capacity) resize_collection(collection);

    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) return;

    record->value = rand() % 100; // Random value between 0 and 99
    record->key_index = key;
    collection->records[collection->count] = record;
    collection->offsets[collection->count] = offset;
    collection->keys[collection->count] = key;
    collection->count++;
}

void cleanup_collection(DynamicCollection* collection) {
    for (size_t i = 0; i < collection->count; i++) {
        free(collection->records[i]);
    }
    free(collection->records);
    free(collection->offsets);
    free(collection->keys);
    free(collection);
}

int main() {
    DynamicCollection* collection = create_dynamic_collection(INITIAL_CAPACITY, MAX_ALLOCATION_LIMIT);

    if (collection) {
        insert_record(collection, 100L, 1);
        insert_record(collection, 200L, 2);
        // Add more records as needed

        cleanup_collection(collection);
    }

    return 0;
}
