    if (list->count >= list->capacity) {
        // Handle memory reallocation or warning
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    ElementData* new_element = &list->elements[list->count++];
    new_element->ue_info_tag = ue_info_tag;
    new_element->rnti = rnti;
    new_element->crc_indication_rel8_tag.CRCFLAG = (rand() / (float)RAND_MAX < PROBABILITY_THRESHOLD);
    new_element->timestamp = time(NULL);
    new_element->sequence_number = list->count - 1;
    new_element->status_flag = false;
    pthread_mutex_unlock(&list->mutex);
}

void cleanup_list(DynamicList* list) {
    pthread_mutex_lock(&list->mutex);
    free(list->elements);
    list->elements = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}
