// Define a structure for the record
typedef struct {
    int key;
    long offset;
} Record;

// Define a structure for the factory function
typedef Record* (*FactoryFunction)(int);

// Define a structure for the factory registry
typedef struct {
    FactoryFunction* factories;
    size_t size;
    size_t capacity;
} FactoryRegistry;

// Initialize the factory registry
void init_factory_registry(FactoryRegistry* registry) {
    registry->factories = NULL;
    registry->size = 0;
    registry->capacity = 0;
}

// Add a factory function to the registry
void add_factory(FactoryRegistry* registry, FactoryFunction factory) {
    if (registry->size >= registry->capacity) {
        size_t new_capacity = (registry->capacity == 0) ? 1 : registry->capacity * 2;
        registry->factories = realloc(registry->factories, new_capacity * sizeof(FactoryFunction));
        registry->capacity = new_capacity;
    }
    registry->factories[registry->size++] = factory;
}

// Create a record using the factory function
Record* create_record(int key, FactoryRegistry* registry) {
    if (key < 0 || key >= registry->size) {
        fprintf(stderr, "Invalid key for factory\n");
        return NULL;
    }
    FactoryFunction factory = registry->factories[key];
    return factory(key);
}

// Example factory function
Record* create_example_record(int key) {
    Record* record = malloc(sizeof(Record));
    record->key = key;
    record->offset = rand() % 1000; // Simulate a random offset
    return record;
}

// Serialize the record to JSON format
void serialize_to_json(Record* record, char** json) {
    *json = malloc(50); // Allocate enough space for the JSON string
    sprintf(*json, "{\"key\": %d, \"offset\": %ld}", record->key, record->offset);
}

// Deserialize the JSON string back to a record
Record* deserialize_from_json(const char* json) {
    Record* record = malloc(sizeof(Record));
    sscanf(json, "{\"key\": %d, \"offset\": %ld}", &record->key, &record->offset);
    return record;
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    FactoryRegistry registry;
    init_factory_registry(&registry);

    // Register a factory function
    add_factory(&registry, create_example_record);

    // Create a record using the factory
    Record* record = create_record(0, &registry);
    if (record != NULL) {
        printf("Record created: key=%d, offset=%ld\n", record->key, record->offset);

        // Serialize the record to JSON
        char* json;
        serialize_to_json(record, &json);
        printf("Serialized JSON: %s\n", json);

        // Deserialize the JSON back to a record
        Record* deserialized_record = deserialize_from_json(json);
        if (deserialized_record != NULL) {
            printf("Deserialized record: key=%d, offset=%ld\n", deserialized_record->key, deserialized_record->offset);
            free(deserialized_record);
        }

        // Free the serialized JSON string
        free(json);

        // Free the record
        free(record);
    }

    return 0;
}
