#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Edge {
    int weight;
    // Additional metadata can be added here
    struct Node* neighbor;
} Edge;

typedef struct Node {
    int id;
    Edge** edges;
    int edge_count;
} Node;

Node* create_node(int id, int n_edges) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        fprintf(stderr, "Memory allocation failed for node\n");
        return NULL;
    }
    node->id = id;
    node->edges = (Edge**)calloc(n_edges, sizeof(Edge*));
    if (!node->edges) {
        free(node);
        fprintf(stderr, "Memory allocation failed for edges\n");
        return NULL;
    }
    node->edge_count = 0;
    return node;
}

void add_edge(Node* from, Node* to, int weight) {
    Edge* edge = (Edge*)malloc(sizeof(Edge));
    if (!edge) {
        fprintf(stderr, "Memory allocation failed for edge\n");
        return;
    }
    edge->weight = weight;
    edge->neighbor = to;
    from->edges[from->edge_count++] = edge;
}

void initialize_graph(int n_nodes, int m_edges, int min_weight, int max_weight) {
    srand(time(NULL));
    Node** nodes = (Node**)calloc(n_nodes, sizeof(Node*));
    if (!nodes) {
        fprintf(stderr, "Memory allocation failed for nodes\n");
        return;
    }

    // Create nodes
    for (int i = 0; i < n_nodes; ++i) {
        nodes[i] = create_node(i, m_edges);
        if (!nodes[i]) {
            fprintf(stderr, "Failed to create node %d\n", i);
            return;
        }
    }

    // Add edges with random weights
    for (int i = 0; i < m_edges; ++i) {
        int from_id = rand() % n_nodes;
        int to_id = rand() % n_nodes;
        if (from_id == to_id) continue; // Avoid self-loops

        Node* from = nodes[from_id];
        Node* to = nodes[to_id];

        add_edge(from, to, min_weight + rand() % (max_weight - min_weight + 1));
    }

    // Perform graph traversal and other operations here
}

void free_graph(Node** nodes, int n_nodes) {
    for (int i = 0; i < n_nodes; ++i) {
        Node* node = nodes[i];
        if (node->edges) {
            for (int j = 0; j < node->edge_count; ++j) {
                free(node->edges[j]);
            }
            free(node->edges);
        }
        free(node);
    }
    free(nodes);
}

int main() {
    int n_nodes = 100;
    int m_edges = 500;
    int min_weight = 1;
    int max_weight = 10;

    initialize_graph(n_nodes, m_edges, min_weight, max_weight);

    // Perform other operations and clean up
    free_graph(nodes, n_nodes);

    return 0;
}
```

This code provides a basic structure for managing a dynamic graph with nodes and edges. It includes functions to create nodes, add edges with random weights, initialize the graph, and free allocated memory. The `initialize_graph` function demonstrates how to populate the graph with random edge weights and avoid self-loops. Error checking is performed during memory allocations, and detailed error logs are printed if failures occur. The `free_graph` function ensures that all allocated memory is freed correctly, preventing dangling pointers.']

