public class MemoryManager
{
    private const int StackArrayThreshold = 1024; // Define the threshold for stack-based allocation

    public static string HashAndManageMemory(string input, int n, bool useHeapForLargeArrays)
    {
        byte[] hashBytes = GenerateMd5Hash(input);
        long max_offset = (long)n * 1000;
        long max_key = (long)n * 10;

        long[] offsets;
        int[] keys;

        if (useHeapForLargeArrays && n > StackArrayThreshold)
        {
            offsets = new long[n];
            keys = new int[n];
        }
        else
        {
            unsafe
            {
                fixed (long* pOffsets = stackalloc long[n])
                    offsets = pOffsets;
                fixed (int* pKeys = stackalloc int[n])
                    keys = pKeys;
            }
        }

        InitializeArrays(offsets, max_offset);
        InitializeKeys(keys, offsets, max_key);

        Record[] records = CreateRecords(n, offsets, keys, min_value: 0, max_value: 1000);

        // Perform concurrent operations and memory management here

        FreeMemory(records, offsets, keys);

        return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
    }

    private static byte[] GenerateMd5Hash(string input)
    {
        using (MD5 md5 = MD5.Create())
        {
            return md5.ComputeHash(Encoding.UTF8.GetBytes(input));
        }
    }

    private static void InitializeArrays(long[] offsets, long max_offset)
    {
        for (int i = 0; i < offsets.Length; i++)
        {
            offsets[i] = i * 10;
        }
    }

    private static void InitializeKeys(int[] keys, long[] offsets, long max_key)
    {
        Random random = new Random();
        HashSet<int> usedKeys = new HashSet<int>();

        for (int i = 0; i < keys.Length; i++)
        {
            int key;
            do
            {
                key = random.Next((int)max_key);
            } while (!usedKeys.Add(key) || key >= offsets[i]);
            keys[i] = key;
        }
    }

    private static Record[] CreateRecords(int n, long[] offsets, int[] keys, int min_value, int max_value)
    {
        Random random = new Random();
        Record[] records = new Record[n];

        for (int i = 0; i < n; i++)
        {
            records[i] = new Record
            {
                Value = random.Next(min_value, max_value + 1),
                Offset = offsets[i],
                Key = keys[i]
            };
        }

        return records;
    }

    private static void FreeMemory(Record[] records, long[] offsets, int[] keys)
    {
        // Implement memory deallocation logic here
    }
}

