#include <pthread.h>

#define MAX_IP_LENGTH 16
#define MAX_NFAPI_ENTRIES 1024

typedef struct {
    u_char ip[MAX_IP_LENGTH];
    int rnti;
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    int rnti;
    NFAPI_CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

int resolve_dns_and_populate_nfaapi(const char *hostname, NFAPI_CRC_INDICATION_PDU_T *nfaapi_entries, int max_entries) {
    struct addrinfo hints, *res, *p;
    int status;
    char ipstr[MAX_IP_LENGTH];

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return -1;
    }

    int entry_count = 0;
    for (p = res; p != NULL && entry_count < max_entries; p = p->ai_next) {
        void *addr;
        char *ipver;

        // get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
            ipver = "IPv4";
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
            ipver = "IPv6";
        }

        // convert the IP to a string and print it:
        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);
        printf("  %s: %s\n", ipver, ipstr);

        // Populate NFAPI entries
        if (entry_count < max_entries) {
            memcpy(nfaapi_entries[entry_count].rx_ue_info_tag.ip, ipstr, strlen(ipstr));
            nfaapi_entries[entry_count].rnti = rand() % 65536; // Random RNTI
            nfaapi_entries[entry_count].crc_indication_rel8_tag.crcflag = rand() % 2; // Random CRCFLAG
            entry_count++;
        }
    }

    freeaddrinfo(res); // free the linked list

    return entry_count;
}

// Thread-safe version using mutex
pthread_mutex_t nfaapi_mutex = PTHREAD_MUTEX_INITIALIZER;

int resolve_dns_and_populate_nfaapi_thread_safe(const char *hostname, NFAPI_CRC_INDICATION_PDU_T *nfaapi_entries, int max_entries) {
    pthread_mutex_lock(&nfaapi_mutex);
    int result = resolve_dns_and_populate_nfaapi(hostname, nfaapi_entries, max_entries);
    pthread_mutex_unlock(&nfaapi_mutex);
    return result;
}
