typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} NFAPI_CRC_LIST_T;

NFAPI_CRC_LIST_T* create_crc_list() {
    NFAPI_CRC_LIST_T *list = (NFAPI_CRC_LIST_T*)malloc(sizeof(NFAPI_CRC_LIST_T));
    if (!list) return NULL;
    list->data = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_crc_list(NFAPI_CRC_LIST_T *list) {
    pthread_mutex_lock(&list->lock);
    free(list->data);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_to_crc_list(NFAPI_CRC_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T item, int threshold) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }
    if (item.CRCFLAG >= threshold) {
        list->data[list->count++] = item;
    }
    pthread_mutex_unlock(&list->lock);
    return 0;
}

