pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_measurements() {
    measurement_list = (LTE_PHY_MEASUREMENTS *)malloc(MAX_CELLS * sizeof(LTE_PHY_MEASUREMENTS));
    if (!measurement_list) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

void populate_measurements(int num_cells) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_cells; ++i) {
        measurement_list[i].cell_id = i + 1;
        measurement_list[i].EVM = (float)(rand() % 100) / 10.0f;
        measurement_list[i].BER = (float)(rand() % 100) / 1000.0f;
        measurement_list[i].RSSI = rand() % 100;
    }
    list_size = num_cells;
    pthread_mutex_unlock(&mutex);
}

void filter_measurements(float evm_threshold) {
    pthread_mutex_lock(&mutex);
    int filtered_count = 0;
    for (int i = 0; i < list_size; ++i) {
        if (measurement_list[i].EVM >= evm_threshold) {
            measurement_list[filtered_count++] = measurement_list[i];
        }
    }
    list_size = filtered_count;
    pthread_mutex_unlock(&mutex);
}

void serialize_measurements(const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    pthread_mutex_lock(&mutex);
    fwrite(measurement_list, sizeof(LTE_PHY_MEASUREMENTS), list_size, file);
    pthread_mutex_unlock(&mutex);

    fclose(file);
}

void deserialize_measurements(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }

    pthread_mutex_lock(&mutex);
    list_size = fread(measurement_list, sizeof(LTE_PHY_MEASUREMENTS), MAX_CELLS, file);
    pthread_mutex_unlock(&mutex);

    fclose(file);
}

