#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <json-c/json.h>

// Define a structure for a record
typedef struct {
    int key;
    long offset;
    char* identifier;
    int value;
} Record;

// Define a factory function type
typedef Record* (*FactoryFunction)(int);

// Factory registry
typedef struct {
    int id;
    FactoryFunction factory;
} FactoryRegistryEntry;

FactoryRegistryEntry factoryRegistry[100];
int factoryCount = 0;

// Register a new factory function
void registerFactory(int id, FactoryFunction factory) {
    if (factoryCount < 100) {
        factoryRegistry[factoryCount].id = id;
        factoryRegistry[factoryCount].factory = factory;
        factoryCount++;
    }
}

// Create a record using a factory function
Record* createRecord(int key, int factoryId) {
    for (int i = 0; i < factoryCount; i++) {
        if (factoryRegistry[i].id == factoryId) {
            return factoryRegistry[i].factory(key);
        }
    }
    return NULL;
}

// Factory function to create a new record
Record* createRandomRecord(int key) {
    Record* record = (Record*)malloc(sizeof(Record));
    record->key = key;
    record->offset = rand();
    time_t now = time(NULL);
    char buffer[20];
    strftime(buffer, sizeof(buffer), "%Y%m%d%H%M%S", localtime(&now));
    record->identifier = strdup(buffer);
    record->value = rand() % 100; // Random value between 0 and 99
    return record;
}

// Serialize a record to JSON
json_object* serializeRecord(Record* record) {
    json_object* jobj = json_object_new_object();
    json_object_object_add(jobj, "key", json_object_new_int(record->key));
    json_object_object_add(jobj, "offset", json_object_new_long(record->offset));
    json_object_object_add(jobj, "identifier", json_object_new_string(record->identifier));
    json_object_object_add(jobj, "value", json_object_new_int(record->value));
    return jobj;
}

// Deserialize a JSON string to a record
Record* deserializeRecord(const char* jsonString) {
    json_object* jobj = json_tokener_parse(jsonString);
    if (jobj == NULL) {
        fprintf(stderr, "Failed to parse JSON\n");
        return NULL;
    }
    Record* record = (Record*)malloc(sizeof(Record));
    record->key = json_object_get_int(json_object_object_get(jobj, "key"));
    record->offset = json_object_get_long(json_object_object_get(jobj, "offset"));
    record->identifier = strdup(json_object_get_string(json_object_object_get(jobj, "identifier")));
    record->value = json_object_get_int(json_object_object_get(jobj, "value"));
    return record;
}

// Free a record
void freeRecord(Record* record) {
    free(record->identifier);
    free(record);
}

int main() {
    // Register the factory function
    registerFactory(1, createRandomRecord);

    // Create a new record using the factory
    Record* record = createRecord(1, 1);

    // Serialize the record to JSON
    json_object* jobj = serializeRecord(record);
    const char* jsonString = json_object_to_json_string(jobj);
    printf("Serialized JSON: %s\n", jsonString);

    // Deserialize the JSON back to a record
    Record* deserializedRecord = deserializeRecord(jsonString);

    // Free the records
    freeRecord(record);
    freeRecord(deserializedRecord);

    return 0;
}
