typedef struct HttpRequest {
    char *url;
    char **headers;
    int header_count;
    char *body;
    int body_length;
    pthread_mutex_t lock;
} HttpRequest;

typedef struct RequestCollection {
    HttpRequest **requests;
    int count;
    int capacity;
    pthread_mutex_t lock;
} RequestCollection;

void init_request_collection(RequestCollection *collection) {
    collection->requests = NULL;
    collection->count = 0;
    collection->capacity = 0;
    pthread_mutex_init(&collection->lock, NULL);
}

void free_request(HttpRequest *request) {
    if (request == NULL) return;
    pthread_mutex_lock(&request->lock);
    free(request->url);
    for (int i = 0; i < request->header_count; i++) {
        free(request->headers[i]);
    }
    free(request->headers);
    free(request->body);
    pthread_mutex_unlock(&request->lock);
    pthread_mutex_destroy(&request->lock);
    free(request);
}

void free_request_collection(RequestCollection *collection) {
    if (collection == NULL) return;
    pthread_mutex_lock(&collection->lock);
    for (int i = 0; i < collection->count; i++) {
        free_request(collection->requests[i]);
    }
    free(collection->requests);
    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
}

HttpRequest *create_request(const char *url, const char **headers, int header_count, const char *body, int body_length) {
    HttpRequest *request = (HttpRequest *)malloc(sizeof(HttpRequest));
    if (request == NULL) return NULL;
    request->url = strdup(url);
    request->header_count = header_count;
    request->headers = (char **)malloc(header_count * sizeof(char *));
    for (int i = 0; i < header_count; i++) {
        request->headers[i] = strdup(headers[i]);
    }
    request->body = (char *)malloc(body_length);
    if (request->url == NULL || request->headers == NULL || request->body == NULL) {
        free_request(request);
        return NULL;
    }
    memcpy(request->body, body, body_length);
    request->body_length = body_length;
    pthread_mutex_init(&request->lock, NULL);
    return request;
}

void add_request(RequestCollection *collection, HttpRequest *request) {
    pthread_mutex_lock(&collection->lock);
    if (collection->count == collection->capacity) {
        int new_capacity = collection->capacity == 0 ? 1 : collection->capacity * 2;
        HttpRequest **new_requests = (HttpRequest **)realloc(collection->requests, new_capacity * sizeof(HttpRequest *));
        if (new_requests == NULL) {
            pthread_mutex_unlock(&collection->lock);
            return;
        }
        collection->requests = new_requests;
        collection->capacity = new_capacity;
    }
    collection->requests[collection->count++] = request;
    pthread_mutex_unlock(&collection->lock);
}

