    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    // Dynamically allocate memory for integers
    int* numbers = (int*)malloc(maxLimit * sizeof(int));
    if (!numbers) {
        fclose(file);
        perror("Memory allocation failed");
        return NULL;
    }

    int count = 0;
    while (count < maxLimit && fscanf(file, "%d", &numbers[count]) == 1) {
        count++;
    }
    fclose(file);

    // Handle edge cases
    if (count == 0) {
        free(numbers);
        printf("Input file is empty.\n");
        return NULL;
    }

    // Calculate largest, smallest, and average
    int max = numbers[0];
    int min = numbers[0];
    double sum = 0.0;
    for (int i = 0; i < count; i++) {
        if (numbers[i] > max) max = numbers[i];
        if (numbers[i] < min) min = numbers[i];
        sum += numbers[i];
    }
    double average = sum / count;

    printf("Largest: %d\n", max);
    printf("Smallest: %d\n", min);
    printf("Average: %.2f\n", average);

    // Generate new filename
    char* newFilename = (char*)malloc(MAX_FILENAME_LENGTH * sizeof(char));
    if (!newFilename) {
        free(numbers);
        perror("Memory allocation failed");
        return NULL;
    }

    time_t now = time(NULL);
    struct tm* timeinfo = localtime(&now);
    int randomId = rand() % 1000; // Simplified for example
    int numericSequence = max + min;

    snprintf(newFilename, MAX_FILENAME_LENGTH, "processed_%s_%d_%d.txt", 
             asctime(timeinfo), randomId, numericSequence);

    // Rename the file (this part depends on the operating system)
#ifdef _WIN32
    if (MoveFile(inputFilename, newFilename) == 0) {
        perror("Failed to rename file");
#else
    if (rename(inputFilename, newFilename) != 0) {
        perror("Failed to rename file");
#endif
        free(numbers);
        free(newFilename);
        return NULL;
    }

    // Free allocated memory
    free(numbers);

    return newFilename;
}
