import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class ProjectManagementService {
    private static final Logger logger = LoggerFactory.getLogger(ProjectManagementService.class);
    private List<Project> projectList;
    private ExternalSystemIntegration externalSystem;

    public ProjectManagementService(int initialCapacity) {
        this.projectList = new ArrayList<>(initialCapacity);
        this.externalSystem = new ExternalSystemIntegration();
        initializeProjects(initialCapacity);
    }

    private void initializeProjects(int capacity) {
        for (int i = 0; i < capacity; i++) {
            double budget = 10000 * (i + 1);
            projectList.add(new Project(budget, "Active", null));
        }
    }

    public void updateProjectStatus(String projectName, String newStatus) {
        for (Project project : projectList) {
            if (project.getName().equals(projectName)) {
                project.setStatus(newStatus);
                if ("Completed".equals(newStatus)) {
                    recalculateCompletionDate(project);
                    adjustBudget(project);
                }
                break;
            }
        }
    }

    private void recalculateCompletionDate(Project project) {
        // Logic to calculate completion date based on progress metrics
        logger.info("Recalculating completion date for project: {}", project.getName());
    }

    private void adjustBudget(Project project) {
        // Logic to adjust budget based on scope changes
        logger.info("Adjusting budget for project: {}", project.getName());
    }

    public void exportToCSV(String filePath) {
        try (BufferedWriter writer = new BufferedWriter(new FileWriter(filePath))) {
            writer.write("Project Name,Budget,Status,Completion Date\n");
            for (Project project : projectList) {
                writer.write(project.toCSV() + "\n");
            }
        } catch (IOException e) {
            logger.error("Error exporting to CSV: {}", e.getMessage());
        }
    }

    public void processBatch(List<String> projectNames) {
        ExecutorService executor = Executors.newFixedThreadPool(10);
        for (String projectName : projectNames) {
            executor.submit(() -> updateProjectStatus(projectName, "Completed"));
        }
        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }

    public static void main(String[] args) {
        ProjectManagementService service = new ProjectManagementService(1000);
        // Simulate processing a batch of projects
        List<String> projectNames = Arrays.asList("Project A", "Project B", "Project C");
        service.processBatch(projectNames);
        service.exportToCSV("projects.csv");
    }
}

class Project {
    private String name;
    private double budget;
    private String status;
    private LocalDateTime completionDate;

    public Project(double budget, String status, LocalDateTime completionDate) {
        this.budget = budget;
        this.status = status;
        this.completionDate = completionDate;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public double getBudget() {
        return budget;
    }

    public void setBudget(double budget) {
        this.budget = budget;
    }

    public String getStatus() {
        return status;
    }

    public void setStatus(String status) {
        this.status = status;
    }

    public LocalDateTime getCompletionDate() {
        return completionDate;
    }

    public void setCompletionDate(LocalDateTime completionDate) {
        this.completionDate = completionDate;
    }

    public String toCSV() {
        return name + "," + budget + "," + status + "," + (completionDate != null ? completionDate.toString() : "");
    }
}

class ExternalSystemIntegration {
    // Logic for real-time updates on project costs and deadlines
}
