#include <time.h>

#define MAX_RECORDS 1000000
#define MAX_MEMORY_LIMIT (1024 * 1024 * 1024) // 1GB

typedef struct {
    int value;
} record;

int allocate_memory(long **offsets, int **keys, record **records, int num_records) {
    size_t total_size = sizeof(record) * num_records + sizeof(long) * num_records + sizeof(int) * num_records;
    if (total_size > MAX_MEMORY_LIMIT) {
        fprintf(stderr, "Memory allocation exceeds limit\n");
        return -1;
    }

    *offsets = (long *)malloc(sizeof(long) * num_records);
    *keys = (int *)malloc(sizeof(int) * num_records);
    *records = (record *)malloc(sizeof(record) * num_records);

    if (!*offsets || !*keys || !*records) {
        fprintf(stderr, "Memory allocation failed\n");
        free(*offsets);
        free(*keys);
        free(*records);
        return -1;
    }

    return 0;
}

void initialize_arrays(long *offsets, int *keys, record *records, int num_records) {
    srand(time(NULL));

    for (int i = 0; i < num_records; ++i) {
        offsets[i] = rand() % MAX_RECORDS;
        keys[i] = rand() % MAX_RECORDS;

        // Ensure no duplicate offsets
        for (int j = 0; j < i; ++j) {
            if (offsets[j] == offsets[i]) {
                offsets[i] = rand() % MAX_RECORDS;
                --i;
                break;
            }
        }

        records[i].value = rand() % 1000;
    }
}

void free_memory(long *offsets, int *keys, record *records) {
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    long *offsets;
    int *keys;
    record *records;
    int num_records = 1000;

    if (allocate_memory(&offsets, &keys, &records, num_records) != 0) {
        return -1;
    }

    initialize_arrays(offsets, keys, records, num_records);

    // Use the records array...

    free_memory(offsets, keys, records);
    return 0;
}
