    RecordManager* manager = (RecordManager*)malloc(sizeof(RecordManager));
    if (!manager) return NULL;

    manager->records = (record*)calloc(num_records, RECORD_SIZE);
    manager->crc_indications = (NFAPI_CRC_INDICATION_PDU_T*)calloc(num_crc_indications, NFAPI_CRC_INDICATION_PDU_T_SIZE);
    manager->num_records = num_records;
    manager->num_crc_indications = num_crc_indications;

    if (!manager->records || !manager->crc_indications) {
        free(manager->records);
        free(manager->crc_indications);
        free(manager);
        return NULL;
