        manager->crc_indications[i].RX_UE_INFORMATION_TAG = rand();
        manager->crc_indications[i].RNTI = rand() % 1024; // Random RNTI between 0 and 1023
        manager->crc_indications[i].CRC_INDICATION_REL8_TAG = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG to 0 or 1
    }

    return manager;
}

void destroy_record_manager(RecordManager* manager) {
    if (!manager) return;

    pthread_mutex_destroy(&manager->mutex);
    free(manager->records);
    free(manager->crc_indications);
    free(manager);
}

size_t filter_crc_indications(RecordManager* manager, uint8_t threshold) {
    size_t count = 0;
    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->num_crc_indications; ++i) {
        if (manager->crc_indications[i].CRC_INDICATION_REL8_TAG == threshold) {
            ++count;
        }
    }

    pthread_mutex_unlock(&manager->mutex);
    return count;
}

