Entry* allocate_entries(int num_entries, int metadata_size, int data_chunk_size, int min_index, int max_index) {
    Entry* entries = (Entry*)malloc(num_entries * sizeof(Entry));
    if (!entries) return NULL;

    for (int i = 0; i < num_entries; i++) {
        entries[i].data_chunk = allocate_metadata_data_chunk(metadata_size, data_chunk_size);
        if (!entries[i].data_chunk) {
            free_entries(entries, i);
            return NULL;
        }

        entries[i].index = allocate_index(metadata_size, min_index, max_index);
        if (!entries[i].index) {
            free_entries(entries, i);
            return NULL;
        }
    }

    return entries;
}

void free_entries(Entry* entries, int num_entries) {
    for (int i = 0; i < num_entries; i++) {
        free_metadata_data_chunk(entries[i].data_chunk);
        free_index(entries[i].index);
    }
    free(entries);
}

sem_t* create_semaphore(int initial_value) {
    sem_t* semaphore = sem_open("/my_semaphore", O_CREAT, 0644, initial_value);
