#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct LTE_TRANSPORT_BLOCK_T {
    int TID;
    // Other fields...
    struct LTE_TRANSPORT_BLOCK_T *next;
} LTE_TRANSPORT_BLOCK_T;

typedef struct {
    pthread_mutex_t lock;
    pthread_rwlock_t rwlock;
    LTE_TRANSPORT_BLOCK_T *head;
    int max_blocks;
    int active_blocks;
} TRANSPORT_LIST_T;

TRANSPORT_LIST_T* create_transport_list(int max_blocks) {
    TRANSPORT_LIST_T *list = (TRANSPORT_LIST_T*)malloc(sizeof(TRANSPORT_LIST_T));
    if (!list) return NULL;

    pthread_mutex_init(&list->lock, NULL);
    pthread_rwlock_init(&list->rwlock, NULL);
    list->head = NULL;
    list->max_blocks = max_blocks;
    list->active_blocks = 0;

    return list;
}

void destroy_transport_list(TRANSPORT_LIST_T *list) {
    LTE_TRANSPORT_BLOCK_T *current = list->head;
    while (current) {
        LTE_TRANSPORT_BLOCK_T *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    pthread_rwlock_destroy(&list->rwlock);
    free(list);
}

int insert_block(TRANSPORT_LIST_T *list, int TID) {
    pthread_mutex_lock(&list->lock);

    if (list->active_blocks >= list->max_blocks) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Max blocks reached
    }

    LTE_TRANSPORT_BLOCK_T *new_block = (LTE_TRANSPORT_BLOCK_T*)malloc(sizeof(LTE_TRANSPORT_BLOCK_T));
    if (!new_block) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Allocation failure
    }

    new_block->TID = TID;
    new_block->next = list->head;
    list->head = new_block;
    list->active_blocks++;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

int delete_block(TRANSPORT_LIST_T *list, int TID) {
    pthread_mutex_lock(&list->lock);

    LTE_TRANSPORT_BLOCK_T *current = list->head;
    LTE_TRANSPORT_BLOCK_T *prev = NULL;

    while (current) {
        if (current->TID == TID) {
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }
            free(current);
            list->active_blocks--;
            pthread_mutex_unlock(&list->lock);
            return 0; // Success
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Block not found
}

