        offsets[i] = i * 10; // Example initialization
    }

    // Initialize keys with random values
    srand(time(NULL));
    for (long i = 0; i < num_keys; ++i) {
        keys[i] = rand() % (max_val - min_val + 1) + min_val;
    }

    // Initialize records with random values
    for (long i = 0; i < num_records; ++i) {
        records[i].value = rand() % (max_val - min_val + 1) + min_val;
    }

    // Print records in reverse order
    printf("Records in reverse order:\n");
    for (long i = num_records - 1; i >= 0; --i) {
        printf("%d\n", records[i].value);
    }

    // Free allocated memory
