#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Record {
    double value;
    char* str;
    size_t length;
} Record;

typedef struct RecordCollection {
    Record** records;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} RecordCollection;

RecordCollection* create_record_collection(size_t initial_capacity) {
    RecordCollection* collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->records = (Record**)malloc(initial_capacity * sizeof(Record*));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->count = 0;
    collection->capacity = initial_capacity;
    pthread_mutex_init(&collection->mutex, NULL);

    return collection;
}

void destroy_record_collection(RecordCollection* collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->records[i]->str);
        free(collection->records[i]);
    }
    free(collection->records);
    pthread_mutex_destroy(&collection->mutex);
    free(collection);
}

int add_record(RecordCollection* collection, double value, const char* str) {
    pthread_mutex_lock(&collection->mutex);

    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity ? collection->capacity * 2 : 1;
        Record** new_records = (Record**)realloc(collection->records, new_capacity * sizeof(Record*));
        if (!new_records) {
            pthread_mutex_unlock(&collection->mutex);
            return -1; // Memory allocation failure
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) {
        pthread_mutex_unlock(&collection->mutex);
        return -1; // Memory allocation failure
    }

    record->value = value;
    record->length = strlen(str);
    record->str = (char*)malloc(record->length + 1);
    if (!record->str) {
        free(record);
        pthread_mutex_unlock(&collection->mutex);
        return -1; // Memory allocation failure
    }
    strcpy(record->str, str);

    collection->records[collection->count++] = record;
    pthread_mutex_unlock(&collection->mutex);

    return 0;
}

