void initialize_arrays(int offset_size, int key_size, int record_count, int range_start, int range_end, int threshold) {
    if (offset_size > MAX_SIZE || key_size > MAX_SIZE || record_count > MAX_SIZE) {
        fprintf(stderr, "Error: Size exceeds maximum limit.\n");
        return;
    }

    long *offsets = (long *)malloc(offset_size * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Error: Failed to allocate memory for offsets.\n");
        return;
    }

    int *keys = (int *)malloc(key_size * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Error: Failed to allocate memory for keys.\n");
        free(offsets);
        return;
    }

    record *records = (record *)malloc(record_count * sizeof(record));
    if (!records) {
        fprintf(stderr, "Error: Failed to allocate memory for records.\n");
        free(offsets);
        free(keys);
        return;
    }

    int tracking_sum[record_count];
    for (int i = 0; i < record_count; i++) {
        tracking_sum[i] = 0;
    }

    srand(time(NULL));
    for (int i = 0; i < record_count; i++) {
        records[i].value = rand() % (range_end - range_start + 1) + range_start;
        tracking_sum[i] += records[i].value;
        if (i > 0) {
            tracking_sum[i] += tracking_sum[i - 1];
        }
    }

    for (int i = record_count - 1; i >= 0; i--) {
        if (tracking_sum[i] > threshold) {
            printf("Record %d: %d\n", i, records[i].value);
        }
    }

    free(offsets);
    free(keys);
    free(records);
}

int main() {
    int offset_size, key_size, record_count, range_start, range_end, threshold;

    printf("Enter the size of offsets array: ");
    scanf("%d", &offset_size);

    printf("Enter the size of keys array: ");
    scanf("%d", &key_size);

    printf("Enter the number of records: ");
    scanf("%d", &record_count);

    printf("Enter the range start for record values: ");
    scanf("%d", &range_start);

    printf("Enter the range end for record values: ");
    scanf("%d", &range_end);

    printf("Enter the threshold for tracking sum: ");
    scanf("%d", &threshold);

    initialize_arrays(offset_size, key_size, record_count, range_start, range_end, threshold);

    return 0;
}
