#define MAX_NUMBERS 1000
#define MIN_VALUE 10
#define MAX_VALUE 100
#define MAX_SUM 1000000

int process_integers() {
    int *numbers = (int *)malloc(MAX_NUMBERS * sizeof(int));
    if (numbers == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    int count = 0, sum = 0, largest = MIN_VALUE - 1;

    while (count < MAX_NUMBERS && scanf("%d", &numbers[count]) == 1) {
        if (numbers[count] < MIN_VALUE || numbers[count] > MAX_VALUE) {
            fprintf(stderr, "Invalid input: %d is out of range\n", numbers[count]);
            continue;
        }

        sum += numbers[count];
        if (sum > MAX_SUM) {
            printf("Sum exceeds limit. Terminating early.\n");
            break;
        }

        if (numbers[count] > largest) {
            largest = numbers[count];
        }
    }

    free(numbers);
    return largest;
}

void free_integers(int *numbers, int count) {
    free(numbers);
}

int main() {
    int largest = process_integers();
    printf("Largest integer: %d\n", largest);
    return 0;
}
