#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 1024
#define MAX_RECORDS 1000000
#define PERSISTENCE_INTERVAL 60

typedef struct record {
    long offset;
    int key;
    struct record *next;
} Record;

typedef struct collection {
    Record **records;
    size_t capacity;
    size_t size;
    size_t allocated_records;
    pthread_mutex_t lock;
} Collection;

void init_collection(Collection *col, size_t initial_capacity) {
    col->capacity = initial_capacity;
    col->size = 0;
    col->allocated_records = 0;
    col->records = (Record **)malloc(initial_capacity * sizeof(Record *));
    pthread_mutex_init(&col->lock, NULL);
}

void resize_collection(Collection *col) {
    size_t new_capacity = col->capacity * 1.5;
    Record **new_records = (Record **)realloc(col->records, new_capacity * sizeof(Record *));
    if (new_records == NULL) {
        fprintf(stderr, "Failed to resize collection\n");
        return;
    }
    col->records = new_records;
    col->capacity = new_capacity;
}

void add_record(Collection *col, long offset, int key) {
    pthread_mutex_lock(&col->lock);
    if (col->size >= col->capacity) {
        resize_collection(col);
    }
    Record *new_record = (Record *)malloc(sizeof(Record));
    if (new_record == NULL) {
        fprintf(stderr, "Failed to allocate record\n");
        pthread_mutex_unlock(&col->lock);
        return;
    }
    new_record->offset = offset;
    new_record->key = key;
    new_record->next = NULL;
    col->records[col->size++] = new_record;
    col->allocated_records++;
    pthread_mutex_unlock(&col->lock);
}

void cleanup_collection(Collection *col) {
    pthread_mutex_lock(&col->lock);
    for (size_t i = 0; i < col->size; i++) {
        free(col->records[i]);
    }
    free(col->records);
    col->records = NULL;
    col->capacity = 0;
    col->size = 0;
    col->allocated_records = 0;
    pthread_mutex_unlock(&col->lock);
}

void *thread_function(void *arg) {
    Collection *col = (Collection *)arg;
    for (int i = 0; i < 1000; i++) {
        add_record(col, rand(), rand());
    }
    return NULL;
}

int main() {
    srand(time(NULL));
    Collection col;
    init_collection(&col, INITIAL_CAPACITY);

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, thread_function, &col);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    cleanup_collection(&col);

    return 0;
}
