} Project;

Project projects[MAX_PROJECTS];
int project_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_projects() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MAX_PROJECTS; i++) {
        projects[i].budget = 10000.0 * (i + 1);
        projects[i].status = strdup("Active");
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        tm_info->tm_mon += rand() % 7; // Random months between 0 and 6
        mktime(tm_info);
        projects[i].completion_deadline = mktime(tm_info);
    }
    project_count = MAX_PROJECTS;
    pthread_mutex_unlock(&mutex);
}

void cleanup_projects() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < project_count; i++) {
        free(projects[i].status);
    }
    pthread_mutex_unlock(&mutex);
}

void update_project(int index, double budget, const char *status, time_t deadline) {
    pthread_mutex_lock(&mutex);
    if (index >= 0 && index < project_count) {
        projects[index].budget = budget > MAX_BUDGET ? MAX_BUDGET : budget;
        free(projects[index].status);
        projects[index].status = strdup(status);
        projects[index].completion_deadline = deadline;
    }
    pthread_mutex_unlock(&mutex);
}

void *submit_to_api(void *arg) {
    // Simulate API submission
    printf("Submitting project data to API...\n");
    return NULL;
}

int main() {
    srand(time(NULL));
    initialize_projects();

    pthread_t api_thread;
    pthread_create(&api_thread, NULL, submit_to_api, NULL);
    pthread_join(api_thread, NULL);

    cleanup_projects();
    return 0;
}
