            pthread_mutex_unlock(&array->lock);
            return -1; // Memory allocation failed
        }
        array->pdus = new_pdus;
        array->capacity = new_capacity;
    }
    array->pdus[array->count++] = pdu;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

int delete_pdu(LTE_RRCNAS_PDUS_ARRAY *array, uint32_t identifier) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->count; ++i) {
        if (array->pdus[i].identifier == identifier) {
            // Free any dynamically allocated memory within the PDU
            memmove(&array->pdus[i], &array->pdus[i + 1], (array->count - i - 1) * sizeof(LTE_RRCNAS_PDU_T));
            array->count--;
            pthread_mutex_unlock(&array->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&array->lock);
    return -1; // PDU not found
}

LTE_RRCNAS_PDU_T* get_pdu_by_identifier(LTE_RRCNAS_PDUS_ARRAY *array, uint32_t identifier) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->count; ++i) {
        if (array->pdus[i].identifier == identifier) {
            pthread_mutex_unlock(&array->lock);
            return &array->pdus[i];
        }
    }
    pthread_mutex_unlock(&array->lock);
    return NULL; // PDU not found
}

int serialize_pdus_array(LTE_RRCNAS_PDUS_ARRAY *array, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        return -1; // File open failed
    }
    fwrite(&array->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < array->count; ++i) {
        fwrite(&array->pdus[i], sizeof(LTE_RRCNAS_PDU_T), 1, file);
    }
    fclose(file);
    return 0;
}

int deserialize_pdus_array(LTE_RRCNAS_PDUS_ARRAY *array, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        return -1; // File open failed
    }
    size_t count;
    fread(&count, sizeof(size_t), 1, file);
    if (count > array->capacity) {
        LTE_RRCNAS_PDU_T *new_pdus = realloc(array->pdus, count * sizeof(LTE_RRCNAS_PDU_T));
        if (!new_pdus) {
            fclose(file);
            return -1; // Memory allocation failed
        }
        array->pdus = new_pdus;
        array->capacity = count;
    }
    for (size_t i = 0; i < count; ++i) {
        fread(&array->pdus[i], sizeof(LTE_RRCNAS_PDU_T), 1, file);
    }
    fclose(file);
    array->count = count;
    return 0;
}
