#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define MAX_LIMIT 300
#define RANDOM_RANGE 100

typedef struct record {
    long offset;
    int key;
    struct record *next;
} Record;

typedef struct dynamic_collection {
    Record **records;
    int capacity;
    int size;
    int allocated_count;
} DynamicCollection;

DynamicCollection* create_collection(int initial_capacity) {
    DynamicCollection *collection = (DynamicCollection*)malloc(sizeof(DynamicCollection));
    collection->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    collection->capacity = initial_capacity;
    collection->size = 0;
    collection->allocated_count = 0;
    return collection;
}

void resize_collection(DynamicCollection *collection) {
    int new_capacity = collection->capacity * 1.5;
    Record **new_records = (Record**)realloc(collection->records, new_capacity * sizeof(Record*));
    if (new_records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    for (int i = collection->capacity; i < new_capacity; i++) {
        new_records[i] = NULL;
    }
    collection->records = new_records;
    collection->capacity = new_capacity;
}

void insert_record(DynamicCollection *collection, long offset) {
    if (collection->allocated_count >= MAX_LIMIT) {
        fprintf(stderr, "Memory limit reached\n");
        return;
    }
    Record *new_record = (Record*)malloc(sizeof(Record));
    new_record->offset = offset;
    new_record->key = rand() % RANDOM_RANGE;
    new_record->next = NULL;

    int index = collection->size % collection->capacity;
    if (collection->records[index] != NULL) {
        resize_collection(collection);
        index = collection->size % collection->capacity;
    }
    collection->records[index] = new_record;
    collection->size++;
    collection->allocated_count++;
}

void cleanup_collection(DynamicCollection *collection) {
    for (int i = 0; i < collection->capacity; i++) {
        Record *current = collection->records[i];
        while (current != NULL) {
            Record *next = current->next;
            free(current);
            current = next;
        }
    }
    free(collection->records);
    free(collection);
}

void log_operation(int success, const char *message) {
    if (success) {
        printf("Success: %s\n", message);
    } else {
        fprintf(stderr, "Failure: %s\n", message);
    }
}

int main() {
    srand(time(NULL));
    DynamicCollection *collection = create_collection(INITIAL_CAPACITY);

    for (int i = 0; i < 150; i++) {
        insert_record(collection, i);
    }

    cleanup_collection(collection);
    return 0;
}
