typedef struct Record {
    int value;
} Record;

typedef struct Node {
    int key;
    long offset;
    Record *record;
    struct Node *left, *right;
} Node;

Node* newNode(int key, long offset, Record *record) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (node == NULL) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    node->key = key;
    node->offset = offset;
    node->record = record;
    node->left = node->right = NULL;
    return node;
}

Node* insert(Node* node, int key, long offset, Record *record) {
    if (node == NULL)
        return newNode(key, offset, record);

    if (key < node->key)
        node->left = insert(node->left, key, offset, record);
    else if (key > node->key)
        node->right = insert(node->right, key, offset, record);

    return node;
}

Node* search(Node* root, int key) {
    if (root == NULL || root->key == key)
        return root;

    if (root->key < key)
        return search(root->right, key);

    return search(root->left, key);
}

void freeRecord(Record *record) {
    free(record);
}

void freeNode(Node* node) {
    if (node != NULL) {
        freeRecord(node->record);
        freeNode(node->left);
        freeNode(node->right);
        free(node);
    }
}

int main() {
    Node* root = NULL;
    Record *record1 = (Record*)malloc(sizeof(Record));
    record1->value = 10;
    root = insert(root, 50, 12345, record1);

    Record *record2 = (Record*)malloc(sizeof(Record));
    record2->value = 20;
    root = insert(root, 30, 67890, record2);

    Node* result = search(root, 30);
    if (result != NULL)
        printf("Found key: %d\n", result->key);

    freeNode(root);
    return 0;
}
