import java.util.Random;

public class MemoryManagementService {

    private long[] offsetArray;
    private int[] keyArray;
    private Record[] recordArray;
    private Random random;

    public MemoryManagementService(int offsetSize, int keySize, double minTimestamp, double maxTimestamp) {
        if (offsetSize < 0 || keySize < 0) {
            throw new IllegalArgumentException("Size inputs must be non-negative integers.");
        }

        this.offsetArray = new long[offsetSize];
        this.keyArray = new int[keySize];
        this.recordArray = new Record[offsetSize];

        initializeArrays(offsetSize, keySize);
        initializeRecords(minTimestamp, maxTimestamp);
    }

    private void initializeArrays(int offsetSize, int keySize) {
        for (int i = 0; i < offsetSize; i++) {
            offsetArray[i] = i;
        }
        for (int i = 0; i < keySize; i++) {
            keyArray[i] = i;
        }
    }

    private void initializeRecords(double minTimestamp, double maxTimestamp) {
        random = new Random(System.currentTimeMillis());
        for (int i = 0; i < recordArray.length; i++) {
            recordArray[i] = new Record(offsetArray[i], keyArray[i], generateRandomTimestamp(minTimestamp, maxTimestamp), "Record" + i + "_" + keyArray[i]);
        }
    }

    private double generateRandomTimestamp(double minTimestamp, double maxTimestamp) {
        return minTimestamp + (maxTimestamp - minTimestamp) * random.nextDouble();
    }

    public void freeMemory() {
        for (int i = recordArray.length - 1; i >= 0; i--) {
            recordArray[i] = null;
        }
        recordArray = null;
        keyArray = null;
        offsetArray = null;
    }

    private static class Record {
        long offset;
        int key;
        double timestamp;
        String content;

        public Record(long offset, int key, double timestamp, String content) {
            this.offset = offset;
            this.key = key;
            this.timestamp = timestamp;
            this.content = content;
        }
    }

    // Additional methods for processing, encryption, and storage can be added here
}
