#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_RECORDS 1000
#define CONFIG_FILE "config.txt"

typedef struct {
    int value;
    int *key;
} record;

record **records = NULL;
int record_count = 0;
int max_records = MAX_RECORDS;

void parse_config_file() {
    FILE *file = fopen(CONFIG_FILE, "r");
    if (file == NULL) {
        fprintf(stderr, "Error opening config file\n");
        exit(EXIT_FAILURE);
    }
    fscanf(file, "%d %d", &max_records, &record_count);
    fclose(file);
}

void allocate_memory() {
    records = (record **)malloc(max_records * sizeof(record *));
    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < max_records; i++) {
        records[i] = (record *)aligned_alloc(64, sizeof(record));
        if (records[i] == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        records[i]->key = (int *)malloc(sizeof(int));
        if (records[i]->key == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
    }
}

void cleanup() {
    for (int i = 0; i < record_count; i++) {
        free(records[i]->key);
        free(records[i]);
    }
    free(records);
    records = NULL;
}

void resize_records() {
    int new_capacity = max_records + (max_records / 10);
    record **new_records = (record **)realloc(records, new_capacity * sizeof(record *));
    if (new_records == NULL) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    for (int i = max_records; i < new_capacity; i++) {
        new_records[i] = (record *)aligned_alloc(64, sizeof(record));
        if (new_records[i] == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        new_records[i]->key = (int *)malloc(sizeof(int));
        if (new_records[i]->key == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
    }
    records = new_records;
    max_records = new_capacity;
}

void read_from_file(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        fprintf(stderr, "Error opening file %s\n", filename);
        return;
    }
    int value, key;
    while (fscanf(file, "%d %d", &value, &key) != EOF) {
        if (record_count >= max_records) {
            resize_records();
        }
        records[record_count]->value = value;
        *records[record_count]->key = key;
        record_count++;
    }
    fclose(file);
}

int main(int argc, char *argv[]) {
    parse_config_file();
    allocate_memory();

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--help") == 0) {
            printf("Usage: %s [--help] [-cs] [-o output_file]\n", argv[0]);
            return 0;
        } else if (strcmp(argv[i], "-cs") == 0) {
            // Handle -cs option
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            // Handle -o output_file option
        } else if (argv[i][0] != '-') {
            read_from_file(argv[i]);
        }
    }

    cleanup();
    return 0;
}
