#include <stdlib.h>
#include <pthread.h>

#define MAX_ENTRIES 100000

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T entries[MAX_ENTRIES];
    int count;
    pthread_mutex_t lock;
} NFAPI_CRC_POOL_T;

NFAPI_CRC_POOL_T* create_crc_pool() {
    NFAPI_CRC_POOL_T* pool = (NFAPI_CRC_POOL_T*)malloc(sizeof(NFAPI_CRC_POOL_T));
    if (!pool) return NULL;
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_crc_pool(NFAPI_CRC_POOL_T* pool) {
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

int add_entry_to_pool(NFAPI_CRC_POOL_T* pool, RX_UE_INFORMATION_TAG ue_info, uint16_t rnti) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count >= MAX_ENTRIES) {
        pthread_mutex_unlock(&pool->lock);
        return -1; // Pool is full
    }
    for (int i = 0; i < pool->count; i++) {
        if (pool->entries[i].rnti == rnti) {
            pthread_mutex_unlock(&pool->lock);
            return -2; // Duplicate RNTI
        }
    }
    NFAPI_CRC_INDICATION_PDU_T new_entry = {ue_info, rnti};
    new_entry.crc_indication.CRCFLAG = simulate_crc_check(ue_info); // Simulate CRC check
    pool->entries[pool->count++] = new_entry;
    pthread_mutex_unlock(&pool->lock);
    return 0; // Success
}

int remove_entry_from_pool(NFAPI_CRC_POOL_T* pool, uint16_t rnti) {
    pthread_mutex_lock(&pool->lock);
    for (int i = 0; i < pool->count; i++) {
        if (pool->entries[i].rnti == rnti) {
            for (int j = i; j < pool->count - 1; j++) {
                pool->entries[j] = pool->entries[j + 1];
            }
            pool->count--;
            pthread_mutex_unlock(&pool->lock);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&pool->lock);
    return -1; // Entry not found
}

NFAPI_CRC_INDICATION_PDU_T* query_entry_by_rnti(NFAPI_CRC_POOL_T* pool, uint16_t rnti) {
    pthread_mutex_lock(&pool->lock);
    for (int i = 0; i < pool->count; i++) {
        if (pool->entries[i].rnti == rnti) {
            NFAPI_CRC_INDICATION_PDU_T* entry = &pool->entries[i];
            pthread_mutex_unlock(&pool->lock);
            return entry;
        }
    }
    pthread_mutex_unlock(&pool->lock);
    return NULL; // Entry not found
}

int simulate_crc_check(RX_UE_INFORMATION_TAG ue_info) {
    // Simulate CRC check based on ue_info
    return rand() % 2; // Randomly set CRCFLAG for demonstration
}
