import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class StringHashService {

    private final ExecutorService executorService = Executors.newFixedThreadPool(10);
    private final Map<String, String> cache = new HashMap<>();
    private final CircuitBreaker circuitBreaker = new CircuitBreaker();

    public CompletableFuture<Map<String, String>> processBatch(String[] batch) {
        return CompletableFuture.supplyAsync(() -> {
            if (circuitBreaker.isOpen()) {
                throw new RuntimeException("Circuit breaker is open");
            }
            Map<String, String> result = new HashMap<>();
            for (String str : batch) {
                try {
                    String md5Hash = getMd5Hash(str);
                    cache.putIfAbsent(str, md5Hash);
                    result.put(str, md5Hash);
                } catch (Exception e) {
                    circuitBreaker.open();
                    throw new RuntimeException("Failed to process string", e);
                }
            }
            return result;
        }, executorService);
    }

    private String getMd5Hash(String str) throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("MD5");
        byte[] hashBytes = digest.digest(str.getBytes());
        StringBuilder sb = new StringBuilder();
        for (byte b : hashBytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }

    private static class CircuitBreaker {
        private boolean open = false;

        public void open() {
            this.open = true;
        }

        public boolean isOpen() {
            return open;
        }
    }
}
