import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;

public class CryptographicLibrary {

    private BlockingQueue<String> queue = new LinkedBlockingQueue<>(1000);

    public void addNID(String nid) {
        try {
            if (nid != null) {
                queue.put(nid);
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public List<CryptographicResult> processBatch() throws InterruptedException, NoSuchAlgorithmException {
        List<String> nids = new ArrayList<>();
        while (!queue.isEmpty()) {
            nids.add(queue.take());
        }

        List<CryptographicResult> results = new ArrayList<>();
        for (String nid : nids) {
            String md5Hash = calculateMD5(nid);
            String sha256Hash = calculateSHA256(nid);
            results.add(new CryptographicResult(nid, md5Hash, sha256Hash));
        }

        return results;
    }

    private String calculateMD5(String input) throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("MD5");
        byte[] hashBytes = digest.digest(input.getBytes());
        StringBuilder sb = new StringBuilder();
        for (byte b : hashBytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    private String calculateSHA256(String input) throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        byte[] hashBytes = digest.digest(input.getBytes());
        StringBuilder sb = new StringBuilder();
        for (byte b : hashBytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public static class CryptographicResult {
        private String nid;
        private String md5Hash;
        private String sha256Hash;

        public CryptographicResult(String nid, String md5Hash, String sha256Hash) {
            this.nid = nid;
            this.md5Hash = md5Hash;
            this.sha256Hash = sha256Hash;
        }

        // Getters and setters
    }
}
