#define MAX_PROJECTS 1000

typedef struct {
    int priority;
    char *status;
    time_t deadline;
    time_t start_date;
} Project;

Project* init_project_list(int num_projects) {
    if (num_projects > MAX_PROJECTS) {
        fprintf(stderr, "Error: Number of projects exceeds maximum limit.\n");
        return NULL;
    }

    Project *project_list = malloc(num_projects * sizeof(Project));
    if (!project_list) {
        perror("Failed to allocate memory for project list.");
        return NULL;
    }

    time_t current_time = time(NULL);
    srand(time(NULL));

    for (int i = 0; i < num_projects; i++) {
        project_list[i].priority = i + 1;
        project_list[i].status = malloc(10 * sizeof(char));
        if (!project_list[i].status) {
            perror("Failed to allocate memory for status.");
            free_project_list(project_list, i);
            return NULL;
        }
        strcpy(project_list[i].status, "Pending");
        project_list[i].start_date = current_time;

        // Set deadline after start date
        project_list[i].deadline = current_time + (rand() % 365 * 24 * 60 * 60);

        // Random value for demonstration purposes
        project_list[i].priority = rand() % 100;
    }

    return project_list;
}

void free_project_list(Project *project_list, int num_projects) {
    for (int i = 0; i < num_projects; i++) {
        free(project_list[i].status);
    }
    free(project_list);
}

int main() {
    int num_projects = 5;
    Project *projects = init_project_list(num_projects);

    if (projects) {
        // Use the project list
        free_project_list(projects, num_projects);
    }

    return 0;
}
