#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int CONNECTION_ID;
    unsigned long BYTES_SENT;
    unsigned long BYTES_RECEIVED;
    double PACKET_LOSS_RATE;
    unsigned long CONNECTION_DURATION;
} NETWORK_CONNECTION_STATS_T;

typedef struct {
    NETWORK_CONNECTION_STATS_T *connections;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} CONNECTION_COLLECTION_T;

void init_connection_collection(CONNECTION_COLLECTION_T *collection, size_t initial_capacity) {
    collection->connections = malloc(initial_capacity * sizeof(NETWORK_CONNECTION_STATS_T));
    if (collection->connections == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    collection->count = 0;
    collection->capacity = initial_capacity;
    pthread_mutex_init(&collection->lock, NULL);
}

void add_connection(CONNECTION_COLLECTION_T *collection, NETWORK_CONNECTION_STATS_T *stats) {
    pthread_mutex_lock(&collection->lock);
    if (collection->count == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        NETWORK_CONNECTION_STATS_T *new_connections = realloc(collection->connections, new_capacity * sizeof(NETWORK_CONNECTION_STATS_T));
        if (new_connections == NULL) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        collection->connections = new_connections;
        collection->capacity = new_capacity;
    }
    memcpy(&collection->connections[collection->count], stats, sizeof(NETWORK_CONNECTION_STATS_T));
    collection->count++;
    pthread_mutex_unlock(&collection->lock);
}

void filter_connections(CONNECTION_COLLECTION_T *collection, unsigned long duration_threshold) {
    pthread_mutex_lock(&collection->lock);
    size_t i = 0;
    while (i < collection->count) {
        if (collection->connections[i].CONNECTION_DURATION < duration_threshold) {
            memmove(&collection->connections[i], &collection->connections[i + 1], (collection->count - i - 1) * sizeof(NETWORK_CONNECTION_STATS_T));
            collection->count--;
        } else {
            i++;
        }
    }
    pthread_mutex_unlock(&collection->lock);
}

void serialize_connections(CONNECTION_COLLECTION_T *collection, FILE *file) {
    pthread_mutex_lock(&collection->lock);
    fwrite(collection->connections, sizeof(NETWORK_CONNECTION_STATS_T), collection->count, file);
    pthread_mutex_unlock(&collection->lock);
}

int deserialize_connections(CONNECTION_COLLECTION_T *collection, FILE *file) {
    pthread_mutex_lock(&collection->lock);
    size_t count = fread(collection->connections, sizeof(NETWORK_CONNECTION_STATS_T), collection->capacity, file);
    if (count < collection->capacity) {
        collection->count = count;
    }
    pthread_mutex_unlock(&collection->lock);
    return count;
}

void destroy_connection_collection(CONNECTION_COLLECTION_T *collection) {
    free(collection->connections);
    pthread_mutex_destroy(&collection->lock);
}
