    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int add_measurement(MeasurementCollection *collection, LTE_PHY_MEASUREMENT_PDU_T measurement) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity ? collection->capacity * 2 : 1;
        LTE_PHY_MEASUREMENT_PDU_T *new_measurements = realloc(collection->measurements, new_capacity * sizeof(LTE_PHY_MEASUREMENT_PDU_T));
        if (!new_measurements) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Memory allocation failed
        }
        collection->measurements = new_measurements;
        collection->capacity = new_capacity;
    }

    collection->measurements[collection->count++] = measurement;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

int filter_measurements(MeasurementCollection *collection, int signal_quality_threshold) {
