struct Service {
    mcus: RwLock<HashMap<String, MCU>>,
    log_channel: mpsc::Sender<LogEntry>,
}

impl Service {
    async fn new(log_channel: mpsc::Sender<LogEntry>) -> Self {
        Service {
            mcus: RwLock::new(HashMap::new()),
            log_channel,
        }
    }

    async fn process_batch(&self, batch: Vec<String>) {
        for string in batch {
            let header = L2Header { /* Initialize fields */ };
            let payload = Payload { data: string.into_bytes() };
            let mcu = MCU::new(header, payload);

            if mcu.validate() {
                self.add_mcu(mcu).await;
            } else {
                error!("Invalid MCU");
            }
        }
    }

    async fn add_mcu(&self, mcu: MCU) {
        let mut mcus = self.mcus.write().await;
        mcus.insert(format!("{:?}", mcu), mcu);
    }
}

#[derive(Debug)]
struct LogEntry {
    level: log::Level,
    message: String,
}

impl LogEntry {
    fn new(level: log::Level, message: String) -> Self {
        LogEntry { level, message }
    }

    async fn send(&self, channel: mpsc::Sender<LogEntry>) {
