    for (int i = 0; i < session_manager.count; i++) {
        if (session_manager.sessions[i].session_id == session_id) {
            session_manager.sessions[i].timestamp = time(NULL);
            break;
        }
    }
    pthread_mutex_unlock(&session_manager.lock);
}

void add_session(int session_id, Device *devices, int device_count) {
    pthread_mutex_lock(&session_manager.lock);
    if (session_manager.count >= session_manager.capacity) {
