        session_manager.capacity += session_manager.capacity / 10;
        session_manager.sessions = realloc(session_manager.sessions, session_manager.capacity * sizeof(Session));
    }
    session_manager.sessions[session_manager.count].session_id = session_id;
    session_manager.sessions[session_manager.count].timestamp = time(NULL);
    // Add more fields as needed
    pthread_mutex_unlock(&session_manager.lock);
}

void cleanup_session_manager() {
