#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int value;
    long offset;
} record;

int allocate_arrays(long *offsets, int *keys, record **records, size_t length) {
    if (length == 0) return -1; // Error: Length cannot be zero

    offsets = malloc(length * sizeof(*offsets));
    keys = malloc(length * sizeof(*keys));
    *records = malloc(length * sizeof(**records));

    if (!offsets || !keys || !*records) {
        free(offsets);
        free(keys);
        free(*records);
        return -2; // Error: Memory allocation failed
    }

    srand(time(NULL)); // Seed for random number generation

    for (size_t i = 0; i < length; ++i) {
        offsets[i] = rand() % length; // Initialize offset
        keys[i] = rand() % length; // Initialize key
        (*records)[i].value = rand() % length; // Initialize record value
        (*records)[i].offset = offsets[i]; // Set record offset

        // Check for duplicate keys and resolve conflicts
        for (size_t j = 0; j < i; ++j) {
            if (keys[i] == keys[j]) {
                keys[i] = rand() % length; // Retry with a new key
                --i; // Decrement to retry current index
                break;
            }
        }
    }

    return 0; // Success
}

void free_arrays(long *offsets, int *keys, record *records) {
    free(offsets);
    free(keys);
    free(records);
}
