#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 10000
#define INITIAL_CAPACITY 100

typedef struct {
    int value;
    long *key;
} record;

record *records = NULL;
int record_count = 0;
int capacity = 0;

void init_records() {
    capacity = INITIAL_CAPACITY;
    records = (record *)aligned_alloc(64, capacity * sizeof(record));
}

void resize_records() {
    int new_capacity = capacity + capacity / 10;
    records = (record *)realloc(records, new_capacity * sizeof(record));
    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    capacity = new_capacity;
}

void add_record(long key) {
    if (record_count >= capacity) {
        resize_records();
    }
    records[record_count].key = &key;
    records[record_count].value = rand() % 100; // Random value between 0 and 99
    record_count++;
}

void process_file(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file: %s\n", filename);
        return;
    }

    long key;
    while (fscanf(file, "%ld", &key) != EOF) {
        add_record(key);
    }

    fclose(file);
}

void print_usage() {
    printf("Usage: program_name [options] <input_file>\n");
    printf("Options:\n");
    printf("  --help\t\tShow this help message\n");
    printf("  -c <config_file>\tSpecify a configuration file\n");
    printf("  -o <output_file>\tSpecify an output file\n");
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        print_usage();
        return EXIT_FAILURE;
    }

    const char *input_file = NULL;
    const char *config_file = NULL;
    const char *output_file = NULL;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--help") == 0) {
            print_usage();
            return EXIT_SUCCESS;
        } else if (strcmp(argv[i], "-c") == 0 && i + 1 < argc) {
            config_file = argv[++i];
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            output_file = argv[++i];
        } else if (input_file == NULL) {
            input_file = argv[i];
        }
    }

    if (input_file == NULL) {
        fprintf(stderr, "Input file not specified\n");
        print_usage();
        return EXIT_FAILURE;
    }

    srand(time(NULL));
    init_records();

    process_file(input_file);

    printf("Number of lines processed: %d\n", record_count);

    // Free allocated memory
    free(records);

    return EXIT_SUCCESS;
}
