    long *offsets;
    int *keys;
    Record *records;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_pdu(int n, int m, int max_offset, int max_key, int min_value, int max_value) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        perror("Failed to allocate memory for pdu");
        return NULL;
    }

    pdu->offsets = (long *)malloc(n * sizeof(long));
    if (!pdu->offsets) {
        perror("Failed to allocate memory for offsets");
        free(pdu);
        return NULL;
    }

    pdu->keys = (int *)malloc(n * sizeof(int));
    if (!pdu->keys) {
        perror("Failed to allocate memory for keys");
        free(pdu->offsets);
        free(pdu);
        return NULL;
    }

    pdu->records = (Record *)malloc(m * sizeof(Record));
    if (!pdu->records) {
        perror("Failed to allocate memory for records");
        free(pdu->keys);
        free(pdu->offsets);
        free(pdu);
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < n; i++) {
        pdu->offsets[i] = rand() % max_offset;
        while (i > 0 && pdu->offsets[i] <= pdu->offsets[i - 1]) {
            pdu->offsets[i] = rand() % max_offset;
        }
    }

    for (int i = 0; i < n; i++) {
        pdu->keys[i] = rand() % max_key;
        while (i > 0 && (pdu->keys[i] >= pdu->offsets[i] || pdu->keys[i] == pdu->keys[i - 1])) {
            pdu->keys[i] = rand() % max_key;
        }
    }

    for (int i = 0; i < m; i++) {
        pdu->records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    return pdu;
}

void free_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (pdu) {
        free(pdu->offsets);
        free(pdu->keys);
        free(pdu->records);
        free(pdu);
    }
}
