#define MAX_N 1000000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* create_list() {
    DynamicList *list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;
    list->data = NULL;
    list->size = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(DynamicList *list) {
    if (list->data) free(list->data);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_to_list(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }
    list->data[list->size++] = item;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void filter_list(DynamicList *list, int threshold) {
    pthread_mutex_lock(&list->lock);
    size_t i = 0, j = 0;
    while (i < list->size) {
        if (list->data[i].CRC_INDICATION_REL8_TAG >= threshold) {
            list->data[j++] = list->data[i];
        }
        i++;
    }
    list->size = j;
    pthread_mutex_unlock(&list->lock);
}

void serialize_list(DynamicList *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    pthread_mutex_lock(&list->lock);
    fwrite(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->size, file);
    pthread_mutex_unlock(&list->lock);

    fclose(file);
}

void deserialize_list(DynamicList *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    fseek(file, 0, SEEK_END);
    size_t size = ftell(file) / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    fseek(file, 0, SEEK_SET);

    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_data) {
        list->data = new_data;
        list->size = size;
        fread(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), size, file);
    }
    pthread_mutex_unlock(&list->lock);

    fclose(file);
}

