#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_URI_LENGTH 2048
#define MAX_BODY_SIZE 1024 * 1024 // 1MB

typedef struct {
    char uri[MAX_URI_LENGTH];
    void* body;
    size_t body_size;
} HttpRequest;

typedef struct {
    HttpRequest* requests;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} RequestQueue;

void init_request_queue(RequestQueue* queue, size_t initial_capacity) {
    queue->requests = (HttpRequest*)malloc(initial_capacity * sizeof(HttpRequest));
    if (!queue->requests) {
        fprintf(stderr, "Failed to allocate memory for request queue\n");
        exit(EXIT_FAILURE);
    }
    queue->count = 0;
    queue->capacity = initial_capacity;
    pthread_mutex_init(&queue->lock, NULL);
}

void enqueue_request(RequestQueue* queue, const char* uri, void* body, size_t body_size) {
    pthread_mutex_lock(&queue->lock);

    if (queue->count >= queue->capacity) {
        // Double the capacity
        HttpRequest* new_requests = (HttpRequest*)realloc(queue->requests, queue->capacity * 2 * sizeof(HttpRequest));
        if (!new_requests) {
            fprintf(stderr, "Failed to reallocate memory for request queue\n");
            exit(EXIT_FAILURE);
        }
        queue->requests = new_requests;
        queue->capacity *= 2;
    }

    HttpRequest* request = &queue->requests[queue->count++];
    strncpy(request->uri, uri, MAX_URI_LENGTH - 1);
    request->body = malloc(body_size);
    if (!request->body) {
        fprintf(stderr, "Failed to allocate memory for request body\n");
        exit(EXIT_FAILURE);
    }
    memcpy(request->body, body, body_size);
    request->body_size = body_size;

    pthread_mutex_unlock(&queue->lock);
}

void free_request_queue(RequestQueue* queue) {
    pthread_mutex_lock(&queue->lock);

    for (size_t i = 0; i < queue->count; ++i) {
        free(queue->requests[i].body);
    }
    free(queue->requests);

    pthread_mutex_unlock(&queue->lock);
    pthread_mutex_destroy(&queue->lock);
}

int main() {
    RequestQueue queue;
    init_request_queue(&queue, 10);

    // Example usage
    const char* uri = "http://example.com/api";
    void* body = malloc(1024); // Simulated body data
    enqueue_request(&queue, uri, body, 1024);

    free_request_queue(&queue);
    return 0;
}
