#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Item {
    char* name;
    int priority;
    struct Item* next;
} Item;

typedef struct Container {
    Item* head;
    size_t memoryUsage;
    size_t maxMemory;
} Container;

Container* createContainer(size_t maxMemory) {
    Container* container = (Container*)malloc(sizeof(Container));
    if (!container) return NULL;
    container->head = NULL;
    container->memoryUsage = 0;
    container->maxMemory = maxMemory;
    return container;
}

void insertItem(Container* container, const char* name, int priority) {
    Item* newItem = (Item*)malloc(sizeof(Item));
    if (!newItem) return;

    newItem->name = strdup(name);
    newItem->priority = priority;
    newItem->next = NULL;

    if (!container->head || container->head->priority < priority) {
        newItem->next = container->head;
        container->head = newItem;
    } else {
        Item* current = container->head;
        while (current->next && current->next->priority >= priority) {
            current = current->next;
        }
        newItem->next = current->next;
        current->next = newItem;
    }

    container->memoryUsage += sizeof(Item) + strlen(name);
}

void traverseContainers(Container** containers, int numContainers) {
    for (int i = 0; i < numContainers; i++) {
        Container* container = containers[i];
        Item* current = container->head;
        while (current) {
            printf("Container %d: %s - Priority %d\n", i, current->name, current->priority);
            current = current->next;
        }
    }
}

void freeContainers(Container** containers, int numContainers) {
    for (int i = 0; i < numContainers; i++) {
        Container* container = containers[i];
        Item* current = container->head;
        while (current) {
            Item* next = current->next;
            free(current->name);
            free(current);
            current = next;
        }
        free(container);
    }
}

int main() {
    const int numContainers = 3;
    Container** containers = (Container**)malloc(numContainers * sizeof(Container*));
    for (int i = 0; i < numContainers; i++) {
        containers[i] = createContainer(1024); // Example max memory of 1KB per container
    }

    insertItem(containers[0], "Task1", 3);
    insertItem(containers[0], "Task2", 1);
    insertItem(containers[1], "Task3", 2);

    traverseContainers(containers, numContainers);

    freeContainers(containers, numContainers);
    free(containers);

    return 0;
}
```

This code provides a basic implementation of the described functionality. It includes functions to create containers, insert items based on priority, traverse all containers, and free allocated memory. The `main` function demonstrates how to use these functions with a simple example.']

