#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Item {
    char* name;
    int priority;
    size_t timestamp;
    size_t ref_count;
    struct Item* next;
} Item;

typedef struct Container {
    Item* head;
    size_t size;
} Container;

Item* create_item(const char* name, int priority) {
    Item* item = (Item*)malloc(sizeof(Item));
    if (item == NULL) return NULL;
    item->name = strdup(name);
    item->priority = priority;
    item->timestamp = time(NULL);
    item->ref_count = 1;
    item->next = NULL;
    return item;
}

void free_item(Item* item) {
    free(item->name);
    free(item);
}

Container* create_container() {
    Container* container = (Container*)malloc(sizeof(Container));
    if (container == NULL) return NULL;
    container->head = NULL;
    container->size = 0;
    return container;
}

void free_container(Container* container) {
    Item* current = container->head;
    while (current != NULL) {
        Item* next = current->next;
        free_item(current);
        current = next;
    }
    free(container);
}

void insert_item(Container* container, Item* item) {
    if (container == NULL || item == NULL) return;

    if (container->head == NULL || 
        item->priority > container->head->priority ||
        (item->priority == container->head->priority && item->timestamp < container->head->timestamp)) {
        item->next = container->head;
        container->head = item;
    } else {
        Item* current = container->head;
        while (current->next != NULL &&
               (current->next->priority >= item->priority ||
                (current->next->priority == item->priority && current->next->timestamp <= item->timestamp))) {
            current = current->next;
        }
        item->next = current->next;
        current->next = item;
    }
    container->size++;
}

Item* find_item(Container* container, const char* name) {
    if (container == NULL || name == NULL) return NULL;

    Item* current = container->head;
    while (current != NULL) {
        if (strcmp(current->name, name) == 0) {
            current->ref_count++;
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void remove_item(Container* container, const char* name) {
    if (container == NULL || name == NULL) return;

    Item** prev = &container->head;
    while (*prev != NULL) {
        if (strcmp((*prev)->name, name) == 0) {
            Item* item = *prev;
            *prev = item->next;
            free_item(item);
            container->size--;
            break;
        }
        prev = &(*prev)->next;
    }
}

void update_item_priority(Container* container, const char* name, int new_priority) {
    if (container == NULL || name == NULL) return;

    Item* item = find_item(container, name);
    if (item != NULL) {
        item->priority = new_priority;
        remove_item(container, name);
        insert_item(container, item);
    }
}

void update_item_timestamp(Container* container, const char* name) {
    if (container == NULL || name == NULL) return;

    Item* item = find_item(container, name);
    if (item != NULL) {
        item->timestamp = time(NULL);
    }
}
