#include <iostream>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>

class Task {
public:
    std::string name;
    unsigned int priority;

    Task(std::string n, unsigned int p) : name(n), priority(p) {}
};

class TaskGroup {
private:
    std::priority_queue<Task> tasks;
    std::mutex mtx;
    std::condition_variable cv;
    size_t memoryUsage;
    static const size_t MAX_MEMORY_USAGE = 1024; // Example threshold

public:
    void addTask(const Task& task) {
        std::unique_lock<std::mutex> lock(mtx);
        tasks.push(task);
        memoryUsage += task.name.size() + sizeof(unsigned int); // Simplified memory estimation
        if (memoryUsage > MAX_MEMORY_USAGE) {
            cv.notify_all();
        }
    }

    void processTasks() {
        while (!tasks.empty()) {
            std::unique_lock<std::mutex> lock(mtx);
            tasks.pop();
            memoryUsage -= tasks.top().name.size() + sizeof(unsigned int); // Simplified memory estimation
            lock.unlock();
            // Process task here
        }
    }

    void waitForMemory() {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this] { return memoryUsage <= MAX_MEMORY_USAGE; });
    }
};

class TaskManager {
private:
    std::vector<TaskGroup*> groups;
    std::mutex mtx;

public:
    ~TaskManager() {
        for (auto group : groups) {
            delete group;
        }
    }

    void addGroup(TaskGroup* group) {
        std::lock_guard<std::mutex> lock(mtx);
        groups.push_back(group);
    }

    void addTask(const Task& task, int groupId) {
        if (groupId >= 0 && groupId < groups.size()) {
            groups[groupId]->addTask(task);
        }
    }

    void processAllTasks() {
        for (auto group : groups) {
            group->processTasks();
        }
    }

    void waitForMemory(int groupId) {
        if (groupId >= 0 && groupId < groups.size()) {
            groups[groupId]->waitForMemory();
        }
    }
};
