    private ILoggerService loggerService;
    private INotificationService notificationService;

    public HtmlContentManager(long[] offsetValues, int[] keys, IExternalAuthService authService, ILoggerService loggerService, INotificationService notificationService)
    {
        this.offsetValues = offsetValues;
        this.keys = keys;
        this.authService = authService;
        this.loggerService = loggerService;
        this.notificationService = notificationService;

        InitializeRecords();
    }

    private void InitializeRecords()
    {
        Random random = new Random();
        var records = new List<RandomRecord>();

        foreach (var key in keys)
        {
            int value = GenerateRandomValue(key, 100, 200); // Example range
            records.Add(new RandomRecord(value));
        }

        // Use the records as needed
    }

    private int GenerateRandomValue(int seed, int min, int max)
    {
        Random random = new Random(seed);
        return random.Next(min, max + 1); // Inclusive upper bound
    }

    public async Task<HttpResponseMessage> HandlePostRequestAsync(HttpContent content)
    {
        try
        {
            var request = await content.ReadAsAsync<HttpRequestDto>();
            if (!await authService.ValidateToken(request.Token))
            {
                loggerService.LogError("Authentication failed");
                return new HttpResponseMessage(HttpStatusCode.Unauthorized);
            }

            // Update HTML content using a service class
            var updateResult = await HtmlContentService.UpdateElementHtml(request.SectionId, request.ElementId, request.NewHtml);

            if (updateResult)
            {
                loggerService.LogInformation("HTML content updated successfully");
                return new HttpResponseMessage(HttpStatusCode.OK) { Content = new StringContent("Success") };
            }
            else
            {
                loggerService.LogError("Failed to update HTML content");
                return new HttpResponseMessage(HttpStatusCode.InternalServerError);
            }
        }
        catch (Exception ex)
        {
            loggerService.LogError(ex, "An error occurred while handling the request");
            await notificationService.SendAlertAsync("Critical failure in HtmlContentManager", ex.Message);
            return new HttpResponseMessage(HttpStatusCode.ServiceUnavailable);
        }
    }

    public class HttpRequestDto
    {
        public string Token { get; set; }
        public int SectionId { get; set; }
        public int ElementId { get; set; }
        public string NewHtml { get; set; }
    }
}

