#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 10000
#define LOG_FILE "crc_log.txt"
#define LOG_SIZE_LIMIT 1024 * 1024

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    time_t timestamp;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *crc_list[MAX_ELEMENTS];
int list_size = 0;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file = NULL;

void log_message(const char *message) {
    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Failed to open log file");
            return;
        }
    }

    fprintf(log_file, "%s\n", message);
    fflush(log_file);

    // Check and rotate log file
    fseek(log_file, 0, SEEK_END);
    long size = ftell(log_file);
    if (size > LOG_SIZE_LIMIT) {
        fclose(log_file);
        rename(LOG_FILE, "crc_log_old.txt");
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Failed to open log file after rotation");
        }
    }
}

void *initialize_and_maintain_list(void *arg) {
    while (1) {
        pthread_mutex_lock(&list_mutex);
        // Initialize and maintain list logic here
        pthread_mutex_unlock(&list_mutex);

        // Prune list logic here

        sleep(60); // Periodically check every minute
    }

    return NULL;
}

void prune_list() {
    time_t current_time = time(NULL);
    int i;

    for (i = 0; i < list_size; i++) {
        if (difftime(current_time, crc_list[i]->timestamp) > 300) { // 5 minutes
            pthread_mutex_lock(&list_mutex);
            free(crc_list[i]);
            memmove(&crc_list[i], &crc_list[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T *) * (list_size - i - 1));
            list_size--;
            pthread_mutex_unlock(&list_mutex);
        }
    }
}

int main() {
    // Initialize log file
    log_message("Starting CRC indication PDU list management");

    // Create and start thread for initializing and maintaining the list
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, initialize_and_maintain_list, NULL) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    // Main program logic here

    // Wait for thread to finish (should never reach this point)
    pthread_join(thread_id, NULL);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    return EXIT_SUCCESS;
}
