#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <atomic>
#include <random>
#include <unordered_map>

// Define structures
struct Metadata {
    char** metadata;
};

struct DataChunk {
    unsigned char* data;
    size_t size;
};

struct Index {
    int* index;
    size_t size;
};

struct Entry {
    DataChunk* chunk;
    Index* idx;
};

// Function to initialize Metadata
Metadata* initMetadata(size_t numFiles) {
    Metadata* meta = (Metadata*)malloc(sizeof(Metadata));
    if (!meta) return NULL;

    meta->metadata = (char**)calloc(numFiles, sizeof(char*));
    for (size_t i = 0; i < numFiles; ++i) {
        meta->metadata[i] = strdup("default");
        if (!meta->metadata[i]) {
            freeMetadata(meta);
            return NULL;
        }
    }

    return meta;
}

// Function to initialize DataChunk
DataChunk* initDataChunk(size_t size) {
    DataChunk* chunk = (DataChunk*)malloc(sizeof(DataChunk));
    if (!chunk) return NULL;

    chunk->data = (unsigned char*)calloc(size, sizeof(unsigned char));
    if (!chunk->data) {
        free(chunk);
        return NULL;
    }

    chunk->size = size;
    return chunk;
}

// Function to initialize Index
Index* initIndex(size_t size) {
    Index* idx = (Index*)malloc(sizeof(Index));
    if (!idx) return NULL;

    idx->index = (int*)calloc(size, sizeof(int));
    if (!idx->index) {
        free(idx);
        return NULL;
    }

    idx->size = size;
    return idx;
}

// Function to initialize Entry
Entry* initEntry(DataChunk* chunk, Index* idx) {
    Entry* entry = (Entry*)malloc(sizeof(Entry));
    if (!entry) return NULL;

    entry->chunk = chunk;
    entry->idx = idx;
    return entry;
}

// Function to free Metadata
void freeMetadata(Metadata* meta) {
    for (size_t i = 0; i < meta->metadata; ++i) {
        free(meta->metadata[i]);
    }
    free(meta->metadata);
    free(meta);
}

// Function to free DataChunk
void freeDataChunk(DataChunk* chunk) {
    free(chunk->data);
    free(chunk);
}

// Function to free Index
void freeIndex(Index* idx) {
    free(idx->index);
    free(idx);
}

// Function to free Entry
void freeEntry(Entry* entry) {
    freeDataChunk(entry->chunk);
    freeIndex(entry->idx);
    free(entry);
}
