#define MAX_RECORDS 1000000
#define RESIZE_FACTOR 0.2

typedef struct {
    float approx;
    double *value;
    int index;
} record;

record* read_dataset(const char *filename, size_t *num_records) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    record *records = (record *)aligned_alloc(64, MAX_RECORDS * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        fclose(file);
        return NULL;
    }

    size_t capacity = MAX_RECORDS;
    size_t count = 0;

    while (count < capacity && fread(&records[count], sizeof(record), 1, file)) {
        records[count].value = aligned_alloc(64, sizeof(double));
        if (!records[count].value) {
            perror("Failed to allocate memory for double value");
            free(records);
            fclose(file);
            return NULL;
        }
        count++;
    }

    *num_records = count;
    fclose(file);
    return records;
}

void process_dataset(record *records, size_t num_records) {
    // Process dataset in chunks
    for (size_t i = 0; i < num_records; i += 1000) {
        size_t chunk_size = (num_records - i > 1000) ? 1000 : num_records - i;
        // Perform processing on records[i:i+chunk_size]
    }
}

void calculate_statistics(record *records, size_t num_records) {
    double sum = 0.0;
    for (size_t i = 0; i < num_records; i++) {
        sum += *(records[i].value);
    }
    double average = sum / num_records;

    printf("Average value: %f\n", average);

    double max_deviation = 0.0;
    for (size_t i = 0; i < num_records; i++) {
        double deviation = fabs(records[i].approx - *(records[i].value));
        if (deviation > max_deviation) {
            max_deviation = deviation;
        }
    }

    printf("Maximum absolute deviation: %f\n", max_deviation);
}

void cleanup(record *records, size_t num_records) {
    for (size_t i = 0; i < num_records; i++) {
        free(records[i].value);
    }
    free(records);
}
