#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_SESSIONS 1000
#define SESSION_EXPIRY_SECONDS 3600
#define MIN_RESIZE_FACTOR 0.2

typedef struct Device {
    char ip[16];
    time_t last_active;
    char hardware_id[32];
} Device;

typedef struct Session {
    int session_id;
    time_t timestamp;
    Device* devices;
    int device_count;
    int max_devices;
} Session;

Session** sessions = NULL;
int session_count = 0;
int max_sessions = MAX_SESSIONS;

void initialize_sessions() {
    sessions = (Session**)malloc(max_sessions * sizeof(Session*));
}

void set_session_timestamps() {
    for (int i = 0; i < session_count; i++) {
        sessions[i]->timestamp = time(NULL);
    }
}

void resize_sessions(int new_capacity) {
    Session** new_sessions = (Session**)realloc(sessions, new_capacity * sizeof(Session*));
    if (new_sessions == NULL) {
        fprintf(stderr, "Failed to resize session list\n");
        return;
    }
    sessions = new_sessions;
    max_sessions = new_capacity;
}

void add_session(int session_id) {
    if (session_count >= max_sessions) {
        int new_capacity = max_sessions + (int)(max_sessions * MIN_RESIZE_FACTOR);
        resize_sessions(new_capacity);
    }
    Session* new_session = (Session*)malloc(sizeof(Session));
    new_session->session_id = session_id;
    new_session->timestamp = time(NULL);
    new_session->devices = NULL;
    new_session->device_count = 0;
    new_session->max_devices = 10; // Initial capacity for devices
    sessions[session_count++] = new_session;
}

void add_device(int session_id, char* ip, char* hardware_id) {
    for (int i = 0; i < session_count; i++) {
        if (sessions[i]->session_id == session_id) {
            if (sessions[i]->device_count >= sessions[i]->max_devices) {
                int new_capacity = sessions[i]->max_devices + (int)(sessions[i]->max_devices * MIN_RESIZE_FACTOR);
                sessions[i]->devices = (Device*)realloc(sessions[i]->devices, new_capacity * sizeof(Device));
                sessions[i]->max_devices = new_capacity;
            }
            Device* new_device = &sessions[i]->devices[sessions[i]->device_count++];
            strcpy(new_device->ip, ip);
            new_device->last_active = time(NULL);
            strcpy(new_device->hardware_id, hardware_id);
            break;
        }
    }
}

void purge_old_sessions(time_t expiry_time) {
    for (int i = 0; i < session_count; i++) {
        if (sessions[i]->timestamp < expiry_time) {
            free(sessions[i]->devices);
            sessions[i]->devices = NULL;
            sessions[i]->device_count = 0;
            sessions[i]->max_devices = 10;
            // Shift remaining sessions
            for (int j = i; j < session_count - 1; j++) {
                sessions[j] = sessions[j + 1];
            }
            session_count--;
            i--; // Adjust index after shift
        }
    }
}

void cleanup_sessions() {
    for (int i = 0; i < session_count; i++) {
        free(sessions[i]->devices);
        sessions[i]->devices = NULL;
        sessions[i]->device_count = 0;
        sessions[i]->max_devices = 10;
        free(sessions[i]);
    }
    free(sessions);
    sessions = NULL;
    session_count = 0;
    max_sessions = MAX_SESSIONS;
}

int main() {
    initialize_sessions();
    set_session_timestamps();

    // Example usage
    add_session(1);
    add_device(1, "192.168.1.1", "device1");
    purge_old_sessions(time(NULL) - SESSION_EXPIRY_SECONDS);

    cleanup_sessions();
    return 0;
}
