#include <string.h>
#include <time.h>

#define CACHE_LINE_SIZE 64

typedef struct {
    int value;
    long *offset;
} record;

void initialize_data_structures(long **offsets, int **keys, record **records, int capacity) {
    // Allocate memory with cache line alignment
    *offsets = (long *)aligned_alloc(CACHE_LINE_SIZE, capacity * sizeof(long));
    *keys = (int *)aligned_alloc(CACHE_LINE_SIZE, capacity * sizeof(int));
    *records = (record *)aligned_alloc(CACHE_LINE_SIZE, capacity * sizeof(record));

    // Initialize with random values
    srand(time(NULL));
    for (int i = 0; i < capacity; i++) {
        (*offsets)[i] = rand() % capacity;
        (*keys)[i] = rand() % 1000;
        (*records)[i].value = rand() % 1000;
        (*records)[i].offset = &(*offsets)[i];
    }
}

void find_and_print_largest(record *records, int count) {
    if (count == 0) {
        fprintf(stderr, "No records to process.\n");
        return;
    }

    int max_value = records[0].value;
    for (int i = 1; i < count; i++) {
        if (records[i].value > max_value) {
            max_value = records[i].value;
        }
    }
    printf("Largest value: %d\n", max_value);
}

void calculate_and_print_average(record *records, int count) {
    if (count == 0) {
        fprintf(stderr, "No records to process.\n");
        return;
    }

    int sum = 0;
    for (int i = 0; i < count; i++) {
        sum += records[i].value;
    }
    double average = (double)sum / count;
    printf("Average value: %.2f\n", average);
}

void update_records(record *records, int count, int new_value_range) {
    for (int i = 0; i < count; i++) {
        records[i].value = rand() % new_value_range + 1;
    }
}

void resize_records(record **records, int *capacity, int new_capacity) {
    if (new_capacity <= *capacity) {
        fprintf(stderr, "New capacity must be greater than current capacity.\n");
        return;
    }

    record *new_records = (record *)aligned_alloc(CACHE_LINE_SIZE, new_capacity * sizeof(record));
    memcpy(new_records, *records, (*capacity) * sizeof(record));

    for (int i = *capacity; i < new_capacity; i++) {
        new_records[i].value = rand() % 1000;
        new_records[i].offset = &new_records[i].value;
    }

    free(*records);
    *records = new_records;
    *capacity = new_capacity;
}

void cleanup(long *offsets, int *keys, record *records) {
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    long *offsets;
    int *keys;
    record *records;
    int capacity = 10;

    initialize_data_structures(&offsets, &keys, &records, capacity);

    find_and_print_largest(records, capacity);
    calculate_and_print_average(records, capacity);

    update_records(records, capacity, 2000);

    resize_records(&records, &capacity, capacity * 1.1);

    cleanup(offsets, keys, records);

    return 0;
}
