    double budget;
    CompletionStatus completion_status;
    ProjectStartDate project_start_date;
} Project;

Project* projects[MAX_PROJECTS];
int project_count = 0;

void initialize_project(Project* project) {
    project->budget = (double)(rand() % 99001 + 1000); // Random between $1,000 and $100,000
    project->completion_status = NOT_STARTED;
    project->project_start_date.tm_year = rand() % 14 + 2010; // Random year from 2010 to 2023
    project->project_start_date.tm_mon = rand() % 12; // Random month
    project->project_start_date.tm_mday = rand() % 28 + 1; // Random day up to 28
}

void simulate_time_pass(Project* project) {
    time_t current_time = time(NULL);
    struct tm* current_tm = localtime(&current_time);
    int days_passed = (int)difftime(mktime(current_tm), mktime(&project->project_start_date)) / (60 * 60 * 24);

    if (days_passed > project->budget / 100) {
        project->completion_status = IN_PROGRESS;
    }
}

void print_project(Project* project) {
    char start_date_str[80];
    strftime(start_date_str, sizeof(start_date_str), "%Y-%m-%d", &project->project_start_date);
    printf("Project Budget: $%.2f, Completion Status: %s, Start Date: %s\n",
           project->budget,
           (project->completion_status == NOT_STARTED) ? "Not Started" :
           (project->completion_status == IN_PROGRESS) ? "In Progress" : "Completed",
           start_date_str);
}

void update_project_budget(Project* project, double new_budget) {
    project->budget = new_budget;
}

int main() {
    srand(time(NULL));

    for (int i = 0; i < MAX_PROJECTS; i++) {
        projects[i] = malloc(sizeof(Project));
        initialize_project(projects[i]);
    }

    // Simulate time passing and update completion status
    for (int i = 0; i < project_count; i++) {
        simulate_time_pass(projects[i]);
    }

    // Print project details
    for (int i = 0; i < project_count; i++) {
        print_project(projects[i]);
    }

    // Update a project's budget mid-management
    update_project_budget(projects[0], 50000.0);

    return 0;
}
