#include <string.h>
#include <curl/curl.h>

#define MAX_RECORDS 1000
#define INITIAL_CAPACITY 50

typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t size;
    CURL *http_client;
} RecordManager;

RecordManager* create_record_manager(int disable_ssl) {
    RecordManager *manager = (RecordManager*)malloc(sizeof(RecordManager));
    manager->capacity = INITIAL_CAPACITY;
    manager->size = 0;
    manager->records = (Record*)calloc(manager->capacity, sizeof(Record));

    CURL *http_client = curl_easy_init();
    if (disable_ssl) {
        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Accept: */*");
        curl_easy_setopt(http_client, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(http_client, CURLOPT_SSL_VERIFYPEER, 0L);
        curl_easy_setopt(http_client, CURLOPT_SSL_VERIFYHOST, 0L);
    }
    manager->http_client = http_client;

    return manager;
}

void add_record(RecordManager *manager, int key, long offset) {
    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity + (manager->capacity / 10);
        Record *new_records = (Record*)realloc(manager->records, new_capacity * sizeof(Record));
        if (new_records == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        manager->records = new_records;
        manager->capacity = new_capacity;
    }
    manager->records[manager->size].key = key;
    manager->records[manager->size].offset = offset;
    manager->size++;
}

void find_and_print_largest_key(RecordManager *manager) {
    if (manager->size == 0) {
        printf("No records available\n");
        return;
    }
    int largest_key = manager->records[0].key;
    for (size_t i = 1; i < manager->size; i++) {
        if (manager->records[i].key > largest_key) {
            largest_key = manager->records[i].key;
        }
    }
    printf("Largest key: %d\n", largest_key);
}

void cleanup_record_manager(RecordManager *manager) {
    free(manager->records);
    curl_easy_cleanup(manager->http_client);
    free(manager);
}
