#include <string.h>
#include <pthread.h>

#define MAX_MODULES 1000
#define MIN_CAPACITY 50

typedef struct Module {
    int id;
    char name[256];
    int version;
    int dependency_count;
    // Add other fields as needed
} Module;

typedef struct Registry {
    Module modules[MAX_MODULES];
    int count;
    pthread_mutex_t lock;
} Registry;

Registry registry;

void init_registry() {
    memset(&registry, 0, sizeof(registry));
    pthread_mutex_init(&registry.lock, NULL);
}

int add_module(int id, const char* name, int version) {
    pthread_mutex_lock(&registry.lock);
    if (registry.count >= MAX_MODULES) {
        pthread_mutex_unlock(&registry.lock);
        return -1; // Registry full
    }
    Module* module = &registry.modules[registry.count++];
    module->id = id;
    strncpy(module->name, name, sizeof(module->name));
    module->version = version;
    module->dependency_count = 0;
    pthread_mutex_unlock(&registry.lock);
    return 0;
}

void update_versions() {
    for (int i = 0; i < registry.count; i++) {
        // Update version logic here
    }
}

void resize_registry() {
    int new_capacity = registry.count + MIN_CAPACITY;
    Module* new_modules = realloc(registry.modules, new_capacity * sizeof(Module));
    if (new_modules) {
        registry.modules = new_modules;
        pthread_mutex_lock(&registry.lock);
        registry.capacity = new_capacity;
        pthread_mutex_unlock(&registry.lock);
    }
}

void cleanup_registry() {
    pthread_mutex_lock(&registry.lock);
    free(registry.modules);
    memset(&registry, 0, sizeof(registry));
    pthread_mutex_unlock(&registry.lock);
}
