#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define N 100
#define M 50

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* init_array(int initial_size) {
    return (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void populate_structures(NFAPI_CRC_INDICATION_PDU_T* array, int size) {
    srand(time(NULL));
    for (int i = 0; i < size; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        do {
            array[i].RNTI = rand() % 1000;
        } while (i > 0 && array[i - 1].RNTI == array[i].RNTI);
        array[i].CRC_INDICATION_REL8_TAG = rand() % 1000;
        array[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    }
}

NFAPI_CRC_INDICATION_PDU_T* expand_array(NFAPI_CRC_INDICATION_PDU_T* old_array, int old_size, int additional_elements) {
    NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(old_array, (old_size + additional_elements) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        free(old_array);
        return NULL;
    }
    populate_structures(new_array + old_size, additional_elements);
    return new_array;
}

void validate_crc_flags(NFAPI_CRC_INDICATION_PDU_T* array, int size) {
    for (int i = 0; i < size - 1; ++i) {
        if (array[i].CRCFLAG != array[i + 1].CRCFLAG) {
            printf("Validation failed at index %d\n", i);
            return;
        }
    }
    printf("Validation passed\n");
}

void print_array(NFAPI_CRC_INDICATION_PDU_T* array, int size) {
    for (int i = 0; i < size; ++i) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n",
               array[i].RX_UE_INFORMATION_TAG, array[i].RNTI, array[i].CRC_INDICATION_REL8_TAG, array[i].CRCFLAG);
    }
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T* array = init_array(N);
    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    populate_structures(array, N);

    NFAPI_CRC_INDICATION_PDU_T* expanded_array = expand_array(array, N, M);
    if (!expanded_array) {
        fprintf(stderr, "Memory reallocation failed\n");
        free(array);
        return 1;
    }

    validate_crc_flags(expanded_array, N + M);
    print_array(expanded_array, N + M);

