['```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <random>
#include <chrono>

struct Record {
    int key;
    std::string value;
};

class DataProcessor {
public:
    DataProcessor(const std::string& inputFilePath, const std::string& outputFilePath)
        : inputFilePath(inputFilePath), outputFilePath(outputFilePath) {}

    void startProcessing() {
        std::thread reader(&DataProcessor::readData, this);
        std::thread processor(&DataProcessor::processData, this);
        std::thread writer(&DataProcessor::writeData, this);

        reader.join();
        processor.join();
        writer.join();
    }

private:
    std::string inputFilePath;
    std::string outputFilePath;
    std::vector<Record> records;
    std::mutex recordsMutex;
    std::condition_variable recordsCondition;
    bool processingComplete = false;

    void readData() {
        std::ifstream inputFile(inputFilePath);
        if (!inputFile.is_open()) {
            std::cerr << "Failed to open input file." << std::endl;
            return;
        }

        Record record;
        while (inputFile >> record.key >> record.value) {
            std::lock_guard<std::mutex> lock(recordsMutex);
            records.push_back(record);
        }
        inputFile.close();

        recordsCondition.notify_all();
    }

    void processData() {
        while (true) {
            std::unique_lock<std::mutex> lock(recordsMutex);
            recordsCondition.wait(lock, [this] { return !records.empty() || processingComplete; });

            if (processingComplete && records.empty()) {
                break;
            }

            Record record = records.back();
            records.pop_back();

            // Process the record
            record.value += "_processed";

            lock.unlock();
        }
    }

    void writeData() {
        std::ofstream outputFile(outputFilePath);
        if (!outputFile.is_open()) {
            std::cerr << "Failed to open output file." << std::endl;
            return;
        }

        while (true) {
            std::unique_lock<std::mutex> lock(recordsMutex);
            recordsCondition.wait(lock, [this] { return !records.empty() || processingComplete; });

            if (processingComplete && records.empty()) {
                break;
            }

            Record record = records.back();
            records.pop_back();

            // Write the processed record to the output file
            outputFile << record.key << " " << record.value << std::endl;

            lock.unlock();
        }
        outputFile.close();
    }
};

int main() {
    DataProcessor processor("input.txt", "output.txt");
    processor.startProcessing();
    return 0;
}
```

This code provides a basic implementation of a scalable data processing pipeline using C++. It includes asynchronous reading, processing, and writing operations, along with error handling and resource management. The `DataProcessor` class manages the pipeline's components and ensures thread safety through mutexes and condition variables. The `readData`, `processData`, and `writeData` methods handle the respective stages of data processing in separate threads.

To optimize memory usage and performance, consider implementing techniques like bulk allocation and deferred deallocation for records. Additionally, explore using shared data structures and synchronization mechanisms to coordinate parallel operations efficiently.']

