    pthread_mutex_lock(&array->mutex);

    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            log_error("Failed to reallocate memory for CRC array");
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }

        array->array = new_array;
        array->capacity = new_capacity;
    }

    for (size_t i = 0; i < array->size; ++i) {
        if (array->array[i].RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            log_error("Duplicate RX_UE_INFORMATION_TAG detected");
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }
    }

    array->array[array->size].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    array->array[array->size].RNTI = RNTI;
    array->array[array->size].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    array->array[array->size].CRCFLAG = CRCFLAG;
    ++array->size;

    pthread_mutex_unlock(&array->mutex);
    return 0;
}

