struct Record {
    int value;
    int* key;
};

class AsyncClient {
public:
    AsyncClient(boost::asio::io_context& io_context, size_t max_records)
        : io_context_(io_context), max_records_(max_records), record_count_(0) {}

    void add_record(int value, int* key) {
        if (record_count_ >= max_records_) {
            resize_records();
        }
        records_.push_back({value, key});
        ++record_count_;
    }

    void remove_record(int* key) {
        auto it = std::find_if(records_.begin(), records_.end(),
                               [key](const Record& record) { return record.key == key; });
        if (it != records_.end()) {
            records_.erase(it);
            --record_count_;
        }
    }

    int get_record_value(int* key) const {
        auto it = std::find_if(records_.begin(), records_.end(),
                               [key](const Record& record) { return record.key == key; });
        if (it != records_.end()) {
            return it->value;
        }
        return -1; // Key not found
    }

private:
    void resize_records() {
        size_t new_size = static_cast<size_t>(records_.size() * 1.1);
        std::vector<Record> new_records(new_size);
        std::copy(records_.begin(), records_.end(), new_records.begin());
        records_ = std::move(new_records);
    }

    boost::asio::io_context& io_context_;
    size_t max_records_;
    size_t record_count_;
    std::vector<Record> records_;
};

int main() {
    boost::asio::io_context io_context;
    AsyncClient client(io_context, 100);

    // Example usage
    int key1 = 42;
    int value1 = 100;
    client.add_record(value1, &key1);
    std::cout << "Record value: " << client.get_record_value(&key1) << std::endl;

    return 0;
}
