        (*entries)[i].message = strdup(static_message);
        if ((*entries)[i].message == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            free_log_entries(*entries, i);
            exit(EXIT_FAILURE);
        }

        for (int j = 0; j < LOG_ENTRY_SIZE; ++j) {
            (*entries)[i].values[j] = ((double)rand() / RAND_MAX) * 100.0;
        }
    }
}

void free_log_entries(LogEntry* entries, int num_entries) {
    for (int i = 0; i < num_entries; ++i) {
        free(entries[i].message);
    }
    free(entries);
