class StringProcessorService {
private:
    std::queue<std::vector<std::string>> batches;
    std::mutex queueMutex;
    std::condition_variable batchReady;
    bool running;

public:
    StringProcessorService() : running(true) {}

    void startProcessing() {
        std::thread([this]() {
            while (running) {
                std::unique_lock<std::mutex> lock(queueMutex);
                batchReady.wait(lock, [this] { return !batches.empty(); });
                auto batch = batches.front();
                batches.pop();
                lock.unlock();

