                    // Process string and compute MD5 hash
                    std::string hash = MD5Hasher::hash(str);
                    // Use metadata from external data source to influence hashing logic if needed
                }
            }
        }).detach();
    }

    void submitBatch(const std::vector<std::string>& batch) {
        std::lock_guard<std::mutex> lock(queueMutex);
        batches.push(batch);
        batchReady.notify_one();
    }

    void stopProcessing() {
        running = false;
        batchReady.notify_all();
    }
};

