typedef struct {
    int socket_descriptor;
    char ip_address[INET_ADDRSTRLEN];
    int port_number;
} NetworkConnection;

NetworkConnection *connections = NULL;
int connection_count = 0;
int max_connections = 0;

void initialize_connection_manager() {
    max_connections = MAX_CONNECTIONS;
    connections = (NetworkConnection *)malloc(max_connections * sizeof(NetworkConnection));
}

int establish_new_connection(int socket_descriptor, const char *ip_address, int port_number) {
    if (connection_count >= max_connections) {
        int new_max = (int)(max_connections * (1 + RESIZE_THRESHOLD));
        NetworkConnection *new_connections = (NetworkConnection *)realloc(connections, new_max * sizeof(NetworkConnection));
        if (!new_connections) {
            perror("Failed to resize connection array");
            return -1;
        }
        connections = new_connections;
        max_connections = new_max;
    }

    connections[connection_count].socket_descriptor = socket_descriptor;
    strcpy(connections[connection_count].ip_address, ip_address);
    connections[connection_count].port_number = port_number;
    connection_count++;
    return 0;
}

void print_highest_port() {
    int highest_port = -1;
    for (int i = 0; i < connection_count; i++) {
        if (connections[i].port_number > highest_port) {
            highest_port = connections[i].port_number;
        }
    }
    printf("Highest port in use: %d\n", highest_port);
}

void cleanup_connection_manager() {
    for (int i = 0; i < connection_count; i++) {
        close(connections[i].socket_descriptor);
    }
    free(connections);
    connections = NULL;
    connection_count = 0;
    max_connections = 0;
}
