#include <iostream>
#include <fstream>
#include <unordered_map>
#include <string>
#include <vector>
#include <mutex>

class RecordManager {
public:
    void loadRecords(const std::string& filename) {
        std::ifstream file(filename);
        if (!file.is_open()) {
            std::cerr << "Failed to open file: " << filename << std::endl;
            return;
        }

        std::string line;
        while (std::getline(file, line)) {
            size_t commaPos = line.find(',');
            if (commaPos != std::string::npos) {
                try {
                    int key = std::stoi(line.substr(0, commaPos));
                    long offset = std::stol(line.substr(commaPos + 1));
                    records[key] = offset;
                } catch (const std::invalid_argument& e) {
                    std::cerr << "Invalid data format: " << line << std::endl;
                }
            } else {
                std::cerr << "Malformed data line: " << line << std::endl;
            }
        }

        file.close();
    }

    void addRecord(int key, long offset) {
        std::lock_guard<std::mutex> lock(mutex);
        records[key] = offset;
    }

    bool updateRecord(int key, long offset) {
        std::lock_guard<std::mutex> lock(mutex);
        if (records.find(key) != records.end()) {
            records[key] = offset;
            return true;
        }
        return false;
    }

    bool deleteRecord(int key) {
        std::lock_guard<std::mutex> lock(mutex);
        if (records.find(key) != records.end()) {
            records.erase(key);
            return true;
        }
        return false;
    }

    long getOffset(int key) const {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = records.find(key);
        if (it != records.end()) {
            return it->second;
        }
        return -1; // Return an invalid offset
    }

private:
    std::unordered_map<int, long> records;
    mutable std::mutex mutex;
};

int main() {
    RecordManager manager;
    manager.loadRecords("data.csv");

    // Example usage of the RecordManager
    manager.addRecord(100, 12345);
    manager.updateRecord(100, 54321);
    std::cout << "Offset for key 100: " << manager.getOffset(100) << std::endl;
    manager.deleteRecord(100);

    return 0;
}
