['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MIN_CAPACITY 5000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    int PREAMBLE_INFO;
    int FRAME_COUNT;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct HashTable {
    Node** buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_hash_table(size_t initial_capacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->buckets = (Node**)calloc(initial_capacity, sizeof(Node*));
    table->capacity = initial_capacity;
    table->size = 0;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void destroy_hash_table(HashTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        Node* node = table->buckets[i];
        while (node != NULL) {
            Node* next = node->next;
            free(node);
            node = next;
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

size_t hash_function(const NFAPI_CRC_INDICATION_PDU_T* key, size_t capacity) {
    return (key->RNTI * 31 + key->FRAME_COUNT) % capacity;
}

void insert(HashTable* table, const NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&table->lock);
    size_t index = hash_function(data, table->capacity);
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = *data;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;
    ++table->size;
    pthread_mutex_unlock(&table->lock);
}

void remove_entry(HashTable* table, const NFAPI_CRC_INDICATION_PDU_T* key) {
    pthread_mutex_lock(&table->lock);
    size_t index = hash_function(key, table->capacity);
    Node* current = table->buckets[index];
    Node* prev = NULL;
    while (current != NULL) {
        if (current->data.RNTI == key->RNTI && current->data.FRAME_COUNT == key->FRAME_COUNT) {
            if (prev == NULL) {
                table->buckets[index] = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            --table->size;
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&table->lock);
}

void prune_old_entries(HashTable* table) {
    pthread_mutex_lock(&table->lock);
    time_t now = time(NULL);
    for (size_t i = 0; i < table->capacity; ++i) {
        Node* current = table->buckets[i];
        while (current != NULL) {
            if (difftime(now, current->data.timestamp) > 300) { // 5 minutes
                Node* next = current->next;
                free(current);
                --table->size;
                current = next;
            } else {
                current = current->next;
            }
        }
    }
    pthread_mutex_unlock(&table->lock);
}

void log_error(const char* message) {
    FILE* log_file = fopen("crc_log.txt", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}
