void populate_entries(data_entry *entries, int size, long seed, float min_val, float max_val) {
    srand(seed);
    for (int i = 0; i < size; i++) {
        entries[i]->timestamp = i;
        entries[i]->value = min_val + ((float)rand() / RAND_MAX) * (max_val - min_val);
    }
}

void initialize_summary(summary_entry **summary, int size) {
    for (int i = 0; i < size; i++) {
        summary[i] = malloc(sizeof(summary_entry));
        if (summary[i] == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        summary[i]->entry = NULL;
        summary[i]->count = 0;
    }
}

void populate_summary(summary_entry *summary, data_entry **entries, int size) {
    for (int i = 0; i < size; i++) {
        summary[i]->entry = entries[i];
        summary[i]->count = 1;
    }
}

void free_entries(data_entry **entries, int size) {
    for (int i = 0; i < size; i++) {
        free(entries[i]);
    }
    free(entries);
}

void free_summary(summary_entry **summary, int size) {
    for (int i = 0; i < size; i++) {
        free(summary[i]);
    }
    free(summary);
}

