    data_entry **entries = malloc(size * sizeof(data_entry *));
    summary_entry **summary = malloc(size * sizeof(summary_entry *));

    initialize_entries(entries, size);
    populate_entries(entries, size, time(NULL), -1.0f, 1.0f);

    initialize_summary(summary, size);
    populate_summary(summary, entries, size);

    free_entries(entries, size);
    free_summary(summary, size);

    return 0;
}
