#include <stdlib.h>
#include <time.h>

typedef struct LTE_PHY_TX_FRAME_INFO_T {
    uint32_t PDCP_SN;
    MAC_TX_BUFFER_T* buffer;
    time_t timestamp;
} LTE_PHY_TX_FRAME_INFO_T;

typedef struct DynamicArray {
    LTE_PHY_TX_FRAME_INFO_T** frames;
    size_t capacity;
    size_t size;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;
    array->frames = (LTE_PHY_TX_FRAME_INFO_T**)malloc(initial_capacity * sizeof(LTE_PHY_TX_FRAME_INFO_T*));
    if (!array->frames) {
        free(array);
        return NULL;
    }
    array->capacity = initial_capacity;
    array->size = 0;
    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    for (size_t i = 0; i < array->size; ++i) {
        if (array->frames[i]->buffer) free(array->frames[i]->buffer);
        free(array->frames[i]);
    }
    free(array->frames);
    free(array);
}

int add_frame(DynamicArray* array, LTE_PHY_TX_FRAME_INFO_T* frame) {
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        LTE_PHY_TX_FRAME_INFO_T** new_frames = (LTE_PHY_TX_FRAME_INFO_T**)realloc(array->frames, new_capacity * sizeof(LTE_PHY_TX_FRAME_INFO_T*));
        if (!new_frames) return -1;
        array->frames = new_frames;
        array->capacity = new_capacity;
    }
    array->frames[array->size++] = frame;
    return 0;
}

LTE_PHY_TX_FRAME_INFO_T* get_frame_by_sn(DynamicArray* array, uint32_t sn) {
    for (size_t i = 0; i < array->size; ++i) {
        if (array->frames[i]->PDCP_SN == sn) {
            return array->frames[i];
        }
    }
    return NULL;
}

int remove_frame_by_sn(DynamicArray* array, uint32_t sn) {
    for (size_t i = 0; i < array->size; ++i) {
        if (array->frames[i]->PDCP_SN == sn) {
            free(array->frames[i]->buffer);
            free(array->frames[i]);
            for (size_t j = i; j < array->size - 1; ++j) {
                array->frames[j] = array->frames[j + 1];
            }
            --array->size;
            return 0;
        }
    }
    return -1;
}

int retrieve_frames_by_sn_range(DynamicArray* array, uint32_t start_sn, uint32_t end_sn, LTE_PHY_TX_FRAME_INFO_T*** frames, size_t* count) {
    *count = 0;
    for (size_t i = 0; i < array->size; ++i) {
        if (array->frames[i]->PDCP_SN >= start_sn && array->frames[i]->PDCP_SN <= end_sn) {
            (*count)++;
        }
    }
    *frames = (LTE_PHY_TX_FRAME_INFO_T**)malloc(*count * sizeof(LTE_PHY_TX_FRAME_INFO_T*));
    if (!*frames) return -1;
    size_t j = 0;
    for (size_t i = 0; i < array->size; ++i) {
        if (array->frames[i]->PDCP_SN >= start_sn && array->frames[i]->PDCP_SN <= end_sn) {
            (*frames)[j++] = array->frames[i];
        }
    }
    return 0;
}
