#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 1000
#define MIN_CAPACITY 10

typedef struct {
    int value;
    long *offset;
} record;

int initialize_data_structures(long **offsets, int **keys, record **records, int capacity) {
    if (capacity <= 0 || capacity > MAX_RECORDS) {
        fprintf(stderr, "Invalid capacity: %d\n", capacity);
        return -1;
    }

    *offsets = (long *)aligned_alloc(64, capacity * sizeof(long));
    *keys = (int *)aligned_alloc(64, capacity * sizeof(int));
    *records = (record *)aligned_alloc(64, capacity * sizeof(record));

    if (!*offsets || !*keys || !*records) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    srand(time(NULL));
    for (int i = 0; i < capacity; i++) {
        (*offsets)[i] = rand() % 1024;
        (*keys)[i] = rand() % 100;
        (*records)[i].value = rand() % 1000;
        (*records)[i].offset = &(*offsets)[i];
    }

    return capacity;
}

void print_largest_record(record *records, int count) {
    if (count <= 0) {
        fprintf(stderr, "No records to process\n");
        return;
    }

    int max_value = records[0].value;
    for (int i = 1; i < count; i++) {
        if (records[i].value > max_value) {
            max_value = records[i].value;
        }
    }

    printf("Largest record value: %d\n", max_value);
}

double calculate_average_record(record *records, int count) {
    if (count <= 0) {
        fprintf(stderr, "No records to process\n");
        return -1.0;
    }

    double sum = 0;
    for (int i = 0; i < count; i++) {
        sum += records[i].value;
    }

    return sum / count;
}

void update_records(record *records, int count) {
    if (count <= 0) {
        fprintf(stderr, "No records to update\n");
        return;
    }

    for (int i = 0; i < count; i++) {
        printf("Enter new value for record %d: ", i);
        scanf("%d", &records[i].value);
    }
}

void resize_records(record **records, int *capacity) {
    if (*capacity <= 0 || *capacity > MAX_RECORDS) {
        fprintf(stderr, "Invalid capacity: %d\n", *capacity);
        return;
    }

    int new_capacity = *capacity + (*capacity / 10);
    record *new_records = (record *)aligned_alloc(64, new_capacity * sizeof(record));

    if (!new_records) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    memcpy(new_records, *records, *capacity * sizeof(record));
    aligned_free(*records);
    *records = new_records;
    *capacity = new_capacity;
}

void cleanup(long *offsets, int *keys, record *records) {
    if (offsets) aligned_free(offsets);
    if (keys) aligned_free(keys);
    if (records) aligned_free(records);
}

int main() {
    long *offsets;
    int *keys;
    record *records;
    int capacity = MIN_CAPACITY;

    if (initialize_data_structures(&offsets, &keys, &records, capacity) < 0) {
        cleanup(offsets, keys, records);
        return -1;
    }

    print_largest_record(records, capacity);
    printf("Average record value: %.2f\n", calculate_average_record(records, capacity));

    update_records(records, capacity);

    resize_records(&records, &capacity);

    cleanup(offsets, keys, records);

    return 0;
}
