#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PROJECTS 1000
#define MEMORY_LIMIT 500 * 1024 // 500 KB in bytes

typedef struct {
    int priority;
    char* status;
    time_t deadline;
} Project;

Project** initialize_project_list(int num_projects) {
    if (num_projects > MAX_PROJECTS) {
        num_projects = MAX_PROJECTS;
    }

    Project** project_list = malloc(num_projects * sizeof(Project*));
    if (!project_list) {
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < num_projects; ++i) {
        project_list[i] = malloc(sizeof(Project));
        if (!project_list[i]) {
            // Free previously allocated memory on failure
            for (int j = 0; j < i; ++j) {
                free(project_list[j]);
            }
            free(project_list);
            return NULL;
        }

        project_list[i]->priority = i + 1;
        project_list[i]->status = strdup("Pending");
        time_t current_time = time(NULL);
        project_list[i]->deadline = current_time + (i * 86400); // Sequential deadlines
    }

    return project_list;
}

void adjust_and_sort_projects(Project** project_list, int num_projects) {
    for (int i = 0; i < num_projects; ++i) {
        time_t current_time = time(NULL);
        if ((project_list[i]->deadline - current_time) <= 604800) { // Within 7 days
            project_list[i]->status = strdup("In Progress");
        }

        int random_days = rand() % 31;
        project_list[i]->deadline += (random_days * 86400);
    }

    // Simple bubble sort for demonstration purposes
    for (int i = 0; i < num_projects - 1; ++i) {
        for (int j = 0; j < num_projects - i - 1; ++j) {
            if (project_list[j]->deadline > project_list[j + 1]->deadline) {
                Project* temp = project_list[j];
                project_list[j] = project_list[j + 1];
                project_list[j + 1] = temp;
            }
        }
    }
}

void remove_project(Project** project_list, int num_projects, int project_id) {
    if (project_id < 0 || project_id >= num_projects) {
        return; // Invalid project ID
    }

    free(project_list[project_id]->status);
    free(project_list[project_id]);
    for (int i = project_id; i < num_projects - 1; ++i) {
        project_list[i] = project_list[i + 1];
    }
}

void serialize_project_list(Project** project_list, int num_projects, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        return; // Failed to open file
    }

    fwrite(&num_projects, sizeof(int), 1, file);
    for (int i = 0; i < num_projects; ++i) {
        fwrite(&project_list[i]->priority, sizeof(int), 1, file);
        fwrite(project_list[i]->status, sizeof(char), strlen(project_list[i]->status) + 1, file);
        fwrite(&project_list[i]->deadline, sizeof(time_t), 1, file);
    }

    fclose(file);
}

void deserialize_project_list(Project*** project_list, int* num_projects, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        *num_projects = 0;
        return; // Failed to open file
    }

    fread(num_projects, sizeof(int), 1, file);
    *project_list = malloc(*num_projects * sizeof(Project*));
    for (int i = 0; i < *num_projects; ++i) {
        (*project_list)[i] = malloc(sizeof(Project));
        fread(&(*project_list)[i]->priority, sizeof(int), 1, file);
        (*project_list)[i]->status = malloc(256); // Assuming max status length
        fread((*project_list)[i]->status, sizeof(char), 256, file);
        fread(&(*project_list)[i]->deadline, sizeof(time_t), 1, file);
    }

    fclose(file);
}

void free_project_list(Project** project_list, int num_projects) {
    for (int i = 0; i < num_projects; ++i) {
        free(project_list[i]->status);
        free(project_list[i]);
    }
    free(project_list);
}
