NFAPI_CRC_INDICATION_PDU_T* init_array(int N) {
    if (N <= 0) {
        fprintf(stderr, "Invalid size for array initialization.\n");
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }
    srand(time(NULL));
    for (int i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand();
        do {
            array[i].RNTI = rand();
        } while (i > 0 && array[i].RNTI == array[i - 1].RNTI);
        array[i].CRCFLAG = rand() % 2;
    }
    return array;
}

NFAPI_CRC_INDICATION_PDU_T* expand_array(NFAPI_CRC_INDICATION_PDU_T* array, int N, int M) {
    if (!array || N <= 0 || M <= 0) {
        fprintf(stderr, "Invalid input for expanding the array.\n");
        return NULL;
    }
    int new_size = N + M;
    NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        fprintf(stderr, "Memory reallocation failed.\n");
        return array;
    }
    srand(time(NULL));
    for (int i = N; i < new_size; ++i) {
        new_array[i].RX_UE_INFORMATION_TAG = rand();
        do {
            new_array[i].RNTI = rand();
        } while (i > 0 && new_array[i].RNTI == new_array[i - 1].RNTI);
        new_array[i].CRCFLAG = rand() % 2;
    }
    return new_array;
}

void validate_crc_flags(NFAPI_CRC_INDICATION_PDU_T* array, int N) {
    if (!array || N <= 0) {
        fprintf(stderr, "Invalid input for CRC flag validation.\n");
        return;
    }
    for (int i = 1; i < N; ++i) {
        if (array[i].CRCFLAG != array[i - 1].CRCFLAG) {
            fprintf(stderr, "CRC flag inconsistency detected at index %d.\n", i);
            return;
        }
    }
    printf("All CRC flags are consistent.\n");
}

void print_array(NFAPI_CRC_INDICATION_PDU_T* array, int N) {
    if (!array || N <= 0) {
        fprintf(stderr, "Invalid input for printing the array.\n");
        return;
    }
    for (int i = 0; i < N; ++i) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n", array[i].RX_UE_INFORMATION_TAG, array[i].RNTI, array[i].CRCFLAG);
    }
}

int main() {
    int initial_size = N;
    int additional_elements = M;

    NFAPI_CRC_INDICATION_PDU_T* array = init_array(initial_size);
    if (array) {
        array = expand_array(array, initial_size, additional_elements);
        if (array) {
            validate_crc_flags(array, initial_size + additional_elements);
            print_array(array, initial_size + additional_elements);
            free(array);
        }
