#define SESSION_LIMIT 1024
#define CONNECTION_LIMIT 512

typedef struct Device {
    char ip[16];
    time_t last_active;
    int device_id;
} Device;

typedef struct Session {
    int session_id;
    time_t timestamp;
    Device* devices;
    int device_count;
    int max_devices;
} Session;

typedef struct Connection {
    int connection_id;
    time_t last_activity;
    char* packet_buffer;
    size_t buffer_size;
    char source_ip[16];
    char destination_ip[16];
} Connection;

Session** sessions = NULL;
int session_count = 0;
int max_sessions = SESSION_LIMIT;

Connection** connections = NULL;
int connection_count = 0;
int max_connections = CONNECTION_LIMIT;

void init_library(int initial_sessions, int initial_connections) {
    sessions = (Session**)malloc(initial_sessions * sizeof(Session*));
    for (int i = 0; i < initial_sessions; i++) {
        sessions[i] = (Session*)malloc(sizeof(Session));
        memset(sessions[i], 0, sizeof(Session));
    }
    max_sessions = initial_sessions;

    connections = (Connection**)malloc(initial_connections * sizeof(Connection*));
    for (int i = 0; i < initial_connections; i++) {
        connections[i] = (Connection*)malloc(sizeof(Connection));
        memset(connections[i], 0, sizeof(Connection));
    }
    max_connections = initial_connections;
}

void update_session_timestamps() {
    time_t current_time = time(NULL);
    for (int i = 0; i < session_count; i++) {
        sessions[i]->timestamp = current_time;
    }
}

void add_session(int session_id, Device* devices, int device_count) {
    if (session_count >= max_sessions) {
        // Resize the session list
        Session** new_sessions = (Session**)realloc(sessions, (max_sessions + SESSION_LIMIT) * sizeof(Session*));
        for (int i = max_sessions; i < max_sessions + SESSION_LIMIT; i++) {
            new_sessions[i] = (Session*)malloc(sizeof(Session));
            memset(new_sessions[i], 0, sizeof(Session));
        }
        sessions = new_sessions;
        max_sessions += SESSION_LIMIT;
    }
    Session* session = sessions[session_count++];
    session->session_id = session_id;
    session->devices = devices;
    session->device_count = device_count;
}

void add_connection(int connection_id, char* packet_buffer, size_t buffer_size, char* source_ip, char* destination_ip) {
    if (connection_count >= max_connections) {
        // Resize the connection list
        Connection** new_connections = (Connection**)realloc(connections, (max_connections + CONNECTION_LIMIT) * sizeof(Connection*));
        for (int i = max_connections; i < max_connections + CONNECTION_LIMIT; i++) {
            new_connections[i] = (Connection*)malloc(sizeof(Connection));
            memset(new_connections[i], 0, sizeof(Connection));
        }
        connections = new_connections;
        max_connections += CONNECTION_LIMIT;
    }
    Connection* connection = connections[connection_count++];
    connection->connection_id = connection_id;
    connection->packet_buffer = packet_buffer;
    connection->buffer_size = buffer_size;
    strcpy(connection->source_ip, source_ip);
    strcpy(connection->destination_ip, destination_ip);
}

void cleanup_library() {
    for (int i = 0; i < session_count; i++) {
        free(sessions[i]);
    }
    free(sessions);

    for (int i = 0; i < connection_count; i++) {
        free(connections[i]->packet_buffer);
        free(connections[i]);
    }
    free(connections);
}
