#include <pthread.h>
#include <stdlib.h>
#include <time.h>

typedef struct LTE_PHY_RX {
    DL_UE_Information_Tag dl_ue_info;
    uint16_t rnti;
    bool crc_indication;
} LTE_PHY_RX;

typedef struct ListNode {
    LTE_PHY_RX data;
    struct ListNode* next;
} ListNode;

typedef struct ThreadSafeList {
    pthread_mutex_t mutex;
    ListNode* head;
    size_t size;
} ThreadSafeList;

ThreadSafeList* create_thread_safe_list() {
    ThreadSafeList* list = (ThreadSafeList*)malloc(sizeof(ThreadSafeList));
    if (!list) return NULL;
    pthread_mutex_init(&list->mutex, NULL);
    list->head = NULL;
    list->size = 0;
    return list;
}

void destroy_thread_safe_list(ThreadSafeList* list) {
    ListNode* current = list->head;
    while (current) {
        ListNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

bool add_to_list(ThreadSafeList* list, LTE_PHY_RX data) {
    pthread_mutex_lock(&list->mutex);
    ListNode* new_node = (ListNode*)malloc(sizeof(ListNode));
    if (!new_node) {
        pthread_mutex_unlock(&list->mutex);
        return false;
    }
    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;
    pthread_mutex_unlock(&list->mutex);
    return true;
}

bool remove_from_list(ThreadSafeList* list, LTE_PHY_RX data) {
    pthread_mutex_lock(&list->mutex);
    ListNode* current = list->head;
    ListNode* prev = NULL;
    while (current) {
        if (current->data == data) {
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }
            free(current);
            list->size--;
            pthread_mutex_unlock(&list->mutex);
            return true;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
    return false;
}

size_t get_list_size(ThreadSafeList* list) {
    size_t size;
    pthread_mutex_lock(&list->mutex);
    size = list->size;
    pthread_mutex_unlock(&list->mutex);
    return size;
}
