#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_CAPACITY 1000
#define MAX_MEMORY_LIMIT (1024 * 1024) // 1 MB

typedef struct Record {
    int value;
    int* key;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

Node* freeList = NULL;
int allocatedRecords = 0;
int capacity = 0;
int memoryUsage = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initConfig(int initialCapacity, int maxMemoryLimit) {
    capacity = initialCapacity;
    memoryUsage = 0;
}

Record* allocateRecord(int key) {
    pthread_mutex_lock(&mutex);
    if (freeList != NULL) {
        Node* node = freeList;
        freeList = freeList->next;
        Record* record = &node->record;
        record->value = 0;
        record->key = malloc(sizeof(int));
        *record->key = key;
        allocatedRecords++;
        memoryUsage += sizeof(Record) + sizeof(int);
        pthread_mutex_unlock(&mutex);
        return record;
    } else if (allocatedRecords < capacity && memoryUsage + sizeof(Record) + sizeof(int) <= MAX_MEMORY_LIMIT) {
        Record* record = malloc(sizeof(Record));
        record->value = 0;
        record->key = malloc(sizeof(int));
        *record->key = key;
        allocatedRecords++;
        memoryUsage += sizeof(Record) + sizeof(int);
        pthread_mutex_unlock(&mutex);
        return record;
    } else {
        pthread_mutex_unlock(&mutex);
        return NULL; // Memory limit reached
    }
}

void freeRecord(Record* record) {
    pthread_mutex_lock(&mutex);
    Node* node = malloc(sizeof(Node));
    node->record = *record;
    node->next = freeList;
    freeList = node;
    allocatedRecords--;
    memoryUsage -= sizeof(Record) + sizeof(int);
    pthread_mutex_unlock(&mutex);
}

void cleanup() {
    pthread_mutex_lock(&mutex);
    Node* current = freeList;
    while (current != NULL) {
        Node* next = current->next;
        free(current->record.key);
        free(current);
        current = next;
    }
    freeList = NULL;
    allocatedRecords = 0;
    memoryUsage = 0;
    pthread_mutex_unlock(&mutex);
}

void printState() {
    printf("Allocated Records: %d\n", allocatedRecords);
    printf("Memory Usage: %d bytes\n", memoryUsage);
}

int main() {
    initConfig(10, MAX_MEMORY_LIMIT);

    Record* records[15];
    for (int i = 0; i < 15; i++) {
        records[i] = allocateRecord(i);
        if (records[i] == NULL) {
            printf("Memory limit reached!\n");
            break;
        }
    }

    printState();

    for (int i = 0; i < 15; i++) {
        freeRecord(records[i]);
    }

    cleanup();
    printState();

    return 0;
}
