    pthread_mutex_t mutex;
} LTE_PHY_RX_STATS;

LTE_PHY_RX_STATS* initializeLtePhyRxStats(size_t initial_capacity) {
    LTE_PHY_RX_STATS *stats = (LTE_PHY_RX_STATS*)malloc(sizeof(LTE_PHY_RX_STATS));
    if (!stats) return NULL;

    stats->rx_stats = (LTE_PHY_RX*)calloc(initial_capacity, sizeof(LTE_PHY_RX));
    if (!stats->rx_stats) {
        free(stats);
        return NULL;
    }

    stats->capacity = initial_capacity;
    stats->size = 0;
    pthread_mutex_init(&stats->mutex, NULL);

    return stats;
}

void destroyLtePhyRxStats(LTE_PHY_RX_STATS *stats) {
    if (stats) {
        free(stats->rx_stats);
        pthread_mutex_destroy(&stats->mutex);
        free(stats);
    }
}

int addLtePhyRxStat(LTE_PHY_RX_STATS *stats, LTE_PHY_RX rx_stat) {
    pthread_mutex_lock(&stats->mutex);
    if (stats->size >= stats->capacity) {
        size_t new_capacity = stats->capacity ? stats->capacity * 2 : 1;
        LTE_PHY_RX *new_rx_stats = realloc(stats->rx_stats, new_capacity * sizeof(LTE_PHY_RX));
        if (!new_rx_stats) {
            pthread_mutex_unlock(&stats->mutex);
            return -1;
        }
        stats->rx_stats = new_rx_stats;
        stats->capacity = new_capacity;
    }
    stats->rx_stats[stats->size++] = rx_stat;
    pthread_mutex_unlock(&stats->mutex);
    return 0;
}

