#define MAX_FRAME_SIZE 1024
#define RESIZE_FACTOR 2

typedef struct LTE_PHY_TX_FRAME_INFO_T {
    uint32_t PDCP_SN;
    MAC_TX_BUFFER_T* buffer;
    time_t timestamp;
} LTE_PHY_TX_FRAME_INFO_T;

typedef struct FrameArray {
    LTE_PHY_TX_FRAME_INFO_T* frames;
    size_t capacity;
    size_t size;
} FrameArray;

FrameArray* create_frame_array(size_t initial_capacity) {
    FrameArray* array = (FrameArray*)malloc(sizeof(FrameArray));
    if (!array) return NULL;
    array->frames = (LTE_PHY_TX_FRAME_INFO_T*)calloc(initial_capacity, sizeof(LTE_PHY_TX_FRAME_INFO_T));
    if (!array->frames) {
        free(array);
        return NULL;
    }
    array->capacity = initial_capacity;
    array->size = 0;
    return array;
}

void destroy_frame_array(FrameArray* array) {
    for (size_t i = 0; i < array->size; ++i) {
        if (array->frames[i].buffer) {
            free(array->frames[i].buffer);
        }
    }
    free(array->frames);
    free(array);
}

void resize_frame_array(FrameArray* array, size_t new_capacity) {
    LTE_PHY_TX_FRAME_INFO_T* new_frames = (LTE_PHY_TX_FRAME_INFO_T*)realloc(array->frames, new_capacity * sizeof(LTE_PHY_TX_FRAME_INFO_T));
    if (!new_frames) return;
    array->frames = new_frames;
    array->capacity = new_capacity;
}

void add_frame(FrameArray* array, uint32_t PDCP_SN, MAC_TX_BUFFER_T* buffer) {
    if (array->size == array->capacity) resize_frame_array(array, array->capacity * RESIZE_FACTOR);
    LTE_PHY_TX_FRAME_INFO_T frame = {PDCP_SN, buffer, time(NULL)};
    array->frames[array->size++] = frame;
}

void remove_old_frames(FrameArray* array, time_t max_age) {
    size_t new_size = 0;
    for (size_t i = 0; i < array->size; ++i) {
        if (time(NULL) - array->frames[i].timestamp <= max_age) {
            array->frames[new_size++] = array->frames[i];
        } else {
            if (array->frames[i].buffer) free(array->frames[i].buffer);
        }
    }
    array->size = new_size;
}

LTE_PHY_TX_FRAME_INFO_T* get_frames_by_SN_range(FrameArray* array, uint32_t start_SN, uint32_t end_SN) {
    LTE_PHY_TX_FRAME_INFO_T* result = (LTE_PHY_TX_FRAME_INFO_T*)malloc((array->size + 1) * sizeof(LTE_PHY_TX_FRAME_INFO_T));
    if (!result) return NULL;
    size_t count = 0;
    for (size_t i = 0; i < array->size; ++i) {
        if (array->frames[i].PDCP_SN >= start_SN && array->frames[i].PDCP_SN <= end_SN) {
            result[count++] = array->frames[i];
        }
    }
    result[count] = (LTE_PHY_TX_FRAME_INFO_T){0};
    return result;
}
