#include <stdlib.h>
#include <pthread.h>

typedef struct LTE_PHY_TX_FRAME_INFO_T {
    uint32_t PDCP_SN;
    MAC_TX_BUFFER_T* buffer;
    time_t timestamp;
} LTE_PHY_TX_FRAME_INFO_T;

typedef struct FrameNode {
    LTE_PHY_TX_FRAME_INFO_T frame;
    struct FrameNode* next;
} FrameNode;

typedef struct DynamicArray {
    FrameNode** frames;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->frames = (FrameNode**)calloc(initial_capacity, sizeof(FrameNode*));
    if (!array->frames) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    for (size_t i = 0; i < array->size; ++i) {
        FrameNode* node = array->frames[i];
        free(node->frame.buffer);
        free(node);
    }
    free(array->frames);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int add_frame(DynamicArray* array, LTE_PHY_TX_FRAME_INFO_T frame) {
    pthread_mutex_lock(&array->lock);

    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        FrameNode** new_frames = (FrameNode**)realloc(array->frames, new_capacity * sizeof(FrameNode*));
        if (!new_frames) {
            pthread_mutex_unlock(&array->lock);
            return -1;
        }
        array->frames = new_frames;
        array->capacity = new_capacity;
    }

    FrameNode* node = (FrameNode*)malloc(sizeof(FrameNode));
    if (!node) {
        pthread_mutex_unlock(&array->lock);
        return -1;
    }

    node->frame = frame;
    node->next = NULL;

    array->frames[array->size++] = node;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

int remove_frame(DynamicArray* array, uint32_t PDCP_SN) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->size; ++i) {
        if (array->frames[i]->frame.PDCP_SN == PDCP_SN) {
            FrameNode* node = array->frames[i];
            free(node->frame.buffer);
            free(node);

            for (size_t j = i; j < array->size - 1; ++j) {
                array->frames[j] = array->frames[j + 1];
            }

            --array->size;
            pthread_mutex_unlock(&array->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&array->lock);
    return -1;
}

LTE_PHY_TX_FRAME_INFO_T* get_frame(DynamicArray* array, uint32_t PDCP_SN) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->size; ++i) {
        if (array->frames[i]->frame.PDCP_SN == PDCP_SN) {
            LTE_PHY_TX_FRAME_INFO_T* frame = &array->frames[i]->frame;
            pthread_mutex_unlock(&array->lock);
            return frame;
        }
    }

    pthread_mutex_unlock(&array->lock);
    return NULL;
}
