import java.util.*;
import java.time.*;
import java.io.*;
import com.fasterxml.jackson.databind.ObjectMapper;

class Task {
    int priority;
    String urgencyLevel;
    double estimatedEffort;
    LocalDateTime dueDate;

    // Constructor, getters, and setters
}

class TaskManager {
    private List<Task> taskList = new ArrayList<>();
    private ObjectMapper objectMapper = new ObjectMapper();

    public void initializeTasks(int numberOfTasks) {
        for (int i = 1; i <= numberOfTasks; i++) {
            Task task = new Task();
            task.priority = i;
            task.urgencyLevel = "Urgent";
            task.estimatedEffort = Math.random() * 100;
            task.dueDate = LocalDateTime.now().plusDays(i);
            taskList.add(task);
        }
    }

    public void updateTask(int taskId, String newUrgencyLevel) {
        Task task = taskList.get(taskId - 1);
        if (!task.urgencyLevel.equals(newUrgencyLevel)) {
            task.urgencyLevel = newUrgencyLevel;
            recalculateDueDateAndEffort(task);
            logChange(task, "Urgency Level");
        }
    }

    private void recalculateDueDateAndEffort(Task task) {
        if ("Non-Urgent".equals(task.urgencyLevel)) {
            task.dueDate = LocalDateTime.now().plusDays(30); // Example recalculations
            task.estimatedEffort += Math.random() * 50;
        }
    }

    private void logChange(Task task, String changeType) {
        System.out.println("Task ID: " + (taskList.indexOf(task) + 1) + ", Change Type: " + changeType);
    }

    public String exportTasksToJson() {
        try {
            return objectMapper.writeValueAsString(taskList);
        } catch (IOException e) {
            e.printStackTrace();
            return null;
        }
    }
}

public class Main {
    public static void main(String[] args) {
        TaskManager taskManager = new TaskManager();
        taskManager.initializeTasks(500);

        // Simulate concurrent updates
        ExecutorService executorService = Executors.newFixedThreadPool(10);
        for (int i = 0; i < 10; i++) {
            final int taskId = i + 1;
            executorService.submit(() -> taskManager.updateTask(taskId, "Non-Urgent"));
        }
        executorService.shutdown();

        // Export tasks to JSON
        String jsonOutput = taskManager.exportTasksToJson();
        if (jsonOutput != null) {
            System.out.println(jsonOutput);
        }
    }
}
