#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_RECORDS 1000
#define RESIZE_THRESHOLD 0.15

typedef struct {
    int value;
} record;

typedef struct {
    int* keys;
    long* offsets;
    record** records;
    void** pointers;
    size_t capacity;
    size_t count;
} data_structures;

data_structures* create_data_structures() {
    data_structures* ds = (data_structures*)malloc(sizeof(data_structures));
    if (!ds) return NULL;

    ds->capacity = 10;
    ds->count = 0;
    ds->keys = (int*)calloc(ds->capacity, sizeof(int));
    ds->offsets = (long*)calloc(ds->capacity, sizeof(long));
    ds->records = (record**)calloc(ds->capacity, sizeof(record*));
    ds->pointers = (void**)calloc(ds->capacity, sizeof(void*));

    if (!ds->keys || !ds->offsets || !ds->records || !ds->pointers) {
        free(ds);
        return NULL;
    }

    for (size_t i = 0; i < ds->capacity; ++i) {
        ds->records[i] = (record*)malloc(sizeof(record));
        if (!ds->records[i]) {
            for (size_t j = 0; j < i; ++j) free(ds->records[j]);
            free(ds->keys);
            free(ds->offsets);
            free(ds->records);
            free(ds->pointers);
            free(ds);
            return NULL;
        }
    }

    return ds;
}

void insert_record(data_structures* ds, int key, long offset, int value) {
    if (ds->count >= MAX_RECORDS) return;

    if (ds->count + 1 > ds->capacity * (1 + RESIZE_THRESHOLD)) {
        size_t new_capacity = (size_t)(ds->capacity * (1 + RESIZE_THRESHOLD));
        int* new_keys = (int*)realloc(ds->keys, new_capacity * sizeof(int));
        long* new_offsets = (long*)realloc(ds->offsets, new_capacity * sizeof(long));
        record** new_records = (record**)realloc(ds->records, new_capacity * sizeof(record*));
        void** new_pointers = (void**)realloc(ds->pointers, new_capacity * sizeof(void*));

        if (!new_keys || !new_offsets || !new_records || !new_pointers) return;

        ds->keys = new_keys;
        ds->offsets = new_offsets;
        ds->records = new_records;
        ds->pointers = new_pointers;
        ds->capacity = new_capacity;
    }

    size_t index = ds->count++;
    ds->keys[index] = key;
    ds->offsets[index] = offset;
    ds->records[index]->value = value;
    ds->pointers[index] = (void*)&ds->keys[index];
}

void cleanup_data_structures(data_structures* ds) {
    for (size_t i = 0; i < ds->count; ++i) free(ds->records[i]);
    free(ds->keys);
    free(ds->offsets);
    free(ds->records);
    free(ds->pointers);
    free(ds);
}

int main() {
    data_structures* ds = create_data_structures();
    if (!ds) return 1;

    insert_record(ds, 10, 20L, 30);
    insert_record(ds, 40, 50L, 60);

    cleanup_data_structures(ds);
    return 0;
}
