#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PROJECTS 800
#define MEMORY_LIMIT 400 * 1024

typedef struct {
    int priority;
    char* status;
    time_t deadline;
} Project;

Project* init_project_list(int num_projects) {
    if (num_projects > MAX_PROJECTS) {
        num_projects = MAX_PROJECTS;
    }

    size_t total_size = num_projects * sizeof(Project);
    if (total_size > MEMORY_LIMIT) {
        fprintf(stderr, "Memory limit exceeded\n");
        return NULL;
    }

    Project* project_list = (Project*)malloc(total_size);
    if (!project_list) {
        perror("Failed to allocate memory for project list");
        return NULL;
    }

    time_t current_time = time(NULL);
    for (int i = 0; i < num_projects; ++i) {
        project_list[i].priority = i + 1;
        project_list[i].status = strdup("Pending");
        project_list[i].deadline = current_time + (i * 86400); // 24 hours apart
    }

    return project_list;
}

void update_project_statuses(Project* project_list, int num_projects) {
    time_t now = time(NULL);
    for (int i = 0; i < num_projects; ++i) {
        if (project_list[i].deadline - now <= 604800) { // 7 days in seconds
            project_list[i].status = strdup("In Progress");
        }
    }
}

void adjust_project_deadlines(Project* project_list, int num_projects) {
    for (int i = 0; i < num_projects; ++i) {
        time_t current_time = time(NULL);
        project_list[i].deadline += rand() % 31 * 86400; // Random days between 0 and 30
    }
}

void sort_project_list(Project* project_list, int num_projects) {
    qsort(project_list, num_projects, sizeof(Project), 
          (int (*)(const void*, const void*))compare_deadlines);
}

int compare_deadlines(const void* a, const void* b) {
    return ((Project*)a)->deadline - ((Project*)b)->deadline;
}

void remove_project(Project** project_list, int* num_projects, int id) {
    for (int i = 0; i < *num_projects; ++i) {
        if (project_list[i]->priority == id) {
            free(project_list[i]->status);
            free(project_list[i]);
            memmove(&project_list[i], &project_list[i + 1], 
                    (*num_projects - i - 1) * sizeof(Project));
            (*num_projects)--;
            break;
        }
    }
}

void serialize_project_list(Project* project_list, int num_projects, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    fwrite(&num_projects, sizeof(int), 1, file);
    for (int i = 0; i < num_projects; ++i) {
        fwrite(&project_list[i].priority, sizeof(int), 1, file);
        size_t status_len = strlen(project_list[i].status) + 1;
        fwrite(&status_len, sizeof(size_t), 1, file);
        fwrite(project_list[i].status, 1, status_len, file);
        fwrite(&project_list[i].deadline, sizeof(time_t), 1, file);
    }

    fclose(file);
}

void deserialize_project_list(Project** project_list, int* num_projects, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }

    fread(num_projects, sizeof(int), 1, file);
    size_t total_size = *num_projects * sizeof(Project);
    *project_list = (Project*)malloc(total_size);
    if (!*project_list) {
        perror("Failed to allocate memory for project list during deserialization");
        fclose(file);
        return;
    }

    for (int i = 0; i < *num_projects; ++i) {
        fread(&(*project_list)[i].priority, sizeof(int), 1, file);
        size_t status_len;
        fread(&status_len, sizeof(size_t), 1, file);
        (*project_list)[i].status = (char*)malloc(status_len);
        if (!(*project_list)[i].status) {
            perror("Failed to allocate memory for project status during deserialization");
            free_project_list(*project_list, *num_projects);
            fclose(file);
            return;
        }
        fread((*project_list)[i].status, 1, status_len, file);
        fread(&(*project_list)[i].deadline, sizeof(time_t), 1, file);
    }

    fclose(file);
}

void free_project_list(Project* project_list, int num_projects) {
    for (int i = 0; i < num_projects; ++i) {
        free(project_list[i].status);
    }
    free(project_list);
}
