import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.SecretKey;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class TextDataProcessor {

    private static final ExecutorService executor = Executors.newFixedThreadPool(10);

    public static String processText(String text, String algorithm) throws Exception {
        if (text == null || text.isEmpty()) {
            return null;
        }

        switch (algorithm) {
            case "MD5":
                return hashWithAlgorithm(text, "MD5");
            case "SHA-256":
                return hashWithAlgorithm(text, "SHA-256");
            case "AES":
                return encryptWithAlgorithm(text, "AES");
            case "Camellia":
                return encryptWithAlgorithm(text, "Camellia");
            default:
                throw new IllegalArgumentException("Unsupported algorithm: " + algorithm);
        }
    }

    private static String hashWithAlgorithm(String text, String algorithm) throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance(algorithm);
        byte[] hashBytes = digest.digest(text.getBytes());
        StringBuilder hexString = new StringBuilder();
        for (byte b : hashBytes) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

    private static String encryptWithAlgorithm(String text, String algorithm) throws Exception {
        KeyGenerator keyGen = KeyGenerator.getInstance(algorithm);
        SecretKey secretKey = keyGen.generateKey();
        Cipher cipher = Cipher.getInstance(algorithm);
        cipher.init(Cipher.ENCRYPT_MODE, secretKey);
        byte[] encryptedBytes = cipher.doFinal(text.getBytes());
        return new String(encryptedBytes);
    }

    public static Future<String> processTextAsync(String text, String algorithm) {
        return executor.submit(() -> processText(text, algorithm));
    }

    public static void shutdown() {
        executor.shutdown();
    }
}
