        return NULL;
    }

    gzFile gzfile = gzdopen(fileno(file), "r");
    if (!gzfile) {
        fclose(file);
        perror("Failed to open gzip file");
        return NULL;
    }

    node* nodes = malloc(buffer_size * sizeof(node));
    if (!nodes) {
        gzclose(gzfile);
        fclose(file);
        perror("Memory allocation failed");
        return NULL;
    }

    size_t count = 0;
    char buffer[chunk_size];
    while (gzgets(gzfile, buffer, chunk_size)) {
        // Process each line here
        // Example: Parse the line and store in nodes[count]
        count++;
        if (count >= buffer_size) {
            // Reallocate memory if needed
            node* new_nodes = realloc(nodes, (buffer_size * 2) * sizeof(node));
            if (!new_nodes) {
                gzclose(gzfile);
                fclose(file);
                free(nodes);
                perror("Memory reallocation failed");
                return NULL;
            }
            nodes = new_nodes;
            buffer_size *= 2;
        }
    }

    gzclose(gzfile);
    fclose(file);

    // Resize the array to fit exactly
    node* resized_nodes = realloc(nodes, count * sizeof(node));
    if (!resized_nodes) {
        free(nodes);
        perror("Memory reallocation failed");
        return NULL;
    }
    nodes = resized_nodes;

    return nodes;
}

