import java.time.LocalDate;
import java.time.ZoneId;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;

public class SubscriptionService {

    private static final ConcurrentHashMap<String, UserCache> userCache = new ConcurrentHashMap<>();
    private static final long CACHE_EXPIRATION_MINUTES = 15;

    public String getSubscriptionStatus(User user) {
        try {
            User cachedUser = userCache.get(user.getId());
            if (cachedUser == null || isCacheExpired(cachedUser)) {
                User fetchedUser = fetchUserFromAPI(user.getId());
                userCache.put(user.getId(), new UserCache(fetchedUser, System.currentTimeMillis()));
            }
            return formatSubscriptionStatus(cachedUser);
        } catch (Exception e) {
            // Handle exceptions gracefully
            return "Error fetching subscription status";
        }
    }

    private User fetchUserFromAPI(String userId) throws Exception {
        // Simulate API call with potential latency and errors
        Thread.sleep(100); // Simulate network delay
        if (userId.equals("error")) throw new RuntimeException("API error");
        return new User(userId, "Subscriber", LocalDate.now().plusDays(30));
    }

    private String formatSubscriptionStatus(User user) {
        switch (user.getRole()) {
            case "DEPRECATED_ROLE":
                return "Redirect to upgrade page";
            case "PREMIUM":
                if (isPremiumAccessValid(user.getAccountExpiry())) {
                    return "Premium User - Access Granted";
                } else {
                    return "Premium User - Access Expired";
                }
            default:
                return "Standard User - Basic Features Only";
        }
    }

    private boolean isCacheExpired(UserCache cachedUser) {
        long currentTime = System.currentTimeMillis();
        return (currentTime - cachedUser.getTimestamp()) > TimeUnit.MINUTES.toMillis(CACHE_EXPIRATION_MINUTES);
    }

    private boolean isPremiumAccessValid(LocalDate accountExpiry) {
        LocalDate now = LocalDate.now(ZoneId.systemDefault());
        return !now.isAfter(accountExpiry);
    }
}

class User {
    private String id;
    private String role;
    private LocalDate accountExpiry;

    public User(String id, String role, LocalDate accountExpiry) {
        this.id = id;
        this.role = role;
        this.accountExpiry = accountExpiry;
    }

    public String getId() {
        return id;
    }

    public String getRole() {
        return role;
    }

    public LocalDate getAccountExpiry() {
        return accountExpiry;
    }
}

class UserCache {
    private User user;
    private long timestamp;

    public UserCache(User user, long timestamp) {
        this.user = user;
        this.timestamp = timestamp;
    }

    public User getUser() {
        return user;
    }

    public long getTimestamp() {
        return timestamp;
    }
}
