typedef struct {
    int id;
    time_t timestamp;
    size_t payload_size;
    unsigned char *payload;
    unsigned short checksum;
} DataPacket;

unsigned short calculate_checksum(DataPacket *packet) {
    // Simple checksum calculation for demonstration
    unsigned short sum = 0;
    for (size_t i = 0; i < packet->payload_size; ++i) {
        sum += packet->payload[i];
    }
    return sum;
}

int insert_packet(DataPacket **array, size_t *size, DataPacket new_packet) {
    // Resize array if necessary
    if (*size == 0 || *array == NULL) {
        *array = (DataPacket *)malloc(sizeof(DataPacket));
        if (*array == NULL) {
            return -1; // Memory allocation failed
        }
        *size = 1;
    } else {
        DataPacket *new_array = (DataPacket *)realloc(*array, (*size + 1) * sizeof(DataPacket));
        if (new_array == NULL) {
            free(*array);
            *array = NULL;
            return -1; // Memory allocation failed
        }
        *array = new_array;
        ++*size;
    }

    // Initialize payload with random bytes
    new_packet.payload = (unsigned char *)malloc(new_packet.payload_size);
    if (new_packet.payload == NULL) {
        free(*array);
        *array = NULL;
        return -1; // Memory allocation failed
    }
    srand(time(NULL));
    for (size_t i = 0; i < new_packet.payload_size; ++i) {
        new_packet.payload[i] = rand() % 256;
    }

    // Calculate and set checksum
    new_packet.checksum = calculate_checksum(&new_packet);

    // Insert packet into array
    (*array)[*size - 1] = new_packet;

    return 0; // Success
}

int update_packet(DataPacket **array, size_t *size, int id, DataPacket new_data) {
    for (size_t i = 0; i < *size; ++i) {
        if ((*array)[i].id == id) {
            free((*array)[i].payload);
            (*array)[i] = new_data;

            // Initialize payload with random bytes
            (*array)[i].payload = (unsigned char *)malloc(new_data.payload_size);
            if ((*array)[i].payload == NULL) {
                return -1; // Memory allocation failed
            }
            srand(time(NULL));
            for (size_t j = 0; j < new_data.payload_size; ++j) {
                (*array)[i].payload[j] = rand() % 256;
            }

            // Calculate and set checksum
            (*array)[i].checksum = calculate_checksum(&(*array)[i]);

            return 0; // Success
        }
    }
    return -1; // Packet not found
}

void free_packets(DataPacket **array, size_t *size) {
    for (size_t i = 0; i < *size; ++i) {
        free((*array)[i].payload);
    }
    free(*array);
    *array = NULL;
    *size = 0;
}
