#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_MEMORY_LIMIT 1024 * 1024 // 1 MB
#define INITIAL_CAPACITY 10

typedef struct Record {
    int value;
    int* key;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

typedef struct MemoryManager {
    Node* freeList;
    int allocatedCount;
    int capacity;
    size_t memoryUsed;
    pthread_mutex_t lock;
} MemoryManager;

MemoryManager* createMemoryManager(int initialCapacity) {
    MemoryManager* manager = (MemoryManager*)malloc(sizeof(MemoryManager));
    if (!manager) return NULL;

    manager->freeList = NULL;
    manager->allocatedCount = 0;
    manager->capacity = initialCapacity;
    manager->memoryUsed = 0;
    pthread_mutex_init(&manager->lock, NULL);

    for (int i = 0; i < initialCapacity; i++) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) {
            freeMemoryManager(manager);
            return NULL;
        }
        newNode->next = manager->freeList;
        manager->freeList = newNode;
    }

    return manager;
}

void destroyMemoryManager(MemoryManager* manager) {
    pthread_mutex_lock(&manager->lock);
    Node* current = manager->freeList;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

Record* allocateRecord(MemoryManager* manager, int keyIndex) {
    pthread_mutex_lock(&manager->lock);
    if (!manager->freeList) {
        // Reallocate memory
        int newCapacity = manager->capacity * 1.15;
        for (int i = 0; i < newCapacity - manager->capacity; i++) {
            Node* newNode = (Node*)malloc(sizeof(Node));
            if (!newNode) {
                pthread_mutex_unlock(&manager->lock);
                return NULL;
            }
            newNode->next = manager->freeList;
            manager->freeList = newNode;
        }
        manager->capacity = newCapacity;
    }

    Node* node = manager->freeList;
    manager->freeList = node->next;
    pthread_mutex_unlock(&manager->lock);

    Record* record = &node->record;
    record->value = 0; // Initialize value
    record->key = (int*)malloc(sizeof(int));
    if (!record->key) {
        free(node);
        return NULL;
    }
    *record->key = keyIndex;

    pthread_mutex_lock(&manager->lock);
    manager->allocatedCount++;
    manager->memoryUsed += sizeof(Record) + sizeof(int);
    pthread_mutex_unlock(&manager->lock);

    return record;
}

void deallocateRecord(MemoryManager* manager, Record* record) {
    pthread_mutex_lock(&manager->lock);
    Node* node = (Node*)record;
    node->next = manager->freeList;
    manager->freeList = node;

    manager->allocatedCount--;
    manager->memoryUsed -= sizeof(Record) + sizeof(int);

    free(record->key);
    record->key = NULL;
    pthread_mutex_unlock(&manager->lock);
}

void* memoryManagerThread(void* arg) {
    MemoryManager* manager = (MemoryManager*)arg;

    // Simulate concurrent allocations and deallocations
    for (int i = 0; i < 100; i++) {
        Record* record = allocateRecord(manager, i);
        if (record) {
            printf("Allocated record with key %d\n", *record->key);
            deallocateRecord(manager, record);
            printf("Deallocated record with key %d\n", *record->key);
        }
    }

    return NULL;
}

int main() {
    MemoryManager* manager = createMemoryManager(INITIAL_CAPACITY);
    if (!manager) {
        fprintf(stderr, "Failed to create memory manager\n");
        return 1;
    }

    pthread_t threads[5];
    for (int i = 0; i < 5; i++) {
        if (pthread_create(&threads[i], NULL, memoryManagerThread, manager) != 0) {
            fprintf(stderr, "Failed to create thread %d\n", i);
            return 1;
        }
    }

    for (int i = 0; i < 5; i++) {
        pthread_join(threads[i], NULL);
    }

    destroyMemoryManager(manager);

    return 0;
}
```

This code provides a basic implementation of a memory manager that can dynamically allocate and deallocate records while managing memory efficiently. It includes thread-safe operations, concurrent access handling, and mechanisms to track memory usage and reallocate memory when necessary. The `main` function demonstrates how to use the memory manager with multiple threads, simulating concurrent allocations and deallocations.

To fully meet the requirements of the task, additional features such as configuration management, logging, memory profiling, garbage collection techniques, and handling edge cases would need to be implemented.']

