#include <string.h>

#define MAX_DATA_ENTRIES 1000

typedef struct {
    int value;
    size_t *index_ptr;
} Data;

typedef struct {
    char *config_name;
    void *data_source;
    void (*log_callback)(const char *);
    void (*cleanup_callback)();
} ConfigStruct;

enum ErrorCode {
    SUCCESS,
    CONFIG_NAME_INVALID,
    DATA_SOURCE_NOT_INITIALIZED,
    LOG_CALLBACK_NULL,
    CLEANUP_CALLBACK_NULL
};

int DataInitializationManager(ConfigStruct *config) {
    if (config->config_name == NULL || strlen(config->config_name) == 0) {
        return CONFIG_NAME_INVALID;
    }
    if (config->data_source == NULL) {
        return DATA_SOURCE_NOT_INITIALIZED;
    }
    if (config->log_callback == NULL || config->cleanup_callback == NULL) {
        return LOG_CALLBACK_NULL;
    }

    size_t *index_array = malloc(MAX_DATA_ENTRIES * sizeof(size_t));
    Data *data_array = malloc(MAX_DATA_ENTRIES * sizeof(Data));

    if (index_array == NULL || data_array == NULL) {
        free(index_array);
        free(data_array);
        config->log_callback("Memory allocation failed");
        return -1;
    }

    size_t current_capacity = MAX_DATA_ENTRIES;
    size_t total_entries = 0;

    // Function to add data with dynamic resizing
    void addData(int value, ConfigStruct *config) {
        if (total_entries >= current_capacity) {
            size_t new_capacity = current_capacity + (current_capacity / 5);
            index_array = realloc(index_array, new_capacity * sizeof(size_t));
            data_array = realloc(data_array, new_capacity * sizeof(Data));
            if (index_array == NULL || data_array == NULL) {
                config->log_callback("Memory reallocation failed");
                return;
            }
            current_capacity = new_capacity;
        }

        index_array[total_entries] = total_entries;
        data_array[total_entries].value = value;
        data_array[total_entries].index_ptr = &index_array[total_entries];
        total_entries++;
    }

    // Example usage
    addData(42, config);

    // Cleanup function
    void cleanup(ConfigStruct *config) {
        free(index_array);
        free(data_array);
        index_array = NULL;
        data_array = NULL;
        config->log_callback("Memory cleaned up");
    }

    return SUCCESS;
}
