#include <time.h>
#include <pthread.h>

#define MAX_UE_INFO 1000
#define EXPIRATION_THRESHOLD 60

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *ue_info_list[MAX_UE_INFO];
    int count;
    pthread_mutex_t mutex;
} UE_Info_Manager;

void initialize_manager(UE_Info_Manager *manager) {
    manager->count = 0;
    pthread_mutex_init(&manager->mutex, NULL);
}

int add_ue_info(UE_Info_Manager *manager, NFAPI_CRC_INDICATION_PDU_T *ue_info) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->count >= MAX_UE_INFO) {
        pthread_mutex_unlock(&manager->mutex);
        return -1; // List is full
    }
    manager->ue_info_list[manager->count++] = ue_info;
    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

void cleanup_manager(UE_Info_Manager *manager) {
    pthread_mutex_lock(&manager->mutex);
    for (int i = 0; i < manager->count; i++) {
        free(manager->ue_info_list[i]);
    }
    manager->count = 0;
    pthread_mutex_unlock(&manager->mutex);
}

void* cleanup_thread(void *arg) {
    UE_Info_Manager *manager = (UE_Info_Manager *)arg;
    time_t current_time;
    while (1) {
        sleep(EXPIRATION_THRESHOLD);
        pthread_mutex_lock(&manager->mutex);
        for (int i = 0; i < manager->count; i++) {
            time(&current_time);
            if (difftime(current_time, manager->ue_info_list[i]->RX_UE_INFORMATION_TAG) > EXPIRATION_THRESHOLD) {
                free(manager->ue_info_list[i]);
                for (int j = i; j < manager->count - 1; j++) {
                    manager->ue_info_list[j] = manager->ue_info_list[j + 1];
                }
                manager->count--;
                i--; // Adjust index after removal
            }
        }
        pthread_mutex_unlock(&manager->mutex);
    }
    return NULL;
}

int main() {
    UE_Info_Manager manager;
    initialize_manager(&manager);

    pthread_t cleanup_tid;
    pthread_create(&cleanup_tid, NULL, cleanup_thread, &manager);

    // Simulate adding UE info
    for (int i = 0; i < MAX_UE_INFO; i++) {
        NFAPI_CRC_INDICATION_PDU_T *ue_info = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        ue_info->RX_UE_INFORMATION_TAG = time(NULL);
        ue_info->RNTI = rand() % 1000;
        ue_info->CRC_INDICATION_REL8_TAG = rand() % 1000;
        ue_info->CRCFLAG = rand() % 1000;
        add_ue_info(&manager, ue_info);
    }

    pthread_join(cleanup_tid, NULL);

    cleanup_manager(&manager);

    return 0;
}
