    if (*sensors == NULL) {
        // Handle memory allocation failure
        return;
    }

    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < num_sensors; i++) {
        (*sensors)[i].measurement = min_temp + (double)(rand() / (RAND_MAX / (max_temp - min_temp)));
        (*sensors)[i].identifier = (char*)malloc(10 * sizeof(char)); // Assuming max identifier length of 9 characters
        if ((*sensors)[i].identifier == NULL) {
            // Handle memory allocation failure for identifier
            free_sensors(*sensors, i);
            return;
        }
        snprintf((*sensors)[i].identifier, 10, "sensor%d", i); // Unique serial number
        (*sensors)[i].status_flag = true; // Initialize status flag
    }
}

void free_sensors(sensor* sensors, int num_sensors) {
    for (int i = 0; i < num_sensors; i++) {
        free(sensors[i].identifier);
    }
    free(sensors);
