EVP_CIPHER_CTX* manage_memory_and_perform_op(const char* option, long n, long m, long max_offset, long max_key, int min_value, int max_value) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    long* offsets = (long*)malloc(n * sizeof(long));
    int* keys = (int*)malloc(n * sizeof(int));
    record* records = (record*)malloc(m * sizeof(record));

    if (!offsets || !keys || !records) {
        EVP_CIPHER_CTX_free(ctx);
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Initialize offsets and keys
    for (long i = 0; i < n; ++i) {
        offsets[i] = i % max_offset;
        keys[i] = rand() % max_key;
        while (keys[i] >= offsets[i]) {
            keys[i] = rand() % max_key;
        }
    }

    // Custom sorting algorithm
    for (long i = 0; i < n - 1; ++i) {
        for (long j = 0; j < n - i - 1; ++j) {
            if (keys[j] > keys[j + 1]) {
                int temp_key = keys[j];
                long temp_offset = offsets[j];
                keys[j] = keys[j + 1];
                offsets[j] = offsets[j + 1];
                keys[j + 1] = temp_key;
                offsets[j + 1] = temp_offset;
            }
        }
    }

    // Populate records with random values
    srand(time(NULL));
    for (long i = 0; i < m; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    // Perform OpenSSL operation based on option
    if (strcmp(option, "encrypt") == 0) {
        EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, (unsigned char*)"0123456789abcdef", (unsigned char*)"0123456789abcdef");
    } else if (strcmp(option, "decrypt") == 0) {
        EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, (unsigned char*)"0123456789abcdef", (unsigned char*)"0123456789abcdef");
    } else {
        EVP_CIPHER_CTX_free(ctx);
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Deallocate memory
    free(offsets);
    free(keys);
    free(records);

    return ctx;
}
