#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_TASKS 1000
#define MAX_MEMORY_LIMIT 1024 * 1024 // 1MB

typedef struct Task {
    char name[256];
    int priority;
    void (*execute)();
} Task;

typedef struct TaskNode {
    Task task;
    struct TaskNode* next;
} TaskNode;

typedef struct TaskManager {
    TaskNode** tasks;
    size_t capacity;
    size_t count;
    size_t memory_used;
    pthread_mutex_t lock;
} TaskManager;

TaskManager* create_task_manager(size_t initial_capacity) {
    TaskManager* manager = (TaskManager*)malloc(sizeof(TaskManager));
    if (!manager) return NULL;

    manager->tasks = (TaskNode**)calloc(initial_capacity, sizeof(TaskNode*));
    if (!manager->tasks) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->memory_used = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_task_manager(TaskManager* manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->capacity; ++i) {
        TaskNode* node = manager->tasks[i];
        while (node) {
            TaskNode* next = node->next;
            free(node);
            node = next;
        }
    }

    free(manager->tasks);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void add_task(TaskManager* manager, const char* name, int priority, void (*execute)()) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity || manager->memory_used + sizeof(TaskNode) > MAX_MEMORY_LIMIT) {
        size_t new_capacity = manager->capacity * 2;
        TaskNode** new_tasks = (TaskNode**)realloc(manager->tasks, new_capacity * sizeof(TaskNode*));
        if (!new_tasks) {
            pthread_mutex_unlock(&manager->lock);
            return;
        }
        memset(new_tasks + manager->capacity, 0, (new_capacity - manager->capacity) * sizeof(TaskNode*));
        manager->tasks = new_tasks;
        manager->capacity = new_capacity;
    }

    TaskNode* node = (TaskNode*)malloc(sizeof(TaskNode));
    if (!node) {
        pthread_mutex_unlock(&manager->lock);
        return;
    }
    strcpy(node->task.name, name);
    node->task.priority = priority;
    node->task.execute = execute;
    node->next = NULL;

    manager->tasks[manager->count++] = node;
    manager->memory_used += sizeof(TaskNode);

    pthread_mutex_unlock(&manager->lock);
}

void execute_tasks(TaskManager* manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        TaskNode* node = manager->tasks[i];
        if (node) {
            node->task.execute();
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void dump_task_manager(TaskManager* manager) {
    pthread_mutex_lock(&manager->lock);

    printf("Task Manager State:\n");
    printf("Capacity: %zu\n", manager->capacity);
    printf("Count: %zu\n", manager->count);
    printf("Memory Used: %zu bytes\n", manager->memory_used);

    for (size_t i = 0; i < manager->count; ++i) {
        TaskNode* node = manager->tasks[i];
        if (node) {
            printf("Task %zu: Name=%s, Priority=%d\n", i, node->task.name, node->task.priority);
        }
    }

    pthread_mutex_unlock(&manager->lock);
}
