#include <pthread.h>

#define MAX_RECORDS 1000000
#define MAX_NFAPI_ENTRIES 500000

typedef struct {
    int value;
} record;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

record* records[MAX_RECORDS];
NFAPI_CRC_INDICATION_PDU_T* nfapi_entries[MAX_NFAPI_ENTRIES];

int keys[MAX_RECORDS];
long offsets[MAX_RECORDS];

pthread_mutex_t record_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t nfapi_lock = PTHREAD_MUTEX_INITIALIZER;

void init_records(int N, int range_start, int range_end) {
    for (int i = 0; i < N; i++) {
        records[i] = malloc(sizeof(record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
        pthread_mutex_lock(&record_lock);
        keys[i] = i;
        offsets[i] = (long)i * sizeof(record);
        pthread_mutex_unlock(&record_lock);

        records[i]->value = rand() % (range_end - range_start + 1) + range_start;
    }
}

void init_nfapi_entries(int N, int threshold) {
    for (int i = 0; i < N; i++) {
        nfapi_entries[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!nfapi_entries[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
        pthread_mutex_lock(&nfapi_lock);
        nfapi_entries[i]->RX_UE_INFORMATION_TAG = rand() % 1000;
        nfapi_entries[i]->RNTI = rand() % 1000;
        nfapi_entries[i]->CRC_INDICATION_REL8_TAG = rand() % 256;
        nfapi_entries[i]->CRCFLAG = (nfapi_entries[i]->CRC_INDICATION_REL8_TAG > threshold) ? 1 : 0;
        pthread_mutex_unlock(&nfapi_lock);
    }
}

void filter_crc_indications(int N, int threshold) {
    for (int i = 0; i < N; i++) {
        if (nfapi_entries[i]->CRCFLAG != 1) {
            free(nfapi_entries[i]);
            nfapi_entries[i] = NULL;
        }
    }
}

void serialize_records_and_entries(int N, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }

    // Serialize records
    fwrite(records, sizeof(record), N, file);

    // Serialize nfapi_entries
    fwrite(nfapi_entries, sizeof(NFAPI_CRC_INDICATION_PDU_T), N, file);

    fclose(file);
}

void free_memory() {
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (records[i]) {
            free(records[i]);
            records[i] = NULL;
        }
    }

    for (int i = 0; i < MAX_NFAPI_ENTRIES; i++) {
        if (nfapi_entries[i]) {
            free(nfapi_entries[i]);
            nfapi_entries[i] = NULL;
        }
    }
}

int main() {
    srand(time(NULL));

    int N = 1000000;
    int range_start = -1000;
    int range_end = 1000;
    int threshold = 128;

    init_records(N, range_start, range_end);
    init_nfapi_entries(N, threshold);
    filter_crc_indications(N, threshold);

    serialize_records_and_entries(N, "data.bin");

    free_memory();

    return 0;
}
