#define MAX_MCS 28

typedef struct {
    int TX_UE_INFORMATION_TAG;
    int CELL_ID;
    int PHY_TRANSPORT_CHANNEL_TAG[MAX_MCS];
} LTE_PHY_TXDU_PDU_T;

typedef struct {
    LTE_PHY_TXDU_PDU_T *data;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} LTE_PHY_TXDU_COLLECTION_T;

LTE_PHY_TXDU_COLLECTION_T* create_collection() {
    LTE_PHY_TXDU_COLLECTION_T *collection = (LTE_PHY_TXDU_COLLECTION_T*)malloc(sizeof(LTE_PHY_TXDU_COLLECTION_T));
    if (!collection) return NULL;
    collection->data = NULL;
    collection->count = 0;
    collection->capacity = 0;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void destroy_collection(LTE_PHY_TXDU_COLLECTION_T *collection) {
    pthread_mutex_lock(&collection->lock);
    free(collection->data);
    collection->data = NULL;
    collection->count = 0;
    collection->capacity = 0;
    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int add_pdu(LTE_PHY_TXDU_COLLECTION_T *collection, LTE_PHY_TXDU_PDU_T pdu) {
    pthread_mutex_lock(&collection->lock);
    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity ? collection->capacity * 2 : 1;
        LTE_PHY_TXDU_PDU_T *new_data = realloc(collection->data, new_capacity * sizeof(LTE_PHY_TXDU_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&collection->lock);
            return -1;
        }
        collection->data = new_data;
        collection->capacity = new_capacity;
    }
    collection->data[collection->count++] = pdu;
    pthread_mutex_unlock(&collection->lock);
    return 0;
}

int serialize_collection(LTE_PHY_TXDU_COLLECTION_T *collection, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    size_t total_size = collection->count * sizeof(LTE_PHY_TXDU_PDU_T);
    fwrite(&total_size, sizeof(size_t), 1, file);

    pthread_mutex_lock(&collection->lock);
    fwrite(collection->data, sizeof(LTE_PHY_TXDU_PDU_T), collection->count, file);
    pthread_mutex_unlock(&collection->lock);

    fclose(file);
    return 0;
}

int deserialize_collection(LTE_PHY_TXDU_COLLECTION_T *collection, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    size_t total_size;
    fread(&total_size, sizeof(size_t), 1, file);

    pthread_mutex_lock(&collection->lock);
    LTE_PHY_TXDU_PDU_T *new_data = realloc(collection->data, total_size);
    if (!new_data) {
        pthread_mutex_unlock(&collection->lock);
        fclose(file);
        return -1;
    }
    collection->data = new_data;
    collection->count = total_size / sizeof(LTE_PHY_TXDU_PDU_T);
    collection->capacity = collection->count;

    fread(collection->data, sizeof(LTE_PHY_TXDU_PDU_T), collection->count, file);
    pthread_mutex_unlock(&collection->lock);

    fclose(file);
    return 0;
}
