#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 10000
#define RESIZE_THRESHOLD 0.15

typedef struct {
    int value;
} record;

typedef struct {
    int* keys;
    long* offsets;
    record** records;
    void** pointers;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} memory_manager;

memory_manager* create_memory_manager(size_t initial_capacity) {
    memory_manager* mm = (memory_manager*)malloc(sizeof(memory_manager));
    if (!mm) return NULL;

    mm->keys = (int*)aligned_alloc(64, initial_capacity * sizeof(int));
    mm->offsets = (long*)aligned_alloc(64, initial_capacity * sizeof(long));
    mm->records = (record**)aligned_alloc(64, initial_capacity * sizeof(record*));
    mm->pointers = (void**)aligned_alloc(64, initial_capacity * sizeof(void*));
    if (!mm->keys || !mm->offsets || !mm->records || !mm->pointers) {
        free(mm);
        return NULL;
    }

    memset(mm->keys, 0, initial_capacity * sizeof(int));
    memset(mm->offsets, 0, initial_capacity * sizeof(long));
    memset(mm->records, 0, initial_capacity * sizeof(record*));
    memset(mm->pointers, 0, initial_capacity * sizeof(void*));

    mm->capacity = initial_capacity;
    mm->size = 0;
    pthread_mutex_init(&mm->lock, NULL);

    return mm;
}

void destroy_memory_manager(memory_manager* mm) {
    if (!mm) return;

    for (size_t i = 0; i < mm->size; ++i) {
        free(mm->records[i]);
    }

    free(mm->keys);
    free(mm->offsets);
    free(mm->records);
    free(mm->pointers);
    pthread_mutex_destroy(&mm->lock);
    free(mm);
}

int insert_record(memory_manager* mm, int key, long offset, int value) {
    if (pthread_mutex_lock(&mm->lock)) return -1;

    if (mm->size >= mm->capacity * (1 + RESIZE_THRESHOLD)) {
        size_t new_capacity = mm->capacity * 2;
        int* new_keys = (int*)aligned_alloc(64, new_capacity * sizeof(int));
        long* new_offsets = (long*)aligned_alloc(64, new_capacity * sizeof(long));
        record** new_records = (record**)aligned_alloc(64, new_capacity * sizeof(record*));
        void** new_pointers = (void**)aligned_alloc(64, new_capacity * sizeof(void*));

        if (!new_keys || !new_offsets || !new_records || !new_pointers) {
            pthread_mutex_unlock(&mm->lock);
            return -1;
        }

        memcpy(new_keys, mm->keys, mm->size * sizeof(int));
        memcpy(new_offsets, mm->offsets, mm->size * sizeof(long));
        for (size_t i = 0; i < mm->size; ++i) {
            new_records[i] = mm->records[i];
            new_pointers[i] = mm->pointers[i];
        }

        free(mm->keys);
        free(mm->offsets);
        free(mm->records);
        free(mm->pointers);

        mm->keys = new_keys;
        mm->offsets = new_offsets;
        mm->records = new_records;
        mm->pointers = new_pointers;
        mm->capacity = new_capacity;
    }

    record* rec = (record*)malloc(sizeof(record));
    if (!rec) {
        pthread_mutex_unlock(&mm->lock);
        return -1;
    }
    rec->value = value;

    mm->keys[mm->size] = key;
    mm->offsets[mm->size] = offset;
    mm->records[mm->size] = rec;
    mm->pointers[mm->size] = (void*)rec;

    ++mm->size;

    pthread_mutex_unlock(&mm->lock);
    return 0;
}

// Additional functions for deletion, resizing, and logging can be implemented here.
