#define INITIAL_CAPACITY 16
#define GROWTH_FACTOR 2

typedef struct Record {
    int key;
    // Add other fields as needed
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

typedef struct RecordCollection {
    Node** nodes;
    size_t capacity;
    size_t size;
} RecordCollection;

RecordCollection* create_record_collection() {
    RecordCollection* collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->nodes = (Node**)calloc(INITIAL_CAPACITY, sizeof(Node*));
    if (!collection->nodes) {
        free(collection);
        return NULL;
    }

    collection->capacity = INITIAL_CAPACITY;
    collection->size = 0;

    return collection;
}

void destroy_record_collection(RecordCollection* collection) {
    for (size_t i = 0; i < collection->size; ++i) {
        Node* node = collection->nodes[i];
        while (node) {
            Node* next = node->next;
            free(node);
            node = next;
        }
    }

    free(collection->nodes);
    free(collection);
}

void resize_record_collection(RecordCollection* collection, size_t new_capacity) {
    Node** new_nodes = (Node**)realloc(collection->nodes, new_capacity * sizeof(Node*));
    if (!new_nodes) return;

    for (size_t i = collection->size; i < new_capacity; ++i) {
        new_nodes[i] = NULL;
    }

    collection->nodes = new_nodes;
    collection->capacity = new_capacity;
}

void insert_record(RecordCollection* collection, int key, Record record, size_t position) {
    if (position > collection->size) return;

    if (collection->size == collection->capacity) {
        resize_record_collection(collection, collection->capacity * GROWTH_FACTOR);
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return;

    new_node->record = record;
    new_node->next = NULL;

    for (size_t i = collection->size; i > position; --i) {
        collection->nodes[i] = collection->nodes[i - 1];
    }

    collection->nodes[position] = new_node;
    ++collection->size;
}

Record* get_record(RecordCollection* collection, int key) {
    for (size_t i = 0; i < collection->size; ++i) {
        Node* node = collection->nodes[i];
        while (node) {
            if (node->record.key == key) {
                return &node->record;
            }
            node = node->next;
        }
    }

    return NULL;
}
