#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_TASKS 1024

typedef struct {
    int tx_power_level;
    int channel_frequency;
    float sinr_db;
    int priority;
    int timeout;
} PHY_TASK_REQUEST;

typedef struct {
    PHY_TASK_REQUEST tasks[MAX_TASKS];
    int count;
    pthread_mutex_t lock;
} TaskList;

void init_task_list(TaskList *list) {
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

int add_task(TaskList *list, PHY_TASK_REQUEST task) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= MAX_TASKS) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }
    list->tasks[list->count++] = task;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void prioritize_tasks(TaskList *list) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->count - 1; i++) {
        for (int j = i + 1; j < list->count; j++) {
            if (list->tasks[i].priority < list->tasks[j].priority) {
                PHY_TASK_REQUEST temp = list->tasks[i];
                list->tasks[i] = list->tasks[j];
                list->tasks[j] = temp;
            }
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void serialize_tasks(TaskList *list, const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) return;

    fprintf(file, "[\n");
    for (int i = 0; i < list->count; i++) {
        fprintf(file, "  {\n");
        fprintf(file, "    \"tx_power_level\": %d,\n", list->tasks[i].tx_power_level);
        fprintf(file, "    \"channel_frequency\": %d,\n", list->tasks[i].channel_frequency);
        fprintf(file, "    \"sinr_db\": %.2f,\n", list->tasks[i].sinr_db);
        fprintf(file, "    \"priority\": %d,\n", list->tasks[i].priority);
        fprintf(file, "    \"timeout\": %d\n", list->tasks[i].timeout);
        if (i < list->count - 1) {
            fprintf(file, "  },\n");
        } else {
            fprintf(file, "  }\n");
        }
    }
    fprintf(file, "]\n");

    fclose(file);
}

void *task_processor(void *arg) {
    TaskList *list = (TaskList *)arg;
    while (1) {
        pthread_mutex_lock(&list->lock);
        if (list->count > 0) {
            PHY_TASK_REQUEST task = list->tasks[--list->count];
            pthread_mutex_unlock(&list->lock);

            // Process the task
            printf("Processing task with priority %d\n", task.priority);
        } else {
            pthread_mutex_unlock(&list->lock);
            break;
        }
    }
    return NULL;
}

int main() {
    TaskList list;
    init_task_list(&list);

    PHY_TASK_REQUEST task1 = {10, 2412, -5.0, 3, 60};
    PHY_TASK_REQUEST task2 = {8, 5180, -7.0, 1, 30};

    add_task(&list, task1);
    add_task(&list, task2);

    prioritize_tasks(&list);

    serialize_tasks(&list, "tasks.json");

    pthread_t thread;
    pthread_create(&thread, NULL, task_processor, &list);
    pthread_join(thread, NULL);

    return 0;
}
