#include <pthread.h>
#include <stdlib.h>
#include <semaphore.h>

typedef struct {
    void (*task_func)(void*);
    void* arg;
} Task;

typedef struct {
    Task** tasks;
    int front, rear, size;
    sem_t task_count;
    pthread_mutex_t lock;
} TaskQueue;

TaskQueue* create_task_queue(int capacity) {
    TaskQueue* queue = (TaskQueue*)malloc(sizeof(TaskQueue));
    queue->tasks = (Task**)malloc(capacity * sizeof(Task*));
    queue->front = queue->rear = -1;
    queue->size = 0;
    sem_init(&queue->task_count, 0, 0);
    pthread_mutex_init(&queue->lock, NULL);
    return queue;
}

void enqueue_task(TaskQueue* queue, Task* task) {
    pthread_mutex_lock(&queue->lock);
    if (queue->rear == -1) {
        queue->front = queue->rear = 0;
    } else if ((queue->rear + 1) % queue->size == queue->front) {
        // Queue is full, handle accordingly
    } else {
        queue->rear = (queue->rear + 1) % queue->size;
    }
    queue->tasks[queue->rear] = task;
    sem_post(&queue->task_count);
    pthread_mutex_unlock(&queue->lock);
}

Task* dequeue_task(TaskQueue* queue) {
    Task* task = NULL;
    sem_wait(&queue->task_count);
    pthread_mutex_lock(&queue->lock);
    if (queue->front != -1) {
        task = queue->tasks[queue->front];
        if (queue->front == queue->rear) {
            queue->front = queue->rear = -1;
        } else {
            queue->front = (queue->front + 1) % queue->size;
        }
    }
    pthread_mutex_unlock(&queue->lock);
    return task;
}

void* worker_thread(void* arg) {
    TaskQueue* queue = (TaskQueue*)arg;
    while (1) {
        Task* task = dequeue_task(queue);
        if (task == NULL) break; // Exit thread
        task->task_func(task->arg);
        free(task); // Free allocated memory for the task
    }
    return NULL;
}

void start_worker_pool(TaskQueue* queue, int num_threads) {
    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; i++) {
        pthread_create(&threads[i], NULL, worker_thread, queue);
    }
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }
}

void resize_worker_pool(TaskQueue* queue, int new_size) {
    // Implement logic to resize the worker pool
}

void health_check_and_recover(TaskQueue* queue) {
    // Implement logic for thread health check and recovery
}
