#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int key;
    long offset;
} Record;

typedef struct HashTable {
    Record** buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_hash_table(size_t initial_capacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->buckets = (Record**)calloc(initial_capacity, sizeof(Record*));
    table->capacity = initial_capacity;
    table->size = 0;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void destroy_hash_table(HashTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        Record* record = table->buckets[i];
        if (record != NULL) {
            free(record);
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

void insert_record(HashTable* table, int key, long offset) {
    pthread_mutex_lock(&table->lock);
    size_t index = key % table->capacity;
    Record* record = table->buckets[index];
    if (record == NULL) {
        record = (Record*)malloc(sizeof(Record));
        record->key = key;
        record->offset = offset;
        table->buckets[index] = record;
        ++table->size;
    } else {
        // Handle collision, e.g., chaining or open addressing
        // For simplicity, we'll just overwrite the existing record
        record->offset = offset;
    }
    pthread_mutex_unlock(&table->lock);
}

void update_record(HashTable* table, int key, long new_offset) {
    pthread_mutex_lock(&table->lock);
    size_t index = key % table->capacity;
    Record* record = table->buckets[index];
    if (record != NULL && record->key == key) {
        record->offset = new_offset;
    }
    pthread_mutex_unlock(&table->lock);
}

long get_record(HashTable* table, int key) {
    pthread_mutex_lock(&table->lock);
    size_t index = key % table->capacity;
    Record* record = table->buckets[index];
    long offset = (record != NULL && record->key == key) ? record->offset : -1;
    pthread_mutex_unlock(&table->lock);
    return offset;
}

int main() {
    HashTable* table = create_hash_table(1024);

    insert_record(table, 1, 100L);
    update_record(table, 1, 200L);
    long offset = get_record(table, 1);
    printf("Offset for key 1: %ld\n", offset);

    destroy_hash_table(table);
    return 0;
}
