    if (!collection) return NULL;

    collection->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!collection->data) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->mutex, NULL);

    return collection;
}

void destroy_collection(NFAPI_CRC_COLLECTION_T *collection) {
    if (collection) {
        pthread_mutex_lock(&collection->mutex);
        free(collection->data);
        pthread_mutex_unlock(&collection->mutex);
        pthread_mutex_destroy(&collection->mutex);
        free(collection);
    }
}

int add_pdu(NFAPI_CRC_COLLECTION_T *collection, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&collection->mutex);

    if (collection->size >= collection->capacity) {
        size_t new_capacity = collection->capacity ? collection->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(collection->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&collection->mutex);
            return -1;
        }
        collection->data = new_data;
        collection->capacity = new_capacity;
    }

    collection->data[collection->size++] = pdu;

    pthread_mutex_unlock(&collection->mutex);
    return 0;
}

