#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

int allocate_and_initialize_arrays(long *offsets, int *keys, record **records, long limit, int range_start, int range_end) {
    if (limit <= 0 || range_start > range_end) {
        return -1; // Invalid input
    }

    srand(time(NULL));
    long total_size = 0;

    for (int i = 0; i < limit; i++) {
        offsets[i] = rand() % (range_end - range_start + 1) + range_start;
        keys[i] = rand() % (range_end - range_start + 1) + range_start;

        record *new_record = malloc(sizeof(record));
        if (!new_record) {
            // Handle memory allocation failure
            for (int j = 0; j < i; j++) {
                free(records[j]);
            }
            return -2;
        }

        new_record->value = rand() % (range_end - range_start + 1) + range_start;
        records[i] = new_record;

        total_size += sizeof(long) + sizeof(int) + sizeof(record);
        if (total_size > limit * (sizeof(long) + sizeof(int))) {
            // Exceeded memory limit
            for (int j = 0; j <= i; j++) {
                free(records[j]);
            }
            return -3;
        }
    }

    return 0; // Success
}

// Example usage:
int main() {
    long *offsets, *keys;
    record **records;
    int limit = 1000;
    int range_start = 0;
    int range_end = 100;

    offsets = malloc(limit * sizeof(long));
    keys = malloc(limit * sizeof(int));
    records = malloc(limit * sizeof(record*));

    if (allocate_and_initialize_arrays(offsets, keys, records, limit, range_start, range_end) == 0) {
        // Use the arrays
        for (int i = 0; i < limit; i++) {
            printf("Offset: %ld, Key: %d, Record Value: %d\n", offsets[i], keys[i], records[i]->value);
            free(records[i]);
        }
    } else {
        // Handle error
    }

    free(offsets);
    free(keys);
    free(records);

    return 0;
}
