sensor_data* initialize_sensor_data(const char* filename, int* num_sensors) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    // Count the number of sensors
    *num_sensors = 0;
    while (fgetc(file) != EOF) {
        if (fgetc(file) == '\n') (*num_sensors)++;
    }
    fseek(file, 0, SEEK_SET);

    sensor_data* data = malloc(*num_sensors * sizeof(sensor_data));
    if (!data) {
        perror("Failed to allocate memory");
        fclose(file);
        return NULL;
    }

    // Initialize sensor data
    for (int i = 0; i < *num_sensors; i++) {
        fscanf(file, "%d %f", &data[i].sensor_id, &data[i].temperature);
        data[i].timestamp = time(NULL);
    }

    fclose(file);
    return data;
}

void free_sensor_data(sensor_data* data) {
    free(data);
}
