            // Free previously allocated resources
            for (int j = 0; j < i; ++j) {
                free(head[j]->data_ptr->str);
                free(head[j]->data_ptr);
                free(head[j]);
            }
            free(head);
            return -1; // Memory allocation failed due to memory limit
        }

        head[i] = new_node;
    }

    // Link the nodes into a list (optional, based on requirements)
    for (int i = 0; i < num_structs - 1; ++i) {
        head[i]->next = head[i + 1];
