#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_NODE_SIZE 1024

typedef struct Node {
    double value;
    char* str;
    struct Node* next;
} Node;

Node* create_node(double value, const char* str) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;

    node->value = value;
    node->str = strdup(str);
    if (!node->str) {
        free(node);
        return NULL;
    }

    node->next = NULL;
    return node;
}

void free_node(Node* node) {
    if (node) {
        free(node->str);
        free(node);
    }
}

Node* populate_list(double min, double max, int budget_kb, int num_processes) {
    srand(time(NULL));
    Node* head = NULL;
    Node** tail = &head;

    for (int i = 0; i < num_processes; ++i) {
        int process_budget_kb = budget_kb / num_processes;
        while (process_budget_kb > 0) {
            double value = min + (double)(rand() % ((max - min) * 100)) / 100.0;
            char str[256];
            snprintf(str, sizeof(str), "Process%d_%d", i, rand() % 100);

            Node* node = create_node(value, str);
            if (!node) {
                // Handle memory allocation failure
                while (head) {
                    Node* temp = head;
                    head = head->next;
                    free_node(temp);
                }
                return NULL;
            }

            *tail = node;
            tail = &node->next;

            process_budget_kb -= sizeof(Node) + strlen(str) + 1; // Approximate memory usage
        }
    }

    return head;
}

void print_list(Node* head) {
    Node* current = head;
    while (current) {
        printf("Value: %f, String: %s\n", current->value, current->str);
        current = current->next;
    }
}

int main() {
    double min = 0.0;
    double max = 100.0;
    int budget_kb = 1024 * 10; // 10 MB
    int num_processes = 5;

    Node* list = populate_list(min, max, budget_kb, num_processes);
    if (list) {
        print_list(list);
        while (list) {
            Node* temp = list;
            list = list->next;
            free_node(temp);
        }
    } else {
        printf("Failed to populate list.\n");
    }

    return 0;
}
```

