Project *project_list[MAX_PROJECTS];
int project_count = 0;

void initialize_project(Project *project, int index) {
    project->priority = index + 1;
    project->status = (char *)malloc(20 * sizeof(char));
    strcpy(project->status, "Pending");
    project->deadline = time(NULL) + 3600; // Example deadline
    project->start_date = time(NULL);
}

void log_project(Project *project) {
    printf("Project %d: Priority=%d, Status=%s, Deadline=%ld, Start Date=%ld\n",
           project->priority, project->priority, project->status, project->deadline, project->start_date);
}

void update_project_status() {
    time_t now = time(NULL);
    for (int i = 0; i < project_count; i++) {
        Project *project = project_list[i];
        double elapsed_time = difftime(now, project->start_date);
        double total_duration = difftime(project->deadline, project->start_date);

        if (elapsed_time > total_duration / 2) {
            strcpy(project->status, "Late");
        } else if (elapsed_time > total_duration) {
            strcpy(project->status, "Completed");
        } else {
            strcpy(project->status, "In Progress");
        }
        log_project(project);
    }
}

void export_projects_to_file(const char *filename) {
    FILE *file = fopen(filename, "w");
    if (file == NULL) {
        perror("Failed to open file for writing");
        return;
    }

    fprintf(file, "Priority,Status,Deadline,Start Date\n");
    for (int i = 0; i < project_count; i++) {
        Project *project = project_list[i];
        fprintf(file, "%d,%s,%ld,%ld\n", project->priority, project->status, project->deadline, project->start_date);
    }

    fclose(file);
}

