    for (int i = 0; i < MAX_PROJECTS; i++) {
        project_list[i] = (Project *)malloc(sizeof(Project));
        initialize_project(project_list[i], i);
    }

    update_project_status();
    export_projects_to_file("projects.csv");

    // Free allocated memory
    for (int i = 0; i < MAX_PROJECTS; i++) {
        free(project_list[i]->status);
        free(project_list[i]);
    }

    return 0;
}
