#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Entry {
    char* key;
    int value;
    struct Entry* next;
} Entry;

typedef struct HashTable {
    Entry** buckets;
    size_t size;
} HashTable;

HashTable* createHashTable(size_t size) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) return NULL;
    table->buckets = (Entry**)calloc(size, sizeof(Entry*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }
    table->size = size;
    return table;
}

void destroyHashTable(HashTable* table) {
    for (size_t i = 0; i < table->size; ++i) {
        Entry* entry = table->buckets[i];
        while (entry) {
            Entry* next = entry->next;
            free(entry->key);
            free(entry);
            entry = next;
        }
    }
    free(table->buckets);
    free(table);
}

unsigned long hashFunction(const char* key, size_t size) {
    unsigned long hash = 5381;
    int c;
    while ((c = *key++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }
    return hash % size;
}

Entry* createEntry(const char* key, int value) {
    Entry* entry = (Entry*)malloc(sizeof(Entry));
    if (!entry) return NULL;
    entry->key = strdup(key);
    if (!entry->key) {
        free(entry);
        return NULL;
    }
    entry->value = value;
    entry->next = NULL;
    return entry;
}

void insertEntry(HashTable* table, const char* key, int value) {
    unsigned long index = hashFunction(key, table->size);
    Entry* newEntry = createEntry(key, value);
    if (!newEntry) return;

    if (table->buckets[index] == NULL) {
        table->buckets[index] = newEntry;
    } else {
        Entry* current = table->buckets[index];
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newEntry;
    }
}

void deleteEntry(HashTable* table, const char* key) {
    unsigned long index = hashFunction(key, table->size);
    Entry* current = table->buckets[index];
    Entry* prev = NULL;

    while (current != NULL) {
        if (strcmp(current->key, key) == 0) {
            if (prev == NULL) {
                table->buckets[index] = current->next;
            } else {
                prev->next = current->next;
            }
            free(current->key);
            free(current);
            return;
        }
        prev = current;
        current = current->next;
    }
}

void traverseHashTable(HashTable* table) {
    for (size_t i = 0; i < table->size; ++i) {
        Entry* entry = table->buckets[i];
        while (entry) {
            printf("Key: %s, Value: %d\n", entry->key, entry->value);
            entry = entry->next;
        }
    }
}

int main() {
    HashTable* table = createHashTable(10);
    insertEntry(table, "one", 1);
    insertEntry(table, "two", 2);
    traverseHashTable(table);
    deleteEntry(table, "one");
    traverseHashTable(table);
    destroyHashTable(table);
    return 0;
}
