typedef struct {
    uint64_t BYTES_SENT;
    uint64_t BYTES_RECEIVED;
    float PACKET_LOSS_RATE;
    uint32_t CONNECTION_DURATION;
    uint32_t CONNECTION_ID;
} NETWORK_CONNECTION_STATS_T;

typedef struct {
    NETWORK_CONNECTION_STATS_T *connections;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} NETWORK_STATS_COLLECTION_T;

void network_stats_collection_init(NETWORK_STATS_COLLECTION_T *collection) {
    collection->connections = NULL;
    collection->count = 0;
    collection->capacity = 0;
    pthread_mutex_init(&collection->lock, NULL);
}

void network_stats_collection_add(NETWORK_STATS_COLLECTION_T *collection, NETWORK_CONNECTION_STATS_T stats) {
    pthread_mutex_lock(&collection->lock);
    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity == 0 ? 1 : collection->capacity * 2;
        NETWORK_CONNECTION_STATS_T *new_connections = realloc(collection->connections, new_capacity * sizeof(NETWORK_CONNECTION_STATS_T));
        if (!new_connections) {
            pthread_mutex_unlock(&collection->lock);
            return; // Handle memory allocation failure
        }
        collection->connections = new_connections;
        collection->capacity = new_capacity;
    }
    collection->connections[collection->count++] = stats;
    pthread_mutex_unlock(&collection->lock);
}

void network_stats_collection_destroy(NETWORK_STATS_COLLECTION_T *collection) {
    pthread_mutex_lock(&collection->lock);
    free(collection->connections);
    collection->connections = NULL;
    collection->count = 0;
    collection->capacity = 0;
    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
}

