#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

void allocate_and_initialize(int max_offset, int max_key, int min_value, int max_value) {
    if (max_offset <= 0 || max_key <= 0 || min_value > max_value) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }

    int n = max_offset;
    int m = max_key;

    // Allocate memory for offsets and keys arrays
    long* offsets = (long*)malloc(n * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets array\n");
        return;
    }

    int* keys = (int*)malloc(m * sizeof(int));
    if (!keys) {
        free(offsets);
        fprintf(stderr, "Memory allocation failed for keys array\n");
        return;
    }

    // Initialize offsets array with unique values from 0 to max_offset - 1
    for (int i = 0; i < n; ++i) {
        offsets[i] = i;
    }

    // Shuffle offsets array to ensure no duplicates and keys[i] < offsets[i]
    srand(time(NULL));
    for (int i = n - 1; i > 0; --i) {
        int j = rand() % (i + 1);
        long temp = offsets[i];
        offsets[i] = offsets[j];
        offsets[j] = temp;
    }

    // Initialize keys array with values from 0 to max_key - 1
    for (int i = 0; i < m; ++i) {
        keys[i] = i;
    }

    // Shuffle keys array to ensure no duplicates and keys[i] < offsets[i]
    for (int i = m - 1; i > 0; --i) {
        int j = rand() % (i + 1);
        int temp = keys[i];
        keys[i] = keys[j];
        keys[j] = temp;
    }

    // Allocate memory for record structures
    record* records = (record*)malloc(n * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        fprintf(stderr, "Memory allocation failed for records array\n");
        return;
    }

    // Populate value fields of record structures with random integers
    srand(time(NULL));
    for (int i = 0; i < n; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    // Deallocate all allocated memory
    free(offsets);
    free(keys);
    free(records);

    printf("Memory allocation and initialization completed successfully\n");
}

int main() {
    int max_offset = 1000;
    int max_key = 500;
    int min_value = -1000;
    int max_value = 1000;

    allocate_and_initialize(max_offset, max_key, min_value, max_value);

    return 0;
}
