#define MAX_RECORDS 1000000
#define SYSTEM_MEMORY_LIMIT (1024 * 1024 * 512) // 512 MB

typedef struct {
    int value;
} Record;

void* manage_memory(void* arg) {
    long* offsets = NULL;
    int* keys = NULL;
    Record* records = NULL;
    int num_records = *(int*)arg;
    long offset_sum = 0;
    int key_sum = 0;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Validate input
    if (num_records <= 0) {
        fprintf(stderr, "Invalid number of records\n");
        return NULL;
    }

    // Allocate memory for offsets and keys arrays
    offsets = (long*)malloc(num_records * sizeof(long));
    keys = (int*)malloc(num_records * sizeof(int));

    if (!offsets || !keys) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize random seed
    srand(time(NULL));

    // Allocate memory for records array and initialize with random values
    records = (Record*)malloc(num_records * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    for (int i = 0; i < num_records; i++) {
        pthread_mutex_lock(&lock);
        records[i].value = rand() % 1000; // Random value between 0 and 999
        offset_sum += offsets[i];
        key_sum += keys[i];
        pthread_mutex_unlock(&lock);

        if (offset_sum + key_sum > SYSTEM_MEMORY_LIMIT) {
            fprintf(stderr, "Memory limit exceeded\n");
            num_records = i;
            break;
        }
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);

    return NULL;
}

int main() {
    int num_records;

    printf("Enter the number of records: ");
    scanf("%d", &num_records);

    pthread_t thread;
    if (pthread_create(&thread, NULL, manage_memory, &num_records) != 0) {
        fprintf(stderr, "Thread creation failed\n");
        return 1;
    }

    pthread_join(thread, NULL);

    return 0;
}
