#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 256

typedef struct {
    char *key;
    float value;
} Entry;

typedef struct {
    Entry **entries;
    size_t capacity;
    size_t size;
} EntryList;

Entry* create_entry(const char *key, float value) {
    Entry *entry = (Entry*)malloc(sizeof(Entry));
    if (!entry) return NULL;
    entry->key = strdup(key);
    entry->value = value;
    return entry;
}

void free_entry(Entry *entry) {
    if (entry) {
        free(entry->key);
        free(entry);
    }
}

EntryList* create_entry_list(size_t initial_capacity) {
    EntryList *list = (EntryList*)malloc(sizeof(EntryList));
    if (!list) return NULL;
    list->entries = (Entry**)calloc(initial_capacity, sizeof(Entry*));
    if (!list->entries) {
        free(list);
        return NULL;
    }
    list->capacity = initial_capacity;
    list->size = 0;
    return list;
}

void free_entry_list(EntryList *list) {
    if (list) {
        for (size_t i = 0; i < list->size; ++i) {
            free_entry(list->entries[i]);
        }
        free(list->entries);
        free(list);
    }
}

int read_entries_from_file(const char *filename, EntryList **list) {
    FILE *file = fopen(filename, "r");
    if (!file) return -1;

    size_t initial_capacity = 10;
    *list = create_entry_list(initial_capacity);
    if (!*list) {
        fclose(file);
        return -1;
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), file)) {
        char *key_end = strchr(line, ':');
        if (!key_end) continue;

        *key_end++ = '\0';
        key_end += strspn(key_end, " \t"); // Skip whitespace after colon

        float value;
        if (sscanf(key_end, "%f", &value) != 1) continue;

        Entry *entry = create_entry(line, value);
        if (!entry) {
            free_entry_list(*list);
            fclose(file);
            return -1;
        }

        if (*list->size == *list->capacity) {
            size_t new_capacity = *list->capacity * 2;
            Entry **new_entries = (Entry**)realloc(*list->entries, new_capacity * sizeof(Entry*));
            if (!new_entries) {
                free_entry(entry);
                free_entry_list(*list);
                fclose(file);
                return -1;
            }
            *list->entries = new_entries;
            *list->capacity = new_capacity;
        }

        (*list)->entries[(*list)->size++] = entry;
    }

    fclose(file);
    return 0;
}

// Example usage
int main() {
    EntryList *entry_list;
    if (read_entries_from_file("data.txt", &entry_list) == 0) {
        for (size_t i = 0; i < entry_list->size; ++i) {
            printf("Key: %s, Value: %.2f\n", entry_list->entries[i]->key, entry_list->entries[i]->value);
        }
        free_entry_list(entry_list);
    } else {
        fprintf(stderr, "Failed to read entries from file.\n");
    }
    return 0;
}
