#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Entry {
    char* key;
    int value;
    struct Entry* next;
    int ref_count;
} Entry;

typedef struct LinkedList {
    Entry* head;
    pthread_mutex_t lock;
} LinkedList;

Entry* create_entry(const char* key, int value) {
    Entry* entry = (Entry*)malloc(sizeof(Entry));
    if (!entry) return NULL;
    entry->key = strdup(key);
    entry->value = value;
    entry->next = NULL;
    entry->ref_count = 1;
    return entry;
}

void free_entry(Entry* entry) {
    if (entry) {
        free(entry->key);
        free(entry);
    }
}

LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    return list;
}

void destroy_linked_list(LinkedList* list) {
    if (list) {
        Entry* current = list->head;
        while (current) {
            Entry* next = current->next;
            free_entry(current);
            current = next;
        }
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

void insert_entry(LinkedList* list, const char* key, int value) {
    pthread_mutex_lock(&list->lock);
    Entry* new_entry = create_entry(key, value);
    if (new_entry) {
        new_entry->next = list->head;
        list->head = new_entry;
    }
    pthread_mutex_unlock(&list->lock);
}

void delete_entry(LinkedList* list, const char* key) {
    pthread_mutex_lock(&list->lock);
    Entry** current = &list->head;
    while (*current) {
        if (strcmp((*current)->key, key) == 0) {
            Entry* temp = *current;
            *current = (*current)->next;
            free_entry(temp);
            break;
        }
        current = &(*current)->next;
    }
    pthread_mutex_unlock(&list->lock);
}

Entry* get_entry(LinkedList* list, const char* key) {
    pthread_mutex_lock(&list->lock);
    Entry* current = list->head;
    while (current) {
        if (strcmp(current->key, key) == 0) {
            current->ref_count++;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return current;
}

void release_entry(Entry* entry) {
    if (entry) {
        pthread_mutex_lock(&entry->ref_count_mutex);
        entry->ref_count--;
        if (entry->ref_count == 0) {
            free_entry(entry);
        }
        pthread_mutex_unlock(&entry->ref_count_mutex);
    }
}

void batch_update(LinkedList* list, const char* key, int new_value) {
    pthread_mutex_lock(&list->lock);
    Entry* current = list->head;
    while (current) {
        if (strcmp(current->key, key) == 0) {
            current->value = new_value;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

int main() {
    LinkedList* list = create_linked_list();
    insert_entry(list, "one", 1);
    insert_entry(list, "two", 2);

    Entry* entry = get_entry(list, "one");
    if (entry) {
        printf("Value of 'one': %d\n", entry->value);
        release_entry(entry);
    }

    delete_entry(list, "one");

    destroy_linked_list(list);
    return 0;
}
