#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_FRAMES 1024

typedef struct {
    uint64_t TIME_STAMP;
    int RB_ID;
    float RX_POWER;
    float SNR;
} PHY_RX_FRAME_STATS;

typedef struct {
    PHY_RX_FRAME_STATS *frames;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} FrameList;

FrameList* create_frame_list() {
    FrameList *list = (FrameList*)malloc(sizeof(FrameList));
    if (!list) return NULL;
    list->frames = (PHY_RX_FRAME_STATS*)calloc(MAX_FRAMES, sizeof(PHY_RX_FRAME_STATS));
    if (!list->frames) {
        free(list);
        return NULL;
    }
    list->count = 0;
    list->capacity = MAX_FRAMES;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_frame_list(FrameList *list) {
    pthread_mutex_lock(&list->lock);
    free(list->frames);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_frame(FrameList *list, PHY_RX_FRAME_STATS frame) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        PHY_RX_FRAME_STATS *new_frames = (PHY_RX_FRAME_STATS*)realloc(list->frames, new_capacity * sizeof(PHY_RX_FRAME_STATS));
        if (!new_frames) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->frames = new_frames;
        list->capacity = new_capacity;
    }
    list->frames[list->count++] = frame;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int filter_frames(FrameList *list, float rx_power_threshold) {
    pthread_mutex_lock(&list->lock);
    size_t filtered_count = 0;
    for (size_t i = 0; i < list->count; ++i) {
        if (list->frames[i].RX_POWER >= rx_power_threshold) {
            list->frames[filtered_count++] = list->frames[i];
        }
    }
    list->count = filtered_count;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int serialize_frames(FrameList *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;
    size_t written = fwrite(list->frames, sizeof(PHY_RX_FRAME_STATS), list->count, file);
    fclose(file);
    return (written == list->count) ? 0 : -1;
}

int deserialize_frames(FrameList *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;
    size_t read_count = fread(list->frames, sizeof(PHY_RX_FRAME_STATS), MAX_FRAMES, file);
    fclose(file);
    pthread_mutex_lock(&list->lock);
    list->count = (read_count < MAX_FRAMES) ? read_count : MAX_FRAMES;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

size_t get_filtered_frame_count(FrameList *list) {
    size_t count = 0;
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->frames[i].RX_POWER >= RX_POWER_THRESHOLD) {
            ++count;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return count;
}
