#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int timeout;
    int retries;
    int buffer_size;
    int num_connections;
} Config;

typedef struct {
    char *buffer;
    size_t size;
} Buffer;

Config* create_config(int timeout, int retries, int buffer_size, int num_connections) {
    if (timeout <= 0 || retries <= 0 || buffer_size <= 0 || num_connections <= 0) {
        fprintf(stderr, "Invalid configuration parameters\n");
        return NULL;
    }

    Config *config = malloc(sizeof(Config));
    if (!config) {
        perror("Failed to allocate memory for config");
        return NULL;
    }

    config->timeout = timeout;
    config->retries = retries;
    config->buffer_size = buffer_size;
    config->num_connections = num_connections;

    return config;
}

Buffer** create_buffer_pool(Config *config, size_t *total_memory) {
    Buffer **pool = malloc(config->num_connections * sizeof(Buffer *));
    if (!pool) {
        perror("Failed to allocate memory for buffer pool");
        return NULL;
    }

    *total_memory = 0;

    for (int i = 0; i < config->num_connections; i++) {
        pool[i] = malloc(sizeof(Buffer));
        if (!pool[i]) {
            perror("Failed to allocate memory for buffer");
            // Free previously allocated buffers
            for (int j = 0; j < i; j++) {
                free(pool[j]);
            }
            free(pool);
            return NULL;
        }

        pool[i]->buffer = malloc(config->buffer_size * sizeof(char));
        if (!pool[i]->buffer) {
            perror("Failed to allocate memory for buffer data");
            // Free previously allocated buffers
            for (int j = 0; j <= i; j++) {
                free(pool[j]->buffer);
                free(pool[j]);
            }
            free(pool);
            return NULL;
        }

        pool[i]->size = config->buffer_size;

        *total_memory += sizeof(Buffer) + config->buffer_size * sizeof(char);

        // Initialize buffer with default message template
        snprintf(pool[i]->buffer, config->buffer_size, "Default Message");
    }

    return pool;
}

void free_config(Config *config, Buffer **pool, size_t total_memory) {
    for (int i = 0; i < config->num_connections; i++) {
        free(pool[i]->buffer);
        free(pool[i]);
    }
    free(pool);
    free(config);
}

int main() {
    Config *config = create_config(5, 3, 1024, 100);
    if (!config) {
        return EXIT_FAILURE;
    }

    size_t total_memory;
    Buffer **pool = create_buffer_pool(config, &total_memory);
    if (!pool) {
        free_config(config, NULL, 0);
        return EXIT_FAILURE;
    }

    // Use the configuration and buffer pool...

    free_config(config, pool, total_memory);

    return EXIT_SUCCESS;
}
