#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INITIAL_CAPACITY 10
#define GROWTH_FACTOR 1.1
#define MAX_RECORDS 1000

typedef struct {
    int value;
    int* key;
    float* average;
} Record;

Record* records = NULL;
int record_count = 0;
int capacity = 0;

void init_records() {
    capacity = INITIAL_CAPACITY;
    records = (Record*)aligned_alloc(64, capacity * sizeof(Record));
}

void add_record(int value, int key_index, float average) {
    if (record_count >= capacity) {
        capacity = (int)(capacity * GROWTH_FACTOR);
        records = (Record*)realloc(records, capacity * sizeof(Record));
    }
    records[record_count].value = value;
    records[record_count].key = &keys[key_index];
    records[record_count].average = &averages[key_index];
    record_count++;
}

void find_largest_integer() {
    int largest = records[0].value;
    for (int i = 1; i < record_count; i++) {
        if (records[i].value > largest) {
            largest = records[i].value;
        }
    }
    printf("Largest integer: %d\n", largest);
}

float calculate_average() {
    float sum = 0;
    for (int i = 0; i < record_count; i++) {
        sum += records[i].value;
    }
    return sum / record_count;
}

void cleanup_records() {
    free(records);
    records = NULL;
    capacity = 0;
    record_count = 0;
}
