#define MAX_SESSIONS 1000
#define SESSION_EXPIRY_SECONDS 3600
#define DEVICE_VALIDATION_CACHE_SIZE 100

typedef struct Device {
    char ip[16];
    time_t last_active;
    char hardware_id[256];
} Device;

typedef struct Session {
    int session_id;
    time_t timestamp;
    Device* devices;
    int device_count;
    int max_devices;
} Session;

Session** sessions = NULL;
int session_count = 0;
int max_sessions = MAX_SESSIONS;
Device** device_validation_cache = NULL;
int cache_size = DEVICE_VALIDATION_CACHE_SIZE;

void initialize_session_list() {
    sessions = (Session**)malloc(max_sessions * sizeof(Session*));
    for (int i = 0; i < max_sessions; i++) {
        sessions[i] = NULL;
    }
    device_validation_cache = (Device**)malloc(cache_size * sizeof(Device*));
}

void set_timestamps() {
    time_t current_time = time(NULL);
    for (int i = 0; i < session_count; i++) {
        sessions[i]->timestamp = current_time;
    }
}

void resize_session_list(int new_capacity) {
    if (new_capacity > max_sessions) {
        Session** new_sessions = (Session**)realloc(sessions, new_capacity * sizeof(Session*));
        for (int i = max_sessions; i < new_capacity; i++) {
            new_sessions[i] = NULL;
        }
        sessions = new_sessions;
        max_sessions = new_capacity;
    }
}

void add_session(int session_id) {
    if (session_count >= max_sessions) {
        resize_session_list(max_sessions * 1.2);
    }
    Session* new_session = (Session*)malloc(sizeof(Session));
    new_session->session_id = session_id;
    new_session->timestamp = time(NULL);
    new_session->devices = NULL;
    new_session->device_count = 0;
    new_session->max_devices = 0;
    sessions[session_count++] = new_session;
}

void add_device(int session_id, Device* device) {
    for (int i = 0; i < session_count; i++) {
        if (sessions[i]->session_id == session_id) {
            if (sessions[i]->device_count >= sessions[i]->max_devices) {
                int new_capacity = sessions[i]->max_devices * 1.2;
                Device* new_devices = (Device*)realloc(sessions[i]->devices, new_capacity * sizeof(Device));
                sessions[i]->devices = new_devices;
                sessions[i]->max_devices = new_capacity;
            }
            sessions[i]->devices[sessions[i]->device_count++] = *device;
            break;
        }
    }
}

void purge_expired_sessions() {
    time_t current_time = time(NULL);
    for (int i = 0; i < session_count; i++) {
        if (current_time - sessions[i]->timestamp > SESSION_EXPIRY_SECONDS) {
            free(sessions[i]->devices);
            free(sessions[i]);
            sessions[i] = NULL;
            // Shift remaining sessions down
            for (int j = i + 1; j < session_count; j++) {
                sessions[j - 1] = sessions[j];
            }
            session_count--;
            i--; // Adjust index after shift
        }
    }
}

void validate_device(Device* device) {
    // Simulate asynchronous validation
    static int next_id = 0;
    device->hardware_id[next_id % cache_size] = 'A' + (next_id++ % 26);
}

void log_resource_usage() {
    time_t current_time = time(NULL);
    if (current_time % 3600 == 0) { // Log every hour
        printf("Total sessions: %d\n", session_count);
        int total_devices = 0;
        for (int i = 0; i < session_count; i++) {
            total_devices += sessions[i]->device_count;
        }
        if (session_count > 0) {
            printf("Average devices per session: %.2f\n", (double)total_devices / session_count);
        } else {
            printf("No active sessions.\n");
        }
    }
}

void cleanup() {
    for (int i = 0; i < session_count; i++) {
        free(sessions[i]->devices);
        free(sessions[i]);
    }
    free(sessions);
    free(device_validation_cache);
}
