// Define a structure for user records
struct UserRecord {
    int id;
    std::string key;
};

class UserDataManager {
public:
    UserDataManager(size_t initialCapacity, size_t memoryThreshold)
        : capacity(initialCapacity), memoryThreshold(memoryThreshold), totalRecords(0) {}

    void addUser(const UserRecord& record) {
        boost::lock_guard<boost::mutex> lock(mutex);
        if (totalRecords >= capacity * 0.8) {
            resize(capacity * 1.2);
        }
        userRecords.push_back(record);
        ++totalRecords;
    }

    void removeUser(int id) {
        boost::lock_guard<boost::mutex> lock(mutex);
        auto it = std::remove_if(userRecords.begin(), userRecords.end(),
                                 [id](const UserRecord& record) { return record.id == id; });
        if (it != userRecords.end()) {
            userRecords.erase(it, userRecords.end());
            --totalRecords;
        }
    }

private:
    void resize(size_t newCapacity) {
        capacity = newCapacity;
        // Implement resizing logic here
    }

    size_t capacity;
    size_t memoryThreshold;
    size_t totalRecords;
    std::vector<UserRecord> userRecords;
    boost::mutex mutex;
};

int main() {
    UserDataManager manager(100, 1024 * 1024); // Initial capacity of 100 records and a memory threshold of 1MB

    // Simulate adding users
    for (int i = 0; i < 150; ++i) {
        UserRecord record{i, "key" + std::to_string(i)};
        manager.addUser(record);
    }

    // Simulate removing users
    for (int i = 0; i < 50; ++i) {
        manager.removeUser(i);
    }

    return 0;
}
