import java.io.File;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

public class FileTransferUtility {
    private ExecutorService executorService;
    private BlockingQueue<TransferTask> taskQueue;
    private AtomicInteger initiatedTasks = new AtomicInteger(0);
    private AtomicInteger completedTasks = new AtomicInteger(0);

    public FileTransferUtility(int initialCapacity) {
        this.taskQueue = new ArrayBlockingQueue<>(initialCapacity);
        this.executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        Runtime.getRuntime().addShutdownHook(new Thread(this::shutdown));
    }

    public void addTask(TransferTask task) {
        initiatedTasks.incrementAndGet();
        taskQueue.add(task);
    }

    private void processTasks() {
        while (true) {
            try {
                TransferTask task = taskQueue.take();
                executorService.submit(() -> {
                    try {
                        if (task.isUpload()) {
                            // Implement SFTP upload logic
                        } else {
                            // Implement SFTP download logic
                        }
                        completedTasks.incrementAndGet();
                    } catch (Exception e) {
                        handleTransferFailure(task, e);
                    }
                });
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }
    }

    private void handleTransferFailure(TransferTask task, Exception e) {
        // Implement retry logic with exponential backoff
        if (task.getRetryCount() < 3) {
            task.incrementRetryCount();
            try {
                Thread.sleep((long) Math.pow(2, task.getRetryCount()) * 1000);
                addTask(task);
            } catch (InterruptedException ie) {
                Thread.currentThread().interrupt();
            }
        } else {
            // Log failure and handle cleanup
        }
    }

    private void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
        // Perform final resource cleanup
    }

    public int getInitiatedTasks() {
        return initiatedTasks.get();
    }

    public int getCompletedTasks() {
        return completedTasks.get();
    }

    public static void main(String[] args) {
        FileTransferUtility utility = new FileTransferUtility(10);
        // Add tasks to the utility
        utility.processTasks();
    }
}

class TransferTask {
    private String filePath;
    private String remoteDir;
    private boolean isUpload;
    private int retryCount;

    public TransferTask(String filePath, String remoteDir, boolean isUpload) {
        this.filePath = filePath;
        this.remoteDir = remoteDir;
        this.isUpload = isUpload;
        this.retryCount = 0;
    }

    // Getters and setters for task attributes

    public boolean isUpload() {
        return isUpload;
    }

    public int getRetryCount() {
        return retryCount;
    }

    public void incrementRetryCount() {
        retryCount++;
    }
}
