#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_IDENTIFIER_LENGTH 100
#define INITIAL_CAPACITY 10
#define RESIZE_FACTOR 0.2

typedef struct {
    double value;
    char identifier[MAX_IDENTIFIER_LENGTH];
} DataStruct;

DataStruct* allocate_structs(int *capacity) {
    *capacity = INITIAL_CAPACITY;
    return (DataStruct*)aligned_alloc(64, (*capacity) * sizeof(DataStruct));
}

void read_and_initialize_structs(DataStruct **array, int *size, int *capacity) {
    double num;
    char identifier[MAX_IDENTIFIER_LENGTH];
    while (scanf("%lf %s", &num, identifier) == 2 && *size < *capacity) {
        if (*size >= *capacity - 1) {
            *capacity += (int)(*capacity * RESIZE_FACTOR);
            *array = realloc(*array, (*capacity) * sizeof(DataStruct));
        }
        (*array)[*size].value = num;
        strncpy((*array)[*size].identifier, identifier, MAX_IDENTIFIER_LENGTH);
        (*size)++;
    }
}

void calculate_and_print_average(DataStruct *array, int size) {
    double sum = 0.0;
    for (int i = 0; i < size; i++) {
        sum += array[i].value;
    }
    printf("Average: %.2f\n", sum / size);
}

void cleanup_structs(DataStruct **array, int *size, int *capacity) {
    free(*array);
    *array = NULL;
    *size = 0;
    *capacity = 0;
}

int main() {
    DataStruct *data_array = NULL;
    int size = 0, capacity = 0;

    data_array = allocate_structs(&capacity);
    read_and_initialize_structs(&data_array, &size, &capacity);

    calculate_and_print_average(data_array, size);

    cleanup_structs(&data_array, &size, &capacity);

    return 0;
}
