    int status;
    // Other interface-specific fields
} NetworkInterface;

typedef struct {
    int priority;
    int timeout;
    // Other policy-specific fields
} NetworkPolicy;

typedef struct {
    NetworkPolicy policies[POLICY_CACHE_SIZE];
    int count;
} PolicyCache;

NetworkInterface interfaces[MAX_INTERFACES];
int interface_count = 0;
PolicyCache policy_cache;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_interface(NetworkInterface *interface, int id) {
    interface->id = id;
    interface->status = 0; // Assuming 0 means down
}

void update_interface_status(int id, int status) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < interface_count; i++) {
        if (interfaces[i].id == id) {
            interfaces[i].status = status;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void add_policy_to_cache(NetworkPolicy policy) {
    pthread_mutex_lock(&mutex);
    if (policy_cache.count < POLICY_CACHE_SIZE) {
        policy_cache.policies[policy_cache.count++] = policy;
    } else {
        // Handle cache overflow, e.g., evict least recently used policy
    }
    pthread_mutex_unlock(&mutex);
}

void resize_interfaces(int new_capacity) {
    pthread_mutex_lock(&mutex);
    if (new_capacity > MAX_INTERFACES) {
        printf("Cannot exceed maximum capacity\n");
        return;
    }
    NetworkInterface *new_interfaces = realloc(interfaces, new_capacity * sizeof(NetworkInterface));
    if (new_interfaces == NULL) {
        printf("Memory allocation failed\n");
        return;
    }
    interfaces = new_interfaces;
    pthread_mutex_unlock(&mutex);
}

void add_interface(int id) {
    pthread_mutex_lock(&mutex);
    if (interface_count >= MAX_INTERFACES) {
        resize_interfaces(interface_count * 1.2); // Increase capacity by 20%
    }
    initialize_interface(&interfaces[interface_count++], id);
    pthread_mutex_unlock(&mutex);
}

void log_network_stats() {
    pthread_mutex_lock(&mutex);
    printf("Total interfaces: %d\n", interface_count);
    if (interface_count > 0) {
        printf("Average policies per interface: %.2f\n", policy_cache.count / (float)interface_count);
    }
    pthread_mutex_unlock(&mutex);
}

int main() {
    // Example usage
    add_interface(1);
    update_interface_status(1, 1); // Assuming 1 means up

    NetworkPolicy policy = {10, 60};
    add_policy_to_cache(policy);

    log_network_stats();

    return 0;
}
