#include <iostream>
#include <forward_list>
#include <string>
#include <fstream>

bool insertAfterOrAppend(std::forward_list<std::string>& list, const std::string& target, const std::string& toInsert, int maxSearchIterations, int maxInsertions) {
    if (maxSearchIterations <= 0 || maxInsertions <= 0) return false;

    auto it = list.begin();
    for (int i = 0; i < maxSearchIterations && it != list.end(); ++i, ++it) {
        if (*it == target) {
            if (maxInsertions > 0) {
                --maxInsertions;
                list.insert_after(it, toInsert);
            }
            return true;
        }
    }

    if (maxInsertions > 0) {
        --maxInsertions;
        list.push_back(toInsert);
    }

    return false;
}

int main() {
    std::forward_list<std::string> myList = {"apple", "banana", "cherry"};
    bool result = insertAfterOrAppend(myList, "banana", "orange", 2, 1);

    if (result) {
        std::cout << "Insertion successful." << std::endl;
    } else {
        std::cout << "Insertion failed or reached maximum iterations/insertions." << std::endl;
    }

    for (const auto& item : myList) {
        std::cout << item << " ";
    }
