DynamicNetworkPDUArray* initDynamicNetworkPDUArray(size_t initialCapacity, size_t keySize, long min_value, long max_value) {
    DynamicNetworkPDUArray* array = (DynamicNetworkPDUArray*)malloc(sizeof(DynamicNetworkPDUArray));
    if (!array) return NULL;

    array->Offset = (long*)calloc(keySize, sizeof(long));
    if (!array->Offset) {
        free(array);
        return NULL;
    }

    array->Key = (int*)calloc(keySize, sizeof(int));
    if (!array->Key) {
        free(array->Offset);
        free(array);
        return NULL;
    }

    for (size_t i = 0; i < keySize; ++i) {
        array->Offset[i] = i * 100L; // Example sequence
        array->Key[i] = i;
    }

    array->Record = (Record**)malloc(keySize * sizeof(Record*));
    if (!array->Record) {
        free(array->Offset);
        free(array->Key);
        free(array);
        return NULL;
    }

    for (size_t i = 0; i < keySize; ++i) {
        array->Record[i] = (Record*)malloc(sizeof(Record));
        if (!array->Record[i]) {
            for (size_t j = 0; j < i; ++j) free(array->Record[j]);
            free(array->Offset);
            free(array->Key);
            free(array);
            return NULL;
        }
        array->Record[i]->value = rand() % (max_value - min_value + 1) + min_value;
    }

    if (sem_init(&array->semaphore, 0, initialCapacity) != 0) {
        for (size_t i = 0; i < keySize; ++i) free(array->Record[i]);
        free(array->Offset);
        free(array->Key);
        free(array);
        return NULL;
    }

    return array;
}

void cleanupDynamicNetworkPDUArray(DynamicNetworkPDUArray* array, size_t keySize) {
    if (array) {
        for (size_t i = 0; i < keySize; ++i) {
            if (array->Record[i]) free(array->Record[i]);
        }
        free(array->Offset);
        free(array->Key);
        free(array->Record);
        sem_destroy(&array->semaphore);
        free(array);
    }
}
