#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct record {
    int value;
    long *offset;
} Record;

typedef struct node {
    Record *rec;
    struct node *next;
} Node;

Node* head = NULL;

void log_memory_usage(size_t used, size_t max) {
    printf("Memory Usage: %zu / %zu\n", used, max);
}

Record* create_record(int value, long offset) {
    Record *new_rec = (Record*)malloc(sizeof(Record));
    if (!new_rec) {
        fprintf(stderr, "Failed to allocate memory for record.\n");
        exit(EXIT_FAILURE);
    }
    new_rec->value = value;
    new_rec->offset = (long*)malloc(sizeof(long));
    if (!new_rec->offset) {
        free(new_rec);
        fprintf(stderr, "Failed to allocate memory for offset.\n");
        exit(EXIT_FAILURE);
    }
    *new_rec->offset = offset;
    return new_rec;
}

void add_record(int value, long offset) {
    Node *new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Failed to allocate memory for node.\n");
        exit(EXIT_FAILURE);
    }
    new_node->rec = create_record(value, offset);
    new_node->next = head;
    head = new_node;
}

long get_offset(int index) {
    Node *current = head;
    int count = 0;
    while (current != NULL) {
        if (count == index) {
            return *(current->rec->offset);
        }
        current = current->next;
        count++;
    }
    fprintf(stderr, "Index out of bounds.\n");
    exit(EXIT_FAILURE);
}

void cleanup() {
    Node *current = head;
    while (current != NULL) {
        Node *temp = current;
        free(temp->rec->offset);
        free(temp->rec);
        free(temp);
        current = temp->next;
    }
    head = NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 5) {
        fprintf(stderr, "Usage: %s size min max maxMemoryUsage\n", argv[0]);
        return EXIT_FAILURE;
    }

    int size = atoi(argv[1]);
    int min = atoi(argv[2]);
    int max = atoi(argv[3]);
    size_t maxMemoryUsage = atol(argv[4]);

    srand(time(NULL));

    for (int i = 0; i < size; i++) {
        int value = rand() % (max - min + 1) + min;
        long offset = rand();
        add_record(value, offset);
    }

    log_memory_usage(size * sizeof(Record) + size * sizeof(long), maxMemoryUsage);

    for (int i = 0; i < size; i++) {
        printf("Offset at index %d: %ld\n", i, get_offset(i));
    }

    cleanup();

    return EXIT_SUCCESS;
}
