            list[i]->CRCFLAG = rand() % 2; // Randomly update CRCFLAG
        }
    }
}

void* periodic_cleanup(void* arg) {
    while (1) {
        cleanup_unused_structures();
        sleep(60); // Cleanup every minute
    }
    return NULL;
}

int main() {
