    if (pthread_create(&thread_id, NULL, create_structure, NULL) != 0) {
        perror("Failed to create thread");
        return 1;
    }

    if (pthread_create(&cleanup_thread_id, NULL, periodic_cleanup, NULL) != 0) {
        perror("Failed to create cleanup thread");
