void insertAfterFirstOccurrence(std::forward_list<std::string>& fl, const std::string& target, const std::string& toInsert) {
    auto it = fl.begin();
    while (it != fl.end()) {
        if (*it == target) {
            ++it;
            fl.insert_after(it, toInsert);
            return;
        }
        ++it;
    }
}

int main() {
    std::forward_list<std::string> fl = {"apple", "banana", "cherry"};
    insertAfterFirstOccurrence(fl, "banana", "grape");

    for (const auto& str : fl) {
        std::cout << str << " ";
    }
    return 0;
}
