#include <string.h>
#include <time.h>

typedef struct {
    double value;
    char* str;
    time_t lastAccessed;
} dataEntry;

typedef struct {
    dataEntry** entries;
    size_t capacity;
    size_t count;
    size_t maxLength;
    size_t maxAge;
    size_t maxMemoryUsage;
    size_t currentMemoryUsage;
} dynamicCollection;

dynamicCollection* createDynamicCollection(size_t initialCapacity, size_t maxLength, size_t maxAge, size_t maxMemoryUsage) {
    dynamicCollection* collection = (dynamicCollection*)malloc(sizeof(dynamicCollection));
    if (!collection) {
        fprintf(stderr, "Failed to allocate memory for dynamic collection.\n");
        exit(EXIT_FAILURE);
    }
    collection->entries = (dataEntry**)calloc(initialCapacity, sizeof(dataEntry*));
    if (!collection->entries) {
        fprintf(stderr, "Failed to allocate memory for entries array.\n");
        free(collection);
        exit(EXIT_FAILURE);
    }
    collection->capacity = initialCapacity;
    collection->count = 0;
    collection->maxLength = maxLength;
    collection->maxAge = maxAge;
    collection->maxMemoryUsage = maxMemoryUsage;
    collection->currentMemoryUsage = 0;
    return collection;
}

void destroyDynamicCollection(dynamicCollection* collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->entries[i]->str);
        free(collection->entries[i]);
    }
    free(collection->entries);
    free(collection);
}

dataEntry* getEntry(dynamicCollection* collection, size_t index) {
    if (index >= collection->count) {
        fprintf(stderr, "Index out of bounds.\n");
        return NULL;
    }
    return collection->entries[index];
}

void backgroundCleanup(dynamicCollection* collection) {
    time_t now = time(NULL);
    for (size_t i = 0; i < collection->count; ++i) {
        if (difftime(now, collection->entries[i]->lastAccessed) > collection->maxAge) {
            free(collection->entries[i]->str);
            free(collection->entries[i]);
            memmove(&collection->entries[i], &collection->entries[i + 1], (collection->count - i - 1) * sizeof(dataEntry*));
            --collection->count;
            --i; // Adjust index after removal
        }
    }
}

void addEntry(dynamicCollection* collection, double value, const char* str) {
    if (collection->currentMemoryUsage + strlen(str) > collection->maxMemoryUsage) {
        fprintf(stderr, "Maximum memory usage exceeded.\n");
        return;
    }
    dataEntry* entry = (dataEntry*)malloc(sizeof(dataEntry));
    if (!entry) {
        fprintf(stderr, "Failed to allocate memory for new entry.\n");
        return;
    }
    entry->value = value;
    entry->str = (char*)malloc(collection->maxLength * sizeof(char));
    if (!entry->str) {
        fprintf(stderr, "Failed to allocate memory for string in entry.\n");
        free(entry);
        return;
    }
    strncpy(entry->str, str, collection->maxLength - 1);
    entry->str[collection->maxLength - 1] = '\0';
    entry->lastAccessed = time(NULL);
    collection->entries[collection->count++] = entry;
    collection->currentMemoryUsage += strlen(str);
}

int main() {
    dynamicCollection* collection = createDynamicCollection(10, 256, 3600, 1024 * 1024); // Example parameters
    addEntry(collection, 3.14, "Pi");
    addEntry(collection, 2.718, "e");
    backgroundCleanup(collection);
    destroyDynamicCollection(collection);
    return 0;
}
