#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 10

typedef struct {
    int key;
    time_t timestamp;
    time_t last_access_time;
    int value;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} Dataset;

Dataset* create_dataset() {
    Dataset* dataset = (Dataset*)malloc(sizeof(Dataset));
    dataset->records = (Record*)calloc(INITIAL_CAPACITY, sizeof(Record));
    dataset->capacity = INITIAL_CAPACITY;
    dataset->size = 0;
    pthread_mutex_init(&dataset->lock, NULL);
    return dataset;
}

void destroy_dataset(Dataset* dataset) {
    free(dataset->records);
    pthread_mutex_destroy(&dataset->lock);
    free(dataset);
}

int add_record(Dataset* dataset, int key, int value) {
    pthread_mutex_lock(&dataset->lock);
    if (dataset->size >= dataset->capacity) {
        size_t new_capacity = dataset->capacity * 2;
        Record* new_records = (Record*)realloc(dataset->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&dataset->lock);
            return -1; // Memory allocation failed
        }
        dataset->records = new_records;
        dataset->capacity = new_capacity;
    }
    Record* record = &dataset->records[dataset->size++];
    record->key = key;
    record->timestamp = time(NULL);
    record->last_access_time = record->timestamp;
    record->value = value;
    pthread_mutex_unlock(&dataset->lock);
    return 0; // Success
}

int update_record(Dataset* dataset, int key, int new_value) {
    pthread_mutex_lock(&dataset->lock);
    for (size_t i = 0; i < dataset->size; ++i) {
        if (dataset->records[i].key == key) {
            dataset->records[i].value = new_value;
            dataset->records[i].last_access_time = time(NULL);
            pthread_mutex_unlock(&dataset->lock);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&dataset->lock);
    return -1; // Record not found
}

int get_record(Dataset* dataset, int key, Record* result) {
    pthread_mutex_lock(&dataset->lock);
    for (size_t i = 0; i < dataset->size; ++i) {
        if (dataset->records[i].key == key) {
            *result = dataset->records[i];
            dataset->records[i].last_access_time = time(NULL);
            pthread_mutex_unlock(&dataset->lock);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&dataset->lock);
    return -1; // Record not found
}

void cleanup_unused_records(Dataset* dataset, time_t threshold) {
    pthread_mutex_lock(&dataset->lock);
    size_t new_size = 0;
    for (size_t i = 0; i < dataset->size; ++i) {
        if (time(NULL) - dataset->records[i].last_access_time > threshold) {
            continue; // Skip unused records
        }
        dataset->records[new_size++] = dataset->records[i];
    }
    dataset->size = new_size;
    pthread_mutex_unlock(&dataset->lock);
}
