char* append_slash_if_within_limit(const char *input, size_t max_size) {
    if (!input || max_size <= 0) {
        return NULL;
    }

    size_t input_len = strlen(input);
    if (input_len >= max_size) {
        return NULL;
    }

    char *new_string = malloc((input_len + 2) * sizeof(char));
    if (!new_string) {
        return NULL;
    }

    strcpy(new_string, input);
    new_string[input_len] = '/';
    new_string[input_len + 1] = '\0';

