        std::unique_lock<std::mutex> lock(mutex);
        condition.wait(lock, [this] { return !isUpdating; });
        isUpdating = true;
        // Validate and apply configuration parameters
        Config newConfig;
        for (const auto& param : configParams) {
            if (param.first == "logLevel") {
                newConfig.logLevel = std::stoi(param.second);
            } else if (param.first == "logPath") {
                newConfig.logPath = param.second;
            }
            // Validate other parameters
        }
        currentConfig = newConfig;
        isUpdating = false;
        condition.notify_all();
    }

    Config getConfig() const {
        std::unique_lock<std::mutex> lock(mutex);
        condition.wait(lock, [this] { return !isUpdating; });
        return currentConfig;
    }

private:
    std::string serviceUrl;
    int maxResourceLimit;
    Config currentConfig;
    bool isUpdating = false;
    mutable std::mutex mutex;
    std::condition_variable condition;
};

int main() {
    ConfigManager configManager("http://configservice.com", 1024 * 1024 * 10); // 10 MB limit
    std::unordered_map<std::string, std::string> configParams = {{"logLevel", "3"}, {"logPath", "/var/log"}};
    configManager.updateConfig(configParams);
    Config currentConfig = configManager.getConfig();
    std::cout << "Current Log Level: " << currentConfig.logLevel << ", Log Path: " << currentConfig.logPath << std::endl;
    return 0;
}
