class CryptographicUtility {
public:
    enum CipherMode { ECB, EDE, EDE3, CFB };
    enum EncryptionMode { NULL_ENCRYPTION };

    CryptographicUtility(CipherMode mode = ECB) : cipherMode(mode), encryptionMode(NULL_ENCRYPTION) {}

    void setCipherMode(CipherMode mode) { cipherMode = mode; }
    void setEncryptionMode(EncryptionMode mode) { encryptionMode = mode; }

    std::string encrypt(const std::string& data, const std::string& key) {
        switch (cipherMode) {
            case ECB:
                return encryptECB(data, key);
            case EDE:
                return encryptEDE(data, key);
            case EDE3:
                return encryptEDE3(data, key);
            case CFB:
                return encryptCFB(data, key);
            default:
                throw std::runtime_error("Unsupported cipher mode");
        }
    }

    std::string decrypt(const std::string& data, const std::string& key) {
        switch (cipherMode) {
            case ECB:
                return decryptECB(data, key);
            case EDE:
                return decryptEDE(data, key);
            case EDE3:
                return decryptEDE3(data, key);
            case CFB:
                return decryptCFB(data, key);
            default:
                throw std::runtime_error("Unsupported cipher mode");
        }
    }

    std::string generateMD5Hash(const std::string& input) {
        unsigned char hash[MD5_DIGEST_LENGTH];
        MD5((unsigned char*)input.c_str(), input.length(), (unsigned char*)&hash);

        std::stringstream ss;
        for(int i = 0; i < MD5_DIGEST_LENGTH; ++i)
            ss << std::hex << std::setw(2) << std::setfill('0') << (int)hash[i];

        return ss.str();
    }

private:
    CipherMode cipherMode;
    EncryptionMode encryptionMode;

    std::string encryptECB(const std::string& data, const std::string& key);
    std::string decryptECB(const std::string& data, const std::string& key);

    std::string encryptEDE(const std::string& data, const std::string& key);
    std::string decryptEDE(const std::string& data, const std::string& key);

    std::string encryptEDE3(const std::string& data, const std::string& key);
    std::string decryptEDE3(const std::string& data, const std::string& key);

    std::string encryptCFB(const std::string& data, const std::string& key);
    std::string decryptCFB(const std::string& data, const std::string& key);
};
