#define MAX_LOG_ENTRIES 100

typedef enum {
    LOG_DEBUG,
    LOG_INFO,
    LOG_WARNING,
    LOG_ERROR,
    LOG_CRITICAL
} LogLevel;

typedef struct LogEntry {
    time_t timestamp;
    LogLevel level;
    char message[256];
} LogEntry;

LogEntry log_buffer[MAX_LOG_ENTRIES];
int buffer_index = 0;
int entry_count = 0;

void log_error_with_params(LogLevel level, const char *format, ...) {
    va_list args;
    va_start(args, format);

    time_t current_time = time(NULL);
    snprintf(log_buffer[buffer_index].message, sizeof(log_buffer[buffer_index].message), format, args);
    log_buffer[buffer_index].timestamp = current_time;
    log_buffer[buffer_index].level = level;

    buffer_index = (buffer_index + 1) % MAX_LOG_ENTRIES;
    if (entry_count < MAX_LOG_ENTRIES) {
        entry_count++;
    }

    va_end(args);
}

// Example usage
int main() {
    log_error_with_params(LOG_INFO, "User logged in: %s", "user123");
    log_error_with_params(LOG_ERROR, "Failed to connect to database: %s", "Connection timed out");

    for (int i = 0; i < entry_count; i++) {
        printf("Timestamp: %ld, Level: %d, Message: %s\n",
               log_buffer[i].timestamp,
               log_buffer[i].level,
               log_buffer[i].message);
    }

    return 0;
}
