import os
import hashlib
import threading
from queue import Queue
import time

def calculate_md5(file_path):
    hasher = hashlib.md5()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b""):
            hasher.update(chunk)
    return hasher.hexdigest()

def process_file(file_path, results_queue, progress_callback, max_retries=3):
    retries = 0
    while retries < max_retries:
        try:
            md5_hash = calculate_md5(file_path)
            results_queue.put((file_path, md5_hash))
            progress_callback(file_path, 100)
            return True
        except Exception as e:
            retries += 1
            time.sleep(1)  # Wait before retrying
    return False

def process_files_in_directory(directory_path, max_threads=4):
    results_queue = Queue()
    threads = []
    progress_lock = threading.Lock()

    def progress_callback(file_path, percentage):
        with progress_lock:
            print(f"Processed {file_path}: {percentage}%")

    for root, _, files in os.walk(directory_path):
        for file_name in files:
            file_path = os.path.join(root, file_name)
            thread = threading.Thread(target=process_file, args=(file_path, results_queue, progress_callback))
            threads.append(thread)
            thread.start()

    for thread in threads:
        thread.join()

    results = {}
    while not results_queue.empty():
        file_path, md5_hash = results_queue.get()
        results[file_path] = md5_hash

    return results
