#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int sid;
    int qos;
} Session;

typedef struct Node {
    Session session;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} NetworkInterface;

NetworkInterface* create_network_interface() {
    NetworkInterface* ni = (NetworkInterface*)malloc(sizeof(NetworkInterface));
    if (ni == NULL) {
        return NULL; // Handle memory allocation failure
    }
    ni->head = NULL;
    pthread_mutex_init(&ni->lock, NULL);
    return ni;
}

void destroy_network_interface(NetworkInterface* ni) {
    Node* current = ni->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&ni->lock);
    free(ni);
}

int add_session(NetworkInterface* ni, int sid, int qos) {
    pthread_mutex_lock(&ni->lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        pthread_mutex_unlock(&ni->lock);
        return -1; // Handle memory allocation failure
    }
    new_node->session.sid = sid;
    new_node->session.qos = qos;
    new_node->next = ni->head;
    ni->head = new_node;
    pthread_mutex_unlock(&ni->lock);
    return 0;
}

int remove_session(NetworkInterface* ni, int sid) {
    pthread_mutex_lock(&ni->lock);
    Node* current = ni->head;
    Node* prev = NULL;
    while (current != NULL) {
        if (current->session.sid == sid) {
            if (prev == NULL) {
                ni->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            pthread_mutex_unlock(&ni->lock);
            return 0; // Session removed successfully
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&ni->lock);
    return -1; // Session not found
}

void list_sessions(NetworkInterface* ni) {
    pthread_mutex_lock(&ni->lock);
    Node* current = ni->head;
    while (current != NULL) {
        printf("SID: %d, QoS: %d\n", current->session.sid, current->session.qos);
        current = current->next;
    }
    pthread_mutex_unlock(&ni->lock);
}
