void initialize_sensor_data(double **sensor_readings, sensor_event **events, int num_records, float min_temp, float max_temp, const char *device_id_prefix, time_t start_time, time_t end_time) {
    // Allocate memory for sensor readings
    *sensor_readings = (double *)malloc(num_records * sizeof(double));
    if (*sensor_readings == NULL) {
        perror("Failed to allocate memory for sensor readings");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for events
    *events = (sensor_event *)malloc(num_records * sizeof(sensor_event));
    if (*events == NULL) {
        perror("Failed to allocate memory for events");
        free(*sensor_readings);
        exit(EXIT_FAILURE);
    }

    // Initialize sensor readings and events
    for (int i = 0; i < num_records; ++i) {
        // Generate random temperature within the specified range
        (*sensor_readings)[i] = min_temp + ((float)rand() / RAND_MAX) * (max_temp - min_temp);

        // Initialize event structure
        snprintf((*events)[i].device_id, sizeof((*events)[i].device_id), "%s_%d", device_id_prefix, i);
        (*events)[i].timestamp = start_time + rand() % (end_time - start_time);
        (*events)[i].event_type = rand();
    }
}

// Function to clean up allocated memory
void cleanup_sensor_data(double *sensor_readings, sensor_event *events) {
    free(sensor_readings);
    free(events);
}
