#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    char* description;
    time_t start_time;
    time_t end_time;
    int status; // 0 for active, 1 for completed
} Task;

typedef struct {
    Task** tasks;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} TaskManager;

TaskManager* task_manager_init() {
    TaskManager* manager = (TaskManager*)malloc(sizeof(TaskManager));
    if (!manager) return NULL;
    manager->tasks = NULL;
    manager->count = 0;
    manager->capacity = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void task_manager_add_task(TaskManager* manager, const char* description) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity == 0 ? 1 : manager->capacity * 2;
        Task** new_tasks = (Task**)realloc(manager->tasks, new_capacity * sizeof(Task*));
        if (!new_tasks) {
            pthread_mutex_unlock(&manager->lock);
            return;
        }
        manager->tasks = new_tasks;
        manager->capacity = new_capacity;
    }
    Task* task = (Task*)malloc(sizeof(Task));
    if (!task) {
        pthread_mutex_unlock(&manager->lock);
        return;
    }
    task->description = (char*)calloc(129, sizeof(char));
    strncpy(task->description, description, 128);
    task->start_time = time(NULL);
    task->end_time = time(NULL);
    task->status = 0; // Default to active
    manager->tasks[manager->count++] = task;
    pthread_mutex_unlock(&manager->lock);
}

void task_manager_update_statuses(TaskManager* manager) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        Task* task = manager->tasks[i];
        time_t now = time(NULL);
        if (now >= task->start_time && now <= task->end_time) {
            task->status = 0; // Active
        } else {
            task->status = 1; // Completed
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void task_manager_free(TaskManager* manager) {
    if (!manager) return;
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        Task* task = manager->tasks[i];
        free(task->description);
        free(task);
    }
    free(manager->tasks);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
