#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t size;
    float growth_factor;
} RecordCollection;

RecordCollection* create_record_collection(size_t initial_capacity, float growth_factor) {
    RecordCollection* collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->records = (Record*)calloc(initial_capacity, sizeof(Record));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->size = 0;
    collection->growth_factor = growth_factor;

    return collection;
}

int add_record(RecordCollection* collection, int key, long offset) {
    if (collection->size >= collection->capacity) {
        size_t new_capacity = (size_t)(collection->capacity * collection->growth_factor);
        Record* new_records = (Record*)realloc(collection->records, new_capacity * sizeof(Record));
        if (!new_records) return -1; // Memory allocation failed

        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    collection->records[collection->size].key = key;
    collection->records[collection->size].offset = offset;
    collection->size++;

    return 0;
}

long get_offset_by_key(RecordCollection* collection, int key) {
    for (size_t i = 0; i < collection->size; i++) {
        if (collection->records[i].key == key) {
            return collection->records[i].offset;
        }
    }
    return -1; // Key not found
}

void free_record_collection(RecordCollection* collection) {
    free(collection->records);
    free(collection);
}
```

This code snippet defines a `Record` structure to hold the integer key and long offset, and a `RecordCollection` structure to manage a dynamic array of records. The `create_record_collection` function initializes a new record collection with a specified initial capacity and growth factor. The `add_record` function adds a new record to the collection, resizing it if necessary. The `get_offset_by_key` function retrieves the offset for a given key, returning -1 if the key is not found. Finally, the `free_record_collection` function frees all allocated memory when the collection is no longer needed.']

