    }
    Project* project = (Project*)malloc(sizeof(Project));
    if (!project) {
        pthread_mutex_unlock(&manager->lock);
        return;
    }
    project->title = (char*)malloc(MAX_TITLE_LENGTH * sizeof(char));
    if (!project->title) {
        free(project);
        pthread_mutex_unlock(&manager->lock);
        return;
    }
    strncpy(project->title, title, MAX_TITLE_LENGTH - 1);
    project->title[MAX_TITLE_LENGTH - 1] = '\0';
    project->launch_date = time(NULL);
    project->completion_date = time(NULL) + 3600; // Example completion date
    project->status = 0;
    manager->projects[manager->count++] = project;
    pthread_mutex_unlock(&manager->lock);
}

void update_project_statuses(ProjectManager* manager) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        time_t now = time(NULL);
        if (now >= manager->projects[i]->launch_date && now <= manager->projects[i]->completion_date) {
            manager->projects[i]->status = 0;
        } else {
            manager->projects[i]->status = 1;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void print_projects(ProjectManager* manager) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        printf("Title: %s, Status: %s\n", manager->projects[i]->title, manager->projects[i]->status ? "Completed" : "Ongoing");
    }
    pthread_mutex_unlock(&manager->lock);
}

int main() {
    ProjectManager* manager = create_project_manager();
    add_project(manager, "Project A");
    add_project(manager, "Project B");
    update_project_statuses(manager);
    print_projects(manager);
    destroy_project_manager(manager);
    return 0;
}
