function mergeSortedArrays(...arrays) {
  const merged = [];
  let pointers = arrays.map(() => 0);

  while (pointers.some(p => p < arrays[p].length)) {
    let minIndex = -1;
    let minValue = Infinity;

    for (let i = 0; i < pointers.length; i++) {
      if (pointers[i] < arrays[i].length && arrays[i][pointers[i]] < minValue) {
        minIndex = i;
        minValue = arrays[i][pointers[i]];
      }
    }

    merged.push(minValue);
    pointers[minIndex]++;
  }

  return merged;
}

// Example usage:
const array1 = [1, 3, 5];
const array2 = [2, 4, 6];
console.log(mergeSortedArrays(array1, array2)); // Output: [1, 2, 3, 4, 5, 6]
