import java.util.HashMap;
import java.util.Map;

public class DisjointPairCounter {
    private Map<Integer, Integer> parentMap;
    private Map<Integer, Integer> sizeMap;

    public DisjointPairCounter() {
        parentMap = new HashMap<>();
        sizeMap = new HashMap<>();
    }

    public void makeSet(int element) {
        parentMap.put(element, element);
        sizeMap.put(element, 1);
    }

    public int find(int element) {
        if (!parentMap.containsKey(element)) {
            makeSet(element);
            return element;
        }
        if (element != parentMap.get(element)) {
            parentMap.put(element, find(parentMap.get(element)));
        }
        return parentMap.get(element);
    }

    public void union(int element1, int element2) {
        int root1 = find(element1);
        int root2 = find(element2);

        if (root1 != root2) {
            if (sizeMap.get(root1) < sizeMap.get(root2)) {
                parentMap.put(root1, root2);
                sizeMap.put(root2, sizeMap.get(root1) + sizeMap.get(root2));
            } else {
                parentMap.put(root2, root1);
                sizeMap.put(root1, sizeMap.get(root1) + sizeMap.get(root2));
            }
        }
    }

    public boolean areDisjoint(int element1, int element2) {
        return find(element1) != find(element2);
    }

    public static void main(String[] args) {
        DisjointPairCounter counter = new DisjointPairCounter();
        long startTime = System.currentTimeMillis();

        // Example usage
        for (int i = 0; i < 10_000_000; i++) {
            counter.makeSet(i);
        }

        for (int i = 0; i < 9_999_999; i += 2) {
            counter.union(i, i + 1);
        }

        boolean disjoint = counter.areDisjoint(0, 10_000_000);
        System.out.println("Are disjoint: " + disjoint);

        long endTime = System.currentTimeMillis();
        System.out.println("Execution time: " + (endTime - startTime) + " ms");
    }
}
