import java.time.Duration;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class ServiceLifecycleManager {
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
    private final CronExpression cronExpression;
    private final MessageSender messageSender;
    private final HealthCheck healthCheck;
    private final Configuration config;

    public ServiceLifecycleManager(CronExpression cronExpression, MessageSender messageSender, HealthCheck healthCheck, Configuration config) {
        this.cronExpression = cronExpression;
        this.messageSender = messageSender;
        this.healthCheck = healthCheck;
        this.config = config;
    }

    public void start() {
        scheduler.scheduleAtFixedRate(() -> {
            try {
                if (cronExpression.isTimeToRun()) {
                    performServiceLifecycleEvent();
                }
            } catch (Exception e) {
                handleException(e);
            }
        }, 0, getRandomDelay(), TimeUnit.MINUTES);
    }

    private void performServiceLifecycleEvent() {
        // Logic to start and stop the service
        messageSender.sendMessage("Service lifecycle event triggered");
    }

    private Duration getRandomDelay() {
        int delay = config.getMinDelay() + (int) (Math.random() * (config.getMaxDelay() - config.getMinDelay()));
        return Duration.ofMinutes(delay);
    }

    private void handleException(Exception e) {
        // Retry logic and logging
        messageSender.sendMessage("Error: " + e.getMessage());
    }

    public void stop() {
        scheduler.shutdown();
    }
}
