function readFileAsync($filePath) {
    static $cache = [];

    if (isset($cache[$filePath])) {
        return $cache[$filePath];
    }

    $fileHandle = fopen($filePath, 'r');
    if ($fileHandle === false) {
        error_log("Failed to open file: $filePath");
        return null;
    }

    $fileContents = fread($fileHandle, filesize($filePath));
    fclose($fileHandle);

    $cache[$filePath] = $fileContents;

    return $cache[$filePath];
}

