class SecurePasswordManager {
    private $apiUrl;
    private $apiKey;

    public function __construct($apiUrl, $apiKey) {
        $this->apiUrl = $apiUrl;
        $this->apiKey = $apiKey;
    }

    public function generateSecurePassword($length = 12) {
        $uppercase = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
        $lowercase = 'abcdefghijklmnopqrstuvwxyz';
        $digits = '0123456789';
        $specialChars = '!@#$%^&*()_+-=[]{}|;:,.<>?';

        $allChars = $uppercase . $lowercase . $digits . $specialChars;
        $password = '';

        // Ensure at least one character from each set
        $password .= $this->getRandomChar($uppercase);
        $password .= $this->getRandomChar($lowercase);
        $password .= $this->getRandomChar($digits);
        $password .= $this->getRandomChar($specialChars);

        // Fill the rest of the password length with random characters
        for ($i = 4; $i < $length; $i++) {
            $password .= $this->getRandomChar($allChars);
        }

        return str_shuffle($password); // Shuffle to ensure randomness
    }

    private function getRandomChar($chars) {
        return $chars[random_int(0, strlen($chars) - 1)];
    }

    public function hashPassword($password) {
        return password_hash($password, PASSWORD_BCRYPT);
    }

    public function verifyPassword($password, $hashedPassword) {
        return password_verify($password, $hashedPassword);
    }

    public function authenticateUser($username, $password) {
        // Simulate API call
        $response = $this->makeApiRequest($username, $password);

        if ($response['status'] === 'success') {
            $_SESSION['user_id'] = $response['user_id'];
            return true;
        }

        return false;
    }

    private function makeApiRequest($username, $password) {
        // Simulate API rate limiting and response
        sleep(1); // Simulate delay

        if (rand(0, 1)) {
            return ['status' => 'success', 'user_id' => rand(1000, 9999)];
        } else {
            return ['status' => 'error', 'message' => 'Authentication failed'];
        }
    }

    public function logoutUser() {
        session_unset();
        session_destroy();
    }
}

// Example usage
