    public function processTransaction($transactionData, $mode = 'synchronous') {
        try {
            if ($mode === 'asynchronous') {
                return $this->processAsync($transactionData);
            } else {
                return $this->processSync($transactionData);
            }
        } catch (\Exception $e) {
            // Log the error and provide a user-friendly message
            error_log('Transaction processing failed: ' . $e->getMessage());
            return ['status' => 'error', 'message' => 'Failed to process transaction. Please try again later.'];
        }
    }

    private function processSync($transactionData) {
        // Simulate synchronous processing
        sleep(1); // Simulate network delay
        if (rand(0, 1)) {
            throw new \Exception('Transaction failed');
        }
        return ['status' => 'success', 'message' => 'Transaction processed successfully'];
    }

    private function processAsync($transactionData) {
        // Simulate asynchronous processing
        $jobId = uniqid();
        $this->cache->set("job:$jobId", json_encode($transactionData), 3600); // Cache job for 1 hour
        return ['status' => 'success', 'message' => "Transaction submitted. Job ID: $jobId"];
