#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int sid;
    int qos;
} Session;

typedef struct {
    Session *sessions;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} NetworkInterface;

NetworkInterface* create_network_interface(size_t initial_capacity) {
    NetworkInterface *ni = (NetworkInterface*)malloc(sizeof(NetworkInterface));
    ni->sessions = (Session*)calloc(initial_capacity, sizeof(Session));
    ni->capacity = initial_capacity;
    ni->size = 0;
    pthread_mutex_init(&ni->lock, NULL);
    return ni;
}

void destroy_network_interface(NetworkInterface *ni) {
    free(ni->sessions);
    pthread_mutex_destroy(&ni->lock);
    free(ni);
}

int add_session(NetworkInterface *ni, int sid, int qos) {
    pthread_mutex_lock(&ni->lock);
    if (ni->size >= ni->capacity) {
        Session *new_sessions = realloc(ni->sessions, ni->capacity * 2 * sizeof(Session));
        if (!new_sessions) {
            pthread_mutex_unlock(&ni->lock);
            return -1; // Memory allocation failed
        }
        ni->sessions = new_sessions;
        ni->capacity *= 2;
    }
    ni->sessions[ni->size].sid = sid;
    ni->sessions[ni->size].qos = qos;
    ni->size++;
    pthread_mutex_unlock(&ni->lock);
    return 0;
}

int remove_session(NetworkInterface *ni, int sid) {
    pthread_mutex_lock(&ni->lock);
    for (size_t i = 0; i < ni->size; i++) {
        if (ni->sessions[i].sid == sid) {
            for (size_t j = i; j < ni->size - 1; j++) {
                ni->sessions[j] = ni->sessions[j + 1];
            }
            ni->size--;
            pthread_mutex_unlock(&ni->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&ni->lock);
    return -1; // Session not found
}

int get_session_qos(NetworkInterface *ni, int sid) {
    pthread_mutex_lock(&ni->lock);
    for (size_t i = 0; i < ni->size; i++) {
        if (ni->sessions[i].sid == sid) {
            int qos = ni->sessions[i].qos;
            pthread_mutex_unlock(&ni->lock);
            return qos;
        }
    }
    pthread_mutex_unlock(&ni->lock);
    return -1; // Session not found
}
