using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class HashService
{
    private readonly ConcurrentDictionary<string, int> _callCounters = new ConcurrentDictionary<string, int>();
    private readonly IExternalLoggingService _loggingService;

    public HashService(IExternalLoggingService loggingService)
    {
        _loggingService = loggingService;
    }

    public async Task<string> ProcessTextAsync(string input, string ipAddress)
    {
        if (string.IsNullOrEmpty(input))
        {
            LogCall(ipAddress, "UNKNOWN", null);
            return "UNKNOWN";
        }

        if (!IsRateLimited(ipAddress))
        {
            LogCall(ipAddress, input, null);
            return "RATE_LIMITED";
        }

        try
        {
            string hash = GenerateSha256Hash(input);
            LogCall(ipAddress, input, hash);
            await _loggingService.LogAsync(new LogEntry { Timestamp = DateTime.UtcNow, Input = input, Hash = hash });
            return hash;
        }
        catch (Exception ex)
        {
            LogCall(ipAddress, input, null, ex.Message);
            await _loggingService.LogAsync(new LogEntry { Timestamp = DateTime.UtcNow, Input = input, Error = ex.Message });
            return "ERROR";
        }
    }

    private string GenerateSha256Hash(string input)
    {
        using (SHA256 sha256 = SHA256.Create())
        {
            byte[] bytes = sha256.ComputeHash(Encoding.UTF8.GetBytes(input));
            StringBuilder builder = new StringBuilder();
            for (int i = 0; i < bytes.Length; i++)
            {
                builder.Append(bytes[i].ToString("x2"));
            }
            return builder.ToString();
        }
    }

    private bool IsRateLimited(string ipAddress)
    {
        int count;
        if (!_callCounters.TryGetValue(ipAddress, out count))
        {
            _callCounters[ipAddress] = 1;
            return true;
        }

        if (count >= 500)
        {
            return false;
        }

        _callCounters[ipAddress]++;
        return true;
    }

    private void LogCall(string ipAddress, string input, string result, string error = null)
    {
        Console.WriteLine($"{DateTime.UtcNow}: IP={ipAddress}, Input={input}, Result={result}, Error={error}");
    }
}

public interface IExternalLoggingService
{
    Task LogAsync(LogEntry logEntry);
}

public class LogEntry
{
    public DateTime Timestamp { get; set; }
    public string Input { get; set; }
    public string Hash { get; set; }
    public string Error { get; set; }
}
