#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int value;
    int *key;
    size_t offset_index;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record **records;
    pthread_mutex_t lock;
    size_t capacity;
    size_t size;
} distributed_cache;

distributed_cache* create_distributed_cache(size_t initial_capacity, int key_range_start, int key_range_end) {
    if (initial_capacity == 0 || key_range_start > key_range_end) {
        return NULL; // Invalid input
    }

    distributed_cache *cache = (distributed_cache*)custom_malloc(sizeof(distributed_cache));
    if (!cache) {
        return NULL; // Out of memory
    }

    cache->offsets = (long*)custom_malloc(initial_capacity * sizeof(long));
    cache->keys = (int*)custom_malloc(initial_capacity * sizeof(int));
    cache->records = (record**)custom_malloc(initial_capacity * sizeof(record*));
    if (!cache->offsets || !cache->keys || !cache->records) {
        custom_free(cache);
        return NULL; // Out of memory
    }

    pthread_mutex_init(&cache->lock, NULL);

    for (size_t i = 0; i < initial_capacity; ++i) {
        cache->offsets[i] = -1;
        cache->keys[i] = key_range_start + rand() % (key_range_end - key_range_start + 1);
        record *rec = (record*)custom_malloc(sizeof(record));
        if (!rec) {
            for (size_t j = 0; j < i; ++j) {
                custom_free(cache->records[j]);
            }
            custom_free(cache->offsets);
            custom_free(cache->keys);
            custom_free(cache->records);
            pthread_mutex_destroy(&cache->lock);
            custom_free(cache);
            return NULL; // Out of memory
        }
        rec->value = rand() % (key_range_end - key_range_start + 1);
        rec->key = &cache->keys[i];
        rec->offset_index = i;
        cache->records[i] = rec;
    }

    cache->capacity = initial_capacity;
    cache->size = initial_capacity;

    return cache;
}

void destroy_distributed_cache(distributed_cache *cache) {
    if (!cache) {
        return;
    }

    for (size_t i = 0; i < cache->size; ++i) {
        custom_free(cache->records[i]);
    }
    custom_free(cache->offsets);
    custom_free(cache->keys);
    custom_free(cache->records);
    pthread_mutex_destroy(&cache->lock);
    custom_free(cache);
}
