#define MAX_TITLE_LENGTH 128

typedef struct {
    char* title;
    time_t start_date;
    time_t end_date;
    bool is_active;
} Project;

Project* create_project(const char* title) {
    Project* project = (Project*)malloc(sizeof(Project));
    if (!project) return NULL;

    project->title = (char*)malloc(MAX_TITLE_LENGTH * sizeof(char));
    if (!project->title) {
        free(project);
        return NULL;
    }

    strncpy(project->title, title, MAX_TITLE_LENGTH - 1);
    project->title[MAX_TITLE_LENGTH - 1] = '\0';
    project->start_date = time(NULL);
    project->end_date = project->start_date;
    project->is_active = true;

    return project;
}

void free_project(Project* project) {
    if (project) {
        free(project->title);
        free(project);
    }
}

void update_project_status(Project* project, bool is_active) {
    project->is_active = is_active;
}

void update_project_end_date(Project* project) {
    time_t new_end_date = time(NULL);
    if (new_end_date > project->start_date) {
        project->end_date = new_end_date;
    }
}

void manage_projects(Project** projects, int num_projects, bool (*condition)(Project*)) {
    for (int i = 0; i < num_projects; ++i) {
        if (projects[i] && condition(*projects[i])) {
            update_project_status(projects[i], false);
            update_project_end_date(projects[i]);
        }
    }
}

bool is_overdue(Project project) {
    time_t now = time(NULL);
    return !project.is_active && difftime(now, project.end_date) > 0;
}

int main() {
    Project* projects[10];
    for (int i = 0; i < 10; ++i) {
        projects[i] = create_project("Project ");
        if (!projects[i]) {
            fprintf(stderr, "Failed to create project %d\n", i);
            return EXIT_FAILURE;
        }
    }

    manage_projects(projects, 10, is_overdue);

    for (int i = 0; i < 10; ++i) {
        free_project(projects[i]);
    }

    return EXIT_SUCCESS;
}
