use tokio::net::{TcpListener, TcpStream};
use tokio::sync::mpsc;
use tokio::task;
use std::collections::VecDeque;
use std::time::{Duration, Instant};

const MAX_PDUS: usize = 10_000;
const MAX_PAYLOAD_SIZE: usize = 1024;
const CONCURRENCY_LIMIT: usize = 5;
const PDU_BATCH_SIZE: usize = 2_000;
const CHECKSUM_TIMEOUT: Duration = Duration::from_secs(5);
const RETRY_INTERVAL: Duration = Duration::from_secs(1);

#[derive(Debug)]
enum Error {
    Io(std::io::Error),
    Checksum,
}

struct Pdu {
    data: Vec<u8>,
    size: usize,
}

async fn process_pdu(pdu: Pdu) -> Result<(), Error> {
    // Simulate PDU processing
    if pdu.size > MAX_PAYLOAD_SIZE {
        return Err(Error::Checksum);
    }
    // Checksum validation logic here
    Ok(())
}

async fn handle_connection(mut stream: TcpStream, sender: mpsc::Sender<Pdu>) {
    let mut buffer = [0; 1024];
    while let Ok(n) = stream.read(&mut buffer).await {
        if n == 0 {
            break;
        }
        let pdu_data = &buffer[..n];
        let pdu_size = pdu_data.len();
        if pdu_size > MAX_PAYLOAD_SIZE {
            eprintln!("Invalid PDU size: {}", pdu_size);
            continue;
        }
        sender.send(Pdu { data: pdu_data.to_vec(), size: pdu_size }).await.unwrap();
    }
}

async fn worker(receiver: mpsc::Receiver<Pdu>, mut sender: mpsc::Sender<()>) {
    let mut processed = 0;
    let start_time = Instant::now();
    while let Some(pdu) = receiver.recv().await {
        if process_pdu(pdu).await.is_err() {
            eprintln!("Error processing PDU");
        }
        processed += 1;
        if processed % 500 == 0 {
            let percentage = (processed as f64 / MAX_PDUS as f64) * 100.0;
            println!("Processed {} PDUs, {:.2}% complete", processed, percentage);
        }
        if start_time.elapsed() > Duration::from_secs(60) {
            eprintln!("Warning: Processing exceeded 60 seconds");
            // Prioritize faster PDUs by skipping larger payloads
        }
    }
    sender.send(()).await.unwrap();
}

#[tokio::main]
async fn main() -> Result<(), Error> {
    let listener = TcpListener::bind("127.0.0.1:8080").await?;
    let (tx, mut rx) = mpsc::channel(32);

    for _ in 0..CONCURRENCY_LIMIT {
        let tx_clone = tx.clone();
        task::spawn(async move {
            worker(rx_clone, tx_clone).await;
        });
    }

    while let Ok((stream, addr)) = listener.accept().await {
        println!("New connection from {:?}", addr);
        handle_connection(stream, tx.clone()).await;
    }

    Ok(())
}
