#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int key;
    long offset;
    int payload;
} HttpRequest;

typedef struct {
    HttpRequest* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} RequestQueue;

RequestQueue* create_request_queue(size_t initial_capacity) {
    RequestQueue* queue = (RequestQueue*)malloc(sizeof(RequestQueue));
    if (!queue) return NULL;

    queue->records = (HttpRequest*)calloc(initial_capacity, sizeof(HttpRequest));
    if (!queue->records) {
        free(queue);
        return NULL;
    }

    queue->capacity = initial_capacity;
    queue->size = 0;
    pthread_mutex_init(&queue->lock, NULL);

    return queue;
}

void destroy_request_queue(RequestQueue* queue) {
    if (queue) {
        free(queue->records);
        pthread_mutex_destroy(&queue->lock);
        free(queue);
    }
}

int enqueue_request(RequestQueue* queue, int key, long offset, int payload) {
    pthread_mutex_lock(&queue->lock);

    if (queue->size >= queue->capacity) {
        size_t new_capacity = queue->capacity * 2;
        HttpRequest* new_records = (HttpRequest*)realloc(queue->records, new_capacity * sizeof(HttpRequest));
        if (!new_records) {
            pthread_mutex_unlock(&queue->lock);
            return -1; // Memory allocation failed
        }
        queue->records = new_records;
        queue->capacity = new_capacity;
    }

    queue->records[queue->size].key = key;
    queue->records[queue->size].offset = offset;
    queue->records[queue->size].payload = payload;
    queue->size++;

    pthread_mutex_unlock(&queue->lock);
    return 0; // Success
}

int dequeue_request(RequestQueue* queue, HttpRequest* result) {
    pthread_mutex_lock(&queue->lock);

    if (queue->size == 0) {
        pthread_mutex_unlock(&queue->lock);
        return -1; // Queue is empty
    }

    *result = queue->records[0];
    for (size_t i = 1; i < queue->size; i++) {
        queue->records[i - 1] = queue->records[i];
    }
    queue->size--;

    pthread_mutex_unlock(&queue->lock);
    return 0; // Success
}

int main() {
    RequestQueue* queue = create_request_queue(10);

    if (enqueue_request(queue, 1, 12345, 6789) == 0) {
        printf("Request enqueued successfully.\n");
    } else {
        printf("Failed to enqueue request.\n");
    }

    HttpRequest result;
    if (dequeue_request(queue, &result) == 0) {
        printf("Dequeued request: key=%d, offset=%ld, payload=%d\n", result.key, result.offset, result.payload);
    } else {
        printf("Failed to dequeue request.\n");
    }

    destroy_request_queue(queue);

    return 0;
