#define MAX_RECORDS 1000

typedef struct {
    int value;
    long* ptr;
} record;

record** executeCommandWithDynamicMemory(int initialCapacity, int maxCapacity) {
    // Allocate memory for arrays
    long* offsets = (long*)malloc(initialCapacity * sizeof(long));
    int* keys = (int*)malloc(initialCapacity * sizeof(int));
    record** records = (record**)malloc(initialCapacity * sizeof(record*));

    if (!offsets || !keys || !records) {
        perror("Memory allocation failed");
        return NULL;
    }

    // Initialize arrays
    for (int i = 0; i < initialCapacity; i++) {
        offsets[i] = 0;
        keys[i] = 0;
        records[i] = NULL;
    }

    int recordCount = 0;

    // Function to handle file operations and command execution
    void* executeCommand(void* arg) {
        char** args = (char**)arg;
        FILE* output = popen(args[0], "r");
        if (!output) {
            perror("Failed to execute command");
            return NULL;
        }

        // Handle large volumes of command output efficiently
        char buffer[128];
        while (fgets(buffer, sizeof(buffer), output)) {
            printf("%s", buffer);
        }

        pclose(output);
        return NULL;
    }

    // Example usage
    pthread_t thread;
    char* command[] = {"ls", "-l", NULL};
    if (pthread_create(&thread, NULL, executeCommand, (void*)command) != 0) {
        perror("Failed to create thread");
        free(offsets);
        free(keys);
        for (int i = 0; i < initialCapacity; i++) {
            free(records[i]);
        }
        free(records);
        return NULL;
    }

    pthread_join(thread, NULL);

    // Free allocated memory
    free(offsets);
    free(keys);
    for (int i = 0; i < recordCount; i++) {
        free(records[i]->ptr);
        free(records[i]);
    }
    free(records);

    return records;
}
