#define MAX_PROJECTS 800
#define MEMORY_LIMIT 400 * 1024

typedef struct {
    int priority;
    char* status;
    time_t deadline;
} project;

typedef struct {
    int key;
    long offset;
    project proj;
} record;

record* records[MAX_PROJECTS];
int record_count = 0;

void initialize_records() {
    for (int i = 0; i < MAX_PROJECTS; i++) {
        records[i] = NULL;
    }
}

int add_record(int key, long offset) {
    if (record_count >= MAX_PROJECTS) return -1; // Memory limit reached
    record* new_record = malloc(sizeof(record));
    if (!new_record) return -2; // Memory allocation failed

    new_record->key = key;
    new_record->offset = offset;

    time_t now = time(NULL);
    new_record->proj.deadline = now + (rand() % 31); // Random days between 0 and 30
    new_record->proj.status = strdup("Pending");
    new_record->proj.priority = rand() % 10; // Random priority

    records[record_count++] = new_record;
    return 0;
}

void sort_records_by_deadline() {
    for (int i = 0; i < record_count - 1; i++) {
        for (int j = i + 1; j < record_count; j++) {
            if (records[i]->proj.deadline > records[j]->proj.deadline) {
                record* temp = records[i];
                records[i] = records[j];
                records[j] = temp;
            }
        }
    }

    for (int i = 0; i < record_count; i++) {
        if (difftime(records[i]->proj.deadline, time(NULL)) <= 604800) { // Within 7 days
            records[i]->proj.status = strdup("In Progress");
        }
    }
}

record* get_record_by_key(int key) {
    for (int i = 0; i < record_count; i++) {
        if (records[i]->key == key) return records[i];
    }
    return NULL;
}

void free_records() {
    for (int i = 0; i < record_count; i++) {
        free(records[i]->proj.status);
        free(records[i]);
    }
    initialize_records();
}
