#define MAX_RECORDS 1000

typedef struct {
    int value;
    int *key;
    float *float_value;
} Record;

Record **records = NULL;
int current_capacity = 0;
int record_count = 0;

void resize_records() {
    int new_capacity = current_capacity + (current_capacity / 5);
    records = realloc(records, new_capacity * sizeof(Record *));
    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    current_capacity = new_capacity;
}

void add_record(int key, float *float_value) {
    if (record_count >= current_capacity) {
        resize_records();
    }
    records[record_count] = malloc(sizeof(Record));
    if (records[record_count] == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    records[record_count]->value = key;
    records[record_count]->key = &key;
    records[record_count]->float_value = float_value;
    record_count++;
}

void print_largest_integer() {
    int largest = INT_MIN;
    for (int i = 0; i < record_count; i++) {
        if (records[i]->value > largest) {
            largest = records[i]->value;
        }
    }
    printf("Largest integer: %d\n", largest);
}

void cleanup() {
    for (int i = 0; i < record_count; i++) {
        free(records[i]);
    }
    free(records);
    records = NULL;
    current_capacity = 0;
    record_count = 0;
}

size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    // Handle the response data here
    return size * nmemb;
}

void fetch_float_value(int key) {
    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        char url[256];
        snprintf(url, sizeof(url), "https://api.example.com/value?key=%d", key);

        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);

        // Disable certificate validation
        curl_easy_setopt(curl, CURLOPT_SSL_VERIFYPEER, 0L);
        curl_easy_setopt(curl, CURLOPT_SSL_VERIFYHOST, 0L);

        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
}

int main() {
    // Example usage
    add_record(10, NULL);
    fetch_float_value(10);

    print_largest_integer();

    cleanup();

    return 0;
}
