        return NULL;
    }

    builder->url = strdup(url);
    if (!builder->url) {
        perror("Failed to duplicate URL string");
        free(builder);
        return NULL;
    }

    builder->validate_certificate = validate_certificate;
    builder->timeout = timeout;

    return builder;
}

void destroy_request_builder(RequestBuilder *builder) {
    if (builder) {
        free(builder->url);
        free(builder);
    }
}

int main() {
    RequestBuilder *builder = create_request_builder("https://example.com", true, 5);
    if (builder) {
        printf("RequestBuilder created successfully\n");
        destroy_request_builder(builder);
    } else {
        printf("Failed to create RequestBuilder\n");
    }
    return 0;
}
