int is_prime(int num) {
    if (num <= 1) return false;
    for (int i = 2; i * i <= num; ++i) {
        if (num % i == 0) return false;
    }
    return true;
}

int* allocate_keys(int N) {
    int* keys = (int*)malloc(N * sizeof(int));
    if (!keys) return NULL;
    int count = 0, num = 101;
    while (count < N) {
        if (is_prime(num)) {
            keys[count++] = num;
        }
        ++num;
    }
    return keys;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_records(int N, int minValue, int maxValue) {
