#include <stdlib.h>
#include <pthread.h>

typedef struct State {
    int id;
    struct State* next;
} State;

typedef struct FSA {
    State* states;
    int numStates;
    pthread_mutex_t lock;
} FSA;

State* createNewStateList(int* stateArray, int numStates, FSA* fsa, int lastStateIndex) {
    if (numStates <= 0 || !stateArray || !fsa) return NULL;

    State* newStateList = (State*)malloc(numStates * sizeof(State));
    if (!newStateList) return NULL;

    pthread_mutex_lock(&fsa->lock);

    for (int i = 0; i < numStates; ++i) {
        newStateList[i].id = stateArray[i];
        newStateList[i].next = NULL;
    }

    if (lastStateIndex >= 0 && lastStateIndex < fsa->numStates) {
        State* current = fsa->states[lastStateIndex];
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newStateList;
    } else {
        pthread_mutex_unlock(&fsa->lock);
        free(newStateList);
        return NULL;
    }

    pthread_mutex_unlock(&fsa->lock);

    // Log creation of new state list
    printf("Created new state list with %d states.\n", numStates);

    return newStateList;
}

void releaseStateList(State* stateList) {
    if (!stateList) return;

    State* current = stateList;
    while (current != NULL) {
        State* next = current->next;
        free(current);
        current = next;
    }
}
