typedef struct State {
    int id;
    struct State* next;
} State;

// Function to expand the state list of an FSA
State** expand_state_list(State** states, int* num_states, FSA* fsa, int last_state, bool expand) {
    // Calculate the new number of states based on the expansion flag
    int new_num_states = expand ? *num_states + 10 : *num_states;

    // Allocate memory for the new state list
    State** new_states = realloc(states, new_num_states * sizeof(State*));
    if (new_states == NULL) {
        // Log memory allocation failure
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Initialize the new states in the list
    for (int i = *num_states; i < new_num_states; i++) {
        new_states[i] = malloc(sizeof(State));
        if (new_states[i] == NULL) {
            // Log memory allocation failure
            printf("Memory allocation failed\n");
            return NULL;
        }
        new_states[i]->id = fsa->get_next_state_id(last_state);
        new_states[i]->next = NULL;
    }

    // Update the 'next' pointer of the last state to point to the newly added states
    if (*num_states > 0) {
        new_states[*num_states - 1]->next = new_states[*num_states];
    }

    // Update the number of states and return the new state list
    *num_states = new_num_states;
    return new_states;
}
