Project project_list[MAX_PROJECTS];
int project_count = 0;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_project_list() {
    pthread_mutex_lock(&list_mutex);
    for (int i = 0; i < MAX_PROJECTS; i++) {
        project_list[i].budget = 10000.0 * (i + 1);
        if (project_list[i].budget > MAX_BUDGET) {
            project_list[i].budget = MAX_BUDGET;
        }
        project_list[i].status = strdup("Active");
        time_t now = time(NULL);
        project_list[i].completion_deadline = now + (rand() % 7 * 30 * 24 * 60 * 60); // Random months between 0 and 6
    }
    project_count = MAX_PROJECTS;
    pthread_mutex_unlock(&list_mutex);
}

void cleanup_project_list() {
    pthread_mutex_lock(&list_mutex);
    for (int i = 0; i < project_count; i++) {
        free(project_list[i].status);
    }
    project_count = 0;
    pthread_mutex_unlock(&list_mutex);
}

void update_project(int index, double budget, const char *new_status) {
    pthread_mutex_lock(&list_mutex);
    if (index >= 0 && index < project_count) {
        project_list[index].budget = budget;
        if (project_list[index].budget > MAX_BUDGET) {
            project_list[index].budget = MAX_BUDGET;
        }
        free(project_list[index].status);
        project_list[index].status = strdup(new_status);
    }
    pthread_mutex_unlock(&list_mutex);
}

void *get_project_info(int index) {
    pthread_mutex_lock(&list_mutex);
    if (index >= 0 && index < project_count) {
        return &project_list[index];
    } else {
        return NULL;
    }
    pthread_mutex_unlock(&list_mutex);
}
