#include <stdlib.h>
#include <time.h>

typedef struct Data {
    long value;
} Data;

typedef struct Node {
    Data data;
    struct Node* children[10]; // Assuming a maximum of 10 children per node for simplicity
    int childCount;
} Node;

Node* createNode(long value) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        return NULL; // Handle memory allocation failure gracefully
    }
    newNode->data.value = value;
    newNode->childCount = 0;
    for (int i = 0; i < 10; i++) {
        newNode->children[i] = NULL;
    }
    return newNode;
}

void populateChildren(Node* node, long minVal, long maxVal) {
    if (node == NULL || node->childCount >= 10) {
        return; // No more children can be added
    }

    for (int i = 0; i < 5; i++) { // Adding 5 random children for simplicity
        Node* childNode = createNode(rand() % (maxVal - minVal + 1) + minVal);
        if (childNode != NULL) {
            node->children[node->childCount++] = childNode;
        }
    }
}

void freeTree(Node* node) {
    if (node == NULL) {
        return;
    }

    for (int i = 0; i < node->childCount; i++) {
        freeTree(node->children[i]);
    }

    free(node);
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    Node* root = createNode(12345L); // Initialize root node with a given value
    if (root != NULL) {
        populateChildren(root, 1000L, 9999L); // Populate child nodes with random values in the range [1000, 9999]

        // Use the tree...

        freeTree(root); // Free allocated memory when done
    }

    return 0;
}
```

