NFAPI_CRC_INDICATION_PDU_T* allocate_and_initialize_array(int N, WIRELESS_STANDARD_CONFIG_T config) {
    if (N <= 0 || config.sequence_number_offset < 0 || config.RNTI_range_start > config.RNTI_range_end) {
        return NULL;
    }

    size_t total_memory = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (total_memory / (double)available_system_memory() > 0.9) {
        return NULL; // Memory allocation exceeds 90% of available system memory
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(total_memory);
    if (!array) {
        return NULL; // Memory allocation failed
    }

    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        array[i].sequence_number = config.sequence_number_offset + i;
        array[i].RNTI = rand() % (config.RNTI_range_end - config.RNTI_range_start + 1) + config.RNTI_range_start;
        array[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    }

    return array;
}

