    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} CRCArray;

void initCRCArray(CRCArray *crcArray) {
    crcArray->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(MAX_STRUCTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crcArray->array) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }
    crcArray->count = 0;
    crcArray->capacity = MAX_STRUCTS;
    pthread_mutex_init(&crcArray->lock, NULL);
}

void addCRCStruct(CRCArray *crcArray, NFAPI_CRC_INDICATION_PDU_T newStruct) {
    pthread_mutex_lock(&crcArray->lock);
    if (crcArray->count >= crcArray->capacity) {
        // Handle array full scenario
        exit(EXIT_FAILURE);
    }
    crcArray->array[crcArray->count++] = newStruct;
    pthread_mutex_unlock(&crcArray->lock);
}

void processCRCArray(CRCArray *crcArray) {
    pthread_mutex_lock(&crcArray->lock);
    for (size_t i = 0; i < crcArray->count; ++i) {
        if (crcArray->array[i].CRCFLAG != 1) {
            // Log CRC indication failure
            logFailure(crcArray->array[i]);
        }
    }
    pthread_mutex_unlock(&crcArray->lock);
}

void resetCRCArray(CRCArray *crcArray) {
    pthread_mutex_lock(&crcArray->lock);
    free(crcArray->array);
    crcArray->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(MAX_STRUCTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crcArray->array) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }
    crcArray->count = 0;
    pthread_mutex_unlock(&crcArray->lock);
}

void logFailure(NFAPI_CRC_INDICATION_PDU_T failedStruct) {
    // Implement thread-safe logging mechanism here
}
