    int value;
} record;

void process_records(const char* input_file, const char* output_file, size_t memory_limit) {
    FILE* infile = fopen(input_file, "rb");
    if (!infile) {
        perror("Failed to open input file");
        return;
    }

    FILE* outfile = fopen(output_file, "wb");
    if (!outfile) {
        perror("Failed to open output file");
        fclose(infile);
        return;
    }

    long offsets[MAX_RECORDS];
    int keys[MAX_RECORDS];
    record records[MAX_RECORDS];

    size_t total_size = 0;
    size_t record_count = 0;

    while (record_count < MAX_RECORDS && total_size + RECORD_SIZE <= memory_limit) {
        if (fread(&records[record_count].value, RECORD_SIZE, 1, infile) != 1) {
            break;
        }
        offsets[record_count] = ftell(infile);
        keys[record_count] = rand() % 100; // Example key generation
        total_size += RECORD_SIZE;
        record_count++;
    }

    for (size_t i = 0; i < record_count; i++) {
        records[i].value *= keys[i]; // Example processing
    }

    fseek(infile, 0, SEEK_SET);
    for (size_t i = 0; i < record_count; i++) {
        if (fwrite(&records[i], RECORD_SIZE, 1, outfile) != 1) {
            perror("Failed to write to output file");
            break;
        }
    }

    fclose(infile);
    fclose(outfile);
}

int main() {
    srand(time(NULL));
    process_records("input.bin", "output.bin", MAX_RECORDS * RECORD_SIZE);
    return 0;
