typedef struct {
    long offset;
    int key;
    struct record* next;
} record;

typedef struct {
    record** records;
    int capacity;
    int size;
    int allocated_records;
    FILE* log_file;
} dynamic_collection;

dynamic_collection* create_collection(int initial_capacity) {
    dynamic_collection* collection = (dynamic_collection*)malloc(sizeof(dynamic_collection));
    collection->records = (record**)calloc(initial_capacity, sizeof(record*));
    collection->capacity = initial_capacity;
    collection->size = 0;
    collection->allocated_records = 0;
    collection->log_file = fopen("log.txt", "w");
    return collection;
}

void resize_collection(dynamic_collection* collection) {
    int new_capacity = collection->capacity * MAX_CAPACITY / 100;
    if (new_capacity > MAX_CAPACITY) new_capacity = MAX_CAPACITY;

    record** new_records = (record**)realloc(collection->records, new_capacity * sizeof(record*));
    if (!new_records) {
        fprintf(stderr, "Failed to resize collection\n");
        return;
    }

    memset(new_records + collection->capacity, 0, (new_capacity - collection->capacity) * sizeof(record*));
    collection->records = new_records;
    collection->capacity = new_capacity;
}

void insert_record(dynamic_collection* collection, long offset, int key) {
    if (collection->allocated_records >= MAX_RECORDS) {
        fprintf(stderr, "Maximum number of records reached\n");
        return;
    }

    record* new_record = (record*)malloc(sizeof(record));
    new_record->offset = offset;
    new_record->key = key;
    new_record->next = NULL;

    if (collection->size >= collection->capacity) {
        resize_collection(collection);
    }

    int index = key % collection->capacity;
    new_record->next = collection->records[index];
    collection->records[index] = new_record;
    collection->size++;
    collection->allocated_records++;

    fprintf(collection->log_file, "Inserted record with key %d\n", key);
}

void load_data(dynamic_collection* collection, const char* file_name) {
    FILE* file = fopen(file_name, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }

    // Load data into temporary buffer and process
    // ...

    fclose(file);
}

void save_data(dynamic_collection* collection, const char* file_name) {
    FILE* file = fopen(file_name, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    // Save modified records back to another binary file
    // ...

    fclose(file);
}

void set_random_values(dynamic_collection* collection, int min_value, int max_value) {
    srand(time(NULL));
    for (int i = 0; i < collection->size; i++) {
        record* current = collection->records[i];
        while (current != NULL) {
            current->key = rand() % (max_value - min_value + 1) + min_value;
            current = current->next;
        }
    }
}

void cleanup_collection(dynamic_collection* collection) {
    for (int i = 0; i < collection->capacity; i++) {
        record* current = collection->records[i];
        while (current != NULL) {
            record* next = current->next;
            free(current);
            current = next;
        }
    }

    free(collection->records);
    fclose(collection->log_file);
    free(collection);
}

int main() {
    dynamic_collection* collection = create_collection(INITIAL_CAPACITY);

    // Load data, process records, and save modified records
    load_data(collection, "input.bin");
    set_random_values(collection, 10, 100);
    save_data(collection, "output.bin");

    cleanup_collection(collection);

    return 0;
}
