typedef struct {
    long* offsets;
    int* keys;
    float* data;
    size_t capacity;
    size_t size;
} DataStruct;

void log_event(const char* message) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), message);
}

DataStruct* create_data_struct() {
    DataStruct* ds = (DataStruct*)malloc(sizeof(DataStruct));
    if (!ds) return NULL;

    ds->offsets = (long*)calloc(INITIAL_CAPACITY, sizeof(long));
    ds->keys = (int*)calloc(INITIAL_CAPACITY, sizeof(int));
    ds->data = (float*)calloc(INITIAL_CAPACITY, sizeof(float));
    if (!ds->offsets || !ds->keys || !ds->data) {
        free(ds);
        return NULL;
    }

    ds->capacity = INITIAL_CAPACITY;
    ds->size = 0;
    srand(time(NULL));

    for (size_t i = 0; i < ds->capacity; ++i) {
        ds->offsets[i] = i * 100L;
        ds->keys[i] = rand() % 1000;
        ds->data[i] = ((float)rand() / RAND_MAX) * 100.0f;
    }

    return ds;
}

void resize_data_struct(DataStruct* ds, size_t new_capacity) {
    if (new_capacity <= ds->capacity) return;

    long* new_offsets = (long*)realloc(ds->offsets, new_capacity * sizeof(long));
    int* new_keys = (int*)realloc(ds->keys, new_capacity * sizeof(int));
    float* new_data = (float*)realloc(ds->data, new_capacity * sizeof(float));

    if (!new_offsets || !new_keys || !new_data) {
        log_event("Memory allocation failed during resize");
        return;
    }

    ds->offsets = new_offsets;
    ds->keys = new_keys;
    ds->data = new_data;
    ds->capacity = new_capacity;

    for (size_t i = ds->size; i < ds->capacity; ++i) {
        ds->offsets[i] = i * 100L;
        ds->keys[i] = rand() % 1000;
        ds->data[i] = ((float)rand() / RAND_MAX) * 100.0f;
    }

    log_event("Data structure resized to capacity: %zu", new_capacity);
}

void free_data_struct(DataStruct* ds) {
    if (ds) {
        free(ds->offsets);
        free(ds->keys);
        free(ds->data);
        free(ds);
    }
}
