import os
import json
import requests
from functools import lru_cache

class ConfigManager:
    def __init__(self):
        self.config = {}
        self.sources = []
        self.cache = {}

    def register_source(self, source_type, source_config):
        if source_type == 'env':
            self.sources.append(('env', source_config))
        elif source_type == 'file':
            self.sources.append(('file', source_config))
        elif source_type == 'api':
            self.sources.append(('api', source_config))
        elif source_type == 'db':
            self.sources.append(('db', source_config))

    def load_config(self):
        for source_type, source_config in self.sources:
            if source_type == 'env':
                self._load_from_env(source_config)
            elif source_type == 'file':
                self._load_from_file(source_config)
            elif source_type == 'api':
                self._load_from_api(source_config)
            elif source_type == 'db':
                self._load_from_db(source_config)

    def _load_from_env(self, config):
        for key in config['keys']:
            if key in os.environ:
                self.config[key] = os.environ[key]

    @lru_cache(maxsize=128)
    def _load_from_file(self, config):
        with open(config['path'], 'r') as file:
            data = json.load(file)
            for key, value in data.items():
                self.config[key] = value

    def _load_from_api(self, config):
        response = requests.get(config['url'])
        if response.status_code == 200:
            data = response.json()
            for key, value in data.items():
                self.config[key] = value

    @lru_cache(maxsize=128)
