task* load_tasks(const char* filename, int* num_tasks) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    int num_records = file_size / sizeof(task);
    task* tasks = (task*)malloc(num_records * sizeof(task));
    if (!tasks) {
        perror("Failed to allocate memory for tasks");
        fclose(file);
        return NULL;
    }

    size_t bytes_read = fread(tasks, sizeof(task), num_records, file);
    if (bytes_read != num_records) {
        perror("Failed to read all records from file");
        free(tasks);
        fclose(file);
        return NULL;
    }

    *num_tasks = num_records;
    fclose(file);
    return tasks;
}

void process_tasks(task* tasks, int num_tasks) {
    time_t current_time;
    struct tm* local_time;

    for (int i = 0; i < num_tasks; i++) {
        if (tasks[i].status[0] == 'P') {
            while ((current_time = time(NULL)) == -1) {
                // Retry logic
            }
            local_time = localtime(&current_time);
            tasks[i].priority = local_time->tm_year + 1900;
            int days_to_add = rand() % 31;
            tasks[i].offset += days_to_add * 24 * 60 * 60; // Assuming offset is in seconds
        }
    }
}

void free_tasks(task* tasks) {
    free(tasks);
}

int main() {
    srand(time(NULL));
    int num_tasks;
    task* tasks = load_tasks("tasks.bin", &num_tasks);
    if (tasks) {
        process_tasks(tasks, num_tasks);
        free_tasks(tasks);
    }
    return 0;
}
