typedef struct {
    void* data;
    size_t element_size;
    size_t capacity;
    size_t count;
} StreamingList;

StreamingList* create_streaming_list(size_t initial_capacity, size_t element_size) {
    StreamingList* list = (StreamingList*)malloc(sizeof(StreamingList));
    list->data = malloc(initial_capacity * element_size);
    list->element_size = element_size;
    list->capacity = initial_capacity;
    list->count = 0;
    return list;
}

void resize_streaming_list(StreamingList* list) {
    size_t new_capacity = (size_t)(list->capacity * RESIZE_FACTOR);
    void* new_data = realloc(list->data, new_capacity * list->element_size);
    if (new_data == NULL) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    list->data = new_data;
    list->capacity = new_capacity;
}

void add_element(StreamingList* list, void* element) {
    if (list->count >= list->capacity) {
        resize_streaming_list(list);
    }
    memcpy((char*)list->data + list->count * list->element_size, element, list->element_size);
    list->count++;
}

void cleanup_streaming_list(StreamingList* list) {
    free(list->data);
    list->data = NULL;
    list->capacity = 0;
    list->count = 0;
}

// Additional functions for processing and displaying data would go here

int main() {
    StreamingList* int_list = create_streaming_list(MAX_ELEMENTS, sizeof(long));
    StreamingList* float_list = create_streaming_list(MAX_ELEMENTS, sizeof(float));

    // Example usage of the streaming list
    long int_value = 42;
    add_element(int_list, &int_value);

    float float_value = 3.14f;
    add_element(float_list, &float_value);

    cleanup_streaming_list(int_list);
    cleanup_streaming_list(float_list);

    return 0;
}
