        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    r->count = 0;

    time_t now = time(NULL);
    for (int i = 0; i < MAX_PROJECTS; i++) {
        project *p = &r->projects[i];
        p->priority = i + 1;
        p->status = strdup("Pending");
        if (!p->status) {
            fprintf(stderr, "Memory allocation failed\n");
            manageProjectList_dealloc(r);
            return NULL;
        }
        p->deadline = now + (i * 86400); // Example deadline calculation
        p->start_date = now;

        r->count++;
    }

    return r;
}

void manageProjectList_dealloc(record *r) {
    for (int i = 0; i < r->count; i++) {
        free(r->projects[i].status);
    }
    free(r);
}

void updateProjectStatuses(record *r) {
    time_t now = time(NULL);
    for (int i = 0; i < r->count; i++) {
        project *p = &r->projects[i];
        double duration = difftime(p->deadline, p->start_date);
        double elapsed = difftime(now, p->start_date);

        if (elapsed > duration / 2) {
            p->status = strdup("Late");
        } else if (elapsed > 0) {
            p->status = strdup("In Progress");
        }
    }
}

void populateRandomValues(record *r, int min_value, int max_value) {
    srand(time(NULL));
    for (int i = 0; i < r->count; i++) {
        project *p = &r->projects[i];
        p->value = rand() % (max_value - min_value + 1) + min_value;
    }
}

