#include <pthread.h>

#define MAX_SESSIONS 1000
#define SESSION_CHUNK_SIZE 100

typedef struct Device {
    char ip[16];
    time_t last_active;
    int device_id;
} Device;

typedef struct Session {
    int session_id;
    time_t timestamp;
    Device* devices;
    int device_count;
    int max_devices;
} Session;

typedef struct SessionList {
    Session** sessions;
    int count;
    int capacity;
    pthread_mutex_t lock;
} SessionList;

SessionList* create_session_list() {
    SessionList* list = (SessionList*)malloc(sizeof(SessionList));
    if (!list) return NULL;
    list->sessions = (Session**)calloc(SESSION_CHUNK_SIZE, sizeof(Session*));
    if (!list->sessions) {
        free(list);
        return NULL;
    }
    list->count = 0;
    list->capacity = SESSION_CHUNK_SIZE;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_session_list(SessionList* list) {
    for (int i = 0; i < list->count; ++i) {
        free(list->sessions[i]->devices);
        free(list->sessions[i]);
    }
    free(list->sessions);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void update_session_timestamps(SessionList* list) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->count; ++i) {
        list->sessions[i]->timestamp = time(NULL);
    }
    pthread_mutex_unlock(&list->lock);
}

Session* create_session(int session_id, int max_devices) {
    Session* session = (Session*)malloc(sizeof(Session));
    if (!session) return NULL;
    session->session_id = session_id;
    session->timestamp = time(NULL);
    session->devices = (Device*)calloc(max_devices, sizeof(Device));
    if (!session->devices) {
        free(session);
        return NULL;
    }
    session->device_count = 0;
    session->max_devices = max_devices;
    return session;
}

void add_session(SessionList* list, Session* session) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        int new_capacity = list->capacity + SESSION_CHUNK_SIZE;
        Session** new_sessions = (Session**)realloc(list->sessions, new_capacity * sizeof(Session*));
        if (!new_sessions) {
            pthread_mutex_unlock(&list->lock);
            return; // Handle memory allocation failure
        }
        list->sessions = new_sessions;
        list->capacity = new_capacity;
    }
    list->sessions[list->count++] = session;
    pthread_mutex_unlock(&list->lock);
}

void resize_session_list(SessionList* list) {
    pthread_mutex_lock(&list->lock);
    int new_capacity = list->capacity * 1.2;
    Session** new_sessions = (Session**)realloc(list->sessions, new_capacity * sizeof(Session*));
    if (!new_sessions) {
        pthread_mutex_unlock(&list->lock);
        return; // Handle memory allocation failure
    }
    list->sessions = new_sessions;
    list->capacity = new_capacity;
    pthread_mutex_unlock(&list->lock);
}

void cleanup_session_list(SessionList* list) {
    destroy_session_list(list);
}
