#include <string.h>

#define MAX_N 1000

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

int load_and_populate_list(const char* file_path, NFAPI_CRC_INDICATION_PDU_T** list, int* count) {
    if (count == NULL || *count < 1 || *count > MAX_N) {
        return -1; // Invalid count
    }

    FILE* file = fopen(file_path, "r");
    if (!file) {
        perror("Failed to open file");
        return -2; // File opening error
    }

    *list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(*count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*list == NULL) {
        fclose(file);
        perror("Memory allocation failed");
        return -3; // Memory allocation error
    }

    int loaded_count = 0;
    while (loaded_count < *count && fscanf(file, "%d %hu %d", 
                                          &(*list)[loaded_count].ue_info_tag,
                                          &(*list)[loaded_count].rnti,
                                          &(*list)[loaded_count].crc_indication_rel8_tag.crcflag) == 3) {
        loaded_count++;
    }

    fclose(file);

    if (loaded_count != *count) {
        free(*list);
        return -4; // Incomplete data loading
    }

    qsort(*list, loaded_count, sizeof(NFAPI_CRC_INDICATION_PDU_T), 
          [](const void* a, const void* b) -> int {
              return ((NFAPI_CRC_INDICATION_PDU_T*)a)->rnti - ((NFAPI_CRC_INDICATION_PDU_T*)b)->rnti;
          });

    *count = loaded_count;
    return 0; // Success
}

void free_list(NFAPI_CRC_INDICATION_PDU_T* list, int count) {
    if (list != NULL) {
        free(list);
    }
}
