    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicCollection_T;

DynamicCollection_T* create_collection(size_t initial_capacity) {
    DynamicCollection_T *collection = (DynamicCollection_T*)malloc(sizeof(DynamicCollection_T));
    if (!collection) return NULL;

    collection->data = (PHY_TRANSPORT_CHANNEL_PDU_T*)calloc(initial_capacity, sizeof(PHY_TRANSPORT_CHANNEL_PDU_T));
    if (!collection->data) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void destroy_collection(DynamicCollection_T *collection) {
    pthread_mutex_lock(&collection->lock);
    free(collection->data);
    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int add_pdu(DynamicCollection_T *collection, PHY_TRANSPORT_CHANNEL_PDU_T pdu) {
    pthread_mutex_lock(&collection->lock);

    if (collection->size >= collection->capacity) {
        size_t new_capacity = collection->capacity ? collection->capacity * 2 : 1;
        PHY_TRANSPORT_CHANNEL_PDU_T *new_data = (PHY_TRANSPORT_CHANNEL_PDU_T*)realloc(collection->data, new_capacity * sizeof(PHY_TRANSPORT_CHANNEL_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Memory allocation failed
        }
        collection->data = new_data;
        collection->capacity = new_capacity;
    }

    collection->data[collection->size++] = pdu;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

int filter_collection(DynamicCollection_T *collection, int min_format_version) {
    pthread_mutex_lock(&collection->lock);

    size_t i = 0, j = 0;
    while (i < collection->size) {
        if (collection->data[i].FORMAT_VERSION >= min_format_version) {
            collection->data[j++] = collection->data[i];
        }
        i++;
    }
    collection->size = j;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

