} NetworkManager;

void initialize_connection_pool(ConnectionPool *pool) {
    pthread_mutex_init(&pool->lock, NULL);
    pool->size = 0;
}

void add_connection_to_pool(ConnectionPool *pool, NetworkConnection *connection) {
    pthread_mutex_lock(&pool->lock);
    if (pool->size < MAX_CONNECTIONS) {
        pool->connections[pool->size++] = connection;
    }
    pthread_mutex_unlock(&pool->lock);
}

NetworkConnection* get_connection_from_pool(ConnectionPool *pool, int socket_descriptor) {
    NetworkConnection *connection = NULL;
    pthread_mutex_lock(&pool->lock);
    for (int i = 0; i < pool->size; i++) {
        if (pool->connections[i]->socket_descriptor == socket_descriptor) {
            connection = pool->connections[i];
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);
    return connection;
}

void remove_connection_from_pool(ConnectionPool *pool, int socket_descriptor) {
    pthread_mutex_lock(&pool->lock);
    for (int i = 0; i < pool->size; i++) {
        if (pool->connections[i]->socket_descriptor == socket_descriptor) {
            free(pool->connections[i]);
            for (int j = i; j < pool->size - 1; j++) {
                pool->connections[j] = pool->connections[j + 1];
            }
            pool->size--;
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

