    public HtmlContentManager(long[] offsets, int[] keys, ILogger<HtmlContentManager> logger, IIdentityProvider identityProvider, IServiceClass serviceClass, INotificationSystem notificationSystem, IAnalyticsService analyticsService, ICachingMechanism cachingMechanism)
