#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    unsigned long reallocations;
} ArrayManager;

ArrayManager* create_array_manager(size_t initial_capacity) {
    ArrayManager* manager = (ArrayManager*)malloc(sizeof(ArrayManager));
    if (!manager) return NULL;

    manager->records = (Record*)calloc(initial_capacity, sizeof(Record));
    if (!manager->records) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    manager->reallocations = 0;

    return manager;
}

void destroy_array_manager(ArrayManager* manager) {
    if (manager) {
        free(manager->records);
        pthread_mutex_destroy(&manager->mutex);
        free(manager);
    }
}

void resize_array_manager(ArrayManager* manager) {
    size_t new_capacity = manager->capacity * 2;
    Record* new_records = (Record*)realloc(manager->records, new_capacity * sizeof(Record));
    if (!new_records) return;

    manager->records = new_records;
    manager->capacity = new_capacity;
    manager->reallocations++;
}

void add_record(ArrayManager* manager, int value) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->size == manager->capacity) {
        resize_array_manager(manager);
    }
    manager->records[manager->size].value = value;
    manager->size++;
    pthread_mutex_unlock(&manager->mutex);
}

void log_reallocations(ArrayManager* manager) {
    printf("Total reallocations: %lu\n", manager->reallocations);
}

int main() {
    ArrayManager* manager = create_array_manager(10);

    srand(time(NULL));
    for (size_t i = 0; i < 20; i++) {
        add_record(manager, rand());
    }

    log_reallocations(manager);
    destroy_array_manager(manager);

    return 0;
}
