#include <iostream>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <chrono>
#include <queue>
#include <unordered_map>
#include <atomic>

class NetworkConnection {
public:
    int socketDescriptor;
    std::string clientIP;
    bool connectionStatus;
    std::chrono::time_point<std::chrono::system_clock> lastHealthCheck;
    int uniqueIdentifier;

    NetworkConnection(int sd, const std::string& ip, bool status)
        : socketDescriptor(sd), clientIP(ip), connectionStatus(status), lastHealthCheck(std::chrono::system_clock::now()), uniqueIdentifier(nextID++) {}

private:
    static int nextID;
};

int NetworkConnection::nextID = 0;

class ConnectionManager {
public:
    void addConnection(int sd, const std::string& ip, bool status) {
        std::lock_guard<std::mutex> lock(mutex);
        connections.push_back(NetworkConnection(sd, ip, status));
        healthCheckQueue.push(&connections.back());
    }

    void removeConnection(int id) {
        std::lock_guard<std::mutex> lock(mutex);
        for (auto it = connections.begin(); it != connections.end(); ++it) {
            if (it->uniqueIdentifier == id) {
                connections.erase(it);
                break;
            }
        }
    }

    void updateHealthCheck(int id) {
        std::lock_guard<std::mutex> lock(mutex);
        for (auto& conn : connections) {
            if (conn.uniqueIdentifier == id) {
                conn.lastHealthCheck = std::chrono::system_clock::now();
                healthCheckQueue.push(&conn);
                break;
            }
        }
    }

private:
    std::vector<NetworkConnection> connections;
    std::priority_queue<NetworkConnection*, std::vector<NetworkConnection*>, HealthCheckComparator> healthCheckQueue;
    std::mutex mutex;
};

class HealthCheckComparator {
public:
    bool operator()(const NetworkConnection* a, const NetworkConnection* b) {
        return a->lastHealthCheck < b->lastHealthCheck;
    }
};
