use tokio::task;
use rand::{RngCore, SeedableRng};
use rand::rngs::MersenneTwister;
use std::sync::{Arc, Mutex};
use std::collections::HashMap;

struct MAC_PDU {
    header: L2Header,
    payload: Vec<u8>,
}

impl MAC_PDU {
    fn new(header: L2Header, payload_size: usize) -> Self {
        let payload = vec![0; payload_size];
        MAC_PDU { header, payload }
    }

    fn destroy(self) {
        // Handle resource cleanup
    }
}

struct L2Header;

struct BufferPool {
    pool: Vec<Vec<u8>>,
    used_buffers: HashMap<usize, bool>,
}

impl BufferPool {
    fn new(buffer_size: usize, num_buffers: usize) -> Self {
        let mut pool = Vec::new();
        for _ in 0..num_buffers {
            pool.push(vec![0; buffer_size]);
        }
        BufferPool {
            pool,
            used_buffers: HashMap::new(),
        }
    }

    fn get_buffer(&mut self) -> Option<Vec<u8>> {
        if let Some((index, false)) = self.used_buffers.iter().find(|&(_, &used)| !used) {
            *self.used_buffers.get_mut(index).unwrap() = true;
            Some(self.pool[*index].clone())
        } else if let Some(buffer) = self.pool.pop() {
            self.used_buffers.insert(self.pool.len(), false);
            Some(buffer)
        } else {
            None
        }
    }

    fn release_buffer(&mut self, buffer: Vec<u8>) {
        if let Some(index) = self.pool.iter().position(|b| b == &buffer) {
            *self.used_buffers.get_mut(&index).unwrap() = false;
        }
    }
}

async fn execute_function(function_name: String, args: Vec<String>, rng: Arc<Mutex<MersenneTwister>>, buffer_pool: Arc<Mutex<BufferPool>>) {
    match function_name.as_str() {
        "generate_random_numbers" => generate_random_numbers(args, rng),
        "process_mac_pdu" => process_mac_pdu(args, buffer_pool),
        _ => println!("Unknown function"),
    }
}

async fn generate_random_numbers(args: Vec<String>, rng: Arc<Mutex<MersenneTwister>>) {
    let count = args[0].parse::<u32>().unwrap();
    for _ in 0..count {
        let mut rng_lock = rng.lock().await;
        let random_number = rng_lock.next_u64();
        println!("Random Number: {}", random_number);
    }
}

async fn process_mac_pdu(args: Vec<String>, buffer_pool: Arc<Mutex<BufferPool>>) {
    let payload_size = args[0].parse::<usize>().unwrap();
    let mut buffer_pool_lock = buffer_pool.lock().await;
    if let Some(payload) = buffer_pool_lock.get_buffer() {
        let header = L2Header;
        let mac_pdu = MAC_PDU::new(header, payload_size);
        // Process the MAC_PDU
        mac_pdu.destroy();
        buffer_pool_lock.release_buffer(payload);
    } else {
        println!("Buffer pool exhausted");
    }
}

#[tokio::main]
async fn main() {
    let rng = Arc::new(Mutex::new(MersenneTwister::from_entropy()));
    let buffer_pool = Arc::new(Mutex::new(BufferPool::new(1024, 100)));

    let args: Vec<String> = std::env::args().skip(1).collect();
    if let Some(function_name) = args.get(0) {
        execute_function(function_name.clone(), args[1..].to_vec(), rng, buffer_pool).await;
    } else {
        println!("No function specified");
    }
}
