#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int id;
    time_t last_activity;
    char *buffer;
    size_t buffer_size;
    char src_ip[16];
    char dest_ip[16];
} NetworkConnection;

typedef struct {
    NetworkConnection **connections;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} ConnectionManager;

void init_connection_manager(ConnectionManager *manager, size_t initial_capacity) {
    manager->connections = (NetworkConnection **)malloc(initial_capacity * sizeof(NetworkConnection *));
    memset(manager->connections, 0, initial_capacity * sizeof(NetworkConnection *));
    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

void destroy_connection_manager(ConnectionManager *manager) {
    for (size_t i = 0; i < manager->size; ++i) {
        free(manager->connections[i]->buffer);
        free(manager->connections[i]);
    }
    free(manager->connections);
    pthread_mutex_destroy(&manager->lock);
}

int add_connection(ConnectionManager *manager, NetworkConnection *connection) {
    pthread_mutex_lock(&manager->lock);
    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity ? manager->capacity * 2 : 1;
        NetworkConnection **new_connections = (NetworkConnection **)realloc(manager->connections, new_capacity * sizeof(NetworkConnection *));
        if (!new_connections) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->connections = new_connections;
        manager->capacity = new_capacity;
    }
    manager->connections[manager->size++] = connection;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

NetworkConnection *get_connection(ConnectionManager *manager, int id) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->connections[i]->id == id) {
            NetworkConnection *connection = manager->connections[i];
            pthread_mutex_unlock(&manager->lock);
            return connection;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

void remove_connection(ConnectionManager *manager, int id) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->connections[i]->id == id) {
            free(manager->connections[i]->buffer);
            free(manager->connections[i]);
            memmove(&manager->connections[i], &manager->connections[i + 1], (manager->size - i - 1) * sizeof(NetworkConnection *));
            manager->size--;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}
