void revoke_compromised_token(int session_id) {
    // Revoke compromised token logic here
}

int add_session(int session_id, const char* auth_token, int expiration_policy) {
    pthread_mutex_lock(&session_lock);
    if (session_count >= MAX_SESSIONS) {
        pthread_mutex_unlock(&session_lock);
        return -1; // Session pool full
    }
    sessions[session_count].session_id = session_id;
    strncpy(sessions[session_count].auth_token, auth_token, sizeof(sessions[session_count].auth_token));
    sessions[session_count].last_active = time(NULL);
    sessions[session_count].expiration_policy = expiration_policy;
    session_count++;
    pthread_mutex_unlock(&session_lock);
    return 0;
}

void update_session(int session_id) {
    pthread_mutex_lock(&session_lock);
    for (int i = 0; i < session_count; i++) {
        if (sessions[i].session_id == session_id) {
            sessions[i].last_active = time(NULL);
            break;
        }
    }
    pthread_mutex_unlock(&session_lock);
}

void remove_session(int session_id) {
    pthread_mutex_lock(&session_lock);
    for (int i = 0; i < session_count; i++) {
        if (sessions[i].session_id == session_id) {
            sessions[i] = sessions[session_count - 1];
            session_count--;
            break;
        }
    }
    pthread_mutex_unlock(&session_lock);
}

void check_session_activity() {
    time_t now = time(NULL);
    for (int i = 0; i < session_count; i++) {
        if (now - sessions[i].last_active > sessions[i].expiration_policy) {
            remove_session(sessions[i].session_id);
            log_user_activity(sessions[i].session_id);
        }
    }
}

void* health_check_thread(void* arg) {
    while (1) {
        check_session_activity();
        revoke_compromised_token(123); // Example compromised token
        sleep(60); // Check every minute
    }
    return NULL;
}

