    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    newNode->value = value;
    newNode->next = NULL;
    return newNode;
}

void appendNode(Node** head, double value) {
    Node* newNode = createNode(value);
    if (*head == NULL) {
        *head = newNode;
    } else {
        Node* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }
}

Node* findNodeByIndex(Node* head, int index) {
    if (index < 0) {
        return NULL;
    }
    Node* temp = head;
    for (int i = 0; i < index && temp != NULL; i++) {
        temp = temp->next;
    }
    return temp;
}

void printListReverse(Node* head) {
    if (head == NULL) {
        return;
    }
    printListReverse(head->next);
    printf("%.2f ", head->value);
}

int main() {
    Node* head = NULL;

    appendNode(&head, 1.1);
    appendNode(&head, 2.2);
    appendNode(&head, 3.3);

    Node* nodeAtIndex = findNodeByIndex(head, 1);
    if (nodeAtIndex != NULL) {
        printf("Value at index 1: %.2f\n", nodeAtIndex->value);
    }

    printf("List in reverse order: ");
    printListReverse(head);
    printf("\n");

    return 0;
}
