typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct List {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
} List;

void initList(List* list) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void insertNode(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) return; // Handle memory allocation failure

    newNode->data = data;
    pthread_mutex_lock(&list->lock);

    if (list->head == NULL) {
        list->head = newNode;
        list->tail = newNode;
        newNode->prev = NULL;
        newNode->next = NULL;
    } else {
        list->tail->next = newNode;
        newNode->prev = list->tail;
        newNode->next = NULL;
        list->tail = newNode;
    }

    pthread_mutex_unlock(&list->lock);
}

void validateAndSetCRCFlag(List* list, int minRNTI, int maxRNTI) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI >= minRNTI && current->data.RNTI <= maxRNTI) {
            // Simulate CRC check
            int crcCheckResult = 1; // Assume CRC check passes

            if (crcCheckResult == 0) {
                current->data.CRCFLAG = 0;
            } else {
                current->data.CRCFLAG = 1;
            }
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void garbageCollect(List* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        if (current->data.CRCFLAG == 0) {
            Node* temp = current;
            current = current->next;

            // Simulate memory reclamation
            free(temp);
        } else {
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void destroyList(List* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    list->head = NULL;
    list->tail = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
