import java.time.Instant;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class NCUService {
    private final ConcurrentLinkedQueue<NCURecord> queue = new ConcurrentLinkedQueue<>();
    private final ExecutorService executorService = Executors.newFixedThreadPool(10);

    public void processBatch(NCURecord[] records) {
        for (NCURecord record : records) {
            assignRandomTimestamp(record);
            queue.add(record);
        }
        startProcessing();
    }

    private void assignRandomTimestamp(NCURecord record) {
        Instant now = Instant.now();
        long timestamp = now.getEpochSecond() * 1000 + now.getNano() / 1_000_000;
        record.setTimestamp(timestamp);
    }

    private void startProcessing() {
        while (!queue.isEmpty()) {
            NCURecord record = queue.poll();
            executorService.submit(() -> processNCU(record));
        }
        executorService.shutdown();
        try {
            executorService.awaitTermination(1, TimeUnit.HOURS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    private void processNCU(NCURecord record) {
        // Process the NCU record
    }

    public static class NCURecord {
        private long timestamp;
        private String id;
        private boolean status;

        public void setTimestamp(long timestamp) {
            this.timestamp = timestamp;
        }

        public void setId(String id) {
            this.id = id;
        }

        public void setStatus(boolean status) {
            this.status = status;
        }
    }
}
