    L2Header l2_header;
    unsigned char *payload;
    size_t payload_size;
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} MAC_PDU;

int initializeMACPDUs(MAC_PDU **mac_pdu_array, size_t num_pdus) {
    srand(time(NULL)); // Seed for random number generation

    *mac_pdu_array = (MAC_PDU *)malloc(num_pdus * sizeof(MAC_PDU));
    if (*mac_pdu_array == NULL) {
        return -1; // Memory allocation failed
    }

    int success_count = 0;
    for (size_t i = 0; i < num_pdus; ++i) {
        (*mac_pdu_array)[i].payload = (unsigned char *)malloc(MAX_PAYLOAD_SIZE);
        if ((*mac_pdu_array)[i].payload == NULL) {
            // Free previously allocated memory and return failure
            for (size_t j = 0; j < i; ++j) {
                free((*mac_pdu_array)[j].payload);
            }
            free(*mac_pdu_array);
            return -1;
        }

        // Initialize L2Header, payload, RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
