        NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(crc_indication_array, max_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&mutex);
