typedef struct {
    int value;
} Record;

void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void deallocate_memory(void* ptr) {
    free(ptr);
}

long* generate_offsets(long max_offset, int n) {
    long* offsets = allocate_memory(n * sizeof(long));
    for (int i = 0; i < n; i++) {
        offsets[i] = i % max_offset;
    }
    return offsets;
}

int* generate_keys(long* offsets, int n) {
    int* keys = allocate_memory(n * sizeof(int));
    // Custom sorting algorithm to find suitable keys
    for (int i = 0; i < n; i++) {
        keys[i] = rand() % offsets[i];
    }
    return keys;
}

Record* initialize_records(int n, int min_value, int max_value) {
    Record* records = allocate_memory(n * sizeof(Record));
    // Initialize records with random integers within the specified range
    for (int i = 0; i < n; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }
    return records;
}

EVP_CIPHER_CTX* initialize_cipher(const char* key, const char* iv) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        exit(EXIT_FAILURE);
    }
    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        fprintf(stderr, "Failed to initialize cipher\n");
        EVP_CIPHER_CTX_free(ctx);
        exit(EXIT_FAILURE);
    }
    return ctx;
}

void cleanup_cipher(EVP_CIPHER_CTX* ctx) {
    EVP_CIPHER_CTX_free(ctx);
}

void deallocate_all_memory(long* offsets, int* keys, Record* records, EVP_CIPHER_CTX* ctx) {
    deallocate_memory(offsets);
    deallocate_memory(keys);
    deallocate_memory(records);
    if (ctx) {
        cleanup_cipher(ctx);
    }
}
