#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 10000
#define MEMORY_THRESHOLD 5000000 // 5MB
#define FLOAT_RANGE_MIN -1.0f
#define FLOAT_RANGE_MAX 1.0f

typedef struct {
    long offset;
    int key;
    float value;
} Record;

typedef struct {
    Record *records[MAX_RECORDS];
    int count;
    pthread_mutex_t lock;
} RecordSet;

RecordSet record_set = { .lock = PTHREAD_MUTEX_INITIALIZER };

void log_message(const char *message) {
    time_t now = time(NULL);
    fprintf(stderr, "%s: %s\n", ctime(&now), message);
}

int initialize_records(const char *csv_file, const char *log_file) {
    FILE *file = fopen(csv_file, "r");
    if (!file) {
        log_message("Failed to open CSV file.");
        return -1;
    }

    RecordSet *set = &record_set;
    pthread_mutex_lock(&set->lock);

    while (set->count < MAX_RECORDS && set->count < MEMORY_THRESHOLD / sizeof(Record)) {
        Record *record = malloc(sizeof(Record));
        if (!record) {
            log_message("Failed to allocate memory for record.");
            break;
        }

        if (fscanf(file, "%ld,%d,%f", &record->offset, &record->key, &record->value) != 3) {
            free(record);
            log_message("Malformed data in CSV file.");
            break;
        }

        set->records[set->count++] = record;
    }

    pthread_mutex_unlock(&set->lock);
    fclose(file);

    return set->count;
}

Record* get_record(int index) {
    RecordSet *set = &record_set;
    pthread_mutex_lock(&set->lock);
    if (index < 0 || index >= set->count) {
        pthread_mutex_unlock(&set->lock);
        return NULL;
    }
    Record *record = set->records[index];
    pthread_mutex_unlock(&set->lock);
    return record;
}

void validate_records() {
    RecordSet *set = &record_set;
    pthread_mutex_lock(&set->lock);

    for (int i = 0; i < set->count; i++) {
        Record *record = set->records[i];
        if (record->offset < 0 || record->key < 0 || record->value < FLOAT_RANGE_MIN || record->value > FLOAT_RANGE_MAX) {
            log_message("Invalid record found.");
            // Optionally, reinitialize or prompt for manual intervention
        }
    }

    pthread_mutex_unlock(&set->lock);
}

void *memory_monitor(void *arg) {
    while (1) {
        validate_records();
        sleep(60); // Validate every minute
    }
    return NULL;
}

int main() {
    const char *csv_file = "data.csv";
    const char *log_file = "app.log";

    int num_records = initialize_records(csv_file, log_file);
    if (num_records < 0) {
        return -1;
    }

    pthread_t monitor_thread;
    pthread_create(&monitor_thread, NULL, memory_monitor, NULL);

    // Example usage
    Record *record = get_record(0);
    if (record) {
        printf("Offset: %ld, Key: %d, Value: %f\n", record->offset, record->key, record->value);
    }

    pthread_join(monitor_thread, NULL);
    return 0;
}
