    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} MAC_PDU;

typedef struct {
    MAC_PDU *entries[MAX_ENTRIES];
    size_t count;
    size_t hash_table[MAX_ENTRIES];
} DynamicArray;

DynamicArray* init_dynamic_array() {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;
    array->count = 0;
    for (size_t i = 0; i < MAX_ENTRIES; ++i) {
        array->entries[i] = NULL;
        array->hash_table[i] = -1;
    }
    srand(time(NULL));
    return array;
}

void free_dynamic_array(DynamicArray *array) {
    if (!array) return;
    for (size_t i = 0; i < MAX_ENTRIES; ++i) {
        if (array->entries[i]) {
            free(array->entries[i]->payload);
            free(array->entries[i]);
        }
    }
    free(array);
}

int add_mac_pdu(DynamicArray *array, MAC_PDU *pdu) {
    if (!array || !pdu || array->count >= MAX_ENTRIES) return -1;
    size_t hash = pdu->RX_UE_INFORMATION_TAG % MAX_ENTRIES;
    while (array->hash_table[hash] != -1 && array->entries[array->hash_table[hash]]->RX_UE_INFORMATION_TAG != pdu->RX_UE_INFORMATION_TAG) {
        hash = (hash + 1) % MAX_ENTRIES;
    }
    if (array->hash_table[hash] == -1) {
        array->hash_table[hash] = array->count;
        array->entries[array->count++] = pdu;
        return 0;
    }
    return -1; // Duplicate entry
}

MAC_PDU* get_mac_pdu(DynamicArray *array, uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    if (!array) return NULL;
    size_t hash = RX_UE_INFORMATION_TAG % MAX_ENTRIES;
    while (array->hash_table[hash] != -1 && array->entries[array->hash_table[hash]]->RX_UE_INFORMATION_TAG != RX_UE_INFORMATION_TAG) {
        hash = (hash + 1) % MAX_ENTRIES;
    }
    if (array->hash_table[hash] == -1) return NULL;
    MAC_PDU *pdu = array->entries[array->hash_table[hash]];
    if (pdu->RNTI != RNTI) return NULL;
    return pdu;
}

int main() {
