InitResult* initialize_records(int num_records, long min_offset, long max_offset, int min_key, int max_key, int min_value, int max_value) {
    if (num_records <= 0 || min_offset > max_offset || min_key > max_key || min_value > max_value) {
        return NULL;
    }

    InitResult *result = (InitResult *)malloc(sizeof(InitResult));
    if (!result) {
        return NULL;
    }

    result->offsets = (long *)malloc(num_records * sizeof(long));
    result->keys = (int *)malloc(num_records * sizeof(int));
    result->records = (Record *)malloc(num_records * sizeof(Record));

    if (!result->offsets || !result->keys || !result->records) {
        free(result);
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_records; ++i) {
        result->offsets[i] = min_offset + rand() % (max_offset - min_offset + 1);
        result->keys[i] = min_key + rand() % (max_key - min_key + 1);

