} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t size;
    uint32_t *tag_hash_table;
    size_t tag_hash_size;
} NFAPI_LIST_T;

int napi_list_init(NFAPI_LIST_T *list) {
    list->capacity = 0;
    list->size = 0;
    list->data = NULL;
    list->tag_hash_table = NULL;
    list->tag_hash_size = 0;
    return 0;
}

void napi_list_free(NFAPI_LIST_T *list) {
    free(list->data);
    free(list->tag_hash_table);
    list->capacity = 0;
    list->size = 0;
    list->data = NULL;
    list->tag_hash_table = NULL;
    list->tag_hash_size = 0;
}

int napi_list_add(NFAPI_LIST_T *list, uint32_t tag, uint16_t rnti) {
    if (list->size >= MAX_LIST_SIZE) return -1; // List is full

    // Check for unique RX_UE_INFORMATION_TAG
    if (napi_list_contains_tag(list, tag)) return -2;

    // Find a free slot or reallocate if necessary
    if (list->size == list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) return -3; // Memory allocation failed
        list->data = new_data;
        list->capacity = new_capacity;

        // Reallocate tag hash table if necessary
        size_t new_tag_hash_size = list->tag_hash_size ? list->tag_hash_size * 2 : 1;
        uint32_t *new_tag_hash_table = realloc(list->tag_hash_table, new_tag_hash_size * sizeof(uint32_t));
        if (!new_tag_hash_table) return -4; // Memory allocation failed
        list->tag_hash_table = new_tag_hash_table;
        list->tag_hash_size = new_tag_hash_size;

        // Initialize new entries in the tag hash table
        for (size_t i = list->size; i < list->capacity; ++i) {
            list->tag_hash_table[i] = 0;
        }
    }

    // Add new entry
    NFAPI_CRC_INDICATION_PDU_T *entry = &list->data[list->size];
    entry->RX_UE_INFORMATION_TAG = tag;
    entry->RNTI = rnti;
    entry->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    list->tag_hash_table[tag] = list->size;
    ++list->size;

    return 0;
}

bool napi_list_contains_tag(NFAPI_LIST_T *list, uint32_t tag) {
    if (tag >= list->tag_hash_size) return false; // Tag out of range
    return list->tag_hash_table[tag] != 0;
}

int napi_list_serialize(const NFAPI_LIST_T *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1; // File open failed

    size_t written = fwrite(&list->size, sizeof(size_t), 1, file);
    if (written != 1) goto error;

    written = fwrite(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->size, file);
    if (written != list->size) goto error;

    fclose(file);
    return 0;

error:
    fclose(file);
    return -2; // Write failed
}

int napi_list_deserialize(NFAPI_LIST_T *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1; // File open failed

    size_t read = fread(&list->size, sizeof(size_t), 1, file);
    if (read != 1) goto error;

    if (list->size > MAX_LIST_SIZE) {
        fclose(file);
        return -2; // List too large
    }

    // Reallocate list data and tag hash table
    NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, list->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) goto error;
    list->data = new_data;

    uint32_t *new_tag_hash_table = realloc(list->tag_hash_table, list->size * sizeof(uint32_t));
    if (!new_tag_hash_table) goto error;
    list->tag_hash_table = new_tag_hash_table;

    // Initialize tag hash table
    for (size_t i = 0; i < list->size; ++i) {
        list->tag_hash_table[i] = 0;
    }

    read = fread(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->size, file);
    if (read != list->size) goto error;

    fclose(file);
    return 0;

error:
    fclose(file);
    napi_list_free(list);
    return -3; // Read failed
}
