    // Derive key using SHA-256
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char*)password, strlen(password), hash);
    memcpy(cipher->key, hash, 32);

    // Generate IV
    if (!RAND_bytes(cipher->iv, sizeof(cipher->iv))) {
        free(cipher);
        return NULL;
    }

    // Initialize cipher context
    cipher->ctx = EVP_CIPHER_CTX_new();
    if (!cipher->ctx) {
        free(cipher);
        return NULL;
    }
    if (1 != EVP_EncryptInit_ex(cipher->ctx, EVP_aes_256_cbc(), NULL, cipher->key, cipher->iv)) {
        EVP_CIPHER_CTX_free(cipher->ctx);
        free(cipher);
        return NULL;
    }

    return cipher;
}

void cleanup_cipher(AES_Cipher *cipher) {
