['```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/pbkdf2.h>
#include <string.h>
#include <stdlib.h>

#define SALT_LEN 16
#define IV_LEN EVP_CIPHER_iv_length(EVP_aes_256_cbc)
#define KEY_LEN EVP_CIPHER_key_length(EVP_aes_256_cbc)

typedef struct {
    unsigned char salt[SALT_LEN];
    unsigned char key[KEY_LEN];
} EncryptionContext;

int derive_key(const char *password, size_t password_len, const unsigned char *salt, size_t salt_len, int iterations, unsigned char *key) {
    return PKCS5_PBKDF2_HMAC(password, password_len, salt, salt_len, iterations, EVP_sha256(), KEY_LEN, key);
}

int encrypt(const EncryptionContext *ctx, const unsigned char *plaintext, size_t plaintext_len, unsigned char *ciphertext, unsigned char *iv) {
    EVP_CIPHER_CTX *ctx_evp = EVP_CIPHER_CTX_new();
    if (!ctx_evp) return -1;

    if (1 != EVP_EncryptInit_ex(ctx_evp, EVP_aes_256_cbc(), NULL, ctx->key, iv)) {
        EVP_CIPHER_CTX_free(ctx_evp);
        return -1;
    }

    int len;
    if (1 != EVP_EncryptUpdate(ctx_evp, ciphertext, &len, plaintext, plaintext_len)) {
        EVP_CIPHER_CTX_free(ctx_evp);
        return -1;
    }
    int ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx_evp, ciphertext + len, &len)) {
        EVP_CIPHER_CTX_free(ctx_evp);
        return -1;
    }
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx_evp);
    return ciphertext_len;
}

int decrypt(const EncryptionContext *ctx, const unsigned char *ciphertext, size_t ciphertext_len, unsigned char *plaintext, unsigned char *iv) {
    EVP_CIPHER_CTX *ctx_evp = EVP_CIPHER_CTX_new();
    if (!ctx_evp) return -1;

    if (1 != EVP_DecryptInit_ex(ctx_evp, EVP_aes_256_cbc(), NULL, ctx->key, iv)) {
        EVP_CIPHER_CTX_free(ctx_evp);
        return -1;
    }

    int len;
    if (1 != EVP_DecryptUpdate(ctx_evp, plaintext, &len, ciphertext, ciphertext_len)) {
        EVP_CIPHER_CTX_free(ctx_evp);
        return -1;
    }
    int plaintext_len = len;

    if (1 != EVP_DecryptFinal_ex(ctx_evp, plaintext + len, &len)) {
        EVP_CIPHER_CTX_free(ctx_evp);
        return -1;
    }
    plaintext_len += len;

    EVP_CIPHER_CTX_free(ctx_evp);
    return plaintext_len;
}

int generate_iv(unsigned char *iv) {
    return RAND_bytes(iv, IV_LEN);
}

EncryptionContext* create_encryption_context(const char *password, size_t password_len, const unsigned char *salt, size_t salt_len, int iterations) {
    EncryptionContext *ctx = (EncryptionContext*)malloc(sizeof(EncryptionContext));
    if (!ctx) return NULL;

    if (derive_key(password, password_len, salt, salt_len, iterations, ctx->key) != 1) {
        free(ctx);
        return NULL;
    }

    memcpy(ctx->salt, salt, SALT_LEN);

    return ctx;
}

void destroy_encryption_context(EncryptionContext *ctx) {
    if (ctx) {
        free(ctx);
    }
}
