    Project** projects;
    size_t count;
    size_t capacity;
    size_t cache_size;
    char** status_cache;
} ProjectList;

Project* create_project(const char* desc, int prio, double time) {
    Project* proj = (Project*)malloc(sizeof(Project));
    if (proj == NULL) return NULL;
    proj->description = strdup(desc);
    proj->priority = prio;
    proj->completion_time = time;
    proj->status = (char*)malloc(20 * sizeof(char)); // Assuming status is at most 19 characters long
    if (proj->status == NULL) {
        free(proj->description);
        free(proj);
        return NULL;
    }
    strcpy(proj->status, "planned");
    return proj;
}

ProjectList* create_project_list(size_t initial_capacity, size_t cache_size) {
    ProjectList* list = (ProjectList*)malloc(sizeof(ProjectList));
    if (list == NULL) return NULL;
    list->projects = (Project**)malloc(initial_capacity * sizeof(Project*));
    if (list->projects == NULL) {
        free(list);
        return NULL;
    }
    list->count = 0;
    list->capacity = initial_capacity;
    list->cache_size = cache_size;
    list->status_cache = (char**)malloc(cache_size * sizeof(char*));
    if (list->status_cache == NULL) {
        free(list->projects);
        free(list);
        return NULL;
    }
    for (size_t i = 0; i < cache_size; ++i) {
        list->status_cache[i] = (char*)malloc(20 * sizeof(char));
        if (list->status_cache[i] == NULL) {
            for (size_t j = 0; j < i; ++j) free(list->status_cache[j]);
            free(list->projects);
            free(list->status_cache);
            free(list);
            return NULL;
        }
    }
    return list;
}

void update_project_status(ProjectList* list, size_t index, const char* new_status) {
    if (index >= list->count) return;
    strcpy(list->projects[index]->status, new_status);
    // Cache the status update
    if (list->cache_size > 0) {
        size_t cache_index = index % list->cache_size;
        free(list->status_cache[cache_index]);
        list->status_cache[cache_index] = strdup(new_status);
    }
}

void iterate_projects(ProjectList* list, void (*callback)(Project*)) {
    for (size_t i = 0; i < list->count; ++i) {
        callback(list->projects[i]);
    }
}

void free_project_list(ProjectList* list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->projects[i]->description);
        free(list->projects[i]->status);
        free(list->projects[i]);
    }
    for (size_t i = 0; i < list->cache_size; ++i) {
        free(list->status_cache[i]);
    }
    free(list->projects);
    free(list->status_cache);
    free(list);
}
