    double *values;
    DataEntry *entries;
} DataArrays;

DataArrays* initializeDataArrays(int num_entries, double min_value, double max_value,
                                  int min_length, int max_length,
                                  int min_metadata, int max_metadata) {
    srand(time(NULL));

    DataArrays *data = (DataArrays *)malloc(sizeof(DataArrays));
    if (!data) return NULL;

    data->values = (double *)calloc(num_entries, sizeof(double));
    if (!data->values) {
        free(data);
        return NULL;
    }

    data->entries = (DataEntry *)calloc(num_entries, sizeof(DataEntry));
    if (!data->entries) {
        free(data->values);
        free(data);
        return NULL;
    }

    for (int i = 0; i < num_entries; ++i) {
        data->values[i] = min_value + (max_value - min_value) * ((double)rand() / RAND_MAX);

        int name_length = min_length + rand() % (max_length - min_length + 1);
        snprintf(data->entries[i].name, sizeof(data->entries[i].name), "%.*s", name_length, "abcdefghijklmnopqrstuvwxyz");

        data->entries[i].metadata = (char *)malloc(256 * sizeof(char));
        if (!data->entries[i].metadata) {
            for (int j = 0; j < i; ++j) {
                free(data->entries[j].metadata);
            }
            free(data->values);
            free(data->entries);
            free(data);
            return NULL;
        }

        int metadata_value = min_metadata + rand() % (max_metadata - min_metadata + 1);
        snprintf(data->entries[i].metadata, 256, "%d", metadata_value);
    }

    return data;
}

void freeDataArrays(DataArrays *data) {
    if (!data) return;

    for (int i = 0; i < num_entries; ++i) {
        free(data->entries[i].metadata);
    }
    free(data->values);
    free(data->entries);
    free(data);
}
