#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char* description;
    int priority;
    double completion_time;
    char* status;
} Project;

typedef struct {
    Project** projects;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} ProjectList;

Project* create_project(const char* desc, int prio, double time) {
    Project* proj = (Project*)malloc(sizeof(Project));
    if (!proj) return NULL;
    proj->description = strdup(desc);
    proj->priority = prio;
    proj->completion_time = time;
    proj->status = NULL; // Status will be set later
    return proj;
}

void free_project(Project* proj) {
    free(proj->description);
    free(proj->status);
    free(proj);
}

ProjectList* create_project_list(size_t initial_capacity) {
    ProjectList* list = (ProjectList*)malloc(sizeof(ProjectList));
    if (!list) return NULL;
    list->projects = (Project**)calloc(initial_capacity, sizeof(Project*));
    if (!list->projects) {
        free(list);
        return NULL;
    }
    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_project_list(ProjectList* list) {
    for (size_t i = 0; i < list->size; ++i) {
        free_project(list->projects[i]);
    }
    free(list->projects);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_project(ProjectList* list, Project* proj) {
    pthread_mutex_lock(&list->lock);
    if (list->size == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        Project** new_projects = (Project**)realloc(list->projects, new_capacity * sizeof(Project*));
        if (!new_projects) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Allocation failed
        }
        list->projects = new_projects;
        list->capacity = new_capacity;
    }
    list->projects[list->size++] = proj;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void remove_project(ProjectList* list, size_t index) {
    pthread_mutex_lock(&list->lock);
    if (index >= list->size) {
        pthread_mutex_unlock(&list->lock);
        return; // Invalid index
    }
    free_project(list->projects[index]);
    for (size_t i = index; i < list->size - 1; ++i) {
        list->projects[i] = list->projects[i + 1];
    }
    --list->size;
    pthread_mutex_unlock(&list->lock);
}

void update_project_status(ProjectList* list, size_t index, const char* new_status) {
    pthread_mutex_lock(&list->lock);
    if (index >= list->size) {
        pthread_mutex_unlock(&list->lock);
        return; // Invalid index
    }
    free(list->projects[index]->status);
    list->projects[index]->status = strdup(new_status);
    pthread_mutex_unlock(&list->lock);
}

void* project_list_iterator(ProjectList* list, size_t* index) {
    pthread_mutex_lock(&list->lock);
    if (*index >= list->size) {
        *index = 0;
        pthread_mutex_unlock(&list->lock);
        return NULL; // End of iteration
    }
    Project* proj = list->projects[(*index)++];
    pthread_mutex_unlock(&list->lock);
    return proj;
}

size_t project_list_size(ProjectList* list) {
    size_t size;
    pthread_mutex_lock(&list->lock);
    size = list->size;
    pthread_mutex_unlock(&list->lock);
    return size;
}

void log_event(const char* message) {
    // Implement logging logic here
    printf("Log: %s\n", message);
}
