    size_t size;
    pthread_mutex_t lock;
} NFAPI_CRC_LIST_T;

NFAPI_CRC_LIST_T* create_crc_list(size_t initial_capacity) {
    NFAPI_CRC_LIST_T *list = (NFAPI_CRC_LIST_T*)malloc(sizeof(NFAPI_CRC_LIST_T));
    if (!list) return NULL;

    list->elements = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->elements) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_crc_list(NFAPI_CRC_LIST_T *list) {
    pthread_mutex_lock(&list->lock);
    free(list->elements);
    pthread_mutex_unlock(&list->lock);
    free(list);
}

int add_to_crc_list(NFAPI_CRC_LIST_T *list, RX_UE_INFORMATION_TAG ue_info, RNTI rnti) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_elements = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_elements) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->elements = new_elements;
        list->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T *element = &list->elements[list->size++];
    element->ue_info = ue_info;
    element->rnti = rnti;
    element->crc_indication.CRCFLAG = (rnti % 2 == 0) ? 1 : 0;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void iterate_crc_list(NFAPI_CRC_LIST_T *list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->size; ++i) {
        callback(list->elements[i]);
    }

    pthread_mutex_unlock(&list->lock);
}
