    unsigned char iv[IV_LENGTH];
} EncryptionContext;

int derive_key(const char *password, size_t password_len, unsigned char *salt, unsigned char *key) {
    return PKCS5_PBKDF2_HMAC(password, password_len, salt, SALT_LENGTH, 10000, EVP_sha256(), KEY_LENGTH, key);
}

int generate_iv(unsigned char *iv) {
    return RAND_bytes(iv, IV_LENGTH);
}

EncryptionContext* create_encryption_context(const char *password, size_t password_len) {
    EncryptionContext *ctx = malloc(sizeof(EncryptionContext));
    if (!ctx) return NULL;

    unsigned char salt[SALT_LENGTH];
    if (RAND_bytes(salt, SALT_LENGTH) != 1) {
        free(ctx);
        return NULL;
    }

    if (derive_key(password, password_len, salt, ctx->key) != 1) {
        free(ctx);
        return NULL;
    }

    if (generate_iv(ctx->iv) != 1) {
        free(ctx);
        return NULL;
    }

    return ctx;
}

void destroy_encryption_context(EncryptionContext *ctx) {
    free(ctx);
}

int encrypt_data(const EncryptionContext *ctx, const unsigned char *plaintext, size_t plaintext_len, unsigned char *ciphertext) {
    EVP_CIPHER_CTX *cipher_ctx = EVP_CIPHER_CTX_new();
    if (!cipher_ctx) return -1;

    if (EVP_EncryptInit_ex(cipher_ctx, EVP_aes_256_cbc(), NULL, ctx->key, ctx->iv) != 1) {
        EVP_CIPHER_CTX_free(cipher_ctx);
        return -1;
    }

    int len;
    if (EVP_EncryptUpdate(cipher_ctx, ciphertext, &len, plaintext, plaintext_len) != 1) {
        EVP_CIPHER_CTX_free(cipher_ctx);
        return -1;
    }
    size_t ciphertext_len = len;

    if (EVP_EncryptFinal_ex(cipher_ctx, ciphertext + len, &len) != 1) {
        EVP_CIPHER_CTX_free(cipher_ctx);
        return -1;
    }
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(cipher_ctx);
    return ciphertext_len;
}

int decrypt_data(const EncryptionContext *ctx, const unsigned char *ciphertext, size_t ciphertext_len, unsigned char *plaintext) {
    EVP_CIPHER_CTX *cipher_ctx = EVP_CIPHER_CTX_new();
    if (!cipher_ctx) return -1;

    if (EVP_DecryptInit_ex(cipher_ctx, EVP_aes_256_cbc(), NULL, ctx->key, ctx->iv) != 1) {
        EVP_CIPHER_CTX_free(cipher_ctx);
        return -1;
    }

    int len;
    if (EVP_DecryptUpdate(cipher_ctx, plaintext, &len, ciphertext, ciphertext_len) != 1) {
        EVP_CIPHER_CTX_free(cipher_ctx);
        return -1;
    }
    size_t plaintext_len = len;

    if (EVP_DecryptFinal_ex(cipher_ctx, plaintext + len, &len) != 1) {
        EVP_CIPHER_CTX_free(cipher_ctx);
        return -1;
    }
    plaintext_len += len;

    EVP_CIPHER_CTX_free(cipher_ctx);
    return plaintext_len;
}
