#define KEY_SIZE 32
#define IV_SIZE 16

typedef struct {
    unsigned char key[KEY_SIZE];
    unsigned char iv[IV_SIZE];
} CryptoKey;

CryptoKey derive_key(const char *password, size_t password_len, int iterations) {
    CryptoKey key;
    PBKDF2_HMAC_SHA512(password, password_len, NULL, 0, iterations, KEY_SIZE, key.key);
    RAND_bytes(key.iv, IV_SIZE);
    return key;
}

void encrypt_data(const CryptoKey *key, const unsigned char *plaintext, size_t plaintext_len, unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key->key, key->iv);
    EVP_EncryptUpdate(ctx, ciphertext, &ciphertext_len, plaintext, plaintext_len);
    unsigned char tag[16];
    int tag_len;
    EVP_EncryptFinal_ex(ctx, NULL, &tag_len);
    memcpy(ciphertext + plaintext_len, tag, tag_len);
    EVP_CIPHER_CTX_free(ctx);
}

void decrypt_data(const CryptoKey *key, const unsigned char *ciphertext, size_t ciphertext_len, unsigned char *plaintext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_DecryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key->key, key->iv);
    int plaintext_len;
    EVP_DecryptUpdate(ctx, plaintext, &plaintext_len, ciphertext, ciphertext_len - 16);
    unsigned char tag[16];
    memcpy(tag, ciphertext + ciphertext_len - 16, 16);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_TAG, 16, tag);
    EVP_DecryptFinal_ex(ctx, plaintext + plaintext_len, &plaintext_len);
    EVP_CIPHER_CTX_free(ctx);
}

