#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char *key;
    float value;
} Entry;

typedef struct {
    Entry **entries;
    size_t count;
    pthread_mutex_t lock;
} DataStructure;

DataStructure* init_data_structure(const char *directory, const char *filename) {
    // Check if web.config exists
    FILE *config_file = fopen("web.config", "r");
    if (!config_file) {
        return NULL;
    }
    fclose(config_file);

    // Open the file and read entries
    char filepath[256];
    snprintf(filepath, sizeof(filepath), "%s/%s", directory, filename);
    FILE *file = fopen(filepath, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    DataStructure *ds = malloc(sizeof(DataStructure));
    ds->entries = NULL;
    ds->count = 0;
    pthread_mutex_init(&ds->lock, NULL);

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Parse the key-value pair
        char *key = strtok(line, ":");
        if (!key) continue;
        key[strcspn(key, "\r\n")] = 0; // Remove newline characters

        float value;
        if (sscanf(strtok(NULL, ":"), "%f", &value) != 1) {
            continue;
        }

        // Allocate memory for the entry
        Entry *entry = malloc(sizeof(Entry));
        entry->key = strdup(key);
        entry->value = value;

        // Add the entry to the data structure
        ds->entries = realloc(ds->entries, (ds->count + 1) * sizeof(Entry *));
        ds->entries[ds->count++] = entry;
    }

    fclose(file);
    return ds;
}

void free_data_structure(DataStructure *ds) {
    for (size_t i = 0; i < ds->count; ++i) {
        free(ds->entries[i]->key);
        free(ds->entries[i]);
    }
    free(ds->entries);
    pthread_mutex_destroy(&ds->lock);
    free(ds);
}

void update_entry(DataStructure *ds, const char *key, float value) {
    pthread_mutex_lock(&ds->lock);
    for (size_t i = 0; i < ds->count; ++i) {
        if (strcmp(ds->entries[i]->key, key) == 0) {
            ds->entries[i]->value = value;
            break;
        }
    }
    pthread_mutex_unlock(&ds->lock);
}

Entry* get_entry(DataStructure *ds, const char *key) {
    pthread_mutex_lock(&ds->lock);
    for (size_t i = 0; i < ds->count; ++i) {
        if (strcmp(ds->entries[i]->key, key) == 0) {
            Entry *entry = malloc(sizeof(Entry));
            entry->key = strdup(ds->entries[i]->key);
            entry->value = ds->entries[i]->value;
            pthread_mutex_unlock(&ds->lock);
            return entry;
        }
    }
    pthread_mutex_unlock(&ds->lock);
    return NULL;
}
