#include <openssl/rsa.h>
#include <openssl/pem.h>
#include <openssl/sha.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>

#define DEFAULT_KEY_SIZE 2048
#define DEFAULT_CACHE_SIZE 100
#define DEFAULT_DIR "/var/lib/rsa_keys"
#define ROTATION_INTERVAL 3600 // 1 hour

typedef struct {
    RSA *key;
    char identifier[65];
} RSAKey;

typedef struct {
    RSAKey keys[DEFAULT_CACHE_SIZE];
    int count;
    pthread_mutex_t lock;
} RSACache;

RSACache cache = { .lock = PTHREAD_MUTEX_INITIALIZER };

void generate_key_identifier(const RSA *rsa, char *identifier) {
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char *)&rsa->n, sizeof(rsa->n), hash);
    for (int i = 0; i < SHA256_DIGEST_LENGTH; i++) {
        sprintf(identifier + i*2, "%02x", hash[i]);
    }
}

RSAKey *generate_rsa_key(int key_size) {
    RSA *rsa = RSA_new();
    BIGNUM *e = BN_new();
    BN_set_word(e, RSA_F4);
    if (RSA_generate_key_ex(rsa, key_size, e, NULL) != 1) {
        RSA_free(rsa);
        BN_free(e);
        return NULL;
    }
    BN_free(e);

    RSAKey *key = malloc(sizeof(RSAKey));
    key->key = rsa;
    generate_key_identifier(rsa, key->identifier);
    return key;
}

void cache_rsa_key(RSAKey *key) {
    pthread_mutex_lock(&cache.lock);
    if (cache.count < DEFAULT_CACHE_SIZE) {
        cache.keys[cache.count++] = *key;
    }
    pthread_mutex_unlock(&cache.lock);
}

RSAKey *get_cached_rsa_key(const char *identifier) {
    pthread_mutex_lock(&cache.lock);
    for (int i = 0; i < cache.count; i++) {
        if (strcmp(cache.keys[i].identifier, identifier) == 0) {
            pthread_mutex_unlock(&cache.lock);
            return &cache.keys[i];
        }
    }
    pthread_mutex_unlock(&cache.lock);
    return NULL;
}

void rotate_rsa_keys() {
    time_t now = time(NULL);
    for (int i = 0; i < cache.count; i++) {
        if (now - cache.keys[i].key->n.d > ROTATION_INTERVAL) {
            RSA_free(cache.keys[i].key);
            free(&cache.keys[i]);
            // Generate new key and update cache
        }
    }
}

void *rsa_key_manager(void *arg) {
    int key_size = *(int *)arg;
    RSAKey *key = get_cached_rsa_key("some_identifier");
    if (key == NULL) {
        key = generate_rsa_key(key_size);
        if (key != NULL) {
            cache_rsa_key(key);
        }
    }
    // Use the key for secure data transmission
    return NULL;
}

int main() {
    int key_size = DEFAULT_KEY_SIZE;
    pthread_t thread;
    pthread_create(&thread, NULL, rsa_key_manager, &key_size);
    pthread_join(thread, NULL);
    return 0;
}
