#define MAX_PROJECTS 1000
#define BUDGET_INCREMENT 10000.0
#define MAX_BUDGET 500000.0

typedef struct {
    double budget;
    char *status;
    time_t completion_deadline;
} Project;

Project project_list[MAX_PROJECTS];
int project_count = 0;

void initialize_project_list() {
    for (int i = 0; i < MAX_PROJECTS; i++) {
        project_list[i].budget = BUDGET_INCREMENT * (i + 1);
        if (project_list[i].budget > MAX_BUDGET) {
            project_list[i].budget = MAX_BUDGET;
        }
        project_list[i].status = strdup("Active");
        time_t now = time(NULL);
        project_list[i].completion_deadline = now + (i + 1) * 86400; // 24 hours increment
    }
    project_count = MAX_PROJECTS;
}

void update_project_status(int index, const char *new_status) {
    if (index >= 0 && index < project_count) {
        free(project_list[index].status);
        project_list[index].status = strdup(new_status);
        time_t now = time(NULL);
        if (strcmp(new_status, "Completed") == 0) {
            project_list[index].completion_deadline = now;
        } else if (strcmp(new_status, "Pending") == 0) {
            project_list[index].budget *= 1.2; // Example adjustment
        }
    }
}

void export_project_list(const char *filename) {
    FILE *file = fopen(filename, "w");
    if (file != NULL) {
        fprintf(file, "Budget,Status,Completion Deadline\n");
        for (int i = 0; i < project_count; i++) {
            fprintf(file, "%.2f,%s,%ld\n", project_list[i].budget, project_list[i].status, project_list[i].completion_deadline);
        }
        fclose(file);
    } else {
        printf("Error opening file for writing.\n");
    }
}

int main() {
    initialize_project_list();
    update_project_status(0, "Completed");
    export_project_list("projects.csv");
    return 0;
}
