#include <stdlib.h>
#include <time.h>

#define INITIAL_CAPACITY 100
#define MAX_CAPACITY 5000
#define GROWTH_INCREMENT 20
#define REFERENCE_THRESHOLD 15
#define CLEANUP_INTERVAL 60

typedef struct Record {
    int value;
    int ref_count;
    time_t timestamp;
} Record;

typedef struct Pool {
    Record** records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} Pool;

Pool* pool_init(size_t initial_capacity) {
    Pool* pool = (Pool*)malloc(sizeof(Pool));
    pool->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    pool->capacity = initial_capacity;
    pool->size = 0;
    pthread_mutex_init(&pool->lock, NULL);
    pthread_cond_init(&pool->cond, NULL);
    return pool;
}

void pool_resize(Pool* pool) {
    size_t new_capacity = pool->capacity * (1 + GROWTH_INCREMENT / 100.0);
    if (new_capacity > MAX_CAPACITY) {
        new_capacity = MAX_CAPACITY;
    }
    Record** new_records = (Record**)realloc(pool->records, new_capacity * sizeof(Record*));
    for (size_t i = pool->capacity; i < new_capacity; ++i) {
        new_records[i] = NULL;
    }
    pool->records = new_records;
    pool->capacity = new_capacity;
}

void pool_add_record(Pool* pool, int value) {
    pthread_mutex_lock(&pool->lock);
    if (pool->size == pool->capacity) {
        pool_resize(pool);
    }
    Record* record = (Record*)malloc(sizeof(Record));
    record->value = value;
    record->ref_count = 1;
    record->timestamp = time(NULL);
    pool->records[pool->size++] = record;
    pthread_cond_signal(&pool->cond);
    pthread_mutex_unlock(&pool->lock);
}

void pool_update_timestamp(Pool* pool, int index) {
    pthread_mutex_lock(&pool->lock);
    if (index >= 0 && index < pool->size) {
        pool->records[index]->timestamp = time(NULL);
    }
    pthread_mutex_unlock(&pool->lock);
}

void pool_cleanup(Pool* pool) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->size; ++i) {
        if (pool->records[i]->ref_count == 0 && time(NULL) - pool->records[i]->timestamp > REFERENCE_THRESHOLD * 60) {
            free(pool->records[i]);
            pool->records[i] = NULL;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

void* cleanup_thread(void* arg) {
    Pool* pool = (Pool*)arg;
    while (1) {
        sleep(CLEANUP_INTERVAL);
        pool_cleanup(pool);
    }
    return NULL;
}

void pool_load_records(Pool* pool, const char* data_source) {
    // Implement data loading logic here
}
