#include <stdlib.h>
#include <pthread.h>

#define MAX_PACKETS 1024
#define MAX_INTERFACES 32

typedef struct {
    int RX_TRANSPORT_CHANNEL_TAG;
    int CELL_ID;
    char TRANSPORT_BUFFER[1500];
} LTE_PHY_TRANSPORT_LAYER_RX_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    pthread_cond_t cond;
    LTE_PHY_TRANSPORT_LAYER_RX_PDU_T *pdu_list[MAX_PACKETS];
    int head, tail, count;
} PacketQueue;

void init_queue(PacketQueue *queue) {
    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->cond, NULL);
    queue->head = queue->tail = queue->count = 0;
}

void enqueue_packet(PacketQueue *queue, LTE_PHY_TRANSPORT_LAYER_RX_PDU_T *pdu) {
    pthread_mutex_lock(&queue->lock);
    while (queue->count == MAX_PACKETS) {
        pthread_cond_wait(&queue->cond, &queue->lock);
    }
    queue->pdu_list[queue->tail] = pdu;
    queue->tail = (queue->tail + 1) % MAX_PACKETS;
    queue->count++;
    pthread_cond_signal(&queue->cond);
    pthread_mutex_unlock(&queue->lock);
}

LTE_PHY_TRANSPORT_LAYER_RX_PDU_T *dequeue_packet(PacketQueue *queue) {
    LTE_PHY_TRANSPORT_LAYER_RX_PDU_T *pdu = NULL;
    pthread_mutex_lock(&queue->lock);
    while (queue->count == 0) {
        pthread_cond_wait(&queue->cond, &queue->lock);
    }
    pdu = queue->pdu_list[queue->head];
    queue->head = (queue->head + 1) % MAX_PACKETS;
    queue->count--;
    pthread_cond_signal(&queue->cond);
    pthread_mutex_unlock(&queue->lock);
    return pdu;
}

void free_queue(PacketQueue *queue) {
    pthread_mutex_lock(&queue->lock);
    for (int i = queue->head; i != queue->tail; i = (i + 1) % MAX_PACKETS) {
        free(queue->pdu_list[i]);
    }
    pthread_mutex_unlock(&queue->lock);
    pthread_mutex_destroy(&queue->lock);
    pthread_cond_destroy(&queue->cond);
}

void *network_interface_thread(void *arg) {
    PacketQueue *queue = (PacketQueue *)arg;
    // Simulate receiving packets
    for (int i = 0; i < MAX_PACKETS; i++) {
        LTE_PHY_TRANSPORT_LAYER_RX_PDU_T *pdu = malloc(sizeof(LTE_PHY_TRANSPORT_LAYER_RX_PDU_T));
        enqueue_packet(queue, pdu);
    }
    return NULL;
}

int main() {
    PacketQueue queue;
    init_queue(&queue);

    pthread_t threads[MAX_INTERFACES];
    for (int i = 0; i < MAX_INTERFACES; i++) {
        pthread_create(&threads[i], NULL, network_interface_thread, &queue);
    }

    for (int i = 0; i < MAX_INTERFACES; i++) {
        pthread_join(threads[i], NULL);
    }

    free_queue(&queue);

    return 0;
}
