    uint8_t CRC_INDICATION_REL8_TAG;
} ProtocolEntity;

typedef struct {
    ProtocolEntity *entities;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} ProtocolList;

ProtocolList* create_protocol_list() {
    ProtocolList *list = (ProtocolList*)malloc(sizeof(ProtocolList));
    list->entities = (ProtocolEntity*)calloc(INITIAL_CAPACITY, sizeof(ProtocolEntity));
    list->capacity = INITIAL_CAPACITY;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
