    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_entity(ProtocolList *list, ProtocolEntity entity) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        list->entities = (ProtocolEntity*)realloc(list->entities, new_capacity * sizeof(ProtocolEntity));
        list->capacity = new_capacity;
    }
    list->entities[list->size++] = entity;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_entity(ProtocolList *list, uint16_t RNTI) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->size; ++i) {
        if (list->entities[i].RNTI == RNTI) {
            for (size_t j = i; j < list->size - 1; ++j) {
                list->entities[j] = list->entities[j + 1];
            }
            --list->size;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return -1;
}

int serialize_list(ProtocolList *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    fwrite(&list->size, sizeof(size_t), 1, file);
    for (size_t i = 0; i < list->size; ++i) {
        fwrite(&list->entities[i], sizeof(ProtocolEntity), 1, file);
    }

    fclose(file);
    return 0;
}

int deserialize_list(ProtocolList *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    size_t size;
    fread(&size, sizeof(size_t), 1, file);

    pthread_mutex_lock(&list->lock);
    if (list->capacity < size) {
        list->entities = (ProtocolEntity*)realloc(list->entities, size * sizeof(ProtocolEntity));
        list->capacity = size;
    }
    list->size = size;

    for (size_t i = 0; i < size; ++i) {
        fread(&list->entities[i], sizeof(ProtocolEntity), 1, file);
    }

    pthread_mutex_unlock(&list->lock);

    fclose(file);
    return 0;
}
