#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PACKETS 1000
#define PAYLOAD_SIZE 128
#define IP_ADDRESS_LENGTH 16

typedef struct {
    time_t timestamp;
    char sourceIP[IP_ADDRESS_LENGTH];
    unsigned int payloadSize;
    unsigned char payload[PAYLOAD_SIZE];
} NetworkPacket;

NetworkPacket* packetArray = NULL;
int currentCapacity = 0;
int totalPackets = 0;
pthread_mutex_t packetMutex = PTHREAD_MUTEX_INITIALIZER;

void generateRandomPayload(unsigned char *payload, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        payload[i] = rand() % 256;
    }
}

unsigned int calculateChecksum(const unsigned char *data, size_t length) {
    return crc32(data, length);
}

void NetworkPacketManager(int numPackets, const char* ipPattern, unsigned int maxPayloadSize) {
    pthread_mutex_lock(&packetMutex);

    if (totalPackets + numPackets > MAX_PACKETS) {
        printf("Error: Exceeds maximum packet limit.\n");
        pthread_mutex_unlock(&packetMutex);
        return;
    }

    while (currentCapacity < totalPackets + numPackets) {
        currentCapacity = (int)(currentCapacity * 1.2) + 1;
        packetArray = realloc(packetArray, currentCapacity * sizeof(NetworkPacket));
        if (!packetArray) {
            printf("Error: Memory allocation failed.\n");
            pthread_mutex_unlock(&packetMutex);
            return;
        }
    }

    for (int i = 0; i < numPackets; ++i) {
        NetworkPacket *newPacket = &packetArray[totalPackets + i];
        newPacket->timestamp = time(NULL);
        snprintf(newPacket->sourceIP, IP_ADDRESS_LENGTH, ipPattern, rand() % 256);
        newPacket->payloadSize = (rand() % (maxPayloadSize - PAYLOAD_SIZE)) + PAYLOAD_SIZE;
        generateRandomPayload(newPacket->payload, newPacket->payloadSize);

        if (!isValidIPAddress(newPacket->sourceIP) || newPacket->payloadSize > maxPayloadSize) {
            printf("Error: Invalid packet discarded.\n");
            currentCapacity--;
        } else {
            totalPackets++;
        }
    }

    pthread_mutex_unlock(&packetMutex);
}

void cleanup() {
    pthread_mutex_lock(&packetMutex);

    if (packetArray) {
        free(packetArray);
        packetArray = NULL;
        currentCapacity = 0;
        totalPackets = 0;
    }

    pthread_mutex_unlock(&packetMutex);
}
