#include <stdlib.h>
#include <pthread.h>

#define INITIAL_CAPACITY 10
#define GROWTH_FACTOR 1.1
#define MAX_RECORDS 1000

typedef struct Record {
    int key;
    time_t timestamp;
    int value;
    int ref_count;
} Record;

typedef struct Dataset {
    Record** records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} Dataset;

Dataset* create_dataset() {
    Dataset* dataset = (Dataset*)aligned_alloc(64, sizeof(Dataset));
    if (!dataset) return NULL;

    dataset->records = (Record**)aligned_alloc(64, INITIAL_CAPACITY * sizeof(Record*));
    if (!dataset->records) {
        free(dataset);
        return NULL;
    }

    dataset->capacity = INITIAL_CAPACITY;
    dataset->size = 0;
    pthread_mutex_init(&dataset->lock, NULL);

    return dataset;
}

void destroy_dataset(Dataset* dataset) {
    for (size_t i = 0; i < dataset->size; ++i) {
        free(dataset->records[i]);
    }
    free(dataset->records);
    pthread_mutex_destroy(&dataset->lock);
    free(dataset);
}

int add_record(Dataset* dataset, int key, time_t timestamp, int value) {
    pthread_mutex_lock(&dataset->lock);

    if (dataset->size >= MAX_RECORDS) {
        pthread_mutex_unlock(&dataset->lock);
        return -1; // Dataset limit reached
    }

    if (dataset->size == dataset->capacity) {
        size_t new_capacity = (size_t)(dataset->capacity * GROWTH_FACTOR);
        Record** new_records = (Record**)aligned_alloc(64, new_capacity * sizeof(Record*));
        if (!new_records) {
            pthread_mutex_unlock(&dataset->lock);
            return -1; // Memory allocation failed
        }

        for (size_t i = 0; i < dataset->size; ++i) {
            new_records[i] = dataset->records[i];
        }

        free(dataset->records);
        dataset->records = new_records;
        dataset->capacity = new_capacity;
    }

    Record* record = (Record*)aligned_alloc(64, sizeof(Record));
    if (!record) {
        pthread_mutex_unlock(&dataset->lock);
        return -1; // Memory allocation failed
    }

    record->key = key;
    record->timestamp = timestamp;
    record->value = value;
    record->ref_count = 1;

    dataset->records[dataset->size++] = record;

    pthread_mutex_unlock(&dataset->lock);
    return 0; // Success
}

void increment_ref_count(Dataset* dataset, int key) {
    pthread_mutex_lock(&dataset->lock);

    for (size_t i = 0; i < dataset->size; ++i) {
        if (dataset->records[i]->key == key) {
            dataset->records[i]->ref_count++;
            break;
        }
    }

    pthread_mutex_unlock(&dataset->lock);
}

void decrement_ref_count(Dataset* dataset, int key) {
    pthread_mutex_lock(&dataset->lock);

    for (size_t i = 0; i < dataset->size; ++i) {
        if (dataset->records[i]->key == key) {
            dataset->records[i]->ref_count--;
            if (dataset->records[i]->ref_count == 0) {
                free(dataset->records[i]);
                for (size_t j = i; j < dataset->size - 1; ++j) {
                    dataset->records[j] = dataset->records[j + 1];
                }
                dataset->size--;
            }
            break;
        }
    }

    pthread_mutex_unlock(&dataset->lock);
}
