NFAPI_CRC_INDICATION_PDU_T* create_and_populate_list(int N) {
    if (N > MAX_SIZE) {
        return NULL; // Exceeds maximum size
    }

    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        return NULL; // Memory allocation failed
    }

    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < N; i++) {
        list[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Example range
        list[i].RNTI = rand() % 4096; // Valid RNTI range
        list[i].CRC_INDICATION_REL8_TAG = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG
    }

    return list;
}

void serialize_list(NFAPI_CRC_INDICATION_PDU_T* list, int N, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        printf("Failed to open file for writing.\n");
        return;
    }

    size_t written = fwrite(list, sizeof(NFAPI_CRC_INDICATION_PDU_T), N, file);
    if (written != N) {
        printf("Error during serialization.\n");
    } else {
        printf("Serialization successful.\n");
    }

    fclose(file);
}

NFAPI_CRC_INDICATION_PDU_T* deserialize_list(const char* filename, int* N) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        printf("Failed to open file for reading.\n");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    long size = ftell(file);
    fseek(file, 0, SEEK_SET);

    *N = size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (*N > MAX_SIZE) {
        printf("File exceeds maximum size.\n");
        fclose(file);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(*N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        printf("Memory allocation failed during deserialization.\n");
        fclose(file);
        return NULL;
    }

    size_t read = fread(list, sizeof(NFAPI_CRC_INDICATION_PDU_T), *N, file);
    if (read != *N) {
        printf("Error during deserialization.\n");
        free(list);
        list = NULL;
    } else {
        printf("Deserialization successful.\n");
    }

    fclose(file);
    return list;
}
