using System;
using System.Diagnostics;
using System.IO;
using System.Linq;
using Microsoft.Extensions.Logging;

public class WebAppManager
{
    private readonly ILogger<WebAppManager> _logger;

    public WebAppManager(ILogger<WebAppManager> logger)
    {
        _logger = logger;
    }

    public Process StartWebApplication(string directoryPath, string siteName, ApplicationSettings settings)
    {
        if (!Directory.Exists(directoryPath))
        {
            _logger.LogError("Directory does not exist: {DirectoryPath}", directoryPath);
            return null;
        }

        if (!File.Exists(Path.Combine(directoryPath, "web.config")) || !File.Exists(Path.Combine(directoryPath, "applicationSettings.json")))
        {
            _logger.LogError("Missing required files in directory: {DirectoryPath}", directoryPath);
            return null;
        }

        if (IsDirectoryInUse(directoryPath))
        {
            _logger.LogError("Directory is already in use by another process: {DirectoryPath}", directoryPath);
            return null;
        }

        try
        {
            var startInfo = new ProcessStartInfo
            {
                WorkingDirectory = directoryPath,
                FileName = "dotnet",
                Arguments = $"run --project {siteName}.csproj"
            };

            var process = Process.Start(startInfo);
            _logger.LogInformation("Web application started successfully: {SiteName}", siteName);
            return process;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to start web application: {SiteName}", siteName);
            return null;
        }
    }

    private bool IsDirectoryInUse(string path)
    {
        try
        {
            using (var directoryInfo = new DirectoryInfo(path))
            {
                directoryInfo.Refresh();
                if (directoryInfo.IsReadOnly)
                    return true;

                var files = directoryInfo.GetFiles("*", SearchOption.AllDirectories);
                foreach (var file in files)
                {
                    if (file.IsReadOnly)
                        return true;
                }

                var directories = directoryInfo.GetDirectories("*", SearchOption.AllDirectories);
                foreach (var dir in directories)
                {
                    if (dir.IsReadOnly)
                        return true;
                }
            }
        }
        catch
        {
            // Handle exceptions that may occur when accessing the directory
            return true;
        }

        return false;
    }
}

public class ApplicationSettings
{
    public string DatabaseConnectionString { get; set; }
    public string ApiKey { get; set; }
    // Add other settings as needed
}
