#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_ENTRIES 5000

typedef struct LTE_PHY_RX_PDU_T {
    int RX_CHANNEL_ID;
    float RSSI;
    // Other fields...
} LTE_PHY_RX_PDU_T;

typedef struct Node {
    LTE_PHY_RX_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct DoublyLinkedList {
    Node* head;
    Node* tail;
    int size;
    pthread_mutex_t lock;
} DoublyLinkedList;

void initList(DoublyLinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

Node* createNode(LTE_PHY_RX_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    newNode->data = data;
    newNode->prev = NULL;
    newNode->next = NULL;
    return newNode;
}

void insertNode(DoublyLinkedList* list, LTE_PHY_RX_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    Node* newNode = createNode(data);

    if (list->size == 0) {
        list->head = newNode;
        list->tail = newNode;
    } else {
        if (newNode->data.RX_CHANNEL_ID != list->tail->data.RX_CHANNEL_ID) {
            newNode->prev = list->tail;
            list->tail->next = newNode;
            list->tail = newNode;
        }
    }

    list->size++;
    pthread_mutex_unlock(&list->lock);
}

void validateAndInsert(DoublyLinkedList* list, LTE_PHY_RX_PDU_T data, float threshold) {
    pthread_mutex_lock(&list->lock);
    if (list->size == 0 || data.RX_CHANNEL_ID != list->tail->data.RX_CHANNEL_ID && data.RSSI >= threshold) {
        Node* newNode = createNode(data);

        if (newNode->data.RX_CHANNEL_ID != list->tail->data.RX_CHANNEL_ID) {
            newNode->prev = list->tail;
            list->tail->next = newNode;
            list->tail = newNode;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void* fetchThresholds(void* arg) {
    // Simulate fetching thresholds from an external data source
    float threshold = 0.5; // Example threshold
    return (void*)threshold;
}

int main() {
    DoublyLinkedList list;
    initList(&list);

    pthread_t thread;
    pthread_create(&thread, NULL, fetchThresholds, NULL);
    void* threshold_ptr = pthread_join(thread, NULL);
    float threshold = *(float*)threshold_ptr;

    LTE_PHY_RX_PDU_T pdu1 = {1, 0.6};
    LTE_PHY_RX_PDU_T pdu2 = {2, 0.4};
    LTE_PHY_RX_PDU_T pdu3 = {1, 0.7};

    validateAndInsert(&list, pdu1, threshold);
    validateAndInsert(&list, pdu2, threshold);
    validateAndInsert(&list, pdu3, threshold);

    // Clean up
    Node* current = list.head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    return 0;
}
