#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int key;
    time_t timestamp;
    int value;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} Dataset;

Dataset* create_dataset(size_t initial_capacity) {
    Dataset* dataset = (Dataset*)malloc(sizeof(Dataset));
    if (!dataset) return NULL;

    dataset->records = (Record*)calloc(initial_capacity, sizeof(Record));
    if (!dataset->records) {
        free(dataset);
        return NULL;
    }

    dataset->capacity = initial_capacity;
    dataset->size = 0;
    pthread_mutex_init(&dataset->lock, NULL);

    return dataset;
}

void destroy_dataset(Dataset* dataset) {
    pthread_mutex_lock(&dataset->lock);
    free(dataset->records);
    pthread_mutex_unlock(&dataset->lock);
    pthread_mutex_destroy(&dataset->lock);
    free(dataset);
}

int add_record(Dataset* dataset, Record record) {
    pthread_mutex_lock(&dataset->lock);
    if (dataset->size >= dataset->capacity) {
        size_t new_capacity = dataset->capacity * 1.1;
        Record* new_records = (Record*)realloc(dataset->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&dataset->lock);
            return -1; // Memory allocation failed
        }
        dataset->records = new_records;
        dataset->capacity = new_capacity;
    }
    dataset->records[dataset->size++] = record;
    pthread_mutex_unlock(&dataset->lock);
    return 0;
}

// Additional functions for managing the dataset, such as removing records, updating records, etc.

int main() {
    Dataset* dataset = create_dataset(100);
    if (!dataset) {
        fprintf(stderr, "Failed to create dataset\n");
        return 1;
    }

    Record record = {1, time(NULL), 42};
    if (add_record(dataset, record) != 0) {
        fprintf(stderr, "Failed to add record\n");
        destroy_dataset(dataset);
        return 1;
    }

    // Additional code for managing the dataset and handling concurrent access

    destroy_dataset(dataset);
    return 0;
}
```

