#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/hmac.h>
#include <string.h>
#include <stdlib.h>
#include <stdio.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char *key;
    unsigned char *iv;
} AESCipher;

AESCipher* aes_init(const char *password, size_t password_len,
                     const unsigned char *salt, size_t salt_len,
                     int key_length, int iv_length,
                     int iterations, const EVP_MD *digest) {
    AESCipher *cipher = (AESCipher*)malloc(sizeof(AESCipher));
    if (!cipher) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    cipher->ctx = EVP_CIPHER_CTX_new();
    if (!cipher->ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        free(cipher);
        return NULL;
    }

    unsigned char *derived_key = (unsigned char*)malloc(key_length);
    if (!derived_key) {
        fprintf(stderr, "Memory allocation failed\n");
        EVP_CIPHER_CTX_free(cipher->ctx);
        free(cipher);
        return NULL;
    }

    int derived_len;
    if (!PKCS5_PBKDF2_HMAC(password, password_len, salt, salt_len,
                           iterations, digest, key_length, derived_key)) {
        fprintf(stderr, "Key derivation failed\n");
        EVP_CIPHER_CTX_free(cipher->ctx);
        free(derived_key);
        free(cipher);
        return NULL;
    }

    cipher->key = derived_key;
    cipher->iv = (unsigned char*)malloc(iv_length);
    if (!cipher->iv) {
        fprintf(stderr, "Memory allocation failed\n");
        EVP_CIPHER_CTX_free(cipher->ctx);
        free(derived_key);
        free(cipher);
        return NULL;
    }

    if (!EVP_EncryptInit_ex(cipher->ctx, EVP_aes_256_gcm(), NULL,
                            derived_key, cipher->iv)) {
        fprintf(stderr, "Cipher initialization failed\n");
        EVP_CIPHER_CTX_free(cipher->ctx);
        free(derived_key);
        free(cipher->iv);
        free(cipher);
        return NULL;
    }

    return cipher;
}

void aes_cleanup(AESCipher *cipher) {
    if (cipher) {
        EVP_CIPHER_CTX_free(cipher->ctx);
        free(cipher->key);
        free(cipher->iv);
        free(cipher);
    }
}
