#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    char* name;
    double value;
    size_t index;
} data_entry;

typedef struct {
    data_entry** entries;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} dynamic_collection;

dynamic_collection* create_collection(size_t initial_capacity) {
    dynamic_collection* collection = (dynamic_collection*)malloc(sizeof(dynamic_collection));
    if (!collection) return NULL;

    collection->entries = (data_entry**)calloc(initial_capacity, sizeof(data_entry*));
    if (!collection->entries) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void destroy_collection(dynamic_collection* collection) {
    for (size_t i = 0; i < collection->size; ++i) {
        free(collection->entries[i]->name);
        free(collection->entries[i]);
    }
    free(collection->entries);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int add_entry(dynamic_collection* collection, const char* source_string, size_t index) {
    pthread_mutex_lock(&collection->lock);

    if (collection->size >= collection->capacity) {
        data_entry** new_entries = (data_entry**)realloc(collection->entries, collection->capacity * 2 * sizeof(data_entry*));
        if (!new_entries) {
            pthread_mutex_unlock(&collection->lock);
            return -1;
        }
        collection->entries = new_entries;
        collection->capacity *= 2;
    }

    data_entry* entry = (data_entry*)malloc(sizeof(data_entry));
    if (!entry) {
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    size_t name_length = strlen(source_string);
    entry->name = (char*)malloc(name_length + 1);
    if (!entry->name) {
        free(entry);
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }
    snprintf(entry->name, name_length + 1, "%.*s", (int)index, source_string);

    entry->value = ((double)rand() / RAND_MAX) * 100.0; // Random value between 0 and 100
    entry->index = index;

    collection->entries[collection->size++] = entry;
    pthread_mutex_unlock(&collection->lock);
    return 0;
}

data_entry* get_entry(dynamic_collection* collection, size_t index) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->size; ++i) {
        if (collection->entries[i]->index == index) {
            data_entry* entry = collection->entries[i];
            pthread_mutex_unlock(&collection->lock);
            return entry;
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return NULL;
}

int update_entry(dynamic_collection* collection, size_t index, double new_value) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->size; ++i) {
        if (collection->entries[i]->index == index) {
            collection->entries[i]->value = new_value;
            pthread_mutex_unlock(&collection->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return -1;
}
