typedef struct {
    int value;
    int *offset_index;
} record;

void manage_memory(int num_records, int seed, long **offsets, int **keys, record **records) {
    if (num_records <= 0 || seed == -1) {
        return; // Handle invalid input
    }

    *offsets = (long *)calloc(num_records, sizeof(long));
    *keys = (int *)calloc(num_records, sizeof(int));
    *records = (record *)malloc(num_records * sizeof(record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        // Handle memory allocation failure
        return;
    }

    srand(seed);
    for (int i = 0; i < num_records; i++) {
        (*records)[i].value = rand() % 100 + 1; // Random value between 1 and 100
        (*records)[i].offset_index = &(*offsets)[i];
        *keys[i] = i; // Unique identifier for each record
    }
}

void cleanup(long *offsets, int *keys, record *records) {
    if (offsets != NULL) free(offsets);
    if (keys != NULL) free(keys);
    if (records != NULL) free(records);
}
