import pandas as pd
import hashlib
import random
import string

def process_and_hash(file_path, chunk_size, column_specs, progress_callback, hash_algorithm='sha256', charset=string.ascii_letters + string.digits):
    def generate_random_string(length):
        return ''.join(random.choice(charset) for _ in range(length))

    def hash_password(password, algorithm):
        hasher = hashlib.new(algorithm)
        hasher.update(password.encode('utf-8'))
        return hasher.hexdigest()

    statistical_summary = {}
    total_rows_processed = 0

    def progress_update():
        nonlocal total_rows_processed
        if callable(progress_callback):
            progress_callback(total_rows_processed)

    try:
        for chunk in pd.read_csv(file_path, chunksize=chunk_size):
            processed_chunk = chunk[column_specs]
            statistical_summary.update(processed_chunk.describe().to_dict())
            total_rows_processed += len(chunk)
            progress_update()

    except Exception as e:
        print(f"An error occurred: {e}")
        return statistical_summary, None

    random_string = generate_random_string(10)  # Example length
    hashed_password = hash_password(random_string, hash_algorithm)

    return statistical_summary, hashed_password
```

