        int retries = 0;
        while (retries < MAX_RETRIES) {
            res = curl_easy_perform(curl);
            if (res != CURLE_OK) {
                fprintf(stderr, "Failed to fetch config: %s\n", curl_easy_strerror(res));
                retries++;
                sleep(1); // Wait before retrying
            } else {
                break;
            }
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Max retries reached. Failed to fetch config.\n");
            free(config_data);
            curl_easy_cleanup(curl);
            curl_global_cleanup();
            return -1;
        }

        // Parse the JSON data and populate the PDU array
        *count = parse_json_config(config_data, pdu_array);
        free(config_data);

        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();

    return 0;
}

size_t write_memory_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    char **ptr = (char **)userp;

    *ptr = realloc(*ptr, realsize + 1);
    if (*ptr == NULL) {
        fprintf(stderr, "Not enough memory (realloc returned NULL)\n");
        return 0;
    }

    memcpy(*ptr + realsize, contents, realsize);
    (*ptr)[realsize] = '\0';

    return realsize;
}

