['```cpp
#include <vector>
#include <memory>
#include <string>
#include <algorithm>

void insertAndMaintainUnique(std::vector<std::shared_ptr<std::string>>& vec, const std::string& target, const std::string& toInsert, int maxCapacity, bool isCaseSensitive) {
    auto it = std::find_if(vec.begin(), vec.end(), [&](const std::shared_ptr<std::string>& str) {
        return isCaseSensitive ? *str == target : std::equal(str->begin(), str->end(), target.begin(), target.end());
    });

    if (it != vec.end()) {
        it = vec.insert(it + 1, std::make_shared<std::string>(toInsert));
    } else {
        vec.push_back(std::make_shared<std::string>(toInsert));
    }

    auto newEnd = std::unique(vec.begin(), vec.end(), [&](const std::shared_ptr<std::string>& a, const std::shared_ptr<std::string>& b) {
        return isCaseSensitive ? *a == *b : std::equal(a->begin(), a->end(), b->begin(), b->end());
    });

    vec.erase(newEnd, vec.end());

    if (vec.size() > maxCapacity) {
        vec.resize(maxCapacity);
    }
}
