    RecordManager(size_t initialSize) : records(initialSize) {}

    void addRecord(long offset, int key, const Record& record) {
        std::lock_guard<std::mutex> lock(recordsMutex);
        if (records.size() <= offset) {
            records.resize(offset + 1);
        }
        records[offset] = record;
    }

    bool verifyIntegrity() {
        for (size_t i = 0; i < records.size(); ++i) {
            // Check if key pointer is valid
            if (records[i].value != static_cast<int>(i)) {
                return false;
            }
        }
        return true;
    }

    void cleanup() {
        std::lock_guard<std::mutex> lock(recordsMutex);
        records.clear();
    }
