using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Newtonsoft.Json.Linq;

public class JsonProcessor
{
    private static int _invocationCount = 0;
    private readonly string _filePath;
    private readonly object _lockObject = new object();

    public JsonProcessor(string filePath)
    {
        _filePath = filePath;
    }

    public JObject FindFirstMatchingObject(string key, JToken value)
    {
        lock (_lockObject)
        {
            _invocationCount++;
            LogInvocationCount();
        }

        try
        {
            using (var reader = new StreamReader(_filePath))
            using (var jsonReader = new JsonTextReader(reader))
            {
                var jObject = JObject.Load(jsonReader);
                return FindMatchingObject(jObject, key, value);
            }
        }
        catch (Exception ex)
        {
            LogError(ex.Message);
            return new JObject();
        }
    }

    private JObject FindMatchingObject(JToken token, string key, JToken value)
    {
        if (token.Type == JTokenType.Object)
        {
            var obj = (JObject)token;
            if (obj.TryGetValue(key, out var objValue) && objValue.Equals(value))
                return obj;

            foreach (var child in obj.Children())
            {
                var result = FindMatchingObject(child, key, value);
                if (result != null)
                    return result;
            }
        }
        else if (token.Type == JTokenType.Array)
        {
            foreach (var item in (JArray)token)
            {
                var result = FindMatchingObject(item, key, value);
                if (result != null)
                    return result;
            }
        }

        return null;
    }

    private void LogInvocationCount()
    {
        Console.WriteLine($"Function invoked {_invocationCount} times.");
    }

    private void LogError(string message)
    {
        Console.Error.WriteLine($"Error: {message}");
    }
}
```

