[Route("api/[controller]")]
public class ContentController : ControllerBase
{
    private readonly IMemoryCache _cache;
    private readonly IContentService _contentService;

    public ContentController(IMemoryCache cache, IContentService contentService)
    {
        _cache = cache;
        _contentService = contentService;
    }

    [HttpPost("update")]
    public async Task<IActionResult> UpdateContent(
        [FromForm] int userId,
        [FromForm] string sessionToken,
        [FromForm] int pageSectionId,
        [FromForm] int elementId,
        [FromForm] string htmlContent)
    {
        try
        {
            if (!await ValidateSessionToken(userId, sessionToken))
                return Unauthorized("Invalid session token");

            var cacheKey = $"PageSection_{pageSectionId}";
            var cachedContent = await _cache.GetOrCreateAsync(cacheKey, async entry =>
            {
                entry.AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(5);
                return await _contentService.GetPageSection(pageSectionId);
            });

            if (cachedContent == null)
                return NotFound("Page section not found");

            var elementToUpdate = cachedContent.Elements.FirstOrDefault(e => e.Id == elementId);
            if (elementToUpdate == null)
                return NotFound("Element not found");

            elementToUpdate.HtmlContent = htmlContent;
            await _contentService.UpdateElement(elementToUpdate);

            // Invalidate the cache to ensure consistency
            _cache.Remove(cacheKey);

            return Ok(new { RefreshPage = true });
        }
        catch (Exception ex)
        {
            return StatusCode(500, new { Error = "Internal server error", Details = ex.Message });
        }
    }

    private async Task<bool> ValidateSessionToken(int userId, string sessionToken)
    {
        // Implement token validation logic here
        // Return true if the token is valid for the user, false otherwise
        return await _contentService.ValidateSessionToken(userId, sessionToken);
    }
}

public interface IContentService
{
    Task<PageSection> GetPageSection(int pageSectionId);
    Task UpdateElement(Element element);
    Task<bool> ValidateSessionToken(int userId, string sessionToken);
}

public class PageSection
{
    public int Id { get; set; }
    public List<Element> Elements { get; set; }
}

public class Element
{
    public int Id { get; set; }
    public string HtmlContent { get; set; }
}
