public class ServiceConfigLoader {

    private static final String DEFAULT_CONFIG_DIR = "/default/config/directory";
    private static Map<String, Object> serviceCache;

    public static ServiceConfig loadServiceConfig(String configFilePath) {
        try (YamlReader reader = new YamlReader(new FileInputStream(configFilePath))) {
            Map<String, Object> configMap = reader.read(Map.class);
            if (configMap != null && configMap.containsKey("service")) {
                Object serviceObj = configMap.get("service");
                if (serviceObj instanceof ServiceConfig) {
                    return (ServiceConfig) serviceObj;
                }
            }
        } catch (IOException e) {
            System.err.println("Failed to load service configuration: " + e.getMessage());
        }
        return null;
    }

    public static void initializeCacheRoot() {
        String configDir = System.getProperty("config.dir");
        if (configDir == null || configDir.isEmpty()) {
            System.setProperty("config.dir", DEFAULT_CONFIG_DIR);
        }
    }

    public static void parseAndStoreConfig(String cacheRoot) {
        try {
            String configFilePath = cacheRoot + "/service-config.yaml";
            ServiceConfig serviceConfig = loadServiceConfig(configFilePath);
            if (serviceConfig != null) {
                synchronized (ServiceConfigLoader.class) {
                    if (serviceCache == null || isStale(serviceCache)) {
                        serviceCache = parseConfigFile(configFilePath);
                    }
                }
            }
        } catch (Exception e) {
            System.err.println("Failed to parse and store configuration: " + e.getMessage());
        }
    }

    private static boolean isStale(Map<String, Object> cache) {
        // Implement staleness check logic
        return false;
    }

    private static Map<String, Object> parseConfigFile(String filePath) throws IOException {
        try (YamlReader reader = new YamlReader(new FileInputStream(filePath))) {
            return reader.read(Map.class);
        }
    }

    public static void main(String[] args) {
        initializeCacheRoot();
        String cacheRoot = System.getProperty("config.dir");
        parseAndStoreConfig(cacheRoot);
    }
}
