const fs = require('fs');
const path = require('path');
const cluster = require('cluster');
const numCPUs = require('os').cpus().length;
const { exec } = require('child_process');

function runTests(modulePath, config) {
  const module = require(modulePath);
  const tests = Object.keys(module).filter(key => typeof module[key] === 'function');
  let passed = 0;
  let failed = 0;
  let totalExecutionTime = 0;

  if (cluster.isMaster) {
    console.log(`Starting ${numCPUs} workers...`);
    cluster.on('exit', (worker, code, signal) => {
      console.log(`Worker ${worker.process.pid} died`);
    });

    for (let i = 0; i < numCPUs; i++) {
      cluster.fork();
    }

    cluster.on('message', (worker, message) => {
      if (message.type === 'testResult') {
        if (message.passed) {
          passed++;
        } else {
          failed++;
        }
        totalExecutionTime += message.executionTime;
      } else if (message.type === 'shutdown') {
        console.log(`All tests completed. Passed: ${passed}, Failed: ${failed}`);
        console.log(`Total execution time: ${totalExecutionTime}ms`);
        process.exit(0);
      }
    });
  } else {
    const testResults = [];
    for (const test of tests) {
      const startTime = Date.now();
      try {
        module[test]();
        testResults.push({ name: test, passed: true, executionTime: Date.now() - startTime });
      } catch (error) {
        testResults.push({ name: test, passed: false, executionTime: Date.now() - startTime, error });
      }
    }

    cluster.worker.send({ type: 'testResult', results: testResults });

    if (config.saveIntermediateResults) {
      saveResultsToStorage(testResults, config.storageBackend);
    }

    cluster.worker.send({ type: 'shutdown' });
  }
}

function saveResultsToStorage(results, storageBackend) {
  // Implement logic to save results to the specified storage backend
  // This could involve writing to a file, uploading to a cloud service, etc.
}

// Example usage:
const config = {
  saveIntermediateResults: true,
  storageBackend: 'database'
};

runTests('./path/to/module', config);
```

