<?php

class RandomStringGenerator {
    private $charset = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    private $cache;
    private $cacheTtl;

    public function __construct($cache, $cacheTtl = 3600) {
        $this->cache = $cache;
        $this->cacheTtl = $cacheTtl;
    }

    public function generateString($length) {
        $key = 'random_string_' . $length;

        if ($this->cache->has($key)) {
            return $this->cache->get($key);
        }

        $string = '';
        while (strlen($string) < $length) {
            $char = substr($this->charset, rand(0, strlen($this->charset) - 1), 1);
            if (!preg_match('/[a-z]/', $string) && preg_match('/[a-z]/', $char)) {
                $string .= $char;
            } elseif (!preg_match('/[A-Z]/', $string) && preg_match('/[A-Z]/', $char)) {
                $string .= $char;
            } elseif (!preg_match('/\d/', $string) && preg_match('/\d/', $char)) {
                $string .= $char;
            }
        }

        $this->cache->set($key, $string, $this->cacheTtl);

        return $string;
    }
}

// Example usage:
$cache = new Memcached();
$cache->addServer('127.0.0.1', 11211);
$generator = new RandomStringGenerator($cache, 3600);
echo $generator->generateString(10);
