#define MAX_PROJECTS 5000

typedef struct {
    int priority;
    char *status;
    time_t deadline;
    time_t start_date;
} project;

project* init_project_list(size_t num_projects) {
    if (num_projects > MAX_PROJECTS) {
        fprintf(stderr, "Error: Number of projects exceeds maximum limit.\n");
        return NULL;
    }

    project *projects = malloc(num_projects * sizeof(project));
    if (!projects) {
        perror("Failed to allocate memory for project list.");
        return NULL;
    }

    time_t current_time = time(NULL);
    for (size_t i = 0; i < num_projects; ++i) {
        projects[i].priority = i + 1;
        projects[i].status = malloc(20 * sizeof(char));
        if (!projects[i].status) {
            perror("Failed to allocate memory for project status.");
            // Free previously allocated memory
            for (size_t j = 0; j < i; ++j) {
                free(projects[j].status);
            }
            free(projects);
            return NULL;
        }
        strcpy(projects[i].status, "Pending");
        projects[i].deadline = current_time + (i * 86400); // Example deadline calculation
        projects[i].start_date = current_time;
    }

    return projects;
}

void update_project_statuses(project *projects, size_t num_projects) {
    time_t now = time(NULL);
    for (size_t i = 0; i < num_projects; ++i) {
        double elapsed_time = difftime(now, projects[i].start_date);
        double total_duration = difftime(projects[i].deadline, projects[i].start_date);

        if (elapsed_time > total_duration / 2 && elapsed_time <= total_duration) {
            strcpy(projects[i].status, "In Progress");
        } else if (elapsed_time > total_duration) {
            strcpy(projects[i].status, "Completed");
        } else if (elapsed_time > total_duration + total_duration / 2) {
            strcpy(projects[i].status, "Late");
        }
    }
}

void free_project_list(project *projects, size_t num_projects) {
    for (size_t i = 0; i < num_projects; ++i) {
        free(projects[i].status);
    }
    free(projects);
}
