class log_entry {
public:
    std::string timestamp;
    std::string message;
    std::optional<int> severity;

    log_entry(std::string msg, std::optional<int> sev = std::nullopt)
        : timestamp(get_current_time()), message(msg), severity(sev) {}

private:
    static std::string get_current_time() {
        auto now = std::chrono::system_clock::now();
        auto in_time_t = std::chrono::system_clock::to_time_t(now);
        return std::ctime(&in_time_t);
    }
};

class log_manager {
public:
    void add_entry(const std::string& msg, std::optional<int> sev = std::nullopt) {
        std::lock_guard<std::mutex> lock(mutex_);
        entries_.emplace_back(msg, sev);
    }

    log_entry* get_entry_by_timestamp(const std::string& ts) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto& entry : entries_) {
            if (entry.timestamp == ts) {
                return &entry;
            }
        }
        return nullptr;
    }

    void update_entry(const std::string& ts, const std::string& new_msg, std::optional<int> new_sev = std::nullopt) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto& entry : entries_) {
            if (entry.timestamp == ts) {
                entry.message = new_msg;
                entry.severity = new_sev;
                return;
            }
        }
    }

private:
    std::vector<log_entry> entries_;
    std::mutex mutex_;
};

int main() {
    log_manager manager;
    manager.add_entry("Initial message");
    manager.update_entry("2023-10-05 14:30:00", "Updated message", 3);
    auto entry = manager.get_entry_by_timestamp("2023-10-05 14:30:00");
    if (entry) {
        std::cout << "Timestamp: " << entry->timestamp << ", Message: " << entry->message << ", Severity: " << entry->severity.value_or(0) << std::endl;
    }
    return 0;
}
