['```cpp
#include <iostream>
#include <forward_list>
#include <mutex>
#include <utility>

template <typename T>
struct Transaction {
    int age;
    int countInLastThreeSeconds;
    T weightedSum;
};

std::forward_list<Transaction<int>> transactions;
int targetTransactionID;
double criteriaThreshold;

std::mutex mtx;
pair<int, int> processTransactions(std::forward_list<Transaction<int>>& transList, const std::string& targetID, double threshold) {
    std::lock_guard<std::mutex> lock(mtx);

    int maxWeightedSum = 0;
    int maxTransactionID = -1;
    auto it = transList.begin();
    bool inserted = false;

    while (it != transList.end()) {
        if (it->age > 0 && it->countInLastThreeSeconds <= 3 && it->weightedSum > threshold) {
            if (!inserted) {
                Transaction<int> newTransaction{0, 0, 0};
                newTransaction.weightedSum = threshold;
                newTransaction.age = 1;
                newTransaction.countInLastThreeSeconds = 1;
                transList.insert_after(it, newTransaction);
                inserted = true;
            }
            if (it->weightedSum > maxWeightedSum) {
                maxWeightedSum = it->weightedSum;
                maxTransactionID = targetTransactionID;
            }
        }
        ++it;
    }

    if (!inserted) {
        Transaction<int> newTransaction{0, 0, 0};
        newTransaction.weightedSum = threshold;
        newTransaction.age = 1;
        newTransaction.countInLastThreeSeconds = 1;
        transList.push_back(newTransaction);
    }

    return {maxWeightedSum, maxTransactionID};
}
