        fprintf(stderr, "Invalid number of records\n");
        return;
    }

    printf("Enter the range for keys and buffers: ");
    scanf("%ld", &key_range);
    if (key_range <= 0) {
        fprintf(stderr, "Invalid key and buffer range\n");
        return;
    }

    long *offsets = malloc(n * sizeof(long));
    int *keys = malloc(n * sizeof(int));
    record *records = malloc(n * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    for (int i = 0; i < n; i++) {
        keys[i] = rand() % key_range;
        offsets[i] = rand() % buffer_range;
        records[i].key = keys[i];
        records[i].buffer = malloc(offsets[i]);
