#include <string.h>
#include <pthread.h>

typedef struct NetworkEvent {
    time_t timestamp;
    char type[32];
    void* data;
    size_t dataSize;
} NetworkEvent;

typedef struct EventList {
    NetworkEvent** events;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} EventList;

void initEventList(EventList* list) {
    list->events = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void freeEventList(EventList* list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->events[i]->data);
        free(list->events[i]);
    }
    free(list->events);
    pthread_mutex_destroy(&list->lock);
}

int addEvent(EventList* list, NetworkEvent* event) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        size_t newCapacity = list->capacity == 0 ? 1 : list->capacity * 2;
        NetworkEvent** newEvents = realloc(list->events, newCapacity * sizeof(NetworkEvent*));
        if (!newEvents) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }
        list->events = newEvents;
        list->capacity = newCapacity;
    }
    list->events[list->count++] = event;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int removeEvent(EventList* list, size_t index) {
    if (index >= list->count) {
        return -1; // Invalid index
    }
    pthread_mutex_lock(&list->lock);
    free(list->events[index]->data);
    free(list->events[index]);
    for (size_t i = index; i < list->count - 1; ++i) {
        list->events[i] = list->events[i + 1];
    }
    --list->count;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

NetworkEvent* getEvent(EventList* list, size_t index) {
    if (index >= list->count) {
        return NULL; // Invalid index
    }
    pthread_mutex_lock(&list->lock);
    NetworkEvent* event = list->events[index];
    pthread_mutex_unlock(&list->lock);
    return event;
}

int validateEvent(NetworkEvent* event, void (*validateFunc)(NetworkEvent*)) {
    if (validateFunc) {
        validateFunc(event);
    }
    // Default validation logic
    if (strlen(event->type) > 31 || event->dataSize > 1024 * 1024) {
        return -1; // Invalid event
    }
    return 0;
}

void logEventList(EventList* list) {
    pthread_mutex_lock(&list->lock);
    printf("Event List: %zu events\n", list->count);
    for (size_t i = 0; i < list->count; ++i) {
        NetworkEvent* event = list->events[i];
        printf("Event %zu: Timestamp=%ld, Type=%s, DataSize=%zu\n", i, event->timestamp, event->type, event->dataSize);
    }
    pthread_mutex_unlock(&list->lock);
}
