#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_BUDGET 500000.0

typedef struct project {
    double budget;
    char *status;
    time_t completion_deadline;
    struct project *next;
} Project;

typedef struct project_list {
    Project *head;
    pthread_mutex_t lock;
} ProjectList;

void init_project(Project *proj, int index) {
    proj->budget = 10000.0 * (index + 1);
    if (proj->budget > MAX_BUDGET) {
        proj->budget = MAX_BUDGET;
    }
    proj->status = strdup("Active");
    time_t now = time(NULL);
    proj->completion_deadline = now + (24 * 60 * 60); // Set deadline to 1 day from now
}

void init_project_list(ProjectList *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void insert_project(ProjectList *list, Project *proj) {
    pthread_mutex_lock(&list->lock);
    proj->next = list->head;
    list->head = proj;
    pthread_mutex_unlock(&list->lock);
}

void delete_project(ProjectList *list, Project *proj) {
    pthread_mutex_lock(&list->lock);
    if (list->head == proj) {
        list->head = proj->next;
    } else {
        Project *current = list->head;
        while (current->next != proj) {
            current = current->next;
        }
        current->next = proj->next;
    }
    free(proj->status);
    free(proj);
    pthread_mutex_unlock(&list->lock);
}

void update_project(ProjectList *list, Project *proj) {
    pthread_mutex_lock(&list->lock);
    if (time(NULL) > proj->completion_deadline) {
        proj->status = strdup("Completed");
        time_t elapsed = time(NULL) - proj->completion_deadline;
        proj->completion_deadline += elapsed; // Recalculate deadline based on elapsed time
    }
    pthread_mutex_unlock(&list->lock);
}

void report_projects(ProjectList *list, double min_budget, double max_budget, const char *status) {
    pthread_mutex_lock(&list->lock);
    Project *current = list->head;
    while (current != NULL) {
        if (current->budget >= min_budget && current->budget <= max_budget && strcmp(current->status, status) == 0) {
            printf("Project Budget: %.2f, Status: %s, Deadline: %ld\n", current->budget, current->status, current->completion_deadline);
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

int main() {
    ProjectList list;
    init_project_list(&list);

    for (int i = 0; i < 10; i++) {
        Project *proj = malloc(sizeof(Project));
        init_project(proj, i);
        insert_project(&list, proj);
    }

    update_project(&list, list.head);
    report_projects(&list, 50000.0, 200000.0, "Active");

    while (list.head != NULL) {
        delete_project(&list, list.head);
    }

    pthread_mutex_destroy(&list.lock);

    return 0;
}
