typedef struct {
    int connection_id;
    unsigned long bytes_sent;
    unsigned long bytes_received;
    double packet_loss_rate;
    unsigned long connection_duration;
} NETWORK_CONNECTION_STATS_T;

typedef struct {
    NETWORK_CONNECTION_STATS_T** connections;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} CONNECTION_MANAGER_T;

CONNECTION_MANAGER_T* create_connection_manager() {
    CONNECTION_MANAGER_T* manager = (CONNECTION_MANAGER_T*)malloc(sizeof(CONNECTION_MANAGER_T));
    if (!manager) return NULL;

    manager->connections = NULL;
    manager->count = 0;
    manager->capacity = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_connection_manager(CONNECTION_MANAGER_T* manager) {
    if (manager) {
        for (size_t i = 0; i < manager->count; ++i) {
            free(manager->connections[i]);
        }
        free(manager->connections);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

int add_connection(CONNECTION_MANAGER_T* manager, NETWORK_CONNECTION_STATS_T* stats) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity == 0 ? 1 : manager->capacity * 2;
        NETWORK_CONNECTION_STATS_T** new_connections = realloc(manager->connections, new_capacity * sizeof(NETWORK_CONNECTION_STATS_T*));
        if (!new_connections) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->connections = new_connections;
        manager->capacity = new_capacity;
    }

    manager->connections[manager->count++] = stats;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

