#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_RECORDS 10000
#define SYSTEM_MEMORY_THRESHOLD 80
#define RESIZE_FACTOR 1.1
#define MAX_GROWTH_FACTOR 2

typedef struct {
    int key;
    int value;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t count;
    size_t system_memory_threshold;
} RecordManager;

RecordManager* create_record_manager(size_t initial_capacity, size_t system_memory_threshold) {
    RecordManager* manager = (RecordManager*)malloc(sizeof(RecordManager));
    if (!manager) return NULL;

    manager->records = (Record*)aligned_alloc(64, initial_capacity * sizeof(Record));
    if (!manager->records) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->system_memory_threshold = system_memory_threshold;

    srand(time(NULL));

    return manager;
}

void destroy_record_manager(RecordManager* manager) {
    if (manager->records) {
        free(manager->records);
        manager->records = NULL;
    }
    free(manager);
}

int add_record(RecordManager* manager, int key) {
    if (manager->count >= manager->capacity * MAX_GROWTH_FACTOR) {
        printf("Warning: Maximum growth factor reached. Consider increasing system memory threshold.\n");
        return -1;
    }

    if (manager->count >= manager->capacity) {
        size_t new_capacity = (size_t)(manager->capacity * RESIZE_FACTOR);
        Record* new_records = (Record*)aligned_alloc(64, new_capacity * sizeof(Record));
        if (!new_records) {
            printf("Error: Failed to allocate memory for resizing.\n");
            return -1;
        }

        for (size_t i = 0; i < manager->count; ++i) {
            new_records[i] = manager->records[i];
        }

        free(manager->records);
        manager->records = new_records;
        manager->capacity = new_capacity;
    }

    manager->records[manager->count].key = key;
    manager->records[manager->count].value = rand() % 100; // Random value between 0 and 99
    ++manager->count;

    return 0;
}

void log_memory_usage(RecordManager* manager) {
    size_t used_memory = manager->capacity * sizeof(Record);
    if (used_memory > manager->system_memory_threshold * 1024 * 1024) { // Assuming system memory threshold is in MB
        printf("Warning: Memory usage exceeds %zu%% of system memory.\n", manager->system_memory_threshold);
    }
}

int main() {
    RecordManager* manager = create_record_manager(100, SYSTEM_MEMORY_THRESHOLD * 1024 * 1024); // Convert to bytes
    if (!manager) return -1;

    for (int i = 0; i < MAX_RECORDS; ++i) {
        add_record(manager, i);
        log_memory_usage(manager);
    }

    destroy_record_manager(manager);

    return 0;
}
