["```javascript
const EventEmitter = require('events');
const fs = require('fs');
const path = require('path');

class HistoricalEventAnalyzer extends EventEmitter {
  constructor(configPath) {
    super();
    this.configPath = configPath;
    this.eventRegexes = [];
    this.frequencyMap = {};
    this.loadConfig();
  }

  async loadConfig() {
    try {
      const config = await fs.promises.readFile(this.configPath, 'utf8');
      const events = JSON.parse(config).events;
      this.eventRegexes = events.map(event => new RegExp(`\\b${event}\\b`, 'gi'));
    } catch (error) {
      this.emit('error', 'Failed to load configuration file:', error);
    }
  }

  async processTextStream(inputStream) {
    inputStream.on('data', chunk => {
      const text = chunk.toString().toLowerCase();
      for (const regex of this.eventRegexes) {
        const matches = text.match(regex);
        if (matches) {
          matches.forEach(match => {
            this.frequencyMap[match] = (this.frequencyMap[match] || 0) + 1;
          });
        }
      }
    });

    inputStream.on('end', () => {
      this.emit('result', this.frequencyMap);
    });

    inputStream.on('error', error => {
      this.emit('error', 'Error processing text stream:', error);
    });
  }

  async updateFrequency(event, increment = 1) {
    if (this.eventRegexes.some(regex => regex.test(event))) {
      this.frequencyMap[event] = (this.frequencyMap[event] || 0) + increment;
      this.emit('update', event, this.frequencyMap[event]);
    } else {
      this.emit('error', 'Event not configured:', event);
    }
  }

  async resetFrequency() {
    this.frequencyMap = {};
    this.emit('reset');
  }
}

module.exports = HistoricalEventAnalyzer;
```

This code snippet defines a `HistoricalEventAnalyzer` class that extends `EventEmitter`. It includes methods for loading configuration, processing text streams, updating event frequencies, and resetting the frequency map. The class uses asynchronous techniques to handle high-throughput data streams efficiently and emits events for results, updates, errors, and resets."]

