    // Allocate memory for double array
    *doubleArray = (double *)malloc(size * sizeof(double));
    if (*doubleArray == NULL) {
        return -1; // Memory allocation failed
    }

    // Allocate memory for char array
    *charArray = (char *)malloc(size * sizeof(char));
    if (*charArray == NULL) {
        free(*doubleArray);
        return -1; // Memory allocation failed
    }

    // Allocate memory for struct array
    *structArray = (TemperatureReading *)malloc(size * sizeof(TemperatureReading));
    if (*structArray == NULL) {
        free(*doubleArray);
        free(*charArray);
        return -1; // Memory allocation failed
    }

    // Initialize arrays with default values
    for (int i = 0; i < size; i++) {
        (*doubleArray)[i] = 0.0;
        (*charArray)[i] = '\0';
        (*structArray)[i].value = 0.0;
        (*structArray)[i].unit = CELSIUS;
    }

    return 0; // Success
}

// Function to populate temperature data based on user input
int populateTemperatureData(double *doubleArray, char *charArray, TemperatureReading *structArray, int size) {
    for (int i = 0; i < size; i++) {
        printf("Enter temperature value for entry %d: ", i);
        scanf("%lf", &doubleArray[i]);
        printf("Enter unit (C for Celsius, F for Fahrenheit): ");
        char unit;
        scanf(" %c", &unit);
        if (unit == 'F' || unit == 'f') {
            structArray[i].unit = FAHRENHEIT;
        } else {
            structArray[i].unit = CELSIUS;
        }
    }

    return 0; // Success
}

// Function to free allocated memory
void freeTemperatureData(double *doubleArray, char *charArray, TemperatureReading *structArray) {
    if (doubleArray != NULL) {
        free(doubleArray);
    }
    if (charArray != NULL) {
        free(charArray);
    }
    if (structArray != NULL) {
        free(structArray);
    }
}

int main() {
    int size = 3;
    double *doubleArray = NULL;
    char *charArray = NULL;
    TemperatureReading *structArray = NULL;

    // Initialize memory for arrays
    if (initializeTemperatureData(&doubleArray, &charArray, &structArray, size) != 0) {
        printf("Failed to initialize temperature data.\n");
        return 1;
    }

    // Populate temperature data based on user input
    if (populateTemperatureData(doubleArray, charArray, structArray, size) != 0) {
        printf("Failed to populate temperature data.\n");
        freeTemperatureData(doubleArray, charArray, structArray);
        return 1;
    }

    // Free allocated memory
    freeTemperatureData(doubleArray, charArray, structArray);

    return 0;
}
