    char format[20];
    FILE* file;
    int rotation_size;
    int compression_enabled;
    pthread_mutex_t mutex;
} LoggerConfig;

LoggerConfig* create_logger(LogLevel level, const char* format, FILE* file, int rotation_size, int compression_enabled) {
    LoggerConfig* config = (LoggerConfig*)malloc(sizeof(LoggerConfig));
    if (!config) return NULL;

    config->level = level;
    strncpy(config->format, format, sizeof(config->format) - 1);
    config->file = file;
    config->rotation_size = rotation_size;
    config->compression_enabled = compression_enabled;
    pthread_mutex_init(&config->mutex, NULL);

    return config;
}

void log_message(LoggerConfig* config, LogLevel level, const char* message) {
    if (level < config->level) return;

    pthread_mutex_lock(&config->mutex);
    fprintf(config->file, "[%s] %s\n", level == DEBUG ? "DEBUG" : 
        (level == INFO ? "INFO" : (level == WARNING ? "WARNING" : 
            (level == ERROR ? "ERROR" : "CRITICAL"))), message);
    fflush(config->file);
    pthread_mutex_unlock(&config->mutex);
}

void destroy_logger(LoggerConfig* config) {
    if (!config) return;
    pthread_mutex_destroy(&config->mutex);
    free(config);
}
