import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class ConfigHasher {

    private static final Logger logger = LoggerFactory.getLogger(ConfigHasher.class);
    private static int entriesProcessed = 0;
    private static int errorsEncountered = 0;

    /**
     * Processes a configuration file to generate an MD5 hash of each entry's value.
     * Handles null values and empty strings gracefully. Logs successful and failed hash computations.
     * Tracks the number of entries processed and any errors encountered.
     *
     * Example usage:
     * ConfigHasher.processConfigFile("config.properties");
     *
     * @param filePath The path to the configuration file.
     */
    public static void processConfigFile(String filePath) {
        try (BufferedReader reader = new BufferedReader(new FileReader(filePath))) {
            String line;
            while ((line = reader.readLine()) != null) {
                entriesProcessed++;
                if (line.trim().isEmpty() || !line.contains("=")) {
                    continue;
                }
                String[] parts = line.split("=");
                String key = parts[0].trim();
                String value = parts.length > 1 ? parts[1].trim() : "";
                try {
                    String hash = generateMD5Hash(value);
                    logger.info("Processed entry: {} -> {}", key, hash);
                } catch (NoSuchAlgorithmException e) {
                    errorsEncountered++;
                    logger.error("Failed to process entry: {}", line, e);
                }
            }
        } catch (IOException e) {
            errorsEncountered++;
            logger.error("Error reading configuration file", e);
        }
    }

    private static String generateMD5Hash(String input) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] messageDigest = md.digest(input.getBytes());
        StringBuilder hexString = new StringBuilder();
        for (byte b : messageDigest) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

    public static int getEntriesProcessed() {
        return entriesProcessed;
    }

    public static int getErrorsEncountered() {
        return errorsEncountered;
    }
}
