#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ENTRIES 1000

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_CRC_INDICATION_PDU_T *shared_memory = NULL;
static size_t current_entries = 0;
static size_t global_rnti_counter = 0;

int generate_unique_rnti(uint16_t *rnti) {
    uint16_t candidate;
    do {
        candidate = (uint16_t)(rand() % 65536); // Random RNTI between 0 and 65535
    } while (candidate == 0 || find_rnti_in_list(candidate));
    *rnti = candidate;
    return 0;
}

int find_rnti_in_list(uint16_t rnti) {
    pthread_mutex_lock(&list_mutex);
    for (size_t i = 0; i < current_entries; ++i) {
        if (shared_memory[i].rnti == rnti) {
            pthread_mutex_unlock(&list_mutex);
            return 1;
        }
    }
    pthread_mutex_unlock(&list_mutex);
    return 0;
}

int add_entry_to_list(size_t max_entries, RX_UE_INFORMATION_TAG ue_info, CRC_INDICATION_REL8_TAG crc_indication) {
    pthread_mutex_lock(&list_mutex);
    if (current_entries >= max_entries) {
        pthread_mutex_unlock(&list_mutex);
        return -1; // Max entries reached
    }

    uint16_t rnti;
    if (generate_unique_rnti(&rnti) != 0) {
        pthread_mutex_unlock(&list_mutex);
        return -2; // Failed to generate unique RNTI
    }

    shared_memory[current_entries].ue_info = ue_info;
    shared_memory[current_entries].rnti = rnti;
    shared_memory[current_entries].crc_indication = crc_indication;

    current_entries++;
    pthread_mutex_unlock(&list_mutex);
    return 0; // Success
}

void initialize_shared_memory(size_t max_entries) {
    shared_memory = (NFAPI_CRC_INDICATION_PDU_T *)malloc(max_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!shared_memory) {
        perror("Failed to allocate memory for shared memory");
        exit(EXIT_FAILURE);
    }
}

void cleanup_shared_memory() {
    free(shared_memory);
}
```

