    const char* chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
    size_t total_size = 0;

    for (int i = 0; i < num_pdus; ++i) {
        pdus[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdus[i]) {
            // Handle memory allocation failure
            return -1;
        }
        pdus[i]->RX_UE_INFORMATION_TAG = rand() % 1000;
        pdus[i]->RNTI = rand() % 1000;
        pdus[i]->CRC_INDICATION_REL8_TAG = rand() % 1000;
        pdus[i]->CRCFLAG = rand() % 2;

        total_size += sizeof(NFAPI_CRC_INDICATION_PDU_T);

        if (total_size > memory_limit) {
            // Handle memory limit exceeded
            for (int j = 0; j < i; ++j) {
                free(pdus[j]);
            }
            return -1;
        }

        data* d = malloc(sizeof(data));
        if (!d) {
            // Handle memory allocation failure
            for (int j = 0; j <= i; ++j) {
                free(pdus[j]);
            }
            return -1;
        }
