        d->str = malloc(str_len);
        if (!d->str) {
            // Handle memory allocation failure
            free(d);
            for (int j = 0; j <= i; ++j) {
                free(pdus[j]);
            }
            return -1;
        }

        for (int j = 0; j < str_len - 1; ++j) {
            d->str[j] = chars[rand() % strlen(chars)];
        }
        d->str[str_len - 1] = '\0';

        total_size += sizeof(data) + str_len;

        if (total_size > memory_limit) {
            // Handle memory limit exceeded
            for (int j = 0; j <= i; ++j) {
                free(pdus[j]->data->str);
                free(pdus[j]->data);
                free(pdus[j]);
            }
            return -1;
        }

        node* n = malloc(sizeof(node));
        if (!n) {
            // Handle memory allocation failure
