typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} ThreadSafeList;

void init_list(ThreadSafeList *list, size_t initial_capacity) {
    list->data = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list->data == NULL) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }
    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->mutex, NULL);
}

void add_entry(ThreadSafeList *list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->mutex);
    if (list->count == list->capacity) {
        // Double the capacity or handle overflow
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_data == NULL) {
            // Handle memory allocation failure
            pthread_mutex_unlock(&list->mutex);
            exit(EXIT_FAILURE);
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }
    list->data[list->count++] = entry;
    pthread_mutex_unlock(&list->mutex);
}

void sort_list(ThreadSafeList *list, int (*comparator)(const void *, const void *)) {
    pthread_mutex_lock(&list->mutex);
    qsort(list->data, list->count, sizeof(NFAPI_CRC_INDICATION_PDU_T), comparator);
    pthread_mutex_unlock(&list->mutex);
}

int filter_predicate(const NFAPI_CRC_INDICATION_PDU_T *entry) {
    // Define the filtering criteria
    return entry->crc_indication.CRCFLAG == 1;
}

void apply_filter(ThreadSafeList *list) {
    pthread_mutex_lock(&list->mutex);
    size_t new_count = 0;
    for (size_t i = 0; i < list->count; ++i) {
        if (filter_predicate(&list->data[i])) {
            list->data[new_count++] = list->data[i];
        }
    }
    list->count = new_count;
    pthread_mutex_unlock(&list->mutex);
}

void free_list(ThreadSafeList *list) {
    pthread_mutex_lock(&list->mutex);
    free(list->data);
    pthread_mutex_destroy(&list->mutex);
    pthread_mutex_unlock(&list->mutex);
}
