#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>

#define MAX_RECORDS 10000
#define RECORD_SIZE sizeof(int)
#define BUFFER_SIZE 4096

typedef struct {
    int value;
} record;

void execute_shell_command(const char *command) {
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        exit(EXIT_FAILURE);
    } else if (pid == 0) {
        execl("/bin/sh", "sh", "-c", command, NULL);
        perror("execl");
        exit(EXIT_FAILURE);
    } else {
        int status;
        waitpid(pid, &status, 0);
        if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
            fprintf(stderr, "Shell command failed\n");
        }
    }
}

void process_records(const char *input_file, const char *output_file, int range_start, int range_end) {
    FILE *in = fopen(input_file, "rb");
    if (!in) {
        perror("fopen input");
        return;
    }

    FILE *out = fopen(output_file, "wb");
    if (!out) {
        perror("fopen output");
        fclose(in);
        return;
    }

    long offsets[MAX_RECORDS];
    int keys[MAX_RECORDS];
    record records[MAX_RECORDS];

    size_t total_memory = 0;

    while (1) {
        size_t bytes_read = fread(offsets, sizeof(long), MAX_RECORDS, in);
        if (bytes_read == 0) break;
        total_memory += bytes_read * sizeof(long);

        bytes_read = fread(keys, sizeof(int), MAX_RECORDS, in);
        if (bytes_read == 0) break;
        total_memory += bytes_read * sizeof(int);

        for (size_t i = 0; i < bytes_read; ++i) {
            records[i].value = rand() % (range_end - range_start + 1) + range_start;
        }

        size_t bytes_written = fwrite(records, RECORD_SIZE, bytes_read, out);
        if (bytes_written != bytes_read) {
            perror("fwrite");
            break;
        }
    }

    fclose(in);
    fclose(out);

    printf("Processed %zu records with total memory usage: %zu\n", bytes_read, total_memory);
}

int main() {
    execute_shell_command("echo 'Processing data...'");

    srand(time(NULL));
    process_records("input.bin", "output.bin", 100, 999);

    return 0;
}
