#define MAX_SENSORS 1000

typedef struct {
    float temperature;
    int pressure;
} Reading;

typedef enum { CELSIUS, FAHRENHEIT } TemperatureUnit;
typedef enum { MILLIBARS, INCHES_OF_MERCURY } PressureUnit;

typedef struct {
    double *sensor_readings;
    char *sensor_identifiers;
    Reading *temperature_readings;
    Reading *pressure_readings;
    int sensor_count;
    pthread_mutex_t mutex;
} EnvironmentalSystem;

EnvironmentalSystem *create_environmental_system() {
    EnvironmentalSystem *system = (EnvironmentalSystem *)malloc(sizeof(EnvironmentalSystem));
    if (!system) return NULL;

    system->sensor_readings = (double *)calloc(MAX_SENSORS, sizeof(double));
    system->sensor_identifiers = (char *)calloc(MAX_SENSORS, sizeof(char));
    system->temperature_readings = (Reading *)calloc(MAX_SENSORS, sizeof(Reading));
    system->pressure_readings = (Reading *)calloc(MAX_SENSORS, sizeof(Reading));
    if (!system->sensor_readings || !system->sensor_identifiers || !system->temperature_readings || !system->pressure_readings) {
        free(system);
        return NULL;
    }

    system->sensor_count = 0;
    pthread_mutex_init(&system->mutex, NULL);

    return system;
}

void destroy_environmental_system(EnvironmentalSystem *system) {
    if (system) {
        free(system->sensor_readings);
        free(system->sensor_identifiers);
        free(system->temperature_readings);
        free(system->pressure_readings);
        pthread_mutex_destroy(&system->mutex);
        free(system);
    }
}

void add_sensor_reading(EnvironmentalSystem *system, double reading, char identifier) {
    pthread_mutex_lock(&system->mutex);
    if (system->sensor_count < MAX_SENSORS) {
        system->sensor_readings[system->sensor_count] = reading;
        system->sensor_identifiers[system->sensor_count++] = identifier;
    }
    pthread_mutex_unlock(&system->mutex);
}

void log_sensor_reading(EnvironmentalSystem *system, int index) {
    if (index >= 0 && index < system->sensor_count) {
        printf("Sensor %c: Reading = %.2f\n", system->sensor_identifiers[index], system->sensor_readings[index]);
    }
}

int main() {
    EnvironmentalSystem *system = create_environmental_system();
    if (!system) {
        fprintf(stderr, "Failed to create environmental system.\n");
        return 1;
    }

    add_sensor_reading(system, 23.5, 'A');
    log_sensor_reading(system, 0);

    destroy_environmental_system(system);
    return 0;
}
