using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class DataTransmission
{
    private readonly IKeyManagementService _keyManagementService;
    private readonly ICryptoTransformFactory _cryptoTransformFactory;
    private readonly IMessageDeliveryService _messageDeliveryService;

    public DataTransmission(IKeyManagementService keyManagementService, ICryptoTransformFactory cryptoTransformFactory, IMessageDeliveryService messageDeliveryService)
    {
        _keyManagementService = keyManagementService ?? throw new ArgumentNullException(nameof(keyManagementService));
        _cryptoTransformFactory = cryptoTransformFactory ?? throw new ArgumentNullException(nameof(cryptoTransformFactory));
        _messageDeliveryService = messageDeliveryService ?? throw new ArgumentNullException(nameof(messageDeliveryService));
    }

    public byte[] TransferData(string plaintext, string recipient)
    {
        try
        {
            var key = _keyManagementService.GetEncryptionKey(recipient);
            var nonce = GenerateNonce();
            var encryptedMessage = Encrypt(plaintext, key, nonce);

            _messageDeliveryService.SendMessage(encryptedMessage, recipient);

            return encryptedMessage;
        }
        catch (Exception ex)
        {
            LogError(ex);
            throw;
        }
    }

    private byte[] Encrypt(string plaintext, byte[] key, byte[] nonce)
    {
        using (var aes = Aes.Create())
        {
            aes.Key = key;
            aes.IV = nonce;

            var encryptor = aes.CreateEncryptor(aes.Key, aes.IV);
            using (var msEncrypt = new MemoryStream())
            {
                using (var csEncrypt = new CryptoStream(msEncrypt, encryptor, CryptoStreamMode.Write))
                {
                    using (var swEncrypt = new StreamWriter(csEncrypt))
                    {
                        swEncrypt.Write(plaintext);
                    }
                    return msEncrypt.ToArray();
                }
            }
        }
    }

    private byte[] GenerateNonce()
    {
        using (var rng = RandomNumberGenerator.Create())
        {
            var nonce = new byte[12]; // 96-bit nonce
            rng.GetBytes(nonce);
            return nonce;
        }
    }

    private void LogError(Exception ex)
    {
        // Implement error logging logic here, ensuring sensitive information is not exposed.
        Console.Error.WriteLine($"Error: {ex.Message}");
    }
}

public interface IKeyManagementService
{
    byte[] GetEncryptionKey(string recipient);
}

public interface ICryptoTransformFactory
{
    ICryptoTransform CreateEncryptor(byte[] key, byte[] iv);
}

public interface IMessageDeliveryService
{
    void SendMessage(byte[] message, string recipient);
}
