    *doubleArray = (double *)malloc(10 * sizeof(double));
    *charArray = (char *)malloc(10 * sizeof(char));
    *tempList = (TemperatureReading *)malloc(10 * sizeof(TemperatureReading));
    *unitArray = (TemperatureUnit *)malloc(10 * sizeof(TemperatureUnit));
}

// Function to initialize the data structures
void initializeData(double *doubleArray, char *charArray, TemperatureReading *tempList, TemperatureUnit *unitArray) {
    for (int i = 0; i < 10; i++) {
        doubleArray[i] = 0.0;
        charArray[i] = '\0';
        tempList[i].value = 0.0;
        tempList[i].unit = CELSIUS;
        tempList[i].timestamp = time(NULL);
        unitArray[i] = CELSIUS;
    }
}

// Function to populate the structs with temperature data
void populateData(double *doubleArray, char *charArray, TemperatureReading *tempList, TemperatureUnit *unitArray) {
    for (int i = 0; i < 10; i++) {
        printf("Enter temperature value for entry %d: ", i);
        scanf("%f", &tempList[i].value);
        printf("Enter unit (C/F): ");
        char unitInput;
        scanf(" %c", &unitInput);
        if (unitInput == 'F' || unitInput == 'f') {
            tempList[i].unit = FAHRENHEIT;
        } else {
            tempList[i].unit = CELSIUS;
        }
        doubleArray[i] = tempList[i].value;
        charArray[i] = tempList[i].unit == CELSIUS ? 'C' : 'F';
    }
