#include <stdio.h>
#include <stdlib.h>

#define INITIAL_CAPACITY 10

typedef struct Record {
    int key;
    long value;
} Record;

typedef struct HashTable {
    Record *records;
    int capacity;
    int size;
} HashTable;

unsigned int hash(int key, int capacity) {
    return abs(key % capacity);
}

HashTable* create_hash_table(int initial_capacity) {
    HashTable *table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    table->records = (Record*)calloc(initial_capacity, sizeof(Record));
    if (!table->records) {
        free(table);
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    table->capacity = initial_capacity;
    table->size = 0;
    return table;
}

void insert_or_update_record(HashTable *table, int key, long value) {
    unsigned int index = hash(key, table->capacity);
    while (table->records[index].key != 0 && table->records[index].key != key) {
        index = (index + 1) % table->capacity;
    }
    if (table->records[index].key == 0) {
        table->size++;
    }
    table->records[index].key = key;
    table->records[index].value = value;
}

long get_record_value(HashTable *table, int key) {
    unsigned int index = hash(key, table->capacity);
    while (table->records[index].key != 0 && table->records[index].key != key) {
        index = (index + 1) % table->capacity;
    }
    if (table->records[index].key == key) {
        return table->records[index].value;
    } else {
        fprintf(stderr, "Key not found\n");
        exit(EXIT_FAILURE);
    }
}

void free_hash_table(HashTable *table) {
    free(table->records);
    free(table);
}
```

This code provides a basic implementation of a hash table for storing records with integer keys and long values. It includes functions for creating the hash table, inserting or updating records, retrieving record values by key, and freeing the hash table when it is no longer needed. The hash function uses simple modulo arithmetic to map keys to indices in the array. Collision handling is done using linear probing.']

