#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    double value;
    unsigned short id;
    char* descriptor;
} Record;

Record* initialize_records(int num_records, const char** ids, double* weights, int weight_count) {
    if (num_records <= 0 || !ids || !weights || weight_count <= 1) {
        return NULL; // Invalid input
    }

    Record* records = (Record*)malloc(num_records * sizeof(Record));
    if (!records) {
        return NULL; // Memory allocation failed
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < num_records; ++i) {
        records[i].id = ids[i][0] - 'A'; // Simplified unique identifier extraction
        records[i].descriptor = strdup(ids[i]); // Duplicate descriptor string
        if (!records[i].descriptor) {
            pthread_mutex_unlock(&mutex);
            free(records);
            return NULL; // Memory allocation failed for descriptor
        }

        double weighted_sum = 0;
        int valid_weights = 0;
        for (int j = 0; j < weight_count; ++j) {
            if (weights[j] > 0) {
                weighted_sum += weights[j];
                ++valid_weights;
            }
        }

        records[i].value = (weighted_sum / valid_weights);
    }

    pthread_mutex_unlock(&mutex);

    return records;
}

void free_records(Record* records, int num_records) {
    if (!records || num_records <= 0) {
        return; // Invalid input
    }

    for (int i = 0; i < num_records; ++i) {
        free(records[i].descriptor);
    }
    free(records);
}

// Example usage:
int main() {
    const char* ids[] = {"A", "B", "C"};
    double weights[] = {1.0, 2.0, 3.0};
    int num_records = sizeof(ids) / sizeof(ids[0]);
    int weight_count = sizeof(weights) / sizeof(weights[0]);

    Record* records = initialize_records(num_records, ids, weights, weight_count);
    if (records) {
        // Use the records array
        free_records(records, num_records);
    }

    return 0;
}
