#include <time.h>

#define MAX_CONNECTIONS 1024

typedef struct {
    int socket_descriptor;
    char client_ip[INET_ADDRSTRLEN];
    int connection_status;
    time_t last_health_check;
} NetworkConnection;

NetworkConnection connections[MAX_CONNECTIONS];
sem_t connection_pool_mutex;
int current_connections = 0;

void initialize_connection_pool() {
    sem_init(&connection_pool_mutex, 0, 1);
}

void add_connection(int socket_descriptor, char *client_ip) {
    sem_wait(&connection_pool_mutex);
    if (current_connections < MAX_CONNECTIONS) {
        connections[current_connections].socket_descriptor = socket_descriptor;
        strcpy(connections[current_connections].client_ip, client_ip);
        connections[current_connections].connection_status = 1;
        connections[current_connections].last_health_check = time(NULL);
        current_connections++;
    }
    sem_post(&connection_pool_mutex);
}

void remove_connection(int socket_descriptor) {
    sem_wait(&connection_pool_mutex);
    for (int i = 0; i < current_connections; i++) {
        if (connections[i].socket_descriptor == socket_descriptor) {
            connections[i] = connections[current_connections - 1];
            current_connections--;
            break;
        }
    }
    sem_post(&connection_pool_mutex);
}

void health_check() {
    time_t now = time(NULL);
    for (int i = 0; i < current_connections; i++) {
        if (now - connections[i].last_health_check > 60) { // Example: Check every minute
            // Perform health check and re-establish connection if necessary
            connections[i].last_health_check = now;
        }
    }
}

void graceful_shutdown() {
    sem_wait(&connection_pool_mutex);
    for (int i = 0; i < current_connections; i++) {
        close(connections[i].socket_descriptor);
    }
    current_connections = 0;
    sem_post(&connection_pool_mutex);
}
