#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int key;
    long value;
} Record;

typedef struct HashNode {
    Record record;
    struct HashNode* next;
} HashNode;

typedef struct {
    HashNode** buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_hash_table(size_t initial_capacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->buckets = (HashNode**)calloc(initial_capacity, sizeof(HashNode*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    table->capacity = initial_capacity;
    table->size = 0;
    pthread_mutex_init(&table->lock, NULL);

    return table;
}

void destroy_hash_table(HashTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        HashNode* node = table->buckets[i];
        while (node) {
            HashNode* next = node->next;
            free(node);
            node = next;
        }
    }

    pthread_mutex_destroy(&table->lock);
    free(table->buckets);
    free(table);
}

size_t hash_function(int key, size_t capacity) {
    return abs(key) % capacity;
}

int insert_record(HashTable* table, int key, long value) {
    pthread_mutex_lock(&table->lock);

    size_t index = hash_function(key, table->capacity);
    HashNode* node = table->buckets[index];

    while (node) {
        if (node->record.key == key) {
            pthread_mutex_unlock(&table->lock);
            return -1; // Key already exists
        }
        node = node->next;
    }

    HashNode* new_node = (HashNode*)malloc(sizeof(HashNode));
    if (!new_node) {
        pthread_mutex_unlock(&table->lock);
        return -2; // Memory allocation failed
    }

    new_node->record.key = key;
    new_node->record.value = value;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;

    ++table->size;
    pthread_mutex_unlock(&table->lock);

    return 0; // Success
}

long get_record(HashTable* table, int key) {
    pthread_mutex_lock(&table->lock);

    size_t index = hash_function(key, table->capacity);
    HashNode* node = table->buckets[index];

    while (node) {
        if (node->record.key == key) {
            long value = node->record.value;
            pthread_mutex_unlock(&table->lock);
            return value; // Record found
        }
        node = node->next;
    }

    pthread_mutex_unlock(&table->lock);
    return -1; // Key not found
}

int remove_record(HashTable* table, int key) {
    pthread_mutex_lock(&table->lock);

    size_t index = hash_function(key, table->capacity);
    HashNode* node = table->buckets[index];
    HashNode* prev = NULL;

    while (node) {
        if (node->record.key == key) {
            if (prev) {
                prev->next = node->next;
            } else {
                table->buckets[index] = node->next;
            }
            free(node);
            --table->size;
            pthread_mutex_unlock(&table->lock);
            return 0; // Success
        }
        prev = node;
        node = node->next;
    }

    pthread_mutex_unlock(&table->lock);
    return -1; // Key not found
}
