const axios = require('axios');
const { execFile } = require('child_process');
const { Pool } = require('pg');

// Configuration
const API_URL = 'https://api.example.com/scripts';
const SHELL_POOL_SIZE = 10;
const TIMEOUT_MS = 60000;

// Database connection pool
const dbPool = new Pool({
  user: 'dbuser',
  host: 'localhost',
  database: 'mydatabase',
  password: 'secretpassword',
  port: 5432,
});

async function fetchScripts() {
  try {
    const response = await axios.get(API_URL);
    return response.data.scripts;
  } catch (error) {
    console.error('Failed to fetch scripts:', error);
    throw error;
  }
}

async function executeScript(scriptPath, scriptArgs = []) {
  return new Promise((resolve, reject) => {
    execFile(scriptPath, scriptArgs, { timeout: TIMEOUT_MS }, (error, stdout, stderr) => {
      if (error) {
        console.error(`Execution failed for ${scriptPath}:`, error);
        dbPool.query('INSERT INTO script_logs (script_path, status, output, error) VALUES ($1, $2, $3, $4)', [scriptPath, 'failed', stdout, stderr]);
        reject(error);
      } else {
        console.log(`Execution successful for ${scriptPath}`);
        dbPool.query('INSERT INTO script_logs (script_path, status, output) VALUES ($1, $2, $3)', [scriptPath, 'success', stdout]);
        resolve(stdout);
      }
    });
  });
}

async function runScriptsSequentially(scripts) {
  for (const script of scripts) {
    await executeScript(script.path, script.args);
  }
}

async function runScriptsConcurrently(scripts) {
  const promises = scripts.map(script => executeScript(script.path, script.args));
  await Promise.all(promises);
}

async function orchestrateScripts() {
  try {
    const scripts = await fetchScripts();
    // Uncomment the line below to run scripts sequentially
    // await runScriptsSequentially(scripts);

    // Uncomment the line below to run scripts concurrently
    await runScriptsConcurrently(scripts);
  } catch (error) {
    console.error('Orchestration failed:', error);
  }
}

orchestrateScripts();
```

