#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PROJECTS 1000
#define MEMORY_LIMIT 500 * 1024

typedef struct {
    int priority;
    char* status;
    time_t deadline;
} Project;

Project* projects[MAX_PROJECTS];
int project_count = 0;

void initialize_projects() {
    for (int i = 0; i < MAX_PROJECTS; i++) {
        projects[i] = malloc(sizeof(Project));
        projects[i]->priority = i + 1;
        projects[i]->status = strdup("Pending");
        time_t now = time(NULL);
        projects[i]->deadline = now + (i * 86400); // Adjust deadline based on priority
    }
    project_count = MAX_PROJECTS;
}

void update_statuses() {
    for (int i = 0; i < project_count; i++) {
        time_t now = time(NULL);
        if (difftime(projects[i]->deadline, now) <= 604800) { // 7 days in seconds
            projects[i]->status = strdup("In Progress");
        }
    }
}

void adjust_deadlines() {
    for (int i = 0; i < project_count; i++) {
        time_t now = time(NULL);
        int random_days = rand() % 31;
        projects[i]->deadline = now + (random_days * 86400); // Add random days
    }
}

void sort_projects_by_deadline() {
    for (int i = 0; i < project_count - 1; i++) {
        for (int j = i + 1; j < project_count; j++) {
            if (projects[i]->deadline > projects[j]->deadline) {
                Project* temp = projects[i];
                projects[i] = projects[j];
                projects[j] = temp;
            }
        }
    }
}

void remove_project(int id) {
    for (int i = 0; i < project_count; i++) {
        if (projects[i]->priority == id) {
            free(projects[i]->status);
            free(projects[i]);
            for (int j = i; j < project_count - 1; j++) {
                projects[j] = projects[j + 1];
            }
            project_count--;
            break;
        }
    }
}

void serialize_projects(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&project_count, sizeof(int), 1, file);
    for (int i = 0; i < project_count; i++) {
        fwrite(&projects[i]->priority, sizeof(int), 1, file);
        int status_len = strlen(projects[i]->status);
        fwrite(&status_len, sizeof(int), 1, file);
        fwrite(projects[i]->status, sizeof(char), status_len, file);
        fwrite(&projects[i]->deadline, sizeof(time_t), 1, file);
    }
    fclose(file);
}

void deserialize_projects(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return;

    int count;
    fread(&count, sizeof(int), 1, file);
    for (int i = 0; i < count; i++) {
        Project* project = malloc(sizeof(Project));
        fread(&project->priority, sizeof(int), 1, file);
        int status_len;
        fread(&status_len, sizeof(int), 1, file);
        project->status = malloc(status_len + 1);
        fread(project->status, sizeof(char), status_len, file);
        project->status[status_len] = '\0';
        fread(&project->deadline, sizeof(time_t), 1, file);
        projects[i] = project;
    }
    fclose(file);
}

int main() {
    srand(time(NULL));
    initialize_projects();
    update_statuses();
    adjust_deadlines();
    sort_projects_by_deadline();

    remove_project(500);

    serialize_projects("projects.dat");
    deserialize_projects("projects.dat");

    for (int i = 0; i < project_count; i++) {
        free(projects[i]->status);
        free(projects[i]);
    }

    return 0;
}
