#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_CONNECTIONS 1024
#define MAX_RECORDS 1024

typedef struct {
    int id;
    time_t last_activity;
    char *buffer;
} NetworkConnection;

typedef struct {
    long timestamp;
    int key;
    double value;
} Record;

typedef struct {
    NetworkConnection *connections;
    Record *records;
    size_t connection_count;
    size_t record_count;
    pthread_mutex_t lock;
} ConnectionManager;

void initialize_connection_manager(ConnectionManager *manager) {
    manager->connection_count = 0;
    manager->record_count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

int add_network_connection(ConnectionManager *manager, int id, char *buffer) {
    pthread_mutex_lock(&manager->lock);
    if (manager->connection_count >= MAX_CONNECTIONS) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Error: No more connections can be added
    }
    manager->connections[manager->connection_count].id = id;
    manager->connections[manager->connection_count].last_activity = time(NULL);
    manager->connections[manager->connection_count].buffer = buffer;
    manager->connection_count++;
    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

void update_connection_activity(ConnectionManager *manager, int id) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->connection_count; i++) {
        if (manager->connections[i].id == id) {
            manager->connections[i].last_activity = time(NULL);
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

int add_record(ConnectionManager *manager, long timestamp, int key, double value) {
    pthread_mutex_lock(&manager->lock);
    if (manager->record_count >= MAX_RECORDS) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Error: No more records can be added
    }
    manager->records[manager->record_count].timestamp = timestamp;
    manager->records[manager->record_count].key = key;
    manager->records[manager->record_count].value = value;
    manager->record_count++;
    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

void generate_random_records(ConnectionManager *manager, size_t count, int min_value, int max_value) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < count; i++) {
        manager->records[manager->record_count].timestamp = time(NULL) + rand() % 1000;
        manager->records[manager->record_count].key = rand() % max_value + min_value;
        manager->records[manager->record_count].value = (double)(rand() % 1000) / 100.0;
        manager->record_count++;
    }
    pthread_mutex_unlock(&manager->lock);
}

void cleanup_connection_manager(ConnectionManager *manager) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->connection_count; i++) {
        free(manager->connections[i].buffer);
    }
    free(manager->connections);
    free(manager->records);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

int main() {
    ConnectionManager manager;
    initialize_connection_manager(&manager);

    // Example usage
    add_network_connection(&manager, 1, "buffer1");
    update_connection_activity(&manager, 1);
    generate_random_records(&manager, 5, 0, 100);

    cleanup_connection_manager(&manager);
    return 0;
}
