#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PACKETS 1024
#define MAX_STREAMS 256

typedef struct {
    int protocol;
    char src_ip[16];
    char dest_ip[16];
    int payload_size;
} Packet;

typedef enum {
    ACTIVE,
    PENDING,
    COMPLETED
} StreamStatus;

typedef struct {
    Packet packets[MAX_PACKETS];
    StreamStatus status;
    pthread_mutex_t lock;
} PacketStream;

PacketStream streams[MAX_STREAMS];

void init_packet_stream(int stream_id) {
    memset(&streams[stream_id], 0, sizeof(PacketStream));
    pthread_mutex_init(&streams[stream_id].lock, NULL);
}

void add_packet_to_stream(int stream_id, Packet packet) {
    pthread_mutex_lock(&streams[stream_id].lock);
    if (streams[stream_id].status == ACTIVE && streams[stream_id].packets[0].payload_size == 0) {
        memcpy(streams[stream_id].packets, &packet, sizeof(Packet));
    } else {
        // Handle error: stream is not active or already has packets
    }
    pthread_mutex_unlock(&streams[stream_id].lock);
}

void mark_stream_completed(int stream_id) {
    pthread_mutex_lock(&streams[stream_id].lock);
    streams[stream_id].status = COMPLETED;
    pthread_mutex_unlock(&streams[stream_id].lock);
}

void* process_packets(void* arg) {
    int stream_id = *(int*)arg;
    while (1) {
        pthread_mutex_lock(&streams[stream_id].lock);
        if (streams[stream_id].status == ACTIVE && streams[stream_id].packets[0].payload_size > 0) {
            // Process packet
            printf("Processing packet from stream %d\n", stream_id);
            memset(streams[stream_id].packets, 0, sizeof(Packet));
        } else if (streams[stream_id].status == COMPLETED) {
            pthread_mutex_unlock(&streams[stream_id].lock);
            break;
        }
        pthread_mutex_unlock(&streams[stream_id].lock);
    }
    return NULL;
}

int main() {
    for (int i = 0; i < MAX_STREAMS; i++) {
        init_packet_stream(i);
    }

    pthread_t threads[MAX_STREAMS];
    int stream_ids[MAX_STREAMS];

    for (int i = 0; i < MAX_STREAMS; i++) {
        stream_ids[i] = i;
        pthread_create(&threads[i], NULL, process_packets, &stream_ids[i]);
    }

    // Simulate adding packets to streams
    Packet packet1 = {TCP, "192.168.1.1", "10.0.0.1", 1024};
    add_packet_to_stream(0, packet1);

    Packet packet2 = {UDP, "192.168.1.2", "10.0.0.2", 512};
    add_packet_to_stream(1, packet2);

    // Simulate marking a stream as completed
    mark_stream_completed(0);

    for (int i = 0; i < MAX_STREAMS; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
