#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Project {
    int priority;
    char *status;
    time_t deadline;
    time_t start_date;
} Project;

typedef struct ProjectList {
    Project **projects;
    size_t count;
    size_t capacity;
} ProjectList;

Project* create_project(int priority, const char *status, time_t deadline, time_t start_date) {
    Project *project = (Project *)malloc(sizeof(Project));
    if (!project) return NULL;

    project->priority = priority;
    project->status = strdup(status);
    if (!project->status) {
        free(project);
        return NULL;
    }
    project->deadline = deadline;
    project->start_date = start_date;

    return project;
}

ProjectList* create_project_list(size_t initial_capacity) {
    ProjectList *list = (ProjectList *)malloc(sizeof(ProjectList));
    if (!list) return NULL;

    list->projects = (Project **)calloc(initial_capacity, sizeof(Project *));
    if (!list->projects) {
        free(list);
        return NULL;
    }
    list->count = 0;
    list->capacity = initial_capacity;

    return list;
}

void destroy_project_list(ProjectList *list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->projects[i]->status);
        free(list->projects[i]);
    }
    free(list->projects);
    free(list);
}

int add_project(ProjectList *list, Project *project) {
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        Project **new_projects = (Project **)realloc(list->projects, new_capacity * sizeof(Project *));
        if (!new_projects) return -1;

        list->projects = new_projects;
        list->capacity = new_capacity;
    }

    list->projects[list->count++] = project;
    return 0;
}

int update_project(ProjectList *list, size_t index, Project *project) {
    if (index >= list->count) return -1;

    free(list->projects[index]->status);
    list->projects[index] = project;
    return 0;
}

int remove_project(ProjectList *list, size_t index) {
    if (index >= list->count) return -1;

    free(list->projects[index]->status);
    free(list->projects[index]);

    for (size_t i = index; i < list->count - 1; ++i) {
        list->projects[i] = list->projects[i + 1];
    }

    --list->count;
    return 0;
}

int initialize_project_list(ProjectList *list, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        time_t now = time(NULL);
        time_t deadline = now + rand() % 31;

        Project *project = create_project(i + 1, "Pending", deadline, now);
        if (!project) return -1;

        if (add_project(list, project)) {
            destroy_project_list(list);
            return -1;
        }
    }

    return 0;
}

int main() {
    srand(time(NULL));
    ProjectList *list = create_project_list(5);
    if (!list) {
        fprintf(stderr, "Failed to create project list\n");
        return 1;
    }

    if (initialize_project_list(list, 5)) {
        fprintf(stderr, "Failed to initialize project list\n");
        destroy_project_list(list);
        return 1;
    }

    // Example usage of update and remove operations
    Project *new_project = create_project(6, "Completed", time(NULL), time(NULL));
    if (new_project && update_project(list, 0, new_project)) {
        fprintf(stderr, "Failed to update project\n");
        destroy_project_list(list);
        free(new_project);
        return 1;
    }

    if (remove_project(list, list->count - 1)) {
        fprintf(stderr, "Failed to remove project\n");
        destroy_project_list(list);
        return 1;
    }

    destroy_project_list(list);
    return 0;
}
