#define MAX_SESSIONS 100
#define RESIZE_FACTOR 1.15

typedef struct {
    int id;
    time_t last_active;
    char** actions;
    int action_count;
} Session;

Session* sessions[MAX_SESSIONS];
int session_count = 0;

void add_session(int id, const char* action) {
    if (session_count >= MAX_SESSIONS) {
        printf("Maximum number of sessions reached.\n");
        return;
    }

    Session* new_session = malloc(sizeof(Session));
    new_session->id = id;
    new_session->last_active = time(NULL);
    new_session->actions = malloc(sizeof(char*) * 10); // Initial capacity for actions
    new_session->action_count = 0;

    char* action_copy = strdup(action);
    new_session->actions[new_session->action_count++] = action_copy;

    sessions[session_count++] = new_session;
}

void update_session(int id, const char* action) {
    for (int i = 0; i < session_count; i++) {
        if (sessions[i]->id == id) {
            time_t current_time = time(NULL);
            if (current_time > sessions[i]->last_active) {
                sessions[i]->last_active = current_time;
            }

            char* action_copy = strdup(action);
            sessions[i]->actions[sessions[i]->action_count++] = action_copy;

            // Resize actions array if needed
            if (sessions[i]->action_count >= 10) {
                sessions[i]->actions = realloc(sessions[i]->actions, sizeof(char*) * 20); // Double capacity
            }

            return;
        }
    }
}

void resize_sessions() {
    int new_capacity = MAX_SESSIONS * RESIZE_FACTOR;
    Session** new_sessions = realloc(sessions, sizeof(Session*) * new_capacity);

    if (new_sessions == NULL) {
        printf("Memory allocation failed for resizing sessions.\n");
        return;
    }

    sessions = new_sessions;
    MAX_SESSIONS = new_capacity;
}

void cleanup() {
    for (int i = 0; i < session_count; i++) {
        for (int j = 0; j < sessions[i]->action_count; j++) {
            free(sessions[i]->actions[j]);
        }
        free(sessions[i]->actions);
        free(sessions[i]);
    }

    session_count = 0;
}

int main() {
    srand(time(NULL));

    // Simulate user activity
    for (int i = 0; i < 150; i++) {
        int id = rand() % 10 + 1;
        const char* action = "Action";

        if (rand() % 2 == 0) {
            add_session(id, action);
        } else {
            update_session(id, action);
        }

        // Resize sessions array if needed
        if (session_count >= MAX_SESSIONS * RESIZE_FACTOR) {
            resize_sessions();
        }
    }

    cleanup();

    return 0;
}
