typedef struct {
    int value;
    long offset;
} record;

int allocate_memory(long *offsets, int *keys, record **records, int num_records) {
    if (num_records <= 0) return -1; // Error: Invalid number of records

    offsets = malloc(num_records * sizeof(long));
    keys = malloc(num_records * sizeof(int));
    *records = malloc(num_records * sizeof(record));

    if (!offsets || !keys || !*records) {
        free(offsets);
        free(keys);
        free(*records);
        return -2; // Error: Memory allocation failed
    }

    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < num_records; ++i) {
        (*records)[i].value = rand() % 100; // Random value for record
        do {
            (*records)[i].offset = rand() % num_records; // Generate unique offset
        } while ((*records)[i].offset == i); // Ensure no self-reference

        keys[i] = (*records)[i].offset;
    }

    return 0; // Success
}

void free_memory(long *offsets, int *keys, record *records) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) free(records);
}
