int create_data_structures(int offset_size, int key_size, int record_count) {
    long *offsets = (long *)malloc(offset_size * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        return -1;
    }

    int *keys = (int *)malloc(key_size * sizeof(int));
    if (!keys) {
        free(offsets);
        perror("Failed to allocate memory for keys");
        return -2;
    }

    record *records = (record *)calloc(record_count, sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        perror("Failed to allocate memory for records");
        return -3;
    }

    // Populate records with unique random values
    srand(time(NULL));
    int used_keys[record_count];
    for (int i = 0; i < record_count; ++i) {
        do {
            records[i].value = rand() % record_count + 1;
        } while (used_keys[records[i].value - 1]);
        used_keys[records[i].value - 1] = 1;
    }

    // Simulate memory usage and fragmentation
    size_t total_memory = offset_size * sizeof(long) + key_size * sizeof(int) + record_count * sizeof(record);
    printf("Total Memory Usage: %zu bytes\n", total_memory);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);

    return 0;
}

