    int count;
    pthread_mutex_t lock;
} SessionManager;

int generate_unique_session_id(SessionManager *manager) {
    // Implement unique session ID generation logic here
    return rand() % MAX_SESSIONS; // Placeholder for actual implementation
}

void add_session(SessionManager *manager, NetworkSession *session) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count < MAX_SESSIONS) {
        manager->sessions[manager->count++] = session;
    } else {
        printf("Session limit reached\n");
    }
    pthread_mutex_unlock(&manager->lock);
}

NetworkSession* get_session(SessionManager *manager, int id) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        if (manager->sessions[i]->id == id) {
            pthread_mutex_unlock(&manager->lock);
            return manager->sessions[i];
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

void remove_inactive_sessions(SessionManager *manager, time_t inactive_duration) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        if (time(NULL) - manager->sessions[i]->timestamp > inactive_duration) {
            // Free session resources here
            free(manager->sessions[i]);
            for (int j = i; j < manager->count - 1; j++) {
                manager->sessions[j] = manager->sessions[j + 1];
            }
            manager->count--;
            i--; // Adjust index after removal
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void initialize_session_manager(SessionManager *manager) {
    memset(manager, 0, sizeof(*manager));
    pthread_mutex_init(&manager->lock, NULL);
}

void destroy_session_manager(SessionManager *manager) {
    for (int i = 0; i < manager->count; i++) {
        free(manager->sessions[i]);
    }
    pthread_mutex_destroy(&manager->lock);
}
