} ConnectionState;

typedef struct TcpConnection {
    int client_fd;
    int server_fd;
    ConnectionState state;
    time_t last_activity;
    // Additional metadata can be added here
} TcpConnection;

typedef struct ConnectionList {
    TcpConnection** connections;
    size_t count;
    size_t capacity;
    time_t idle_timeout;
} ConnectionList;

void init_connection_list(ConnectionList* list, size_t initial_capacity, time_t timeout) {
    list->connections = (TcpConnection**)malloc(initial_capacity * sizeof(TcpConnection*));
    list->count = 0;
    list->capacity = initial_capacity;
    list->idle_timeout = timeout;
}

void free_connection_list(ConnectionList* list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->connections[i]);
    }
    free(list->connections);
}

TcpConnection* add_connection(ConnectionList* list, int client_fd, int server_fd) {
    if (list->count == list->capacity) {
        list->capacity *= 2;
        list->connections = (TcpConnection**)realloc(list->connections, list->capacity * sizeof(TcpConnection*));
    }
    TcpConnection* new_conn = (TcpConnection*)malloc(sizeof(TcpConnection));
    new_conn->client_fd = client_fd;
    new_conn->server_fd = server_fd;
    new_conn->state = TCP_CONNECTED;
    new_conn->last_activity = time(NULL);
    list->connections[list->count++] = new_conn;
    return new_conn;
}

void remove_connection(ConnectionList* list, TcpConnection* conn) {
    for (size_t i = 0; i < list->count; ++i) {
        if (list->connections[i] == conn) {
            free(list->connections[i]);
            for (size_t j = i; j < list->count - 1; ++j) {
                list->connections[j] = list->connections[j + 1];
            }
            --list->count;
            break;
        }
    }
}

void update_connection_activity(ConnectionList* list, TcpConnection* conn) {
    conn->last_activity = time(NULL);
}

void close_idle_connections(ConnectionList* list) {
    time_t now = time(NULL);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->connections[i]->state == TCP_CONNECTED && difftime(now, list->connections[i]->last_activity) > list->idle_timeout) {
            remove_connection(list, list->connections[i]);
            --i; // Adjust index after removal
        }
    }
}

// Example usage:
int main() {
    ConnectionList conn_list;
    init_connection_list(&conn_list, 10, 300); // Initial capacity of 10 connections, idle timeout of 5 minutes

    TcpConnection* conn = add_connection(&conn_list, 1234, 5678);
    update_connection_activity(&conn_list, conn);

    close_idle_connections(&conn_list);

    free_connection_list(&conn_list);
    return 0;
}
