import json
from abc import ABC, abstractmethod
from typing import Dict, Any, Callable

class Config(ABC):
    @abstractmethod
    def to_json(self) -> str:
        pass

    @classmethod
    @abstractmethod
    def from_json(cls, json_str: str) -> 'Config':
        pass

class EnvironmentConfig(Config):
    def __init__(self, settings: Dict[str, Any]):
        self.settings = settings

    def to_json(self) -> str:
        return json.dumps(self.settings)

    @classmethod
    def from_json(cls, json_str: str) -> 'EnvironmentConfig':
        return cls(json.loads(json_str))

class ConfigFactoryRegistry:
    _registry: Dict[str, Callable[[], Config]] = {}

    @staticmethod
    def register_factory(env_id: str, factory_func: Callable[[], Config]):
        ConfigFactoryRegistry._registry[env_id] = factory_func

    @staticmethod
    def create_config(env_id: str) -> Config:
        if env_id in ConfigFactoryRegistry._registry:
            return ConfigFactoryRegistry._registry[env_id]()
        else:
            raise ValueError(f"No factory registered for environment ID: {env_id}")

class DefaultConfig(EnvironmentConfig):
    def __init__(self, settings: Dict[str, Any]):
        super().__init__(settings)

# Example usage
def create_dev_config():
    return EnvironmentConfig({"debug": True, "log_level": "INFO"})

ConfigFactoryRegistry.register_factory("dev", create_dev_config)
config = ConfigFactoryRegistry.create_config("dev")
print(config.to_json())
