#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_ELEMENTS 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    int count;
} List;

void initList(List* list) {
    list->head = NULL;
    list->count = 0;
}

Node* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

void insert(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = createNode(data);
    if (list->count >= MAX_ELEMENTS) {
        free(newNode);
        printf("Maximum elements reached. Cannot insert more.\n");
        return;
    }
    if (list->head == NULL || list->head->data.RNTI > data.RNTI) {
        newNode->next = list->head;
        list->head = newNode;
    } else {
        Node* current = list->head;
        while (current->next != NULL && current->next->data.RNTI < data.RNTI) {
            current = current->next;
        }
        newNode->next = current->next;
        current->next = newNode;
    }
    list->count++;
}

void validateAndInsert(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    // Implement validation logic here
    if (data.CRCFLAG == 1) {
        insert(list, data);
    } else {
        printf("Validation failed. CRCFLAG is not set.\n");
    }
}

void deleteNode(List* list, int RNTI) {
    Node* current = list->head;
    Node* previous = NULL;
    while (current != NULL && current->data.RNTI != RNTI) {
        previous = current;
        current = current->next;
    }
    if (current == NULL) {
        printf("Node with RNTI %d not found\n", RNTI);
        return;
    }
    if (previous == NULL) {
        list->head = current->next;
    } else {
        previous->next = current->next;
    }
    free(current);
    list->count--;
}

void sortList(List* list) {
    // Implement sorting logic here
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        while (next != NULL && next->data.RNTI < current->data.RNTI) {
            NFAPI_CRC_INDICATION_PDU_T temp = current->data;
            current->data = next->data;
            next->data = temp;
            next = next->next;
        }
        current = current->next;
    }
}

void freeList(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->count = 0;
}

