    for (int i = 0; i < 3; i++) {
        (*char_arr)[i] = safe_malloc(max_length * sizeof(char));
        for (int j = 0; j < max_length; j++) {
            (*char_arr)[i][j] = 'a' + rand() % 26;
        }
    }
}

void populate_points_array(point*** points_arr, int max_points) {
    (*points_arr) = safe_malloc(max_points * sizeof(point*));
    for (int i = 0; i < max_points; i++) {
        (*points_arr)[i] = safe_malloc(sizeof(point));
        do {
            (*points_arr)[i]->x = rand() % 100;
            (*points_arr)[i]->y = rand() % 100;
        } while (i > 0 && (*points_arr)[i]->x == (*points_arr)[i - 1]->x && (*points_arr)[i]->y == (*points_arr)[i - 1]->y);
    }
}

void calculate_distances(float** distances_arr, point*** points_arr) {
    int n = (*points_arr)->length;
    *distances_arr = safe_malloc(n * (n - 1) / 2 * sizeof(float));
    int index = 0;
    for (int i = 0; i < n - 1; i++) {
        for (int j = i + 1; j < n; j++) {
            (*distances_arr)[index++] = sqrt(pow((*points_arr)[i]->x - (*points_arr)[j]->x, 2) + pow((*points_arr)[i]->y - (*points_arr)[j]->y, 2));
        }
    }
}

void sort_distances(float** distances_arr, int n) {
    qsort(*distances_arr, n, sizeof(float), (int (*)(const void *, const void *))compare_floats);
}

int compare_floats(const void *a, const void *b) {
    return (*(float*)a - *(float*)b);
