#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} Record;

typedef struct {
    // Define the structure fields as per NFAPI_CRC_INDICATION_PDU_T
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void manage_memory(long n, long max_offset, int m, int min_value, int max_value, int N) {
    // Allocate memory for offsets and keys arrays
    long* offsets = (long*)malloc(n * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets array\n");
        return;
    }

    int* keys = (int*)malloc(n * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Memory allocation failed for keys array\n");
        free(offsets);
        return;
    }

    // Initialize offsets array with unique values
    for (long i = 0; i < n; ++i) {
        offsets[i] = i % max_offset;
    }

    // Initialize keys array with unique values and ensure keys[i] < offsets[i]
    int key_set[1024]; // Assuming max_key <= 1023 for simplicity
    for (int i = 0; i < n; ++i) {
        while (1) {
            int key = rand() % max_value;
            if (key < offsets[i] && !key_set[key]) {
                keys[i] = key;
                key_set[key] = 1;
                break;
            }
        }
    }

    // Allocate memory for record structures
    Record* records = (Record*)malloc(m * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records array\n");
        free(offsets);
        free(keys);
        return;
    }

    // Populate record values with random integers within the specified range
    srand(time(NULL)); // Seed for random number generation
    for (int i = 0; i < m; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    // Allocate memory and populate NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* crc_indications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_indications) {
        fprintf(stderr, "Memory allocation failed for CRC indications array\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    // Populate CRC indications with unique RNTI values and random CRCFLAG
    int rnti_set[1024]; // Assuming max RNTI <= 1023 for simplicity
    for (int i = 0; i < N; ++i) {
        while (1) {
            int rnti = rand() % 1024;
            if (!rnti_set[rnti]) {
                crc_indications[i].RNTI = rnti;
                crc_indications[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG
                rnti_set[rnti] = 1;
                break;
            }
        }
    }

    // Sort the list based on RNTI values in ascending order
    for (int i = 0; i < N - 1; ++i) {
        for (int j = i + 1; j < N; ++j) {
            if (crc_indications[i].RNTI > crc_indications[j].RNTI) {
                NFAPI_CRC_INDICATION_PDU_T temp = crc_indications[i];
                crc_indications[i] = crc_indications[j];
                crc_indications[j] = temp;
            }
        }
    }

    // Deallocate all allocated memory
    free(offsets);
    free(keys);
    free(records);
    free(crc_indications);
}

int main() {
    long n = 100, max_offset = 500, m = 200, min_value = -100, max_value = 100;
    int N = 30;

    manage_memory(n, max_offset, m, min_value, max_value, N);

    return 0;
}
