#define MAX_CONNECTIONS 1024
#define MAX_IP_LENGTH 16

typedef struct {
    int socket_descriptor;
    char client_ip[MAX_IP_LENGTH];
    int connection_status;
} Connection;

typedef struct {
    Connection *connections;
    int size;
    int capacity;
    pthread_mutex_t lock;
} ConnectionPool;

void init_connection_pool(ConnectionPool *pool) {
    pool->size = 0;
    pool->capacity = MAX_CONNECTIONS;
    pool->connections = (Connection *)malloc(pool->capacity * sizeof(Connection));
    pthread_mutex_init(&pool->lock, NULL);
}

void destroy_connection_pool(ConnectionPool *pool) {
    free(pool->connections);
    pthread_mutex_destroy(&pool->lock);
}

int add_connection(ConnectionPool *pool, int socket_descriptor, const char *client_ip) {
    pthread_mutex_lock(&pool->lock);
    if (pool->size >= pool->capacity) {
        // Resize the connection pool
        pool->capacity *= 2;
        pool->connections = (Connection *)realloc(pool->connections, pool->capacity * sizeof(Connection));
    }
    Connection new_connection = {socket_descriptor, client_ip, 1};
    pool->connections[pool->size++] = new_connection;
    pthread_mutex_unlock(&pool->lock);
    return 0;
}

void remove_connection(ConnectionPool *pool, int socket_descriptor) {
    pthread_mutex_lock(&pool->lock);
    for (int i = 0; i < pool->size; i++) {
        if (pool->connections[i].socket_descriptor == socket_descriptor) {
            // Move the last element to the current position
            pool->connections[i] = pool->connections[--pool->size];
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

void monitor_connection_health(ConnectionPool *pool) {
    pthread_mutex_lock(&pool->lock);
    for (int i = 0; i < pool->size; i++) {
        if (!check_connection_status(pool->connections[i].socket_descriptor)) {
            // Re-establish the connection
            re_establish_connection(&pool->connections[i]);
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

void log_connection_metrics(ConnectionPool *pool) {
    pthread_mutex_lock(&pool->lock);
    int total_connections = pool->size;
    double average_latency = calculate_average_latency(pool);
    double success_rate = calculate_success_rate(pool);
    double throughput = calculate_throughput(pool);

    printf("Total Connections: %d\n", total_connections);
    printf("Average Latency: %.2f ms\n", average_latency);
    printf("Success Rate: %.2f%%\n", success_rate * 100);
    printf("Throughput: %.2f connections/s\n", throughput);

    pthread_mutex_unlock(&pool->lock);
}

