    if (max_payload_size > MAX_PAYLOAD_SIZE) {
        log_error("Payload size exceeds maximum limit.");
        return NULL;
    }

    MAC_PDU* pdu_array = (MAC_PDU*)malloc(num_pdus * sizeof(MAC_PDU));
    if (!pdu_array) {
        log_error("Memory allocation failed for PDU array.");
        return NULL;
    }

    for (int i = 0; i < num_pdus; ++i) {
        pdu_array[i].payload = (char*)malloc(max_payload_size);
        if (!pdu_array[i].payload) {
            log_error("Memory allocation failed for payload.");
            // Free previously allocated memory
            for (int j = 0; j < i; ++j) {
                free(pdu_array[j].payload);
            }
            free(pdu_array);
            return NULL;
        }
    }

    return pdu_array;
}

void process_input_values(int* input_values, int max_values) {
    int count = 0;
    while (1) {
        int value;
        if (scanf("%d", &value) != 1) {
            break;
        }
        if (count >= max_values) {
            log_error("Input values exceed maximum limit. Truncating.");
            break;
        }
        input_values[count++] = value;
    }

    // Sort the array in descending order
    for (int i = 0; i < count - 1; ++i) {
        for (int j = i + 1; j < count; ++j) {
            if (input_values[i] < input_values[j]) {
                int temp = input_values[i];
                input_values[i] = input_values[j];
                input_values[j] = temp;
            }
        }
    }

    // Print the largest integer
    if (count > 0) {
        printf("Largest integer: %d\n", input_values[0]);
    } else {
        printf("No valid integers provided.\n");
    }
}

void free_pdu_array(MAC_PDU* pdu_array, int num_pdus) {
    for (int i = 0; i < num_pdus; ++i) {
        free(pdu_array[i].payload);
    }
    free(pdu_array);
}

int main() {
    int num_pdus;
    printf("Enter the number of PDUs: ");
    scanf("%d", &num_pdus);

    MAC_PDU* pdu_array = initialize_and_process_pdu_array(num_pdus, MAX_PAYLOAD_SIZE);
    if (!pdu_array) {
        return 1;
    }

    // Process input values
    int input_values[MAX_INPUT_VALUES];
    process_input_values(input_values, MAX_INPUT_VALUES);

    // Free allocated memory
    free_pdu_array(pdu_array, num_pdus);

    return 0;
}
