public class BatchProcessingService {
    private final ExecutorService executor;
    private final BlockingQueue<String> queue;
    private final Random random;

    public BatchProcessingService(int poolSize) {
        this.executor = Executors.newFixedThreadPool(poolSize);
        this.queue = new LinkedBlockingQueue<>();
        this.random = new Random(System.currentTimeMillis());
    }

    public void submitBatch(String[] batch) {
        for (String item : batch) {
            queue.add(item);
        }
    }

    public void startProcessing() {
        executor.submit(() -> {
            while (!Thread.currentThread().isInterrupted()) {
                try {
                    String item = queue.take();
                    processItem(item);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        });
    }

    private void processItem(String item) {
        long timestamp = System.currentTimeMillis() + random.nextLong();
        // Process the item with the timestamp
    }

    public void shutdown() {
        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }
    }

    public static void main(String[] args) {
        BatchProcessingService service = new BatchProcessingService(10);
        String[] batch = {"item1", "item2", "item3"};
        service.submitBatch(batch);
        service.startProcessing();
