NFAPI_CRC_INDICATION_PDU_T* create_and_populate_pdu_list(int N) {
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < N; i++) {
        pdu_list[i].RX_UE_INFORMATION_TAG = i + 1;
        pdu_list[i].RNTI = i * 2;

        NFAPI_CRC_INDICATION_REL8_TAG* crc_tag = (NFAPI_CRC_INDICATION_REL8_TAG*)malloc(sizeof(NFAPI_CRC_INDICATION_REL8_TAG));
        if (!crc_tag) {
            fprintf(stderr, "Memory allocation failed\n");
            free(pdu_list);
            return NULL;
        }

        // Randomly set CRCFLAG
        crc_tag->CRCFLAG = rand() % 2;

        pdu_list[i].crc_tag = crc_tag;
    }

    return pdu_list;
}

void query_available_crypto_functions() {
    EVP_CIPHER* cipher;
    const EVP_CIPHER* ciphers[] = {EVP_aes_128_cbc(), EVP_aes_256_cbc()};
    int num_ciphers = sizeof(ciphers) / sizeof(ciphers[0]);

    for (int i = 0; i < num_ciphers; i++) {
        cipher = ciphers[i];
        if (!EVP_CIPHER_is_a(cipher, "AES")) {
            fprintf(stderr, "Unsupported cryptographic cipher: %s\n", EVP_CIPHER_name(cipher));
        }
    }

    EVP_MD* md;
    const EVP_MD* mds[] = {EVP_sha256(), EVP_sha512()};
    int num_mds = sizeof(mds) / sizeof(mds[0]);

    for (int i = 0; i < num_mds; i++) {
        md = mds[i];
        if (!EVP_MD_is_a(md, "SHA")) {
            fprintf(stderr, "Unsupported cryptographic hash function: %s\n", EVP_MD_name(md));
        }
    }
}

int main() {
    int N = 10;
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = create_and_populate_pdu_list(N);
    if (pdu_list) {
        query_available_crypto_functions();
        // Free allocated memory
        for (int i = 0; i < N; i++) {
            free(pdu_list[i].crc_tag);
        }
        free(pdu_list);
    }

    return 0;
}
