#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    long timestamp;
    float key_id;
    double magnitude;
    char* message;
} Event;

typedef struct {
    Event** events;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} EventQueue;

Event* create_event(long timestamp, float key_id, double magnitude, const char* message) {
    Event* event = (Event*)malloc(sizeof(Event));
    if (event == NULL) return NULL;
    event->timestamp = timestamp;
    event->key_id = key_id;
    event->magnitude = magnitude;
    event->message = strdup(message);
    return event;
}

void free_event(Event* event) {
    if (event != NULL) {
        free(event->message);
        free(event);
    }
}

EventQueue* create_event_queue(size_t capacity) {
    EventQueue* queue = (EventQueue*)malloc(sizeof(EventQueue));
    if (queue == NULL) return NULL;
    queue->events = (Event**)calloc(capacity, sizeof(Event*));
    if (queue->events == NULL) {
        free(queue);
        return NULL;
    }
    queue->capacity = capacity;
    queue->size = 0;
    pthread_mutex_init(&queue->lock, NULL);
    return queue;
}

void enqueue_event(EventQueue* queue, Event* event) {
    pthread_mutex_lock(&queue->lock);
    if (queue->size < queue->capacity) {
        queue->events[queue->size++] = event;
    }
    pthread_mutex_unlock(&queue->lock);
}

Event* dequeue_event(EventQueue* queue) {
    pthread_mutex_lock(&queue->lock);
    Event* event = NULL;
    if (queue->size > 0) {
        event = queue->events[--queue->size];
        queue->events[queue->size] = NULL; // Avoid dangling pointer
    }
    pthread_mutex_unlock(&queue->lock);
    return event;
}

void free_event_queue(EventQueue* queue) {
    if (queue != NULL) {
        for (size_t i = 0; i < queue->size; ++i) {
            free_event(queue->events[i]);
        }
        free(queue->events);
        pthread_mutex_destroy(&queue->lock);
        free(queue);
    }
}

// Additional functions for random number generation, string manipulation,
// and garbage collection can be implemented here.
