#define MAX_MEMORY_LIMIT 1024 * 1024 // 1 MB

typedef struct {
    int offset;
    char key[50];
    char record[100];
} DataRecord;

DataRecord* initialize_data_structures(int initial_size, int max_memory_limit) {
    if (initial_size <= 0 || max_memory_limit <= 0) {
        fprintf(stderr, "Invalid input parameters.\n");
        return NULL;
    }

    size_t record_size = sizeof(DataRecord);
    size_t total_size = initial_size * record_size;

    if (total_size > max_memory_limit) {
        fprintf(stderr, "Initial size exceeds maximum memory limit.\n");
        return NULL;
    }

    DataRecord* records = (DataRecord*)malloc(total_size);
    if (!records) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < initial_size; i++) {
        records[i].offset = i * record_size;
        snprintf(records[i].key, sizeof(records[i].key), "Key%d", i);
        snprintf(records[i].record, sizeof(records[i].record), "Record%d", i);
    }

    return records;
}

void free_data_structures(DataRecord* records) {
    if (records) {
        free(records);
    }
}

int main() {
    int initial_size = 100;
    int max_memory_limit = MAX_MEMORY_LIMIT;

    DataRecord* records = initialize_data_structures(initial_size, max_memory_limit);

    if (records) {
        printf("Data structures initialized successfully.\n");
        // Use the data structures here
        free_data_structures(records);
    }

    return 0;
}
