typedef struct L2_HEADER {
    // Define the fields of the L2_HEADER structure
} L2_HEADER;

typedef struct L2_DATA {
    // Define the fields of the L2_DATA structure, including a checksum field
} L2_DATA;

typedef struct L2_MESSAGE {
    L2_HEADER header;
    L2_DATA data;
    unsigned long sequence_number;
    time_t timestamp;
    struct L2_MESSAGE *next;
} L2_MESSAGE;

typedef struct {
    L2_MESSAGE *head;
    pthread_mutex_t lock;
} L2_LIST;

void init_l2_list(L2_LIST *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

int insert_l2_message(L2_LIST *list, L2_HEADER header, L2_DATA data, unsigned long sequence_number, time_t timestamp) {
    pthread_mutex_lock(&list->lock);
    L2_MESSAGE *new_message = (L2_MESSAGE *)malloc(sizeof(L2_MESSAGE));
    if (!new_message) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }
    new_message->header = header;
    new_message->data = data;
    new_message->sequence_number = sequence_number;
    new_message->timestamp = timestamp;
    new_message->next = NULL;

    if (!list->head || list->head->sequence_number > sequence_number) {
        new_message->next = list->head;
        list->head = new_message;
    } else {
        L2_MESSAGE *current = list->head;
        while (current->next && current->next->sequence_number < sequence_number) {
            current = current->next;
        }
        new_message->next = current->next;
        current->next = new_message;
    }

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

int lookup_l2_message(L2_LIST *list, unsigned long sequence_number, time_t timestamp) {
    pthread_mutex_lock(&list->lock);
    L2_MESSAGE *current = list->head;
    while (current) {
        if (current->sequence_number == sequence_number && current->timestamp == timestamp) {
            pthread_mutex_unlock(&list->lock);
            return 0; // Found
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return -1; // Not found
}

int delete_l2_message(L2_LIST *list, unsigned long sequence_number, time_t timestamp) {
    pthread_mutex_lock(&list->lock);
    L2_MESSAGE *current = list->head;
    L2_MESSAGE *prev = NULL;
    while (current) {
        if (current->sequence_number == sequence_number && current->timestamp == timestamp) {
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }
            free(current);
            pthread_mutex_unlock(&list->lock);
            return 0; // Deleted
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return -1; // Not found
}

void destroy_l2_list(L2_LIST *list) {
    pthread_mutex_lock(&list->lock);
    L2_MESSAGE *current = list->head;
    while (current) {
        L2_MESSAGE *next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
