#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_KEYS 1000
#define RESIZE_FACTOR 1.1

typedef struct {
    int key;
    int offset;
    void* data;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} RecordCollection;

RecordCollection* create_record_collection() {
    RecordCollection* collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->records = (Record*)calloc(MAX_KEYS, sizeof(Record));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->capacity = MAX_KEYS;
    collection->size = 0;
    pthread_mutex_init(&collection->mutex, NULL);

    return collection;
}

void destroy_record_collection(RecordCollection* collection) {
    if (collection) {
        for (size_t i = 0; i < collection->size; ++i) {
            free(collection->records[i].data);
        }
        free(collection->records);
        pthread_mutex_destroy(&collection->mutex);
        free(collection);
    }
}

int add_record(RecordCollection* collection, int key, int offset, void* data) {
    pthread_mutex_lock(&collection->mutex);

    if (collection->size >= collection->capacity * 0.9) {
        size_t new_capacity = (size_t)(collection->capacity * RESIZE_FACTOR);
        Record* new_records = (Record*)realloc(collection->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&collection->mutex);
            return -1;
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    for (size_t i = 0; i < collection->size; ++i) {
        if (collection->records[i].key == key) {
            pthread_mutex_unlock(&collection->mutex);
            return -2; // Duplicate key
        }
    }

    collection->records[collection->size].key = key;
    collection->records[collection->size].offset = offset;
    collection->records[collection->size].data = data;
    ++collection->size;

    pthread_mutex_unlock(&collection->mutex);
    return 0;
}

// Additional functions for key generation, error handling, and performance optimization can be added here.
