#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 1024

typedef struct {
    double amount;
    char* description;
} Item;

typedef struct {
    double* transactionAmounts;
    char** transactionIDs;
    Item** items;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} TransactionData;

TransactionData* createTransactionData() {
    TransactionData* data = (TransactionData*)malloc(sizeof(TransactionData));
    if (!data) return NULL;

    data->transactionAmounts = (double*)malloc(INITIAL_CAPACITY * sizeof(double));
    data->transactionIDs = (char**)malloc(INITIAL_CAPACITY * sizeof(char*));
    data->items = (Item**)malloc(INITIAL_CAPACITY * sizeof(Item*));
    if (!data->transactionAmounts || !data->transactionIDs || !data->items) {
        free(data);
        return NULL;
    }

    data->count = 0;
    data->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&data->lock, NULL);

    return data;
}

void destroyTransactionData(TransactionData* data) {
    if (!data) return;

    for (size_t i = 0; i < data->count; ++i) {
        free(data->transactionIDs[i]);
        free(data->items[i]->description);
        free(data->items[i]);
    }

    free(data->transactionAmounts);
    free(data->transactionIDs);
    free(data->items);
    pthread_mutex_destroy(&data->lock);
    free(data);
}

void resizeTransactionData(TransactionData* data) {
    size_t newCapacity = data->capacity * 2;
    double* newAmounts = (double*)realloc(data->transactionAmounts, newCapacity * sizeof(double));
    char** newIDs = (char**)realloc(data->transactionIDs, newCapacity * sizeof(char*));
    Item** newItems = (Item**)realloc(data->items, newCapacity * sizeof(Item*));

    if (!newAmounts || !newIDs || !newItems) {
        fprintf(stderr, "Memory reallocation failed\n");
        return;
    }

    data->transactionAmounts = newAmounts;
    data->transactionIDs = newIDs;
    data->items = newItems;
    data->capacity = newCapacity;
}

void addTransaction(TransactionData* data, double amount, const char* id, const char* description) {
    pthread_mutex_lock(&data->lock);

    if (data->count == data->capacity) {
        resizeTransactionData(data);
    }

