#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_CONNECTIONS 1000
#define RESIZE_FACTOR 25

typedef struct Message {
    char *data;
    size_t length;
} Message;

typedef struct Connection {
    int id;
    time_t last_communication;
    Message *messages;
    int message_count;
    pthread_mutex_t lock;
} Connection;

Connection *connections[MAX_CONNECTIONS];
int connection_count = 0;
pthread_mutex_t connections_lock;

void initialize_connections() {
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        connections[i] = NULL;
    }
    pthread_mutex_init(&connections_lock, NULL);
}

void cleanup_connections() {
    pthread_mutex_lock(&connections_lock);
    for (int i = 0; i < connection_count; i++) {
        Connection *conn = connections[i];
        if (conn != NULL) {
            for (int j = 0; j < conn->message_count; j++) {
                free(conn->messages[j].data);
            }
            free(conn->messages);
            pthread_mutex_destroy(&conn->lock);
            free(conn);
        }
    }
    connection_count = 0;
    pthread_mutex_unlock(&connections_lock);
}

void add_or_update_connection(int id, time_t timestamp) {
    pthread_mutex_lock(&connections_lock);
    Connection *conn = NULL;
    for (int i = 0; i < connection_count; i++) {
        if (connections[i]->id == id) {
            conn = connections[i];
            break;
        }
    }

    if (conn == NULL && connection_count < MAX_CONNECTIONS) {
        conn = malloc(sizeof(Connection));
        conn->id = id;
        conn->last_communication = timestamp;
        conn->messages = malloc(10 * sizeof(Message)); // Initial capacity
        conn->message_count = 0;
        pthread_mutex_init(&conn->lock, NULL);
        connections[connection_count++] = conn;
    } else if (conn != NULL) {
        conn->last_communication = timestamp;
    }

    pthread_mutex_unlock(&connections_lock);
}

void simulate_network_traffic() {
    srand(time(NULL));
    for (int i = 0; i < 10000; i++) {
        int id = rand() % MAX_CONNECTIONS;
        time_t timestamp = time(NULL) - rand() % 3600; // Random timestamp within the last hour
        add_or_update_connection(id, timestamp);
    }
}

int main() {
    initialize_connections();
    simulate_network_traffic();
    cleanup_connections();
    return 0;
}
```

