void resize_record_array(RecordArray* array) {
    size_t new_capacity = (size_t)(array->capacity * RESIZE_FACTOR);
    Record* new_records = (Record*)aligned_alloc(64, new_capacity * sizeof(Record));
    if (!new_records) return;

    pthread_mutex_lock(&array->lock);
    memcpy(new_records, array->records, array->count * sizeof(Record));
