    system->max_profiles = initial_profiles;
    system->max_logs = initial_logs;
    system->memory_footprint = 0;
    system->max_memory_footprint = initial_profiles * sizeof(UserProfile) + initial_logs * sizeof(ActivityLog);

    return system;
}

