import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.atomic.AtomicInteger;

public class StringHashProcessor {

    private static final int BATCH_SIZE = 10_000;
    private static final int MAX_ACTIVE_REQUESTS = 100;
    private static final int QUEUE_CAPACITY = 100_000;
    private static final AtomicInteger activeRequests = new AtomicInteger(0);
    private static final BlockingQueue<String> queue = new LinkedBlockingQueue<>(QUEUE_CAPACITY);

    public void processStrings(String[] strings) {
        if (activeRequests.incrementAndGet() > MAX_ACTIVE_REQUESTS) {
            throw new IllegalStateException("Too many active requests");
        }
        try {
            for (String str : strings) {
                if (str == null || str.length() > 1_048_576) {
                    continue; // Skip invalid inputs
                }
                queue.put(str);
            }
            processBatch();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } finally {
            activeRequests.decrementAndGet();
        }
    }

    private void processBatch() throws InterruptedException {
        while (!queue.isEmpty()) {
            String[] batch = new String[BATCH_SIZE];
            int count = 0;
            for (int i = 0; i < BATCH_SIZE && !queue.isEmpty(); i++) {
                batch[i] = queue.take();
                count++;
            }
            persistHashes(batch, count);
        }
    }

    private void persistHashes(String[] strings, int count) {
        // Integrate with external data ingestion service to persist hash values
        for (int i = 0; i < count; i++) {
            String str = strings[i];
            try {
                String md5Hash = calculateMD5(str);
                // Persist md5Hash in the database
            } catch (NoSuchAlgorithmException e) {
                // Handle exception
            }
        }
    }

    private String calculateMD5(String input) throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("MD5");
        byte[] hashBytes = digest.digest(input.getBytes());
        StringBuilder sb = new StringBuilder();
        for (byte b : hashBytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public void healthCheck() {
        // Report the current state of the system
        System.out.println("Active threads: " + activeRequests.get());
        System.out.println("Memory usage: " + Runtime.getRuntime().totalMemory() - Runtime.getRuntime().freeMemory());
        System.out.println("Queue length: " + queue.size());
        // Check database connection status
    }
}
