} record;

typedef struct {
    long* offsets;
    int* keys;
    record** records;
    time_t* timestamps;
    int* statuses;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} data_structures;

data_structures* create_data_structures() {
    data_structures* ds = (data_structures*)aligned_alloc(64, sizeof(data_structures));
    if (!ds) return NULL;

    ds->offsets = (long*)aligned_alloc(64, MAX_RECORDS * sizeof(long));
    ds->keys = (int*)aligned_alloc(64, MAX_RECORDS * sizeof(int));
    ds->records = (record**)aligned_alloc(64, MAX_RECORDS * sizeof(record*));
    ds->timestamps = (time_t*)aligned_alloc(64, MAX_RECORDS * sizeof(time_t));
    ds->statuses = (int*)aligned_alloc(64, MAX_RECORDS * sizeof(int));

    if (!ds->offsets || !ds->keys || !ds->records || !ds->timestamps || !ds->statuses) {
        free(ds);
        return NULL;
    }

    ds->capacity = MAX_RECORDS;
    ds->count = 0;
    pthread_mutex_init(&ds->lock, NULL);

    return ds;
}

void destroy_data_structures(data_structures* ds) {
    if (!ds) return;

    for (size_t i = 0; i < ds->count; ++i) {
        free(ds->records[i]);
    }

    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    free(ds->timestamps);
    free(ds->statuses);
    pthread_mutex_destroy(&ds->lock);
    free(ds);
}

void resize_data_structures(data_structures* ds) {
    size_t new_capacity = (size_t)(ds->capacity * (1 + RESIZE_THRESHOLD));
    long* new_offsets = (long*)aligned_alloc(64, new_capacity * sizeof(long));
    int* new_keys = (int*)aligned_alloc(64, new_capacity * sizeof(int));
    record** new_records = (record**)aligned_alloc(64, new_capacity * sizeof(record*));
    time_t* new_timestamps = (time_t*)aligned_alloc(64, new_capacity * sizeof(time_t));
    int* new_statuses = (int*)aligned_alloc(64, new_capacity * sizeof(int));

    if (!new_offsets || !new_keys || !new_records || !new_timestamps || !new_statuses) {
        return;
    }

    for (size_t i = 0; i < ds->count; ++i) {
        new_records[i] = ds->records[i];
    }

    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    free(ds->timestamps);
    free(ds->statuses);

    ds->offsets = new_offsets;
    ds->keys = new_keys;
    ds->records = new_records;
    ds->timestamps = new_timestamps;
    ds->statuses = new_statuses;
    ds->capacity = new_capacity;
}

void add_record(data_structures* ds, int value, int key) {
    pthread_mutex_lock(&ds->lock);
    if (ds->count >= ds->capacity) {
        resize_data_structures(ds);
    }
    record* rec = (record*)malloc(sizeof(record));
    rec->value = value;
    rec->key = &ds->keys[ds->count];
    *rec->key = key;
    rec->timestamp = time(NULL);
    rec->status = 1;
    ds->records[ds->count] = rec;
    ds->offsets[ds->count] = (long)rec;
    ds->timestamps[ds->count] = rec->timestamp;
    ds->statuses[ds->count] = rec->status;
    ++ds->count;
    pthread_mutex_unlock(&ds->lock);
}

void archive_old_records(data_structures* ds, size_t threshold) {
    pthread_mutex_lock(&ds->lock);
    for (size_t i = 0; i < ds->count; ++i) {
        if (time(NULL) - ds->timestamps[i] > threshold && ds->statuses[i] == 0) {
            free(ds->records[i]);
            memmove(&ds->records[i], &ds->records[i + 1], (ds->count - i - 1) * sizeof(record*));
            memmove(&ds->offsets[i], &ds->offsets[i + 1], (ds->count - i - 1) * sizeof(long));
            memmove(&ds->timestamps[i], &ds->timestamps[i + 1], (ds->count - i - 1) * sizeof(time_t));
            memmove(&ds->statuses[i], &ds->statuses[i + 1], (ds->count - i - 1) * sizeof(int));
            --ds->count;
        }
    }
    pthread_mutex_unlock(&ds->lock);
}

void update_record(data_structures* ds, int key, int new_value) {
    pthread_mutex_lock(&ds->lock);
    for (size_t i = 0; i < ds->count; ++i) {
        if (*ds->records[i]->key == key) {
            ds->records[i]->value = new_value;
            ds->records[i]->timestamp = time(NULL);
            break;
        }
    }
    pthread_mutex_unlock(&ds->lock);
}

void cleanup_data_structures(data_structures* ds) {
    destroy_data_structures(ds);
}
