#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_NAME_LENGTH 256
#define MAX_HOBBY_LENGTH 128
#define MAX_PROFILES 1000
#define MAX_MEMORY_FOOTPRINT (10 * 1024 * 1024) // 10 MB

typedef struct Hobby {
    char name[MAX_HOBBY_LENGTH];
    struct Hobby* next;
} Hobby;

typedef struct UserProfile {
    char name[MAX_NAME_LENGTH];
    int age;
    Hobby* hobbies;
} UserProfile;

typedef struct ProfileManager {
    UserProfile profiles[MAX_PROFILES];
    size_t profile_count;
    size_t memory_usage;
    size_t max_memory_usage;
} ProfileManager;

ProfileManager* create_profile_manager(size_t max_memory_usage) {
    if (max_memory_usage > MAX_MEMORY_FOOTPRINT) {
        return NULL; // Exceeds maximum allowed memory footprint
    }
    ProfileManager* manager = (ProfileManager*)malloc(sizeof(ProfileManager));
    if (!manager) {
        return NULL; // Memory allocation failed
    }
    memset(manager, 0, sizeof(ProfileManager));
    manager->max_memory_usage = max_memory_usage;
    return manager;
}

void destroy_profile_manager(ProfileManager* manager) {
    for (size_t i = 0; i < manager->profile_count; ++i) {
        Hobby* hobby = manager->profiles[i].hobbies;
        while (hobby) {
            Hobby* next = hobby->next;
            free(hobby);
            hobby = next;
        }
    }
    free(manager);
}

int add_profile(ProfileManager* manager, const char* name, int age) {
    if (manager->profile_count >= MAX_PROFILES) {
        return -1; // Maximum number of profiles reached
    }
    UserProfile* profile = &manager->profiles[manager->profile_count];
    strncpy(profile->name, name, MAX_NAME_LENGTH);
    profile->age = age;
    profile->hobbies = NULL;
    manager->profile_count++;
    return 0;
}

int add_hobby(ProfileManager* manager, size_t profile_index, const char* hobby) {
    if (profile_index >= manager->profile_count) {
        return -1; // Invalid profile index
    }
    Hobby** hobbies_ptr = &manager->profiles[profile_index].hobbies;
    while (*hobbies_ptr) {
        hobbies_ptr = &(*hobbies_ptr)->next;
    }
    *hobbies_ptr = (Hobby*)malloc(sizeof(Hobby));
    if (!*hobbies_ptr) {
        return -1; // Memory allocation failed
    }
    strncpy((*hobbies_ptr)->name, hobby, MAX_HOBBY_LENGTH);
    (*hobbies_ptr)->next = NULL;
    manager->memory_usage += sizeof(Hobby) + strlen(hobby) + 1;
    if (manager->memory_usage > manager->max_memory_usage) {
        // Handle memory usage limit exceeded
        return -2;
    }
    return 0;
}

void remove_profile(ProfileManager* manager, size_t profile_index) {
    if (profile_index >= manager->profile_count) {
        return; // Invalid profile index
    }
    Hobby* hobby = manager->profiles[profile_index].hobbies;
    while (hobby) {
        Hobby* next = hobby->next;
        free(hobby);
        hobby = next;
    }
    for (size_t i = profile_index; i < manager->profile_count - 1; ++i) {
        manager->profiles[i] = manager->profiles[i + 1];
    }
    manager->profile_count--;
}

void update_profile_age(ProfileManager* manager, size_t profile_index, int new_age) {
    if (profile_index >= manager->profile_count) {
        return; // Invalid profile index
    }
    manager->profiles[profile_index].age = new_age;
}
