#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_ENTRIES 1000000

typedef struct {
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicList;

void initDynamicList(DynamicList *list) {
    list->entries = (NFAPI_CRC_INDICATION_PDU_T *)malloc(MAX_ENTRIES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->entries) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    list->count = 0;
    list->capacity = MAX_ENTRIES;
    pthread_mutex_init(&list->lock, NULL);
}

void destroyDynamicList(DynamicList *list) {
    free(list->entries);
    pthread_mutex_destroy(&list->lock);
}

int addEntry(DynamicList *list, int RNTI, int CRCFLAG) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        fprintf(stderr, "Dynamic list is full\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    for (size_t i = 0; i < list->count; ++i) {
        if (list->entries[i].RNTI == RNTI) {
            pthread_mutex_unlock(&list->lock);
            return -2; // Duplicate RNTI
        }
    }
    list->entries[list->count].RNTI = RNTI;
    list->entries[list->count].CRCFLAG = CRCFLAG;
    ++list->count;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int removeEntry(DynamicList *list, int RNTI) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->entries[i].RNTI == RNTI) {
            for (size_t j = i; j < list->count - 1; ++j) {
                list->entries[j] = list->entries[j + 1];
            }
            --list->count;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return -1; // RNTI not found
}

int queryEntry(DynamicList *list, int RNTI) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->entries[i].RNTI == RNTI) {
            pthread_mutex_unlock(&list->lock);
            return list->entries[i].CRCFLAG;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return -1; // RNTI not found
}

int main() {
    DynamicList list;
    initDynamicList(&list);

    addEntry(&list, 12345, 0);
    addEntry(&list, 67890, 1);

    printf("CRCFLAG for RNTI 12345: %d\n", queryEntry(&list, 12345));
    printf("CRCFLAG for RNTI 67890: %d\n", queryEntry(&list, 67890));

    removeEntry(&list, 12345);

    printf("CRCFLAG for RNTI 12345 after removal: %d\n", queryEntry(&list, 12345));

    destroyDynamicList(&list);
    return 0;
}
