#include <stdio.h>
#include <stdlib.h>
#include <semaphore.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_PROCESSES 100

typedef struct {
    sem_t *semaphores[MAX_PROCESSES];
    int process_count;
    pthread_mutex_t counter_lock;
} SemaphoreManager;

SemaphoreManager manager;

void initialize_manager(int num_processes) {
    manager.process_count = num_processes;
    for (int i = 0; i < num_processes; i++) {
        manager.semaphores[i] = sem_open("/semaphore", O_CREAT, 0644, 1);
        if (manager.semaphores[i] == SEM_FAILED) {
            perror("Failed to create semaphore");
            exit(EXIT_FAILURE);
        }
    }
    pthread_mutex_init(&manager.counter_lock, NULL);
}

void destroy_manager() {
    for (int i = 0; i < manager.process_count; i++) {
        sem_close(manager.semaphores[i]);
        sem_unlink("/semaphore");
    }
    pthread_mutex_destroy(&manager.counter_lock);
}

void acquire_semaphore(int process_id) {
    if (sem_wait(manager.semaphores[process_id]) == -1) {
        perror("Failed to wait on semaphore");
        exit(EXIT_FAILURE);
    }
}

void release_semaphore(int process_id) {
    if (sem_post(manager.semaphores[process_id]) == -1) {
        perror("Failed to post semaphore");
        exit(EXIT_FAILURE);
    }
}

int main() {
    int num_processes = 5;
    initialize_manager(num_processes);

    pthread_t threads[num_processes];
    for (int i = 0; i < num_processes; i++) {
        pthread_create(&threads[i], NULL, process_task, (void *)(long)i);
    }

    for (int i = 0; i < num_processes; i++) {
        pthread_join(threads[i], NULL);
    }

    destroy_manager();
    return 0;
}

void *process_task(void *arg) {
    int process_id = (int)(long)arg;

    acquire_semaphore(process_id);

    // Simulate resource access
    printf("Process %d accessing shared resource\n", process_id);
    sleep(1);

    release_semaphore(process_id);

    return NULL;
}
