#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    double timestamp;
    char status;
    float measurement;
} Entry;

typedef struct {
    Entry* entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DataStructure;

void init_data_structure(DataStructure* ds, size_t initial_capacity) {
    ds->entries = (Entry*)aligned_alloc(64, initial_capacity * sizeof(Entry));
    ds->capacity = initial_capacity;
    ds->count = 0;
    pthread_mutex_init(&ds->lock, NULL);
}

void resize_data_structure(DataStructure* ds) {
    size_t new_capacity = ds->capacity * 1.1;
    Entry* new_entries = (Entry*)aligned_alloc(64, new_capacity * sizeof(Entry));
    for (size_t i = 0; i < ds->count; ++i) {
        new_entries[i] = ds->entries[i];
    }
    pthread_mutex_lock(&ds->lock);
    free(ds->entries);
    ds->entries = new_entries;
    ds->capacity = new_capacity;
    pthread_mutex_unlock(&ds->lock);
}

void add_entry(DataStructure* ds, double timestamp, char status, float measurement) {
    if (ds->count >= ds->capacity) {
        resize_data_structure(ds);
    }
    pthread_mutex_lock(&ds->lock);
    ds->entries[ds->count].timestamp = timestamp;
    ds->entries[ds->count].status = status;
    ds->entries[ds->count].measurement = measurement;
    ++ds->count;
    pthread_mutex_unlock(&ds->lock);
}

void cleanup_data_structure(DataStructure* ds) {
    pthread_mutex_lock(&ds->lock);
    free(ds->entries);
    ds->entries = NULL;
    ds->capacity = 0;
    ds->count = 0;
    pthread_mutex_unlock(&ds->lock);
    pthread_mutex_destroy(&ds->lock);
}

// Serialization and deserialization functions would be implemented here
```

