public class ConfigLoader
{
    private readonly ConfigParser _parser;

    public ConfigLoader(ConfigParser parser)
    {
        _parser = parser;
    }

    public async Task<GameConfig> LoadConfigAsync(string jsonPath, string yamlPath, string xmlPath)
    {
        var config = new GameConfig();

        try
        {
            if (File.Exists(jsonPath))
            {
                var jsonContent = await File.ReadAllTextAsync(jsonPath);
                config = _parser.ParseJson(jsonContent);
            }

            if (File.Exists(yamlPath))
            {
                var yamlContent = await File.ReadAllTextAsync(yamlPath);
                var tempConfig = _parser.ParseYaml(yamlContent);
                MergeConfigs(config, tempConfig);
            }

            if (File.Exists(xmlPath))
            {
                var xmlContent = await File.ReadAllTextAsync(xmlPath);
                var tempConfig = _parser.ParseXml(xmlContent);
                MergeConfigs(config, tempConfig);
            }
        }
        catch
        {
            // Fallback to default values from embedded XML
            config = LoadDefaultConfigFromEmbeddedXml();
        }

        return config;
    }

    private void MergeConfigs(GameConfig target, GameConfig source)
    {
        if (source.ResolutionWidth > 0) target.ResolutionWidth = source.ResolutionWidth;
        if (source.ResolutionHeight > 0) target.ResolutionHeight = source.ResolutionHeight;
        if (source.NumberOfPlayers > 0) target.NumberOfPlayers = source.NumberOfPlayers;
        if (source.PlayerHealthPoints != null && source.PlayerHealthPoints.Any()) target.PlayerHealthPoints = source.PlayerHealthPoints;
        if (source.SpawnPoints != null && source.SpawnPoints.Any()) target.SpawnPoints = source.SpawnPoints;
    }

    private GameConfig LoadDefaultConfigFromEmbeddedXml()
    {
        // Implement default config loading from embedded XML
        return new GameConfig();
    }
}

