#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_NODE_SIZE 1024
#define MIN_NODE_SIZE 64
#define MAX_CHILDREN 10
#define MAX_LEAVES 100
#define MAX_TREE_DEPTH 10

typedef enum { ROOT, CHILD, LEAF } NodeType;

typedef struct Node {
    NodeType type;
    size_t size;
    void* data;
    struct Node** children;
    int num_children;
    struct Node* parent;
} Node;

Node* create_node(NodeType type, size_t size) {
    Node* node = (Node*)aligned_alloc(64, sizeof(Node));
    if (!node) return NULL;
    memset(node, 0, sizeof(Node));
    node->type = type;
    node->size = size;
    node->data = aligned_alloc(64, size);
    if (!node->data) {
        free(node);
        return NULL;
    }
    return node;
}

void init_node(Node* node) {
    if (node->type == LEAF) {
        for (int i = 0; i < node->size; ++i) {
            ((char*)node->data)[i] = rand() % 256;
        }
    } else {
        for (int i = 0; i < node->num_children; ++i) {
            init_node(node->children[i]);
        }
    }
}

void print_tree_size(Node* root, size_t* total_size) {
    *total_size += root->size;
    if (root->type != LEAF) {
        for (int i = 0; i < root->num_children; ++i) {
            print_tree_size(root->children[i], total_size);
        }
    }
}

double calculate_average_size(Node* root, size_t total_nodes) {
    size_t total_size;
    print_tree_size(root, &total_size);
    return (double)total_size / total_nodes;
}

void read_leaf_sizes(Node* leaf, int max_depth) {
    if (max_depth <= 0 || leaf->type != LEAF) return;
    printf("Enter size for leaf node: ");
    scanf("%zu", &leaf->size);
    if (leaf->size < MIN_NODE_SIZE || leaf->size > MAX_NODE_SIZE) {
        fprintf(stderr, "Invalid size. Must be between %zu and %zu.\n", MIN_NODE_SIZE, MAX_NODE_SIZE);
        exit(EXIT_FAILURE);
    }
    leaf->data = aligned_alloc(64, leaf->size);
    if (!leaf->data) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < leaf->size; ++i) {
        ((char*)leaf->data)[i] = rand() % 256;
    }
}

void free_tree(Node* root) {
    if (!root) return;
    if (root->type != LEAF) {
        for (int i = 0; i < root->num_children; ++i) {
            free_tree(root->children[i]);
        }
        free(root->children);
    }
    free(root->data);
    free(root);
}

int main() {
    srand(time(NULL));
    Node* root = create_node(ROOT, MAX_NODE_SIZE);
    if (!root) {
        fprintf(stderr, "Memory allocation failed.\n");
        return EXIT_FAILURE;
    }

    // Initialize tree structure and data
    init_node(root);

    // Read leaf sizes from standard input
    read_leaf_sizes(root, MAX_TREE_DEPTH);

    // Calculate and print total size and average size
    size_t total_size;
    double average_size = calculate_average_size(root, 1);
    printf("Total size: %zu\n", total_size);
    printf("Average size: %.2f\n", average_size);

    // Free allocated memory
    free_tree(root);

    return EXIT_SUCCESS;
}
