Graph* createGraph(int vertexCount) {
    if (vertexCount <= 0 || vertexCount > MAX_VERTICES) {
        fprintf(stderr, "Invalid vertex count\n");
        return NULL;
    }

    Graph* graph = (Graph*)malloc(sizeof(Graph));
    if (!graph) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    graph->vertices = (Vertex*)calloc(vertexCount, sizeof(Vertex));
    if (!graph->vertices) {
        free(graph);
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    graph->vertexCount = vertexCount;
    graph->edgeCount = 0;

    for (int i = 0; i < vertexCount; i++) {
        graph->vertices[i].id = i + 1;
        graph->vertices[i].edges = (Edge*)calloc(MAX_EDGES, sizeof(Edge));
        if (!graph->vertices[i].edges) {
            freeGraph(graph);
            fprintf(stderr, "Memory allocation failed\n");
            return NULL;
        }
        graph->vertices[i].capacity = MAX_EDGES;
    }

    return graph;
}

void freeGraph(Graph* graph) {
    for (int i = 0; i < graph->vertexCount; i++) {
        free(graph->vertices[i].edges);
    }
    free(graph->vertices);
