#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 1000

typedef enum { ACTIVE, INACTIVE, SUSPENDED } SubscriptionState;

typedef struct {
    int subscriber_ID;
    double latest_usage;
    char service_code[5];
    time_t last_update;
    SubscriptionState status;
} ServiceRecord;

ServiceRecord records[MAX_RECORDS];
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_records() {
    for (int i = 0; i < MAX_RECORDS; i++) {
        records[i].subscriber_ID = -1;
    }
}

int find_available_index(int start_index, int end_index) {
    pthread_mutex_lock(&lock);
    for (int i = start_index; i <= end_index; i++) {
        if (records[i].subscriber_ID == -1) {
            pthread_mutex_unlock(&lock);
            return i;
        }
    }
    pthread_mutex_unlock(&lock);
    return -1;
}

void update_service_record(int subscriber_ID, double latest_usage, char* service_code, SubscriptionState status) {
    int index = find_available_index(0, MAX_RECORDS - 1);
    if (index == -1) {
        printf("No available slot to update record.\n");
        return;
    }

    pthread_mutex_lock(&lock);
    records[index].subscriber_ID = subscriber_ID;
    records[index].latest_usage = latest_usage;
    strcpy(records[index].service_code, service_code);
    records[index].last_update = time(NULL);
    records[index].status = status;
    pthread_mutex_unlock(&lock);

    printf("Record updated for subscriber ID: %d\n", subscriber_ID);
}

void* thread_function(void* arg) {
    int id = *(int*)arg;
    double usage = (double)(rand() % 1000) / 10.0; // Random usage between 0 and 100
    char code[5];
    sprintf(code, "S%d", id);
    update_service_record(id, usage, code, ACTIVE);
    free(arg);
    return NULL;
}

int main() {
    srand(time(NULL));
    initialize_records();

    pthread_t threads[MAX_RECORDS];
    for (int i = 0; i < MAX_RECORDS; i++) {
        int* id = malloc(sizeof(int));
        *id = i + 1;
        pthread_create(&threads[i], NULL, thread_function, id);
    }

    for (int i = 0; i < MAX_RECORDS; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
