import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.List;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;

public class CryptoLibrary {

    private static final BlockingQueue<String> requestQueue = new LinkedBlockingQueue<>(5000);

    public static void main(String[] args) {
        // Start processing thread
        Thread processorThread = new Thread(() -> processRequests());
        processorThread.start();

        // Example usage
        List<String> strings = List.of("example1", "example2");
        try {
            List<String> hashes = batchProcess(strings);
            System.out.println(hashes);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public static void submitRequest(String input) throws InterruptedException {
        if (input == null || input.length() > 1048576) { // 1 MB
            throw new IllegalArgumentException("Invalid input");
        }
        requestQueue.put(input);
    }

    private static void processRequests() {
        while (true) {
            try {
                String input = requestQueue.take();
                String hash = computeHash(input, "MD5");
                System.out.println("Processed: " + input + " -> " + hash);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }
    }

    public static List<String> batchProcess(List<String> inputs) throws Exception {
        for (String input : inputs) {
            submitRequest(input);
        }
        return requestQueue.stream()
                           .map(CryptoLibrary::computeHash)
                           .toList();
    }

    private static String computeHash(String input, String algorithm) throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance(algorithm);
        byte[] hashBytes = digest.digest(input.getBytes());
        StringBuilder hexString = new StringBuilder();
        for (byte b : hashBytes) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

    public static void registerAlgorithm(String name, MessageDigest digest) {
        // Placeholder for dynamic registration logic
    }
}
