#define MAX_UE_CONTEXTS 1000

typedef enum {
    IDLE,
    CONNECTED,
    INACTIVE
} MobilityState;

typedef struct {
    int ue_id;
    char serving_plmn[16];
    MobilityState state;
    time_t last_updated;
} LTE_UE_Context;

typedef struct {
    long offset;
    int key;
} Record;

typedef struct {
    pthread_mutex_t lock;
    LTE_UE_Context *ue_contexts[MAX_UE_CONTEXTS];
    Record *long_offsets[MAX_UE_CONTEXTS];
    int *int_keys[MAX_UE_CONTEXTS];
    int record_count;
} UE_Context_Manager;

void initialize_manager(UE_Context_Manager *manager) {
    pthread_mutex_init(&manager->lock, NULL);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        manager->ue_contexts[i] = NULL;
        manager->long_offsets[i] = NULL;
        manager->int_keys[i] = NULL;
    }
    manager->record_count = 0;
}

void add_or_update_ue_context(UE_Context_Manager *manager, int ue_id, char *plmn, MobilityState state) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (manager->ue_contexts[i] != NULL && manager->ue_contexts[i]->ue_id == ue_id) {
            free(manager->ue_contexts[i]);
            break;
        }
    }
    LTE_UE_Context *new_context = malloc(sizeof(LTE_UE_Context));
    new_context->ue_id = ue_id;
    strncpy(new_context->serving_plmn, plmn, sizeof(new_context->serving_plmn) - 1);
    new_context->state = state;
    new_context->last_updated = time(NULL);
    manager->ue_contexts[ue_id % MAX_UE_CONTEXTS] = new_context;
    pthread_mutex_unlock(&manager->lock);
}

void initialize_records(UE_Context_Manager *manager, int start_index, int end_index) {
    for (int i = start_index; i <= end_index; i++) {
        Record *record = malloc(sizeof(Record));
        record->offset = rand();
        record->key = rand() % 100;
        manager->long_offsets[i] = record;
        manager->int_keys[i] = &record->key;
    }
}

void free_manager(UE_Context_Manager *manager) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (manager->ue_contexts[i] != NULL) {
            free(manager->ue_contexts[i]);
        }
        if (manager->long_offsets[i] != NULL) {
            free(manager->long_offsets[i]);
        }
    }
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}
