#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 10
#define GROWTH_FACTOR 1.5

typedef struct Transaction {
    char date[20];
    double amount;
    char type[20];
    struct Transaction* next;
} Transaction;

typedef struct UserProfile {
    char name[50];
    int age;
    char email[100];
    Transaction* transactions;
    int transaction_count;
    pthread_mutex_t lock;
    int ref_count;
} UserProfile;

typedef struct ProfileList {
    UserProfile** profiles;
    size_t capacity;
    size_t size;
    pthread_mutex_t list_lock;
} ProfileList;

ProfileList* create_profile_list() {
    ProfileList* list = (ProfileList*)malloc(sizeof(ProfileList));
    if (!list) return NULL;
    list->profiles = (UserProfile**)calloc(INITIAL_CAPACITY, sizeof(UserProfile*));
    if (!list->profiles) {
        free(list);
        return NULL;
    }
    list->capacity = INITIAL_CAPACITY;
    list->size = 0;
    pthread_mutex_init(&list->list_lock, NULL);
    return list;
}

void destroy_profile_list(ProfileList* list) {
    if (list) {
        for (size_t i = 0; i < list->size; ++i) {
            UserProfile* profile = list->profiles[i];
            if (profile) {
                pthread_mutex_destroy(&profile->lock);
                Transaction* trans = profile->transactions;
                while (trans) {
                    Transaction* next = trans->next;
                    free(trans);
                    trans = next;
                }
                free(profile);
            }
        }
        free(list->profiles);
        pthread_mutex_destroy(&list->list_lock);
        free(list);
    }
}

int add_profile(ProfileList* list, const char* name, int age, const char* email) {
    if (list->size >= list->capacity) {
        size_t new_capacity = (size_t)(list->capacity * GROWTH_FACTOR);
        UserProfile** new_profiles = (UserProfile**)realloc(list->profiles, new_capacity * sizeof(UserProfile*));
        if (!new_profiles) return -1;
        list->profiles = new_profiles;
        list->capacity = new_capacity;
    }
    UserProfile* profile = (UserProfile*)malloc(sizeof(UserProfile));
    if (!profile) return -1;
    pthread_mutex_init(&profile->lock, NULL);
    profile->ref_count = 1;
    strcpy(profile->name, name);
    profile->age = age;
    strcpy(profile->email, email);
    profile->transactions = NULL;
    profile->transaction_count = 0;
    list->profiles[list->size++] = profile;
    return 0;
}

// Additional functions for managing profiles and transactions would be implemented here
