class NFAPI_CRC_INDICATION_PDU_T {
    constructor() {
        this.RX_UE_INFORMATION_TAG = Math.random().toString(36).substr(2, 9);
        this.RNTI = Math.floor(Math.random() * 10000);
        this.CRC_INDICATION_REL8_TAG = Math.random() > 0.5;
    }
}

class MemoryPool {
    constructor(size) {
        this.pool = [];
        for (let i = 0; i < size; i++) {
            this.pool.push(new NFAPI_CRC_INDICATION_PDU_T());
        }
    }

    get() {
        return this.pool.pop();
    }

    release(obj) {
        this.pool.push(obj);
    }
}

const memoryPool = new MemoryPool(100);

function renderNFAPIFooter() {
    let html = '';
    for (let i = 0; i < 10; i++) { // Example: Render 10 scripts
        const scriptObj = memoryPool.get();
        scriptObj.CRC_INDICATION_REL8_TAG = Math.random() > 0.5; // Update CRCFLAG randomly
        html += `<script key="${scriptObj.RX_UE_INFORMATION_TAG}">${JSON.stringify(scriptObj)}</script>`;
        memoryPool.release(scriptObj);
    }
    return html;
}

