} Service;

Service* create_service(int duration, const char *type, time_t start_time) {
    Service *service = (Service *)malloc(sizeof(Service));
    if (service == NULL) {
        return NULL;
    }
    service->duration = duration;
    service->type = strdup(type);
    service->start_time = start_time;
    return service;
}

void update_service_type(Service *service, const char *new_type) {
    free(service->type);
    service->type = strdup(new_type);
}

void recalculate_start_time(Service *service, time_t new_start_time) {
    service->start_time = new_start_time;
}

void log_change(Service *service, const char *change_description) {
    printf("Service ID: %p, Change: %s\n", (void *)service, change_description);
}

void export_service_list(Service **services, int count, const char *filename) {
    FILE *file = fopen(filename, "w");
    if (file == NULL) {
        perror("Failed to open file for writing");
        return;
    }
    fprintf(file, "[\n");
    for (int i = 0; i < count; i++) {
        fprintf(file, "  {\n");
        fprintf(file, "    \"duration\": %d,\n", services[i]->duration);
        fprintf(file, "    \"type\": \"%s\",\n", services[i]->type);
        fprintf(file, "    \"start_time\": \"%ld\"\n", (long)services[i]->start_time);
        if (i < count - 1) {
            fprintf(file, "  },\n");
        } else {
            fprintf(file, "  }\n");
        }
    }
    fprintf(file, "]\n");
    fclose(file);
}

int main() {
    Service *services[10];
    time_t current_time = time(NULL);

    for (int i = 0; i < 10; i++) {
        services[i] = create_service(30 + i * 30, "Scheduled", current_time + i * 60);
    }

    // Simulate service completion and update
    update_service_type(services[0], "Completed");
    recalculate_start_time(services[0], time(NULL) + 120);

    log_change(services[0], "Service completed and start time recalculated");

    export_service_list(services, 10, "services.json");

    for (int i = 0; i < 10; i++) {
        free(services[i]->type);
        free(services[i]);
    }

    return 0;
}
