#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_PACKET_SIZE 1024
#define SESSION_EXPIRY_TIME 3600

typedef struct {
    int connection_id;
    time_t start_timestamp;
    char *packet_data;
} NetworkSession;

typedef struct Node {
    NetworkSession session;
    struct Node *next;
} SessionNode;

typedef struct {
    SessionNode *head;
    pthread_mutex_t lock;
} SessionList;

void initialize_session_list(SessionList *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void destroy_session_list(SessionList *list) {
    pthread_mutex_lock(&list->lock);
    SessionNode *current = list->head;
    while (current != NULL) {
        SessionNode *next = current->next;
        free(current->session.packet_data);
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int add_session(SessionList *list, NetworkSession session) {
    pthread_mutex_lock(&list->lock);
    SessionNode *new_node = (SessionNode *)malloc(sizeof(SessionNode));
    if (new_node == NULL) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }
    new_node->session = session;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void *cleanup_expired_sessions(void *arg) {
    SessionList *list = (SessionList *)arg;
    while (1) {
        time_t current_time = time(NULL);
        pthread_mutex_lock(&list->lock);
        SessionNode *current = list->head;
        SessionNode *prev = NULL;
        while (current != NULL) {
            if (difftime(current_time, current->session.start_timestamp) > SESSION_EXPIRY_TIME) {
                if (prev == NULL) {
                    list->head = current->next;
                } else {
                    prev->next = current->next;
                }
                free(current->session.packet_data);
                free(current);
                current = prev->next;
            } else {
                prev = current;
                current = current->next;
            }
        }
        pthread_mutex_unlock(&list->lock);
        sleep(SESSION_EXPIRY_TIME); // Check every hour
    }
}

void iterate_session_list(SessionList *list) {
    pthread_mutex_lock(&list->lock);
    SessionNode *current = list->head;
    while (current != NULL) {
        printf("Connection ID: %d, Start Timestamp: %ld\n", current->session.connection_id, current->session.start_timestamp);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

int main() {
    SessionList session_list;
    initialize_session_list(&session_list);

    // Example usage
    NetworkSession new_session = {12345, time(NULL), (char *)malloc(MAX_PACKET_SIZE)};
    add_session(&session_list, new_session);

    pthread_t cleanup_thread;
    pthread_create(&cleanup_thread, NULL, cleanup_expired_sessions, &session_list);
    pthread_detach(cleanup_thread);

    iterate_session_list(&session_list);

    destroy_session_list(&session_list);
    return 0;
