    ConnectionStatus status;
} Connection;

Connection* connections[MAX_CONNECTIONS];
int connectionCount = 0;

void addPacket(int connectionId, int sequenceNumber, const char* data) {
    for (int i = 0; i < connectionCount; i++) {
        if (connections[i]->id == connectionId) {
            if (connections[i]->packetCount < MAX_PACKETS_PER_CONNECTION) {
                connections[i]->packets[connections[i]->packetCount].sequenceNumber = sequenceNumber;
                strcpy(connections[i]->packets[connections[i]->packetCount].data, data);
                connections[i]->packetCount++;
                connections[i]->lastActiveTime = time(NULL);
            }
            return;
        }
    }
}

void simulateNetworkTraffic() {
    srand(time(NULL));
    for (int i = 0; i < MAX_CONNECTIONS * 2; i++) {
        int connectionId = rand() % MAX_CONNECTIONS;
        if (rand() % 2 == 0) {
            addPacket(connectionId, rand(), "Data Packet");
        } else {
            // Update existing connection status or packet
        }
    }
}

void cleanupConnections() {
    for (int i = 0; i < connectionCount; i++) {
        free(connections[i]);
    }
    connectionCount = 0;
}

int main() {
    simulateNetworkTraffic();
    cleanupConnections();
    return 0;
}
