typedef struct {
    int value;
    time_t timestamp;
    int *key;
    char *metadata;
} record;

record **records = NULL;
long *offsets = NULL;
int *keys = NULL;
time_t *timestamps = NULL;
char **metadatas = NULL;
int record_count = 0;
int capacity = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void log_event(const char *message) {
    // Implement logging logic here
}

void initialize_data_structures() {
    pthread_mutex_lock(&lock);
    if (records == NULL) {
        records = (record **)malloc(sizeof(record *) * capacity);
        offsets = (long *)aligned_alloc(64, sizeof(long) * capacity);
        keys = (int *)aligned_alloc(64, sizeof(int) * capacity);
        timestamps = (time_t *)aligned_alloc(64, sizeof(time_t) * capacity);
        metadatas = (char **)malloc(sizeof(char *) * capacity);
    }
    pthread_mutex_unlock(&lock);
}

void resize_records() {
    int new_capacity = capacity * GROWTH_FACTOR;
    record **new_records = (record **)realloc(records, sizeof(record *) * new_capacity);
    long *new_offsets = (long *)aligned_realloc(offsets, sizeof(long) * new_capacity);
    int *new_keys = (int *)aligned_realloc(keys, sizeof(int) * new_capacity);
    time_t *new_timestamps = (time_t *)aligned_realloc(timestamps, sizeof(time_t) * new_capacity);
    char **new_metadatas = (char **)realloc(metadatas, sizeof(char *) * new_capacity);

    if (new_records == NULL || new_offsets == NULL || new_keys == NULL || new_timestamps == NULL || new_metadatas == NULL) {
        log_event("Memory reallocation failed");
        return;
    }

    records = new_records;
    offsets = new_offsets;
    keys = new_keys;
    timestamps = new_timestamps;
    metadatas = new_metadatas;
    capacity = new_capacity;
}

void allocate_record(int key, const char *metadata) {
    pthread_mutex_lock(&lock);
    if (record_count >= capacity) {
        resize_records();
    }

    records[record_count] = (record *)malloc(sizeof(record));
    offsets[record_count] = (long)records[record_count];
    keys[record_count] = key;
    timestamps[record_count] = time(NULL);
    metadatas[record_count] = strdup(metadata);

    record_count++;
    pthread_mutex_unlock(&lock);
}

void set_random_values(int min, int max) {
    srand(time(NULL));
    for (int i = 0; i < record_count; i++) {
        records[i]->value = rand() % (max - min + 1) + min;
    }
}

void cleanup_data_structures() {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < record_count; i++) {
        free(records[i]);
        free(metadatas[i]);
    }

    free(records);
    free(offsets);
    free(keys);
    free(timestamps);
    free(metadatas);
    records = NULL;
    offsets = NULL;
    keys = NULL;
    timestamps = NULL;
    metadatas = NULL;
    record_count = 0;
    capacity = 0;
    pthread_mutex_unlock(&lock);
}
