import java.util.concurrent.*;
import java.util.logging.Logger;

public class ConnectionManager {
    private static final Logger logger = Logger.getLogger(ConnectionManager.class.getName());
    private ExecutorService executor;
    private BlockingQueue<Runnable> taskQueue;
    private int maxConnections;
    private int retryAttempts;
    private long initialBackoff;
    private double backoffFactor;

    public ConnectionManager(int maxConnections, int retryAttempts, long initialBackoff, double backoffFactor) {
        this.maxConnections = maxConnections;
        this.retryAttempts = retryAttempts;
        this.initialBackoff = initialBackoff;
        this.backoffFactor = backoffFactor;
        taskQueue = new LinkedBlockingQueue<>(maxConnections);
        executor = Executors.newFixedThreadPool(maxConnections);
    }

    public void connect(String address) {
        if (taskQueue.size() < maxConnections) {
            taskQueue.offer(() -> attemptConnection(address));
        } else {
            logger.warning("Max connections reached, backpressure applied.");
        }
    }

    private void attemptConnection(String address) {
        int attempts = 0;
        while (attempts < retryAttempts) {
            try {
                // Simulate connection attempt
                long responseTime = simulateConnection(address);
                logger.info("Connected to " + address + " in " + responseTime + "ms");
                return;
            } catch (Exception e) {
                attempts++;
                long backoff = calculateBackoff(attempts);
                logger.warning("Failed to connect to " + address + ", retrying in " + backoff + "ms");
                try {
                    Thread.sleep(backoff);
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                }
            }
        }
        logger.severe("Failed to connect to " + address + " after " + retryAttempts + " attempts.");
    }

    private long simulateConnection(String address) throws Exception {
        // Simulate connection logic
        return 100; // Simulated response time in milliseconds
    }

    private long calculateBackoff(int attempt) {
        return (long) (initialBackoff * Math.pow(backoffFactor, attempt));
    }

    public void shutdown() {
        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }
    }

    public static void main(String[] args) {
        ConnectionManager manager = new ConnectionManager(1000, 5, 100, 2);
        for (int i = 0; i < 1500; i++) {
            manager.connect("remote-address-" + i);
        }
        manager.shutdown();
    }
}
