    time(&now);
    for (int i = 0; i < MAX_PROJECTS; i++) {
        double elapsed_time = difftime(now, projects[i].start_date);
        double total_duration = difftime(projects[i].deadline, projects[i].start_date);
        if (elapsed_time > total_duration / 2) {
            if (elapsed_time > total_duration) {
                free(projects[i].status);
                projects[i].status = strdup("Late");
            } else {
                free(projects[i].status);
                projects[i].status = strdup("Completed");
            }
        } else {
            free(projects[i].status);
            projects[i].status = strdup("In Progress");
        }
    }
}

char* process_string(const char* input, size_t max_size) {
    if (strlen(input) < max_size - 1) {
        char* result = (char*)malloc(max_size + 1);
        if (!result) {
            fprintf(stderr, "Memory allocation failed: Out of memory.\n");
            return NULL;
        }
        strcpy(result, input);
        strcat(result, "/");
        return result;
    } else {
        return strdup(input);
    }
}

