typedef struct {
    uint8_t L2Header[14];
    uint8_t *payload;
    size_t payload_size;
    time_t timestamp;
} MAC_PDU;

typedef struct {
    MAC_PDU **array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray *da = malloc(sizeof(DynamicArray));
    if (!da) return NULL;

    da->array = malloc(initial_capacity * sizeof(MAC_PDU *));
    if (!da->array) {
        free(da);
        return NULL;
    }

    da->capacity = initial_capacity;
    da->size = 0;
    pthread_mutex_init(&da->lock, NULL);

    return da;
}

void destroy_dynamic_array(DynamicArray *da) {
    for (size_t i = 0; i < da->size; ++i) {
        free(da->array[i]->payload);
        free(da->array[i]);
    }
    free(da->array);
    pthread_mutex_destroy(&da->lock);
    free(da);
}

int add_pdu(DynamicArray *da, MAC_PDU *pdu) {
    pthread_mutex_lock(&da->lock);

    if (da->size >= da->capacity) {
        size_t new_capacity = da->capacity ? da->capacity * 2 : 1;
        MAC_PDU **new_array = realloc(da->array, new_capacity * sizeof(MAC_PDU *));
        if (!new_array) {
            pthread_mutex_unlock(&da->lock);
            return -1; // Memory allocation failed
        }
        da->array = new_array;
        da->capacity = new_capacity;
    }

    da->array[da->size++] = pdu;

    pthread_mutex_unlock(&da->lock);
    return 0;
}

