struct alignas(64) Record {
    long offset;
    int key;
    struct {
        int value;
    } data;
};

class SandeshClient {
public:
    SandeshClient(size_t initial_capacity)
        : capacity(initial_capacity), size(0), records(new Record[capacity]), keys(new std::string[capacity]) {}

    ~SandeshClient() {
        cleanup();
    }

    void add_record(int key, int value) {
        if (size >= capacity) resize(capacity * 1.1);
        records[size].offset = size;
        records[size].key = key;
        records[size].data.value = value;
        keys[key] = std::to_string(key);
        ++size;
    }

    void cleanup() {
        delete[] records;
        delete[] keys;
        records = nullptr;
        keys = nullptr;
        capacity = 0;
        size = 0;
    }

private:
    size_t capacity;
    size_t size;
    Record* records;
    std::string* keys;

    void resize(size_t new_capacity) {
        Record* new_records = new Record[new_capacity];
        std::string* new_keys = new std::string[new_capacity];
        for (size_t i = 0; i < size; ++i) {
            new_records[i] = records[i];
            new_keys[records[i].key] = keys[records[i].key];
        }
        delete[] records;
        delete[] keys;
        records = new_records;
        keys = new_keys;
        capacity = new_capacity;
    }
};

