#include <stdlib.h>
#include <time.h>

#define CHUNK_SIZE 16

typedef struct {
    // Define the structure fields here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t allocated_elements;
    size_t total_allocated_chunks;
} NFAPI_CRC_INDICATION_POOL_T;

NFAPI_CRC_INDICATION_POOL_T* create_pool(size_t initial_size) {
    NFAPI_CRC_INDICATION_POOL_T *pool = (NFAPI_CRC_INDICATION_POOL_T*)malloc(sizeof(NFAPI_CRC_INDICATION_POOL_T));
    if (!pool) return NULL;

    pool->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->array) {
        free(pool);
        return NULL;
    }

    pool->allocated_elements = initial_size;
    pool->total_allocated_chunks = 1;

    srand(time(NULL)); // Seed for random number generation

    return pool;
}

int allocate_element(NFAPI_CRC_INDICATION_POOL_T *pool, RX_UE_INFORMATION_TAG ue_tag, RNTI rnti) {
    if (pool->allocated_elements >= CHUNK_SIZE) {
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(pool->array, (pool->total_allocated_chunks + 1) * CHUNK_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) return -1; // Memory allocation failed

        pool->array = new_array;
        pool->total_allocated_chunks++;
        pool->allocated_elements = 0;
    }

    NFAPI_CRC_INDICATION_PDU_T *element = &pool->array[pool->allocated_elements++];
    element->RX_UE_INFORMATION_TAG = ue_tag;
    element->RNTI = rnti;
    element->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    return 0;
}

size_t get_total_allocated_elements(NFAPI_CRC_INDICATION_POOL_T *pool) {
    return pool->allocated_elements + (pool->total_allocated_chunks - 1) * CHUNK_SIZE;
}

void destroy_pool(NFAPI_CRC_INDICATION_POOL_T *pool) {
    free(pool->array);
    free(pool);
}
```

