#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef enum {
    PLANNED,
    ACTIVE,
    COMPLETED
} ProjectStatus;

typedef struct {
    int id;
    ProjectStatus status;
    time_t start_time;
} Project;

typedef struct Node {
    Project project;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
} ProjectList;

void initProjectList(ProjectList* list) {
    list->head = NULL;
    list->count = 0;
}

Node* createNode(Project project) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    newNode->project = project;
    newNode->next = NULL;
    return newNode;
}

void addProject(ProjectList* list, Project project) {
    Node* newNode = createNode(project);
    if (list->head == NULL) {
        list->head = newNode;
    } else {
        Node* temp = list->head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }
    list->count++;
}

void updateProjectStatus(ProjectList* list, time_t current_time) {
    Node* temp = list->head;
    while (temp != NULL) {
        double elapsed_days = difftime(current_time, temp->project.start_time) / (60 * 60 * 24);
        if (elapsed_days >= 30 && temp->project.status == PLANNED) {
            temp->project.status = ACTIVE;
        } else if (elapsed_days >= 90 && temp->project.status == ACTIVE) {
            temp->project.status = COMPLETED;
        }
        temp = temp->next;
    }
}

void displayProjects(ProjectList* list, time_t current_time) {
    updateProjectStatus(list, current_time);
    Node* temp = list->head;
    while (temp != NULL) {
        printf("ID: %d, Status: %s\n", temp->project.id, 
               temp->project.status == PLANNED ? "PLANNED" : 
               temp->project.status == ACTIVE ? "ACTIVE" : "COMPLETED");
        temp = temp->next;
    }
}

void freeProjectList(ProjectList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->count = 0;
}
