#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_NAME_LENGTH 100
#define INITIAL_CAPACITY 10
#define MAX_MEMORY_USAGE 1024 * 1024 // 1MB

typedef struct {
    char* name;
    int quantity;
    double price;
} Product;

typedef struct {
    Product** products;
    size_t capacity;
    size_t count;
    size_t memory_usage;
} ProductCollection;

Product* create_product(const char* name, int quantity, double price) {
    Product* product = (Product*)malloc(sizeof(Product));
    if (!product) return NULL;

    product->name = (char*)malloc((strlen(name) + 1) * sizeof(char));
    if (!product->name) {
        free(product);
        return NULL;
    }
    strcpy(product->name, name);
    product->quantity = quantity;
    product->price = price;

    return product;
}

void destroy_product(Product* product) {
    free(product->name);
    free(product);
}

ProductCollection* create_collection(size_t initial_capacity) {
    ProductCollection* collection = (ProductCollection*)malloc(sizeof(ProductCollection));
    if (!collection) return NULL;

    collection->products = (Product**)calloc(initial_capacity, sizeof(Product*));
    if (!collection->products) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->count = 0;
    collection->memory_usage = 0;

    return collection;
}

void destroy_collection(ProductCollection* collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        destroy_product(collection->products[i]);
    }
    free(collection->products);
    free(collection);
}

int add_product(ProductCollection* collection, const char* name, int quantity, double price) {
    if (collection->memory_usage + strlen(name) > MAX_MEMORY_USAGE) return -1;

    if (collection->count == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Product** new_products = (Product**)realloc(collection->products, new_capacity * sizeof(Product*));
        if (!new_products) return -1;

        collection->products = new_products;
        collection->capacity = new_capacity;
    }

    Product* product = create_product(name, quantity, price);
    if (!product) return -1;

    collection->products[collection->count++] = product;
    collection->memory_usage += strlen(name);

    return 0;
}

int main() {
    srand(time(NULL));

    ProductCollection* collection = create_collection(INITIAL_CAPACITY);
    if (!collection) {
        fprintf(stderr, "Failed to create product collection\n");
        return 1;
    }

    for (size_t i = 0; i < 20; ++i) {
        int quantity = rand() % 100 + 1;
        double price = (double)(rand() % 10000) / 100.0;

        if (add_product(collection, "Product", quantity, price) != 0) {
            fprintf(stderr, "Failed to add product\n");
            destroy_collection(collection);
            return 1;
        }
    }

    for (size_t i = 0; i < collection->count; ++i) {
        printf("Name: %s, Quantity: %d, Price: %.2f\n", collection->products[i]->name, collection->products[i]->quantity, collection->products[i]->price);
    }

    destroy_collection(collection);
    return 0;
}
