#include <stdlib.h>
#include <stdio.h>

#define CHUNK_SIZE 32

typedef enum {
    TEST_TYPE_A,
    TEST_TYPE_B,
    // Add more test types as needed
} PHY_TEST_COMMAND;

typedef struct LTE_PHY_TEST_MESSAGE {
    PHY_TEST_COMMAND command;
    int id;
    char data[1]; // Flexible array member
} LTE_PHY_TEST_MESSAGE;

typedef struct Chunk {
    struct Chunk *next;
    LTE_PHY_TEST_MESSAGE messages[CHUNK_SIZE / sizeof(LTE_PHY_TEST_MESSAGE)];
} Chunk;

Chunk *head = NULL;
int total_allocated = 0;

LTE_PHY_TEST_MESSAGE* allocate_message(PHY_TEST_COMMAND command, int id, size_t data_size) {
    if (data_size > sizeof(((LTE_PHY_TEST_MESSAGE *)NULL)->data)) {
        fprintf(stderr, "Error: Data size exceeds maximum allowed.\n");
        return NULL;
    }

    LTE_PHY_TEST_MESSAGE *msg = NULL;

    // Search for a chunk with an available slot
    Chunk *current_chunk = head;
    while (current_chunk != NULL) {
        for (int i = 0; i < CHUNK_SIZE / sizeof(LTE_PHY_TEST_MESSAGE); i++) {
            if (current_chunk->messages[i].command == TEST_TYPE_A && current_chunk->messages[i].id == id) {
                fprintf(stderr, "Error: Duplicate TEST_TYPE and TEST_ID combination.\n");
                return NULL;
            }
            if (current_chunk->messages[i].command == TEST_TYPE_A) {
                continue; // Skip already allocated messages
            }
            msg = &current_chunk->messages[i];
            msg->command = command;
            msg->id = id;
            break;
        }
        if (msg != NULL) {
            break;
        }
        current_chunk = current_chunk->next;
    }

    // If no available slot found, allocate a new chunk
    if (msg == NULL) {
        Chunk *new_chunk = malloc(sizeof(Chunk));
        if (new_chunk == NULL) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            return NULL;
        }
        new_chunk->next = head;
        head = new_chunk;

        msg = &new_chunk->messages[0];
        msg->command = command;
        msg->id = id;
    }

    // Allocate memory for the data buffer
    msg->data = malloc(data_size);
    if (msg->data == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    total_allocated++;
    return msg;
}

void free_message(LTE_PHY_TEST_MESSAGE *msg) {
    if (msg != NULL && msg->data != NULL) {
        free(msg->data);
        msg->data = NULL;
        msg->command = TEST_TYPE_A; // Reset to default value
        msg->id = 0;
        total_allocated--;
    }
}

void print_total_allocated() {
    printf("Total allocated messages: %d\n", total_allocated);
}
