typedef struct {
    int value;
} record;

typedef struct {
    void* baseAddress;
    size_t size;
} MemoryBlock;

MemoryBlock* memoryBlocks = NULL;
int numAllocatedBlocks = 0;

void resetSystemState() {
    for (int i = 0; i < numAllocatedBlocks; i++) {
        free(memoryBlocks[i].baseAddress);
    }
    free(memoryBlocks);
    memoryBlocks = NULL;
    numAllocatedBlocks = 0;
}

void* allocateMemory(int numOffsets, int numKeys, int* minValue, int* maxValue) {
    if (numOffsets <= 0 || numKeys <= 0 || *minValue > *maxValue) {
        return NULL;
    }

    size_t offsetsSize = numOffsets * sizeof(long);
    size_t keysSize = numKeys * sizeof(int);
    size_t recordsSize = numKeys * sizeof(record);

    MemoryBlock newBlock;
    newBlock.baseAddress = malloc(offsetsSize + keysSize + recordsSize);
    if (newBlock.baseAddress == NULL) {
        return NULL;
    }

    newBlock.size = offsetsSize + keysSize + recordsSize;

    if (memoryBlocks == NULL) {
        memoryBlocks = malloc(sizeof(MemoryBlock));
    } else {
        MemoryBlock* temp = realloc(memoryBlocks, (numAllocatedBlocks + 1) * sizeof(MemoryBlock));
        if (temp == NULL) {
            free(newBlock.baseAddress);
            return NULL;
        }
        memoryBlocks = temp;
    }

    memoryBlocks[numAllocatedBlocks++] = newBlock;

    long* offsets = (long*)((char*)newBlock.baseAddress + 0);
    int* keys = (int*)((char*)newBlock.baseAddress + offsetsSize);
    record* records = (record*)((char*)newBlock.baseAddress + offsetsSize + keysSize);

    srand(time(NULL));
    for (int i = 0; i < numKeys; i++) {
        records[i].value = rand() % (*maxValue - *minValue + 1) + *minValue;
    }

    return newBlock.baseAddress;
}
