} Record;

Record* create_records(size_t num_records, int key_range_min, int key_range_max,
                        int value_range_min, int value_range_max, size_t max_access_logs) {
    Record *records = (Record *)malloc(num_records * sizeof(Record));
    if (!records) return NULL;

    srand(time(NULL));

    for (size_t i = 0; i < num_records; ++i) {
        records[i].key = rand() % (key_range_max - key_range_min + 1) + key_range_min;
        records[i].value = rand() % (value_range_max - value_range_min + 1) + value_range_min;
        records[i].last_accessed = time(NULL);
        records[i].access_log = (time_t *)malloc(max_access_logs * sizeof(time_t));
        if (!records[i].access_log) {
            // Free previously allocated memory and return NULL
            for (size_t j = 0; j < i; ++j) free(records[j].access_log);
            free(records);
            return NULL;
        }
        records[i].log_size = 0;
    }

    return records;
}

void destroy_records(Record *records, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) free(records[i].access_log);
    free(records);
}

void increment_value(Record *record) {
    record->value++;
    time(&record->last_accessed);
    if (record->log_size < max_access_logs) {
        record->access_log[record->log_size++] = record->last_accessed;
    }
}

time_t get_latest_access_log(const Record *record) {
    return record->log_size > 0 ? record->access_log[record->log_size - 1] : (time_t)-1;
}

void update_last_accessed(Record *record, time_t current_time) {
    record->last_accessed = current_time;
}
