    PduContainer* container = (PduContainer*)malloc(sizeof(PduContainer));
    if (container == NULL) {
        return NULL;
    }
    container->pdus = (NFAPI_CRC_INDICATION_PDU_T**)malloc(CHUNK_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (container->pdus == NULL) {
        free(container);
        return NULL;
