    ProjectManager* manager = (ProjectManager*)malloc(sizeof(ProjectManager));
    if (manager == NULL) {
        return NULL;
    }
    manager->projects = (Project**)malloc(CHUNK_SIZE * sizeof(Project*));
    if (manager->projects == NULL) {
        free(manager);
        return NULL;
    }
    manager->pdu_container = create_pdu_container();
    if (manager->pdu_container == NULL) {
        free(manager->projects);
        free(manager);
        return NULL;
    }
    manager->project_count = 0;
    manager->project_capacity = CHUNK_SIZE;
    return manager;
