        for (size_t i = 0; i < manager->project_count; ++i) {
            free_project(manager->projects[i]);
        }
        free_pdu_container(&manager->pdu_container);
        free(manager->projects);
        free(manager);
    }
}

int add_project(ProjectManager* manager, int priority, const char* status, time_t deadline, time_t start_date) {
    if (manager->project_count >= manager->project_capacity) {
        Project** new_projects = (Project**)realloc(manager->projects, (manager->project_capacity + CHUNK_SIZE) * sizeof(Project*));
        if (new_projects == NULL) {
            return -1; // Allocation failed
        }
        manager->projects = new_projects;
        manager->project_capacity += CHUNK_SIZE;
    }

    Project* project = create_project(priority, status, deadline, start_date);
    if (project == NULL) {
        return -1; // Allocation failed
    }

    manager->projects[manager->project_count++] = project;
    return 0;
}

size_t get_total_allocated_elements(ProjectManager* manager) {
