['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define GROWTH_RATE 0.10
#define MAX_RECORDS 1000
#define CACHE_SIZE 100

typedef struct {
    int value;
    long* offset_ptr;
} Record;

typedef struct {
    Record** records;
    long* offsets;
    int* keys;
    size_t capacity;
    size_t size;
    size_t allocated_records;
    pthread_mutex_t lock;
    Record* cache[CACHE_SIZE];
} RecordCollection;

void init_record_collection(RecordCollection* collection) {
    collection->records = (Record**)aligned_alloc(64, sizeof(Record*) * INITIAL_CAPACITY);
    collection->offsets = (long*)aligned_alloc(64, sizeof(long) * INITIAL_CAPACITY);
    collection->keys = (int*)aligned_alloc(64, sizeof(int) * INITIAL_CAPACITY);
    collection->capacity = INITIAL_CAPACITY;
    collection->size = 0;
    collection->allocated_records = 0;
    pthread_mutex_init(&collection->lock, NULL);

    for (int i = 0; i < CACHE_SIZE; i++) {
        collection->cache[i] = NULL;
    }
}

void resize_record_collection(RecordCollection* collection) {
    size_t new_capacity = (size_t)(collection->capacity * (1 + GROWTH_RATE));
    Record** new_records = (Record**)aligned_alloc(64, sizeof(Record*) * new_capacity);
    long* new_offsets = (long*)aligned_alloc(64, sizeof(long) * new_capacity);
    int* new_keys = (int*)aligned_alloc(64, sizeof(int) * new_capacity);

    for (size_t i = 0; i < collection->size; i++) {
        new_records[i] = collection->records[i];
        new_offsets[i] = collection->offsets[i];
        new_keys[i] = collection->keys[i];
    }

    free(collection->records);
    free(collection->offsets);
    free(collection->keys);

    collection->records = new_records;
    collection->offsets = new_offsets;
    collection->keys = new_keys;
    collection->capacity = new_capacity;
}

void add_record(RecordCollection* collection, long offset, int key) {
    pthread_mutex_lock(&collection->lock);
    if (collection->size >= collection->capacity) {
        resize_record_collection(collection);
    }
    if (collection->allocated_records < MAX_RECORDS) {
        Record* new_record = (Record*)aligned_alloc(64, sizeof(Record));
        new_record->value = rand() % 100; // Random value between 0 and 99
        new_record->offset_ptr = &collection->offsets[collection->size];
        *new_record->offset_ptr = offset;
        collection->records[collection->size] = new_record;
        collection->keys[collection->size] = key;
        collection->allocated_records++;
    }
    pthread_mutex_unlock(&collection->lock);
}

void cleanup_record_collection(RecordCollection* collection) {
    for (size_t i = 0; i < collection->size; i++) {
        free(collection->records[i]);
    }
    free(collection->records);
    free(collection->offsets);
    free(collection->keys);
    pthread_mutex_destroy(&collection->lock);

    for (int i = 0; i < CACHE_SIZE; i++) {
        if (collection->cache[i] != NULL) {
            free(collection->cache[i]);
        }
    }
}

void log_performance(RecordCollection* collection, size_t reallocations, size_t total_memory_usage, double cache_effectiveness) {
    printf("Reallocations: %zu\n", reallocations);
