#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_RECORDS 1000
#define INITIAL_CAPACITY 50

typedef struct {
    int value;
    int *offset;
} record;

record **records = NULL;
int *keys = NULL;
int capacity = 0;
int count = 0;

void init_records() {
    capacity = INITIAL_CAPACITY;
    records = (record **)aligned_alloc(64, capacity * sizeof(record *));
    keys = (int *)aligned_alloc(64, capacity * sizeof(int));
    for (int i = 0; i < capacity; i++) {
        records[i] = NULL;
        keys[i] = 0;
    }
}

void add_record(int value) {
    if (count >= capacity) {
        int new_capacity = capacity + (capacity >> 1);
        record **new_records = (record **)aligned_alloc(64, new_capacity * sizeof(record *));
        memcpy(new_records, records, count * sizeof(record *));
        aligned_free(records);
        records = new_records;
        keys = (int *)realloc(keys, new_capacity * sizeof(int));
        for (int i = capacity; i < new_capacity; i++) {
            records[i] = NULL;
            keys[i] = 0;
        }
        capacity = new_capacity;
    }
    record *new_record = (record *)aligned_alloc(64, sizeof(record));
    new_record->value = value;
    new_record->offset = &keys[count];
    records[count++] = new_record;
}

void find_and_print_largest() {
    int largest = INT_MIN;
    for (int i = 0; i < count; i++) {
        if (records[i]->value > largest) {
            largest = records[i]->value;
        }
    }
    printf("Largest value: %d\n", largest);
}

void cleanup() {
    for (int i = 0; i < count; i++) {
        aligned_free(records[i]);
    }
    aligned_free(records);
    free(keys);
    records = NULL;
    keys = NULL;
    capacity = 0;
    count = 0;
}
