#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_SETTINGS_SIZE 1024

typedef struct UserProfile {
    int userID;
    time_t lastLogin;
    char *settings;
} UserProfile;

typedef struct UserList {
    UserProfile **profiles;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} UserList;

UserList* userListCreate() {
    UserList *list = (UserList*)malloc(sizeof(UserList));
    list->profiles = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void userListDestroy(UserList *list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->profiles[i]->settings);
        free(list->profiles[i]);
    }
    free(list->profiles);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int userProfileValidate(UserProfile *profile, size_t maxSettingsSize) {
    if (profile == NULL || profile->userID <= 0 || profile->lastLogin < 0 ||
        profile->settings == NULL || strlen(profile->settings) > maxSettingsSize) {
        return -1;
    }
    return 0;
}

int userListAdd(UserList *list, UserProfile *profile, size_t maxSettingsSize) {
    pthread_mutex_lock(&list->lock);
    if (userProfileValidate(profile, maxSettingsSize) != 0) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    if (list->count >= list->capacity) {
        UserProfile **newProfiles = realloc(list->profiles, (list->capacity + 1) * sizeof(UserProfile*));
        if (newProfiles == NULL) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->profiles = newProfiles;
        list->capacity++;
    }
    list->profiles[list->count++] = profile;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

UserProfile* userListGet(UserList *list, int userID) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->profiles[i]->userID == userID) {
            UserProfile *profile = list->profiles[i];
            pthread_mutex_unlock(&list->lock);
            return profile;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

int userProfileUpdate(UserList *list, int userID, const char *newSettings, size_t maxSettingsSize) {
    pthread_mutex_lock(&list->lock);
    UserProfile *profile = userListGet(list, userID);
    if (profile == NULL) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    if (strlen(newSettings) > maxSettingsSize) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    free(profile->settings);
    profile->settings = strdup(newSettings);
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void userProfileIterator(UserList *list, void (*callback)(UserProfile *)) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        callback(list->profiles[i]);
    }
    pthread_mutex_unlock(&list->lock);
}
