#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_SESSIONS 1024
#define MAX_CUSTOM_DATA 512
#define BUFFER_SIZE 4096

typedef struct {
    int connection_id;
    time_t start_timestamp;
    char *packet_data;
} SessionRecord;

typedef struct {
    char name[256];
    int age;
    char *address;
} CustomData;

typedef struct {
    SessionRecord **sessions;
    CustomData **custom_data;
    int session_count;
    int custom_data_count;
    pthread_mutex_t lock;
} NetworkManager;

NetworkManager* create_network_manager(int initial_capacity) {
    NetworkManager *manager = (NetworkManager*)malloc(sizeof(NetworkManager));
    manager->sessions = (SessionRecord**)calloc(initial_capacity, sizeof(SessionRecord*));
    manager->custom_data = (CustomData**)calloc(initial_capacity, sizeof(CustomData*));
    manager->session_count = 0;
    manager->custom_data_count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_network_manager(NetworkManager *manager) {
    for (int i = 0; i < manager->session_count; i++) {
        free(manager->sessions[i]->packet_data);
        free(manager->sessions[i]);
    }
    for (int i = 0; i < manager->custom_data_count; i++) {
        free(manager->custom_data[i]->address);
        free(manager->custom_data[i]);
    }
    free(manager->sessions);
    free(manager->custom_data);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void add_session(NetworkManager *manager, int connection_id, time_t start_timestamp, char *packet_data) {
    pthread_mutex_lock(&manager->lock);
    if (manager->session_count >= MAX_SESSIONS) {
        printf("Session list is full\n");
        pthread_mutex_unlock(&manager->lock);
        return;
    }
    SessionRecord *record = (SessionRecord*)malloc(sizeof(SessionRecord));
    record->connection_id = connection_id;
    record->start_timestamp = start_timestamp;
    record->packet_data = strdup(packet_data);
    manager->sessions[manager->session_count++] = record;
    pthread_mutex_unlock(&manager->lock);
}

void add_custom_data(NetworkManager *manager, char *name, int age, char *address) {
    pthread_mutex_lock(&manager->lock);
    if (manager->custom_data_count >= MAX_CUSTOM_DATA) {
        printf("Custom data list is full\n");
        pthread_mutex_unlock(&manager->lock);
        return;
    }
    CustomData *data = (CustomData*)malloc(sizeof(CustomData));
    strncpy(data->name, name, sizeof(data->name) - 1);
    data->age = age;
    data->address = strdup(address);
    manager->custom_data[manager->custom_data_count++] = data;
    pthread_mutex_unlock(&manager->lock);
}

void iterate_sessions(NetworkManager *manager) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->session_count; i++) {
        printf("Session %d: ID=%d, Timestamp=%ld\n", i, manager->sessions[i]->connection_id, manager->sessions[i]->start_timestamp);
    }
    pthread_mutex_unlock(&manager->lock);
}

void iterate_custom_data(NetworkManager *manager) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->custom_data_count; i++) {
        printf("Custom Data %d: Name=%s, Age=%d, Address=%s\n", i, manager->custom_data[i]->name, manager->custom_data[i]->age, manager->custom_data[i]->address);
    }
    pthread_mutex_unlock(&manager->lock);
}

void *cleanup_expired_sessions(void *arg) {
    NetworkManager *manager = (NetworkManager*)arg;
    while (1) {
        sleep(60); // Cleanup every minute
        pthread_mutex_lock(&manager->lock);
        for (int i = 0; i < manager->session_count; i++) {
            if (time(NULL) - manager->sessions[i]->start_timestamp > 3600) { // Expired after 1 hour
                free(manager->sessions[i]->packet_data);
                free(manager->sessions[i]);
                for (int j = i; j < manager->session_count - 1; j++) {
                    manager->sessions[j] = manager->sessions[j + 1];
                }
                manager->session_count--;
                i--; // Adjust index after removal
            }
        }
        pthread_mutex_unlock(&manager->lock);
    }
}

int main() {
    NetworkManager *manager = create_network_manager(10);
    add_session(manager, 12345, time(NULL), "Packet Data");
    add_custom_data(manager, "John Doe", 30, "192.168.1.1");
    iterate_sessions(manager);
    iterate_custom_data(manager);

    pthread_t cleanup_thread;
    pthread_create(&cleanup_thread, NULL, cleanup_expired_sessions, manager);

    // Simulate adding more data
    for (int i = 0; i < 5; i++) {
        add_session(manager, 12346 + i, time(NULL), "Packet Data");
        add_custom_data(manager, "User", i * 10, "192.168.1." + i);
    }

    iterate_sessions(manager);
    iterate_custom_data(manager);

    pthread_join(cleanup_thread, NULL);
    destroy_network_manager(manager);
    return 0;
}
