        free(semaphore);
        cleanUpTaskList(taskList, numStates);
        return NULL;
    }

    taskList->semaphore = semaphore;

    return taskList;
}

void cleanUpTaskList(TaskList *taskList, int numStates) {
    for (int i = 0; i < numStates; i++) {
        free(taskList->records[i]);
    }
    free(taskList->keys);
    free(taskList->offsets);
    StateNode *current = taskList->head;
    while (current) {
        StateNode *next = current->next;
        free(current);
        current = next;
    }
    sem_destroy(taskList->semaphore);
    free(taskList->semaphore);
