#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INITIAL_CAPACITY 10
#define RESIZE_FACTOR 1.15

typedef struct {
    char* name;
    int age;
    int status; // Assuming 0 for false and 1 for true
} Object;

typedef struct {
    Object** objects;
    size_t capacity;
    size_t size;
    size_t hash_table_size;
    Object** hash_table;
} DynamicList;

DynamicList* create_dynamic_list(size_t initial_capacity) {
    if (initial_capacity == 0) return NULL;

    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->objects = (Object**)calloc(initial_capacity, sizeof(Object*));
    if (!list->objects) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->size = 0;
    list->hash_table_size = initial_capacity * 2; // Assuming a load factor of 0.5
    list->hash_table = (Object**)calloc(list->hash_table_size, sizeof(Object*));
    if (!list->hash_table) {
        free(list->objects);
        free(list);
        return NULL;
    }

    return list;
}

void resize_dynamic_list(DynamicList* list) {
    size_t new_capacity = (size_t)(list->capacity * RESIZE_FACTOR);
    Object** new_objects = (Object**)realloc(list->objects, new_capacity * sizeof(Object*));
    if (!new_objects) return;

    for (size_t i = 0; i < list->size; ++i) {
        size_t hash_index = hash_function(new_objects[i]->name, list->hash_table_size);
        while (list->hash_table[hash_index] != NULL) {
            hash_index = (hash_index + 1) % list->hash_table_size;
        }
        list->hash_table[hash_index] = new_objects[i];
    }

    free(list->objects);
    list->objects = new_objects;
    list->capacity = new_capacity;
}

void update_ages(DynamicList* list, int (*age_update_func)(int)) {
    for (size_t i = 0; i < list->size; ++i) {
        list->objects[i]->age = age_update_func(list->objects[i]->age);
    }
}

void cleanup_dynamic_list(DynamicList* list) {
    for (size_t i = 0; i < list->size; ++i) {
        free(list->objects[i]->name);
        free(list->objects[i]);
    }

    free(list->objects);
    free(list->hash_table);
    free(list);
}

// Example usage
int main() {
    DynamicList* list = create_dynamic_list(INITIAL_CAPACITY);
    if (!list) return 1;

    // Add objects to the list and perform operations...

    cleanup_dynamic_list(list);
    return 0;
}
