}

void access_record(RecordCollection* collection, const char* key) {
    for (size_t i = 0; i < collection->size; ++i) {
        if (strcmp(collection->records[i]->key, key) == 0) {
            collection->records[i]->ref_count++;
            // Update associated key metadata in the external store
            break;
        }
    }
}

void resize_collection(RecordCollection* collection) {
    size_t new_capacity = collection->capacity * 2;
    Record** new_records = (Record**)realloc(collection->records, new_capacity * sizeof(Record*));

    if (!new_records) return;

    collection->records = new_records;
    collection->capacity = new_capacity;
}

void cleanup_collection(RecordCollection* collection) {
    for (size_t i = 0; i < collection->size; ++i) {
