#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t mutex;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) {
        perror("Failed to allocate memory for list");
        return NULL;
    }
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void free_list(List* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int add_element(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for new node");
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void print_list(List* list) {
    if (!list) {
        fprintf(stderr, "List is null\n");
        return;
    }
    Node* current = list->head;
    while (current) {
        printf("UE Info: %d, RNTI: %d, CRC Flag: %d\n", 
               current->data.ue_info, current->data.rnti, current->data.crc_indication);
        current = current->next;
    }
}

int main() {
    List* list = create_list();
    if (!list) {
        return 1;
    }

    NFAPI_CRC_INDICATION_PDU_T data = { /* Initialize with valid values */ };
    add_element(list, data);

    print_list(list);

    free_list(list);
    return 0;
}
```

