    da->size = 0;
    pthread_mutex_init(&da->mutex, NULL);
    return da;
}

void destroy_dynamic_array(DynamicArray *da) {
    if (da) {
        pthread_mutex_lock(&da->mutex);
        free(da->array);
        pthread_mutex_unlock(&da->mutex);
        pthread_mutex_destroy(&da->mutex);
        free(da);
    }
}

int add_mac_phy_stats(DynamicArray *da, MAC_PhyStats stats) {
    pthread_mutex_lock(&da->mutex);
    if (da->size >= da->capacity) {
        size_t new_capacity = da->capacity * 2;
        MAC_PhyStats *new_array = (MAC_PhyStats*)realloc(da->array, new_capacity * sizeof(MAC_PhyStats));
        if (!new_array) {
            perror("Failed to reallocate memory for MAC_PhyStats array");
            pthread_mutex_unlock(&da->mutex);
            return -1;
        }
        da->array = new_array;
        da->capacity = new_capacity;
    }
    da->array[da->size++] = stats;
    pthread_mutex_unlock(&da->mutex);
    return 0;
