typedef struct {
    int value;
    int* key;
    long* offset;
} record;

typedef struct {
    record** records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} dynamic_array;

void init_dynamic_array(dynamic_array* arr, size_t initial_capacity) {
    arr->records = (record**)malloc(initial_capacity * sizeof(record*));
    arr->capacity = initial_capacity;
    arr->size = 0;
    pthread_mutex_init(&arr->lock, NULL);
}

void resize_dynamic_array(dynamic_array* arr, size_t new_capacity) {
    record** new_records = (record**)realloc(arr->records, new_capacity * sizeof(record*));
    if (new_records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    arr->records = new_records;
    arr->capacity = new_capacity;
}

void add_record(dynamic_array* arr, int value, int key_value, long offset_value) {
    pthread_mutex_lock(&arr->lock);
    if (arr->size == arr->capacity) {
        resize_dynamic_array(arr, arr->capacity * 2);
    }
    record* new_record = (record*)malloc(sizeof(record));
    new_record->value = value;
    new_record->key = (int*)malloc(sizeof(int));
    *new_record->key = key_value;
    new_record->offset = (long*)malloc(sizeof(long));
    *new_record->offset = offset_value;
    arr->records[arr->size++] = new_record;
    pthread_mutex_unlock(&arr->lock);
}

void free_dynamic_array(dynamic_array* arr) {
    for (size_t i = 0; i < arr->size; ++i) {
        free(arr->records[i]->key);
        free(arr->records[i]->offset);
        free(arr->records[i]);
    }
    free(arr->records);
    pthread_mutex_destroy(&arr->lock);
}

int main() {
    dynamic_array my_array;
    init_dynamic_array(&my_array, 10);

    add_record(&my_array, 42, 1, 100L);
    add_record(&my_array, 99, 2, 200L);

    for (size_t i = 0; i < my_array.size; ++i) {
        printf("Value: %d, Key: %d, Offset: %ld\n", my_array.records[i]->value, *my_array.records[i]->key, *my_array.records[i]->offset);
    }

    free_dynamic_array(&my_array);

    return 0;
}
