#define BUFFER_SIZE 1024

typedef struct {
    double *values;
    size_t count;
} NumericArray;

NumericArray* read_and_process_data(int socket_fd) {
    NumericArray *array = (NumericArray*)malloc(sizeof(NumericArray));
    array->values = NULL;
    array->count = 0;

    char buffer[BUFFER_SIZE];
    while (1) {
        ssize_t bytes_read = recv(socket_fd, buffer, BUFFER_SIZE - 1, 0);
        if (bytes_read <= 0) break; // Connection closed or error

        buffer[bytes_read] = '\0';
        char *token = strtok(buffer, " ");
        while (token != NULL) {
            double value;
            if (sscanf(token, "%lf", &value) == 1) {
                array->count++;
                array->values = realloc(array->values, array->count * sizeof(double));
                array->values[array->count - 1] = value;
            }
            token = strtok(NULL, " ");
        }
    }

    return array;
}

double find_largest_value(NumericArray *array) {
    if (array->count == 0) return NAN; // No values in the array

    double max_value = array->values[0];
    for (size_t i = 1; i < array->count; i++) {
        if (array->values[i] > max_value) {
            max_value = array->values[i];
        }
    }

    return max_value;
}

void free_numeric_array(NumericArray *array) {
    free(array->values);
    free(array);
}
