    COMPLETED
} CompletionStatus;

typedef struct tm ProjectStartDate;

typedef struct {
    double budget;
    CompletionStatus completion_status;
    ProjectStartDate project_start_date;
} Project;

Project* create_project_list(int num_projects) {
    Project* projects = (Project*)malloc(num_projects * sizeof(Project));
    if (!projects) return NULL;

    srand(time(NULL));

    for (int i = 0; i < num_projects; i++) {
        projects[i].budget = ((double)rand() / RAND_MAX) * 99000 + 1000;
        projects[i].completion_status = NOT_STARTED;
        projects[i].project_start_date.tm_year = rand() % 14 + 2010; // 2010-2023
        projects[i].project_start_date.tm_mon = rand() % 12; // 0-11
        projects[i].project_start_date.tm_mday = rand() % 28 + 1; // 1-28
    }

    return projects;
}

void simulate_time_pass(Project* project, int days) {
    time_t start_time = mktime(&project->project_start_date);
    time_t end_time = start_time + (time_t)(days * 24 * 60 * 60);
    struct tm* new_date = localtime(&end_time);
    memcpy(&project->project_start_date, new_date, sizeof(struct tm));

    double budget_days = project->budget / 100;
    if (difftime(end_time, start_time) > budget_days * 24 * 60 * 60) {
        project->completion_status = IN_PROGRESS;
    }
}

void print_project(Project* project) {
    char date_str[80];
    strftime(date_str, sizeof(date_str), "%Y-%m-%d", &project->project_start_date);
    printf("Project Start Date: %s\n", date_str);
    printf("Budget: $%.2f\n", project->budget);
    switch (project->completion_status) {
