            printf("Completion Status: Not Started\n");
            break;
        case IN_PROGRESS:
            printf("Completion Status: In Progress\n");
            break;
        case COMPLETED:
            printf("Completion Status: Completed\n");
            break;
    }
}

void adjust_budget(Project* project, double new_budget) {
    project->budget = new_budget;
}
