typedef struct Record {
    char identifier;
    short status_flag;
    long timestamp;
} Record;

typedef struct List {
    void** elements;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} List;

List* create_list(size_t initial_capacity) {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;

    list->elements = (void**)calloc(initial_capacity, sizeof(void*));
    if (!list->elements) {
        free(list);
        return NULL;
    }

    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

int add_element(List* list, void* element) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        void** new_elements = (void**)realloc(list->elements, new_capacity * sizeof(void*));
        if (!new_elements) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Memory allocation failed
        }
        list->elements = new_elements;
        list->capacity = new_capacity;
    }
    list->elements[list->count++] = element;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void free_list(List* list) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; ++i) {
        free(list->elements[i]);
    }
    free(list->elements);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

void print_list(List* list, void (*print_element)(void*)) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; ++i) {
        print_element(list->elements[i]);
    }
    pthread_mutex_unlock(&list->mutex);
}

