#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_CONNECTIONS 1024
#define MIN_VALUE 0
#define MAX_VALUE 1000000

typedef struct {
    long *offsets;
    int size;
} Offset;

typedef struct {
    int *keys;
    int size;
} Key;

typedef struct {
    int value;
} Record;

typedef struct {
    int socket_descriptor;
    char client_ip[INET_ADDRSTRLEN];
    int connection_status;
    time_t last_health_check;
} NetworkConnection;

NetworkConnection connections[MAX_CONNECTIONS];
int connection_count = 0;
pthread_mutex_t connection_lock = PTHREAD_MUTEX_INITIALIZER;

Offset *create_offset(int size) {
    Offset *offset = (Offset *)malloc(sizeof(Offset));
    if (!offset) return NULL;
    offset->size = size;
    offset->offsets = (long *)aligned_alloc(16, sizeof(long) * size);
    if (!offset->offsets) {
        free(offset);
        return NULL;
    }
    for (int i = 0; i < size; i++) {
        offset->offsets[i] = i;
    }
    return offset;
}

Key *create_key(int size) {
    Key *key = (Key *)malloc(sizeof(Key));
    if (!key) return NULL;
    key->size = size;
    key->keys = (int *)malloc(sizeof(int) * size);
    if (!key->keys) {
        free(key);
        return NULL;
    }
    memset(key->keys, 0, sizeof(int) * size);
    return key;
}

Record *create_record(int min_value, int max_value, int count) {
    Record *record = (Record *)malloc(sizeof(Record) * count);
    if (!record) return NULL;
    for (int i = 0; i < count; i++) {
        record[i].value = rand() % (max_value - min_value + 1) + min_value;
    }
    return record;
}

void manageNetworkConnections(int socket_descriptor, char *client_ip) {
    pthread_mutex_lock(&connection_lock);
    if (connection_count >= MAX_CONNECTIONS) {
        pthread_mutex_unlock(&connection_lock);
        return; // Connection pool is full
    }
    NetworkConnection new_connection = {socket_descriptor, client_ip, 1, time(NULL)};
    connections[connection_count++] = new_connection;
    pthread_mutex_unlock(&connection_lock);
}

void *health_check_thread(void *arg) {
    while (1) {
        for (int i = 0; i < connection_count; i++) {
            if (time(NULL) - connections[i].last_health_check > 60) {
                // Re-establish failed connection
                manageNetworkConnections(connections[i].socket_descriptor, connections[i].client_ip);
            }
        }
        sleep(10); // Check every 10 seconds
    }
}

void *log_thread(void *arg) {
    while (1) {
        for (int i = 0; i < connection_count; i++) {
            if (connections[i].connection_status == 0) {
                printf("Connection %d with IP %s failed\n", connections[i].socket_descriptor, connections[i].client_ip);
            }
        }
        sleep(1); // Log every second
    }
}

void graceful_shutdown() {
    pthread_mutex_lock(&connection_lock);
    for (int i = 0; i < connection_count; i++) {
        close(connections[i].socket_descriptor);
    }
    connection_count = 0;
    pthread_mutex_unlock(&connection_lock);
}

int main() {
    srand(time(NULL));
    Offset *offset = create_offset(1024);
    Key *key = create_key(1024);
    Record *record = create_record(MIN_VALUE, MAX_VALUE, 1000000);

    pthread_t health_check_tid, log_tid;
    pthread_create(&health_check_tid, NULL, health_check_thread, NULL);
    pthread_create(&log_tid, NULL, log_thread, NULL);

    for (int i = 0; i < 1000; i++) {
        manageNetworkConnections(i, "127.0.0.1");
    }

    graceful_shutdown();

    free(offset->offsets);
    free(offset);
    free(key->keys);
    free(key);
    free(record);

    pthread_join(health_check_tid, NULL);
    pthread_join(log_tid, NULL);

    return 0;
}
