#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_MAC_PDU 1000000

typedef struct {
    // Define SIR structure fields
} SIR;

typedef struct {
    // Define TCI_STATE structure fields
} TCI_STATE;

typedef struct {
    // Define PREAMBLE_INFO structure fields
} PREAMBLE_INFO;

typedef struct MAC_PDU {
    SIR sir;
    TCI_STATE tci_state;
    PREAMBLE_INFO preamble_info;
    struct MAC_PDU *next;
} MAC_PDU;

typedef struct {
    MAC_PDU *head;
    pthread_mutex_t lock;
} MAC_PDU_COLLECTION;

void init_mac_pdu_collection(MAC_PDU_COLLECTION *collection) {
    collection->head = NULL;
    pthread_mutex_init(&collection->lock, NULL);
}

MAC_PDU* create_mac_pdu() {
    return (MAC_PDU*)malloc(sizeof(MAC_PDU));
}

void add_mac_pdu_to_collection(MAC_PDU_COLLECTION *collection, MAC_PDU *pdu) {
    pthread_mutex_lock(&collection->lock);
    pdu->next = collection->head;
    collection->head = pdu;
    pthread_mutex_unlock(&collection->lock);
}

MAC_PDU* filter_mac_pdu_by_sir(MAC_PDU_COLLECTION *collection, float threshold) {
    MAC_PDU *filtered_head = NULL;
    MAC_PDU *current = collection->head;

    while (current != NULL) {
        if (current->sir.quality >= threshold) {
            MAC_PDU *new_node = create_mac_pdu();
            *new_node = *current;
            new_node->next = filtered_head;
            filtered_head = new_node;
        }
        current = current->next;
    }

    return filtered_head;
}

void serialize_mac_pdu_collection(MAC_PDU_COLLECTION *collection, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        perror("Failed to open file for writing");
        return;
    }

    MAC_PDU *current = collection->head;
    while (current != NULL) {
        fwrite(&current->sir, sizeof(SIR), 1, file);
        fwrite(&current->tci_state, sizeof(TCI_STATE), 1, file);
        fwrite(&current->preamble_info, sizeof(PREAMBLE_INFO), 1, file);
        current = current->next;
    }

    fclose(file);
}

void deserialize_mac_pdu_collection(MAC_PDU_COLLECTION *collection, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Failed to open file for reading");
        return;
    }

    MAC_PDU *current = collection->head;
    while (current != NULL) {
        MAC_PDU *next = current->next;
        free(current);
        current = next;
    }
    collection->head = NULL;

    while (!feof(file)) {
        MAC_PDU *new_node = create_mac_pdu();
        if (fread(&new_node->sir, sizeof(SIR), 1, file) != 1 ||
            fread(&new_node->tci_state, sizeof(TCI_STATE), 1, file) != 1 ||
            fread(&new_node->preamble_info, sizeof(PREAMBLE_INFO), 1, file) != 1) {
            free(new_node);
            break;
        }
        new_node->next = collection->head;
        collection->head = new_node;
    }

    fclose(file);
}

void destroy_mac_pdu_collection(MAC_PDU_COLLECTION *collection) {
    MAC_PDU *current = collection->head;
    while (current != NULL) {
        MAC_PDU *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&collection->lock);
}
