    int thread_id = *(int*)arg;
    int N = MAX_RECORDS / 10; // Divide records among threads for parallel processing

    NFAPI_CRC_INDICATION_PDU_T* records = create_records(N, MAX_MEMORY_LIMIT);
    if (!records) {
        fprintf(stderr, "Thread %d: Memory allocation failed\n", thread_id);
        return NULL;
    }

    int persist_result = persist_records(records, N);
    if (persist_result != 0) {
        fprintf(stderr, "Thread %d: Failed to persist records\n", thread_id);
        free_records(records);
        return NULL;
    }

    int retrieved_N;
    NFAPI_CRC_INDICATION_PDU_T* retrieved_records;
    int retrieve_result = retrieve_records(thread_id * 1000, thread_id * 1000 + 1, &retrieved_records, &retrieved_N);
    if (retrieve_result != 0) {
        fprintf(stderr, "Thread %d: Failed to retrieve records\n", thread_id);
        free_records(records);
        return NULL;
    }

    // Process retrieved records

    free_records(records);
    free(retrieved_records);

    return NULL;
}

int main() {
    pthread_t threads[10];
    int thread_ids[10];

    for (int i = 0; i < 10; i++) {
        thread_ids[i] = i;
        if (pthread_create(&threads[i], NULL, worker_thread, &thread_ids[i]) != 0) {
            fprintf(stderr, "Failed to create thread %d\n", i);
            return 1;
        }
    }

    for (int i = 0; i < 10; i++) {
        if (pthread_join(threads[i], NULL) != 0) {
            fprintf(stderr, "Failed to join thread %d\n", i);
            return 1;
        }
    }

    return 0;
}
