#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    char token[128];
    int user_profile_id;
    time_t expiration_timestamp;
    time_t last_activity_timestamp;
    int page_views;
    double session_duration;
} Session;

typedef struct {
    Session *sessions;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} SessionPool;

SessionPool *create_session_pool(size_t initial_capacity) {
    SessionPool *pool = (SessionPool *)malloc(sizeof(SessionPool));
    pool->sessions = (Session *)calloc(initial_capacity, sizeof(Session));
    pool->capacity = initial_capacity;
    pool->size = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_session_pool(SessionPool *pool) {
    free(pool->sessions);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

int add_session(SessionPool *pool, const Session *session) {
    pthread_mutex_lock(&pool->lock);
    if (pool->size >= pool->capacity) {
        // Resize the session pool
        pool->capacity *= 2;
        pool->sessions = (Session *)realloc(pool->sessions, pool->capacity * sizeof(Session));
    }
    pool->sessions[pool->size++] = *session;
    pthread_mutex_unlock(&pool->lock);
    return 0;
}

void remove_session(SessionPool *pool, int user_profile_id) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->size; ++i) {
        if (pool->sessions[i].user_profile_id == user_profile_id) {
            // Shift elements to fill the gap
            memmove(&pool->sessions[i], &pool->sessions[i + 1], (pool->size - i - 1) * sizeof(Session));
            pool->size--;
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

void prune_dormant_sessions(SessionPool *pool, time_t grace_period) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->size;) {
        if (time(NULL) - pool->sessions[i].last_activity_timestamp > grace_period) {
            // Shift elements to fill the gap
            memmove(&pool->sessions[i], &pool->sessions[i + 1], (pool->size - i - 1) * sizeof(Session));
            pool->size--;
        } else {
            ++i;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

void log_session_event(const Session *session, const char *event_type) {
    // Implement logging logic here
    printf("Session %s: Token=%s, User ID=%d, Event=%s\n", session->token, event_type, session->user_profile_id, event_type);
}

int main() {
    SessionPool *pool = create_session_pool(10);

    Session new_session;
    strcpy(new_session.token, "abc123");
    new_session.user_profile_id = 12345;
    new_session.expiration_timestamp = time(NULL) + 3600; // 1 hour
    new_session.last_activity_timestamp = time(NULL);
    new_session.page_views = 0;
    new_session.session_duration = 0.0;

    add_session(pool, &new_session);

    remove_session(pool, 12345);

    prune_dormant_sessions(pool, 60); // Prune sessions inactive for more than 1 minute

    log_session_event(&new_session, "LOGIN");

    destroy_session_pool(pool);

    return 0;
}
