#include <iostream>
#include <forward_list>
#include <chrono>

struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    std::string CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
};

bool processForwardList(std::forward_list<NFAPI_CRC_INDICATION_PDU_T>& list, int targetRNTI, const std::string& additionalString, int maxProcessingTime) {
    auto start = std::chrono::high_resolution_clock::now();

    for (auto& pdu : list) {
        if (pdu.RNTI == targetRNTI) {
            pdu.CRC_INDICATION_REL8_TAG += additionalString;
            return true;
        }
        if (std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::high_resolution_clock::now() - start).count() > maxProcessingTime) {
            break;
        }
    }

    list.push_back({0, targetRNTI, additionalString, false});
    return false;
}

int main() {
    std::forward_list<NFAPI_CRC_INDICATION_PDU_T> pduList = {
        {1, 101, "Initial", true},
        {2, 102, "Data", false}
    };

    int targetRNTI = 101;
    std::string additionalString = "_Processed";
    int maxProcessingTime = 50; // milliseconds

    bool result = processForwardList(pduList, targetRNTI, additionalString, maxProcessingTime);

    if (result) {
        std::cout << "Insertion successful." << std::endl;
    } else {
        std::cout << "No matching RNTI found within the allowed processing time. Appended to the end of the list." << std::endl;
    }

    return 0;
}
