    for (int i = 0; i < n; i++) {
        offsets[i] = rand() % max_offset;
        keys[i] = i;

        records[i].offset = offsets[i];
        records[i].key = keys[i];
        records[i].timestamp = min_timestamp + (rand() / (double)RAND_MAX) * (max_timestamp - min_timestamp);

