        fprintf(stderr, "Error: Sizes must be non-negative integers.\n");
        return;
    }

    TCP_CONNECTION_STATS_T** records = (TCP_CONNECTION_STATS_T**)malloc(in_size * sizeof(TCP_CONNECTION_STATS_T*));
