    for (int i = 0; i < in_size; ++i) {
        records[i] = (TCP_CONNECTION_STATS_T*)malloc(sizeof(TCP_CONNECTION_STATS_T));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed for record %d.\n", i);
            // Free previously allocated memory
            for (int j = 0; j < i; ++j) {
                free(records[j]->name);
                free(records[j]);
            }
            free(records);
            return;
        }

        records[i]->in_bytes = i * in_size;
        records[i]->out_bytes = i * out_size;
        records[i]->connection_id = conn_id_size > 0 ? rand() % conn_id_size : 0;

        char name[50];
        snprintf(name, sizeof(name), "Record_%d_%d", i, records[i]->connection_id);
        records[i]->name = strdup(name);

        double min_latency = 1.0;
        double max_latency = 10.0;
        if (min_latency >= max_latency) {
            fprintf(stderr, "Error: Invalid latency range.\n");
            // Free previously allocated memory
            for (int j = 0; j <= i; ++j) {
                free(records[j]->name);
                free(records[j]);
            }
            free(records);
            return;
        }

        records[i]->latency = min_latency + (rand() / (RAND_MAX / (max_latency - min_latency)));
    }

    // Simulate external data source integration
    for (int i = 0; i < in_size; ++i) {
        // Update latency based on external data source
        records[i]->latency += 0.5 * rand() / RAND_MAX;
    }

    // Free allocated memory in reverse order
    for (int i = in_size - 1; i >= 0; --i) {
        free(records[i]->name);
        free(records[i]);
    }
    free(records);
}

int main() {
    manageTCPConnections(5, 3, 7);
    return 0;
}
