#include <stdlib.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* populateAndSerializeNFACRCIndications(int N, const char* filename) {
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)aligned_alloc(64, N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) return NULL;

    srand(time(NULL));
    for (int i = 0; i < N; ++i) {
        list[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        list[i].RNTI = rand() % 256;
        list[i].CRC_INDICATION_REL8_TAG = rand() % 2 ? 1 : 0;
    }

    FILE* file = fopen(filename, "wb");
    if (!file) {
        free(list);
        return NULL;
    }

    size_t written = fwrite(list, sizeof(NFAPI_CRC_INDICATION_PDU_T), N, file);
    fclose(file);

    if (written != N) {
        free(list);
        return NULL;
    }

    return list;
}

NFAPI_CRC_INDICATION_PDU_T* deserializeNFACRCIndications(const char* filename, int* count) {
    FILE* file = fopen(filename, "rb");
    if (!file) return NULL;

    fseek(file, 0, SEEK_END);
    long size = ftell(file);
    fseek(file, 0, SEEK_SET);

    *count = size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)aligned_alloc(64, *count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        fclose(file);
        return NULL;
    }

    size_t read = fread(list, sizeof(NFAPI_CRC_INDICATION_PDU_T), *count, file);
    fclose(file);

    if (read != *count) {
        free(list);
        return NULL;
    }

    return list;
}
