using System;
using System.Collections.Concurrent;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;

[ApiController]
[Route("api/[controller]")]
public class HtmlContentController : ControllerBase
{
    private readonly IAuthenticationService _authenticationService;
    private readonly ILogger<HtmlContentController> _logger;
    private readonly ConcurrentDictionary<string, DateTime> _requestCache = new ConcurrentDictionary<string, DateTime>();
    private const int MaxConcurrentRequests = 100;
    private const int CacheTimeoutMinutes = 5;

    public HtmlContentController(IAuthenticationService authenticationService, ILogger<HtmlContentController> logger)
    {
        _authenticationService = authenticationService;
        _logger = logger;
    }

    [HttpPost("update")]
    public async Task<IActionResult> UpdateContent([FromBody] ContentUpdateRequest request)
    {
        if (!await ValidateToken(request.Token))
            return Unauthorized();

        if (IsDuplicateRequest(request.ClientId, request.RequestId))
            return BadRequest("Duplicate request detected.");

        try
        {
            // Simulate content update logic
            await Task.Delay(100); // Simulate processing time

            _requestCache.TryAdd($"{request.ClientId}_{request.RequestId}", DateTime.UtcNow);
            _logger.LogInformation($"Content updated for section {request.SectionId}, element {request.ElementId}");

            return Ok("Content updated successfully.");
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error updating content");
            return StatusCode(500, "Internal server error");
        }
    }

    private async Task<bool> ValidateToken(string token)
    {
        // Simulate token validation logic
        return await _authenticationService.ValidateTokenAsync(token);
    }

    private bool IsDuplicateRequest(string clientId, string requestId)
    {
        if (!_requestCache.TryGetValue($"{clientId}_{requestId}", out var lastRequestTime))
            return false;

        return DateTime.UtcNow - lastRequestTime < TimeSpan.FromMinutes(CacheTimeoutMinutes);
    }
}

public class ContentUpdateRequest
{
    public string Token { get; set; }
    public string ClientId { get; set; }
    public string RequestId { get; set; }
    public string SectionId { get; set; }
    public string ElementId { get; set; }
    public string HtmlContent { get; set; }
}

public interface IAuthenticationService
{
    Task<bool> ValidateTokenAsync(string token);
}
