#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_MESSAGE_LENGTH 1024

typedef enum {
    LOG_INFO,
    LOG_WARNING,
    LOG_ERROR
} Severity;

typedef struct {
    time_t timestamp;
    Severity severity;
    char *message;
} LogRecord;

typedef struct {
    LogRecord **records;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} LogSystem;

LogSystem* log_system_create(size_t max_records) {
    if (max_records == 0 || max_records < 0) {
        return NULL;
    }
    LogSystem *system = malloc(sizeof(LogSystem));
    system->records = malloc(max_records * sizeof(LogRecord *));
    for (size_t i = 0; i < max_records; ++i) {
        system->records[i] = NULL;
    }
    system->capacity = max_records;
    system->count = 0;
    pthread_mutex_init(&system->mutex, NULL);
    return system;
}

void log_system_destroy(LogSystem *system) {
    for (size_t i = 0; i < system->count; ++i) {
        free(system->records[i]->message);
        free(system->records[i]);
    }
    free(system->records);
    pthread_mutex_destroy(&system->mutex);
    free(system);
}

int log_system_add(LogSystem *system, time_t timestamp, Severity severity, const char *message) {
    if (system == NULL || message == NULL) {
        return -1;
    }
    pthread_mutex_lock(&system->mutex);
    if (system->count >= system->capacity) {
        pthread_mutex_unlock(&system->mutex);
        return -2; // Log buffer full
    }
    LogRecord *record = malloc(sizeof(LogRecord));
    record->timestamp = timestamp;
    record->severity = severity;
    record->message = strdup(message);
    if (record->message == NULL) {
        free(record);
        pthread_mutex_unlock(&system->mutex);
        return -3; // Memory allocation failed
    }
    system->records[system->count++] = record;
    pthread_mutex_unlock(&system->mutex);
    return 0;
}

void log_system_log(LogSystem *system, const char *message) {
    time_t timestamp = time(NULL);
    Severity severity = LOG_INFO;
    if (log_system_add(system, timestamp, severity, message) != 0) {
        printf("Failed to add log entry\n");
    }
}
