#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <pthread.h>

// Define weather_record structure
typedef struct {
    float temperature;
    char* location;
    time_t timestamp;
    uint16_t condition_id;
} weather_record;

// Define custom thread-safe queue node
typedef struct queue_node {
    weather_record data;
    struct queue_node* next;
} queue_node;

// Define custom thread-safe queue
typedef struct {
    queue_node* front;
    queue_node* rear;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} thread_safe_queue;

// Function to initialize a new thread-safe queue
void init_thread_safe_queue(thread_safe_queue* q) {
    q->front = q->rear = NULL;
    pthread_mutex_init(&q->mutex, NULL);
    pthread_cond_init(&q->cond, NULL);
}

// Function to enqueue an item into the thread-safe queue
void enqueue(thread_safe_queue* q, weather_record data) {
    pthread_mutex_lock(&q->mutex);
    queue_node* new_node = (queue_node*)malloc(sizeof(queue_node));
    new_node->data = data;
    new_node->next = NULL;
    if (q->rear == NULL) {
        q->front = q->rear = new_node;
    } else {
        q->rear->next = new_node;
        q->rear = new_node;
    }
    pthread_cond_signal(&q->cond);
    pthread_mutex_unlock(&q->mutex);
}

// Function to dequeue an item from the thread-safe queue
weather_record dequeue(thread_safe_queue* q) {
    pthread_mutex_lock(&q->mutex);
    while (q->front == NULL) {
        pthread_cond_wait(&q->cond, &q->mutex);
    }
    weather_record data = q->front->data;
    queue_node* temp = q->front;
    q->front = q->front->next;
    if (q->front == NULL) {
        q->rear = NULL;
    }
    free(temp);
    pthread_mutex_unlock(&q->mutex);
    return data;
}

// Function to generate random weather_record entries
weather_record generate_random_weather_record(float min_temp, float max_temp, int location_len, time_t start_time, time_t end_time) {
    weather_record record;
    record.temperature = (float)(rand() / (float)RAND_MAX * (max_temp - min_temp) + min_temp);
    record.location = (char*)malloc((location_len + 1) * sizeof(char));
    snprintf(record.location, location_len + 1, "%d", rand());
    record.timestamp = (time_t)(rand() % (end_time - start_time + 1)) + start_time;
    record.condition_id = (uint16_t)(rand() % UINT16_MAX);
    return record;
}

// Function to free memory allocated for weather_record entries
void free_weather_record(weather_record* record) {
    if (record->location != NULL) {
        free(record->location);
    }
}

// Function to perform periodic garbage collection
void* garbage_collection_thread(void* arg) {
    thread_safe_queue* q = (thread_safe_queue*)arg;
    while (1) {
        // Perform garbage collection logic here
        sleep(60); // Example: run every minute
    }
    return NULL;
}

// Main function to demonstrate usage
int main() {
    srand(time(NULL));
    int num_records = 10;
    float min_temp = -20.0, max_temp = 40.0;
    int location_len = 10;
    time_t start_time = time(NULL) - 86400; // One day ago
    time_t end_time = time(NULL);

    thread_safe_queue q;
    init_thread_safe_queue(&q);

    pthread_t gc_thread;
    pthread_create(&gc_thread, NULL, garbage_collection_thread, &q);

    for (int i = 0; i < num_records; i++) {
        weather_record record = generate_random_weather_record(min_temp, max_temp, location_len, start_time, end_time);
        enqueue(&q, record);
    }

    for (int i = 0; i < num_records; i++) {
        weather_record record = dequeue(&q);
        free_weather_record(&record);
    }

    pthread_join(gc_thread, NULL);

    return 0;
}
```

