#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MIN_SIZE 10
#define MAX_SIZE 1000

typedef struct {
    int value;
    char* str;
} record;

void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

record* create_records(int size, int min_val, int max_val, char** error_buffer, int print_flag) {
    if (size < MIN_SIZE || size > MAX_SIZE) {
        snprintf(*error_buffer, 256, "Invalid array size: %d\n", size);
        return NULL;
    }

    long* offsets = allocate_memory(size * sizeof(long));
    int* keys = allocate_memory(size * sizeof(int));
    record* records = allocate_memory(size * sizeof(record));

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < size; i++) {
        offsets[i] = rand();
        keys[i] = rand() % (max_val - min_val + 1) + min_val;
        records[i].value = keys[i];
        records[i].str = allocate_memory(256 * sizeof(char));
        snprintf(records[i].str, 256, "Record %d", i);
    }

    if (print_flag) {
        for (int i = 0; i < size; i++) {
            printf("Record %d: Value = %d, String = %s\n", i, records[i].value, records[i].str);
        }
    }

    return records;
}

void free_records(record* records, int size) {
    for (int i = 0; i < size; i++) {
        free(records[i].str);
    }
    free(records);
}

int main() {
    char error_buffer[256];
    record* my_records = create_records(100, 1, 1000, &error_buffer, 1);

    if (my_records != NULL) {
        free_records(my_records, 100);
    } else {
        printf("Error: %s\n", error_buffer);
    }

    return 0;
}
