#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define RESIZE_THRESHOLD 0.75

typedef struct {
    long* offsets;
    int* keys;
    float* data;
    size_t capacity;
    size_t size;
} DataStruct;

void init_data_struct(DataStruct* ds, size_t initial_capacity) {
    ds->offsets = (long*)malloc(initial_capacity * sizeof(long));
    ds->keys = (int*)malloc(initial_capacity * sizeof(int));
    ds->data = (float*)malloc(initial_capacity * sizeof(float));
    ds->capacity = initial_capacity;
    ds->size = 0;
}

void resize_data_struct(DataStruct* ds, size_t new_capacity) {
    long* new_offsets = (long*)realloc(ds->offsets, new_capacity * sizeof(long));
    int* new_keys = (int*)realloc(ds->keys, new_capacity * sizeof(int));
    float* new_data = (float*)realloc(ds->data, new_capacity * sizeof(float));

    if (!new_offsets || !new_keys || !new_data) {
        fprintf(stderr, "Memory allocation failed during resize.\n");
        exit(EXIT_FAILURE);
    }

    ds->offsets = new_offsets;
    ds->keys = new_keys;
    ds->data = new_data;
    ds->capacity = new_capacity;
}

void add_record(DataStruct* ds, long offset, int key) {
    if (ds->size >= ds->capacity * RESIZE_THRESHOLD) {
        size_t new_capacity = ds->capacity * 2;
        resize_data_struct(ds, new_capacity);
    }

    ds->offsets[ds->size] = offset;
    ds->keys[ds->size] = key;
    ds->data[ds->size] = (float)(rand() / (float)RAND_MAX); // Random float between 0 and 1
    ds->size++;
}

void free_data_struct(DataStruct* ds) {
    free(ds->offsets);
    free(ds->keys);
    free(ds->data);
}
