    strcpy(col->name, name);
    col->type = type;
    col->defaultValue = defaultValue;
    return col;
}

// Function to add a table to the database
void addTable(DBMS* dbms, const char* tableName, void (*dbOperation)(void)) {
    Table* newTable = (Table*)malloc(sizeof(Table));
    strcpy(newTable->tableName, tableName);
    newTable->columns = NULL;
    newTable->columnCount = 0;
    newTable->dbOperation = dbOperation;
    dbms->tables = realloc(dbms->tables, (dbms->tableCount + 1) * sizeof(Table*));
    dbms->tables[dbms->tableCount++] = newTable;
}

// Function to add a column to a table
void addColumn(Table* table, Column* col) {
