    table1->columns[0] = col1;
    table1->columns[1] = col2;
    table1->columnCount = 2;
    table1->dbOperation = exampleDBOperation;

    addTable(&dbms, "users", exampleDBOperation);

    // Add more tables and columns as needed

    // Clean up allocated memory
    for (int i = 0; i < dbms.tableCount; i++) {
        free(dbms.tables[i]->columns);
        free(dbms.tables[i]);
    }
    free(dbms.tables);

    return 0;
}
