#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_CONNECTIONS 1024

typedef struct {
    int socket_descriptor;
    char client_ip[INET_ADDRSTRLEN];
    int connection_status;
    time_t last_seen;
} Connection;

Connection *connection_pool[MAX_CONNECTIONS];
int pool_size = 0;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

void add_connection(int socket_descriptor, const char *client_ip) {
    pthread_mutex_lock(&pool_lock);
    if (pool_size < MAX_CONNECTIONS) {
        connection_pool[pool_size] = malloc(sizeof(Connection));
        connection_pool[pool_size]->socket_descriptor = socket_descriptor;
        strcpy(connection_pool[pool_size]->client_ip, client_ip);
        connection_pool[pool_size]->connection_status = 1;
        time(&connection_pool[pool_size]->last_seen);
        pool_size++;
    }
    pthread_mutex_unlock(&pool_lock);
}

void remove_connection(int socket_descriptor) {
    pthread_mutex_lock(&pool_lock);
    for (int i = 0; i < pool_size; i++) {
        if (connection_pool[i]->socket_descriptor == socket_descriptor) {
            free(connection_pool[i]);
            for (int j = i; j < pool_size - 1; j++) {
                connection_pool[j] = connection_pool[j + 1];
            }
            pool_size--;
            break;
        }
    }
    pthread_mutex_unlock(&pool_lock);
}

void health_check() {
    pthread_mutex_lock(&pool_lock);
    for (int i = 0; i < pool_size; i++) {
        time_t current_time;
        time(&current_time);
        if (difftime(current_time, connection_pool[i]->last_seen) > 60) {
            remove_connection(connection_pool[i]->socket_descriptor);
        }
    }
    pthread_mutex_unlock(&pool_lock);
}

void *connection_manager(void *arg) {
    while (1) {
        health_check();
        // Add more logic for handling connections
        sleep(1);
    }
    return NULL;
}

int main() {
    pthread_t manager_thread;
    pthread_create(&manager_thread, NULL, connection_manager, NULL);

    // Simulate adding and removing connections
    add_connection(12345, "192.168.1.1");
    sleep(2);
    remove_connection(12345);

    pthread_join(manager_thread, NULL);
