#include <string.h>
#include <time.h>
#include <uuid/uuid.h>

#define MAX_PROJECTS 100

typedef struct {
    int priority;
    char *status;
    time_t deadline;
} Project;

Project *project_list[MAX_PROJECTS];
int project_count = 0;

void initialize_project_list() {
    for (int i = 0; i < MAX_PROJECTS; i++) {
        project_list[i] = malloc(sizeof(Project));
        project_list[i]->priority = i + 1;
        project_list[i]->status = strdup("Pending");
        time_t now = time(NULL);
        project_list[i]->deadline = now + (i * 86400); // Adjust deadline by days
    }
    project_count = MAX_PROJECTS;
}

void update_project_statuses() {
    for (int i = 0; i < project_count; i++) {
        time_t now = time(NULL);
        if (difftime(now, project_list[i]->deadline) <= 604800) { // Within 7 days
            project_list[i]->status = strdup("In Progress");
        }
    }
}

void adjust_project_deadlines() {
    for (int i = 0; i < project_count; i++) {
        time_t now = time(NULL);
        int random_days = rand() % 31;
        project_list[i]->deadline = now + (random_days * 86400); // Add random days
    }
}

void sort_project_list_by_deadline() {
    for (int i = 0; i < project_count - 1; i++) {
        for (int j = 0; j < project_count - i - 1; j++) {
            if (project_list[j]->deadline > project_list[j + 1]->deadline) {
                Project *temp = project_list[j];
                project_list[j] = project_list[j + 1];
                project_list[j + 1] = temp;
            }
        }
    }
}

void remove_project_by_uuid(uuid_t uuid) {
    for (int i = 0; i < project_count; i++) {
        if (memcmp(project_list[i]->uuid, uuid, sizeof(uuid_t)) == 0) {
            free(project_list[i]);
            for (int j = i; j < project_count - 1; j++) {
                project_list[j] = project_list[j + 1];
            }
            project_count--;
            break;
        }
    }
}

void log_operation(const char *operation, int result) {
    printf("%s: %d\n", operation, result);
}

int main() {
    srand(time(NULL));
    initialize_project_list();
    update_project_statuses();
    adjust_project_deadlines();
    sort_project_list_by_deadline();

    uuid_t uuid;
    uuid_generate(uuid);
    remove_project_by_uuid(uuid);

    log_operation("Initialization", 0);
    log_operation("Status Update", 0);
    log_operation("Deadline Adjustment", 0);
    log_operation("Sorting", 0);
    log_operation("Removal", 0);

    for (int i = 0; i < project_count; i++) {
        free(project_list[i]->status);
        free(project_list[i]);
    }

    return 0;
}
