#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_CAPACITY 10000

typedef struct {
    long key;
    long value;
    int timestamp;
} Record;

typedef struct {
    Record* records;
    size_t count;
    size_t capacity;
} RecordCollection;

RecordCollection* create_record_collection() {
    RecordCollection* collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!collection) {
        fprintf(stderr, "Memory allocation failed for RecordCollection\n");
        return NULL;
    }
    collection->records = (Record*)calloc(MAX_CAPACITY, sizeof(Record));
    if (!collection->records) {
        free(collection);
        fprintf(stderr, "Memory allocation failed for records array\n");
        return NULL;
    }
    collection->count = 0;
    collection->capacity = MAX_CAPACITY;
    return collection;
}

void destroy_record_collection(RecordCollection* collection) {
    if (collection->records) {
        free(collection->records);
    }
    free(collection);
}

int add_record(RecordCollection* collection, long key, long value, int timestamp) {
    if (collection->count >= collection->capacity) {
        fprintf(stderr, "RecordCollection is full\n");
        return -1;
    }
    collection->records[collection->count].key = key;
    collection->records[collection->count].value = value;
    collection->records[collection->count].timestamp = timestamp;
    collection->count++;
    return 0;
}

void prune_old_records(RecordCollection* collection, int threshold) {
    time_t current_time = time(NULL);
    size_t i = 0;
    while (i < collection->count) {
        if ((current_time - collection->records[i].timestamp) > threshold) {
            for (size_t j = i; j < collection->count - 1; j++) {
                collection->records[j] = collection->records[j + 1];
            }
            collection->count--;
        } else {
            i++;
        }
    }
}

int main() {
    RecordCollection* collection = create_record_collection();
    if (!collection) {
        return 1;
    }

    // Example usage
    add_record(collection, 1, 100, time(NULL));
    add_record(collection, 2, 200, time(NULL));

    prune_old_records(collection, 60); // Prune records older than 60 seconds

    destroy_record_collection(collection);
    return 0;
}
