record_array* allocate_and_populate_records(size_t max_records) {
    if (max_records == 0 || max_records > MAX_PDUS) {
        return NULL; // Handle edge cases
    }

    record_array* array = malloc(sizeof(record_array));
    if (!array) {
        return NULL; // Handle memory allocation failure
    }

    array->offsets = malloc(max_records * sizeof(long));
    array->keys = malloc(max_records * sizeof(int));
    array->records = malloc(max_records * sizeof(record));

    if (!array->offsets || !array->keys || !array->records) {
        free(array->offsets);
        free(array->keys);
        free(array->records);
        free(array);
        return NULL; // Handle memory allocation failure
    }

    array->count = 0;
    array->capacity = max_records;

    srand(time(NULL)); // Seed for random number generation

    for (size_t i = 0; i < max_records; ++i) {
        long offset = rand() % MAX_PAYLOAD_SIZE;
        int key = rand();
        record rec = {rand() % 100}; // Random value between 0 and 99

        array->offsets[i] = offset;
        array->keys[i] = key;
        array->records[i] = rec;

        ++array->count;
    }

    return array;
}

void free_record_array(record_array* array) {
    if (array) {
        free(array->offsets);
        free(array->keys);
        free(array->records);
        free(array);
    }
