    long offset;
    int key;
    NFAPI_CRC_INDICATION_PDU_T record;
} Record;

Record* records = NULL;
long* offsets = NULL;
int* keys = NULL;
size_t num_records = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void process_nfaapi_records(int max_records) {
    if (max_records <= 0 || max_records > MAX_PDUS) {
        fprintf(stderr, "Invalid number of records: %d\n", max_records);
        return;
    }

    size_t required_size = sizeof(Record) * max_records + sizeof(long) * max_records + sizeof(int) * max_records;

    if (required_size > MAX_PAYLOAD_SIZE) {
        fprintf(stderr, "Insufficient memory for requested number of records: %zu\n", required_size);
        return;
    }

    pthread_mutex_lock(&mutex);

    if (records == NULL || offsets == NULL || keys == NULL) {
        free(records);
        free(offsets);
        free(keys);

        records = malloc(required_size);
        offsets = (long*)((char*)records + sizeof(Record) * max_records);
        keys = (int*)((char*)offsets + sizeof(long) * max_records);
    }

    if (records == NULL || offsets == NULL || keys == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

