#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Node {
    char *name;
    size_t size;
    time_t modified;
    struct Node **children;
    int num_children;
} Node;

Node* create_node(const char *name, size_t size, time_t modified) {
    Node *node = (Node *)malloc(sizeof(Node));
    node->name = strdup(name);
    node->size = size;
    node->modified = modified;
    node->children = NULL;
    node->num_children = 0;
    return node;
}

void add_child(Node *parent, Node *child) {
    parent->children = realloc(parent->children, (parent->num_children + 1) * sizeof(Node *));
    parent->children[parent->num_children++] = child;
}

void initialize_tree() {
    srand(time(NULL));
    Node *root = create_node("root0", 0, time(NULL));

    for (int i = 1; i <= 5; ++i) {
        char name[20];
        snprintf(name, sizeof(name), "dir%d", i);
        size_t size = rand() % (1024 * 1024 - 1024 + 1) + 1024;
        time_t modified = time(NULL) - rand() % 365 * 86400;
        Node *dir = create_node(name, size, modified);
        add_child(root, dir);

        for (int j = 1; j <= 3; ++j) {
            char file_name[20];
            snprintf(file_name, sizeof(file_name), "file%d", j);
            size_t file_size = rand() % (1024 * 1024 - 1024 + 1) + 1024;
            time_t file_modified = time(NULL) - rand() % 365 * 86400;
            Node *file = create_node(file_name, file_size, file_modified);
            add_child(dir, file);
        }
    }

    // Print tree structure for demonstration
    void print_tree(Node *node, int level) {
        for (int i = 0; i < level; ++i) printf("  ");
        printf("%s (%zu bytes, %ld)\n", node->name, node->size, node->modified);
        for (int i = 0; i < node->num_children; ++i) {
            print_tree(node->children[i], level + 1);
        }
    }

    print_tree(root, 0);

    // Cleanup function
    void cleanup_node(Node *node) {
        free(node->name);
        for (int i = 0; i < node->num_children; ++i) {
            cleanup_node(node->children[i]);
        }
        free(node->children);
        free(node);
    }

    cleanup_node(root);
}

int main() {
    initialize_tree();
    return 0;
}
