#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define RESIZE_THRESHOLD 0.75

typedef enum { ACTIVE, INACTIVE } ConnectionStatus;

typedef struct {
    char sessionId[256];
    char ipAddress[16];
    time_t lastActivity;
    ConnectionStatus status;
} UserSession;

typedef struct {
    UserSession *sessions;
    size_t capacity;
    size_t size;
} SessionList;

size_t hash(const char *sessionId) {
    size_t hash = 0;
    for (int i = 0; sessionId[i] != '\0'; i++) {
        hash = hash * 31 + sessionId[i];
    }
    return hash % capacity;
}

SessionList* createSessionList(size_t initialCapacity) {
    SessionList *list = malloc(sizeof(SessionList));
    if (!list) return NULL;

    list->sessions = calloc(initialCapacity, sizeof(UserSession));
    if (!list->sessions) {
        free(list);
        return NULL;
    }

    list->capacity = initialCapacity;
    list->size = 0;

    return list;
}

int addSession(SessionList *list, const char *sessionId, const char *ipAddress, ConnectionStatus status) {
    if (list->size >= list->capacity * RESIZE_THRESHOLD) {
        size_t newCapacity = list->capacity * 2;
        UserSession *newSessions = realloc(list->sessions, newCapacity * sizeof(UserSession));
        if (!newSessions) return -1;

        list->sessions = newSessions;
        list->capacity = newCapacity;
    }

    strcpy(list->sessions[list->size].sessionId, sessionId);
    strcpy(list->sessions[list->size].ipAddress, ipAddress);
    list->sessions[list->size].lastActivity = time(NULL);
    list->sessions[list->size].status = status;

    list->size++;
    return 0;
}

void updateLastActivity(SessionList *list, const char *sessionId, void (*updateFunc)(time_t *)) {
    size_t index = hash(sessionId) % list->capacity;
    while (strcmp(list->sessions[index].sessionId, sessionId) != 0 && index < list->size) {
        index++;
    }

    if (index < list->size) {
        updateFunc(&list->sessions[index].lastActivity);
    }
}

void cleanupSessionList(SessionList *list) {
    free(list->sessions);
    free(list);
}
