#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define INITIAL_CAPACITY 10
#define GROWTH_FACTOR 1.2

typedef struct {
    char *source_ip;
    char *destination_ip;
    int port_number;
    bool connection_status;
} ConnectionState;

typedef struct ConnectionStateNode {
    ConnectionState state;
    struct ConnectionStateNode *next;
} ConnectionStateNode;

typedef struct {
    ConnectionStateNode **buckets;
    size_t capacity;
    size_t size;
} ConnectionStateCollection;

size_t hash(const char *ip) {
    // Simple hash function for demonstration purposes
    return (size_t)ip[0] + (size_t)ip[1] * 256 + (size_t)ip[2] * 65536;
}

ConnectionStateCollection* create_connection_state_collection(size_t initial_capacity) {
    ConnectionStateCollection *collection = malloc(sizeof(ConnectionStateCollection));
    collection->buckets = calloc(initial_capacity, sizeof(ConnectionStateNode*));
    collection->capacity = initial_capacity;
    collection->size = 0;
    return collection;
}

void resize_collection(ConnectionStateCollection *collection) {
    size_t new_capacity = (size_t)(collection->capacity * GROWTH_FACTOR);
    ConnectionStateNode **new_buckets = calloc(new_capacity, sizeof(ConnectionStateNode*));

    for (size_t i = 0; i < collection->capacity; ++i) {
        ConnectionStateNode *node = collection->buckets[i];
        while (node != NULL) {
            size_t new_index = hash(node->state.source_ip) % new_capacity;
            ConnectionStateNode *next_node = node->next;
            node->next = new_buckets[new_index];
            new_buckets[new_index] = node;
            node = next_node;
        }
    }

    free(collection->buckets);
    collection->buckets = new_buckets;
    collection->capacity = new_capacity;
}

void add_connection_state(ConnectionStateCollection *collection, const char *source_ip, const char *destination_ip, int port_number, bool connection_status) {
    if (collection->size >= collection->capacity * 0.8) {
        resize_collection(collection);
    }

    size_t index = hash(source_ip) % collection->capacity;
    ConnectionStateNode *new_node = malloc(sizeof(ConnectionStateNode));
    new_node->state.source_ip = strdup(source_ip);
    new_node->state.destination_ip = strdup(destination_ip);
    new_node->state.port_number = port_number;
    new_node->state.connection_status = connection_status;
    new_node->next = collection->buckets[index];
    collection->buckets[index] = new_node;
    ++collection->size;
}

void update_port_numbers(ConnectionStateCollection *collection, int (*update_function)(int)) {
    for (size_t i = 0; i < collection->capacity; ++i) {
        ConnectionStateNode *node = collection->buckets[i];
        while (node != NULL) {
            node->state.port_number = update_function(node->state.port_number);
            node = node->next;
        }
    }
}

void cleanup_connection_state_collection(ConnectionStateCollection *collection) {
    for (size_t i = 0; i < collection->capacity; ++i) {
        ConnectionStateNode *node = collection->buckets[i];
        while (node != NULL) {
            ConnectionStateNode *next_node = node->next;
            free(node->state.source_ip);
            free(node->state.destination_ip);
            free(node);
            node = next_node;
        }
    }
    free(collection->buckets);
    free(collection);
}

int main() {
    ConnectionStateCollection *collection = create_connection_state_collection(INITIAL_CAPACITY);

    add_connection_state(collection, "192.168.1.1", "10.0.0.1", 80, true);
    add_connection_state(collection, "192.168.1.2", "10.0.0.2", 443, false);

    update_port_numbers(collection, [](int port) { return port + 1; });

    cleanup_connection_state_collection(collection);

    return 0;
}
