void init_data_collection(DataCollection *collection, size_t initial_capacity) {
    collection->entries = (DataEntry *)malloc(initial_capacity * sizeof(DataEntry));
    if (!collection->entries) {
        perror("Failed to allocate memory for data collection");
        exit(EXIT_FAILURE);
    }
    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->lock, NULL);
}

void destroy_data_collection(DataCollection *collection) {
    free(collection->entries);
    pthread_mutex_destroy(&collection->lock);
}

void add_entry(DataCollection *collection, DataEntry entry) {
    pthread_mutex_lock(&collection->lock);
    if (collection->size >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        DataEntry *new_entries = (DataEntry *)realloc(collection->entries, new_capacity * sizeof(DataEntry));
        if (!new_entries) {
            perror("Failed to reallocate memory for data collection");
            exit(EXIT_FAILURE);
        }
        collection->entries = new_entries;
        collection->capacity = new_capacity;
    }
    collection->entries[collection->size++] = entry;
    pthread_mutex_unlock(&collection->lock);
}

