["```javascript
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const scriptDirectory = './scripts';
const cacheDuration = 24 * 60 * 60 * 1000; // 24 hours in milliseconds
const maxConcurrentLoads = 5;
const retryAttempts = 3;

let currentLoads = 0;
let loadQueue = [];

function generateFilename(scriptContent) {
    const hash = crypto.createHash('sha256').update(scriptContent).digest('hex');
    const timestamp = new Date().toISOString().replace(/[-:.]/g, '');
    return `${hash}-${timestamp}.js`;
}

function loadScript(filename) {
    currentLoads++;
    console.log(`Loading script: ${filename}`);

    fs.readFile(path.join(scriptDirectory, filename), 'utf8', (err, data) => {
        if (err) {
            console.error(`Failed to load script: ${filename}`, err);
            retryLoad(filename);
            return;
        }

        const script = document.createElement('script');
        script.textContent = data;
        script.onload = () => {
            currentLoads--;
            console.log(`Script loaded and executed successfully: ${filename}`);
            if (loadQueue.length > 0) {
                loadNextScript();
            }
        };
        script.onerror = (e) => {
            currentLoads--;
            console.error(`Failed to execute script: ${filename}`, e);
            retryLoad(filename);
        };

        document.head.appendChild(script);
    });
}

function retryLoad(filename) {
    if (retryAttempts > 0) {
        retryAttempts--;
        console.log(`Retrying load for script: ${filename}`);
        setTimeout(() => loadScript(filename), 1000); // Retry after 1 second
    } else {
        console.error(`Failed to load and execute script after retries: ${filename}`);
    }
}

function loadNextScript() {
    if (currentLoads < maxConcurrentLoads && loadQueue.length > 0) {
        const filename = loadQueue.shift();
        loadScript(filename);
    }
}

function startLoadingScripts() {
    fs.readdir(scriptDirectory, (err, files) => {
        if (err) {
            console.error('Failed to read script directory', err);
            return;
        }

        files.forEach((file) => {
            const filePath = path.join(scriptDirectory, file);
            fs.stat(filePath, (err, stats) => {
                if (err) {
                    console.error(`Failed to get stats for file: ${filePath}`, err);
                    return;
                }

                if (Date.now() - stats.mtimeMs < cacheDuration) {
                    loadQueue.push(file);
                } else {
                    const scriptContent = fs.readFileSync(filePath, 'utf8');
                    const filename = generateFilename(scriptContent);
                    fs.writeFileSync(path.join(scriptDirectory, filename), scriptContent);
                    loadQueue.push(filename);
                }

                if (loadQueue.length > 0) {
                    loadNextScript();
                }
            });
        });
    });
}

startLoadingScripts();
