        {
            throw new InvalidOperationException("Maximum number of connections reached.");
        }

        int descriptor = socket.Handle.ToInt32();
        var connection = new Connection
        {
            Descriptor = descriptor,
            ClientIp = clientIp,
            Status = ConnectionStatus.Connected,
            LastHealthCheck = DateTime.UtcNow
        };

        _connections.TryAdd(descriptor, connection);
    }

    public void RemoveConnection(int descriptor)
    {
        _connections.TryRemove(descriptor, out _);
    }

    private void HealthCheck(object state)
    {
        foreach (var connection in _connections.Values)
        {
            if (connection.Status == ConnectionStatus.Connected && DateTime.UtcNow - connection.LastHealthCheck > TimeSpan.FromSeconds(30))
            {
                // Perform health check
                if (!IsConnectionHealthy(connection.Descriptor))
                {
                    ReestablishConnection(connection.Descriptor);
                }
            }
        }
    }

