record* init_records(int initial_capacity) {
    if (initial_capacity <= 0 || initial_capacity > MAX_RECORDS) {
        return NULL;
    }
    record* records = aligned_alloc(64, initial_capacity * sizeof(record));
    if (!records) {
        return NULL;
    }
    memset(records, 0, initial_capacity * sizeof(record));
    return records;
}

int read_file_value(const char* file_path, int* value) {
    FILE* file = fopen(file_path, "r");
    if (!file) {
        return -1; // File open error
    }
    if (fscanf(file, "%d", value) != 1) {
        fclose(file);
        return -2; // Read error
    }
    fclose(file);
    return 0;
}

int resize_records(record** records, int* capacity) {
    int new_capacity = *capacity + (*capacity / 10);
    if (new_capacity > MAX_RECORDS) {
        new_capacity = MAX_RECORDS;
    }
    record* new_records = aligned_alloc(64, new_capacity * sizeof(record));
    if (!new_records) {
        return -1; // Memory allocation error
    }
    memcpy(new_records, *records, (*capacity) * sizeof(record));
    free(*records);
    *records = new_records;
    *capacity = new_capacity;
    return 0;
}

void cleanup_records(record** records, int* capacity) {
    if (*records) {
        free(*records);
        *records = NULL;
    }
    *capacity = 0;
}

int initialize_first_record(const char* file_path, record* records, int capacity) {
    if (!records || capacity <= 0) {
        return -1; // Invalid input
    }
    int value;
    if (read_file_value(file_path, &value) != 0) {
        return -2; // File read error
    }
    records[0].value = value;
    return 0;
}
