#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct record {
    long offset;
    int key;
    int value;
    struct record *next;
} Record;

typedef struct container {
    Record *head;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    struct container *next;
} Container;

Container *containers = NULL;
size_t total_records = 0;
pthread_mutex_t global_lock;
int reallocations = 0;

void initialize_container(Container **container) {
    *container = (Container *)malloc(sizeof(Container));
    (*container)->head = NULL;
    (*container)->count = 0;
    (*container)->capacity = 16; // Initial capacity
    pthread_mutex_init(&(*container)->lock, NULL);
}

Record *create_record(long offset, int key) {
    Record *record = (Record *)malloc(sizeof(Record));
    record->offset = offset;
    record->key = key;
    record->value = rand();
    record->next = NULL;
    return record;
}

void insert_record(Container *container, long offset, int key) {
    pthread_mutex_lock(&container->lock);
    if (container->count >= container->capacity) {
        reallocations++;
        container->capacity *= 2; // Double the capacity
        Record **new_records = (Record **)realloc(container->head, container->capacity * sizeof(Record *));
        if (!new_records) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        container->head = new_records;
    }
    Record *record = create_record(offset, key);
    record->next = container->head;
    container->head = record;
    container->count++;
    pthread_mutex_unlock(&container->lock);
}

void traverse_containers() {
    Container *current_container = containers;
    while (current_container) {
        Record *current_record = current_container->head;
        while (current_record) {
            printf("Container: %p, Offset: %ld, Key: %d, Value: %d\n", current_container, current_record->offset, current_record->key, current_record->value);
            current_record = current_record->next;
        }
        current_container = current_container->next;
    }
}

void *thread_function(void *arg) {
    Container *container = (Container *)arg;
    for (int i = 0; i < 1000; i++) {
        insert_record(container, i, rand());
    }
    return NULL;
}

int main() {
    srand(time(NULL));
    pthread_mutex_init(&global_lock, NULL);

    initialize_container(&containers);
    Container *current_container = containers;

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        if (pthread_create(&threads[i], NULL, thread_function, current_container) != 0) {
            fprintf(stderr, "Thread creation failed\n");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    traverse_containers();
    printf("Total reallocations: %d\n", reallocations);

    Container *current = containers;
    while (current) {
        Record *record = current->head;
        while (record) {
            Record *temp = record;
            record = record->next;
            free(temp);
        }
        Container *temp_container = current;
        current = current->next;
        free(temp_container);
    }

    pthread_mutex_destroy(&global_lock);

    return 0;
}
