PHY_TRANSPORT_CHANNEL_COLLECTION_T* create_collection() {
    PHY_TRANSPORT_CHANNEL_COLLECTION_T* collection = (PHY_TRANSPORT_CHANNEL_COLLECTION_T*)malloc(sizeof(PHY_TRANSPORT_CHANNEL_COLLECTION_T));
    if (!collection) return NULL;

    collection->pdu_array = NULL;
    collection->count = 0;
    collection->capacity = 0;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void destroy_collection(PHY_TRANSPORT_CHANNEL_COLLECTION_T* collection) {
    if (collection->pdu_array) free(collection->pdu_array);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int add_pdu(PHY_TRANSPORT_CHANNEL_COLLECTION_T* collection, PHY_TRANSPORT_CHANNEL_PDU_T pdu) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity ? collection->capacity * 2 : 1;
        PHY_TRANSPORT_CHANNEL_PDU_T* new_array = realloc(collection->pdu_array, new_capacity * sizeof(PHY_TRANSPORT_CHANNEL_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Memory allocation failed
        }
        collection->pdu_array = new_array;
        collection->capacity = new_capacity;
    }

    collection->pdu_array[collection->count++] = pdu;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

int filter_collection(PHY_TRANSPORT_CHANNEL_COLLECTION_T* collection, int min_version) {
    pthread_mutex_lock(&collection->lock);

    size_t new_count = 0;
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->pdu_array[i].FORMAT_VERSION >= min_version) {
            collection->pdu_array[new_count++] = collection->pdu_array[i];
        }
    }

    if (new_count != collection->count) {
        PHY_TRANSPORT_CHANNEL_PDU_T* new_array = realloc(collection->pdu_array, new_count * sizeof(PHY_TRANSPORT_CHANNEL_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Memory allocation failed
        }
        collection->pdu_array = new_array;
        collection->count = new_count;
    }

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

