#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PACKETS 1024

typedef struct {
    uint32_t header;
    uint32_t payload_length;
    char *payload;
} NetworkPacket;

typedef struct {
    NetworkPacket packets[MAX_PACKETS];
    int count;
    pthread_mutex_t lock;
} PacketCollection;

void packet_collection_init(PacketCollection *collection) {
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);
}

int packet_collection_add(PacketCollection *collection, uint32_t header, uint32_t payload_length, const char *payload) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count >= MAX_PACKETS) {
        pthread_mutex_unlock(&collection->lock);
        return -1; // Collection overflow
    }

    NetworkPacket *packet = &collection->packets[collection->count];
    packet->header = header;
    packet->payload_length = payload_length;

    if (payload_length > 0) {
        packet->payload = malloc(payload_length);
        if (!packet->payload) {
            pthread_mutex_unlock(&collection->lock);
            return -2; // Memory allocation failed
        }
        memcpy(packet->payload, payload, payload_length);
    } else {
        packet->payload = NULL;
    }

    collection->count++;
    pthread_mutex_unlock(&collection->lock);

    return 0; // Success
}

void packet_collection_free(PacketCollection *collection) {
    pthread_mutex_lock(&collection->lock);

    for (int i = 0; i < collection->count; i++) {
        NetworkPacket *packet = &collection->packets[i];
        if (packet->payload) {
            free(packet->payload);
        }
    }

    collection->count = 0;
    pthread_mutex_unlock(&collection->lock);

    pthread_mutex_destroy(&collection->lock);
}
