// Function to insert a string after the first occurrence of another string in a forward list
void insertAfter(std::forward_list<std::string>& flist, const std::string& target, const std::string& value) {
    auto it = flist.before_begin();
    for (; it != flist.end(); ++it) {
        if (*it == target) {
            break;
        }
    }
    if (it != flist.end()) {
        flist.insert_after(it, value);
