#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PROJECTS 1000
#define MAX_STATUS_LENGTH 50

typedef struct {
    int priority;
    char *status;
    time_t deadline;
} Project;

typedef struct Node {
    Project project;
    struct Node *next;
} Node;

Node* createProject(int id, time_t initialDeadline) {
    Node *newNode = (Node*)malloc(sizeof(Node));
    newNode->project.priority = id;
    newNode->project.status = (char*)malloc(MAX_STATUS_LENGTH * sizeof(char));
    strcpy(newNode->project.status, "Pending");
    newNode->project.deadline = initialDeadline + 86400 * id; // Set deadline based on priority
    newNode->next = NULL;
    return newNode;
}

void adjustDeadlinesAndSort(Node **head) {
    time_t now = time(NULL);
    Node *current = *head;
    while (current != NULL) {
        current->project.deadline += rand() % 31; // Adjust deadline by random days
        if (difftime(current->project.deadline, now) <= 604800) { // Check if within 7 days
            strcpy(current->project.status, "In Progress");
        }
        current = current->next;
    }

    // Sort projects based on adjusted deadlines
    Node *sortedHead = NULL;
    while (*head != NULL) {
        Node *temp = *head;
        *head = (*head)->next;

        if (sortedHead == NULL || temp->project.deadline < sortedHead->project.deadline) {
            temp->next = sortedHead;
            sortedHead = temp;
        } else {
            Node *current = sortedHead;
            while (current->next != NULL && current->next->project.deadline <= temp->project.deadline) {
                current = current->next;
            }
            temp->next = current->next;
            current->next = temp;
        }
    }

    *head = sortedHead;
}

void removeProject(Node **head, int id) {
    Node *current = *head;
    Node *previous = NULL;

    while (current != NULL && current->project.priority != id) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) return; // Project not found

    if (previous == NULL) {
        *head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current->project.status);
    free(current);
}

void serializeProjects(Node *head, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) return;

    Node *current = head;
    while (current != NULL) {
        fwrite(&current->project.priority, sizeof(int), 1, file);
        fwrite(current->project.status, sizeof(char), MAX_STATUS_LENGTH, file);
        fwrite(&current->project.deadline, sizeof(time_t), 1, file);
        current = current->next;
    }

    fclose(file);
}

int main() {
    srand(time(NULL));
    Node *head = NULL;

    for (int i = 0; i < MAX_PROJECTS; i++) {
        Node *newNode = createProject(i + 1, time(NULL));
        newNode->next = head;
        head = newNode;
    }

    adjustDeadlinesAndSort(&head);

    removeProject(&head, 500); // Remove project with id 500

    serializeProjects(head, "projects.dat");

    Node *current = head;
    while (current != NULL) {
        free(current->project.status);
        Node *temp = current;
        current = current->next;
        free(temp);
    }

    return 0;
}
