ConnectionPool* createConnectionPool(size_t initialCapacity) {
    ConnectionPool* pool = (ConnectionPool*)malloc(sizeof(ConnectionPool));
    if (pool == NULL) {
        perror("Failed to allocate memory for connection pool");
        return NULL;
    }
    pool->connections = (TCPConnection**)calloc(initialCapacity, sizeof(TCPConnection*));
    if (pool->connections == NULL) {
        perror("Failed to allocate memory for connections array");
        free(pool);
        return NULL;
    }
    pool->capacity = initialCapacity;
    pool->size = 0;
    pthread_mutex_init(&pool->lock, NULL);
    // Initialize other fields as needed
    return pool;
}

