    if (pool != NULL) {
        for (size_t i = 0; i < pool->size; ++i) {
            destroyTCPConnection(pool->connections[i]);
        }
        free(pool->connections);
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}

void addConnection(ConnectionPool* pool, TCPConnection* conn) {
    pthread_mutex_lock(&pool->lock);
    if (pool->size == pool->capacity) {
        // Resize the connection pool
        size_t newCapacity = pool->capacity * 2;
        TCPConnection** newConnections = (TCPConnection**)realloc(pool->connections, newCapacity * sizeof(TCPConnection*));
        if (newConnections == NULL) {
            perror("Failed to resize connection pool");
            pthread_mutex_unlock(&pool->lock);
            return;
        }
        pool->connections = newConnections;
        pool->capacity = newCapacity;
    }
    pool->connections[pool->size++] = conn;
    pthread_mutex_unlock(&pool->lock);
}

