    for (size_t i = 0; i < pool->size; ++i) {
        if (pool->connections[i]->clientID == clientID) {
            destroyTCPConnection(pool->connections[i]);
            for (size_t j = i; j < pool->size - 1; ++j) {
                pool->connections[j] = pool->connections[j + 1];
