    pthread_t monitorThread;
    if (pthread_create(&monitorThread, NULL, monitorConnections, pool) != 0) {
        perror("Failed to create monitoring thread");
        destroyConnectionPool(pool);
        return 1;
    }

    // Add and remove connections as needed
    TCPConnection* conn = createTCPConnection(1, socket(AF_INET, SOCK_STREAM, 0));
    if (conn != NULL) {
        addConnection(pool, conn);
    }

    // ...

    pthread_join(monitorThread, NULL);
    destroyConnectionPool(pool);

    return 0;
}
