void initialize_arrays(int num_records, float temp_range_min, float temp_range_max) {
    // Seed random number generator
    srand(time(NULL));

    // Allocate memory for arrays and structures
    float *temperature_readings = (float *)malloc(num_records * sizeof(float));
    char **sensor_ids = (char **)malloc(num_records * sizeof(char *));
    sensor_data *sensor_data_array = (sensor_data *)malloc(num_records * sizeof(sensor_data));
    metadata *metadata_entry = (metadata *)malloc(sizeof(metadata));
    alert_thresholds *alert_thresholds_entry = (alert_thresholds *)malloc(sizeof(alert_thresholds));

    // Initialize arrays and structures
    for (int i = 0; i < num_records; i++) {
        temperature_readings[i] = temp_range_min + (rand() / (float)RAND_MAX) * (temp_range_max - temp_range_min);
        sensor_ids[i] = (char *)malloc(10 * sizeof(char));
        snprintf(sensor_ids[i], 10, "sensor%d", i);
        sensor_data_array[i].temperature = temperature_readings[i];
        strcpy(sensor_data_array[i].id, sensor_ids[i]);
        sensor_data_array[i].timestamp = time(NULL) * 1e6 + rand() % (int)(1e6); // Microseconds
        sensor_data_array[i].status = operational;
    }

    metadata_entry->record_count = num_records;
    strcpy(metadata_entry->description, "Sensor Data");

    alert_thresholds_entry->max_temp = temp_range_max * 1.1;
    alert_thresholds_entry->min_temp = temp_range_min * 0.9;

    // Free allocated memory
    free(temperature_readings);
    for (int i = 0; i < num_records; i++) {
        free(sensor_ids[i]);
    }
    free(sensor_ids);
    free(sensor_data_array);
    free(metadata_entry);
    free(alert_thresholds_entry);
}

// Main function to demonstrate usage
int main() {
    int num_records = 5;
    float temp_range_min = -10.0f;
    float temp_range_max = 40.0f;

    initialize_arrays(num_records, temp_range_min, temp_range_max);

    return 0;
}
