typedef struct {
    LTE_RLC_PDU_T *list;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* create_dynamic_list() {
    DynamicList *list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->list = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_dynamic_list(DynamicList *list) {
    if (list->list) free(list->list);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_to_list(DynamicList *list, LTE_RLC_PDU_T item) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        LTE_RLC_PDU_T *new_list = realloc(list->list, new_capacity * sizeof(LTE_RLC_PDU_T));
        if (!new_list) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }
        list->list = new_list;
        list->capacity = new_capacity;
    }

    list->list[list->count++] = item;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

