#define MAX_ELEMENTS 10000
#define MIN_OFFSET 0
#define MAX_OFFSET 100000
#define MIN_KEY 0
#define MAX_KEY 10000

typedef struct {
    int value;
} Record;

void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void validate_input(int num_elements, long* offsets, int* keys) {
    for (int i = 0; i < num_elements; i++) {
        if (offsets[i] < MIN_OFFSET || offsets[i] > MAX_OFFSET ||
            keys[i] < MIN_KEY || keys[i] > MAX_KEY) {
            fprintf(stderr, "Invalid input at index %d\n", i);
            exit(EXIT_FAILURE);
        }
    }
}

void generate_random_records(int num_elements, Record* records) {
    srand(time(NULL));
    for (int i = 0; i < num_elements; i++) {
        records[i].value = rand() % 10001;
    }
}

void log_error(const char* message) {
    FILE* error_log = fopen("error.log", "a");
    if (error_log != NULL) {
        fprintf(error_log, "%s\n", message);
        fclose(error_log);
    } else {
        printf("Failed to open error log file\n");
    }
}

void stress_test(int num_elements) {
    long* offsets = safe_malloc(num_elements * sizeof(long));
    int* keys = safe_malloc(num_elements * sizeof(int));
    Record* records = safe_malloc(num_elements * sizeof(Record));

    // Simulate heavy load
    for (int i = 0; i < num_elements; i++) {
        offsets[i] = rand() % MAX_OFFSET;
        keys[i] = rand() % MAX_KEY;
    }

    validate_input(num_elements, offsets, keys);
    generate_random_records(num_elements, records);

    free(offsets);
    free(keys);
    free(records);
}

int main() {
    int num_elements = 5000; // Example input
    long* offsets = safe_malloc(num_elements * sizeof(long));
    int* keys = safe_malloc(num_elements * sizeof(int));
    Record* records = safe_malloc(num_elements * sizeof(Record));

    // Simulate user input
    for (int i = 0; i < num_elements; i++) {
        offsets[i] = rand() % MAX_OFFSET;
        keys[i] = rand() % MAX_KEY;
    }

    validate_input(num_elements, offsets, keys);
    generate_random_records(num_elements, records);

    // Simulate stress testing
    stress_test(MAX_ELEMENTS);

    free(offsets);
    free(keys);
    free(records);

    return 0;
}
