    if (pool->size >= pool->capacity) {
        size_t new_capacity = pool->capacity ? pool->capacity * 2 : 1;
        NetworkConnection *new_connections = (NetworkConnection *)realloc(pool->connections, new_capacity * sizeof(NetworkConnection));
        if (!new_connections) {
            pthread_mutex_unlock(&pool->lock);
            return -1;
        }
        pool->connections = new_connections;
        pool->capacity = new_capacity;
    }
