#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 10000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Record {
    char identifier;
    short status_flag;
    long timestamp;
} Record;

typedef struct List {
    void** elements;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} List;

List* create_list(size_t initial_capacity) {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;

    list->elements = (void**)calloc(initial_capacity, sizeof(void*));
    if (!list->elements) {
        free(list);
        return NULL;
    }

    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

int add_element(List* list, void* element) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        void** new_elements = (void**)realloc(list->elements, new_capacity * sizeof(void*));
        if (!new_elements) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Memory allocation failed
        }
        list->elements = new_elements;
        list->capacity = new_capacity;
    }
    list->elements[list->count++] = element;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void print_list(List* list, void (*print_element)(void*)) {
    if (!list) return;

    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; ++i) {
        print_element(list->elements[i]);
    }
    pthread_mutex_unlock(&list->mutex);
}

void free_list(List* list, void (*free_element)(void*)) {
    if (!list) return;

    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; ++i) {
        free_element(list->elements[i]);
    }
    free(list->elements);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

void print_nfaapi(NFAPI_CRC_INDICATION_PDU_T* nfaapi) {
    printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d\n", 
           nfaapi->RX_UE_INFORMATION_TAG, nfaapi->RNTI, nfaapi->CRC_INDICATION_REL8_TAG);
}

void free_nfaapi(NFAPI_CRC_INDICATION_PDU_T* nfaapi) {
    free(nfaapi);
}

void print_record(Record* record) {
    printf("Identifier: %c, Status Flag: %d, Timestamp: %ld\n", 
           record->identifier, record->status_flag, record->timestamp);
}

void free_record(Record* record) {
    free(record);
}

int main() {
    srand(time(NULL));

    List* nfaapi_list = create_list(10);
    List* record_list = create_list(10);

    if (!nfaapi_list || !record_list) {
        printf("Failed to create lists\n");
        return 1;
    }

    for (int i = 0; i < 20; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* nfaapi = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!nfaapi) continue;

        nfaapi->RX_UE_INFORMATION_TAG = i;
        nfaapi->RNTI = rand() % 1000; // Simulate unique RNTI
        nfaapi->CRC_INDICATION_REL8_TAG = rand() % 2; // Random CRCFLAG

        if (add_element(nfaapi_list, nfaapi) != 0) {
            free_nfaapi(nfaapi);
        }
    }

    for (int i = 0; i < 15; ++i) {
        Record* record = (Record*)malloc(sizeof(Record));
        if (!record) continue;

        record->identifier = 'A' + rand() % 26;
        record->status_flag = rand() % 3;
        record->timestamp = time(NULL) + rand() % 100; // Random timestamp within next 100 seconds

        if (add_element(record_list, record) != 0) {
            free_record(record);
        }
    }

    print_list(nfaapi_list, (void (*)(void*))print_nfaapi);
    print_list(record_list, (void (*)(void*))print_record);

    free_list(nfaapi_list, (void (*)(void*))free_nfaapi);
    free_list(record_list, (void (*)(void*))free_record);

    return 0;
}
