#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 1000000
#define INITIAL_CAPACITY 1024

typedef struct {
    long offset;
    int key;
    int value;
} record;

typedef struct {
    record *data;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} record_array;

record_array* create_record_array(size_t initial_capacity) {
    record_array *arr = (record_array*)malloc(sizeof(record_array));
    arr->data = (record*)aligned_alloc(64, initial_capacity * sizeof(record));
    arr->capacity = initial_capacity;
    arr->count = 0;
    pthread_mutex_init(&arr->lock, NULL);
    return arr;
}

void destroy_record_array(record_array *arr) {
    free(arr->data);
    pthread_mutex_destroy(&arr->lock);
    free(arr);
}

int read_file_to_int(const char *path) {
    FILE *file = fopen(path, "r");
    if (!file) {
        perror("Failed to open file");
        return -1;
    }
    int value;
    if (fscanf(file, "%d", &value) != 1) {
        fprintf(stderr, "Invalid integer in file\n");
        fclose(file);
        return -1;
    }
    fclose(file);
    return value;
}

void initialize_record_array(record_array *arr, const char *file_path) {
    pthread_mutex_lock(&arr->lock);
    if (arr->count >= MAX_RECORDS) {
        fprintf(stderr, "Maximum records limit reached\n");
        pthread_mutex_unlock(&arr->lock);
        return;
    }
    int value = read_file_to_int(file_path);
    if (value == -1) {
        pthread_mutex_unlock(&arr->lock);
        return;
    }
    arr->data[arr->count].offset = 0; // Assuming offset is always 0 for simplicity
    arr->data[arr->count].key = arr->count + 1;
    arr->data[arr->count].value = value;
    arr->count++;
    pthread_mutex_unlock(&arr->lock);
}

void resize_record_array(record_array *arr) {
    size_t new_capacity = arr->capacity * 1.1;
    if (new_capacity > MAX_RECORDS) {
        new_capacity = MAX_RECORDS;
    }
    record *new_data = (record*)aligned_alloc(64, new_capacity * sizeof(record));
    if (!new_data) {
        fprintf(stderr, "Failed to allocate memory for resize\n");
        return;
    }
    pthread_mutex_lock(&arr->lock);
    memcpy(new_data, arr->data, arr->count * sizeof(record));
    free(arr->data);
    arr->data = new_data;
    arr->capacity = new_capacity;
    pthread_mutex_unlock(&arr->lock);
}

void cleanup_record_array(record_array *arr) {
    destroy_record_array(arr);
    printf("Processed %zu records\n", arr->count);
}
