        size_t new_capacity = list->capacity == 0 ? 1 : list->capacity * 2;
        TPC_CONFIG_COMMAND *new_commands = realloc(list->commands, new_capacity * sizeof(TPC_CONFIG_COMMAND));
        if (!new_commands) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }
        list->commands = new_commands;
        list->capacity = new_capacity;
    }

    for (size_t i = 0; i < list->count; ++i) {
        if (list->commands[i].BAND == command.BAND && list->commands[i].CHANNEL == command.CHANNEL) {
            pthread_mutex_unlock(&list->lock);
            return -2; // Duplicate BAND and CHANNEL combination
        }
