#define MAX_THREADS 100
#define TASK_QUEUE_SIZE 1000

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    bool processed;
} Task;

Task task_queue[TASK_QUEUE_SIZE];
int front = 0, rear = -1;
pthread_mutex_t queue_lock;
pthread_cond_t not_empty, not_full;

void* worker_thread(void* arg) {
    int thread_id = *(int*)arg;
    while (true) {
        pthread_mutex_lock(&queue_lock);
        while (front == (rear + 1) % TASK_QUEUE_SIZE) {
            pthread_cond_wait(&not_empty, &queue_lock);
        }
        Task task = task_queue[front];
        front = (front + 1) % TASK_QUEUE_SIZE;
        pthread_cond_signal(&not_full);
        pthread_mutex_unlock(&queue_lock);

        // Process the task
        process_task(task.pdu);
    }
}

void enqueue_task(Task task) {
    pthread_mutex_lock(&queue_lock);
    while ((rear + 1) % TASK_QUEUE_SIZE == front) {
        pthread_cond_wait(&not_full, &queue_lock);
    }
    rear = (rear + 1) % TASK_QUEUE_SIZE;
    task_queue[rear] = task;
    pthread_cond_signal(&not_empty);
    pthread_mutex_unlock(&queue_lock);
}

void initialize_worker_threads(int num_threads) {
    pthread_t threads[MAX_THREADS];
    int thread_ids[MAX_THREADS];

    for (int i = 0; i < num_threads; i++) {
        thread_ids[i] = i;
        pthread_create(&threads[i], NULL, worker_thread, &thread_ids[i]);
    }

    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }
}

