        ++search_iterations;
        if (*it == target) {
            for (int i = 0; i < newStr.length(); ++i) {
                if (insertions >= max_insertions) break;
                it = list.insert_after(it, newStr[i]);
                ++insertions;
            }
            // Move past the last inserted element
            if (it != list.end()) ++it;
        } else {
            ++it;
        }
    }

    if (search_iterations == max_search_iterations && insertions < max_insertions) {
        for (int i = 0; i < newStr.length(); ++i) {
            if (insertions >= max_insertions) break;
            list.push_back(newStr[i]);
            ++insertions;
        }
    }

    return {insertions, search_iterations};
}

// Example usage
int main() {
    std::forward_list<std::string> myList = {"apple", "banana", "cherry"};
    auto [inserted, searched] = insertString(myList, "banana", "orange", 3, 2);
    std::cout << "Inserted: " << inserted << ", Searched: " << searched << std::endl;
    for (const auto& str : myList) {
        std::cout << str << " ";
    }
    return 0;
}
