#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_NAME_LENGTH 256

typedef struct {
    char *name;
    int quantity;
    double price;
} Product;

typedef struct {
    Product *products;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} ProductCollection;

ProductCollection* create_product_collection(size_t initial_capacity) {
    ProductCollection *collection = (ProductCollection*)malloc(sizeof(ProductCollection));
    if (!collection) return NULL;

    collection->capacity = initial_capacity;
    collection->size = 0;
    collection->products = (Product*)calloc(initial_capacity, sizeof(Product));
    if (!collection->products) {
        free(collection);
        return NULL;
    }

    pthread_mutex_init(&collection->mutex, NULL);
    return collection;
}

void destroy_product_collection(ProductCollection *collection) {
    for (size_t i = 0; i < collection->size; ++i) {
        free(collection->products[i].name);
    }
    free(collection->products);
    pthread_mutex_destroy(&collection->mutex);
    free(collection);
}

int add_product(ProductCollection *collection, const char *name, int quantity, double price) {
    pthread_mutex_lock(&collection->mutex);

    if (collection->size >= collection->capacity) {
        size_t new_capacity = collection->capacity ? collection->capacity * 2 : 1;
        Product *new_products = (Product*)realloc(collection->products, new_capacity * sizeof(Product));
        if (!new_products) {
            pthread_mutex_unlock(&collection->mutex);
            return -1; // Memory allocation failed
        }
        collection->products = new_products;
        collection->capacity = new_capacity;
    }

    Product *product = &collection->products[collection->size++];
    product->name = (char*)malloc((strlen(name) + 1) * sizeof(char));
    if (!product->name) {
        pthread_mutex_unlock(&collection->mutex);
        return -1; // Memory allocation failed
    }
    strcpy(product->name, name);
    product->quantity = quantity;
    product->price = price;

    pthread_mutex_unlock(&collection->mutex);
    return 0;
}

// Additional functions for concurrent access, resizing, validation, and network integration would be implemented here.
