#define MAX_RNTI 65536

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    size_t count;
} LinkedList;

void init_linked_list(LinkedList* list) {
    list->head = NULL;
    list->count = 0;
}

void free_linked_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->count = 0;
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (node != NULL) {
        node->data = data;
        node->next = NULL;
    }
    return node;
}

void insert_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = create_node(data);
    if (new_node != NULL) {
        new_node->next = list->head;
        list->head = new_node;
        list->count++;
    }
}

int is_rnti_registered(uint16_t rnti, uint8_t* registration_table) {
    return registration_table[rnti % MAX_RNTI] != 0;
}

void set_crc_flag(NFAPI_CRC_INDICATION_PDU_T* pdu, uint8_t* registration_table) {
    if (is_rnti_registered(pdu->rnti, registration_table)) {
        pdu->crc_indication.crcflag = 1;
    } else {
        pdu->crc_indication.crcflag = 0;
    }
}

void process_crc_indications(LinkedList* list, uint8_t* registration_table) {
    Node* current = list->head;
    while (current != NULL) {
        set_crc_flag(&current->data, registration_table);
        current = current->next;
    }
}

