EVP_CIPHER_CTX* init_aes_cipher(const char* password) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) return NULL;

    uint8_t key[32];
    SHA1((unsigned char*)password, strlen(password), key);

    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, (unsigned char*)"0123456789abcdef")) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

void cleanup_cipher(EVP_CIPHER_CTX* ctx) {
    if (ctx != NULL) {
        EVP_CIPHER_CTX_free(ctx);
    }
