#include <stdlib.h>
#include <pthread.h>

typedef enum {
    IN_TRANSIT,
    RECEIVED,
    PROCESSED
} PacketState;

typedef struct {
    unsigned long timestamp;
    char sourceIP[16];
    char destinationIP[16];
    PacketState state;
} PacketMetadata;

typedef struct {
    PacketMetadata* packets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} PacketQueue;

PacketQueue* create_packet_queue(size_t initial_capacity) {
    PacketQueue* queue = (PacketQueue*)malloc(sizeof(PacketQueue));
    if (!queue) return NULL;

    queue->packets = (PacketMetadata*)calloc(initial_capacity, sizeof(PacketMetadata));
    if (!queue->packets) {
        free(queue);
        return NULL;
    }

    queue->capacity = initial_capacity;
    queue->size = 0;
    pthread_mutex_init(&queue->lock, NULL);

    return queue;
}

void destroy_packet_queue(PacketQueue* queue) {
    if (queue) {
        free(queue->packets);
        pthread_mutex_destroy(&queue->lock);
        free(queue);
    }
}

int enqueue_packet(PacketQueue* queue, PacketMetadata packet) {
    pthread_mutex_lock(&queue->lock);

    if (queue->size >= queue->capacity) {
        size_t new_capacity = queue->capacity * 2;
        PacketMetadata* new_packets = (PacketMetadata*)realloc(queue->packets, new_capacity * sizeof(PacketMetadata));
        if (!new_packets) {
            pthread_mutex_unlock(&queue->lock);
            return -1; // Memory allocation failed
        }
        queue->packets = new_packets;
        queue->capacity = new_capacity;
    }

    queue->packets[queue->size++] = packet;

    pthread_mutex_unlock(&queue->lock);
    return 0;
}

int dequeue_packet(PacketQueue* queue, PacketMetadata* packet) {
    pthread_mutex_lock(&queue->lock);

    if (queue->size == 0) {
        pthread_mutex_unlock(&queue->lock);
        return -1; // Queue is empty
    }

    *packet = queue->packets[--queue->size];

    pthread_mutex_unlock(&queue->lock);
    return 0;
}
