    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* init_dynamic_array(size_t initial_capacity) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->pdus = (MAC_PDU**)calloc(initial_capacity, sizeof(MAC_PDU*));
    if (!array->pdus) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

int add_pdu(DynamicArray* array, L2Header header, const char* payload, size_t payload_size) {
    if (array->size >= array->capacity) {
        // Resize the array
        MAC_PDU** new_pdus = (MAC_PDU**)realloc(array->pdus, array->capacity * 2 * sizeof(MAC_PDU*));
        if (!new_pdus) return -1;
        array->pdus = new_pdus;
        array->capacity *= 2;
    }

    MAC_PDU* pdu = (MAC_PDU*)malloc(sizeof(MAC_PDU));
    if (!pdu) return -1;

    pdu->header = header;
    pdu->payload_size = payload_size;
    pdu->payload = (char*)malloc(payload_size);
    if (!pdu->payload) {
        free(pdu);
        return -1;
    }

    // Copy payload data
    memcpy(pdu->payload, payload, payload_size);

    pthread_mutex_lock(&array->lock);
    array->pdus[array->size++] = pdu;
    pthread_mutex_unlock(&array->lock);

    return 0;
}

void free_dynamic_array(DynamicArray* array) {
    if (!array) return;

    for (size_t i = 0; i < array->size; ++i) {
        free(array->pdus[i]->payload);
        free(array->pdus[i]);
    }

    free(array->pdus);
    pthread_mutex_destroy(&array->lock);
    free(array);
}
