#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PDUS 1024
#define MEMORY_BUDGET 1024 * 1024 // 1MB

typedef struct {
    uint8_t L2Header[14];
    uint8_t* payload;
    size_t payload_size;
} MAC_PDU;

typedef struct {
    MAC_PDU* pdus;
    size_t count;
    size_t capacity;
    size_t total_memory_usage;
    pthread_mutex_t lock;
} MAC_PDU_Array;

int init_mac_pdu_array(MAC_PDU_Array* array, size_t initial_capacity) {
    if (initial_capacity > MAX_PDUS) return -1; // Exceeds maximum capacity
    array->pdus = malloc(initial_capacity * sizeof(MAC_PDU));
    if (!array->pdus) return -2; // Memory allocation failed

    array->count = 0;
    array->capacity = initial_capacity;
    array->total_memory_usage = 0;
    pthread_mutex_init(&array->lock, NULL);

    return 0;
}

void free_mac_pdu_array(MAC_PDU_Array* array) {
    for (size_t i = 0; i < array->count; ++i) {
        free(array->pdus[i].payload);
    }
    free(array->pdus);
    pthread_mutex_destroy(&array->lock);
}

int add_mac_pdu(MAC_PDU_Array* array, const MAC_PDU* pdu) {
    pthread_mutex_lock(&array->lock);

    if (array->total_memory_usage + pdu->payload_size > MEMORY_BUDGET) {
        pthread_mutex_unlock(&array->lock);
        return -3; // Memory budget exceeded
    }

    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        MAC_PDU* new_pdus = realloc(array->pdus, new_capacity * sizeof(MAC_PDU));
        if (!new_pdus) {
            pthread_mutex_unlock(&array->lock);
            return -4; // Memory reallocation failed
        }
        array->pdus = new_pdus;
        array->capacity = new_capacity;
    }

    memcpy(&array->pdus[array->count], pdu, sizeof(MAC_PDU));
    array->total_memory_usage += pdu->payload_size;
    ++array->count;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

// Example usage
int main() {
    MAC_PDU_Array array;
    init_mac_pdu_array(&array, 10);

    MAC_PDU pdu = { /* Initialize L2Header and payload */ };
    add_mac_pdu(&array, &pdu);

    free_mac_pdu_array(&array);
    return 0;
}
```

This code snippet provides a basic implementation of a dynamic array for `MAC_PDU` structures with thread safety and memory management. It includes functions to initialize, add PDUs, and free the array. The actual validation logic and payload integrity checks are left as an exercise for the developer to implement based on specific requirements.']

