using System;
using System.Collections.Generic;
using System.IO;
using System.Xml.Linq;

public interface ITileset
{
    float Density { get; }
    float Friction { get; }
}

public class Tile : ITileset
{
    public int X { get; set; }
    public int Y { get; set; }
    public float Density { get; set; }
    public float Friction { get; set; }

    public Tile(int x, int y, float density, float friction)
    {
        X = x;
        Y = y;
        Density = density;
        Friction = friction;
    }
}

public class World
{
    public string Name { get; set; }
    public List<Tile> Tiles { get; set; }

    public World(string name)
    {
        Name = name;
        Tiles = new List<Tile>();
    }

    public void LoadFromXml(string filePath)
    {
        XDocument doc = XDocument.Load(filePath);
        var tiles = from tile in doc.Descendants("Tile")
                    select new Tile(
                        (int)tile.Attribute("X"),
                        (int)tile.Attribute("Y"),
                        (float)tile.Attribute("Density"),
                        (float)tile.Attribute("Friction")
                    );

        Tiles.AddRange(tiles);
    }

    public void SaveToJson(string filePath)
    {
        using (StreamWriter file = File.CreateText(filePath))
        {
            JsonSerializer serializer = new JsonSerializer();
            serializer.Serialize(file, this);
        }
    }
}

public class TileManager
{
    private Dictionary<string, World> worlds;

    public TileManager()
    {
        worlds = new Dictionary<string, World>();
    }

    public void LoadWorld(string worldName, string xmlFilePath)
    {
        if (!worlds.ContainsKey(worldName))
        {
            World world = new World(worldName);
            world.LoadFromXml(xmlFilePath);
            worlds[worldName] = world;
        }
    }

    public void SaveWorld(string worldName, string jsonFilePath)
    {
        if (worlds.ContainsKey(worldName))
        {
            worlds[worldName].SaveToJson(jsonFilePath);
        }
    }

    public World GetWorld(string worldName)
    {
