#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Record {
    int key;
    long offset;
    char* data;
} Record;

typedef struct RecordNode {
    Record record;
    struct RecordNode* next;
} RecordNode;

typedef struct RecordCollection {
    RecordNode* head;
    pthread_mutex_t lock;
} RecordCollection;

RecordCollection* create_record_collection() {
    RecordCollection* collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (collection == NULL) {
        return NULL;
    }
    collection->head = NULL;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void destroy_record_collection(RecordCollection* collection) {
    RecordNode* current = collection->head;
    while (current != NULL) {
        RecordNode* next = current->next;
        free(current->record.data);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int add_record(RecordCollection* collection, int key, long offset, const char* data) {
    pthread_mutex_lock(&collection->lock);
    RecordNode* new_node = (RecordNode*)malloc(sizeof(RecordNode));
    if (new_node == NULL) {
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }
    new_node->record.key = key;
    new_node->record.offset = offset;
    new_node->record.data = strdup(data);
    if (new_node->record.data == NULL) {
        free(new_node);
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }
    new_node->next = collection->head;
    collection->head = new_node;
    pthread_mutex_unlock(&collection->lock);
    return 0;
}

int remove_record(RecordCollection* collection, int key) {
    pthread_mutex_lock(&collection->lock);
    RecordNode* current = collection->head;
    RecordNode* prev = NULL;
    while (current != NULL) {
        if (current->record.key == key) {
            if (prev == NULL) {
                collection->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current->record.data);
            free(current);
            pthread_mutex_unlock(&collection->lock);
            return 0;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&collection->lock);
    return -1;
}

Record* get_record(RecordCollection* collection, int key) {
    pthread_mutex_lock(&collection->lock);
    RecordNode* current = collection->head;
    while (current != NULL) {
        if (current->record.key == key) {
            pthread_mutex_unlock(&collection->lock);
            return &current->record;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&collection->lock);
    return NULL;
}
