    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicList;

DynamicList* create_dynamic_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(INITIAL_CAPACITY, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->capacity = INITIAL_CAPACITY;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void destroy_dynamic_list(DynamicList* list) {
    if (list) {
        pthread_mutex_lock(&list->mutex);
        free(list->data);
        pthread_mutex_unlock(&list->mutex);
        pthread_mutex_destroy(&list->mutex);
        free(list);
    }
}

int add_to_list(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T item) {
    if (!list || !item.RX_UE_INFORMATION_TAG || !item.RNTI || !item.CRC_INDICATION_REL8_TAG) return -1;

    pthread_mutex_lock(&list->mutex);
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&list->mutex);
            return -1;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }

    list->data[list->size++] = item;
    pthread_mutex_unlock(&list->mutex);

    return 0;
}

void initialize_random_number_generator() {
    srand(time(NULL));
}

NFAPI_CRC_INDICATION_PDU_T generate_random_item() {
    NFAPI_CRC_INDICATION_PDU_T item;
    item.RX_UE_INFORMATION_TAG = rand();
    item.RNTI = rand();
    item.CRC_INDICATION_REL8_TAG = rand();
    item.CRCFLAG = MIN_CRCFLAG + (rand() % (MAX_CRCFLAG - MIN_CRCFLAG + 1));
    return item;
}

int main() {
    initialize_random_number_generator();

    DynamicList* list = create_dynamic_list();
    if (!list) return -1;

    for (size_t i = 0; i < 20; ++i) {
        NFAPI_CRC_INDICATION_PDU_T item = generate_random_item();
        if (add_to_list(list, item) != 0) {
            destroy_dynamic_list(list);
            return -1;
        }
    }

    destroy_dynamic_list(list);
    return 0;
}
