#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_SESSIONS 1000

typedef enum {
    IN_TRANSIT,
    RECEIVED,
    PROCESSED
} PacketState;

typedef struct {
    int packetID;
    time_t timestamp;
    char sourceIP[16];
    char destinationIP[16];
    PacketState state;
} PacketMetadata;

typedef struct {
    PacketMetadata *packets;
    int count;
    pthread_mutex_t lock;
} PacketQueue;

typedef struct {
    PacketQueue queues[MAX_SESSIONS];
    int sessionCount;
    pthread_mutex_t sessionLock;
} SessionManager;

SessionManager sessionManager;

void initializePacketQueue(PacketQueue *queue) {
    queue->packets = (PacketMetadata *)malloc(100 * sizeof(PacketMetadata));
    queue->count = 0;
    pthread_mutex_init(&queue->lock, NULL);
}

void destroyPacketQueue(PacketQueue *queue) {
    free(queue->packets);
    pthread_mutex_destroy(&queue->lock);
}

int addPacketToQueue(int sessionID, PacketMetadata packet) {
    pthread_mutex_lock(&sessionManager.queues[sessionID].lock);
    if (sessionManager.queues[sessionID].count >= 100) {
        pthread_mutex_unlock(&sessionManager.queues[sessionID].lock);
        return -1; // Queue is full
    }
    sessionManager.queues[sessionID].packets[sessionManager.queues[sessionID].count++] = packet;
    pthread_mutex_unlock(&sessionManager.queues[sessionID].lock);
    return 0;
}

void initializeSessionManager() {
    for (int i = 0; i < MAX_SESSIONS; i++) {
        initializePacketQueue(&sessionManager.queues[i]);
    }
    sessionManager.sessionCount = 0;
    pthread_mutex_init(&sessionManager.sessionLock, NULL);
}

void destroySessionManager() {
    for (int i = 0; i < MAX_SESSIONS; i++) {
        destroyPacketQueue(&sessionManager.queues[i]);
    }
    pthread_mutex_destroy(&sessionManager.sessionLock);
}

int addNewSession() {
    pthread_mutex_lock(&sessionManager.sessionLock);
    if (sessionManager.sessionCount >= MAX_SESSIONS) {
        pthread_mutex_unlock(&sessionManager.sessionLock);
        return -1; // Maximum sessions reached
    }
    int sessionID = sessionManager.sessionCount++;
    pthread_mutex_unlock(&sessionManager.sessionLock);
    initializePacketQueue(&sessionManager.queues[sessionID]);
    return sessionID;
}

void removeSession(int sessionID) {
    destroyPacketQueue(&sessionManager.queues[sessionID]);
    pthread_mutex_lock(&sessionManager.sessionLock);
    sessionManager.sessionCount--;
    pthread_mutex_unlock(&sessionManager.sessionLock);
}
