#define MAX_PDUS 1024
#define MEMORY_BUDGET 1024 * 1024 // 1MB

typedef struct {
    uint8_t L2Header[14];
    uint8_t* payload;
    size_t payload_size;
} MAC_PDU;

typedef struct {
    MAC_PDU* pdus;
    size_t count;
    size_t capacity;
    size_t total_memory_usage;
    pthread_mutex_t mutex;
} DynamicArray;

int init_dynamic_array(DynamicArray* array, size_t initial_capacity) {
    if (initial_capacity > MAX_PDUS) return -1; // Exceeds maximum capacity
    array->pdus = malloc(initial_capacity * sizeof(MAC_PDU));
    if (!array->pdus) return -2; // Memory allocation failed

    pthread_mutex_init(&array->mutex, NULL);
    array->count = 0;
    array->capacity = initial_capacity;
    array->total_memory_usage = 0;

    return 0;
}

void free_dynamic_array(DynamicArray* array) {
    for (size_t i = 0; i < array->count; ++i) {
        free(array->pdus[i].payload);
    }
    pthread_mutex_destroy(&array->mutex);
    free(array->pdus);
}

int add_pdu_to_array(DynamicArray* array, const MAC_PDU* pdu) {
    pthread_mutex_lock(&array->mutex);

    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        if (new_capacity > MAX_PDUS) return -3; // Exceeds maximum capacity
        MAC_PDU* new_pdus = realloc(array->pdus, new_capacity * sizeof(MAC_PDU));
        if (!new_pdus) {
            pthread_mutex_unlock(&array->mutex);
            return -2; // Memory allocation failed
        }
        array->pdus = new_pdus;
        array->capacity = new_capacity;
    }

    size_t payload_size = pdu->payload_size;
    uint8_t* new_payload = malloc(payload_size);
    if (!new_payload) {
        pthread_mutex_unlock(&array->mutex);
        return -2; // Memory allocation failed
    }
    memcpy(new_payload, pdu->payload, payload_size);

    array->pdus[array->count].L2Header[0] = pdu->L2Header[0];
    array->pdus[array->count].payload = new_payload;
    array->pdus[array->count].payload_size = payload_size;
    ++array->count;

    pthread_mutex_unlock(&array->mutex);
    return 0;
}

// Additional functions for error reporting, configuration flexibility,
// payload integrity check, external dependency integration, performance optimization,
// and customizable validation logic can be implemented here.
