} UEPacket;

typedef struct DynamicArray {
    UEPacket** packets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* createDynamicArray(size_t initialCapacity) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->packets = (UEPacket**)malloc(initialCapacity * sizeof(UEPacket*));
    if (!array->packets) {
        free(array);
        return NULL;
    }

    array->capacity = initialCapacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void destroyDynamicArray(DynamicArray* array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->packets[i]->packetInfoTags);
        free(array->packets[i]);
    }
    free(array->packets);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

void addPacket(DynamicArray* array, UEPacket* packet) {
    pthread_mutex_lock(&array->lock);
    if (array->size == array->capacity) {
        size_t newCapacity = array->capacity * 2;
        UEPacket** newPackets = (UEPacket**)realloc(array->packets, newCapacity * sizeof(UEPacket*));
        if (!newPackets) {
            pthread_mutex_unlock(&array->lock);
            return;
        }
        array->packets = newPackets;
        array->capacity = newCapacity;
    }

    array->packets[array->size++] = packet;
    pthread_mutex_unlock(&array->lock);
}

UEPacket* getPacket(DynamicArray* array, size_t index) {
    if (index >= array->size) return NULL;

    pthread_mutex_lock(&array->lock);
    UEPacket* packet = array->packets[index];
    pthread_mutex_unlock(&array->lock);

    return packet;
}
