    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_record(Record* record) {
    free(record->data.str);
    pthread_mutex_destroy(&record->lock);
    free(record);
}

void destroy_node(Node* node) {
    destroy_record(node->record);
    free(node);
}

void destroy_linked_list(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        destroy_node(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

Record* create_record(int key, long offset, int value, const char* str) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) return NULL;
    record->key = key;
    record->offset = offset;
    record->data.value = value;
    record->data.str = strdup(str);
    if (!record->data.str) {
        free(record);
        return NULL;
    }
    record->ref_count = 0;
    pthread_mutex_init(&record->lock, NULL);
    return record;
}

Node* create_node(Record* record) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    node->record = record;
    node->next = NULL;
    return node;
}

void add_record(LinkedList* list, Record* record) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = create_node(record);
    if (new_node) {
        new_node->next = list->head;
        list->head = new_node;
    }
    pthread_mutex_unlock(&list->lock);
}

void print_records(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        Record* record = current->record;
        printf("Key: %d, Offset: %ld, Value: %d, String: %s, Ref Count: %d\n",
               record->key, record->offset, record->data.value, record->data.str, record->ref_count);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void delete_record(LinkedList* list, int key) {
    pthread_mutex_lock(&list->lock);
    Node** prev = &list->head;
    while (*prev) {
        Record* record = (*prev)->record;
        if (record->key == key) {
            Node* temp = *prev;
            *prev = (*prev)->next;
            destroy_node(temp);
            break;
        }
        prev = &(*prev)->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void batch_update(LinkedList* list, Record** records, int count) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < count; i++) {
        add_record(list, records[i]);
    }
    pthread_mutex_unlock(&list->lock);
}
