#define MAX_ELEMENTS 50000
#define SORT_THRESHOLD 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T *array[MAX_ELEMENTS];
int count = 0;

void* update_rnti_list(void* arg) {
    // Simulate external data source
    int new_rntis[] = {1, 2, 3, 4, 5};
    int num_new_rntis = sizeof(new_rntis) / sizeof(new_rntis[0]);

    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_new_rntis; i++) {
        if (count >= MAX_ELEMENTS) break;
        array[count] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!array[count]) {
            perror("Memory allocation failed");
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
        array[count]->RX_UE_INFORMATION_TAG = 100 + i;
        array[count]->RNTI = new_rntis[i];
        array[count]->CRC_INDICATION_REL8_TAG = 200 + i;
        array[count]->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
        count++;
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void sort_array() {
    if (count <= SORT_THRESHOLD) {
        qsort(array, count, sizeof(NFAPI_CRC_INDICATION_PDU_T), 
              (int (*)(const void *, const void *))compare_rnti);
    } else {
        // Use disk-based sorting or alternative algorithms
        printf("Using disk-based sorting for large datasets\n");
    }
}

int compare_rnti(const void *a, const void *b) {
    return ((NFAPI_CRC_INDICATION_PDU_T*)a)->RNTI - ((NFAPI_CRC_INDICATION_PDU_T*)b)->RNTI;
}

void* filter_array(void* arg) {
    int threshold = *(int*)arg;
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < count; i++) {
        if (array[i]->CRCFLAG < threshold) {
            free(array[i]);
            array[i] = NULL;
            // Shift elements to fill the gap
            for (int j = i; j < count - 1; j++) {
                array[j] = array[j + 1];
            }
            count--;
            i--; // Adjust index after shifting
        }
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void cleanup() {
    for (int i = 0; i < count; i++) {
        free(array[i]);
    }
    count = 0;
}

int main() {
    srand(time(NULL));
    pthread_t update_thread, sort_thread, filter_thread;

    if (pthread_create(&update_thread, NULL, update_rnti_list, NULL) != 0) {
        perror("Thread creation failed");
        return 1;
    }

    if (pthread_join(update_thread, NULL) != 0) {
        perror("Thread join failed");
        return 1;
    }

    sort_array();

    int threshold = 1; // Configurable threshold
    if (pthread_create(&filter_thread, NULL, filter_array, &threshold) != 0) {
        perror("Thread creation failed");
        return 1;
    }

    if (pthread_join(filter_thread, NULL) != 0) {
        perror("Thread join failed");
        return 1;
    }

    cleanup();

    return 0;
}
