#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <semaphore.h>
#include <time.h>

#define MAX_CONNECTIONS 100

typedef struct {
    int socket_descriptor;
    char client_ip[16];
    int connection_status;
    time_t last_health_check;
} NFV_RAN;

typedef struct {
    NFV_RAN connections[MAX_CONNECTIONS];
    sem_t semaphore;
    int current_size;
} ConnectionPool;

void initialize_connection_pool(ConnectionPool *pool, int initial_size) {
    pool->current_size = initial_size;
    sem_init(&pool->semaphore, 0, initial_size);
}

int add_connection(ConnectionPool *pool, NFV_RAN new_connection) {
    if (sem_wait(&pool->semaphore) == -1) {
        perror("Failed to acquire semaphore");
        return -1;
    }

    if (pool->current_size >= MAX_CONNECTIONS) {
        sem_post(&pool->semaphore);
        fprintf(stderr, "Connection pool is full\n");
        return -1;
    }

    pool->connections[pool->current_size++] = new_connection;

    sem_post(&pool->semaphore);
    return 0;
}

NFV_RAN* get_next_connection(ConnectionPool *pool) {
    if (sem_wait(&pool->semaphore) == -1) {
        perror("Failed to acquire semaphore");
        return NULL;
    }

    if (pool->current_size == 0) {
        sem_post(&pool->semaphore);
        fprintf(stderr, "No available connections\n");
        return NULL;
    }

    NFV_RAN *connection = &pool->connections[--pool->current_size];
    sem_post(&pool->semaphore);
    return connection;
}

void shutdown_connection_pool(ConnectionPool *pool) {
    sem_destroy(&pool->semaphore);
}
