#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 1000

typedef struct Record {
    int key;
    long offset;
    char *data;
} Record;

typedef struct RecordCollection {
    Record records[MAX_RECORDS];
    int count;
    pthread_mutex_t lock;
} RecordCollection;

void init_collection(RecordCollection *collection) {
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);
}

int add_record(RecordCollection *collection, int key, long offset, const char *data) {
    pthread_mutex_lock(&collection->lock);
    if (collection->count >= MAX_RECORDS) {
        pthread_mutex_unlock(&collection->lock);
        return -1; // Collection is full
    }
    Record *new_record = &collection->records[collection->count];
    new_record->key = key;
    new_record->offset = offset;
    new_record->data = strdup(data); // Duplicate the string
    if (new_record->data == NULL) {
        pthread_mutex_unlock(&collection->lock);
        return -2; // Memory allocation failed
    }
    collection->count++;
    pthread_mutex_unlock(&collection->lock);
    return 0;
}

int remove_record(RecordCollection *collection, int key) {
    pthread_mutex_lock(&collection->lock);
    for (int i = 0; i < collection->count; i++) {
        if (collection->records[i].key == key) {
            free(collection->records[i].data); // Free the string
            for (int j = i; j < collection->count - 1; j++) {
                collection->records[j] = collection->records[j + 1];
            }
            collection->count--;
            pthread_mutex_unlock(&collection->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&collection->lock);
    return -1; // Record not found
}

Record *get_record(RecordCollection *collection, int key) {
    pthread_mutex_lock(&collection->lock);
    for (int i = 0; i < collection->count; i++) {
        if (collection->records[i].key == key) {
            pthread_mutex_unlock(&collection->lock);
            return &collection->records[i];
        }
    }
    pthread_mutex_unlock(&collection->lock);
    return NULL;
}

void cleanup_collection(RecordCollection *collection) {
    pthread_mutex_lock(&collection->lock);
    for (int i = 0; i < collection->count; i++) {
        free(collection->records[i].data); // Free each string
    }
    collection->count = 0;
    pthread_mutex_unlock(&collection->lock);
}

void log_operation(int success, const char *message) {
    if (success) {
        printf("SUCCESS: %s\n", message);
    } else {
        printf("ERROR: %s\n", message);
    }
}
