typedef struct {
    float budget;
    int completion_percentage;
    struct tm start_date;
} Project;

void initialize_project_list(Project **project_list, int num_projects) {
    *project_list = (Project *)malloc(num_projects * sizeof(Project));
    if (*project_list == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    time_t current_time = time(NULL);
    struct tm fixed_year_start;
    fixed_year_start.tm_year = 2023 - 1900; // Year is stored as years since 1900
    fixed_year_start.tm_mon = 0; // January
    fixed_year_start.tm_mday = 1;
    fixed_year_start.tm_hour = 0;
    fixed_year_start.tm_min = 0;
    fixed_year_start.tm_sec = 0;
    fixed_year_start.tm_isdst = -1;

    for (int i = 0; i < num_projects; i++) {
        (*project_list)[i].budget = 10000 + i * 10000;
        (*project_list)[i].completion_percentage = 0;
        time_t project_start_time = mktime(&fixed_year_start);
        if (project_start_time == -1) {
            fprintf(stderr, "Failed to set start date for project %d\n", i);
            exit(1);
        }
        memcpy(&(*project_list)[i].start_date, &fixed_year_start, sizeof(struct tm));
    }

    srand(time(NULL));
    time_t current_date = time(NULL);
    struct tm *current_tm = localtime(&current_date);

    for (int i = 0; i < num_projects; i++) {
        int random_completion = rand() % 91;
        (*project_list)[i].completion_percentage += random_completion;

        if ((*project_list)[i].completion_percentage > 100) {
            (*project_list)[i].completion_percentage = 100;
        }
    }
}

void update_start_date(Project *project, int delay_days) {
    time_t project_start_time = mktime(&project->start_date);
    if (project_start_time == -1) {
        fprintf(stderr, "Failed to get start date for project\n");
        return;
    }

    project_start_time += delay_days * 24 * 60 * 60; // Convert days to seconds
    struct tm new_start_date = *localtime(&project_start_time);

    if (mktime(&new_start_date) == -1 || new_start_date.tm_year < 2023 - 1900) {
        fprintf(stderr, "New start date precedes fixed year of 2023\n");
        return;
    }

    memcpy(&project->start_date, &new_start_date, sizeof(struct tm));
}

int main() {
    int num_projects = 5;
    Project *projects;

    initialize_project_list(&projects, num_projects);

    for (int i = 0; i < num_projects; i++) {
        printf("Project %d: Budget = %.2f, Completion = %d%%, Start Date = %s\n",
               i, projects[i].budget, projects[i].completion_percentage,
               asctime(&projects[i].start_date));
    }

    update_start_date(&projects[0], 30);
    printf("Updated Start Date for Project 0: %s\n", asctime(&projects[0].start_date));

    free(projects);

    return 0;
}
