typedef struct {
    uint8_t *buffer;
    size_t buffer_size;
} TransportBlock;

typedef struct {
    MAC_PDU mac_pdu;
    RLC_PDU rlc_pdu;
    TransportBlock transport_block;
} LTE_PHY_TRANSPORT_LAYER_PDU_T;

LTE_PHY_TRANSPORT_LAYER_PDU_T* initialize_transport_layer_pdu(size_t pdu_count, size_t block_size) {
    LTE_PHY_TRANSPORT_LAYER_PDU_T *pdus = (LTE_PHY_TRANSPORT_LAYER_PDU_T*)malloc(pdu_count * sizeof(LTE_PHY_TRANSPORT_LAYER_PDU_T));
    if (!pdus) {
        return NULL;
    }

    for (size_t i = 0; i < pdu_count; ++i) {
        pdus[i].transport_block.buffer = (uint8_t*)malloc(block_size);
        if (!pdus[i].transport_block.buffer) {
            // Handle memory allocation failure
            for (size_t j = 0; j < i; ++j) {
                free(pdus[j].transport_block.buffer);
            }
            free(pdus);
            return NULL;
        }
        pdus[i].transport_block.buffer_size = block_size;
    }

    return pdus;
}

void configure_transport_layer_pdu(LTE_PHY_TRANSPORT_LAYER_PDU_T *pdus, size_t pdu_count, Configuration config) {
    for (size_t i = 0; i < pdu_count; ++i) {
        // Configure MAC_PDU and RLC_PDU elements
        configure_mac_pdu(&pdus[i].mac_pdu);
        configure_rlc_pdu(&pdus[i].rlc_pdu);

        // Initialize transport block with data
        size_t data_size = generate_data(pdus[i].transport_block.buffer, pdus[i].transport_block.buffer_size);
        if (data_size != pdus[i].transport_block.buffer_size) {
            // Handle data generation failure
            free(pdus[i].transport_block.buffer);
            continue;
        }

        // Set CRC and sequence number
        set_crc_and_sequence_number(&pdus[i], config.sequence_range_start, config.sequence_range_end);

        // Initialize retransmission logic
        pdus[i].retries = 0;
