typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* createList() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (list == NULL) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void addElement(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        pthread_mutex_unlock(&list->lock);
        return; // Handle memory allocation failure
    }
    newNode->data = data;
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
}

void updateElement(DynamicList* list, int RNTI, NFAPI_CRC_INDICATION_PDU_T newData) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            current->data = newData;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void removeElement(DynamicList* list, int RNTI) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* prev = NULL;
    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

int validateCRCFlags(DynamicList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    int count = 0;
    while (current != NULL) {
        // Implement CRC validation logic here
        // Example: if (calculateChecksum(current->data.RX_DATA) != current->data.CRC_INDICATION_REL8_TAG) {
        //              printf("CRC validation failed for RNTI %d\n", current->data.RNTI);
        //          }
        count++;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return count;
}

void destroyList(DynamicList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
