record* create_records(int size) {
    if (size <= 0) return NULL;

    // Initialize random seed
    srand(time(NULL));

    // Allocate memory for arrays
    long* values = malloc(size * sizeof(long));
    int* keys = malloc(size * sizeof(int));
    record* records = malloc(size * sizeof(record));

    if (!values || !keys || !records) {
        free(values);
        free(keys);
        return NULL;
    }

    // Initialize unique keys
    for (int i = 0; i < size; ++i) {
        keys[i] = i;
    }
    for (int i = 1; i < size; ++i) {
        int j;
        do {
            j = rand() % size;
        } while (keys[j] == -1);
        keys[j] = -1;
    }

    // Initialize values and records
    for (int i = 0; i < size; ++i) {
        values[i] = rand() % 1001;
        records[i].value = &values[i];
        records[i].key = keys[i];
        records[i].additional_field = 0;
    }

    // Free temporary keys array
    free(keys);

    return records;
}

void free_records(record* records, int size) {
    if (records) {
        for (int i = 0; i < size; ++i) {
            if (records[i].value) {
                *records[i].value = 0; // Reset value to avoid dangling pointer issues
            }
        }
        free(records);
    }
}
