int allocate_memory(size_t num_records, long **offsets, int **keys, record ***records, hash_entry **hash_table) {
    if (num_records > MAX_RECORDS) {
        fprintf(stderr, "Error: Maximum number of records exceeded.\n");
        return -1;
    }

    *offsets = (long *)calloc(num_records, sizeof(long));
    *keys = (int *)calloc(num_records, sizeof(int));
    *records = (record **)malloc(num_records * sizeof(record *));
    *hash_table = (hash_entry *)calloc(num_records, sizeof(hash_entry));

    if (!*offsets || !*keys || !*records || !*hash_table) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return -1;
    }

    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i] = (record *)malloc(sizeof(record));
        if (!(*records)[i]) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            return -1;
        }
    }

    return num_records;
}

void free_memory(long *offsets, int *keys, record **records, hash_entry *hash_table) {
    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        if (records[i]) {
            free(records[i]);
        }
    }

    free(offsets);
    free(keys);
    free(records);
    free(hash_table);
}

int main() {
