    int *keys;
    record **records;
    hash_entry *hash_table;

    size_t num_records = 5000; // Example number of records
    int result = allocate_memory(num_records, &offsets, &keys, &records, &hash_table);

    if (result != -1) {
        printf("Memory allocation successful for %zu records.\n", result);
        free_memory(offsets, keys, records, hash_table);
    }

    return 0;
}
