void initialize_connection_pool(int initial_size) {
    sem_init(&connection_pool_semaphore, 0, initial_size);
}

void add_connection(NFV_RAN new_connection) {
    sem_wait(&connection_pool_semaphore);
    if (current_connections < MAX_CONNECTIONS) {
        connections[current_connections++] = new_connection;
    } else {
        printf("Connection pool is full!\n");
    }
    sem_post(&connection_pool_semaphore);
}

void remove_connection(int socket_descriptor) {
    sem_wait(&connection_pool_semaphore);
    for (int i = 0; i < current_connections; i++) {
        if (connections[i].socket_descriptor == socket_descriptor) {
            memmove(&connections[i], &connections[i + 1], sizeof(NFV_RAN) * (current_connections - i - 1));
            current_connections--;
            break;
        }
    }
    sem_post(&connection_pool_semaphore);
}

void load_balance_connections() {
    // Implement a simple round-robin load balancing algorithm
    static int next_index = 0;
    for (int i = 0; i < current_connections; i++) {
        NFV_RAN *current_connection = &connections[(next_index + i) % current_connections];
        // Perform operations on the current connection
    }
}

void graceful_shutdown() {
    sem_destroy(&connection_pool_semaphore);
    // Perform any additional cleanup or resource release
}

