record* initialize_records(size_t long_size, size_t key_size, unsigned int seed) {
    static record result;
    static long *temp_long_values = NULL;
    static int *temp_int_keys = NULL;
    static size_t temp_long_size = 0;
    static size_t temp_key_size = 0;

    if (long_size != temp_long_size || key_size != temp_key_size) {
        free(temp_long_values);
        free(temp_int_keys);

        temp_long_values = malloc(long_size * sizeof(long));
        temp_int_keys = malloc(key_size * sizeof(int));

        if (!temp_long_values || !temp_int_keys) {
            return (record*)-1; // Return error code for allocation failure
        }

        temp_long_size = long_size;
        temp_key_size = key_size;

        srand(seed);
    }

    for (size_t i = 0; i < long_size; ++i) {
        temp_long_values[i] = rand() % 1001;
    }

    int used_keys[10001] = {0};
    size_t key_index = 0;

    while (key_index < key_size) {
        int key = rand() % 10001;
        if (!used_keys[key]) {
            temp_int_keys[key_index++] = key;
            used_keys[key] = 1;
        }
    }

    result.long_values = temp_long_values;
    result.int_keys = temp_int_keys;

    return &result;
}
