typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

record* records[MAX_RECORDS];
NFAPI_CRC_INDICATION_PDU_T* nfapi_entries[MAX_NFAPI_ENTRIES];

pthread_mutex_t record_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t nfapi_lock = PTHREAD_MUTEX_INITIALIZER;

void init_records(int count, int min_value, int max_value) {
    pthread_mutex_lock(&record_lock);
    for (int i = 0; i < count; i++) {
        records[i] = malloc(sizeof(record));
        records[i]->value = rand() % (max_value - min_value + 1) + min_value;
    }
    pthread_mutex_unlock(&record_lock);
}

void init_nfapi_entries(int count) {
    pthread_mutex_lock(&nfapi_lock);
    for (int i = 0; i < count; i++) {
        nfapi_entries[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        nfapi_entries[i]->RX_UE_INFORMATION_TAG = rand() % MAX_RECORDS;
        nfapi_entries[i]->RNTI = rand() % 1024;
        nfapi_entries[i]->CRC_INDICATION_REL8_TAG = rand() % 1024;
        nfapi_entries[i]->CRCFLAG = rand() % 2;
    }
    pthread_mutex_unlock(&nfapi_lock);
}

void filter_nfapi_entries(int threshold) {
    pthread_mutex_lock(&nfapi_lock);
    for (int i = 0; i < MAX_NFAPI_ENTRIES; i++) {
        if (nfapi_entries[i]->CRCFLAG != threshold) {
            free(nfapi_entries[i]);
            nfapi_entries[i] = NULL;
        }
    }
    pthread_mutex_unlock(&nfapi_lock);
}

void serialize_records(const char* filename, int count) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&count, sizeof(int), 1, file);
    for (int i = 0; i < count; i++) {
        fwrite(records[i], sizeof(record), 1, file);
    }

    fclose(file);
}

void deserialize_records(const char* filename, int* count) {
    FILE* file = fopen(filename, "rb");
    if (!file) return;

    fread(count, sizeof(int), 1, file);
    for (int i = 0; i < *count; i++) {
        records[i] = malloc(sizeof(record));
        fread(records[i], sizeof(record), 1, file);
    }

    fclose(file);
}

void serialize_nfapi_entries(const char* filename, int count) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&count, sizeof(int), 1, file);
    for (int i = 0; i < count; i++) {
        if (nfapi_entries[i]) {
            fwrite(nfapi_entries[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        }
    }

    fclose(file);
}

void deserialize_nfapi_entries(const char* filename, int* count) {
    FILE* file = fopen(filename, "rb");
    if (!file) return;

    fread(count, sizeof(int), 1, file);
    for (int i = 0; i < *count; i++) {
        nfapi_entries[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        fread(nfapi_entries[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }

    fclose(file);
}

void free_records(int count) {
    pthread_mutex_lock(&record_lock);
    for (int i = 0; i < count; i++) {
        if (records[i]) {
            free(records[i]);
            records[i] = NULL;
        }
    }
    pthread_mutex_unlock(&record_lock);
}

void free_nfapi_entries(int count) {
    pthread_mutex_lock(&nfapi_lock);
    for (int i = 0; i < count; i++) {
        if (nfapi_entries[i]) {
            free(nfapi_entries[i]);
            nfapi_entries[i] = NULL;
