#include <stdatomic.h>

typedef enum {
    IN_TRANSIT,
    RECEIVED,
    PROCESSED
} PacketState;

typedef struct {
    uint64_t timestamp;
    char sourceIP[16];
    char destinationIP[16];
    PacketState state;
} PacketMetadata;

typedef struct {
    PacketMetadata *packets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} PacketQueue;

void initPacketQueue(PacketQueue *queue, size_t initialCapacity) {
    queue->packets = (PacketMetadata *)malloc(initialCapacity * sizeof(PacketMetadata));
    if (!queue->packets) {
        perror("Failed to allocate memory for packet queue");
        exit(EXIT_FAILURE);
    }
    queue->capacity = initialCapacity;
    queue->size = 0;
    pthread_mutex_init(&queue->lock, NULL);
}

void enqueuePacket(PacketQueue *queue, PacketMetadata packet) {
    pthread_mutex_lock(&queue->lock);
    if (queue->size == queue->capacity) {
        size_t newCapacity = queue->capacity * 2;
        PacketMetadata *newPackets = (PacketMetadata *)realloc(queue->packets, newCapacity * sizeof(PacketMetadata));
        if (!newPackets) {
            perror("Failed to reallocate memory for packet queue");
            exit(EXIT_FAILURE);
        }
        queue->packets = newPackets;
        queue->capacity = newCapacity;
    }
    queue->packets[queue->size++] = packet;
    pthread_mutex_unlock(&queue->lock);
}

void sortPacketQueue(PacketQueue *queue) {
    pthread_mutex_lock(&queue->lock);
    // Implement sorting algorithm (e.g., quicksort, mergesort)
    // For simplicity, using a placeholder function
    for (size_t i = 0; i < queue->size - 1; ++i) {
        for (size_t j = 0; j < queue->size - i - 1; ++j) {
            if (queue->packets[j].timestamp > queue->packets[j + 1].timestamp) {
                PacketMetadata temp = queue->packets[j];
                queue->packets[j] = queue->packets[j + 1];
                queue->packets[j + 1] = temp;
            }
        }
    }
    pthread_mutex_unlock(&queue->lock);
}

void cleanupPacketQueue(PacketQueue *queue) {
    free(queue->packets);
    pthread_mutex_destroy(&queue->lock);
}

int handleNetworkPackets(PacketQueue *queue, size_t initialCapacity) {
    initPacketQueue(queue, initialCapacity);

    // Simulate adding packets to the queue
    for (size_t i = 0; i < 1000000; ++i) {
        PacketMetadata packet;
        packet.timestamp = i;
        snprintf(packet.sourceIP, sizeof(packet.sourceIP), "192.168.%d.%d", i % 256, i / 256);
        snprintf(packet.destinationIP, sizeof(packet.destinationIP), "10.0.%d.%d", i % 256, i / 256);
        packet.state = IN_TRANSIT;
        enqueuePacket(queue, packet);
    }

    sortPacketQueue(queue);

    cleanupPacketQueue(queue);

    return 0;
}
