        NFAPI_CRC_INDICATION_PDU_T *new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) {
            return -2; // Memory allocation failed
        }

        new_node->rx_ue_information_tag.RNTI = rand() % 1000 + 1;
        new_node->rx_ue_information_tag.CRCFLAG = rand() % 2;
        new_node->rnti = new_node->rx_ue_information_tag.RNTI;
        new_node->crc_indication_rel8_tag = new_node->rx_ue_information_tag.CRCFLAG;

        pthread_mutex_lock(&list->lock);
        if (list->head == NULL || list->head->rnti > new_node->rnti) {
            new_node->next = list->head;
            list->head = new_node;
        } else {
            NFAPI_CRC_INDICATION_PDU_T *current = list->head;
            while (current->next != NULL && current->next->rnti < new_node->rnti) {
                current = current->next;
            }
            new_node->next = current->next;
            current->next = new_node;
        }
        pthread_mutex_unlock(&list->lock);
    }

    return 0; // Success
}

void free_crc_list(CRC_LIST *list) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}

