void add_frame(FrameList *list, PHY_RX_FRAME_STATS frame) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        size_t new_capacity = (list->capacity == 0) ? MAX_FRAMES : list->capacity * 2;
        PHY_RX_FRAME_STATS *new_frames = realloc(list->frames, new_capacity * sizeof(PHY_RX_FRAME_STATS));
        if (new_frames == NULL) {
            perror("Failed to allocate memory for frame list");
            pthread_mutex_unlock(&list->lock);
            return;
        }
        list->frames = new_frames;
        list->capacity = new_capacity;
    }
    list->frames[list->count++] = frame;
    pthread_mutex_unlock(&list->lock);
}

