#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PDUS 1024

typedef struct {
    uint8_t header[14];
    uint8_t *payload;
    size_t payload_size;
} MAC_PDU;

typedef struct {
    MAC_PDU *pdus;
    size_t count;
    size_t capacity;
    size_t memory_usage;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* init_dynamic_array(size_t initial_capacity) {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->pdus = (MAC_PDU*)calloc(initial_capacity, sizeof(MAC_PDU));
    if (!array->pdus) {
        free(array);
        return NULL;
    }

    array->count = 0;
    array->capacity = initial_capacity;
    array->memory_usage = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void destroy_dynamic_array(DynamicArray *array) {
    for (size_t i = 0; i < array->count; ++i) {
        free(array->pdus[i].payload);
    }
    free(array->pdus);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int add_pdu_to_array(DynamicArray *array, const MAC_PDU *pdu, size_t max_memory_usage) {
    pthread_mutex_lock(&array->lock);

    if (array->memory_usage + pdu->payload_size > max_memory_usage) {
        pthread_mutex_unlock(&array->lock);
        return -1; // Memory limit exceeded
    }

    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        MAC_PDU *new_pdus = (MAC_PDU*)realloc(array->pdus, new_capacity * sizeof(MAC_PDU));
        if (!new_pdus) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Realloc failed
        }
        array->pdus = new_pdus;
        array->capacity = new_capacity;
    }

    memcpy(&array->pdus[array->count], pdu, sizeof(MAC_PDU));
    array->pdus[array->count].payload = (uint8_t*)malloc(pdu->payload_size);
    if (!array->pdus[array->count].payload) {
        pthread_mutex_unlock(&array->lock);
        return -1; // Payload allocation failed
    }
    memcpy(array->pdus[array->count].payload, pdu->payload, pdu->payload_size);

    array->memory_usage += pdu->payload_size;
    ++array->count;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

