Record* create_records(int num_records, int key_range_start, int key_range_end) {
    if (num_records <= 0 || key_range_start >= key_range_end) {
        return NULL;
    }

    Record* records = (Record*)malloc(num_records * sizeof(Record));
    if (!records) {
        return NULL;
    }

    for (int i = 0; i < num_records; ++i) {
        records[i].key = rand() % (key_range_end - key_range_start + 1) + key_range_start;

        // Generate unique identifier based on index
        char identifier_buffer[20];
        snprintf(identifier_buffer, sizeof(identifier_buffer), "record_%d", i);
        records[i].identifier = strdup(identifier_buffer);
        if (!records[i].identifier) {
            free_records(records, i);
            return NULL;
        }

        // Allocate memory for metadata string
        records[i].metadata = (char**)malloc(sizeof(char*));
        if (!records[i].metadata) {
            free_records(records, i);
            return NULL;
        }
        *records[i].metadata = strdup("default_metadata");
        if (!(*records[i].metadata)) {
            free_records(records, i);
            return NULL;
        }
    }

    return records;
}

void free_records(Record* records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        free(records[i].identifier);
        free(*records[i].metadata);
        free(records[i].metadata);
    }
    free(records);
}

int main() {
    srand(time(NULL));
    int num_records = 10;
    int key_range_start = 1;
    int key_range_end = 100;

    Record* records = create_records(num_records, key_range_start, key_range_end);
    if (records) {
        // Use the records here
        free_records(records, num_records);
    }

    return 0;
}
