    if (!crc_indications) {
        fprintf(stderr, "Memory allocation failed for CRC indications\n");
        exit(EXIT_FAILURE);
    }
}

void init_sessions() {
    sessions = (UserSession**)malloc(max_session_capacity * sizeof(UserSession*));
    if (!sessions) {
        fprintf(stderr, "Memory allocation failed for user sessions\n");
        exit(EXIT_FAILURE);
    }

    time_t current_time = time(NULL);
    for (int i = 0; i < max_session_capacity; i++) {
        sessions[i] = (UserSession*)malloc(sizeof(UserSession));
        if (!sessions[i]) {
            fprintf(stderr, "Memory allocation failed for user session %d\n", i);
            exit(EXIT_FAILURE);
        }
        sessions[i]->session_id = i;
        sessions[i]->timestamp = current_time;
        sessions[i]->device_count = 0;
    }
}

void add_crc_indication(NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (crc_count >= max_crc_capacity) {
        fprintf(stderr, "CRC indication limit reached\n");
        return;
    }

    crc_indications[crc_count] = (CRCIndication*)malloc(sizeof(CRCIndication));
    if (!crc_indications[crc_count]) {
        fprintf(stderr, "Memory allocation failed for CRC indication %d\n", crc_count);
        exit(EXIT_FAILURE);
    }
    crc_indications[crc_count]->pdu = pdu;
    crc_indications[crc_count]->user_session = NULL;

    crc_count++;
}

void add_user_session(int session_id) {
    if (session_count >= max_session_capacity) {
        fprintf(stderr, "User session limit reached\n");
        return;
    }

    sessions[session_count] = (UserSession*)malloc(sizeof(UserSession));
    if (!sessions[session_count]) {
        fprintf(stderr, "Memory allocation failed for user session %d\n", session_count);
        exit(EXIT_FAILURE);
    }
    sessions[session_count]->session_id = session_id;
    sessions[session_count]->timestamp = time(NULL);
    sessions[session_count]->device_count = 0;

    session_count++;
}

void purge_old_sessions() {
    time_t current_time = time(NULL);
    for (int i = 0; i < session_count; i++) {
        if (current_time - sessions[i]->timestamp > SESSION_EXPIRY_TIME) {
            free(sessions[i]);
            sessions[i] = NULL;
            session_count--;
            i--; // Adjust index after removal
        }
    }
}

void validate_device_hardware_id(const char* hardware_id) {
    // Asynchronous validation logic here
}

void log_session_stats() {
    time_t current_time = time(NULL);
    if (current_time % 3600 == 0) { // Log every hour
        printf("Total sessions: %d\n", session_count);
        printf("Average devices per session: %.2f\n", (float)session_count / crc_count);
    }
}

void cleanup() {
    for (int i = 0; i < crc_count; i++) {
        free(crc_indications[i]);
    }
    free(crc_indications);

    for (int i = 0; i < session_count; i++) {
        free(sessions[i]);
    }
    free(sessions);
}

int main() {
    init_crc_indications();
    init_sessions();

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T pdu;
    add_crc_indication(pdu);

    int session_id = 123;
    add_user_session(session_id);

    purge_old_sessions();
    log_session_stats();

    cleanup();

    return 0;
}
