#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int uid;
    char *event_tag;
    time_t timestamp;
    int status_code;
} NetworkEvent;

typedef struct Node {
    NetworkEvent event;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    pthread_mutex_t lock;
} EventList;

void init_event_list(EventList *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void destroy_event_list(EventList *list) {
    Node *current = list->head;
    while (current != NULL) {
        Node *next = current->next;
        free(current->event.event_tag);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}

int add_event(EventList *list, int uid, const char *event_tag, time_t timestamp, int status_code) {
    pthread_mutex_lock(&list->lock);
    Node *new_node = (Node *)malloc(sizeof(Node));
    if (new_node == NULL) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }
    new_node->event.uid = uid;
    new_node->event.event_tag = strdup(event_tag);
    new_node->event.timestamp = timestamp;
    new_node->event.status_code = status_code;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

int update_event(EventList *list, int uid, const char *new_tag, time_t timestamp, int status_code) {
    pthread_mutex_lock(&list->lock);
    Node *current = list->head;
    while (current != NULL) {
        if (current->event.uid == uid) {
            free(current->event.event_tag);
            current->event.event_tag = strdup(new_tag);
            current->event.timestamp = timestamp;
            current->event.status_code = status_code;
            pthread_mutex_unlock(&list->lock);
            return 0; // Success
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return -1; // UID not found
}

NetworkEvent *get_event(EventList *list, int uid) {
    pthread_mutex_lock(&list->lock);
    Node *current = list->head;
    while (current != NULL) {
        if (current->event.uid == uid) {
            NetworkEvent *result = &current->event;
            pthread_mutex_unlock(&list->lock);
            return result; // Found
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL; // UID not found
}
