    pthread_mutex_t mutex;
    bool log_enabled;
    LOG_FORMAT log_format;
} CRC_MANAGER_T;

CRC_MANAGER_T* crc_manager_init(size_t initial_size, bool enable_logging, LOG_FORMAT format) {
    CRC_MANAGER_T *manager = (CRC_MANAGER_T*)malloc(sizeof(CRC_MANAGER_T));
    if (!manager) {
        return NULL; // Memory allocation failed
    }

    manager->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        free(manager);
        return NULL; // Memory allocation failed
    }

    manager->size = 0;
    manager->allocated_size = initial_size;
    pthread_mutex_init(&manager->mutex, NULL);
    manager->log_enabled = enable_logging;
    manager->log_format = format;

    return manager;
}

void crc_manager_free(CRC_MANAGER_T *manager) {
    if (manager->array) {
        free(manager->array);
    }
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

void crc_manager_process_pdus(CRC_MANAGER_T *manager, size_t N) {
    pthread_mutex_lock(&manager->mutex);

    if (N > manager->allocated_size - manager->size) {
        // Resize array
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(manager->array, (manager->allocated_size + N) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&manager->mutex);
            return; // Memory allocation failed
        }
        manager->array = new_array;
        manager->allocated_size += N;
    }

    for (size_t i = 0; i < N; i++) {
        // Simulate probabilistic model for CRCFLAG
        manager->array[manager->size + i].CRCFLAG = rand() % 2 == 0;
        // Set RX_UE_INFORMATION_TAG and RNTI here based on actual logic
    }

    manager->size += N;

    pthread_mutex_unlock(&manager->mutex);

    if (manager->log_enabled) {
        // Log statistics in JSON or CSV format
    }
}

// Unit tests for crc_manager_process_pdus function
void test_crc_manager() {
    CRC_MANAGER_T *manager = crc_manager_init(10, true, LOG_FORMAT_JSON);
    if (!manager) {
        return; // Initialization failed
    }

    crc_manager_process_pdus(manager, 5); // Test with N=5
    crc_manager_process_pdus(manager, 1024); // Test with maximum size

    crc_manager_free(manager);
}
