#include <sys/wait.h>
#include <pthread.h>

#define MAX_LIST_SIZE 100

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *nfaapi_list[MAX_LIST_SIZE];
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
int current_size = 0;

void log_status(const char *message) {
    FILE *log_file = fopen("operation_log.txt", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

int populateNFAPIListAndExecuteCommand(int max_size, const char *command) {
    if (max_size > MAX_LIST_SIZE) {
        log_status("Error: Maximum list size exceeded.");
        return -1;
    }

    for (int i = 0; i < max_size; i++) {
        pthread_mutex_lock(&list_mutex);
        if (current_size >= max_size) {
            pthread_mutex_unlock(&list_mutex);
            log_status("Error: List is full.");
            return -2;
        }
        nfaapi_list[current_size] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (nfaapi_list[current_size] == NULL) {
            pthread_mutex_unlock(&list_mutex);
            log_status("Error: Failed to allocate memory for list entry.");
            return -3;
        }
        // Populate the structure with valid data
        nfaapi_list[current_size]->ue_info = generate_valid_rx_ue_information_tag();
        nfaapi_list[current_size]->rnti = generate_random_rnti();
        nfaapi_list[current_size]->crc_indication.crcflag = rand() % 2;
        current_size++;
        pthread_mutex_unlock(&list_mutex);
    }

    pid_t pid = fork();
    if (pid == -1) {
        log_status("Error: Failed to create background process.");
        return -4;
    } else if (pid == 0) {
        // Child process
        execlp(command, command, NULL);
        log_status("Error: Command execution failed.");
        exit(EXIT_FAILURE);
    } else {
        // Parent process
        int status;
        wait(&status);
        if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
            log_status("Error: Background process exited with an error.");
            return -5;
        }
    }

    log_status("Operation successful.");
    return 1;
}
