#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_PDUS 10000
#define MAX_PAYLOAD_SIZE 2048

typedef struct {
    uint8_t L2Header[14];
    uint8_t *payload;
    size_t payload_size;
} MAC_PDU;

MAC_PDU *pdus[MAX_PDUS];
int pdu_count = 0;
pthread_mutex_t pdu_lock = PTHREAD_MUTEX_INITIALIZER;

void log_error(const char *message) {
    // Implementation of error logging
}

int initializeAndManagePDUs(uint8_t *L2Header, uint8_t *payload, size_t payload_size) {
    pthread_mutex_lock(&pdu_lock);
    if (pdu_count >= MAX_PDUS) {
        log_error("Maximum number of PDUs reached");
        pthread_mutex_unlock(&pdu_lock);
        return -1;
    }
    if (payload_size > MAX_PAYLOAD_SIZE) {
        log_error("Payload size exceeds maximum limit");
        pthread_mutex_unlock(&pdu_lock);
        return -1;
    }

    MAC_PDU *new_pdu = malloc(sizeof(MAC_PDU));
    if (!new_pdu) {
        log_error("Memory allocation failed");
        pthread_mutex_unlock(&pdu_lock);
        return -1;
    }
    memcpy(new_pdu->L2Header, L2Header, 14);
    new_pdu->payload = malloc(payload_size);
    if (!new_pdu->payload) {
        free(new_pdu);
        log_error("Memory allocation failed");
        pthread_mutex_unlock(&pdu_lock);
        return -1;
    }
    memcpy(new_pdu->payload, payload, payload_size);
    new_pdu->payload_size = payload_size;

    pdus[pdu_count++] = new_pdu;
    pthread_mutex_unlock(&pdu_lock);
    return 0;
}

void compactPDUs() {
    pthread_mutex_lock(&pdu_lock);
    int valid_index = 0;
    for (int i = 0; i < pdu_count; i++) {
        if (pdus[i]->payload_size <= MAX_PAYLOAD_SIZE) {
            pdus[valid_index++] = pdus[i];
        } else {
            free(pdus[i]->payload);
            free(pdus[i]);
        }
    }
    for (; valid_index < pdu_count; valid_index++) {
        free(pdus[valid_index]->payload);
        free(pdus[valid_index]);
    }
    pdu_count = valid_index;
    pthread_mutex_unlock(&pdu_lock);
}

void iteratePDUs(void (*operation)(MAC_PDU *)) {
    pthread_mutex_lock(&pdu_lock);
    for (int i = 0; i < pdu_count; i++) {
        operation(pdus[i]);
    }
    pthread_mutex_unlock(&pdu_lock);
}

void cleanupPDUs() {
    pthread_mutex_lock(&pdu_lock);
    for (int i = 0; i < pdu_count; i++) {
        free(pdus[i]->payload);
        free(pdus[i]);
    }
    pdu_count = 0;
    pthread_mutex_unlock(&pdu_lock);
}
