void allocate_memory(int max_records, int max_structs) {
    if (max_records > MAX_RECORDS || max_structs > MAX_STRUCTS) {
        fprintf(stderr, "Memory limit exceeded.\n");
        exit(1);
    }
    records = (record*)malloc(max_records * sizeof(record));
    structs = (data_struct*)malloc(max_structs * sizeof(data_struct));
    if (!records || !structs) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(1);
    }
}

void free_memory() {
    free(records);
    records = NULL;
    free(structs);
    structs = NULL;
    num_records = 0;
    num_structs = 0;
    total_memory_used = 0;
}

double calculate_average(double* values, int count) {
    double sum = 0.0;
    for (int i = 0; i < count; i++) {
        sum += values[i];
    }
    return sum / count;
}

void print_average() {
    if (num_structs == 0) {
        printf("No data to average.\n");
        return;
    }
    double average = calculate_average(structs->value, num_structs);
    printf("Average value: %f\n", average);
}

int main() {
    allocate_memory(5000000, 1000000);

    // Populate records and structs
    for (int i = 0; i < 5000000; i++) {
        records[i].key = i;
        records[i].offset = i * 1000;
        structs[i].value = (double)i / 100.0;
        snprintf(structs[i].identifier, sizeof(structs[i].identifier), "Struct%d", i);
    }

    print_average();

    free_memory();
    return 0;
}
