int allocationFailures = 0;

NFAPI_CRC_INDICATION_PDU_T* manageArray(int N, int initialSize) {
    static NFAPI_CRC_INDICATION_PDU_T* array = NULL;
    static int currentSize = 0;

    if (array == NULL || currentSize < N) {
        allocationAttempts++;
        int newSize = (currentSize > 0) ? currentSize * GROWTH_FACTOR : initialSize;
        if (newSize > MAX_ELEMENTS) {
            printf("Error: Maximum elements limit reached.\n");
            return array;
        }

        NFAPI_CRC_INDICATION_PDU_T* newArray = realloc(array, newSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (newArray == NULL) {
            allocationFailures++;
            printf("Memory allocation failed. Attempts: %d, Failures: %d\n", allocationAttempts, allocationFailures);
            return array;
        }

        array = newArray;
        currentSize = newSize;

        for (int i = currentSize - 1; i < N; i++) {
            array[i].RX_UE_INFORMATION_TAG = rand() % 1000;
            array[i].RNTI = rand() % 1000;
            array[i].CRC_INDICATION_REL8_TAG = rand() % 1000;
            array[i].CRCFLAG = rand() % 2;
        }
    }

    return array;
}

int main() {
    srand(time(NULL));

    int N = 500000;
    int initialSize = 1000;

    NFAPI_CRC_INDICATION_PDU_T* array = manageArray(N, initialSize);

    if (array != NULL) {
