#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PAYLOAD_SIZE 1024
#define HEADER_ALIGNMENT 4
#define PAYLOAD_ALIGNMENT 8
#define MAX_INTS 100

typedef struct {
    uint32_t checksum;
    uint16_t length;
} L2Header;

typedef struct {
    L2Header header;
    char *payload;
} MAC_PDU;

void* aligned_malloc(size_t size, size_t alignment) {
    void *ptr = malloc(size + alignment);
    if (!ptr) return NULL;
    void *aligned_ptr = (void*)(((uintptr_t)ptr + alignment - 1) & ~(alignment - 1));
    ((void**)aligned_ptr)[-1] = ptr;
    return aligned_ptr;
}

void aligned_free(void *ptr) {
    free(((void**)ptr)[-1]);
}

MAC_PDU* initialize_and_process_pdu_array() {
    MAC_PDU *array = NULL;
    size_t array_size = 0;
    size_t capacity = 10;

    while (1) {
        int value;
        if (scanf("%d", &value) != 1) break;

        if (array_size >= capacity) {
            capacity *= 2;
            array = realloc(array, capacity * sizeof(MAC_PDU));
            if (!array) {
                fprintf(stderr, "Memory allocation failed\n");
                exit(1);
            }
        }

        MAC_PDU pdu;
        L2Header header;
        header.checksum = value; // Simplified checksum for demonstration
        header.length = sizeof(L2Header) + sizeof(value);

        if (header.length > MAX_PAYLOAD_SIZE) {
            fprintf(stderr, "Payload size exceeds maximum limit\n");
            continue;
        }

        pdu.header = header;
        pdu.payload = aligned_malloc(header.length - sizeof(L2Header), PAYLOAD_ALIGNMENT);
        if (!pdu.payload) {
            fprintf(stderr, "Memory allocation failed for payload\n");
            exit(1);
        }
        memcpy(pdu.payload, &value, sizeof(value));

        array[array_size++] = pdu;
    }

    return array;
}

void print_largest_integer(int *array, size_t size) {
    if (size == 0) {
        printf("Array is empty\n");
        return;
    }

    int largest = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }

    printf("Largest integer: %d\n", largest);
}

void free_pdu_array(MAC_PDU *array, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        aligned_free(array[i].payload);
    }
    free(array);
}

int main() {
    MAC_PDU *pdu_array = initialize_and_process_pdu_array();
    int ints[MAX_INTS];
    size_t num_ints = 0;

    while (1) {
        if (num_ints >= MAX_INTS) {
            fprintf(stderr, "Too many integers\n");
            break;
        }

        int value;
        if (scanf("%d", &value) != 1) break;

        ints[num_ints++] = value;
    }

    print_largest_integer(ints, num_ints);
    free_pdu_array(pdu_array, num_ints);

    return 0;
}
