#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define N 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} RX_UE_INFORMATION;

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8;

typedef struct {
    RX_UE_INFORMATION rx_ue_info;
    CRC_INDICATION_REL8 crc_ind_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* create_and_populate_list(void* arg) {
    int threshold = *(int*)arg;
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        perror("Failed to allocate memory");
        return NULL;
    }

    for (int i = 0; i < N; i++) {
        pthread_mutex_lock(&mutex);
        list[i].rx_ue_info.RX_UE_INFORMATION_TAG = rand() % 1000;
        list[i].rx_ue_info.RNTI = rand() % 1000;
        list[i].crc_ind_rel8.CRCFLAG = rand() % 2;
        pthread_mutex_unlock(&mutex);

        if (list[i].crc_ind_rel8.CRCFLAG != threshold) {
            memmove(&list[i], &list[i + 1], (N - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            N--;
            i--;
        }
    }

    return list;
}

void serialize_list(NFAPI_CRC_INDICATION_PDU_T* list, int size, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    fwrite(&size, sizeof(int), 1, file);
    fwrite(list, sizeof(NFAPI_CRC_INDICATION_PDU_T), size, file);

    fclose(file);
}

NFAPI_CRC_INDICATION_PDU_T* deserialize_list(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return NULL;
    }

    int size;
    fread(&size, sizeof(int), 1, file);

    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        perror("Failed to allocate memory");
        fclose(file);
        return NULL;
    }

    fread(list, sizeof(NFAPI_CRC_INDICATION_PDU_T), size, file);

    fclose(file);
    return list;
}

int main() {
