#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Packet {
    int header;
    int payload_length;
    char *payload;
    struct Packet *next;
} Packet;

typedef struct PacketManager {
    Packet *head;
    pthread_mutex_t lock;
    FILE *log_file;
} PacketManager;

Packet* create_packet(int header, int payload_length) {
    Packet *packet = (Packet*)malloc(sizeof(Packet));
    if (packet == NULL) return NULL;
    packet->header = header;
    packet->payload_length = payload_length;
    packet->payload = (char*)malloc(payload_length);
    if (packet->payload == NULL) {
        free(packet);
        return NULL;
    }
    // Initialize payload
    for (int i = 0; i < payload_length; i++) {
        packet->payload[i] = 'A' + (i % 26);
    }
    packet->next = NULL;
    return packet;
}

void add_packet(PacketManager *manager, Packet *packet) {
    pthread_mutex_lock(&manager->lock);
    if (manager->head == NULL) {
        manager->head = packet;
    } else {
        Packet *current = manager->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = packet;
    }
    pthread_mutex_unlock(&manager->lock);
    fprintf(manager->log_file, "Packet added: Header=%d, Payload Length=%d\n", packet->header, packet->payload_length);
}

void remove_packet(PacketManager *manager, int header) {
    pthread_mutex_lock(&manager->lock);
    Packet *current = manager->head;
    Packet *prev = NULL;
    while (current != NULL) {
        if (current->header == header) {
            if (prev == NULL) {
                manager->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current->payload);
            free(current);
            fprintf(manager->log_file, "Packet removed: Header=%d\n", header);
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
}

void batch_add_packets(PacketManager *manager, Packet **packets, int count) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < count; i++) {
        if (manager->head == NULL) {
            manager->head = packets[i];
        } else {
            Packet *current = manager->head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = packets[i];
        }
    }
    pthread_mutex_unlock(&manager->lock);
    for (int i = 0; i < count; i++) {
        fprintf(manager->log_file, "Packet added: Header=%d, Payload Length=%d\n", packets[i]->header, packets[i]->payload_length);
    }
}

void initialize_manager(PacketManager *manager) {
    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    manager->log_file = fopen("packet_log.txt", "w");
}

void cleanup_manager(PacketManager *manager) {
    Packet *current = manager->head;
    while (current != NULL) {
        Packet *next = current->next;
        free(current->payload);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&manager->lock);
    fclose(manager->log_file);
}
