#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>

#define NFAPI_CRC_INDICATION_PDU_T struct { int tag; int rnti; }

typedef struct {
    long timestamp;
    int key;
    double value;
    char label[256];
} record;

typedef struct {
    long offset;
    int key;
    record *record_ptr;
    void *metadata;
} data_entry;

typedef struct {
    data_entry **entries;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} dynamic_pool;

void init_dynamic_pool(dynamic_pool *pool, size_t initial_capacity) {
    pool->entries = (data_entry **)malloc(initial_capacity * sizeof(data_entry *));
    memset(pool->entries, 0, initial_capacity * sizeof(data_entry *));
    pool->capacity = initial_capacity;
    pool->size = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

void destroy_dynamic_pool(dynamic_pool *pool) {
    for (size_t i = 0; i < pool->size; ++i) {
        free(pool->entries[i]);
    }
    free(pool->entries);
    pthread_mutex_destroy(&pool->lock);
}

data_entry* allocate_data_entry(dynamic_pool *pool, long offset, int key, record *record_ptr, void *metadata) {
    pthread_mutex_lock(&pool->lock);
    if (pool->size == pool->capacity) {
        size_t new_capacity = pool->capacity ? pool->capacity * 2 : 1;
        data_entry **new_entries = (data_entry **)realloc(pool->entries, new_capacity * sizeof(data_entry *));
        if (!new_entries) {
            pthread_mutex_unlock(&pool->lock);
            return NULL; // Memory allocation failed
        }
        pool->entries = new_entries;
        pool->capacity = new_capacity;
    }
    data_entry *entry = (data_entry *)malloc(sizeof(data_entry));
    entry->offset = offset;
    entry->key = key;
    entry->record_ptr = record_ptr;
    entry->metadata = metadata;
    pool->entries[pool->size++] = entry;
    pthread_mutex_unlock(&pool->lock);
    return entry;
}

void deallocate_data_entry(dynamic_pool *pool, data_entry *entry) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->size; ++i) {
        if (pool->entries[i] == entry) {
            free(entry);
            memmove(pool->entries + i, pool->entries + i + 1, (pool->size - i - 1) * sizeof(data_entry *));
            --pool->size;
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

// Additional functions for managing records and metadata can be implemented here
