#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_FRAMES 100000

typedef struct {
    RX_FRAME_INFO_TAG tag;
    uint16_t RNTI;
    float phy_metrics;
} NFAPI_RX_FRAME_T;

typedef struct {
    NFAPI_RX_FRAME_T *frames;
    size_t count;
    pthread_mutex_t lock;
} FrameCollection;

FrameCollection* create_frame_collection() {
    FrameCollection *collection = (FrameCollection*)malloc(sizeof(FrameCollection));
    if (!collection) return NULL;

    collection->frames = (NFAPI_RX_FRAME_T*)calloc(MAX_FRAMES, sizeof(NFAPI_RX_FRAME_T));
    if (!collection->frames) {
        free(collection);
        return NULL;
    }

    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void destroy_frame_collection(FrameCollection *collection) {
    if (collection) {
        pthread_mutex_destroy(&collection->lock);
        free(collection->frames);
        free(collection);
    }
}

int add_frame_to_collection(FrameCollection *collection, NFAPI_RX_FRAME_T frame, float snr_threshold) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count >= MAX_FRAMES || frame.phy_metrics < snr_threshold) {
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    collection->frames[collection->count++] = frame;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

int serialize_frame_collection(FrameCollection *collection, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    fwrite(&collection->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < collection->count; ++i) {
        fwrite(&collection->frames[i], sizeof(NFAPI_RX_FRAME_T), 1, file);
    }

    fclose(file);
    return 0;
}

int deserialize_frame_collection(FrameCollection *collection, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);
    if (count > MAX_FRAMES) {
        fclose(file);
        return -1;
    }

    pthread_mutex_lock(&collection->lock);

    collection->count = count;
    for (size_t i = 0; i < count; ++i) {
        fread(&collection->frames[i], sizeof(NFAPI_RX_FRAME_T), 1, file);
    }

    pthread_mutex_unlock(&collection->lock);

    fclose(file);
    return 0;
}
