void initialize_components(int num_records, int threshold) {
    // Validate user input
    if (num_records <= 0 || num_records > MAX_LIMIT) {
        fprintf(stderr, "Invalid number of records.\n");
        return;
    }

    // Allocate memory for offsets array
    offsets = (long*)malloc(num_records * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets.\n");
        return;
    }

    // Allocate memory for keys array
    keys = (int*)malloc(num_records * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Memory allocation failed for keys.\n");
        free(offsets);
        return;
    }

    // Initialize records and tracking sums arrays
    records = (record*)malloc(num_records * sizeof(record));
    tracking_sums = (int*)calloc(num_records, sizeof(int));
    if (!records || !tracking_sums) {
        fprintf(stderr, "Memory allocation failed for records or tracking sums.\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize records with random numbers and update tracking sums
    srand(time(NULL));
    for (int i = 0; i < num_records; ++i) {
        records[i].value = rand() % threshold;
        if (i > 0) {
            tracking_sums[i] = tracking_sums[i - 1] + records[i].value;
        }
    }

    // Print records in reverse order if tracking sum exceeds threshold
    for (int i = num_records - 1; i >= 0; --i) {
        if (tracking_sums[i] > threshold) {
            printf("Record %d: %d\n", i, records[i].value);
        }
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
    free(tracking_sums);
}

int main() {
    int num_records;
    int threshold;

    printf("Enter the number of records: ");
    scanf("%d", &num_records);

    printf("Enter the threshold for tracking sum: ");
    scanf("%d", &threshold);

    initialize_components(num_records, threshold);

    return 0;
}
