typedef struct {
    int id;
    time_t timestamp;
    float* values;
} DataBlock;

DataBlock** create_data_blocks(int num_blocks, size_t array_size) {
    DataBlock** blocks = (DataBlock**)malloc(num_blocks * sizeof(DataBlock*));
    if (!blocks) return NULL;

    for (int i = 0; i < num_blocks; ++i) {
        blocks[i] = (DataBlock*)malloc(sizeof(DataBlock));
        if (!blocks[i]) {
            // Free previously allocated memory on failure
            for (int j = 0; j < i; ++j) free(blocks[j]);
            free(blocks);
            return NULL;
        }
        blocks[i]->id = i + 1;
        blocks[i]->timestamp = time(NULL);
        blocks[i]->values = (float*)malloc(array_size * sizeof(float));
        if (!blocks[i]->values) {
            // Free previously allocated memory on failure
            for (int j = 0; j <= i; ++j) {
                free(blocks[j]->values);
                free(blocks[j]);
            }
            free(blocks);
            return NULL;
        }
    }

    return blocks;
}

void populate_with_random_values(DataBlock** blocks, int num_blocks, size_t array_size, float min_val, float max_val) {
    srand(time(NULL));
    for (int i = 0; i < num_blocks; ++i) {
        for (size_t j = 0; j < array_size; ++j) {
            blocks[i]->values[j] = min_val + ((float)rand() / RAND_MAX) * (max_val - min_val);
        }
    }
}

void destroy_data_blocks(DataBlock** blocks, int num_blocks) {
    for (int i = 0; i < num_blocks; ++i) {
        free(blocks[i]->values);
        free(blocks[i]);
    }
    free(blocks);
}

// Example usage
int main() {
    int num_blocks = 5;
    size_t array_size = 100;
    float min_val = -1.0f, max_val = 1.0f;

    DataBlock** blocks = create_data_blocks(num_blocks, array_size);
    if (blocks) {
        populate_with_random_values(blocks, num_blocks, array_size, min_val, max_val);

        // Use the data blocks...

        destroy_data_blocks(blocks, num_blocks);
    }

    return 0;
}
