        fprintf(stderr, "Invalid size. Must be between 1 and %d.\n", MAX_LIMIT);
        return -1;
    }
    return 0;
}

void initialize_arrays(int offsets_size, int keys_size, record *records, int tracking_size, int threshold) {
    long *offsets = (long *)malloc(offsets_size * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Failed to allocate memory for offsets.\n");
        return;
    }

    int *keys = (int *)aligned_alloc(64, keys_size * sizeof(int)); // Align for hardware optimization
    if (!keys) {
        fprintf(stderr, "Failed to allocate aligned memory for keys.\n");
        free(offsets);
        return;
    }

    srand(time(NULL));
    for (int i = 0; i < records_size; ++i) {
        records[i].value = rand() % threshold + 1;
    }

    int *tracking = (int *)calloc(tracking_size, sizeof(int));
    if (!tracking) {
        fprintf(stderr, "Failed to allocate memory for tracking.\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize tracking array
    for (int i = 0; i < records_size; ++i) {
        tracking[i] += records[i].value;
    }

    // Iterate and print in reverse order if tracking sum exceeds threshold
    for (int i = records_size - 1; i >= 0; --i) {
        if (tracking[i] > threshold) {
            printf("Record %d: %d\n", i, records[i].value);
        }
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(tracking);
}

int main() {
    int offsets_size, keys_size, records_size, tracking_size, threshold;

    printf("Enter size for offsets array: ");
    scanf("%d", &offsets_size);

    printf("Enter size for keys array: ");
    scanf("%d", &keys_size);

    printf("Enter number of records: ");
    scanf("%d", &records_size);

    printf("Enter tracking array size: ");
    scanf("%d", &tracking_size);

    printf("Enter threshold value: ");
    scanf("%d", &threshold);

    if (validate_size(offsets_size) != 0 || validate_size(keys_size) != 0 ||
        validate_size(records_size) != 0 || validate_size(tracking_size) != 0) {
        return 1;
    }

    record *records = (record *)malloc(records_size * sizeof(record));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records.\n");
        return 1;
    }

    initialize_arrays(offsets_size, keys_size, records, tracking_size, threshold);

    free(records);
    return 0;
}
