} dynamicCollection;

dynamicCollection* createDynamicCollection(size_t initialCapacity, size_t maxAge, size_t maxMemoryUsage) {
    dynamicCollection* collection = (dynamicCollection*)malloc(sizeof(dynamicCollection));
    if (!collection) {
        perror("Failed to allocate memory for dynamic collection");
        exit(EXIT_FAILURE);
    }
    collection->entries = (dataEntry*)calloc(initialCapacity, sizeof(dataEntry));
    if (!collection->entries) {
        perror("Failed to allocate memory for entries");
        free(collection);
        exit(EXIT_FAILURE);
    }
    collection->capacity = initialCapacity;
    collection->length = 0;
    collection->maxAge = maxAge;
    collection->maxMemoryUsage = maxMemoryUsage;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void destroyDynamicCollection(dynamicCollection* collection) {
    free(collection->entries);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

void addEntry(dynamicCollection* collection, double value, const char* string) {
    pthread_mutex_lock(&collection->lock);
    if (collection->length >= collection->capacity) {
        // Resize logic here
    }
    dataEntry newEntry = {value, string, time(NULL)};
    collection->entries[collection->length++] = newEntry;
    pthread_mutex_unlock(&collection->lock);
}

void cleanupExpiredEntries(dynamicCollection* collection) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->length; ) {
        if (time(NULL) - collection->entries[i].lastAccessed > collection->maxAge) {
            // Remove expired entry logic here
            i--;
        }
        i++;
    }
    pthread_mutex_unlock(&collection->lock);
}

void* backgroundCleanup(void* arg) {
    dynamicCollection* collection = (dynamicCollection*)arg;
    while (1) {
        cleanupExpiredEntries(collection);
        sleep(60); // Cleanup every minute
    }
    return NULL;
}

int main() {
    dynamicCollection* collection = createDynamicCollection(10, 3600, 1024 * 1024 * 10); // Example parameters

    pthread_t cleanupThread;
    pthread_create(&cleanupThread, NULL, backgroundCleanup, collection);

    // Add entries and perform other operations here

    pthread_join(cleanupThread, NULL);
    destroyDynamicCollection(collection);

    return 0;
}
