#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct task {
    int id;
    int priority;
    time_t due_date;
    char status[20];
    struct task *next;
} Task;

typedef struct {
    Task **tasks;
    size_t capacity;
    size_t size;
} TaskList;

Task* create_task(int priority, time_t due_date) {
    Task *new_task = (Task*)malloc(sizeof(Task));
    new_task->id = rand(); // Auto-generate task ID
    new_task->priority = priority;
    new_task->due_date = due_date;
    strcpy(new_task->status, "active");
    new_task->next = NULL;
    return new_task;
}

void add_task(TaskList *list, Task *task) {
    if (list->size >= list->capacity) {
        list->capacity *= 2;
        list->tasks = (Task**)realloc(list->tasks, list->capacity * sizeof(Task*));
    }
    list->tasks[list->size++] = task;
}

void update_task(TaskList *list, int id, char *new_status) {
    for (size_t i = 0; i < list->size; ++i) {
        if (list->tasks[i]->id == id) {
            strcpy(list->tasks[i]->status, new_status);
            break;
        }
    }
}

void remove_task(TaskList *list, int id) {
    for (size_t i = 0; i < list->size; ++i) {
        if (list->tasks[i]->id == id) {
            free(list->tasks[i]);
            for (size_t j = i; j < list->size - 1; ++j) {
                list->tasks[j] = list->tasks[j + 1];
            }
            --list->size;
            break;
        }
    }
}

void check_task_expiration(TaskList *list) {
    time_t now = time(NULL);
    for (size_t i = 0; i < list->size; ++i) {
        if (list->tasks[i]->due_date <= now && strcmp(list->tasks[i]->status, "active") == 0) {
            strcpy(list->tasks[i]->status, "inactive");
        }
    }
}

void free_task_list(TaskList *list) {
    for (size_t i = 0; i < list->size; ++i) {
        free(list->tasks[i]);
    }
    free(list->tasks);
    free(list);
}
