MAC_PDU* initialize_mac_pdu_array(size_t num_pdus, size_t max_payload_length, const unsigned char *user_data, size_t user_data_len, int network_interface) {
    if (num_pdus == 0 || max_payload_length > MAX_PAYLOAD_LENGTH || user_data_len > max_payload_length) {
        return NULL;
    }

    MAC_PDU *pdus = (MAC_PDU *)malloc(num_pdus * sizeof(MAC_PDU));
    if (!pdus) {
        return NULL;
    }

    for (size_t i = 0; i < num_pdus; ++i) {
        pdus[i].payload_length = user_data_len > max_payload_length ? max_payload_length : user_data_len;
        pdus[i].payload = (unsigned char *)malloc(pdus[i].payload_length);
        if (!pdus[i].payload) {
            // Handle memory allocation failure
            for (size_t j = 0; j < i; ++j) {
                free(pdus[j].payload);
            }
            free(pdus);
            return NULL;
        }

        memcpy(pdus[i].payload, user_data, pdus[i].payload_length);

        // Initialize L2Header
