#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define INITIAL_SIZE 10
#define GROWTH_FACTOR 2

typedef struct {
    int value;
    unsigned char flag;
    size_t index;
} Record;

typedef struct {
    long* offsets;
    int* keys;
    Record** records;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    Record** cache;
    size_t cache_size;
} DataStructures;

DataStructures* create_data_structures() {
    DataStructures* ds = (DataStructures*)malloc(sizeof(DataStructures));
    ds->offsets = (long*)malloc(INITIAL_SIZE * sizeof(long));
    ds->keys = (int*)malloc(INITIAL_SIZE * sizeof(int));
    ds->records = (Record**)malloc(INITIAL_SIZE * sizeof(Record*));
    ds->count = 0;
    ds->capacity = INITIAL_SIZE;
    pthread_mutex_init(&ds->lock, NULL);
    ds->cache = (Record**)malloc(INITIAL_SIZE * sizeof(Record*));
    ds->cache_size = 0;
    return ds;
}

void destroy_data_structures(DataStructures* ds) {
    for (size_t i = 0; i < ds->count; ++i) {
        free(ds->records[i]);
    }
    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    pthread_mutex_destroy(&ds->lock);
    free(ds->cache);
    free(ds);
}

void add_record(DataStructures* ds, int key, long offset) {
    if (ds->count >= ds->capacity) {
        ds->offsets = realloc(ds->offsets, ds->capacity * GROWTH_FACTOR * sizeof(long));
        ds->keys = realloc(ds->keys, ds->capacity * GROWTH_FACTOR * sizeof(int));
        ds->records = realloc(ds->records, ds->capacity * GROWTH_FACTOR * sizeof(Record*));
        ds->capacity *= GROWTH_FACTOR;
    }
    Record* record = (Record*)malloc(sizeof(Record));
    record->value = key;
    record->flag = 0;
    record->index = ds->count;
    ds->records[ds->count] = record;
    ds->keys[ds->count] = key;
    ds->offsets[ds->count] = offset;
    ++ds->count;
}

void reset_records(DataStructures* ds, int min_value, int max_value) {
    pthread_mutex_lock(&ds->lock);
    for (size_t i = 0; i < ds->count; ++i) {
        if (ds->records[i]->flag) {
            ds->records[i]->value = rand() % (max_value - min_value + 1) + min_value;
        }
    }
    pthread_mutex_unlock(&ds->lock);
}

void serialize_data_structures(DataStructures* ds, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    fwrite(ds->offsets, sizeof(long), ds->count, file);
    fwrite(ds->keys, sizeof(int), ds->count, file);
    for (size_t i = 0; i < ds->count; ++i) {
        fwrite(&ds->records[i]->value, sizeof(int), 1, file);
        fwrite(&ds->records[i]->flag, sizeof(unsigned char), 1, file);
        fwrite(&ds->records[i]->index, sizeof(size_t), 1, file);
    }
    fclose(file);
}

void deserialize_data_structures(DataStructures* ds, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return;

    free(ds->offsets);
    free(ds->keys);
    for (size_t i = 0; i < ds->count; ++i) {
        free(ds->records[i]);
    }
    free(ds->records);

    fread(&ds->count, sizeof(size_t), 1, file);
    ds->capacity = ds->count;
    ds->offsets = (long*)malloc(ds->capacity * sizeof(long));
    ds->keys = (int*)malloc(ds->capacity * sizeof(int));
    ds->records = (Record**)malloc(ds->capacity * sizeof(Record*));

    fread(ds->offsets, sizeof(long), ds->count, file);
    fread(ds->keys, sizeof(int), ds->count, file);
    for (size_t i = 0; i < ds->count; ++i) {
        Record* record = (Record*)malloc(sizeof(Record));
        fread(&record->value, sizeof(int), 1, file);
        fread(&record->flag, sizeof(unsigned char), 1, file);
        fread(&record->index, sizeof(size_t), 1, file);
        ds->records[i] = record;
    }
    fclose(file);
}
