#define MAX_RECORDS 1000

typedef struct {
    long *offset;
    int key;
    int ref_counter;
} record;

record records[MAX_RECORDS];

void initialize_memory() {
    srand(time(NULL));
    for (int i = 0; i < MAX_RECORDS; i++) {
        records[i].offset = malloc(sizeof(long));
        if (!records[i].offset) {
            // Handle memory allocation failure
            exit(1);
        }
        *records[i].offset = i * sizeof(long); // Efficient space utilization
        records[i].key = rand() % 1000; // Unique random values within range
        records[i].ref_counter = 0;
    }
}

void update_reference_counters(int start, int end) {
    for (int i = start; i <= end && i < MAX_RECORDS; i++) {
        if (records[i].offset) {
            records[i].ref_counter++;
            // Ensure thread safety and prevent overflow/underflow
            if (records[i].ref_counter > INT_MAX - 1) {
                records[i].ref_counter = INT_MAX;
            } else if (records[i].ref_counter < 0) {
                records[i].ref_counter = 0;
            }
        }
    }
}

void free_memory() {
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (records[i].offset) {
            free(records[i].offset);
            records[i].offset = NULL;
        }
    }
}
