#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_DOUBLE_SIZE 1000000
#define MIN_STRING_LENGTH 5
#define MAX_STRING_LENGTH 20

typedef struct {
    double *value;
    char *str;
    int status;
} data_point;

double* allocate_and_initialize_doubles(int size) {
    double *array = (double*)malloc(size * sizeof(double));
    if (!array) return NULL;
    for (int i = 0; i < size; ++i) {
        array[i] = exp(i);
    }
    return array;
}

char** allocate_and_initialize_strings(int size, int min_length, int max_length) {
    char **array = (char**)malloc(size * sizeof(char*));
    if (!array) return NULL;

    srand(time(NULL));
    for (int i = 0; i < size; ++i) {
        int length = rand() % (max_length - min_length + 1) + min_length;
        array[i] = (char*)malloc((length + 1) * sizeof(char));
        if (!array[i]) {
            // Handle memory allocation failure
            for (int j = 0; j < i; ++j) free(array[j]);
            free(array);
            return NULL;
        }
        for (int j = 0; j < length; ++j) {
            array[i][j] = 'A' + rand() % 62; // Alphanumeric characters
        }
        array[i][length] = '\0';
    }

    // Validate uniqueness
    for (int i = 0; i < size; ++i) {
        for (int j = i + 1; j < size; ++j) {
            if (strcmp(array[i], array[j]) == 0) {
                // Handle duplicate string
                for (int k = 0; k <= i; ++k) free(array[k]);
                free(array);
                return NULL;
            }
        }
    }

    return array;
}

data_point* create_data_points(double *doubles, char **strings, int size) {
    data_point *points = (data_point*)malloc(size * sizeof(data_point));
    if (!points) return NULL;

    for (int i = 0; i < size; ++i) {
        points[i].value = &doubles[i];
        points[i].str = strings[i];
        points[i].status = 0;
    }

    return points;
}

double compute_weighted_average(data_point *point, int string_length) {
    // Implement numerical stability and precision handling
    return (*point->value) / (string_length + 1);
}

void sort_data_points(data_point *points, int size) {
    // Implement a robust sorting algorithm considering performance constraints
    qsort(points, size, sizeof(data_point), [](const void *a, const void *b) {
        data_point *pa = (data_point*)a;
        data_point *pb = (data_point*)b;
        double diff = compute_weighted_average(pa, strlen(pa->str)) - 
                      compute_weighted_average(pb, strlen(pb->str));
        return (diff > 0) ? -1 : ((diff < 0) ? 1 : 0);
    });
}

void free_memory(double *doubles, char **strings, data_point *points, int size) {
    for (int i = 0; i < size; ++i) {
        free(strings[i]);
    }
    free(doubles);
    free(points);
}

int main() {
    int size = 100;
    double *doubles = allocate_and_initialize_doubles(size);
    char **strings = allocate_and_initialize_strings(size, MIN_STRING_LENGTH, MAX_STRING_LENGTH);
    data_point *points = create_data_points(doubles, strings, size);

    if (doubles && strings && points) {
        sort_data_points(points, size);

        for (int i = 0; i < size; ++i) {
            printf("Value: %f, String: %s, Weighted Average: %f\n",
                   *points[i].value, points[i].str, compute_weighted_average(&points[i], strlen(points[i].str)));
        }

        free_memory(doubles, strings, points, size);
    } else {
        printf("Memory allocation failed.\n");
    }

    return 0;
}
