    private string _apiEndpoint;
    private int _cacheTimeout;
    private DateTime _lastCacheUpdate;

    public ConfigurationManager(string xmlFilePath, string apiEndpoint, int cacheTimeout)
    {
        _xmlFilePath = xmlFilePath;
        _apiEndpoint = apiEndpoint;
        _cacheTimeout = cacheTimeout;
        _httpClient = new HttpClient();
    }

    public async Task LoadConfigurationsAsync()
    {
        try
        {
            if (DateTime.Now - _lastCacheUpdate > TimeSpan.FromSeconds(_cacheTimeout))
            {
                await UpdateFromXmlFileAsync();
                await UpdateFromApiEndpointAsync();
                _lastCacheUpdate = DateTime.Now;
            }
        }
        catch (Exception ex)
        {
            // Log error and handle fallback mechanism
        }
    }

    private async Task UpdateFromXmlFileAsync()
    {
        try
        {
            var xmlContent = File.ReadAllText(_xmlFilePath);
            // Parse XML content and update configurations dictionary
        }
        catch (Exception ex)
        {
            // Log error and handle fallback mechanism
        }
    }

    private async Task UpdateFromApiEndpointAsync()
    {
        try
        {
            HttpResponseMessage response = await _httpClient.GetAsync(_apiEndpoint, HttpCompletionOption.ResponseHeadersRead);
            if (response.IsSuccessStatusCode)
            {
                string apiContent = await response.Content.ReadAsStringAsync();
                // Parse API content and update configurations dictionary
            }
        }
        catch (Exception ex)
        {
            // Log error and handle fallback mechanism
        }
    }

    public string GetConfiguration(string key)
    {
        return _configurations.ContainsKey(key) ? _configurations[key] : null;
    }
}
