#define INITIAL_CAPACITY 10
#define RESIZE_THRESHOLD 80
#define MIN_FLOAT 0.0f
#define MAX_FLOAT 1.0f

typedef struct {
    long* offsets;
    int* keys;
    float* data;
    size_t capacity;
    size_t size;
} DataStruct;

void log_event(const char* message) {
    // Placeholder for logging function
