}

DataStruct* create_data_struct() {
    DataStruct* ds = (DataStruct*)malloc(sizeof(DataStruct));
    if (!ds) return NULL;
    ds->offsets = (long*)malloc(INITIAL_CAPACITY * sizeof(long));
    ds->keys = (int*)malloc(INITIAL_CAPACITY * sizeof(int));
    ds->data = (float*)malloc(INITIAL_CAPACITY * sizeof(float));
    ds->capacity = INITIAL_CAPACITY;
    ds->size = 0;
    if (!ds->offsets || !ds->keys || !ds->data) {
        free(ds);
        return NULL;
    }
    srand(time(NULL));
    for (size_t i = 0; i < ds->capacity; ++i) {
        ds->data[i] = MIN_FLOAT + (float)(rand()) / RAND_MAX * (MAX_FLOAT - MIN_FLOAT);
    }
    return ds;
}

void resize_data_struct(DataStruct* ds, size_t new_capacity) {
    if (!ds || new_capacity <= ds->capacity) return;

    long* new_offsets = (long*)realloc(ds->offsets, new_capacity * sizeof(long));
    int* new_keys = (int*)realloc(ds->keys, new_capacity * sizeof(int));
    float* new_data = (float*)realloc(ds->data, new_capacity * sizeof(float));

    if (!new_offsets || !new_keys || !new_data) {
        log_event("Memory allocation failed during resize");
        return;
    }

    ds->offsets = new_offsets;
    ds->keys = new_keys;
    ds->data = new_data;
    ds->capacity = new_capacity;

    for (size_t i = ds->size; i < ds->capacity; ++i) {
        ds->data[i] = MIN_FLOAT + (float)(rand()) / RAND_MAX * (MAX_FLOAT - MIN_FLOAT);
    }

    log_event("Data structure resized to capacity: %zu", new_capacity);
}

void add_data(DataStruct* ds, long offset, int key, float data_value) {
    if (!ds || ds->size >= ds->capacity) return;

    ds->offsets[ds->size] = offset;
    ds->keys[ds->size] = key;
    ds->data[ds->size++] = data_value;

    if (ds->size * 100 / ds->capacity > RESIZE_THRESHOLD) {
        resize_data_struct(ds, ds->capacity * 2);
    }
}

void validate_data(DataStruct* ds) {
    if (!ds) return;

    for (size_t i = 0; i < ds->size; ++i) {
        if (ds->data[i] < MIN_FLOAT || ds->data[i] > MAX_FLOAT) {
            log_event("Data validation failed at index: %zu", i);
            break;
        }
    }
}

void free_data_struct(DataStruct* ds) {
    if (!ds) return;

    free(ds->offsets);
    free(ds->keys);
    free(ds->data);
    free(ds);
}
