    char* payload;
    int metadata;
} MAC_PDU;

MAC_PDU* create_pdu(L2Header header, const char* data, int size) {
    MAC_PDU* pdu = (MAC_PDU*)malloc(sizeof(MAC_PDU));
    if (!pdu) return NULL;

    pdu->header = header;
    pdu->payload = (char*)malloc(size);
    if (!pdu->payload) {
        free(pdu);
        return NULL;
    }
    memcpy(pdu->payload, data, size);
    pdu->metadata = calculate_metadata(header, data, size);

    return pdu;
}

void process_pdus(MAC_PDU** pdus, int count) {
    for (int i = 0; i < count; ++i) {
        if (validate_pdu(pdus[i])) {
            // Process PDU
            free(pdus[i]->payload);
            free(pdus[i]);
        }
    }
}

int main() {
    L2Header header;
    const char* data = "example_data";
    int size = strlen(data);

    MAC_PDU* pdu = create_pdu(header, data, size);
    if (pdu) {
        process_pdus(&pdu, 1);
    }

    return 0;
}
