            for (size_t j = 0; j < i; ++j) free(library->records[j]);
            free(library->offsets);
            free(library->keys);
            free(library->records);
            free(library);
            return NULL;
        }
        library->records[i]->ptr = &library->offsets[i];
        library->records[i]->key = library->keys[i];
        library->records[i]->ref_count = 0;
