#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int priority;
    char *status;
    time_t deadline;
    char *description;
} Project;

Project* create_project(int num_projects) {
    Project *projects = (Project*)malloc(num_projects * sizeof(Project));
    if (!projects) return NULL;

    for (int i = 0; i < num_projects; ++i) {
        projects[i].priority = i + 1;
        projects[i].status = strdup("Pending");
        projects[i].deadline = time(NULL);
        projects[i].description = strdup("Project A");
    }

    return projects;
}

void update_project(Project *project) {
    srand(time(NULL));
    project->status = (rand() % 10 < 7) ? "In Progress" : "Completed";
    time_t now = time(NULL);
    int days_change = rand() % 61 - 30; // Random number between -30 and 30
    project->deadline += days_change * 24 * 60 * 60;
    if (project->deadline < now) {
        project->deadline = now;
    }
}

void add_project(Project **projects, int *num_projects, Project new_project) {
    (*num_projects)++;
    *projects = realloc(*projects, *num_projects * sizeof(Project));
    if (!*projects) return;

    for (int i = *num_projects - 1; i > 0 && (*projects)[i-1].priority > new_project.priority; --i) {
        (*projects)[i] = (*projects)[i-1];
    }
    (*projects)[i] = new_project;
}

int remove_project(Project **projects, int *num_projects, int priority) {
    for (int i = 0; i < *num_projects; ++i) {
        if ((*projects)[i].priority == priority) {
            free((*projects)[i].status);
            free((*projects)[i].description);
            memmove(&(*projects)[i], &(*projects)[i+1], (*num_projects - i - 1) * sizeof(Project));
            (*num_projects)--;
            return 1;
        }
    }
    return 0;
}

void free_projects(Project *projects, int num_projects) {
    for (int i = 0; i < num_projects; ++i) {
        free(projects[i].status);
        free(projects[i].description);
    }
    free(projects);
}
