#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_NAME_LENGTH 256

typedef struct {
    char *name;
    int quantity;
    double price;
} Product;

typedef struct {
    Product **products;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} ProductCollection;

Product* create_product(const char *name, int quantity, double price) {
    Product *product = (Product*)malloc(sizeof(Product));
    product->name = strdup(name);
    product->quantity = quantity;
    product->price = price;
    return product;
}

void destroy_product(Product *product) {
    free(product->name);
    free(product);
}

ProductCollection* create_collection(size_t initial_capacity) {
    ProductCollection *collection = (ProductCollection*)malloc(sizeof(ProductCollection));
    collection->products = (Product**)calloc(initial_capacity, sizeof(Product*));
    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->mutex, NULL);
    return collection;
}

void destroy_collection(ProductCollection *collection) {
    for (size_t i = 0; i < collection->size; ++i) {
        destroy_product(collection->products[i]);
    }
    free(collection->products);
    pthread_mutex_destroy(&collection->mutex);
    free(collection);
}

void resize_collection(ProductCollection *collection, size_t new_capacity) {
    Product** new_products = (Product**)realloc(collection->products, new_capacity * sizeof(Product*));
    if (new_products == NULL) {
        // Handle memory allocation failure
        return;
    }
    collection->products = new_products;
    collection->capacity = new_capacity;
}

void add_product(ProductCollection *collection, const char *name, int quantity, double price) {
    pthread_mutex_lock(&collection->mutex);
    if (collection->size == collection->capacity) {
        resize_collection(collection, collection->capacity * 2);
    }
    collection->products[collection->size++] = create_product(name, quantity, price);
    pthread_mutex_unlock(&collection->mutex);
}

void remove_product(ProductCollection *collection, size_t index) {
    pthread_mutex_lock(&collection->mutex);
    if (index < collection->size) {
        destroy_product(collection->products[index]);
        for (size_t i = index; i < collection->size - 1; ++i) {
            collection->products[i] = collection->products[i + 1];
        }
        --collection->size;
        if (collection->size > 0 && collection->size == collection->capacity / 4) {
            resize_collection(collection, collection->capacity / 2);
        }
    }
    pthread_mutex_unlock(&collection->mutex);
}

void print_collection(ProductCollection *collection) {
    pthread_mutex_lock(&collection->mutex);
    for (size_t i = 0; i < collection->size; ++i) {
        printf("Product %zu: Name=%s, Quantity=%d, Price=%.2f\n", i, collection->products[i]->name, collection->products[i]->quantity, collection->products[i]->price);
    }
    pthread_mutex_unlock(&collection->mutex);
}

int main() {
    srand(time(NULL));
    ProductCollection *collection = create_collection(10);

    add_product(collection, "Product A", rand() % 100 + 1, (double)rand() / RAND_MAX * 100);
    add_product(collection, "Product B", rand() % 100 + 1, (double)rand() / RAND_MAX * 100);

    print_collection(collection);

    remove_product(collection, 0);

    print_collection(collection);

    destroy_collection(collection);

    return 0;
}
