#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <atomic>

#define MAX_USERS 1000000
#define MAX_THREADS 100

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* user_list[MAX_USERS];
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
atomic_int next_user_id(0);

void generate_random_data(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pdu->RX_UE_INFORMATION_TAG = rand() % MAX_USERS + 1;
    pdu->RNTI = rand() % 65536 + 1; // Valid range for RNTI
    pdu->CRC_INDICATION_REL8_TAG = rand() % 2;
    time_t current_time = time(NULL);
    long offset = (rand() % 201) - 100; // Random offset between -100ms and 100ms
    pdu->timestamp = current_time + offset * 1e-3;
}

void* create_user_data(void* arg) {
    int thread_id = *(int*)arg;
    for (int i = 0; i < MAX_USERS / MAX_THREADS; ++i) {
        pthread_mutex_lock(&mutex);
        int user_id = next_user_id.fetch_add(1, std::memory_order_relaxed);
        if (user_id >= MAX_USERS) {
            break;
        }
        user_list[user_id] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        generate_random_data(user_list[user_id]);
        pthread_mutex_unlock(&mutex);
    }
    return NULL;
}

void reset_state() {
    for (int i = 0; i < MAX_USERS; ++i) {
        if (user_list[i]) {
            free(user_list[i]);
            user_list[i] = NULL;
        }
    }
    next_user_id.store(0, std::memory_order_relaxed);
}

void configure_logging(int level) {
    // Configure logging based on the level
}

int main() {
    srand(time(NULL));
    pthread_t threads[MAX_THREADS];
    int thread_ids[MAX_THREADS];

    for (int i = 0; i < MAX_THREADS; ++i) {
        thread_ids[i] = i;
        pthread_create(&threads[i], NULL, create_user_data, &thread_ids[i]);
    }

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    configure_logging(1); // Set logging level

    reset_state();

    return 0;
}
