    if (queue->size == queue->capacity) {
        // Handle capacity overflow
        queue->data = realloc(queue->data, 2 * queue->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        queue->capacity *= 2;
    }
    queue->data[queue->size++] = item;
    pthread_mutex_unlock(&queue->lock);
