typedef struct {
    uint32_t MAC_INSTANCE_ID;
    uint16_t MAC_PDU_TAG;
    uint16_t SECURITY_CONTEXT_TAG;
    uint8_t SECURITY_STATUS;
} MAC_CONTEXT_T;

typedef enum {
    SECURITY_STATUS_ACTIVE,
    SECURITY_STATUS_INACTIVE
} SECURITY_STATUS_T;

typedef struct {
    uint16_t min_pdu_tag;
    uint16_t max_pdu_tag;
    SECURITY_STATUS_T inactive_status;
} POLICY_CONFIG_T;

int populate_mac_contexts(MAC_CONTEXT_T *contexts, size_t num_contexts, POLICY_CONFIG_T policy_config) {
    if (num_contexts > MAX_MAC_CONTEXTS) {
        return -1; // Error: Exceeds maximum number of contexts
    }

    for (size_t i = 0; i < num_contexts; ++i) {
        uint32_t instance_id;
        do {
            instance_id = rand(); // Generate a random MAC_INSTANCE_ID
        } while (instance_id == 0); // Ensure it's not zero

        contexts[i].MAC_INSTANCE_ID = instance_id;
        contexts[i].MAC_PDU_TAG = (rand() % (policy_config.max_pdu_tag - policy_config.min_pdu_tag + 1)) + policy_config.min_pdu_tag;

        if (contexts[i].MAC_PDU_TAG < policy_config.min_pdu_tag || contexts[i].MAC_PDU_TAG > policy_config.max_pdu_tag) {
            return -2; // Error: Invalid MAC_PDU_TAG
        }

        if (contexts[i].MAC_PDU_TAG % 2 == 0) {
            contexts[i].SECURITY_STATUS = policy_config.inactive_status;
        } else {
            contexts[i].SECURITY_STATUS = SECURITY_STATUS_ACTIVE;
        }
    }

    return 0; // Success
}
