    pthread_mutex_destroy(&manager->lock);
}

void add_session(SessionManager *manager, UserSession session) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->capacity) {
        int new_capacity = (int)(manager->capacity * RESIZE_FACTOR);
        manager->sessions = realloc(manager->sessions, new_capacity * sizeof(UserSession));
        manager->capacity = new_capacity;
    }
    manager->sessions[manager->count++] = session;
    pthread_mutex_unlock(&manager->lock);
}

void remove_session(SessionManager *manager, int session_id) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        if (manager->sessions[i].session_id == session_id) {
            free(manager->sessions[i].devices);
            for (int j = i; j < manager->count - 1; j++) {
                manager->sessions[j] = manager->sessions[j + 1];
            }
            manager->count--;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

UserSession *get_session(SessionManager *manager, int session_id) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        if (manager->sessions[i].session_id == session_id) {
            UserSession *session = &manager->sessions[i];
            pthread_mutex_unlock(&manager->lock);
            return session;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

