#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_TASKS 100

typedef struct {
    int taskID;
    int priority;
    void (*callback)();
} Task;

typedef struct {
    Task tasks[MAX_TASKS];
    int front, rear;
    pthread_mutex_t lock;
    pthread_cond_t not_empty, not_full;
} TaskQueue;

void initTaskQueue(TaskQueue *queue) {
    queue->front = queue->rear = -1;
    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->not_empty, NULL);
    pthread_cond_init(&queue->not_full, NULL);
}

int isFull(TaskQueue *queue) {
    return (queue->rear + 1) % MAX_TASKS == queue->front;
}

int isEmpty(TaskQueue *queue) {
    return queue->front == -1;
}

void enqueueTask(TaskQueue *queue, Task task) {
    pthread_mutex_lock(&queue->lock);
    while (isFull(queue)) {
        pthread_cond_wait(&queue->not_full, &queue->lock);
    }
    if (isEmpty(queue)) {
        queue->front = queue->rear = 0;
    } else {
        queue->rear = (queue->rear + 1) % MAX_TASKS;
    }
    queue->tasks[queue->rear] = task;
    pthread_cond_signal(&queue->not_empty);
    pthread_mutex_unlock(&queue->lock);
}

Task dequeueTask(TaskQueue *queue) {
    pthread_mutex_lock(&queue->lock);
    while (isEmpty(queue)) {
        pthread_cond_wait(&queue->not_empty, &queue->lock);
    }
    Task task = queue->tasks[queue->front];
    if (queue->front == queue->rear) {
        queue->front = queue->rear = -1;
    } else {
        queue->front = (queue->front + 1) % MAX_TASKS;
    }
    pthread_cond_signal(&queue->not_full);
    pthread_mutex_unlock(&queue->lock);
    return task;
}

void processTaskQueue(TaskQueue *queue) {
    while (1) {
        Task task = dequeueTask(queue);
        if (task.callback()) {
            printf("Error processing task %d\n", task.taskID);
        }
    }
}

int main() {
    TaskQueue queue;
    initTaskQueue(&queue);

    // Example usage
    enqueueTask(&queue, (Task){1, 5, someCallbackFunction});
    enqueueTask(&queue, (Task){2, 3, anotherCallbackFunction});

    pthread_t thread;
    pthread_create(&thread, NULL, (void*)processTaskQueue, &queue);
    pthread_join(thread, NULL);

    return 0;
}
