} NFAPDUListPool;

NFAPDUListPool* generateNFADynamicPDUList(size_t initialCapacity) {
    NFAPDUListPool *pool = (NFAPDUListPool*)malloc(sizeof(NFAPDUListPool));
    if (!pool) return NULL;

    pool->pduList = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initialCapacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->pduList) {
        free(pool);
        return NULL;
    }

    pool->capacity = initialCapacity;
    pool->size = 0;
    pthread_mutex_init(&pool->mutex, NULL);

    for (size_t i = 0; i < initialCapacity; ++i) {
        pool->pduList[i].RX_UE_INFORMATION_TAG = rand();
        pool->pduList[i].RNTI = rand();
        pool->pduList[i].CRC_INDICATION_REL8_TAG = rand();
        pool->pduList[i].CRCFLAG = rand() % 2;
    }

    return pool;
}

void freeNFAPDUListPool(NFAPDUListPool *pool) {
    if (pool) {
        pthread_mutex_destroy(&pool->mutex);
        free(pool->pduList);
        free(pool);
    }
}
