```javascript
function executeDynamicJSFilesSequentially(filePaths, callback) {
    let index = 0;

    function loadAndExecuteNextFile() {
        if (index >= filePaths.length) {
            callback(null, "All files executed successfully");
            return;
        }

        const script = document.createElement('script');
        script.src = filePaths[index];
        script.onload = () => {
            index++;
            loadAndExecuteNextFile();
        };
        script.onerror = (error) => {
            console.error(`Failed to execute file: ${filePaths[index]}`, error);
            index++;
            loadAndExecuteNextFile();
        };

        document.head.appendChild(script);
    }

    loadAndExecuteNextFile();
}
