void filter_nfaapi_list(float evm_threshold) {
    pthread_mutex_lock(&nfapi_mutex);
    for (int i = 0; i < nfapi_count; ) {
        if (nfapi_list[i]->EVM < evm_threshold) {
            free(nfapi_list[i]);
            for (int j = i; j < nfapi_count - 1; j++) {
                nfapi_list[j] = nfapi_list[j + 1];
            }
